def _normalize_world_model(entry: dict) -> dict:
    """Fill in sane defaults for a (possibly partial) model registry entry."""
    mid = str(entry.get("id") or "").strip()
    if not mid:
        return None
    protocol = entry.get("protocol")
    requires_seed = entry.get("requires_seed_image")
    # Infer the missing half of (protocol, requires_seed_image) from the other.
    if protocol is None:
        protocol = "seed_locked" if requires_seed else "blend"
    if requires_seed is None:
        requires_seed = (protocol == "seed_locked")
    return {
        "id": mid,
        "label": entry.get("label") or mid,
        "sdk_name": entry.get("sdk_name") or _default_sdk_name(mid),
        "requires_seed_image": bool(requires_seed),
        "protocol": protocol,
    }


def _load_world_models() -> list:
    """Build the world-model registry: env override (REACTOR_MODELS) if valid,
    otherwise the built-in list. New models can thus be added with pure config."""
    raw = os.getenv("REACTOR_MODELS")
    if raw:
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, list):
                models = [_normalize_world_model(e) for e in parsed if isinstance(e, dict)]
                models = [m for m in models if m]
                if models:
                    return models
            print("[reactor] REACTOR_MODELS is not a non-empty JSON array; using built-ins")
        except Exception as e:
            print("[reactor] failed to parse REACTOR_MODELS ({}); using built-ins".format(e))
    return [_normalize_world_model(m) for m in _BUILTIN_WORLD_MODELS]


AVAILABLE_WORLD_MODELS = _load_world_models()

# Let the web client connect to a model name a tester types in even if it isn't
# advertised above — so a newly released Reactor model is usable instantly.
REACTOR_ALLOW_CUSTOM_MODELS = os.getenv("REACTOR_ALLOW_CUSTOM_MODELS", "1").strip().lower() not in (
    "0", "false", "no", "off",
)


def world_model_sdk_name(model_id: str) -> str:
    """SDK model string for a world-model id.

    Falls back to the ``reactor/<id>`` convention for unknown ids so a custom /
    brand-new model still resolves to a usable SDK name."""
    for m in AVAILABLE_WORLD_MODELS:
        if m["id"] == model_id:
            return m["sdk_name"]
    return _default_sdk_name(model_id) if model_id and "/" not in model_id else model_id

# Guard so the (slow, LLM-backed) realtime "vision" re-grounding never stacks up.
_observe_reground_active = False

# ── Experience Mode System ────────────────────────────────────────────────────
# These constants name the three selectable visual modes shown at game start.
# Storing them in engine ensures a single source of truth for bot, tests, and
# any future API endpoint that exposes mode selection.

EXPERIENCE_MODE_NO_IMAGES  = "no_images"   # Text-only; all image generation off
EXPERIENCE_MODE_FLIPBOOK   = "flipbook"    # In-between frames per turn (see flipbook.py)
EXPERIENCE_MODE_FULL_FRAME = "full_frame"  # Single photorealistic still image (default)

# ── Flipbook knobs ────────────────────────────────────────────────────────────
# Set from tunables.py (a browser-reachable store), so turning flipbook on and
# changing the frame count are live settings rather than a redeploy. A session
# can also override them for itself — a Watch render turns flipbook on for its
# own session without changing what live Play is doing (see flipbook_active).
FLIPBOOK_ENABLED  = False
FLIPBOOK_FRAMES   = flipbook.DEFAULT_FRAMES
FLIPBOOK_FRAME_MS = flipbook.DEFAULT_FRAME_MS

# ── Opening montage ───────────────────────────────────────────────────────────
# Whether a level opens on an establishing montage (cutscene.py, "approach"
# mood) rather than cutting straight to the World's cached first frame. Its own
# knob, and on by default, unlike FLIPBOOK_ENABLED: the case for one generation
# at the top of a level is much stronger than for one on every turn, because
# this is the beat that has to make somebody want to play.
INTRO_CUTSCENE = True

# ── Scene ambience ────────────────────────────────────────────────────────────
# Whether each scene gets the ambience bed the shipped sound library matches to
# what the frame shows (33 places: fence line at night, fluorescent corridor,
# server room, neon rain…) rather than one of the seven generic beds matched by
# keyword. This is the atmosphere layer — see scene_audio._pick_ambience. Since
# 2026-09-25 every sound comes from the library; none is generated.
SCENE_AMBIENCE_ENABLED = True

# Whether committing an action plays a Foley clip of that action from the
# library — "Sprint toward the utility truck" is running footsteps on gravel.
# Chosen by the choice TEXT; the client asks when the slate appears and plays
# on the click. See the "Action foley" section in scene_audio.py.
ACTION_FOLEY_ENABLED = True

# Whether a turn plays one sound of what the choice actually did (6-12 s from
# the library, by the turn's visual caption: a door breached, a collapse,
# gunfire, dread). Asked for when the consequence lands, five pipeline steps
# before the picture, so it covers the wait and the flipbook. It plays ONCE —
# it looped at first and the repetition was the whole problem. See the
# "Consequence bed" section in scene_audio.py.
CONSEQUENCE_BED_ENABLED = True


def flipbook_settings(st: Optional[dict] = None) -> dict:
    """Whether this turn draws a flipbook, and at what shape.

    Session state wins over the global knob so a render (or one player) can run
    flipbook without flipping it on for everything sharing the process. A
    session that has never been told either way inherits the global.
    """
    st = st or {}
    enabled = st.get("flipbook_mode")
    if enabled is None:
        enabled = FLIPBOOK_ENABLED
    frames = flipbook.normalize_frames(
        st.get("flipbook_frames") or FLIPBOOK_FRAMES)
    frame_ms = int(st.get("flipbook_frame_ms") or FLIPBOOK_FRAME_MS)
    return {"enabled": bool(enabled), "frames": frames, "frame_ms": frame_ms}


def flipbook_active(st: Optional[dict] = None, identity_spec=None) -> bool:
    """Same question, as a bool, with the one hard exclusion applied.

    CAMERA/viewfinder frames are a composed plate with its own contract — a
    grid of in-betweens there would paint over the viewfinder.
    """
    if not flipbook_settings(st)["enabled"]:
        return False
    if identity_spec is not None and game_identity.is_viewfinder_spec(identity_spec):
        return False
    return True

EXPERIENCE_MODES: dict = {
    EXPERIENCE_MODE_NO_IMAGES: {
        "label":         "📝 Text Only",
        "emoji":         "📝",
        "description":   (
            "Pure narrative — no image generation. "
            "Fastest; every word of the horror stands alone."
        ),
        "image_enabled":  False,
        "flipbook_mode":  False,
    },
    EXPERIENCE_MODE_FLIPBOOK: {
        "label":         "🎬 Flipbook",
        "emoji":         "🎬",
        "description":   (
            "In-between frames per turn — one generation split into a short "
            "sequence, played as full-quality frames. Count is a setting."
        ),
        "image_enabled":  True,
        "flipbook_mode":  True,
    },
    EXPERIENCE_MODE_FULL_FRAME: {
        "label":         "🖼️ Full Frame",
        "emoji":         "🖼️",
        "description":   (
            "Single photorealistic still image per turn — "
            "classic analog-horror atmosphere, no flipbook guide."
        ),
        "image_enabled":  True,
        "flipbook_mode":  False,
    },
}


def apply_experience_mode(mode: str, session_id: str = "default",
                          frames=None, frame_ms=None) -> bool:
    """Apply a named experience mode, updating engine globals and session state.

    Sets ``IMAGE_ENABLED`` / ``WORLD_IMAGE_ENABLED`` and writes
    ``flipbook_mode`` + ``experience_mode`` into the session state so that
    every subsequent turn respects the player's choice without needing to
    pass the flag around.

    ``frames``/``frame_ms`` pin the flipbook shape for THIS session only, which
    is how a Watch render runs 8 frames without changing what live Play is
    doing. Left out, the session follows the global tunables.

    Returns ``True`` on success, ``False`` if *mode* is not recognised.
    """
    global IMAGE_ENABLED, WORLD_IMAGE_ENABLED

    if mode not in EXPERIENCE_MODES:
        logging.warning(f"[EXPERIENCE] Unknown mode requested: {mode!r}")
        return False

    cfg = EXPERIENCE_MODES[mode]

    IMAGE_ENABLED       = cfg["image_enabled"]
    WORLD_IMAGE_ENABLED = cfg["image_enabled"]

    st = _load_state(session_id)
    st["flipbook_mode"]   = cfg["flipbook_mode"]
    st["experience_mode"] = mode
    if frames is not None:
        st["flipbook_frames"] = flipbook.normalize_frames(frames)
    if frame_ms is not None:
        st["flipbook_frame_ms"] = int(frame_ms)
    _save_state(st, session_id)

    logging.info(
        f"[EXPERIENCE] Mode '{mode}' applied — "
        f"image_enabled={IMAGE_ENABLED}, flipbook={cfg['flipbook_mode']}, "
        f"frames={st.get('flipbook_frames') or FLIPBOOK_FRAMES}"
    )
    return True


# ── Experience graph (worlds + transitions) ───────────────────────────────
# Distinct from EXPERIENCE_MODES above (flipbook / stills). This is the
# designer-authored graph: multiple Worlds stitched by conditions the turn
# loop can actually evaluate. See experience_store.py.


def _cutscene_feed_item(info: dict) -> dict:
    import cutscene as _cutscene

    dest = (info or {}).get("to") or {}
    pending = (info or {}).get("cutscene") or {}
    name = dest.get("name") or pending.get("name") or "Cutscene"
    return create_feed_item(
        type="cutscene",
        content=name,
        metadata={
            "cutscene_id": dest.get("id") or pending.get("cutscene_id"),
            "name": name,
            "mood": dest.get("mood") or pending.get("mood") or "threshold",
            "status": pending.get("status") or "pending",
            "from_world": ((info or {}).get("from") or {}).get("id"),
            "shots": pending.get("shots") or [],
            "duration_ms": pending.get("duration_ms") or int(_cutscene.HOLD_MS),
            # The opening montage carries its own title card copy, rather than
            # leaving the client to guess at one from whatever is painted.
            "opening": bool(pending.get("opening")),
            "goal": pending.get("goal") or "",
        },
    )


def apply_experience_cutscene(
    state: dict, cutscene_id: str, session_id: str = "default"
) -> Optional[dict]:
    """Land on a Cutscene node. Does not load a World snapshot.

    Generation happens when the client POSTs /api/cutscene/play — the hop
    only stamps pending_cutscene so the feed can start the Moment.
    """
    try:
        import experience_store
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] apply cutscene skipped: {e}")
        return None
    exp = experience_store.get_experience()
    dest = experience_store.cutscene_by_id(exp, cutscene_id)
    if not dest:
        return None
    src = experience_store.world_by_id(exp, state.get("experience_world_id") or "")
    pending = {
        "cutscene_id": dest["id"],
        "name": dest.get("name") or "Cutscene",
        "mood": dest.get("mood") or "threshold",
        "source": dest.get("source") or "incoming",
        "shot_brief": dest.get("shot_brief") or "",
        "status": "pending",
        "graph": True,
    }
    # A cutscene that leads to ANOTHER World is that World's arrival, and the
    # montage reads everything it draws from the live prompt file — the bible
    # for its shotlist, the Level sheet for the place, landmarks and palette,
    # the goal for its title card. Until now the destination was only bound
    # when the montage finished (complete_cutscene → apply_experience_world),
    # so a world-to-world cutscene was composed for the world the player was
    # LEAVING and stitched onto the frame they were leaving from. Reported as
    # "not all data gets cleared for the cutscene, which then pollutes the
    # rest". Bind the destination here, before a shot is drawn; the state
    # swap (goal, clock, detection, history boundary) still happens on
    # completion, when the player actually arrives.
    #
    # The one mood that is ABOUT the place being left — "departure", a last
    # look and a walk away — keeps the world it is leaving and lands on the
    # destination's own plate afterwards, so the old place never becomes the
    # new one's anchor either way.
    to_world = _cutscene_outgoing_world(exp, dest["id"])
    if to_world and to_world.get("id") != (src or {}).get("id"):
        pending["to_world"] = to_world["id"]
        if _cutscene_arrives(dest):
            pending["arrival"] = True
            if _bind_world_prompts(to_world):
                # Shoot the destination's look book during the montage; the
                # arrival's first frame waits for it (api_cutscene_complete).
                _look_book_for_arrival(session_id)
                print(f"[EXPERIENCE GRAPH] cutscene {dest.get('name')!r} arrives in "
                      f"{to_world.get('name')!r} — its World is bound before the "
                      f"montage draws", flush=True)
                # The montage reads the run's "Lighting:" line from the state.
                # Rolled here, off the destination's own palette, so the montage
                # and the first playable frame agree on the hour; the stitch
                # keeps this roll rather than making a second one (see
                # complete_cutscene).
                try:
                    state["time_of_day"] = _generate_random_starting_time()
                    pending["arrival_lighting"] = state["time_of_day"]
                except Exception as e:
                    logging.warning(f"[EXPERIENCE GRAPH] arrival lighting roll failed: {e}")
        else:
            print(f"[EXPERIENCE GRAPH] cutscene {dest.get('name')!r} is a departure "
                  f"from {(src or {}).get('name')!r}; {to_world.get('name')!r} is "
                  f"bound when it ends", flush=True)
    state["experience_id"] = exp.get("id") or "default"
    state["experience_cutscene_id"] = dest["id"]
    state["pending_cutscene"] = pending
    return {
        "from": src or {},
        "to": dest,
        "kind": "cutscene",
        "cutscene": pending,
        "transition": None,
    }


def complete_cutscene(state: dict, session_id: str = "default") -> Optional[dict]:
    """Leave the current Cutscene and follow its outgoing edge, if any."""
    try:
        import experience_store
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] complete cutscene skipped: {e}")
        return None
    cid = str(state.get("experience_cutscene_id") or "").strip()
    pending = state.get("pending_cutscene") or {}
    to_world = str(pending.get("to_world") or "").strip()
    # The arrival montage's last panel is the freshest picture of the
    # destination there is — composed for that World, moments ago. It is what
    # the first turn there continues from (see apply_experience_world).
    arrival_shot = ""
    montage_refs: List[str] = []
    if pending.get("arrival"):
        try:
            for shot in reversed(list(pending.get("shots") or [])):
                path = str((shot or {}).get("path") or "")
                if path and os.path.exists(path):
                    arrival_shot = path
                    break
            if arrival_shot:
                montage_refs = _montage_place_refs(pending, plate_path=arrival_shot)
        except Exception:
            arrival_shot, montage_refs = "", []
    # The arrival rolled the destination's lighting before the montage drew
    # (see apply_experience_cutscene). Rolling again here would put the first
    # playable frame under a different sky from the montage it continues.
    rolled = str(pending.get("arrival_lighting") or "")
    relight = not (rolled and rolled == str(state.get("time_of_day") or ""))
    state["experience_cutscene_id"] = ""
    state["pending_cutscene"] = None
    exp = experience_store.get_experience()
    hit = None
    if cid and not cid.startswith("play-"):
        hit = experience_store.matched_transition(
            exp, cid, world_turn_count=0, player_alive=True,
        )
    dest_id = (hit or {}).get("to") or to_world
    if not dest_id:
        return {"kind": "resume"}
    if experience_store.cutscene_by_id(exp, dest_id):
        info = apply_experience_cutscene(state, dest_id, session_id)
        if info:
            info["transition"] = hit
            info["kind"] = "cutscene"
            return info
        return {"kind": "resume"}
    info = apply_experience_world(state, dest_id, session_id,
                                  arrival_shot=arrival_shot, montage_refs=montage_refs,
                                  relight=relight)
    if info:
        info["transition"] = hit
        info["kind"] = "world"
        return info
    return {"kind": "resume"}


def _cutscene_outgoing_world(exp: dict, cutscene_id: str) -> Optional[dict]:
    """The World this cutscene's outgoing edge leads to, if any."""
    try:
        import experience_store
        for t in experience_store.transitions_from(exp, cutscene_id):
            dest = experience_store.world_by_id(exp, t.get("to") or "")
            if dest:
                return dest
    except Exception:
        pass
    return None


def _cutscene_arrives(node: dict) -> bool:
    """Does this cutscene show the place the player is ARRIVING in?

    Every mood but one restages "this exact place" or crosses into the next
    one, and when the edge out of it leads to another World that place is the
    destination. "departure" is a last look at the place being left.
    """
    return str((node or {}).get("mood") or "").strip().lower() != "departure"


def _look_book_for_arrival(session_id: str) -> None:
    """The World just bound gets its look book (see look_book.ensure_for_level)."""
    try:
        import look_book
        look_book.ensure_for_level(session_id or "default", reason="arrival")
    except Exception as e:
        logging.warning(f"[LOOK BOOK] arrival book not started: {e}")


def _bind_world_prompts(dest: dict) -> bool:
    """Load a World snapshot into the live prompt file, keeping the run's cast.

    Who the player IS belongs to the run, not to a World. `sync_cast_to_worlds`
    copies one cast across every World of an Experience when the sheet is
    saved, so in practice the snapshots agree — but a World saved before that
    sync, or authored with a different protagonist, used to swap the player
    mid-run: the old guard restored the prior cast only when the destination's
    sheet was DISABLED, and two enabled-but-different sheets slid straight
    through it (a run begun as Isaac Clarke would arrive as Jason Fleece). The
    run's protagonist now wins whenever the run has one.
    """
    import worlds_store
    slug = str((dest or {}).get("slug") or "")
    if not slug:
        return False
    prior_cast = None
    try:
        # raw_spec, not get_spec: a run that is a Character reads it laid over
        # the sheet, and writing THAT back would put the character in the file.
        _raw = game_identity.raw_spec()
        if game_identity.character_enabled(_raw):
            prior_cast = dict(_raw[game_identity.CHARACTER_KEY])
    except Exception:
        prior_cast = None
    try:
        worlds_store.load_world(slug)
    except KeyError:
        logging.warning(f"[EXPERIENCE GRAPH] world '{slug}' missing")
        return False
    if prior_cast:
        try:
            import prompts_store
            now = None
            try:
                now = dict(game_identity.raw_spec()[game_identity.CHARACTER_KEY])
            except Exception:
                now = None
            if now != prior_cast:
                prompts_store.save_prompts_bulk({game_identity.CHARACTER_KEY: prior_cast})
                logging.info(
                    "[EXPERIENCE GRAPH] kept protagonist "
                    f"{prior_cast.get('name')!r} across the world stitch"
                )
        except Exception as e:
            logging.warning(f"[EXPERIENCE GRAPH] cast carry-over failed: {e}")
    return True


# Everything that describes THE PLACE the run is in, or what has happened in
# it. A world stitch used to mutate the live state in place and clear six of
# these; the rest survived by omission, and every one of them is read by a
# prompt: the previous world's goal ("WHAT THE PLAYER CAME HERE FOR"), its
# heat and witness, its narrator memory, its encounter roster (built from its
# lore), its flipbook keyframe (the START of the next grid — reference slot 1),
# its stagnation streak, its lighting line. New Game clears all of it because
# it rebuilds the state from a literal; the stitch has to earn it key by key.
_WORLD_SCOPED_KEYS = (
    "level_goal", "goal_reached_turn", "_turn_goal_reached",
    "goal_name", "goal_why", "goal_look",
    # The goal's spine and the thing inside it belong to the World it was
    # drafted for: a stitch into another one must not carry the last place's
    # secret, its claimant, or a prize that is not in the room any more.
    "goal_truth", "goal_claim", "goal_cost", "goal_phase",
    "goal_prize", "goal_prize_look", "goal_prize_verb",
    "goal_boss_name", "goal_boss_kind", "goal_boss_look", "goal_boss_want", "goal_boss_defeated",
    "detection_witness",
    "environment_streak", "environment_streak_vocab",
    "recent_events", "narrator_recent", "narrator_beat",
    "encounter", "encounter_outcome", "encounter_resolving",
    "encounter_roster", "encounter_kinds_used",
    "encounter_last_turn", "encounter_last_at", "encounter_last_label",
    "encounter_sighting", "encounter_travel_remain",
    "flipbook_last_frame", "flipbook_first_frame", "flipbook_last_grid",
    "current_sequence",
    "choices", "choices_metadata", "pending_opening_choices",
    "scene_objects", "scene_objects_turn",
    "fate", "in_combat", "current_render_base",
)


def _clear_world_scoped_state(state: dict) -> None:
    """Leave the previous World behind. What stays: who the player is, what
    they carry, who is with them, whether they are hurt, the feed, and the
    run's turn count. See _WORLD_SCOPED_KEYS for what goes."""
    for key in _WORLD_SCOPED_KEYS:
        state.pop(key, None)
    state["seen_elements"] = []
    state["scene_objects"] = []
    state["scene_objects_turn"] = -1
    state["choices"] = []
    turn = int(state.get("turn_count") or 0)
    # Nobody in the new place knows the player is there yet.
    state["detection"] = {"heat": 0, "level": DETECT_HIDDEN, "since_turn": turn}
    # The story clock is per place: a level that opens at "critical" writes
    # every beat as a last stand from its first turn.
    state["threat_level"] = 0
    state["current_phase"] = "normal"
    state["chaos_level"] = 0
    state["in_combat"] = False


def _stitch_history(session_id: str, state: dict, dest: dict, anchor: str,
                    montage_refs: Optional[List[str]] = None) -> None:
    """Mark the World boundary in history.json.

    The next turn's img2img references are the last history images, walked
    back until a hard transition — and nothing ever wrote one for a stitch,
    so the new World's first frame was drawn off the old World's last frame,
    and every frame after that chained off it. The row below is the boundary:
    its image is the picture of the DESTINATION the run continues from (the
    arrival montage's last panel, else the World's plate), it is a hard
    transition so collection stops here, and it carries the destination's
    setting so cutscene.environment_type reads this place, not the last one.

    It is also written the way the level's opening writes its handoff row
    (``cached_opening``, see _apply_cached_opening_frame): the turn after a
    stitch is forced to a hard cut, and a hard cut blurs its reference to a
    colour swatch — so the first frame in the new World shared only a palette
    with the picture the player had just been shown. The handoff mark keeps
    the anchor's pixels for that one turn, with the rest of the arrival
    montage riding along as ``montage_refs``, exactly as turn one continues
    the opening.
    """
    place = ""
    try:
        place = game_identity.place_summary() or ""
    except Exception:
        place = ""
    try:
        hist = _load_history(session_id) or []
        hist.append({
            "choice": "__world_stitch__",
            "dispatch": f"You are in {dest.get('name') or 'a new place'} now. {place}".strip(),
            "vision_dispatch": place or f"{dest.get('name') or 'A new place'}.",
            "vision_analysis": "",
            "world_prompt": state.get("world_prompt") or "",
            "setting_type": classify_setting(place) or "",
            "image": anchor or "",
            "image_url": anchor or "",
            "analysis_image": anchor or "",
            "guide_image": anchor or "",
            "image_prompt": place,
            "hard_transition": True,
            "cached_opening": bool(anchor),
            "montage_refs": [str(p) for p in (montage_refs or []) if p],
            "world_stitch": True,
            "world": dest.get("slug") or dest.get("id") or "",
        })
        _save_history(hist, session_id)
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] history stitch row failed: {e}")


def _world_transition_feed_item(info: dict) -> dict:
    dest = (info or {}).get("to") or {}
    src = (info or {}).get("from") or {}
    name = dest.get("name") or "another world"
    left = src.get("name") or "this world"
    return create_feed_item(
        type="world_transition",
        content=f"You leave {left} and enter {name}.",
        metadata={
            "from_world": src.get("id"),
            "to_world": dest.get("id"),
            "transition_id": ((info or {}).get("transition") or {}).get("id"),
        },
    )


def apply_experience_start(state: dict, session_id: str = "default",
                           world_id: str = "") -> dict:
    """Bind a fresh run to the active Experience's start World.

    ``world_id`` starts the run in that World instead — the editor's GENERATE
    restarts the run in the World it just drew, which is not always the start.
    It skips the Experience's opening cutscene unless the cutscene lands there
    anyway.

    A start World with a slug is a bound identity — Play / Watch / reset
    load that snapshot so the run cannot silently drift off the designed
    beginning (SOMEWHERE is locked this way). Empty slug means "use the
    live prompt file" (the Create scratch pad).
    """
    try:
        import experience_store
        import worlds_store
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] start bind skipped: {e}")
        return state
    exp = experience_store.get_experience()
    start_id = experience_store.start_node_id(exp)
    cut = experience_store.opening_cutscene(exp)
    land_from = (cut or {}).get("id") or start_id
    start = experience_store.landing_world(exp, land_from)
    if start is None and exp.get("worlds"):
        start = exp["worlds"][0]
    chosen = experience_store.world_by_id(exp, world_id) if world_id else None
    if chosen is not None and chosen.get("id") != (start or {}).get("id"):
        start = chosen
        cut = None
    if start and start.get("slug"):
        try:
            worlds_store.load_world(start["slug"])
        except KeyError:
            logging.warning(
                f"[EXPERIENCE GRAPH] start world '{start.get('slug')}' missing"
            )
    state["experience_id"] = exp.get("id") or "default"
    state["experience_world_id"] = (start or {}).get("id") or ""
    state["world_turn_count"] = 0
    state["pending_world_transition"] = False
    if cut:
        pending = {
            "cutscene_id": cut["id"],
            "name": cut.get("name") or "Cutscene",
            "mood": cut.get("mood") or "threshold",
            "source": cut.get("source") or "incoming",
            "shot_brief": cut.get("shot_brief") or "",
            "status": "pending",
            "graph": True,
        }
        state["experience_cutscene_id"] = cut["id"]
        state["pending_cutscene"] = pending
        dest_slug = str((start or {}).get("slug") or "")
        if dest_slug:
            try:
                import world_frames
                rec = world_frames.record(dest_slug)
                if rec.get("url"):
                    state["current_image_url"] = rec["url"]
            except Exception:
                pass
    else:
        state["experience_cutscene_id"] = ""
        state["pending_cutscene"] = None
    return state


def apply_experience_world(state: dict, world_id: str, session_id: str = "default",
                           *, arrival_shot: str = "",
                           montage_refs: Optional[List[str]] = None,
                           relight: bool = True) -> Optional[dict]:
    """Land in a World: bind its prompts, leave the previous place behind.

    ``arrival_shot`` is the last panel of the cutscene that brought the player
    here, when there was one — the freshest picture of this World, composed
    for it moments ago. It becomes the frame the run continues from, and
    ``montage_refs`` (the montage's other panels) ride into that first frame's
    references beside it. ``relight`` is off when that cutscene already rolled
    this World's lighting line and drew under it.
    """
    try:
        import experience_store
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] apply world skipped: {e}")
        return None
    exp = experience_store.get_experience()
    dest = experience_store.world_by_id(exp, world_id)
    if not dest:
        return None
    src = experience_store.world_by_id(exp, state.get("experience_world_id") or "")
    if dest.get("slug"):
        # Idempotent when the arrival cutscene already bound it (see
        # apply_experience_cutscene); a direct edge binds here.
        if not _bind_world_prompts(dest):
            return None
        _look_book_for_arrival(session_id)
    state["experience_id"] = exp.get("id") or "default"
    state["experience_world_id"] = dest["id"]
    state["world_turn_count"] = 0
    state["pending_world_transition"] = True
    # The previous place, its memory, its clock and its confrontation — gone.
    # A stitch used to clear a confrontation, the discovered-entity list and
    # the scene objects ("Heave open the truck door" offered in a facility that
    # has no truck) and leave everything else; see _WORLD_SCOPED_KEYS.
    _clear_world_scoped_state(state)
    # Caches keyed by session, not by world: the new world would otherwise open
    # on the previous one's palette gloss, its cast portraits and its campfire.
    purge_run_caches(session_id, reason=f"world stitch -> {dest.get('slug') or dest['id']}")
    state["world_prompt"] = experience_store.with_lore(
        game_identity.world_brief(
            PROMPTS.get("world_initial_state", "Default world starting point.")
        )
    )
    # The lighting line rides into every render of the session as "Lighting:"
    # and is rolled off the level's palette — so it is rolled again here, off
    # THIS level's, the way New Game rolls it after its bind.
    if relight:
        try:
            state["time_of_day"] = _generate_random_starting_time()
        except Exception as e:
            logging.warning(f"[EXPERIENCE GRAPH] lighting re-roll failed: {e}")
    # And the run's goal is this World's goal, not the last one's.
    try:
        _goal_for_this_run(state, "", session_id)
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] goal for the new world failed: {e}")
    # Land on a picture of the destination so a world stitch isn't a black cut
    # while the next turn renders: the arrival montage's last panel, else the
    # World's plate when it was drawn from the prompts the run is playing on,
    # else that plate anyway (a stale plate beats a black one). The same
    # picture is the history boundary the next turn continues from.
    dest_slug = str(dest.get("slug") or "")
    anchor = arrival_shot if (arrival_shot and os.path.exists(str(arrival_shot))) else ""
    anchor_url = _to_web_image_url(anchor, session_id) if anchor else ""
    if dest_slug:
        try:
            import world_frames
            rec = world_frames.record(dest_slug)
            if not anchor and rec.get("path") and os.path.exists(str(rec.get("path"))):
                anchor = str(rec["path"])
                anchor_url = rec.get("url") or ""
                if not world_frames.drawn_from_live(rec):
                    print(f"[EXPERIENCE GRAPH] {dest_slug!r}'s plate predates the "
                          f"prompts it is played on — landing on it anyway", flush=True)
            elif not anchor and rec.get("url"):
                anchor_url = rec["url"]
        except Exception:
            pass
    if anchor_url:
        state["current_image_url"] = anchor_url
    _stitch_history(session_id, state, dest, anchor, montage_refs if anchor else None)
    try:
        import run_tape
        run_tape.chapter(session_id, str(dest.get("name") or "A new place"), state)
        if anchor or anchor_url:
            run_tape.record(session_id, "opening", [anchor or anchor_url],
                            prose=f"You are in {dest.get('name') or 'a new place'} now.",
                            turn=state.get("turn_count"), state=state)
    except Exception as _tape_err:
        log_error(f"[TAPE] chapter not marked: {_tape_err}")
    print(f"[EXPERIENCE GRAPH] stitched into {dest.get('name')!r}: goal "
          f"{str(state.get('level_goal') or '')[:60]!r}, lighting "
          f"{str(state.get('time_of_day') or '')[:40]!r}, anchor "
          f"{os.path.basename(anchor) if anchor else '(none)'}", flush=True)
    return {"from": src or {}, "to": dest, "transition": None}


def maybe_apply_world_transition(
    state: dict,
    session_id: str = "default",
    *,
    player_alive: bool = True,
) -> Optional[dict]:
    """If the current World's outgoing condition is met, stitch to the target.

    The turn that fired the condition has already been written in the source
    World. The next turn (and ``world_prompt``) use the destination.
    """
    try:
        import experience_store
    except Exception as e:
        logging.warning(f"[EXPERIENCE GRAPH] evaluate skipped: {e}")
        return None
    if str(state.get("experience_cutscene_id") or "").strip():
        return None
    exp = experience_store.get_experience()
    wid = state.get("experience_world_id") or exp.get("start_world")
    if not wid:
        return None
    hit = experience_store.matched_transition(
        exp,
        wid,
        world_turn_count=int(state.get("world_turn_count") or 0),
        player_alive=player_alive,
    )
    if not hit:
        return None
    dest_id = hit["to"]
    if experience_store.cutscene_by_id(exp, dest_id):
        info = apply_experience_cutscene(state, dest_id, session_id)
    else:
        info = apply_experience_world(state, dest_id, session_id)
    if not info:
        return None
    info["transition"] = hit
    info.setdefault(
        "kind",
        "cutscene" if experience_store.cutscene_by_id(exp, dest_id) else "world",
    )
    logging.info(
        f"[EXPERIENCE GRAPH] {wid} → {hit['to']} "
        f"via {((hit.get('condition') or {}).get('type'))} "
        f"({info.get('kind')})"
    )
    return info


def _tick_world_and_maybe_transition(
    state: dict,
    session_id: str,
    *,
    player_alive: bool = True,
) -> Optional[dict]:
    """Count a turn against the current World, then evaluate outgoing edges."""
    state["world_turn_count"] = int(state.get("world_turn_count") or 0) + 1
    return maybe_apply_world_transition(
        state, session_id, player_alive=player_alive
    )

