# ───────── world‑state helpers ───────────────────────────────────────────────
def _load_state(session_id='default') -> dict:
    """Load state for a specific session"""
    state_path = _get_state_path(session_id)
    with WORLD_STATE_LOCK:
        if state_path.exists():
            try:
                # Explicitly open with utf-8, and ensure file is closed with try/finally or with statement
                with state_path.open('r', encoding='utf-8') as f:
                    st = json.load(f)
                # Ensure essential keys exist after loading
                st.setdefault('player_state', {'alive': True})
                # A save written before detection was simulated doesn't have it,
                # and every consumer would then read its own hardcoded default.
                # Backfill once, here, so there is one answer.
                st.setdefault('detection', {'heat': 0, 'level': DETECT_HIDDEN,
                                            'since_turn': 0})
                st.setdefault('feed_log', [])
                st.setdefault('current_image_url', None)
                st.setdefault('choices', []) # Ensure choices list is present
                # Left UNSET, not False: flipbook_settings only falls back to the
                # global knob for a session that has never been told either way,
                # so defaulting to False here made the tunable unreachable —
                # every session shadowed it before anything could read it.
                # apply_experience_mode writes a real bool when a mode is chosen.
                st.setdefault('flipbook_mode', None)
                st.setdefault('experience_id', 'default')
                st.setdefault('experience_world_id', '')
                st.setdefault('world_turn_count', 0)
                st.setdefault('pending_world_transition', False)
                st.setdefault('experience_cutscene_id', '')
                st.setdefault('pending_cutscene', None)
                return st
            except json.JSONDecodeError as e_json:
                logging.error(f"JSONDecodeError in _load_state for {state_path}: {e_json}. File might be corrupt or empty.")
                # Fallback to a default state but log this as a critical issue
            except Exception as e_load:
                logging.error(f"Unexpected error loading {state_path} in _load_state: {e_load}")
                # Fallback for other errors too
        
        # Fallback: If file doesn't exist or loading failed, return a clean default state.
        # First-time runs and brand-new sessions are expected to hit this path,
        # so log at INFO level when the file simply doesn't exist (and only WARN
        # if there was an actual load error above — those errors are already
        # logged separately).
        if not state_path.exists():
            logging.info(f"{state_path} does not exist yet; returning default state.")
        else:
            logging.warning(f"{state_path} failed to load, returning default state.")
        return {
            "world_prompt": PROMPTS.get("world_initial_state", "Default world starting point."), # Use .get for safety
            "current_phase": "normal",
            "chaos_level": 0,
            "last_choice": "",
            "last_saved": datetime.now(timezone.utc).isoformat(),
            "seen_elements": [],
            "inventory": [],  # Player inventory
            "player_state": {"alive": True},
            "feed_log": [],
            "current_image_url": None,
            "choices": [],
            "turn_count": 0, # Initialize turn_count
            "interim_index": 0, # Initialize interim_index
            "time_of_day": INITIAL_TIME_OF_DAY,
            # None = follow the global tunable; a chosen experience mode writes
            # a real bool. False here shadowed the knob permanently.
            "flipbook_mode": None,
            "experience_id": "default",
            "experience_world_id": "",
            "world_turn_count": 0,
            "pending_world_transition": False,
            "experience_cutscene_id": "",
            "pending_cutscene": None,
        }

# Module-global state backing the standalone feed UI. It mirrors the
# 'default' session on disk (sessions/default/state.json), the same session
# the feed endpoints and _perform_game_reset read and write, so in-memory
# state and disk state no longer diverge across restarts.
# Read the world bible once, up front, and say what it found. The lore is
# prepended to every narrative call, so it is one of the highest-leverage inputs
# in the game — and it was the only one that never announced itself. A Lore node
# holding the wrong text, or nothing at all, looked exactly like a working one.
# This also primes the cache, so the first turn does not pay for the read.
try:
    import experience_store as _xs_boot
    print(f"[ENGINE INIT] {_xs_boot.boot_report()}", flush=True)
except Exception as _lore_boot_err:
    print(f"[ENGINE INIT] Lore could not be read ({_lore_boot_err}); "
          f"running without it", flush=True)

print("[ENGINE INIT] Initializing global state from 'default' session...", flush=True)
try:
    state = _load_state('default')
    print(f"[ENGINE INIT] Default-session state loaded successfully", flush=True)
except Exception as e:
    print(f"[ENGINE INIT ERROR] Failed to load default-session state: {e}", flush=True)
    import traceback
    traceback.print_exc()
    # Create default state if loading fails
    state = {
        "world_prompt": "You crouch behind a rusted Horizon vehicle at the edge of the facility.",
        "current_phase": "normal",
        "chaos_level": 0,
        "last_choice": "",
        "last_saved": datetime.now(timezone.utc).isoformat(),
        "seen_elements": [],
        "inventory": [],  # Player inventory
        "player_state": {"alive": True},
        "detection": {"heat": 0, "level": DETECT_HIDDEN, "since_turn": 0},
        "feed_log": [],
        "current_image_url": None,
        "choices": [],
        "choices_metadata": {},
        "turn_count": 0,
        "interim_index": 0,
        "in_combat": False,
        "threat_level": 0,
        "time_of_day": INITIAL_TIME_OF_DAY,
        # None = follow the global tunable; a chosen experience mode writes a
        # real bool. False here shadowed the knob permanently.
        "flipbook_mode": None,
        "experience_id": "default",
        "experience_world_id": "",
        "world_turn_count": 0,
        "pending_world_transition": False,
        "experience_cutscene_id": "",
        "pending_cutscene": None,
    }
    print("[ENGINE INIT] Created default fallback state", flush=True)

# Global history mirrors the 'default' session (standalone feed path) so the
# feed no longer writes history to a separate root history.json.
history_path = _get_history_path('default')
if history_path.exists():
    try:
        with history_path.open("r", encoding="utf-8") as f:
            history = json.load(f)
    except Exception:
        history = []
else:
    history = []

# Advance the feed-item id counter past any ids already persisted in the
# resumed 'default' session so new items stay monotonically increasing and
# never collide with existing feed_log entries after a restart.
try:
    _existing_feed = state.get("feed_log", []) if isinstance(state, dict) else []
    _max_feed_id = max((int(i.get("id", 0)) for i in _existing_feed), default=0)
    if _max_feed_id > _next_feed_item_id:
        _next_feed_item_id = _max_feed_id
except Exception:
    pass

# Session-based history functions
def _load_history(session_id='default') -> list:
    """Load history for a specific session"""
    history_path = _get_history_path(session_id)
    if history_path.exists():
        try:
            with history_path.open("r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            logging.error(f"Failed to load history for session {session_id}: {e}")
            return []
    return []

def _save_history(hist: list, session_id='default'):
    """Save history for a specific session"""
    history_path = _get_history_path(session_id)
    try:
        with history_path.open("w", encoding="utf-8") as f:
            json.dump(hist, f, indent=2, ensure_ascii=False)
    except Exception as e:
        logging.error(f"Failed to save history for session {session_id}: {e}")

def _save_state(st: dict, session_id='default'):
    """Save state for a specific session"""
    state_path = _get_state_path(session_id)
    # CRITICAL FIX: Always acquire lock to prevent concurrent write race conditions
    with WORLD_STATE_LOCK:
        st["last_saved"] = datetime.now(timezone.utc).isoformat()
        temp_state_file = state_path.with_suffix(".json.tmp")
        max_retries = 3
        retry_delay = 0.1 # seconds

        for attempt in range(max_retries):
            try:
                temp_state_file.write_text(json.dumps(st, indent=2, ensure_ascii=False), encoding='utf-8')
                os.replace(temp_state_file, state_path)
                
                # Update session metadata (Minecraft-style world stats)
                try:
                    _update_session_metadata(
                        session_id,
                        turn_count=st.get('turn_count', 0),
                        player_alive=st.get('player_state', {}).get('alive', True)
                    )
                except Exception as meta_error:
                    print(f"[SESSION META] Warning: Failed to update metadata: {meta_error}")
                
                return # Success
            except OSError as e_os:
                logging.warning(f"Attempt {attempt + 1} to save state to {state_path} failed with OSError: {e_os}")
                if attempt < max_retries - 1:
                    time.sleep(retry_delay)
                else:
                    logging.error(f"All {max_retries} attempts to save state to {state_path} failed due to OSError: {e_os}")
            except Exception as e:
                logging.error(f"Failed to save state to {state_path} on attempt {attempt + 1}: {e}")
                if attempt == max_retries - 1 or not isinstance(e, OSError):
                    try:
                        logging.error(f"State content that failed to save: {json.dumps(st, indent=2, default=str, ensure_ascii=False)}")
                    except Exception as e_log_state:
                        logging.error(f"Could not even serialize state for error logging: {e_log_state}")
                if attempt == max_retries - 1:
                    break 
                time.sleep(retry_delay)

        logging.error(f"Persistently failed to save state to {state_path} after {max_retries} attempts.")
        if temp_state_file.exists():
            try:
                os.remove(temp_state_file)
            except Exception as e_remove:
                logging.error(f"Error removing temporary state file {temp_state_file} after failed save: {e_remove}")


# ═══════════════════════════════════════════════════════════════════
# MULTI-USER SESSION CONTEXT SWITCHING
#
# The engine keeps ONE active game state in memory (module globals `state`,
# `history`, `_next_feed_item_id`, `_last_image_path`, `history_path`) so
# the standalone feed handlers (api_reset / api_feed / api_choose) can stay
# simple. To let multiple people play concurrently against the same server
# process, each with their own persistent instance on disk, we treat that
# in-memory slot as a *context* and swap it before each session-scoped
# request handler runs.
#
# Concurrency model: turns serialize on WORLD_STATE_LOCK. Two different
# users on two different sessions can each read/write their own on-disk
# state and each interact with the game — but only one turn is actively
# being processed by the engine at a time. This is acceptable because the
# per-turn work is dominated by LLM + image API latency (multi-second),
# not CPU, and this framework lets us horizontally split later by process
# without changing the client contract.
#
# Public API:
#   engine.set_active_session(session_id) -> str
#     Persist current state under its previous session id, then load the
#     requested session's state into memory. Returns the resolved id.
#   engine.get_active_session_id() -> str
#     Returns the id of the session currently loaded in memory.
#   engine.session_context(session_id)   [context manager]
#     Acquires WORLD_STATE_LOCK, swaps active session, yields, then
#     persists on exit. Use this around anything that mutates state.
# ═══════════════════════════════════════════════════════════════════

# The session id currently loaded into the module-global `state`. The
# engine boots with the 'default' session (see _load_state('default') above)
# so start there and update as we swap.
_active_session_id: str = 'default'


def get_active_session_id() -> str:
    """Session id whose state is currently loaded in memory."""
    return _active_session_id


def _sanitize_session_id(session_id) -> str:
    """
    Normalize + validate an incoming session id. Falls back to 'default' if
    the id is missing, empty, or does not match the allowed character set.
    Never raises — a bad id from a URL simply routes to the default slot so
    the caller still gets a working game instead of a 400.
    """
    if not session_id:
        return 'default'
    try:
        sid = str(session_id).strip()
        if not sid:
            return 'default'
        # _validate_session_id accepts alnum + '_' + '-' up to 100 chars.
        _validate_session_id(sid)
        return sid
    except Exception:
        logging.warning(f"[SESSION CTX] Rejected invalid session id: {session_id!r}; using 'default'")
        return 'default'


def _resolve_request_session_id() -> str:
    """Resolve the session id for the CURRENT request straight from Flask's
    `request` object — NOT from `get_active_session_id()` / the shared
    `_active_session_id` global.

    Why this matters: `_active_session_id` (and the `state`/`history`
    mirrors) are module-level globals shared by every request thread. Flask
    runs concurrent requests on separate threads (see app.run(threaded=True)
    in api.py), so between the moment `_session_scoped` swaps the active
    session in for THIS request and the moment this request's handler body
    actually reads `get_active_session_id()`, a DIFFERENT thread handling a
    DIFFERENT session's request can run its own swap and change that shared
    global out from under us. That raced in practice: two sessions taking
    turns at the same instant could see one player's action land in BOTH
    sessions' saves.

    `flask.request` is a context-local proxy — safe to read from any thread
    handling its own request — so re-deriving the session id here (mirroring
    the exact precedence `_session_scoped` used in api.py: query string,
    then JSON body, then header) gives each request thread its own correct
    answer regardless of what any other concurrent request is doing.
    """
    try:
        sid = (
            request.args.get('session_id')
            or (request.get_json(silent=True) or {}).get('session_id')
            or request.headers.get('X-Session-Id')
        )
    except Exception:
        sid = None
    return _sanitize_session_id(sid)


def set_active_session(session_id: str) -> str:
    """
    Swap the module-global game state to the requested session.

    - Saves the currently active state to its own session file first so we
      never lose in-flight progress when a different user takes a turn.
    - Loads the target session's state (creating a fresh default state on
      disk if it does not yet exist).
    - Rebinds `state`, `history`, `history_path`, and advances
      `_next_feed_item_id` past any ids persisted in the loaded feed_log so
      newly generated items stay monotonically increasing.

    Safe to call with the same id (no-op). Always returns the resolved id.
    """
    global state, history, history_path, _next_feed_item_id, _active_session_id

    target = _sanitize_session_id(session_id)

    with WORLD_STATE_LOCK:
        if target == _active_session_id and isinstance(state, dict):
            # Already loaded; nothing to do. Touch metadata so recent-access
            # timestamps still bump for the lobby list.
            try:
                _update_session_metadata(target)
            except Exception:
                pass
            return target

        # Persist whatever is currently in memory back to its own slot before
        # we overwrite the globals. This preserves in-flight progress even if
        # a request handler forgot to _save_state() before returning.
        try:
            if isinstance(state, dict) and _active_session_id:
                _save_state(state, _active_session_id)
        except Exception as e_save_prev:
            logging.warning(f"[SESSION CTX] Failed to persist previous session '{_active_session_id}' during swap: {e_save_prev}")

        # Ensure the target session directory + metadata exist. _load_session_metadata
        # creates a fresh session on disk when create_if_missing=True (default).
        try:
            _load_session_metadata(target)
        except Exception as e_meta:
            logging.warning(f"[SESSION CTX] Metadata init failed for '{target}': {e_meta}")

        # Swap in the new session's persisted state.
        state = _load_state(target)
        history = _load_history(target)
        history_path = _get_history_path(target)

        # Feed-item ids must stay monotonically increasing per active session,
        # so bump the module-global counter past whatever the loaded feed_log
        # already contains. (This is the same guarantee the boot path makes.)
        try:
            feed = state.get('feed_log', []) if isinstance(state, dict) else []
            max_id = max((int(i.get('id', 0)) for i in feed if isinstance(i, dict)), default=0)
            if max_id > _next_feed_item_id:
                _next_feed_item_id = max_id
        except Exception:
            pass

        _active_session_id = target
        logging.info(f"[SESSION CTX] Active session -> '{target}' (feed_log len={len(state.get('feed_log', []))})")
        return target


from contextlib import contextmanager as _contextmanager

@_contextmanager
def session_context(session_id):
    """
    Context manager that switches the engine's active session for the
    duration of a request. Persists the state on exit so the on-disk copy
    always reflects any mutations made inside the block — but ONLY if
    `resolved` is still the active session when we exit.

    Why the guard: `state` is a module-global mirror shared by every
    request thread. If a DIFFERENT session's request ran (and swapped the
    mirror again) while this request's handler was doing slow work, `state`
    at exit time no longer belongs to `resolved` — blindly saving it here
    would stomp `resolved`'s on-disk file with another session's data. Every
    handler that actually needs to persist mutations now does so itself
    against an explicitly-resolved session id (see _resolve_request_session_id
    and api_choose / _perform_game_reset / api_regenerate_choices), so this
    is a safety net for anything else, not the only path to disk. When the
    mirror has moved on, the swap that moved it already persisted whatever
    was in `resolved`'s slot at that time (see set_active_session), so
    skipping here loses nothing.
    """
    resolved = set_active_session(session_id)
    try:
        yield resolved
    finally:
        try:
            with WORLD_STATE_LOCK:
                if isinstance(state, dict) and get_active_session_id() == resolved:
                    _save_state(state, resolved)
        except Exception as e:
            logging.warning(f"[SESSION CTX] Failed to persist session '{resolved}' after request: {e}")


def _sync_ambient_state(st: dict, session_id: str) -> None:
    """Best-effort refresh of the module-global `state` mirror used by the
    same-session /api/feed fast path (see set_active_session's no-op branch).

    Background threads (turn processing, scene-image generation, world
    evolution, vision reground) run well after the request that spawned them
    returns, and by the time they finish, a DIFFERENT session's request may
    have swapped the ambient mirror via session_context(). Blindly
    reassigning `state` here would leak session_id's data into whichever
    session is now active. Each caller already persists the authoritative
    copy to disk via _save_state(); this only controls the in-memory
    convenience mirror, so skip the write when session_id is no longer the
    active one — the next request for session_id will simply reload from
    disk (set_active_session always does on a real switch).

    The check-and-set runs under WORLD_STATE_LOCK so it is atomic with
    respect to set_active_session() (which also holds that lock while it
    swaps `_active_session_id` and `state` together). Without the lock the
    `get_active_session_id() == session_id` test and the `state = st` write
    straddle a window in which a concurrent set_active_session could change
    the active session out from under us, leaving `state` pointing at one
    session's data while `_active_session_id` names another — which the
    session_context exit-save would then persist to the WRONG file.
    """
    global state
    with WORLD_STATE_LOCK:
        if get_active_session_id() == session_id:
            state = st


def _sync_ambient_history(hist: list, session_id: str) -> None:
    """History counterpart of _sync_ambient_state: refresh the module-global
    `history` mirror only when session_id is still the active session, under
    WORLD_STATE_LOCK for atomicity with set_active_session. The on-disk copy
    (via _save_history) is always the source of truth; this only controls the
    in-memory convenience mirror so a finished background task can't leak its
    frames into whichever session is active by the time it completes."""
    global history
    with WORLD_STATE_LOCK:
        if get_active_session_id() == session_id:
            history = hist


def _publish_ambient(st=None, hist=None) -> None:
    """UNCONDITIONALLY set the module-global state/history mirrors.

    Used ONLY by the legacy single-session Discord bot turn path
    (advance_turn_image_fast / advance_turn_choices_deferred called with
    local_only=False), whose interaction handlers read engine.state /
    engine.history directly after a turn resolves. The bot process runs a
    single game flow and never calls set_active_session, so an unconditional
    write is correct there. The web multi-user path passes local_only=True and
    never calls this — it keeps everything in locals + on-disk per session, so
    no concurrent request can corrupt an in-flight turn via the shared mirror."""
    global state, history
    if st is not None:
        state = st
    if hist is not None:
        history = hist


# ───────── reading an authored world's prose ─────────────────────────────────
# A world bible is written by a person, and the normal way a person rules
# something out is to name it: "clear or lightly clouded sky — no storms or
# thunderclouds", "Never depict forests, dense woods, or non-desert biomes".
# A plain `'storm' in world_prompt` reads that prohibition as a fact, so the
# motif fires on the very sentence forbidding it. That is how a run set under an
# explicitly storm-free sky came back with lightning in every frame.
#
# Negation scope ends at sentence punctuation and dashes, NOT at commas —
# "Never depict forests, dense woods, or non-desert biomes" has to keep covering
# "dense woods" two commas later. The bias is deliberately conservative: a
# missed beat line costs a turn of flavour, a false one rewrites the sky.
_NEGATION_CUES = (
    "no", "not", "never", "nor", "without", "avoid", "avoids", "avoiding",
    "exclude", "excludes", "excluding", "free of", "devoid of", "absent",
    "lacking", "don't", "do not", "doesn't", "cannot", "can't", "won't",
)
_CLAUSE_BREAK = re.compile(r"[.!?;:\n]|—|–|--")
_NEGATION_WINDOW = 160


def _world_asserts(text: str, term: str) -> bool:
    """True when ``text`` states ``term`` as a fact rather than ruling it out.

    Any un-negated mention wins: a world may forbid storms at the opening and
    then genuinely break one later in the run, and the live beat should fire on
    that second mention instead of being cancelled by the first.
    """
    if not text or not term:
        return False
    for m in re.finditer(rf"\b{re.escape(term)}\b", text, flags=re.I):
        window = text[max(0, m.start() - _NEGATION_WINDOW):m.start()].replace("\u2019", "'")
        breaks = list(_CLAUSE_BREAK.finditer(window))
        if breaks:
            window = window[breaks[-1].end():]
        if not any(re.search(rf"\b{re.escape(cue)}\b", window, flags=re.I)
                   for cue in _NEGATION_CUES):
            return True
    return False


def summarize_world_state(state: dict) -> str:
    """
    Return a single, actionable, dynamic sentence summarizing the most important, immediate world state or threat.
    Prioritize: player danger, pursuit, injury, chaos, visible threats, or urgent objectives.

    NOTE: This IS live — it feeds situation_summary into the dispatch/choice
    prompts (see call sites in the turn pipeline). An earlier comment wrongly
    labelled it dead code; do not remove without checking those callers.

    It is a DRAMATIC PRESSURE line for the story prompts, and deliberately no
    longer reaches image generation: "a violent storm is gathering overhead" or
    "the red biome is dangerously close" can only add to a render something the
    camera cannot see. What is in frame comes from `visual_scene`, the look from
    summarize_world_prompt_for_image, the sky from `time_of_day`.
    """
    chaos = state.get('chaos_level', 0)
    if chaos > 7:
        return "OVERWHELMING CHAOS! Immediate, decisive action is paramount to survive!"
    elif chaos > 5:
        return "CRITICAL CHAOS! Guards are on high alert and actively hunting."
    
    if not state.get('player_state', {}).get('alive', True):
        return "You are gravely wounded and in danger of dying."
    world_prompt = state.get('world_prompt', '') or ''
    if _world_asserts(world_prompt, 'storm'):
        return "A violent storm is gathering overhead."
    if any(_world_asserts(world_prompt, w) for w in ('pursued', 'chased', 'hunted', 'spotted')):
        return "You are being pursued by hostile forces."
    if _world_asserts(world_prompt, 'red biome'):
        return "The red biome is dangerously close."
    # Add more as needed for your motifs
    return "You are alone, but danger could strike at any moment."

# ───────── safe OpenAI wrapper ──────────────────────────────────────────────
def _call(fn, *a, **kw):
    global LLM_ENABLED
    if not LLM_ENABLED:
        raise RuntimeError("LLM disabled")
    try:
        return fn(*a, **kw)
    except OpenAIError as e:
        if any(t in str(e).lower() for t in ("quota", "credit", "authentication", "insufficient")):
            LLM_ENABLED = False
            print("LLM disabled:", e, file=sys.stderr, flush=True)
        raise

def _ask(prompt: str, model="gemini", temp=1.0, tokens=90, image_path: str = None, use_lore: bool = True, response_schema: Optional[dict] = None) -> str:
    """Flexible text generation supporting multiple AI providers.
    
    Args:
        prompt: Text prompt
        model: Legacy parameter (ignored - uses ai_config.json instead)
        temp: Temperature (0-1)
        tokens: Max output tokens
        image_path: Optional path to image for multimodal input (e.g. "/images/file.png")
        use_lore: Whether to include lore cache (default True). Set False for mechanical/vision tasks.
    """
    if not LLM_ENABLED:
        place = ""
        try:
            place = game_identity.place_summary() or game_identity.display_name()
        except Exception:
            place = ""
        place = place or "this place"
        return f"You are still in {place}. The next move is yours."
    
    # Experience lore is the native bible (Horizon, The Gate, …). The old
    # Gemini cachedContent path is optional and usually off; this is the
    # one that actually fires.
    if use_lore:
        try:
            import experience_store
            prompt = experience_store.apply_lore_to_prompt(prompt)
        except Exception:
            pass

    # Get active provider from config
    provider = ai_provider_manager.get_text_provider()
    model_name = ai_provider_manager.get_text_model()
    if provider_bridge.active():
        # OpenAI chosen in ACCOUNT: build the Gemini request; the bridge
        # answers it with the player's OpenAI key and models.
        if provider != "gemini":
            model_name = "gemini-3.1-flash-lite"
        provider = "gemini"
    
    if provider == "gemini":
        return _ask_gemini(prompt, model_name, temp, tokens, image_path, use_lore, response_schema=response_schema)
    elif provider == "openai":
        return _ask_openai(prompt, model_name, temp, tokens, image_path)
    elif provider == "anthropic":
        return _ask_claude(prompt, model_name, temp, tokens, image_path)
    else:
        print(f"[ASK ERROR] Unknown provider: {provider}, falling back to Gemini")
        return _ask_gemini(prompt, model_name, temp, tokens, image_path, use_lore, response_schema=response_schema)

def _record_text_usage(provider: str, model_name: str, *, success: bool,
                        input_units: Optional[float] = None,
                        output_units: Optional[float] = None,
                        error_message: Optional[str] = None) -> None:
    """
    Record one text-generation call for the admin Analytics tab.

    Attribution uses `get_active_session_id()` rather than a threaded-through
    `session_id` param — `_ask()`/`_ask_gemini()`/`_ask_openai()`/`_ask_claude()`
    have ~10 call sites across engine.py and none of them carry session_id
    today. This is the same known tradeoff already documented for
    `_active_session_id` elsewhere (see `_resolve_request_session_id`'s
    docstring): accurate for the common case (one active session at a time),
    imprecise under truly concurrent multi-session load. Good enough for a
    cost *estimate* dashboard; revisit if/when that becomes the norm.
    """
    try:
        cost_tracker.record_usage(
            get_active_session_id(), "text", provider, model_name,
            operation="ask", input_units=input_units, output_units=output_units,
            unit_type="tokens", success=success, error_message=error_message,
        )
    except Exception as _e:
        print(f"[COST TRACKER] _record_text_usage failed (non-fatal): {_e}", flush=True)


def _ask_gemini(prompt: str, model_name: str, temp: float, tokens: int, image_path: str = None, use_lore: bool = True, response_schema: Optional[dict] = None) -> str:
    """Gemini text generation implementation with optional lore cache."""
    import requests
    import base64
    from pathlib import Path
    gemini_api_key = GEMINI_API_KEY
    
    try:
        # Build parts list (text + optional image)
        parts = [{"text": prompt}]
        
        # Add image if provided
        if image_path:
            # Convert path to actual file path
            if image_path.startswith("/images/"):
                actual_path = Path("images") / image_path.replace("/images/", "")
            else:
                actual_path = Path(image_path)
            
            if actual_path.exists():
                # Use pre-downsampled version if available (saves processing time)
                small_path = actual_path.parent / actual_path.name.replace(".png", "_small.png")
                use_path = small_path if small_path.exists() else actual_path

                # Compact JPEG attach (falls back to raw bytes on any error).
                _img_part = _encode_image_inline_part(use_path)
                if _img_part is None:
                    with open(use_path, "rb") as f:
                        image_data = base64.b64encode(f.read()).decode('utf-8')
                    _img_part = {"inlineData": {"mimeType": "image/png", "data": image_data}}
                parts.insert(0, _img_part)
                size_note = "(480x360, 4:3)" if small_path.exists() else "(full-res)"
                print(f"[GEMINI TEXT+IMG] Including image: {image_path} {size_note}")
        
        # Check for lore cache (only if use_lore=True). Imported lazily so the
        # disabled-by-default lore cache never loads with the core engine.
        cache_id = None
        if use_lore:
            import lore_cache_manager
            cache_id = lore_cache_manager.get_cache_id()
        
        # Build request payload with ALL SAFETY FILTERS DISABLED
        gen_cfg = {"thinkingConfig": {"thinkingBudget": 0}, "temperature": temp, "maxOutputTokens": tokens}
        if response_schema:
            gen_cfg["responseMimeType"] = "application/json"
            gen_cfg["responseSchema"] = response_schema
        payload = {
            "contents": [{"parts": parts}],
            "generationConfig": gen_cfg,
            "safetySettings": [
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"}
            ]
        }
        
        # Add cached content if available
        if cache_id:
            payload["cachedContent"] = cache_id
            print(f"[GEMINI CACHED] Using lore cache: {cache_id.split('/')[-1][:16]}...")
        elif use_lore:
            print(f"[GEMINI] Experience lore on prompt; Gemini cache unused")
        
        print(f"[GEMINI TEXT] Calling {model_name} API...", flush=True)
        _gemini_url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent"
        _gemini_headers = {"x-goog-api-key": gemini_api_key, "Content-Type": "application/json"}
        response_data = None
        # Found by playtest.py's forced-encounter probe (see
        # docs/plans/PLAYTEST_CONSOLIDATION_PLAN.md): this is the core
        # narrative call, and it timed out and masked itself as a diegetic
        # "Signal interrupted..." beat the very first time the API was slow
        # for even a moment — one call site tighter than every other Gemini
        # call in this file (20-30s elsewhere), on the path most likely to
        # carry an inline reference image and so be the slowest to answer.
        # A single retry, same as the existing 429 handling below, is what
        # every other timeout-prone call in this file already does.
        for _attempt in range(2):  # one retry on 429 or on a timeout
            try:
                response = requests.post(_gemini_url, headers=_gemini_headers, json=payload, timeout=25)
                print(f"[GEMINI TEXT] API returned status: {response.status_code}", flush=True)
                if response.status_code == 429 and _attempt == 0:
                    print(f"[GEMINI TEXT] Rate limited (429) — retrying in 4s...", flush=True)
                    time.sleep(4)
                    continue
                response.raise_for_status()
                response_data = response.json()
                print(f"[GEMINI TEXT] Response parsed successfully", flush=True)
                break
            except requests.exceptions.Timeout:
                if _attempt == 0:
                    print(f"[GEMINI TEXT] API timeout after 25s — retrying once...", flush=True)
                    continue
                print(f"[GEMINI TEXT ERROR] API timeout after 25 seconds, twice!", flush=True)
                _record_text_usage("gemini", model_name, success=False, error_message="timeout")
                return "Signal interrupted due to timeout..."
            except requests.exceptions.HTTPError as e:
                print(f"[GEMINI TEXT ERROR] HTTP error: {e}", flush=True)
                _record_text_usage("gemini", model_name, success=False, error_message=str(e))
                return "Signal interrupted due to API error..."
            except Exception as e:
                print(f"[GEMINI TEXT ERROR] Unexpected error: {type(e).__name__}: {e}", flush=True)
                import traceback
                traceback.print_exc()
                _record_text_usage("gemini", model_name, success=False, error_message=str(e))
                return "Signal interrupted..."
        if response_data is None:
            _record_text_usage("gemini", model_name, success=False, error_message="rate_limited")
            return "Signal interrupted due to rate limiting..."
        
        # Check for error response from Gemini API
        if "candidates" not in response_data:
            print(f"[ASK GEMINI ERROR] Gemini API error response: {response_data}", flush=True)
            if "error" in response_data:
                error_details = response_data['error']
                print(f"[ASK GEMINI ERROR] Code: {error_details.get('code')}, Message: {error_details.get('message')}", flush=True)
            _record_text_usage("gemini", model_name, success=False, error_message=str(response_data.get("error")))
            return "The transmission wavers... static fills the air as the signal struggles to maintain connection."
        
        result = response_data["candidates"][0]["content"]["parts"][0]["text"].strip()
        # Gemini's raw REST response already includes token counts — just never
        # read them until now. See ADMIN_COST_ANALYTICS_DASHBOARD_PLAN.md §4.
        usage = response_data.get("usageMetadata", {}) or {}
        _record_text_usage(
            "gemini", model_name, success=True,
            input_units=usage.get("promptTokenCount"),
            output_units=usage.get("candidatesTokenCount"),
        )
        return result if result else "..."
    except Exception as e:
        # Catch any unexpected errors not handled above
        log_error(f"[ASK GEMINI CRITICAL] Unexpected error: {e}")
        import traceback
        traceback.print_exc()
        _record_text_usage("gemini", model_name, success=False, error_message=str(e))
        return "Signal interrupted..."

def _ask_openai(prompt: str, model_name: str, temp: float, tokens: int, image_path: str = None) -> str:
    """OpenAI text generation implementation."""
    import base64
    from pathlib import Path
    
    # Validate API key
    if not OPENAI_API_KEY:
        print("[OPENAI TEXT] ERROR: OPENAI_API_KEY not set! Cannot generate text.")
        print("[OPENAI TEXT] Set environment variable OPENAI_API_KEY or add to config.json")
        raise ValueError("OPENAI_API_KEY not configured")
    
    try:
        messages = []
        
        # Add image if provided (using GPT-4 Vision)
        if image_path:
            if image_path.startswith("/images/"):
                actual_path = Path("images") / image_path.replace("/images/", "")
            else:
                actual_path = Path(image_path)
            
            if actual_path.exists():
                small_path = actual_path.parent / actual_path.name.replace(".png", "_small.png")
                use_path = small_path if small_path.exists() else actual_path
                
                with open(use_path, "rb") as f:
                    image_data = base64.b64encode(f.read()).decode('utf-8')
                
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:image/png;base64,{image_data}"
                            }
                        },
                        {
                            "type": "text",
                            "text": prompt
                        }
                    ]
                })
                print(f"[OPENAI TEXT+IMG] Including image: {image_path}")
            else:
                messages.append({"role": "user", "content": prompt})
        else:
            messages.append({"role": "user", "content": prompt})
        
        response = client.chat.completions.create(
            model=model_name,
            messages=messages,
            temperature=temp,
            max_tokens=tokens
        )
        
        result = response.choices[0].message.content.strip()
        usage = getattr(response, "usage", None)
        _record_text_usage(
            "openai", model_name, success=True,
            input_units=getattr(usage, "prompt_tokens", None) if usage else None,
            output_units=getattr(usage, "completion_tokens", None) if usage else None,
        )
        return result if result else "..."
    except Exception as e:
        log_error(f"[ASK OPENAI] {e}")
        _record_text_usage("openai", model_name, success=False, error_message=str(e))
        return "Signal interrupted..."

def _ask_claude(prompt: str, model_name: str, temp: float, tokens: int, image_path: str = None) -> str:
    """Anthropic Claude text generation implementation."""
    anthropic_key = os.environ.get("ANTHROPIC_API_KEY", "")
    if not anthropic_key:
        print("[CLAUDE TEXT] ERROR: ANTHROPIC_API_KEY not set! Cannot generate text.")
        return "Signal interrupted — Anthropic API key not configured."

    try:
        import anthropic as _anthropic
        _claude_client = _anthropic.Anthropic(api_key=anthropic_key)

        content: list = []

        if image_path:
            from pathlib import Path as _Path
            import base64 as _base64
            if image_path.startswith("/images/"):
                actual_path = _Path("images") / image_path.replace("/images/", "")
            else:
                actual_path = _Path(image_path)
            if actual_path.exists():
                small_path = actual_path.parent / actual_path.name.replace(".png", "_small.png")
                use_path = small_path if small_path.exists() else actual_path
                with open(use_path, "rb") as f:
                    image_data = _base64.b64encode(f.read()).decode("utf-8")
                content.append({
                    "type": "image",
                    "source": {
                        "type": "base64",
                        "media_type": "image/png",
                        "data": image_data,
                    },
                })
                print(f"[CLAUDE TEXT+IMG] Including image: {image_path}")

        content.append({"type": "text", "text": prompt})

        print(f"[CLAUDE TEXT] Calling {model_name} API...", flush=True)
        response = _claude_client.messages.create(
            model=model_name,
            max_tokens=tokens,
            temperature=temp,
            messages=[{"role": "user", "content": content}],
        )
        result = response.content[0].text.strip()
        print(f"[CLAUDE TEXT] Response received ({len(result)} chars)", flush=True)
        usage = getattr(response, "usage", None)
        _record_text_usage(
            "anthropic", model_name, success=True,
            input_units=getattr(usage, "input_tokens", None) if usage else None,
            output_units=getattr(usage, "output_tokens", None) if usage else None,
        )
        return result if result else "..."
    except Exception as e:
        log_error(f"[ASK CLAUDE] {e}")
        import traceback
        traceback.print_exc()
        _record_text_usage("anthropic", model_name, success=False, error_message=str(e))
        return "Signal interrupted..."

# ───────── path resolution helper ───────────────────────────────────────────
def _resolve_image_path(image_path: str, session_id: str = None) -> Path:
    """
    Resolve image path to actual filesystem location.

    Handles absolute (session-specific) and web (``/images/<name>``) paths, and
    is SESSION-AWARE: web URLs carry a ``?session=<id>`` hint (stamped by
    ``_to_web_image_url``) because each session writes into its OWN
    ``sessions/<id>/images`` dir. Mirrors the ``/images/<filename>`` serve
    route's resolution order (session dir -> default -> legacy root -> scan) so
    a per-session image (e.g. a companion portrait) actually resolves instead of
    falling back to the legacy root dir and reporting "missing".

    Args:
        image_path: e.g. ``/images/file.png``, ``/images/file.png?session=abc``,
                    ``images/file.png``, or an absolute path.
        session_id: explicit session hint (wins over any ``?session=`` query).

    Returns:
        A Path to the file (existing when found); on a miss returns the legacy
        ``ROOT/images/<name>`` guess so callers' ``.exists()`` checks still work.
    """
    if not image_path:
        return None

    s = str(image_path)
    hint = session_id
    # Strip a ?session=<id> hint (part of the URL, not the filename).
    if "?" in s:
        base, _, query = s.partition("?")
        if not hint:
            try:
                from urllib.parse import parse_qs
                q = parse_qs(query)
                hint = (q.get("session") or q.get("session_id") or [None])[0]
            except Exception:
                hint = None
        s = base

    path = Path(s)
    # Absolute path that exists — use it directly.
    if path.is_absolute() and path.exists():
        return path

    name = path.name
    candidates = []
    if hint and hint not in ('default', 'legacy'):
        try:
            candidates.append(Path(_get_image_dir(hint)) / name)
        except Exception:
            pass
    # 'images/<name>' legacy relative form maps under ROOT as-is.
    if s.startswith("images/"):
        candidates.append(ROOT / s)
    try:
        candidates.append(Path(_get_image_dir('default')) / name)
    except Exception:
        pass
    candidates.append(ROOT / "images" / name)
    for c in candidates:
        try:
            if c.exists():
                return c
        except Exception:
            pass

    # Last resort: scan session image dirs for the basename (covers URLs that
    # lost their session hint). Only reached when the file wasn't found above,
    # so it never runs in the common path.
    try:
        sessions_root = DATA / "sessions"
        if sessions_root.exists():
            for sess in sessions_root.iterdir():
                cand = sess / "images" / name
                if cand.exists():
                    return cand
    except Exception:
        pass

    return ROOT / "images" / name


def _sniff_image_mime(path) -> str:
    """MIME type from magic bytes, then extension.

    Realtime observe/act captures are JPEG data URLs written to disk. Older
    builds named them ``observed_*.png``, so trusting the extension sends the
    wrong type to Gemini and vision/choice-reground silently drop the frame.
    """
    try:
        p = Path(path)
        head = b""
        if p.exists() and p.is_file():
            with open(p, "rb") as f:
                head = f.read(16)
        if head.startswith(b"\xff\xd8\xff"):
            return "image/jpeg"
        if head.startswith(b"\x89PNG"):
            return "image/png"
        if head.startswith(b"GIF8"):
            return "image/gif"
        if len(head) >= 12 and head[:4] == b"RIFF" and head[8:12] == b"WEBP":
            return "image/webp"
        name = p.name.lower()
        if name.endswith((".jpg", ".jpeg")):
            return "image/jpeg"
        if name.endswith(".webp"):
            return "image/webp"
    except Exception:
        pass
    return "image/png"


def _encode_image_inline_part(path) -> Optional[dict]:
    """Build a Gemini `inlineData` part for an image path.

    Four multimodal attachments ride the turn's critical path (the previous
    frame on the consequence call, the new frame on the vision read, the choice
    call, and the critic when it runs). Each is a 480x360 sidecar; re-encoding
    to JPEG shrinks the upload several-fold versus PNG for the same content.
    Falls back to the raw file bytes with a sniffed MIME on ANY error, so a
    decode problem never drops the image entirely. Returns None only when the
    file itself cannot be read."""
    import base64 as _b64
    try:
        p = Path(path)
        raw = p.read_bytes()
    except Exception:
        return None
    try:
        import io
        from PIL import Image
        with Image.open(io.BytesIO(raw)) as im:
            if im.mode not in ("RGB", "L"):
                im = im.convert("RGB")
            buf = io.BytesIO()
            im.save(buf, format="JPEG", quality=85)
            data = buf.getvalue()
        # Only prefer JPEG when it is actually smaller (it essentially always is
        # for these PNG sidecars; a tiny image could round the other way).
        if data and len(data) < len(raw):
            return {"inlineData": {"mimeType": "image/jpeg",
                                   "data": _b64.b64encode(data).decode("utf-8")}}
    except Exception:
        pass
    try:
        return {"inlineData": {"mimeType": _sniff_image_mime(p),
                               "data": _b64.b64encode(raw).decode("utf-8")}}
    except Exception:
        return None


def _detect_scene_prior(st) -> str:
    """Label hint for SCAN / detect — must describe the on-screen frame.

    ``current_image_prompt`` is the last still's render recipe (camera grammar,
    previous-turn objects, style). Folding it into detect is why MOVE TO keeps
    offering the pink sedan / rusted truck after the live video has drifted.
    Only a vision pass that actually looked at a captured live frame is an
    honest prior; otherwise the pixels are the sole source of truth.
    """
    if not isinstance(st, dict):
        return ""
    return str(st.get("current_observed_vision") or "").strip()

# ───────── vision description helper ────────────────────────────────────────
def _downscale_for_vision(image_path: str, size=(640, 426)) -> io.BytesIO:
    full = _resolve_image_path(image_path)
    buf = io.BytesIO()
    if not full or not full.exists():
        return None
    try:
        img = Image.open(full)
        img = img.convert("RGB")
        img = img.resize(size, Image.LANCZOS)
        img.save(buf, format="PNG")
        buf.seek(0)
        return buf
    except Exception as e:
        print("[VISION] Downscale error:", e, file=sys.stderr)
        return None

def _vision_analyze_all(image_path: str) -> dict:
    """
    Unified vision analysis - gets description, time of day, and color in ONE API call.
    Results are cached to avoid redundant API calls.
    
    Returns dict with keys: 'description', 'time_of_day', 'color_palette'
    """
    import base64
    import requests
    import os
    
    if not LLM_ENABLED or not VISION_ENABLED:
        return {"description": "", "time_of_day": "", "color_palette": ""}
    
    try:
        
        # Handle path - ensure it's accessible
        full_path = _resolve_image_path(image_path)
        if not full_path or not full_path.exists():
            return {"description": "", "time_of_day": "", "color_palette": ""}
        
        if not os.path.exists(full_path):
            print(f"[VISION ERROR] Image file not found: {image_path}")
            return {"description": "", "time_of_day": "", "color_palette": ""}
        
        # Use pre-downsampled version if available (saves processing time)
        from pathlib import Path
        full_path_obj = Path(full_path)
        small_path = full_path_obj.parent / full_path_obj.name.replace(".png", "_small.png")
        use_path = full_path_obj
        if small_path.exists():
            # A downsample left over from an earlier render of the same path
            # is a picture nobody is looking at any more.
            try:
                fresh = small_path.stat().st_mtime >= full_path_obj.stat().st_mtime
            except OSError:
                fresh = False
            if fresh:
                use_path = small_path
        
        # Cache on the BYTES, not the name. World frames live at one fixed
        # path per world (worlds/<slug>.frame.png) and are regenerated in
        # place, so a path-keyed cache kept answering with the description of
        # the previous render — the game confidently describing a picture
        # that is no longer on screen.
        try:
            st = use_path.stat()
            cache_key = f"{use_path.resolve()}:{st.st_mtime_ns}:{st.st_size}"
        except OSError:
            cache_key = str(use_path)
        if cache_key in _vision_cache:
            print(f"[VISION] Using cached analysis for {os.path.basename(image_path)}")
            return _vision_cache[cache_key]

        static_frame = _vision_cache_is_static(use_path)
        if static_frame:
            stored = _vision_disk_cache_get(cache_key)
            if stored:
                print(f"[VISION] Using stored analysis for "
                      f"{os.path.basename(image_path)} (no API call)")
                _vision_cache[cache_key] = stored
                return stored
        
        # Attach the frame as a compact JPEG part (falls back to the raw bytes
        # on any decode error). This is the read on the turn's critical path, so
        # the smaller upload shaves real wall-clock.
        _img_part = _encode_image_inline_part(use_path)
        if _img_part is None:
            # Last-resort: keep the original raw-bytes attach so a decode failure
            # never drops the frame.
            with open(use_path, "rb") as f:
                image_bytes = f.read()
            _img_part = {"inlineData": {"mimeType": _sniff_image_mime(use_path),
                                        "data": base64.b64encode(image_bytes).decode('utf-8')}}
        
        if small_path.exists():
            print(f"[VISION] Using pre-downsampled image (480x360, 4:3)")
        
        # Use Gemini vision API - ONE call for everything
        print(f"[VISION] Analyzing {os.path.basename(image_path)} (all-in-one)...")
        
        # This analysis becomes the SPATIAL ANCHOR for the next frame's image
        # prompt, so it is a continuity loop: whatever vocabulary it answers in
        # is what the next image is built from. The worked example used to be a
        # Horizon truck on sandy desert, which quietly dragged an authored level
        # back toward the shipped one one turn at a time. Ground it in the
        # player's actual level and camera instead.
        grounding = game_identity.scene_grounding()
        grounding_block = f"{grounding}\n\n" if grounding else ""
        vision_prompt = grounding_block + """Analyze this image and respond in this EXACT format:

TIME: <time of day - use ONLY: dawn, morning, afternoon, golden hour, dusk, or night>
COLOR: <dominant color palette in 5-10 words>
DESCRIPTION: <detailed description of what is visible, focusing on objects, threats, exits, and anything you could interact with. Be direct and literal. If there are hands, weapons, tools, figures, silhouettes, or creatures visible, mention them explicitly.>
SPATIAL: <spatial compass — describe: (a) what is DIRECTLY AHEAD at what distance, (b) what is visible to the LEFT, (c) what is visible to the RIGHT, (d) what is underfoot/ground type, (e) camera height estimate (standing/crouching/elevated). Keep under 50 words. Format: "Ahead: <thing> ~<distance>. Left: <thing> ~<distance>. Right: <thing> ~<distance>. Ground: <surface>. <Camera height>.">
SETTING: <ONE of: outdoor-desert, outdoor-cliff, outdoor-road, outdoor-other, indoor-corridor, indoor-lab, indoor-warehouse, indoor-other, transitional>
WATCHERS: <count> | <facing|away|none> | <near|mid|far>

Describe ONLY what is actually in this image. Do not assume a desert, a facility, or any location the image does not show.

WATCHERS answers one thing: could something in this frame see the camera right now.
• <count>: how many LIVING things are visible (people, figures, silhouettes, creatures, animals). Machines only if clearly pointed this way.
• <facing>: the NEAREST one's orientation — `facing` toward this camera, `away` if turned off or occupied, `none` if count is 0.
• <near|mid|far>: that same nearest one's distance — `near` is within a stride, `far` is a distant silhouette.
Grade the FRAME, not the story: no watchers you cannot see, nobody implied by the setting, and darkness is not somebody hiding in it. `0 | none | far` is the common, correct answer."""
        
        # Model note: gemini-2.0-flash-exp and later gemini-2.0-flash were retired
        # on the current API/key (text calls 404'd while gemini-3.1-flash-lite-image still
        # worked). Use the current gemini-3.1-flash-lite text model.
        api_url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent"
        
        # DEBUG: Log API key status for Vision
        if not provider_bridge.can_call_gemini_api():
            print(f"[VISION ERROR] no Gemini key and no OpenAI key to stand in")

        headers = {
            "x-goog-api-key": GEMINI_API_KEY,
            "Content-Type": "application/json"
        }
        
        payload = {
            "contents": [{
                "parts": [
                    # IMAGE FIRST per Gemini best practices for single-image prompts
                    _img_part,
                    {"text": vision_prompt}
                ]
            }],
            "generationConfig": {"thinkingConfig": {"thinkingBudget": 0}, 
                "temperature": 1.0,  # Default for Gemini 2.x/3.x per guidelines
                "maxOutputTokens": 800
            },
            "safetySettings": [
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"}
            ]
        }
        
        response = requests.post(api_url, headers=headers, json=payload, timeout=30)
        response.raise_for_status()
        
        result = response.json()
        
        # Extract text from Gemini response
        if "candidates" not in result or not result["candidates"]:
            print(f"[VISION ERROR] No candidates in response")
            return {"description": "", "time_of_day": "", "color_palette": ""}
        
        candidate = result["candidates"][0]
        if "content" not in candidate or "parts" not in candidate["content"]:
            print(f"[VISION ERROR] Invalid response structure")
            return {"description": "", "time_of_day": "", "color_palette": ""}
        
        parts = candidate["content"]["parts"]
        full_text = ""
        for part in parts:
            if "text" in part:
                full_text += part["text"]
        
        if not full_text:
            print(f"[VISION ERROR] No text in response")
            return {"description": "", "time_of_day": "", "color_palette": ""}
        
        # Parse the structured response
        time_of_day  = ""
        color_palette = ""
        description  = ""
        spatial      = ""   # NEW: directional compass (ahead/left/right/ground/height)
        setting      = ""   # NEW: environment type (outdoor-desert, indoor-corridor, etc.)
        watchers     = ""   # NEW: could anything in frame see the camera (see the
                            # detection ladder's "witness" — this is the sensor that
                            # makes being seen a fact about the picture rather than a
                            # phrase the narrator happened to choose)

        lines = full_text.strip().split("\n")
        for i, line in enumerate(lines):
            if line.startswith("TIME:"):
                time_of_day = line.replace("TIME:", "").strip()
            elif line.startswith("COLOR:"):
                color_palette = line.replace("COLOR:", "").strip()
            elif line.startswith("DESCRIPTION:"):
                description = line.replace("DESCRIPTION:", "").strip()
                # Capture continuation lines that are NOT other field labels.
                # Every field label has to be in this stop-list: one that is
                # missing gets swallowed into the description, which is the
                # spatial anchor for the NEXT image prompt, so a parse leak
                # here quietly poisons the render continuity loop.
                j = i + 1
                while j < len(lines) and not any(
                    lines[j].startswith(k) for k in
                    ("SPATIAL:", "SETTING:", "TIME:", "COLOR:", "WATCHERS:")
                ):
                    description += " " + lines[j]
                    j += 1
            elif line.startswith("SPATIAL:"):
                spatial = line.replace("SPATIAL:", "").strip()
            elif line.startswith("SETTING:"):
                setting = line.replace("SETTING:", "").strip()
            elif line.startswith("WATCHERS:"):
                watchers = line.replace("WATCHERS:", "").strip()

        # If parsing failed, fall back to raw text
        if not description:
            description = full_text

        result_dict = {
            "description":   description.strip().replace("\n", " "),
            "time_of_day":   time_of_day.strip(),
            "color_palette": color_palette.strip(),
            "spatial":       spatial.strip(),
            "setting":       setting.strip(),
            "watchers":      watchers.strip(),
        }

        # Cache the result
        _vision_cache[cache_key] = result_dict
        if static_frame:
            _vision_disk_cache_put(cache_key, result_dict)

        print(
            f"[VISION] Analysis complete: {len(description)} chars, "
            f"time={time_of_day}, setting={setting}, "
            f"spatial='{spatial[:60]}...'" if len(spatial) > 60 else
            f"[VISION] Analysis complete: {len(description)} chars, "
            f"time={time_of_day}, setting={setting}, spatial='{spatial}'"
        )
        return result_dict
    
    except requests.exceptions.HTTPError as e:
        safe_e = str(e).encode('ascii', 'replace').decode('ascii')
        print(f"[VISION ERROR] Gemini API HTTP error: {safe_e}")
        if e.response is not None:
            print(f"[VISION ERROR] Response: {e.response.text}")
        return {"description": "", "time_of_day": "", "color_palette": ""}
    except Exception as e:
        safe_e = str(e).encode('ascii', 'replace').decode('ascii')
        print(f"[VISION ERROR] Failed to analyze image: {safe_e}")
        import traceback
        traceback.print_exc()
        return {"description": "", "time_of_day": "", "color_palette": ""}

# Legacy wrapper for backward compatibility
def _vision_describe(image_path: str) -> str:
    """Get image description (uses cached unified analysis)."""
    result = _vision_analyze_all(image_path)
    return result["description"]


# Labels that read as something you could hold a conversation with, even when
# the vision model forgets to flag `speaks`. Kept deliberately broad (people,
# figures, sentient creatures, and machines that carry a voice) because a false
# positive just offers a TALK option the story can gracefully play off, while a
# false negative silently hides the whole mechanic.
_SPEAKER_LABEL_RE = re.compile(
    r"\b("
    r"person|people|man|men|woman|women|boy|girl|child|children|kid|guy|lady|"
    r"figure|silhouette|stranger|survivor|soldier|guard|worker|scientist|"
    r"doctor|nurse|officer|cop|ranger|pilot|driver|operator|technician|"
    r"crowd|villager|prisoner|captive|hostage|patient|passenger|civilian|"
    r"face|head|corpse|body|ghost|spirit|apparition|"
    r"creature|beast|monster|alien|humanoid|android|robot|droid|cyborg|"
    r"ai|hologram|avatar|puppet|doll|mannequin|statue|"
    r"radio|intercom|speaker|phone|telephone|handset|walkie|walkie-talkie|"
    r"transceiver|receiver|terminal|console|computer|monitor|screen|"
    r"pa system|loudspeaker|megaphone|"
    r"dog|cat|horse|bird|parrot|crow|raven|snake|wolf|fox|rat|owl"
    r")\b"
)

# Kinds the model may return that we consider conversational.
_SPEAKER_KINDS = {"person", "character", "creature"}


# Detected labels that make underwhelming scan tags / "photograph the X"
# objectives, filtered out entirely so they never reach the client. This is a
# first-person driving POV shot on found-footage tape, so the model otherwise
# keeps re-detecting the SAME boring things every single scan: the player's
# own gloved hands on the wheel, the dashboard/mirrors/controls of the car
# they're always sitting in, and the camcorder doing the recording. None of
# that is ever a meaningful objective — the interesting stuff is what's OUT in
# the world (structures, terrain, hazards, creatures, props). An exact-phrase
# set covers the unambiguous vehicle/gear nouns; a small regex backstops the
# hand/glove/arm family, whose labels vary ("gloved hand", "driving glove",
# "hands") but — given labels are capped at 1-3 words by the detect prompt —
# are overwhelmingly the player's own POV hands whenever they appear at all.
_LEADING_ARTICLE_RE = re.compile(r"^(?:a|an|the)\s+")
_UNDERWHELMING_LABELS = frozenset({
    # Vehicle-interior fixtures the player is always sitting inside of.
    "steering wheel", "dashboard", "dash", "gauge", "gauges", "speedometer",
    "odometer", "rearview mirror", "rear view mirror", "side mirror",
    "windshield", "wiper", "wipers", "gear shift", "gearshift", "gearstick",
    "handbrake", "hand brake", "seatbelt", "seat belt", "sun visor",
    "glove box", "glovebox", "car seat", "headrest",
    # The player's OWN recording gear — always in frame in this found-footage
    # conceit, never a story object.
    "camcorder", "handheld camera", "viewfinder", "camera lens",
    # Worn kit the follow-cam body is carrying. A radio on a crate is a
    # world object; a "microphone" on the player's chest is not.
    "microphone", "mic", "headset", "headphones", "earbuds",
    # Generic background the detect prompt already discourages; kept here as a
    # backstop in case the model tags it anyway.
    "shadow", "shadows", "reflection", "dust", "haze", "glare", "sunbeam",
    "sunlight", "horizon",
})
_UNDERWHELMING_PART_RE = re.compile(
    # ONLY the parts of the camera operator that are genuinely in every single
    # frame of a found-footage game: the hands holding the camera and the arms
    # attached to them.
    #
    # This list used to run all the way down the body — leg, knee, shin, foot,
    # boot, shoe, shoulder, sleeve — on the theory that "photograph the boot" is
    # a weak tag. But in a horror game a boot on the ground, a leg sticking out
    # from under something, a single shoe: those are the most interesting things
    # in the frame, and they were being thrown away before they could be tagged.
    # Same reasoning that already kept "chest" and "torso" off this list.
    r"\b(glove|gloves|hand|hands|finger|fingers|thumb|thumbs|palm|palms|"
    r"wrist|wrists|knuckle|knuckles|fist|fists|arm|arms|forearm|forearms|"
    r"elbow|elbows|jacket cuff|cuff)\b"
)


def _is_underwhelming_label(label: str) -> bool:
    """True for a detected label that would make an underwhelming scan tag or
    objective — see _UNDERWHELMING_LABELS / _UNDERWHELMING_PART_RE above."""
    normalized = _LEADING_ARTICLE_RE.sub("", (label or "").strip().lower())
    if not normalized:
        return True
    if normalized in _UNDERWHELMING_LABELS:
        return True
    return bool(_UNDERWHELMING_PART_RE.search(normalized))


_PLAYER_SELF_LABELS = frozenset({
    "player", "player character", "the player", "protagonist",
    "main character", "the protagonist",
})

# Generic names Gemini gives the followed body when it ignores the self-rule.
_FOLLOW_CAM_PERSON_RE = re.compile(
    r"^(?:a|an|the)?\s*(person|people|man|woman|boy|girl|figure|"
    r"silhouette|stranger|guy|lady|character)\s*$",
    re.I,
)
# Kit hanging off that body — a radio on a crate is a world object; a
# microphone on the follow-cam chest is not.
_WORN_GEAR_RE = re.compile(
    r"\b(microphone|mic|headset|headphone|headphones|earphone|earbuds|"
    r"radio|walkie|walkie-talkie|camera|camcorder|backpack|holster|"
    r"antenna|handset|transmitter|press badge|badge)\b",
    re.I,
)


def _is_player_self_label(label: str) -> bool:
    """True when SCAN named the body the camera is already following.

    The detect prompt already asks not to tag them; Gemini still does
    ("player character", the shipped name). Tapping that tag is "Move to
    yourself", which is how a second, differently-gendered figure gets
    invented into the next hard cut. Dropping the tag in code is the
    backstop — not another sentence in the detect prompt.
    """
    if not game_identity.shows_character():
        return False
    normalized = _LEADING_ARTICLE_RE.sub("", (label or "").strip().lower())
    if not normalized:
        return False
    if normalized in _PLAYER_SELF_LABELS:
        return True
    who = game_identity.display_name().strip().lower()
    if not who or who == "the player character":
        return False
    if normalized == who:
        return True
    parts = [p for p in re.findall(r"[a-z]+", who) if len(p) > 2]
    return normalized in parts


def _detection_ymax(obj: dict) -> float:
    return float(obj.get("cy") or 0.0) + float(obj.get("h") or 0.0) / 2.0


def _is_generic_person_label(label: str) -> bool:
    normalized = _LEADING_ARTICLE_RE.sub("", (label or "").strip().lower())
    return bool(_FOLLOW_CAM_PERSON_RE.match(normalized))


def _is_person_like_tag(obj: dict) -> bool:
    kind = str(obj.get("kind") or "").strip().lower()
    if kind in ("person", "character"):
        return True
    return _is_generic_person_label(obj.get("label") or "")


def _is_follow_cam_body(obj: dict) -> bool:
    """True for the third-person follow-cam subject.

    The tell is a person-like box clipped by the bottom of the frame in the
    lower center — feet run off the shot, mass sits below the midline. An
    NPC standing in the world almost always has ground under them.
    """
    if not _is_person_like_tag(obj):
        return False
    if _detection_ymax(obj) < 0.90:
        return False
    if float(obj.get("h") or 0) < 0.30:
        return False
    cx = float(obj.get("cx") or 0)
    if not (0.18 <= cx <= 0.82):
        return False
    if float(obj.get("cy") or 0) < 0.38:
        return False
    return True


def _center_inside(inner: dict, outer: dict) -> bool:
    x0 = outer["cx"] - outer["w"] / 2.0
    x1 = outer["cx"] + outer["w"] / 2.0
    y0 = outer["cy"] - outer["h"] / 2.0
    y1 = outer["cy"] + outer["h"] / 2.0
    return x0 <= inner["cx"] <= x1 and y0 <= inner["cy"] <= y1


def _is_torso_band_gear(obj: dict) -> bool:
    """Worn-kit sitting where the follow-cam chest is, even with no body box.

    Only labels that are almost never world objects in this game. A radio
    on a crate or a security camera on a wall must still tag.
    """
    if not re.search(
        r"\b(microphone|mic|headset|headphone|headphones|earphone|earbuds)\b",
        obj.get("label") or "",
        re.I,
    ):
        return False
    cx = float(obj.get("cx") or 0)
    cy = float(obj.get("cy") or 0)
    if not (0.22 <= cx <= 0.78):
        return False
    if not (0.38 <= cy <= 0.82):
        return False
    if float(obj.get("w") or 0) > 0.40 or float(obj.get("h") or 0) > 0.45:
        return False
    return True


def _strip_follow_cam_detections(objects: list) -> list:
    """Drop the followed body and the kit hanging off it.

    Gemini's detect prompt already asks not to tag them; it still returns
    ``person`` on the follow-cam character and ``microphone`` on their
    radio, crowding out the barn / trucks / fence the player actually
    tapped the world to find. Watch never hits this path — it paints
    recorded landmarks — which is why those options look right there.
    """
    if not objects:
        return objects
    bodies = [o for o in objects if _is_follow_cam_body(o)]
    subject = max(bodies, key=lambda o: o["w"] * o["h"]) if bodies else None
    kept = []
    for o in objects:
        if subject is not None and o is subject:
            continue
        if subject is not None and _is_follow_cam_body(o):
            # A second equally-huge bottom-clipped body is still the
            # follow-cam subject under a different label.
            if o["w"] * o["h"] >= subject["w"] * subject["h"] * 0.75:
                continue
        label = o.get("label") or ""
        if _WORN_GEAR_RE.search(label) and (
            (subject is not None and _center_inside(o, subject))
            or _is_torso_band_gear(o)
        ):
            continue
        # Generic "person"/"figure" with no standing-NPC geometry is the
        # follow-cam body boxed as a torso, or junk the detector invented
        # on cables / wreckage. Named NPCs (guard, soldier) keep their tag.
        if _is_generic_person_label(label) and not _is_follow_cam_body(o):
            if float(o.get("h") or 0) < 0.22 or float(o.get("w") or 0) > float(o.get("h") or 0) * 1.2:
                continue
        kept.append(o)
    return kept


def _classify_speaker(label: str, kind_raw, speaks_raw) -> tuple:
    """Decide a detected thing's ``kind`` and whether it ``speaks``.

    Fuses the vision model's own classification with a label heuristic so the
    TALK affordance is offered whenever a person, character, sentient creature,
    or voice-carrying machine is on screen — and withheld for inert scenery.

    Returns ``(kind: str, speaks: bool)`` where kind is one of
    person/character/creature/animal/machine/object.
    """
    valid_kinds = {"person", "character", "creature", "animal", "machine", "object"}
    kind = str(kind_raw or "").strip().lower()
    if kind not in valid_kinds:
        kind = ""

    # Normalize the model's speaks flag (it may arrive as a real bool, a string,
    # or be absent entirely).
    speaks = None
    if isinstance(speaks_raw, bool):
        speaks = speaks_raw
    elif isinstance(speaks_raw, str):
        speaks = speaks_raw.strip().lower() in ("true", "yes", "1")

    label_hit = bool(_SPEAKER_LABEL_RE.search(label or ""))

    # Infer a kind when the model didn't give a usable one.
    if not kind:
        if label_hit:
            if re.search(r"\b(radio|intercom|speaker|phone|telephone|handset|walkie|"
                         r"walkie-talkie|transceiver|receiver|terminal|console|computer|"
                         r"monitor|screen|robot|droid|android|cyborg|ai|hologram|"
                         r"loudspeaker|megaphone|pa system)\b", label):
                kind = "machine"
            elif re.search(r"\b(creature|beast|monster|alien|humanoid|ghost|spirit|apparition)\b", label):
                kind = "creature"
            elif re.search(r"\b(dog|cat|horse|bird|parrot|crow|raven|snake|wolf|fox|rat|owl)\b", label):
                kind = "animal"
            else:
                kind = "person"
        else:
            kind = "object"

    # Decide speaks: honor an explicit model call, else fall back to the kind +
    # the label heuristic.
    if speaks is None:
        speaks = kind in _SPEAKER_KINDS or label_hit
    else:
        # Even a model "true" needs a plausible subject; and a model "false" is
        # overridden when the label very clearly names a speaker (people/voices).
        speaks = speaks or label_hit
        if kind == "object" and not label_hit:
            speaks = False

    return kind, bool(speaks)


_FIGURE_KINDS = frozenset({"person", "character", "creature", "animal"})
_OBJECT_KINDS = frozenset({"machine", "object"})
_OBJECT_LABEL_RE = re.compile(
    r"\b(radio|intercom|speaker|phone|telephone|handset|walkie|"
    r"walkie-talkie|transceiver|receiver|terminal|console|computer|"
    r"monitor|screen|laptop|keyboard|display|panel|loudspeaker|"
    r"megaphone|pa system)\b",
    re.I,
)


def _talk_subject_is_figure(subject: dict) -> bool:
    """True when a TALK subject is a being (cinematic portrait).

    Machines and objects (a computer monitor, a radio) must stay those
    pixels — the portrait path used to phrase every subject as a person,
    so img2img invented a random face in a new room.
    """
    subject = subject or {}
    kind = str(subject.get("kind") or "").strip().lower()
    if kind in _OBJECT_KINDS:
        return False
    if kind in _FIGURE_KINDS:
        return True
    return not bool(_OBJECT_LABEL_RE.search(str(subject.get("label") or "")))


# Shared keep-alive HTTP session for Gemini vision calls. Reopening a TLS
# connection on every /api/detect (which fires at a ~2.1-2.6 s cadence while
# the SCAN overlay is live) burns 100-300 ms per call; a pooled session cuts
# that to near zero and keeps our request/response amortized across the run.
_GEMINI_HTTP_SESSION = requests.Session()

# JSON schema Gemini must adhere to for /api/detect responses. Using a
# responseSchema (not just responseMimeType) guarantees a well-formed array
# with the exact fields we consume — no code-fence stripping, no regex
# fallback, no "wrapped the JSON in prose" edge cases.
#
# `dispatch` and `visual_scene` are two different channels and the schema has
# to carry both. While only `visual_scene` was declared here, structured output
# made it impossible for the model to answer with `dispatch` at all, so the
# parse fell back to `dispatch = visual_scene` and the story log printed the
# image caption: ten turns of "Wren Alvarez stands atop the jumbled heap of
# rusted scrap, the crane appearing closer" — camera bookkeeping, no prose.
# `action_consequence_instructions` has declared both fields mandatory the
# whole time; this is the schema catching up to the authored contract.
_CONSEQUENCE_RESPONSE_SCHEMA = {
    "type": "OBJECT",
    "properties": {
        "dispatch": {"type": "STRING"},
        "visual_scene": {"type": "STRING"},
        "player_alive": {"type": "BOOLEAN"},
        # Did this beat move the player somewhere else? The renderer used to
        # guess that from the wording of the choice, and guessed wrong often
        # enough to break the game: "explore deeper into this space" was read
        # as staying put (`deeper` suppresses the detector, and neither
        # `explore` nor `space` is in its word lists), so the turn rendered as
        # an img2img refine of the frame the player was trying to leave. They
        # watched a step forward animate and land back in the same room.
        #
        # The model has just written the beat, so it already knows. Asking it
        # here costs nothing — same call, one more field — and it makes the
        # picture follow the prose instead of second-guessing it.
        "relocated": {"type": "BOOLEAN"},
        # Did this beat reach WHAT THE PLAYER CAME HERE FOR? Same argument as
        # `relocated`: the model has just written the beat, so it knows. Not
        # required — a World snapshot carrying an older prompt copy never
        # mentions it, and a missing answer reads as "not this turn".
        "goal_reached": {"type": "BOOLEAN"},
    },
    # `relocated` is required too. It was declared but optional, and the
    # prompt's own OUTPUT FORMAT block (further down than the contract, so
    # read later) showed a three-field example — so a model that followed the
    # nearer example left it out, `relocated` parsed as None, and the renderer
    # fell back to the wording classifier this field exists to replace. The
    # example now lists all four, and the schema no longer lets one go missing.
    "required": ["dispatch", "visual_scene", "player_alive", "relocated"],
}


_DETECT_RESPONSE_SCHEMA = {
    "type": "ARRAY",
    "items": {
        "type": "OBJECT",
        "properties": {
            "label":   {"type": "STRING"},
            "box_2d":  {"type": "ARRAY", "items": {"type": "NUMBER"}},
            "kind":    {"type": "STRING",
                        "enum": ["person", "character", "creature",
                                 "animal", "machine", "object"]},
            "speaks":  {"type": "BOOLEAN"},
        },
        "required": ["label", "box_2d"],
    },
}


def _read_detect_image_bytes(image_path: str) -> tuple:
    """Load a path-based detection input into (bytes, mime_type).

    Prefers the pre-downsampled ``*_small.png`` companion when present, matching
    the behavior we've used since ``_vision_analyze_all``. Returns
    ``(None, None)`` if the path can't be resolved.
    """
    full_path = _resolve_image_path(image_path)
    if not full_path or not os.path.exists(full_path):
        return None, None
    full_path_obj = Path(full_path)
    small_path = full_path_obj.parent / full_path_obj.name.replace(".png", "_small.png")
    use_path = small_path if small_path.exists() else full_path_obj
    with open(use_path, "rb") as f:
        image_bytes = f.read()
    mime_type = "image/jpeg" if str(use_path).lower().endswith((".jpg", ".jpeg")) else "image/png"
    return image_bytes, mime_type


def _detect_self_rule(viewfinder: bool = False) -> str:
    """What SCAN should ignore because it's the player, not the world.

    In first person that's the hands and the vehicle cabin around the camera.
    In any third-person mode the player's whole body is legitimately in frame,
    and without this it gets tagged as an anonymous "figure" the player can
    walk up to and talk to.

    ``viewfinder`` is the PHOTO restage: the plate is first-person even when
    the authored camera is still third-person, so a foreground NPC must not
    be dropped as "the followed character".
    """
    if viewfinder or not game_identity.shows_character():
        return (
            "Do NOT tag the viewer's own hands, gloves, arms, or the vehicle "
            "they're inside (steering wheel, dashboard, gauges, mirrors, seat) "
            "— that's just the player's own body/vehicle, not a point of "
            "interest."
        )
    who = game_identity.display_name()
    return (
        f"The camera is following {who}, the player's own character, seen "
        "from behind or over the shoulder. "
        f"Do NOT tag {who}. Do NOT tag anything they are wearing or "
        "carrying (radio, microphone, camera, bag, holster, clothing) — "
        "that is the player's own kit, not an explorable region. "
        "DO tag other people who are clearly someone else: different "
        "clothes, facing the camera, or standing off to the side. "
        "DO tag the place around them: buildings, vehicles, doors, "
        "fences, landmarks, containers, and world props. "
        "A wide shot of a yard or room is not a close-up of the player — "
        "name the structures and vehicles, not the followed body. "
        f"If the frame is a close-up of {who} with almost no world around "
        "them, still tag every distinct environmental prop, container, "
        "door, or vehicle — never their clothing or carried gear."
    )


def _normalize_detections(parsed: list, max_items: int = DETECT_MAX_ITEMS,
                          *, include_self: bool = False,
                          viewfinder: bool = False) -> list:
    """Turn raw detector output into the wire shape the client consumes.

    Shared by every backend on purpose. Both Gemini and ``local_vision`` hand
    back the same intermediate shape — a list of
    ``{"label", "box_2d": [ymin, xmin, ymax, xmax] on a 0-1000 grid, "kind",
    "speaks"}`` — so all the rules that decide what a player is actually allowed
    to see live here, once, and apply identically no matter who did the looking:
    the underwhelming-label filter, the player's-own-body geometry backstop,
    degenerate-box rejection, dedupe, the speaks/kind classifier and the cap.

    Returns a list of at most ``max_items`` dicts:
        {"label": str, "cx": float, "cy": float, "w": float, "h": float,
         "kind": str, "speaks": bool}
    where cx/cy are the box CENTER and w/h its size, all normalized 0..1
    relative to the frame.
    """
    if not isinstance(parsed, list):
        return []

    objects = []
    seen = set()
    for entry in parsed:
        if not isinstance(entry, dict):
            continue
        label = str(entry.get("label") or "").strip().lower()
        box = entry.get("box_2d") or entry.get("box") or entry.get("bbox")
        if not label or not isinstance(box, (list, tuple)) or len(box) < 4:
            continue
        # Drop underwhelming labels before they cost a max_items slot: the
        # player's own hands/gear/vehicle-interior, never worth a tag.
        if _is_underwhelming_label(label):
            continue
        # SCAN drops the operator so you cannot "move to yourself". The
        # viewfinder leak check must KEEP that label — otherwise a hero
        # copied from the 3P grab is invisible to the retry.
        if (not include_self) and _is_player_self_label(label):
            continue
        try:
            ymin, xmin, ymax, xmax = (float(box[0]), float(box[1]), float(box[2]), float(box[3]))
        except Exception:
            continue
        # Normalize the 0-1000 grid to 0..1, guarding against swapped bounds.
        ymin, ymax = sorted((ymin / 1000.0, ymax / 1000.0))
        xmin, xmax = sorted((xmin / 1000.0, xmax / 1000.0))
        cx = max(0.0, min(1.0, (xmin + xmax) / 2.0))
        cy = max(0.0, min(1.0, (ymin + ymax) / 2.0))
        w = max(0.0, min(1.0, xmax - xmin))
        h = max(0.0, min(1.0, ymax - ymin))
        # Drop degenerate or full-frame boxes (not useful as a tag point).
        if w <= 0.001 or h <= 0.001 or (w >= 0.98 and h >= 0.98):
            continue
        # GEOMETRY BACKSTOP for the camera operator's own body/gear: the held
        # camcorder or an arm juts up from the bottom of the frame in this
        # conceit, and the model sometimes labels it something the word filter
        # misses ("grip", "device", "object").
        #
        # This used to reject anything touching the bottom that was half the
        # frame tall and taller than wide — which is ALSO the exact shape of a
        # person standing in front of you. It was quietly eating the single most
        # interesting thing SCAN can find. Now it has to be a NARROW column
        # hugging the very bottom edge, and it never applies to something the
        # detector already called a living subject: if it says person, it is not
        # the player's own elbow.
        kind_raw = str(entry.get("kind") or "").strip().lower()
        subject = kind_raw in ("person", "character", "creature", "animal")
        if (not subject) and ymax >= 0.97 and h >= 0.62 and w <= 0.22:
            continue
        # Dedupe on label AND rough position: keying on the label alone meant a
        # frame with three people in it — all of them labelled "person" — came
        # back with one tag. Two things twenty percent of the frame apart are two
        # things, whatever they are called.
        key = (label[:24], round(cx * 5), round(cy * 5))
        if key in seen:
            continue
        seen.add(key)
        # Classify whether this thing can be TALKED to. Trust the detector's
        # own call, but backstop it with a label heuristic so the TALK
        # affordance still appears when the field is omitted/undercalled.
        kind, speaks = _classify_speaker(label, entry.get("kind"), entry.get("speaks"))
        objects.append({
            "label": label[:40],
            "cx": round(cx, 4),
            "cy": round(cy, 4),
            "w": round(w, 4),
            "h": round(h, 4),
            "kind": kind,
            "speaks": speaks,
        })

    # Third-person follow-cam: the body filling the lower center is the
    # player, and kit on that body is not an explorable region. Collect
    # first, then strip, so a "person" + "microphone" pair at the front of
    # the response cannot spend the cap before the barn and trucks land.
    # Viewfinder plates are first-person; include_self is the leak check.
    if (
        objects
        and (not include_self)
        and (not viewfinder)
        and game_identity.shows_character()
    ):
        objects = _strip_follow_cam_detections(objects)

    return objects[:max_items]


def _detect_objects(image_path: str = None,
                    max_items: int = DETECT_MAX_ITEMS,
                    image_bytes: bytes = None,
                    mime_type: str = None,
                    scene_prompt: str = "",
                    viewfinder: bool = False,
                    include_self: bool = False) -> list:
    """Realtime object recognition for the live scene.

    Names the prominent, interactable things visible in a frame and boxes them,
    so the standalone UI can float "starfield" tags over the live video where
    each object actually sits. This powers the SCAN tool: the player drags
    across the scene and the world names what it sees.

    Two backends answer this, selected by ``DETECT_BACKEND``: on-device
    MediaPipe fused with the scene prompt (``local_vision``, the default, ~30 ms
    and free) or the original Gemini vision call (~1-3 s, open vocabulary).
    Both return the same wire shape, and both are filtered by the same
    ``_normalize_detections`` rules.

    Callers can pass either ``image_path`` (legacy) or the raw frame directly
    via ``image_bytes`` + ``mime_type`` (preferred from ``api_detect``, which
    already has the frame in memory — this avoids a disk round-trip plus a
    second base64 encode per call). When both are given, bytes win.

    ``scene_prompt`` is an optional description of what is currently on
    screen (``current_observed_vision``). Gemini takes it as a prior for
    sharper labels; the local backend leans on it as the open vocabulary
    COCO cannot supply. It must NOT be the last still's render recipe —
    that names objects from the previous location after the live video
    has drifted.

    Returns a list of dicts (at most ``max_items``) — see
    ``_normalize_detections`` for the exact shape. Returns [] on any failure
    (never raises).
    """
    if not VISION_ENABLED:
        return []

    if image_bytes is None:
        image_bytes, mime_type = _read_detect_image_bytes(image_path)
        if image_bytes is None:
            return []
    if not mime_type:
        mime_type = "image/jpeg"

    use_local = (
        DETECT_BACKEND in ("local", "auto")
        and local_vision is not None
        and local_vision.available()
    )
    if use_local:
        try:
            parsed = local_vision.detect(
                image_bytes,
                mime_type=mime_type,
                max_items=max_items,
                scene_prompt=scene_prompt,
            )
            return _normalize_detections(
                parsed, max_items, include_self=include_self, viewfinder=viewfinder,
            )
        except Exception as e:  # noqa: BLE001 — never raise into a request
            safe_e = str(e).encode("ascii", "replace").decode("ascii")
            log_error(f"[DETECT] local detection failed: {safe_e}")
            if DETECT_BACKEND == "local":
                return []
            # In "auto" a local failure is exactly when Gemini should cover.

    if DETECT_BACKEND == "local":
        # Asked for local, and local can't run. Say so once per call rather than
        # silently degrading to a paid backend the operator opted out of.
        log_error("[DETECT] DETECT_BACKEND=local but local_vision is unavailable "
                  f"({local_vision.status() if local_vision else 'module not imported'})")
        return []

    parsed = _detect_objects_gemini(
        image_bytes, mime_type, max_items, scene_prompt, viewfinder=viewfinder,
    )
    return _normalize_detections(
        parsed, max_items, include_self=include_self, viewfinder=viewfinder,
    )


def _salvage_json_array_objects(text: str) -> list:
    """Recover the COMPLETE objects out of a truncated JSON array.

    A response that hit the output-token ceiling ends mid-object, so
    ``json.loads`` on the whole string fails and every object in it is lost —
    including the eight perfectly good ones that arrived before the cut. That
    reads to the player as an empty world: SCAN on a room full of things
    returns no tags at all, with no error anywhere, because "the call failed"
    and "there is nothing here" are the same empty list.

    Walks the text tracking brace depth (string- and escape-aware, so a brace
    inside a label can't throw off the count) and parses each balanced
    top-level ``{...}`` on its own. Returns [] if nothing is recoverable.
    """
    import json as _json

    objects = []
    depth = 0
    start = None
    in_string = False
    escaped = False
    for i, ch in enumerate(text):
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == "{":
            if depth == 0:
                start = i
            depth += 1
        elif ch == "}":
            if depth > 0:
                depth -= 1
                if depth == 0 and start is not None:
                    try:
                        objects.append(_json.loads(text[start:i + 1]))
                    except Exception:
                        pass
                    start = None
    return objects


def _detect_objects_gemini(image_bytes: bytes,
                           mime_type: str,
                           max_items: int = DETECT_MAX_ITEMS,
                           scene_prompt: str = "",
                           viewfinder: bool = False) -> list:
    """Ask Gemini to name and box what's in the frame.

    Returns the raw parsed entries ({"label", "box_2d", "kind", "speaks"}) for
    ``_normalize_detections`` to filter, or [] on any failure.
    """
    import base64
    import json as _json
    import random as _random
    import time as _time

    if not LLM_ENABLED or not provider_bridge.can_call_gemini_api():
        return []

    try:
        image_b64 = base64.b64encode(image_bytes).decode("utf-8")

        detect_instructions = (
            "Detect the prominent, distinct things a person could look at or "
            "interact with in this image (objects, tools, doors, exits, "
            "figures, creatures, vehicles, hazards). "
            f"Return AT MOST {max_items} of the most salient. "
            "Each item: label (1-3 word noun, lowercase), "
            "box_2d [ymin, xmin, ymax, xmax] as integers 0-1000 "
            "(y top-to-bottom, x left-to-right), "
            "kind (person/character/creature/animal/machine/object), "
            "speaks (true|false). "
            "Set \"speaks\" true ONLY for something that could plausibly hold a "
            "conversation right now: a visible person, humanoid figure, named "
            "character, sentient creature, or a talking machine (radio, phone, "
            "intercom, robot, terminal with a voice). Set it false for inert "
            "objects, scenery, tools, and plain animals that would not speak. "
            # Other people first — not the followed player character. A
            # third-person frame is full of the protagonist, and "always
            # include every person" made SCAN return `person` + `microphone`
            # instead of the barn, trucks, and fence around them.
            "ALWAYS include every OTHER person, figure, body, face or creature "
            "you can see besides the character the camera is following — even "
            "partly visible, even in shadow, even at a distance — list them "
            "FIRST, before any props. If there are several, return each one "
            "separately with its own box. Prefer buildings, vehicles, doors, "
            "fences, landmarks, and world props over the followed body or "
            "anything they are wearing or carrying. "
            "Prefer specific, concrete labels over vague ones. "
            "Skip generic background like 'sky', 'ground', 'wall' unless notable. "
            "Never return an empty list when anything a player could walk to, "
            "pick up, talk to, or look at is visible — barrels, crates, "
            "weapons, doors, lights, railings, vehicles, and other people "
            "all count, even in a close-up, even at the edge of the frame. "
            + _detect_self_rule(viewfinder=viewfinder) +
            " Do NOT tag the camcorder recording this footage. Focus "
            "on what's OUT in the world: structures, terrain, other vehicles, "
            "hazards, creatures, and story props."
        )

        # Optional on-screen prior (a vision description of THIS frame, not
        # the last still's render recipe). Kept short so it can't dominate
        # the pixels — those are the only source of truth for SCAN / MOVE TO.
        prompt_prior = ""
        if scene_prompt:
            prior = scene_prompt.strip().replace("\n", " ")
            if len(prior) > 500:
                prior = prior[:500].rstrip() + "..."
            prompt_prior = (
                "A recent description of what is on screen follows. "
                "Use it only to sharpen labels for things you can actually "
                "see in the pixels — do NOT invent objects named here but "
                "not visible.\n"
                f"ON-SCREEN: {prior}\n\n"
            )

        api_url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent"
        headers = {
            "x-goog-api-key": GEMINI_API_KEY,
            "Content-Type": "application/json",
        }
        payload = {
            "contents": [{
                "parts": [
                    {"inlineData": {"mimeType": mime_type, "data": image_b64}},
                    {"text": prompt_prior + detect_instructions},
                ]
            }],
            "generationConfig": {
                "thinkingConfig": {"thinkingBudget": 0},
                # Detection is a classification task: deterministic runs mean
                # tag labels stay stable frame-to-frame, so the client-side
                # reconciler doesn't get whiplashed by "figure" vs "person"
                # renaming on identical pixels.
                "temperature": 0.0,
                # Budget the ceiling against what we actually asked for. The
                # response is pretty-printed JSON at roughly 45 tokens per
                # object, so a flat 700 could not fit DETECT_MAX_ITEMS (12) and
                # busy interiors — a wall of monitors, a desk of clutter — ran
                # off the end mid-object. The player saw an empty scan of a
                # room full of things.
                "maxOutputTokens": max(700, 64 + max_items * 64),
                "responseMimeType": "application/json",
                "responseSchema": _DETECT_RESPONSE_SCHEMA,
            },
            "safetySettings": [
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
            ],
        }

        # Realtime cadence: /api/detect fires every ~2.5 s, so a 20 s timeout
        # was long enough to stack multiple in-flight calls and completely
        # blackhole the SCAN overlay on a single slow response. Cap it tight
        # and retry once on the errors that are actually worth retrying
        # (429 rate-limit, 5xx transient) with jittered backoff.
        response = None
        last_err = None
        for attempt in range(2):
            try:
                response = _GEMINI_HTTP_SESSION.post(
                    api_url, headers=headers, json=payload, timeout=8
                )
                if response.status_code == 429 or 500 <= response.status_code < 600:
                    last_err = requests.exceptions.HTTPError(
                        f"{response.status_code} {response.reason}", response=response
                    )
                    if attempt == 0:
                        _time.sleep(0.35 + _random.random() * 0.35)
                        continue
                    raise last_err
                response.raise_for_status()
                last_err = None
                break
            except (requests.exceptions.Timeout,
                    requests.exceptions.ConnectionError) as e:
                last_err = e
                if attempt == 0:
                    _time.sleep(0.35 + _random.random() * 0.35)
                    continue
                raise
        if last_err is not None and response is None:
            raise last_err
        result = response.json()

        candidates = result.get("candidates") or []
        if not candidates:
            return []
        parts = (candidates[0].get("content") or {}).get("parts") or []
        full_text = "".join(p.get("text", "") for p in parts).strip()
        if not full_text:
            return []

        # With responseSchema Gemini returns strict JSON, so a single
        # json.loads normally suffices. It does NOT when the response hits the
        # output-token ceiling: the array ends mid-object and parsing the whole
        # string throws, which used to discard every object in it. Salvage the
        # complete ones instead — a scan that finds eight of twelve things is
        # the feature working, whereas returning [] renders a populated room as
        # empty with nothing logged the player can see.
        try:
            parsed = _json.loads(full_text)
        except Exception as parse_err:
            salvaged = _salvage_json_array_objects(full_text)
            finish = (candidates[0].get("finishReason") or "?")
            if salvaged:
                log_error(f"[DETECT] truncated structured response (finishReason={finish}); "
                          f"salvaged {len(salvaged)} object(s)")
                return salvaged
            log_error(f"[DETECT] malformed structured response (finishReason={finish}): "
                      f"{parse_err} :: {full_text[:200]}")
            return []

        if not isinstance(parsed, list):
            return []
        return parsed
    except requests.exceptions.HTTPError as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        log_error(f"[DETECT] Gemini API HTTP error: {safe_e}")
        return []
    except Exception as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        log_error(f"[DETECT] Failed to detect objects: {safe_e}")
        return []


# ─────────────────────────────────────────────────────────────────────────────
# Realtime danger perception (for the peripheral-vignette / health system).
#
# One vision call, one answer: "is what's on screen dangerous, right now?"
# Fired ~1x/second by the client against the live world-model frame. Kept
# deliberately narrow — three ordinal levels + a short human-readable reason
# + optional bbox of the primary threat — so the client's state machine has
# a single, predictable signal to drive the red-vignette pulse and health
# drain. Nothing here mutates world state; this is a read-only perception
# probe, like /api/detect.
# ─────────────────────────────────────────────────────────────────────────────

_DANGER_RESPONSE_SCHEMA = {
    "type": "OBJECT",
    "properties": {
        # 0 = safe, 1 = threatened (hostile in frame, not committing),
        # 2 = attacking (aimed/lunging at camera, or camera is IN a hazard).
        # NOTE: the Gemini structured-output API requires enum values to be
        # STRINGS even for an INTEGER field — passing raw ints (0,1,2) makes
        # generateContent reject the whole request with 400 INVALID_ARGUMENT
        # ("Invalid value ... (TYPE_STRING)"), which silently broke the entire
        # danger-vignette loop (every ~1 Hz call 400'd). The model still
        # returns an integer; the caller also clamps to 0..2 defensively.
        "level": {"type": "INTEGER", "enum": ["0", "1", "2"]},
        # A terse, human-readable reason (<=8 words). Shown in the client
        # log for tuning and debugging; never rendered to the player.
        "reason": {"type": "STRING"},
        # Optional bbox of the primary threat, so the client can bias the
        # vignette gradient toward the edge that thing is coming from.
        # Same 0-1000 int format as _detect_objects for consistency.
        "threat_box": {"type": "ARRAY", "items": {"type": "NUMBER"}},
    },
    "required": ["level"],
}


def _perceive_danger(image_bytes: bytes = None,
                     mime_type: str = None,
                     scene_prompt: str = "") -> dict:
    """Grade the live frame's threat level for the peripheral-vignette loop.

    Returns a dict:
        {"level": 0|1|2,
         "reason": str,
         "direction": "left"|"right"|"top"|"bottom"|"center"|None,
         "threat_cx": float,   # 0..1, only when a threat_box is present
         "threat_cy": float}

    ``level``:
      • 0 — safe. Nothing hostile / actively harmful in frame.
      • 1 — threatened. Hostile entity present and oriented toward camera,
            OR player is adjacent to a live environmental hazard.
      • 2 — attacking. Hostile weapon/limb pointed at or striking camera,
            OR camera is physically inside a hazard (in the flames, on the
            collapsing floor, engulfed by the toxic cloud, etc).

    Returns level=0 with reason="" on any failure — the danger loop should
    NEVER be able to hurt the player because a vision call went sideways.
    """
    import base64
    import json as _json
    import random as _random
    import time as _time

    safe = {"level": 0, "reason": "", "direction": None,
            "threat_cx": None, "threat_cy": None}

    if not LLM_ENABLED or not VISION_ENABLED or not provider_bridge.can_call_gemini_api():
        return safe
    if not image_bytes:
        return safe
    if not mime_type:
        mime_type = "image/jpeg"

    try:
        image_b64 = base64.b64encode(image_bytes).decode("utf-8")

        # Tuned rubric. Three levels, one paragraph each — the goal is that
        # the SAME frame gets the SAME level on re-runs (client state machine
        # stability), while ALSO being sensitive enough that a typical
        # exploration scene actually surfaces threats. Prior version required
        # a hostile to be aimed AT the camera to escalate, which made the
        # loop effectively inert in a world-model exploration game (most
        # frames are rooms/corridors, not gunfights). We now escalate on
        # anything a person would reasonably flinch at: visible weapons,
        # aggressive creatures, active hazards in-frame, high edges,
        # aggressive approach — even when not committed AT camera yet.
        # Who the danger is being graded FOR changes with the camera: in first
        # person it's whoever is behind the lens, in third person it's the
        # character standing in the middle of the frame.
        if game_identity.shows_character():
            _danger_subject = (
                f"survival exploration game. Look at this single frame and grade its "
                f"immediate danger to {game_identity.display_name()}, the player's own "
                f"character visible in the shot"
            )
        else:
            _danger_subject = (
                "first-person survival exploration game. Look at this single frame from "
                "the player's point-of-view camera and grade its immediate danger to the "
                "person BEHIND the camera"
            )
        danger_instructions = (
            f"You are a threat detector for a {_danger_subject}"
            ". Return ONE JSON object with fields: level (integer 0, 1, "
            "or 2), reason (<= 8 words, lowercase), and optionally threat_box "
            "[ymin, xmin, ymax, xmax] integers 0-1000 (y top-to-bottom, "
            "x left-to-right) around the single most dangerous thing in view.\n\n"
            "LEVEL 0 — SAFE: nothing that could plausibly injure the player is "
            "in frame. Calm empty rooms, benign scenery, cluttered but inert "
            "spaces, distant crowds of non-hostile figures, safe outdoor areas. "
            "Choose 0 only when the scene is clearly benign.\n\n"
            "LEVEL 1 — THREATENED: something in the frame that a reasonable "
            "person would want to move away from. Examples that qualify:\n"
            "  • A visible weapon carried by anyone in view (gun, blade, "
            "improvised weapon), whether or not it is aimed at camera.\n"
            "  • A hostile-looking creature, monster, or aggressive animal "
            "anywhere in frame, whether or not it faces camera.\n"
            "  • A human figure with visibly hostile posture (raised fist, "
            "advancing on camera, glaring / staring down camera).\n"
            "  • An active environmental hazard visible in frame: open flame, "
            "large fire, exposed live wiring / sparks, deep water, high drop / "
            "cliff edge, unstable / collapsing structure, poisonous / toxic "
            "atmosphere hints (smoke, gas, dense fog), extreme heights, "
            "radiation / warning signs indicating current danger.\n"
            "  • Blood, gore, or fresh signs of violence in the immediate area "
            "(indicates the space is unsafe).\n"
            "  • Camera is in a very unsafe posture: standing on a narrow "
            "ledge, looking down a shaft, near a large predator, at the mouth "
            "of a burning corridor.\n"
            "You have a beat to react — the threat is present but not "
            "yet committed to harming you.\n\n"
            "LEVEL 2 — ATTACKING: damage is imminent or already happening. "
            "Examples that qualify:\n"
            "  • A weapon, limb, or projectile committed toward the camera "
            "(muzzle flash, swinging blade close to lens, incoming projectile, "
            "hands reaching for the lens).\n"
            "  • A creature or hostile figure lunging / charging directly at "
            "the camera, filling a significant portion of the frame.\n"
            "  • Camera is PHYSICALLY INSIDE a hazard: engulfed in flames, "
            "submerged in toxic fluid, buried under debris, falling, being "
            "crushed, surrounded by fire on multiple sides.\n"
            "  • The frame itself is visibly obscured by the attack: blood on "
            "the lens, cracked visor, smoke choking the view.\n\n"
            "RULES:\n"
            "• Grade the FRAME, not the story. Don't infer off-screen dangers.\n"
            "• Any visible weapon or hostile creature is at least LEVEL 1, even "
            "if the camera isn't currently being targeted. In an exploration "
            "game, seeing a threat is itself dangerous.\n"
            "• Dark / low-visibility scenes are NOT automatically dangerous. "
            "Grade what you can actually see; if the scene is dark but the "
            "visible content is benign, choose 0.\n"
            "• Prefer LEVEL 1 over LEVEL 0 whenever there is a plausible "
            "threat in frame — the game's danger vignette should be a live "
            "signal, not a rarely-triggered alarm."
        )

        prompt_prior = ""
        if scene_prompt:
            prior = scene_prompt.strip().replace("\n", " ")
            if len(prior) > 400:
                prior = prior[:400].rstrip() + "..."
            prompt_prior = (
                "This frame was rendered from the following scene prompt. "
                "Use it as a hint for what the world contains, but grade "
                "ONLY what you can actually see in the pixels.\n"
                f"SCENE PROMPT: {prior}\n\n"
            )

        api_url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent"
        headers = {
            "x-goog-api-key": GEMINI_API_KEY,
            "Content-Type": "application/json",
        }
        payload = {
            "contents": [{
                "parts": [
                    {"inlineData": {"mimeType": mime_type, "data": image_b64}},
                    {"text": prompt_prior + danger_instructions},
                ]
            }],
            "generationConfig": {
                "thinkingConfig": {"thinkingBudget": 0},
                # Deterministic: same frame → same level. Predictability
                # matters more here than variety.
                "temperature": 0.0,
                "maxOutputTokens": 120,
                "responseMimeType": "application/json",
                "responseSchema": _DANGER_RESPONSE_SCHEMA,
            },
            "safetySettings": [
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
            ],
        }

        # Same tight-timeout + one-retry pattern as _detect_objects. The
        # danger loop is running at ~1 Hz, so a stalled call must NOT stack.
        response = None
        last_err = None
        for attempt in range(2):
            try:
                response = _GEMINI_HTTP_SESSION.post(
                    api_url, headers=headers, json=payload, timeout=6
                )
                if response.status_code == 429 or 500 <= response.status_code < 600:
                    last_err = requests.exceptions.HTTPError(
                        f"{response.status_code} {response.reason}", response=response
                    )
                    if attempt == 0:
                        _time.sleep(0.25 + _random.random() * 0.25)
                        continue
                    raise last_err
                response.raise_for_status()
                last_err = None
                break
            except (requests.exceptions.Timeout,
                    requests.exceptions.ConnectionError) as e:
                last_err = e
                if attempt == 0:
                    _time.sleep(0.25 + _random.random() * 0.25)
                    continue
                raise
        if last_err is not None and response is None:
            raise last_err
        result = response.json()

        candidates = result.get("candidates") or []
        if not candidates:
            return safe
        parts = (candidates[0].get("content") or {}).get("parts") or []
        full_text = "".join(p.get("text", "") for p in parts).strip()
        if not full_text:
            return safe

        try:
            parsed = _json.loads(full_text)
        except Exception as parse_err:
            log_error(f"[DANGER] malformed response: {parse_err} :: {full_text[:200]}")
            return safe
        if not isinstance(parsed, dict):
            return safe

        try:
            level = int(parsed.get("level", 0))
        except Exception:
            level = 0
        if level not in (0, 1, 2):
            level = max(0, min(2, level))
        reason = str(parsed.get("reason") or "").strip().lower()
        if len(reason) > 80:
            reason = reason[:80]

        # Compute a direction hint from the threat bbox (if present) so the
        # client can bias the vignette gradient toward the edge the danger
        # is coming from. Empty / degenerate boxes → direction None → the
        # vignette stays symmetric.
        direction = None
        threat_cx = None
        threat_cy = None
        box = parsed.get("threat_box")
        if isinstance(box, (list, tuple)) and len(box) >= 4:
            try:
                ymin, xmin, ymax, xmax = (float(box[0]), float(box[1]),
                                          float(box[2]), float(box[3]))
                ymin, ymax = sorted((ymin / 1000.0, ymax / 1000.0))
                xmin, xmax = sorted((xmin / 1000.0, xmax / 1000.0))
                cx = max(0.0, min(1.0, (xmin + xmax) / 2.0))
                cy = max(0.0, min(1.0, (ymin + ymax) / 2.0))
                w = max(0.0, min(1.0, xmax - xmin))
                h = max(0.0, min(1.0, ymax - ymin))
                if w > 0.001 and h > 0.001 and not (w >= 0.98 and h >= 0.98):
                    threat_cx = round(cx, 3)
                    threat_cy = round(cy, 3)
                    # Cardinal direction from the box center, with a dead
                    # zone in the middle so a threat dead-center reads as
                    # "center" (symmetric vignette) rather than randomly
                    # snapping to a side.
                    dx = cx - 0.5
                    dy = cy - 0.5
                    if abs(dx) < 0.15 and abs(dy) < 0.15:
                        direction = "center"
                    elif abs(dx) >= abs(dy):
                        direction = "right" if dx > 0 else "left"
                    else:
                        direction = "bottom" if dy > 0 else "top"
            except Exception:
                direction = None
                threat_cx = None
                threat_cy = None

        return {
            "level": level,
            "reason": reason,
            "direction": direction,
            "threat_cx": threat_cx,
            "threat_cy": threat_cy,
        }
    except requests.exceptions.HTTPError as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        log_error(f"[DANGER] Gemini API HTTP error: {safe_e}")
        return safe
    except Exception as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        log_error(f"[DANGER] Failed: {safe_e}")
        return safe


def _appraise_photo(image_path: str, max_items: int = 6) -> dict:
    """Appraise a photograph the player captured — the reward loop's "feedback".

    Where ``_detect_objects`` locates things for live SCAN tags, this reads a
    single captured crop like an evidence analyst: it names the notable things
    in frame, rates how *interesting/telling* each one is, and gives a terse
    reason it matters — plus a one-line caption and an overall mood word. The
    standalone UI turns this into a "receipt" that prints item-by-item, each
    line scoring points toward the run's EVIDENCE total.

    Returns a dict (never raises):
        {
          "items": [{"label": str, "interest": 1..5, "note": "<=6 words"}],
          "caption": str,   # one evocative line about the shot
          "mood": str,      # single lowercase word, may be ""
        }
    On any failure / disabled vision it returns {"items": [], "caption": "",
    "mood": ""} so the client can still render a graceful "undeveloped" receipt.
    """
    import base64
    import json as _json
    import re as _re
    import requests

    empty = {"items": [], "caption": "", "mood": ""}
    if not LLM_ENABLED or not VISION_ENABLED or not provider_bridge.can_call_gemini_api():
        return empty

    try:
        full_path = _resolve_image_path(image_path)
        if not full_path or not os.path.exists(full_path):
            return empty

        from pathlib import Path
        full_path_obj = Path(full_path)
        small_path = full_path_obj.parent / full_path_obj.name.replace(".png", "_small.png")
        use_path = small_path if small_path.exists() else full_path_obj

        with open(use_path, "rb") as f:
            image_bytes = f.read()
        image_b64 = base64.b64encode(image_bytes).decode("utf-8")

        mime_type = _sniff_image_mime(use_path)

        appraise_prompt = (
            "You are an evidence analyst reviewing a single photograph a field "
            "investigator just captured. Identify the notable, concrete things "
            "in the frame (objects, tools, figures, creatures, hazards, exits, "
            "clues). For each, rate how interesting/telling it is and say WHY in "
            "a few words. "
            f"Return AT MOST {max_items} items, most interesting first. "
            "Respond with ONLY a JSON object, no prose, no code fences:\n"
            '{"items": [{"label": "<1-3 word noun, lowercase>", '
            '"interest": <integer 1-5>, "note": "<<=6 words on why it matters>"}], '
            '"caption": "<one evocative sentence about the shot>", '
            '"mood": "<single lowercase word for the vibe>"}. '
            "interest: 1 = mundane, 5 = striking/rare/story-critical. "
            "Prefer specific labels over vague ones. Skip generic background "
            "(sky, ground, wall) unless genuinely notable."
        )

        api_url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent"
        headers = {
            "x-goog-api-key": GEMINI_API_KEY,
            "Content-Type": "application/json",
        }
        payload = {
            "contents": [{
                "parts": [
                    {"inlineData": {"mimeType": mime_type, "data": image_b64}},
                    {"text": appraise_prompt},
                ]
            }],
            "generationConfig": {
                "thinkingConfig": {"thinkingBudget": 0},
                "temperature": 0.5,
                "maxOutputTokens": 700,
                "responseMimeType": "application/json",
            },
            "safetySettings": [
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
            ],
        }

        response = requests.post(api_url, headers=headers, json=payload, timeout=20)
        response.raise_for_status()
        result = response.json()

        candidates = result.get("candidates") or []
        if not candidates:
            return empty
        parts = (candidates[0].get("content") or {}).get("parts") or []
        full_text = "".join(p.get("text", "") for p in parts).strip()
        if not full_text:
            return empty

        cleaned = _re.sub(r"^```(?:json)?|```$", "", full_text.strip(), flags=_re.MULTILINE).strip()
        try:
            parsed = _json.loads(cleaned)
        except Exception:
            m = _re.search(r"\{.*\}", cleaned, _re.DOTALL)
            if not m:
                return empty
            try:
                parsed = _json.loads(m.group(0))
            except Exception:
                return empty

        if not isinstance(parsed, dict):
            return empty

        raw_items = parsed.get("items")
        if not isinstance(raw_items, list):
            raw_items = []
        items = []
        seen = set()
        for entry in raw_items:
            if not isinstance(entry, dict):
                continue
            label = str(entry.get("label") or "").strip().lower()
            if not label:
                continue
            key = label[:24]
            if key in seen:
                continue
            seen.add(key)
            try:
                interest = int(round(float(entry.get("interest", 2))))
            except Exception:
                interest = 2
            interest = max(1, min(5, interest))
            note = str(entry.get("note") or "").strip()[:80]
            items.append({"label": label[:40], "interest": interest, "note": note})
            if len(items) >= max_items:
                break

        caption = str(parsed.get("caption") or "").strip()[:160]
        mood = str(parsed.get("mood") or "").strip().lower()[:24]
        return {"items": items, "caption": caption, "mood": mood}
    except requests.exceptions.HTTPError as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        print(f"[APPRAISE ERROR] Gemini API HTTP error: {safe_e}")
        return empty
    except Exception as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        print(f"[APPRAISE ERROR] Failed to appraise photo: {safe_e}")
        return empty

def _fallback_directive(st: dict) -> dict:
    """A deterministic "current lead" derived purely from world state — no LLM.

    Used both when the model is unavailable and as the always-safe default the
    generative path upgrades. Keeps the objectives tracker's LEAD reading well
    even with no network / no key.
    """
    phase = str((st or {}).get("current_phase", "normal") or "normal").lower()
    # DURABLE, CATEGORY leads only. The world regenerates each scene, so a lead
    # naming a specific seen element ("Document the blue container") points at
    # something that has already vanished and reads as impossible. Instead point
    # at a recurring KIND of evidence the world keeps producing, so any matching
    # subject the player photographs satisfies it — always achievable.
    templates = {
        "normal": ("Document A Specimen",
                   "Find biological evidence of what they did here and get it on film."),
        "escalating": ("Photograph The Machinery",
                       "The facility's equipment is the story — capture it before it fails."),
        "critical": ("Capture A Victim",
                     "It's turning deadly — document the aftermath and stay alive."),
    }
    lead, detail = templates.get(phase, templates["normal"])
    return {"lead": lead, "detail": detail, "generated": False}


def generate_directive(session_id: str = "default") -> dict:
    """Generate the objectives tracker's evolving "current lead" — a short,
    in-world investigative directive grounded in the live world state.

    This is the GENERATIVE spine of the objectives system: it reads the
    evolving world (premise, recent beats, phase, discovered elements) and asks
    the model for the player's most pressing current goal, phrased like a AAA
    objective line. It NEVER raises and always returns a usable directive —
    degrading to :func:`_fallback_directive` when the model is unavailable.

    Returns: {"lead": str, "detail": str, "generated": bool}
    """
    import json as _json
    import re as _re
    import requests

    # Always read the requested session from disk (not the shared `state`
    # global) so a concurrent different-session request can't make this
    # objective describe the wrong player's world.
    try:
        st = _load_state(session_id)
    except Exception:
        st = state or {}

    fb = _fallback_directive(st or {})
    if not LLM_ENABLED or not provider_bridge.can_call_gemini_api():
        return fb

    try:
        world_prompt = str((st or {}).get("world_prompt", "") or "")[:900]
        recent = (st or {}).get("recent_events") or []
        recent_txt = " | ".join(str(r) for r in recent[-3:])[:500]
        seen = (st or {}).get("seen_elements") or []
        seen_txt = ", ".join(str(s) for s in seen[-8:])[:300]
        phase = str((st or {}).get("current_phase", "normal") or "normal")
        threat = (st or {}).get("threat_level", 0)
        tod = str((st or {}).get("time_of_day", "") or "")[:80]
        # The run's destination. The lead used to be composed from the world
        # prose and the phase alone, so the HUD could tell the player to
        # photograph a specimen while the title card had just told them the
        # run was about a door at the end of the hall — two goal systems that
        # had never met.
        goal = run_goal(st)
        if goal and (st or {}).get("goal_reached_turn"):
            goal_line = (f"THE RUN'S DESTINATION: {goal} — REACHED. The lead is "
                         f"now what to document there, or on the way out.\n")
        elif goal:
            goal_line = (f"THE RUN'S DESTINATION: {goal} — the lead should read as "
                         f"a step toward it, or what is worth documenting on the way.\n")
        else:
            goal_line = ""

        prompt = game_identity.apply(
            "You are the objective director for an investigative "
            "photography game. The WIN CONDITION is documenting distinct evidence "
            "to build a case file. Your job is to give the player a DURABLE "
            "current lead that stays achievable.\n\n", "narrative"
        ) + (
            "CRITICAL RULE: the world REGENERATES every scene, so a specific "
            "one-off prop ('the blue container', 'that severed hand') VANISHES "
            "and can never be found again — an objective naming one feels broken "
            "and impossible. So the LEAD must name a recurring KIND / CATEGORY of "
            "evidence the world keeps producing (a specimen, a victim/body, the "
            "machinery, a containment vessel, a mutation/creature, a document or "
            "sign, a bloodstain/aftermath), NOT one unique object. Any matching "
            "thing the player photographs satisfies it, so it's always doable.\n\n"
            "Choose the category that best fits the CURRENT world + phase and "
            "reads as the most compelling next thing to hunt for and shoot.\n\n"
            f"PREMISE / WORLD: {world_prompt}\n"
            f"{goal_line}"
            f"RECENT BEATS: {recent_txt}\n"
            f"KNOWN ELEMENTS: {seen_txt}\n"
            f"PHASE: {phase} (threat {threat}); TIME: {tod}\n\n"
            "Phrase the LEAD as a durable directive to document that category, "
            "e.g. 'Document A Specimen', 'Photograph The Machinery', 'Capture A "
            "Victim', 'Document A Mutation'. Use the article 'a/the' — never a "
            "unique proper-noun object. The DETAIL is one grounded sentence of "
            "why it matters. Do NOT tell them to 'wait' or 'observe'.\n\n"
            "Respond with ONLY a JSON object, no prose, no code fences:\n"
            '{"lead": "<durable imperative, 2-6 words, Title Case, no period>", '
            '"detail": "<one grounded sentence of context, <= 16 words>"}'
        )

        api_url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent"
        headers = {"x-goog-api-key": GEMINI_API_KEY, "Content-Type": "application/json"}
        payload = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {
                "thinkingConfig": {"thinkingBudget": 0},
                "temperature": 0.8,
                "maxOutputTokens": 200,
                "responseMimeType": "application/json",
            },
            "safetySettings": [
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
            ],
        }
        response = requests.post(api_url, headers=headers, json=payload, timeout=15)
        response.raise_for_status()
        result = response.json()
        candidates = result.get("candidates") or []
        if not candidates:
            return fb
        parts = (candidates[0].get("content") or {}).get("parts") or []
        full_text = "".join(p.get("text", "") for p in parts).strip()
        if not full_text:
            return fb
        cleaned = _re.sub(r"^```(?:json)?|```$", "", full_text.strip(), flags=_re.MULTILINE).strip()
        try:
            parsed = _json.loads(cleaned)
        except Exception:
            m = _re.search(r"\{.*\}", cleaned, _re.DOTALL)
            parsed = _json.loads(m.group(0)) if m else None
        if not isinstance(parsed, dict):
            return fb
        lead = str(parsed.get("lead") or "").strip().strip('".').strip()[:48]
        detail = str(parsed.get("detail") or "").strip()[:160]
        if not lead:
            return fb
        return {"lead": lead, "detail": detail, "generated": True}
    except requests.exceptions.HTTPError as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        print(f"[DIRECTIVE ERROR] Gemini API HTTP error: {safe_e}")
        return fb
    except Exception as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        print(f"[DIRECTIVE ERROR] Failed to generate directive: {safe_e}")
        return fb


# ───────── world report (with vision‑desc) ─────────────────────────────────
def _world_report() -> str:
    context = state.get("world_prompt", "")
    last_choice = state.get("last_choice", "")

    # `field_notes_format` has no {context}/{last_choice} placeholders by
    # default, and str.format() silently swallows unused kwargs — so this used
    # to pass the world state in and have it thrown away, leaving the model
    # writing field notes about nothing. Substitute when the author HAS added
    # the placeholders, otherwise append the context explicitly.
    template = PROMPTS.get("field_notes_format", "") or ""
    if "{context}" in template or "{last_choice}" in template:
        base = template.format(context=context, last_choice=last_choice)
    else:
        base = (
            f"{template}\n\n"
            f"WORLD STATE: {context}\n"
            f"LAST ACTION: {last_choice or '(none yet)'}"
        )

    # Vision model disabled: do not use _vision_describe or add image description
    # Alternate tone based on phase and beat
    phase = state.get("current_phase", "normal")
    if phase == "critical":
        tone = "suspenseful"
    elif phase == "escalating":
        tone = "mysterious"
    else:
        tone = "reflective"

    # This used to read PROMPTS['situation_report_prompt'], a key that has never
    # existed in simulation_prompts.json — so every call raised KeyError and took
    # begin_tick() (and therefore autotest.py) down with it. The bulletin prompt
    # it meant is `situation_summary_instructions`; read it defensively so a
    # missing prompt can degrade instead of killing a turn.
    bulletin = PROMPTS.get(
        "situation_summary_instructions",
        "Describe what is happening NOW in 1-2 sentences.",
    )
    prompt = game_identity.apply(f"{base}\n\n[{tone.upper()} TONE] {bulletin}", "narrative")
    # Don't use lore - this is just a summary of current state
    return _ask(prompt, tokens=60, use_lore=False)

# ───────── dispatch helpers ────────────────────────────────────────────────
# Per-session cache of the last "Visual tone" gloss (see
# summarize_world_prompt_for_image). Kept in-memory only — never persisted —
# because it is re-derived from world_prompt on every hard transition or new
# session anyway, and persisting it risks a stale tone surviving a save/load
# from an older code path that never wrote this key.
_VISUAL_TONE_CACHE: dict = {}


def summarize_world_prompt_for_image(world_prompt: str, session_id: str = 'default',
                                      hard_transition: bool = False, frame_idx: int = 0,
                                      relight: bool = False) -> str:
    """Boil the world context down to an aesthetic/tone gloss appended to
    EVERY image prompt as "World flavor" — never a second description of
    the scene or the character.

    `world_prompt` is frequently just the static character bio ("WHO: Jason
    Fleece... equipped with a heavy-duty 1993 VHS camcorder...") with no
    scene or pose in it at all. The old instruction ("vivid, scene-specific
    sentences... focus on the current visual environment") asked this call
    to describe a scene and a pose anyway — with nothing in the source to
    draw one from, at temp=1.0 it INVENTED one fresh every turn ("crouches
    on a concrete floor, clutching a circuit board", "hunches in the
    flickering light"). That invented pose is a second, self-contained
    character description sitting in the same prompt as the turn's real
    `visual_scene` ("the render exactly this scene" text), and the image
    model sometimes tried to satisfy both — which is how a second, often
    front-facing figure ended up standing in frames that `visual_scene`
    never asked for. Restricting this to tone/palette/era and explicitly
    banning pose or action removes the thing being hallucinated, rather
    than hoping the image model resolves the contradiction correctly.

    CACHING: this used to call the LLM fresh every single turn, independent
    of every other turn. Because `world_prompt` is the dramatic beat text
    ("OVERWHELMING CHAOS! Immediate, decisive action is paramount...",
    "the red biome is dangerously close..."), a fresh call reliably invented
    a NEW lighting/mood gloss each time ("flickering sodium-vapor
    highlights" one turn, "high-contrast crimson strobe lighting" the next,
    "oppressive desert twilight" after that) — three different ambient
    lighting descriptions across three consecutive frames of the SAME
    unbroken chase, even though every image prompt already also says
    "Maintain the same lighting... as the previous image". The two
    instructions fought each other and the freshly-generated one, being more
    specific, often won, which is what produced day-for-night flicker across
    a run the state machine's own `time_of_day` string never changed. Now
    this is only recomputed on a hard location transition (where the light
    genuinely may be different) or the first frame of a session; every other
    turn reuses the cached gloss so the tone truly stays fixed, matching the
    continuity instruction it sits next to instead of undercutting it.

    `relight` is the exception the anchoring needs. A hard transition re-asks
    but is deliberately handed the old gloss as "PREVIOUS TONE (keep matching
    this)", because a doorway does not change the sun. A change of REGION does
    (see is_region_change), and the anchor then becomes the bug: a capture had
    the gloss for an Antarctic ice sheet come back as "golden hour, rust, red
    dust" because the desert it was anchored to was the more concrete of the two
    texts in front of the model. This drops the anchor for that one call.
    """
    cached = _VISUAL_TONE_CACHE.get(session_id)
    if cached and not hard_transition and frame_idx > 1:
        return cached
    # `cached` stays intact below as the failure fallback — a transient API error
    # must still leave the run with a tone rather than none. What a relight drops
    # is the ANCHOR: the continuity paragraph and the PREVIOUS TONE line.
    anchor = "" if relight else (cached or "")
    if relight and cached:
        print(f"[VISUAL TONE] region change — letting go of {cached[:48]!r} "
              f"rather than anchoring the new place to it", flush=True)
    continuity = (
        "This is one still moment of a single, continuous scene. Unless "
        "the world context explicitly says the time of day changed, the "
        "weather broke, or the player moved indoors/outdoors, name the "
        "SAME base lighting condition and palette as the previous tone "
        "below — do not invent a new light source or swap day for night.\n"
    ) if not relight else (
        "The player has just travelled to a DIFFERENT PLACE. Name the tone of "
        "the place described below and nothing else. Do not carry over a "
        "palette, a light or a weather condition from anywhere else — the "
        "previous location's are not available to you and would be wrong. Keep "
        "only the era and the film stock.\n"
    )
    prompt = (
        "In ONE short phrase, name the visual TONE of the following world "
        "context for an image generation model — grain/film stock, era, "
        "color palette, ambient mood. Example: 'muted 1993 desert "
        "thriller, amber and rust tones, oppressive haze.'\n"
        "Do NOT describe a character, a pose, a posture, an action, or "
        "anything happening — that scene is described elsewhere in the "
        "prompt already, in full, and adding another one here is exactly "
        "what this call must never do. If the text below names no scene "
        "or action, do not invent one; describe only its texture/tone.\n"
        "Omit backstory, equipment lists, and names entirely. Never mention "
        "a camcorder, VHS, videotape, analog recording, or any recording "
        "device — those are equipment, not tone, and must not leak into "
        "the aesthetic gloss.\n"
        + continuity
        + "CRITICAL: Avoid using graphic or violent words like 'blood', 'gore', 'mutilated', 'viscera', etc. "
        "Use clinical or atmospheric equivalents if needed.\n\n"
        + (f"PREVIOUS TONE (keep matching this unless the context below overrides it): {anchor}\n\n" if anchor else "")
        + "WORLD CONTEXT: " + world_prompt
    )
    # Don't use lore - just summarizing existing text. Low temperature on
    # purpose: this is a factual gloss, not creative writing, and the
    # improvisation a high temperature buys is exactly the hallucination
    # this function used to produce.
    tone = _ask(prompt, model="gemini", temp=0.3, tokens=32, use_lore=False)
    # A failed _ask returns a sentinel STRING, not an empty one — "Signal
    # interrupted due to API error...". The narrative path has caught those
    # since _is_failure_dispatch was written; this one never did, so the
    # sentence went into the image prompt as the world's visual tone and, worse,
    # into _VISUAL_TONE_CACHE — where it then described every remaining frame of
    # the session. One transient 403 was enough to render the rest of a run
    # "in the style of" an error message. Keep the previous gloss instead; a
    # slightly stale tone is the whole point of the cache.
    if _is_failure_dispatch(tone):
        if tone:
            print(f"[VISUAL TONE] ask failed ({str(tone)[:60]!r}) — keeping the "
                  f"last good tone rather than describing the error", flush=True)
        return cached or ""
    _VISUAL_TONE_CACHE[session_id] = tone
    return tone


def _generate_caption(dispatch: str, mode: str, is_first_frame: bool = False) -> str:
    # Simplified caption generation - not used in StoryGen version
    return f"{dispatch} ({mode})"

# ───────── imaging helpers ─────────────────────────────────────────────────
def _slug(s: str) -> str:
    # Ensure get_next_feed_item_id is available if slug is empty.
    # This is a minor case, get_next_feed_item_id has its own lock.
    return "".join(c for c in s.lower().replace(" ","_") if c.isalnum() or c=="_")[:48] or f"auto_slug_{get_next_feed_item_id()}"

def _save_img(b64: str, caption: str, session_id: str = 'default') -> str:
    """Save image to session-specific directory"""
    img_dir = _get_image_dir(session_id)
    path = img_dir / f"{hash(caption) & 0xFFFFFFFF}_{_slug(caption)}.png"
    path.write_bytes(base64.b64decode(b64))
    # Return relative path from session root
    return f"images/{path.name}"

# _vision_is_inside removed - was expensive and never used in StoryGen
# _generate_burn_in removed - was never called and caused timecode overlays

# Enclosed / distinct spaces a player can move INTO or THROUGH. Crossing into
# one of these from a different environment is a genuine scene change (a "hard
# cut") — a fresh composition — rather than a small step within the current view.
_TRANSITION_SPACE_NOUNS = [
    'shaft', 'vent', 'ventilation', 'duct', 'ductwork', 'tunnel', 'crawlspace',
    'crawl space', 'conduit', 'hatch', 'opening', 'corridor', 'hallway',
    'stairwell', 'stairway', 'staircase', 'chamber', 'room', 'building',
    'facility', 'structure', 'doorway', 'gateway', 'gate', 'threshold',
    'archway', 'entrance', 'gap', 'hole', 'cave', 'cavern', 'basement',
    'cellar', 'elevator', 'airlock', 'passage', 'passageway', 'grate', 'grating',
    'manhole', 'sewer', 'pit', 'trench', 'alcove', 'vault', 'den', 'nest',
    'window', 'maw', 'pipe', 'pipeline', 'lab', 'laboratory', 'silo', 'bunker',
    'compound', 'courtyard', 'clearing', 'ravine', 'culvert', 'shed', 'garage',
    'warehouse', 'reactor', 'core', 'atrium', 'lobby', 'vestibule', 'antechamber',
]

# Verbs that denote the player physically relocating their whole body/camera INTO
# or THROUGH a space (as opposed to observational verbs like "peer/look/reach
# into", which must NOT trigger a scene change).
_TRANSITION_MOVE_VERBS = [
    'enter', 'climb', 'clamber', 'crawl', 'scramble', 'squeeze', 'wriggle',
    'duck', 'drop', 'descend', 'ascend', 'wade', 'slip', 'slide', 'dive',
    'vault', 'step', 'push', 'pass', 'move', 'go', 'head', 'venture', 'sneak',
    'creep', 'lower yourself', 'haul yourself', 'pull yourself', 'force your way',
    'navigate', 'plunge', 'burrow', 'thrust yourself', 'hoist yourself',
    'make your way', 'break', 'stumble', 'run', 'sprint', 'walk', 'march',
]

# The subset of the above that are THRESHOLDS rather than destinations: you do
# not stand next to a doorway you have gone through, you stand on the far side
# of it. Crossing one is the case the throttle must never refuse, because the
# previous frame contains no pixel of where the player now is.
_PORTAL_NOUNS = frozenset({
    'doorway', 'gateway', 'gate', 'threshold', 'archway', 'entrance', 'hatch',
    'airlock', 'opening', 'gap', 'hole', 'window', 'grate', 'grating',
    'manhole', 'maw', 'vent', 'ventilation', 'duct', 'ductwork', 'passage',
    'passageway', 'stairwell', 'stairway', 'staircase', 'elevator', 'shaft',
})

# Prepositions that, paired with a move verb and a space noun, indicate crossing
# into a new area.
_TRANSITION_PREPS = [
    'into', 'through', 'inside', 'in through', 'out through', 'down into',
    'up into', 'in to', 'onto',
]

# Everything above is an interiors vocabulary: the prepositions all mean
# "entering an enclosure" and every destination noun is a room or a passage.
# In an open world nothing could ever match, so "sprint toward the scorched
# basin", "scale the lightning-struck mesa" and "follow the canyon trail" were
# all classed as in-place beats and rendered as img2img edits of the previous
# frame. Travel outdoors is a destination you cross to, not a threshold you
# pass through.
_TRAVEL_PREPS = [
    'toward', 'towards', 'across', 'over to', 'up to', 'down to',
    'out onto', 'out to', 'back to', 'to the', 'to a ', 'to an ',
    'over the', 'over a ', 'down the', 'up the', 'past the', 'past a ',
    'beyond the', 'behind the',
    # Getting ON something is a change of place as surely as crossing to it:
    # "climb onto the roof" leaves the ground. An observational tail still
    # vetoes it further down (_IN_PLACE_MARKERS covers "climb onto the crate
    # to get a better look").
    'onto the', 'onto a ',
]

# Locomotion that covers GROUND. Kept separate from _TRANSITION_MOVE_VERBS
# because these do not need an enclosure to count, and deliberately excludes
# the short-range approach verbs (walk / move / go / head / approach /
# advance). Crossing a room to stand at an oil pump is a new vantage on the
# same place, and cutting for it is what made MOVE read as teleporting; that
# case is handled by the chain cap below, not by a cut.
_TRAVEL_VERBS = [
    'sprint', 'run', 'dash', 'bolt', 'charge', 'race', 'jog', 'hurry',
    'march', 'hike', 'trek', 'cross', 'traverse', 'follow', 'scale',
    'climb', 'ascend', 'descend', 'clamber', 'scramble', 'vault', 'leap',
    'wade', 'swim', 'creep', 'sneak', 'crawl', 'venture', 'retreat',
    'backtrack', 'double back', 'make your way',
]

# Being CARRIED somewhere, under power. Deliberately separate from the list
# above AND from the short-range approach verbs it excludes, because the
# distinction is not politeness about wording — it is distance. Walking to the
# oil pump leaves you in the same place; DRIVING or FLYING to something does
# not, ever.
#
# These are the verbs a player TYPES. The curated slates are written in the
# game's own locomotion vocabulary and so were covered; free will is not, and
# without these "drive to the big building", "fly to antarctica" and "take the
# helicopter to the city" all scored as no-transition — so the next frame
# continued img2img from the frame they had just left and put them back on the
# same dirt. Measured: four of five typed travel actions failed to register.
_VEHICLE_TRAVEL_VERBS = [
    'drive', 'fly', 'ride', 'sail', 'speed', 'steer', 'pilot', 'motor',
    'floor it', 'gun it', 'take off',
]

# Travel verbs that take their destination as a plain object: you do not
# "scale INTO" a mesa, you scale it, and you are somewhere else after.
_TRAVEL_OBJECT_VERBS = [
    'scale', 'cross', 'traverse', 'follow', 'climb', 'ascend', 'descend',
]

# A heading with no named destination still moves the camera.
_TRAVEL_DIRECTIONS = [
    'forward', 'ahead', 'onward', 'onwards', 'downhill', 'uphill',
    'upstream', 'downstream', 'inland', 'north', 'south', 'east', 'west',
]

# Verbs that keep the body where it is. "Follow the wire with your eyes" and
# "climb onto the crate to get a better look" are observations, not journeys,
# so an observational tail vetoes a travel match.
_IN_PLACE_MARKERS = [
    'with your eyes', 'with the camcorder', 'through the viewfinder',
    'from here', 'from where you stand', 'without moving', 'in place',
    'stay put', 'hold position', 'for a better look', 'to get a better look',
]

# Words signalling continuation WITHIN the current space rather than crossing into
# a new one ("navigate DEEPER into the crawlspace" = same crawlspace, keep img2img
# continuity; "scramble into the ventilation shaft" = new space, hard cut).
_TRANSITION_CONTINUATION_WORDS = [
    'deeper', 'further', 'farther', 'onward', 'onwards', 'along', 'ahead within',
]


def transition_kind(choice: str) -> str:
    """How the player is leaving: "portal", "approach", or "" for neither.

    The grade matters because only one of them can be safely refused. Crossing
    a THRESHOLD — a door, a hatch, a gate — is a passage: the wall the camera
    was looking at is behind it now, and no amount of img2img off the old frame
    can depict that. Refuse it and the render has no choice but to draw the
    room the player just left, which is precisely the "I entered the dark door
    and came out where I started" report.

    An APPROACH ("move to the silo", "climb into the trench") is a distance
    closed inside a space the camera can already see. That one softens fine,
    and softening it is the whole reason the throttle exists — walking up to a
    rock should not compose a brand-new world.
    """
    if not choice:
        return ""
    return _transition_reason(choice.lower())[0]


def is_hard_transition(choice: str, dispatch: str) -> bool:
    """
    Detect if the player's CHOICE moves them into a genuinely new area — a
    location change that warrants a "hard cut" (fresh image composition) rather
    than img2img continuity off the previous frame.

    Only the player's CHOICE is inspected, never the LLM narrative ``dispatch``:
    narrative prose is full of dramatic language ("the floor falls away", "you
    crumple") that would cause false location changes and shatter continuity.

    Two detectors, tuned to fire on real scene changes while staying quiet on
    small in-place moves so the world still feels temporally continuous:

      1. Unambiguous location phrases (enter/exit/leave/through the door, …).
      2. A movement verb + into/through + a distinct/enclosed space noun
         (e.g. "scramble into the ventilation shaft", "crawl through the duct").
         Suppressed when a continuation word ("deeper", "further", …) is present,
         since that means moving WITHIN the current space, not into a new one.
    """
    if not choice:
        return False

    kind, reason = _transition_reason(choice.lower())
    if kind:
        safe_choice = choice.encode('ascii', 'replace').decode('ascii')
        print(f"[HARD TRANSITION] Detected in choice ({kind}: {reason}): "
              f"'{safe_choice}' - new location (fresh composition, keep lighting/aesthetic)")
        return True
    return False


def resolve_hard_transition(choice: str, dispatch: str,
                            relocated: Optional[bool] = None) -> bool:
    """Did this turn end somewhere the last frame cannot be edited into?

    `relocated` is the consequence model's own answer, and it wins when it has
    one. It is answering about the beat it just wrote, where is_hard_transition
    is guessing from the player's wording — and the guess was wrong often
    enough to break the game. Reported: "explore deeper into this space"
    rendered as an img2img refine of the room the player was trying to leave,
    so a step forward animated and landed back where it started. Three ways to
    miss in one phrase: `deeper` suppresses the detector outright, `explore` is
    not in its verb list, and `space` is not in its noun list. Word lists
    cannot be finished, and the model already knows the answer.

    None means the model did not say (an older save, a failed parse, a
    degraded turn), and then the wording guess is still better than nothing.
    Egress still forces a cut either way: running for the exit is a departure
    whatever the prose decided to describe.
    """
    if is_egress_choice(choice):
        return True
    if relocated is not None:
        print(f"[HARD TRANSITION] consequence says relocated={relocated}", flush=True)
        return bool(relocated)
    return is_hard_transition(choice, dispatch)


# ───────── leaving the REGION, not just the room ─────────────────────────────
# `hard_transition` means "the previous frame cannot be edited into this one".
# That is the right answer for a doorway, and it turned out to be half the
# answer for a journey.
#
# Reported: the player typed "travel to antartica". Every stage upstream worked.
# The consequence model wrote the flight and the arrival; world evolution
# recorded "the transport helicopter has deposited you over a desolate Antarctic
# ice shelf"; the cut was detected; the scene description handed to the renderer
# read "a vast, featureless Antarctic ice sheet". The frame that came back was
# the Utah desert at golden hour with a helicopter parked in it.
#
# Nothing overruled the cut. What overruled it was everything the cut politely
# keeps hold of — all of which is written for the next ROOM:
#
#   - the hard-cut camera block, which says "Carry over the light, the look, and
#     whether this is indoors or outdoors"
#   - the img2img clause, "Maintain the same lighting, time of day, and color
#     palette as the previous image"
#   - `time_of_day`, rolled once at reset off the LEVEL PLATE's palette and
#     pinned for the session: "weather: golden hour, rust, red dust,
#     chain-link steel"
#   - the visual tone gloss, which a cut is allowed to re-ask but which is
#     handed the old gloss as "PREVIOUS TONE (keep matching this)"
#   - the previous desert frame, still img2img reference #1
#
# Five concrete statements that the light is red desert dusk, against one
# sentence naming Antarctica. The model went with the five — exactly as this
# module's own notes predict it will whenever precedence is left undefined.
#
# Carrying light across a threshold is correct: two rooms in one building share
# a sun. Carrying it across a CONTINENT is not. So this is the grade above a
# hard cut, and the only things that survive it are the film stock, the era and
# who the player is.

#: Being MOVED somewhere by something else. Not a long walk — these phrases mean
#: the player never crossed the ground in between.
_RELOCATION_PHRASES = (
    'teleport', 'transported to', 'transports you', 'transport you',
    'carried to', 'dragged to', 'flown to', 'airlifted',
    'wake up in', 'wakes up in', 'find yourself in',
)

#: Verbs whose destination is a PLACE ON THE MAP rather than something in view.
#: You do not travel to the far side of a yard, and the game has no vocabulary
#: for "walk there for two days", so any of these plus a destination has left
#: the region. Kept separate from `_VEHICLE_TRAVEL_VERBS`, which exists to
#: answer the narrower question of whether a cut is needed at all.
_LONGHAUL_TRAVEL_VERBS = (
    'travel', 'journey', 'voyage', 'relocate', 'migrate', 'warp',
    'fly', 'sail', 'drive', 'ride',
)

#: Things you ride or drive WITHOUT leaving the building. "Ride the elevator to
#: the top floor" is a long-haul verb and a destination by the rule above, and
#: it is also the same place: the tower keeps its weather and its hour, and
#: relighting it would be the original continuity bug wearing the fix's clothes.
_SAME_PLACE_CONVEYANCES = (
    'elevator', 'lift', 'escalator', 'stairs', 'stairway', 'staircase',
    'stairwell', 'ladder', 'dumbwaiter', 'hoist', 'forklift', 'cart',
    'gurney', 'conveyor',
)


def is_region_change(choice: str) -> bool:
    """Did this action leave the PLACE, rather than just the room?

    Only the player's action is inspected, for the same reason
    `is_hard_transition` refuses to read the narrative: prose is full of
    dramatic relocation language ("the floor falls away", "the world tilts")
    that means nothing of the kind.

    Deliberately narrow. A false positive costs one frame its lighting
    continuity, which the next frame restores. A false negative is the bug
    above, which costs the player their belief that typing anything does
    anything. Narrow still wins, because the actions that reach here are
    unambiguous: a player who types a continent has said what they want.
    """
    if not choice:
        return False
    low = choice.lower()
    # "follow the wire with your eyes" style tails mean the body did not move,
    # whatever verb they were built on.
    if any(m in low for m in _IN_PLACE_MARKERS):
        return False
    for phrase in _RELOCATION_PHRASES:
        if phrase in low:
            print(f"[REGION CHANGE] '{choice[:60]}' — moved by something else "
                  f"('{phrase}'): the old place's light has no authority here",
                  flush=True)
            return True
    if any(re.search(rf"\b{re.escape(c)}", low) for c in _SAME_PLACE_CONVEYANCES):
        return False
    # A long-haul verb still needs somewhere to go. Bare "drive" is flooring it
    # down the same road; "drive to the city" is not.
    has_verb = any(re.search(rf"\b{re.escape(v)}", low)
                   for v in _LONGHAUL_TRAVEL_VERBS)
    if has_verb and re.search(r"\b(?:to|toward|towards|into|for)\s+\w", low):
        print(f"[REGION CHANGE] '{choice[:60]}' — long-haul travel to a named "
              f"destination: relighting for the new place", flush=True)
        return True
    return False


def _transition_reason(choice_lower: str) -> tuple[str, str]:
    """The shared detector behind :func:`is_hard_transition` and
    :func:`transition_kind`. Returns (kind, human reason), ("", "") for no."""
    # ── 1. Unambiguous location-change phrases ────────────────────────────────
    location_keywords = [
        'enter ', 'step inside', 'go inside', 'walk inside', 'move inside',
        'step outdoors', 'go outdoors', 'walk outdoors', 'move outdoors',
        'step outside', 'head outside', 'get outside',
        'exit ', 'leave ', 'open door', 'open the door', 'through the door',
        'through the doorway', 'through the gate', 'through the hatch',
        'cross into', 'cross over', 'cross through', 'cross the threshold',
        'red biome', 'new location', 'different room', 'different area',
        'next room', 'another room', 'the next area',
        'teleport', 'wake up in', 'dragged to', 'carried to', 'transported to',
        'emerge into', 'emerge from', 'emerge onto',
    ]
    if any(k in choice_lower for k in location_keywords):
        return "portal", "explicit location phrase"

    # ── 2. move-verb + preposition + enclosed-space noun ──────────────────────
    is_continuation = any(w in choice_lower for w in _TRANSITION_CONTINUATION_WORDS)
    if not is_continuation:
        has_verb = any(v in choice_lower for v in _TRANSITION_MOVE_VERBS)
        if has_verb:
            for prep in _TRANSITION_PREPS:
                marker = f" {prep} "
                if marker not in choice_lower:
                    continue
                # Only the text AFTER the preposition should name the space we
                # are moving into, so "reach into your PACK" style objects
                # before the noun don't cause false hits.
                tail = choice_lower.split(marker, 1)[1]
                if any(re.search(rf"\b{re.escape(n)}\b", tail)
                       for n in _TRANSITION_SPACE_NOUNS):
                    # A named threshold in the tail is a passage even by this
                    # looser route: "squeeze through the hatch" is not an
                    # approach to a hatch, it is the other side of one.
                    kind = ("portal"
                            if any(re.search(rf"\b{re.escape(n)}\b", tail)
                                   for n in _PORTAL_NOUNS)
                            else "approach")
                    return kind, f"move-verb + '{prep}' + new space"

    # ── 3. travel in the open: locomotion + a destination ────────────────────
    # Graded "approach", never "portal": crossing open ground to a landmark is
    # a new vantage on the same world, so the throttle may still refuse it.
    if is_continuation or any(m in choice_lower for m in _IN_PLACE_MARKERS):
        return "", ""
    has_travel_verb = any(re.search(rf"\b{re.escape(v)}", choice_lower)
                          for v in _TRAVEL_VERBS)
    # Under power, a bare "to" is enough. The prep list wants an article —
    # "to the", "to a" — because on foot "turn to the left" and "listen to the
    # hum" are not journeys. But a PLACE NAME takes no article, so "fly to
    # antarctica" and "sail to Mexico" matched nothing, and the one kind of
    # action that is guaranteed to leave was the one kind that never cut.
    under_power = any(re.search(rf"\b{re.escape(v)}", choice_lower)
                      for v in _VEHICLE_TRAVEL_VERBS)
    if under_power and re.search(r"\b(?:to|for)\s+\w", choice_lower):
        return "approach", "under power + destination"
    if has_travel_verb or under_power:
        for prep in _TRAVEL_PREPS:
            if f" {prep}" in choice_lower:
                return "approach", f"travel verb + '{prep.strip()}' + destination"
        for direction in _TRAVEL_DIRECTIONS:
            if re.search(rf"\b{re.escape(direction)}\b", choice_lower):
                return "approach", f"travel verb + heading '{direction}'"
    for verb in _TRAVEL_OBJECT_VERBS:
        if re.search(rf"\b{re.escape(verb)}\s+(?:the|a|an|that|this)\s+\w", choice_lower):
            return "approach", f"'{verb}' + destination"

    return "", ""

# ───────── environment stagnation ────────────────────────────────────────────
# Cutting to a new place every turn is not the same as GOING anywhere. A SCAN
# run that entered a pipe, a tunnel, a bone structure and another tunnel changed
# location 27 turns running and never once left "cramped organic interior",
# because every slate it was offered led further in. Nothing was watching the
# shape of the run, so nothing ever offered a way back out.
#
# Vision already labels each turn's environment (`setting_type`: "indoor-corridor",
# "outdoor-desert", …) and stores it in history. Counting an unbroken run of the
# same label is enough to notice, and cheap — no extra model call.
ENVIRONMENT_STREAK_LIMIT = 4

# Phrasing that means "get out of this kind of space", as opposed to the
# "deeper / further in" language a stuck run keeps generating.
_EGRESS_RE = re.compile(
    r"\b(exit|leave|leaves|leaving|escape|retreat|withdraw|abandon|surface|"
    r"back out|climb out|crawl out|haul yourself out|get out|way out|"
    r"out of|outside|open air|open ground|daylight|back the way|turn back|"
    r"away from|double back|"
    # Flight. This is not decoration: taking an egress option is the only thing
    # that sheds detection heat, so a phrasing missing from here is a way out
    # the player can pick that the engine will not count as running. The forced
    # options the game offers a hunted player were themselves failing to match.
    # "run" is qualified because prose runs cables and runs hands along pipes.
    r"flee|flees|fleeing|sprint|scramble away|scramble out|scramble back|"
    r"break away|break and run|make a run|get clear|put distance|"
    r"run for|run to|run back|run toward|run towards|bolt for|bolt out)\b",
    re.I,
)

# Deterministic last resort when the model ignores the directive. Deliberately
# generic: they name no affordance that might not exist, and every one of them
# is a physical movement of the body out of wherever it currently is.
_EGRESS_FALLBACKS = (
    "Turn back and retrace your route",
    "Climb out toward open air",
    "Force your way back out",
    "Abandon this route entirely",
)

# The same backstop, for when the reason is a pursuer rather than a rut. Walking
# calmly back the way you came is not an answer to something chasing you, and
# offering it as one reads as the game not having noticed. These are the same
# deliberate genericness — no affordance that might not exist — at a run.
_FLIGHT_FALLBACKS = (
    "Break and run for open ground",
    "Sprint back the way you came",
    "Bolt for the nearest way out",
    "Turn and flee into the dark",
)


# Vision is the better labeller, but it is not always there: it needs a key, a
# network round-trip and a frame that has finished rendering, and on the live
# turn path Phase 2 runs before the image lands. A stagnation guard that only
# works when vision works is a guard that switches itself off in exactly the
# conditions that produce stuck runs. So the same taxonomy is also derivable
# from the render base, which is written on every frame with no model call.
# Words that name a KIND OF SPACE, not the machinery standing in it. An oil pump
# is not evidence of a warehouse — it is just as at home in an open yard — and
# the label is also what keeps drift beats honest about indoor vs outdoor, so
# guessing "indoor" off a nearby machine would blow wind through a sealed room.
# Prose that names no space at all scores nothing and returns "", which the
# streak treats as missing evidence rather than as movement.
_SETTING_KEYWORDS: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("outdoor-desert",   ("desert", "dune", "dunes", "sand", "wasteland", "scrubland")),
    ("outdoor-cliff",    ("cliff", "ravine", "canyon", "ledge", "precipice", "gorge")),
    ("outdoor-road",     ("road", "highway", "asphalt", "street", "roadside")),
    # No "field": every render base says "medium-wide field of view", which would
    # tag the whole run outdoors on boilerplate alone.
    ("outdoor-other",    ("sky", "yard", "courtyard", "forest", "rooftop",
                          "treeline", "horizon", "fence", "outdoors",
                          "open air", "open ground")),
    ("indoor-corridor",  ("corridor", "hallway", "tunnel", "pipe", "duct", "shaft",
                          "passage", "passageway", "stairwell", "crawlspace")),
    ("indoor-lab",       ("laboratory", "infirmary", "clean room")),
    ("indoor-warehouse", ("warehouse", "factory", "refinery", "catwalk", "gantry",
                          "machine hall", "pump house", "boiler room", "plant floor")),
    ("indoor-other",     ("room", "chamber", "basement", "cellar", "office", "interior",
                          "inside the")),
    ("transitional",     ("doorway", "threshold", "gateway", "entrance", "airlock",
                          "hatch")),
)

# Word-boundary matching, because substring counting reads "vent" out of
# "vented" and silently breaks a streak that never left the room.
_SETTING_PATTERNS: tuple[tuple[str, "re.Pattern[str]"], ...] = tuple(
    (label, re.compile("|".join(r"\b" + re.escape(w) + r"\b" for w in words), re.I))
    for label, words in _SETTING_KEYWORDS
)


def classify_setting(text: str) -> str:
    """Best-effort environment label for free scene prose.

    Returns "" when the prose names no kind of space.
    """
    if not (text or "").strip():
        return ""
    best, best_hits = "", 0
    for label, pattern in _SETTING_PATTERNS:
        hits = len(pattern.findall(text))
        if hits > best_hits:
            best, best_hits = label, hits
    return best


# When the nine-bucket taxonomy above can't name the space at all — "crawling
# under the truck", "the drainage ditch ahead" name no room — the only
# remaining evidence is whether the prose keeps repeating itself. Comparing
# full scene text works because the constant style/camera preamble every
# render_base repeats verbatim is filtered out here, not because it was
# stripped out before being passed in.
_GENERIC_SCENE_STOPWORDS = frozenset(
    "there their about across toward directly before after while still other "
    "again further along which where being frame camera first person "
    "walking vantage field view empty hands lower weapon crosshair reticle "
    "health minimap screen video game found footage".split()
)
# Overlap coefficient (|A∩B| / min(|A|,|B|)), not Jaccard: against a single
# anchor turn, a real stall (oil pump -> drive rod -> floor grate -> oil pit)
# scores as low as a genuine truck -> ditch -> pipe chase, because each turn
# names a different PART of the same machine — Jaccard punishes the anchor's
# vocabulary for growing. Comparing against the ACCUMULATED vocabulary of the
# whole streak, and asking only "is most of THIS turn's vocabulary already in
# it", tells the two apart: the stall's small shared parts-vocabulary keeps
# getting hit turn after turn, while a chase keeps spending new nouns.
_SCENE_OVERLAP_STUCK = 0.30
_style_anchor_words_cache: "frozenset | None" = None


def _raw_words(text: str) -> frozenset:
    return frozenset(re.findall(r"[a-z]{4,}", (text or "").lower()))


def _style_anchor_words() -> frozenset:
    """Lazy + cached: REALTIME_STYLE_ANCHOR is defined further down the module,
    so this can't be a module-level constant computed at this point in the file."""
    global _style_anchor_words_cache
    if _style_anchor_words_cache is None:
        _style_anchor_words_cache = _raw_words(REALTIME_STYLE_ANCHOR) | _GENERIC_SCENE_STOPWORDS
    return _style_anchor_words_cache


def _content_words(text: str) -> frozenset:
    return _raw_words(text) - _style_anchor_words()


def _overlap_coefficient(a: frozenset, b: frozenset) -> float:
    """|A∩B| / min(|A|,|B|) — how much of the SMALLER set the other one covers.
    0.0 when either is empty."""
    if not a or not b:
        return 0.0
    return len(a & b) / min(len(a), len(b))


def resolve_environment_label(state: dict, history: list) -> str:
    """The current environment label, from vision if it ran and prose if it didn't."""
    last = history[-1] if history else {}
    label = (last.get("setting_type") or "").strip()
    if label:
        return label
    # The render base carries a constant style preamble plus this turn's scene
    # sentence; the preamble names no place, so it cannot bias the vote.
    return classify_setting((state or {}).get("current_render_base") or "")


def _environment_key(setting_type: str) -> str:
    return re.sub(r"[^a-z]+", "-", (setting_type or "").lower()).strip("-")


def update_environment_streak(state: dict, setting_type: str,
                              hard_transition: bool = False,
                              scene_text: str = "") -> int:
    """How many turns in a row the run has been in this kind of place.

    A hard cut or a changed label is unambiguous evidence of movement. When
    neither is available — the nine-bucket taxonomy names no room for plenty
    of real scene prose ("crawling under the truck", "the drainage ditch
    ahead") — blindly counting every unlabelled turn as "no movement" is what
    turned a truck-to-pipe chase into eight forced "turn back and retrace your
    route" prompts: nothing NAMED a room, so nothing LOOKED like it changed.

    The tiebreaker is whether this turn's words are mostly already in the
    streak's accumulated vocabulary. A single fixed anchor turn undercounts a
    real stall, because "oil pump", "drive rod" and "floor grate" are three
    different nouns for parts of the same machine and share almost no words
    with each other — only with the growing pool of everything said so far.
    """
    prev   = int(state.get("environment_streak", 0) or 0)
    key    = _environment_key(setting_type)
    known  = state.get("environment_key") or ""
    vocab  = set(state.get("environment_streak_vocab") or [])
    words  = _content_words(scene_text)

    if hard_transition:
        streak, vocab = 1, set(words)
    elif key and key == known:
        streak = prev + 1
        vocab |= words
    elif key:
        streak, vocab = 1, set(words)
    elif words and vocab and _overlap_coefficient(words, vocab) >= _SCENE_OVERLAP_STUCK:
        streak = prev + 1 if prev else 1
        vocab |= words
    elif prev:
        streak = prev  # neither confirmed same nor confirmed different: hold, don't guess
    else:
        streak, vocab = 1, set(words)

    if key:
        state["environment_key"] = key
    state["environment_streak_vocab"] = sorted(vocab)
    state["environment_streak"] = streak
    return streak


def is_egress_choice(choice: str) -> bool:
    """Does this option physically take the player OUT of the current space?"""
    return bool(_EGRESS_RE.search(choice or ""))


def enforce_egress_option(choices: list, streak: int,
                          detection: int = DETECT_HIDDEN, turn: int = 0) -> list:
    """Guarantee a way out on the slate when the run needs one.

    Two reasons to need one. The run has been in one kind of place too long, or
    the player is being hunted — and the second is the one that matters most,
    because fleeing is the only thing that sheds detection heat (see
    DETECT_COOL_FLEEING). Being hunted with no way to run offered is a trap the
    player cannot see the edges of.

    The dispatch prompt asks for one first (see the stagnation directive); this
    is the backstop for when the model would rather offer a third way deeper in.
    Replaces the LAST option so the two the model felt strongest about survive.
    """
    needed = streak >= ENVIRONMENT_STREAK_LIMIT or detection >= DETECT_HUNTED
    if not needed or not choices:
        return choices
    if any(is_egress_choice(c) for c in choices):
        return choices
    hunted = detection >= DETECT_HUNTED
    pool = _FLIGHT_FALLBACKS if hunted else _EGRESS_FALLBACKS
    # Rotate on the turn as well as the streak. A hunted run holds both of the
    # others constant, so a live render forced the identical sentence eight
    # times running — which is the repetition this backstop exists to prevent.
    forced = pool[(streak + detection + turn) % len(pool)]
    why = "being hunted" if hunted else f"{streak} turns in one place"
    print(f"[ANTI-LOOP] {why} and no way out on the slate — forcing '{forced}'",
          flush=True)
    return list(choices[:-1]) + [forced]


def stagnation_directive(streak: int) -> str:
    """Prompt text telling the consequence call to offer an exit."""
    if streak < ENVIRONMENT_STREAK_LIMIT:
        return ""
    return (
        f"\n\nSTUCK IN ONE KIND OF PLACE: the player has spent {streak} consecutive "
        "turns in this same type of environment. The run needs somewhere else to go. "
        "Your `visual_scene` MUST make a way out of this kind of space physically "
        "visible in the frame (an opening to elsewhere, a route back, a change in the "
        "structure ahead), and ONE of your three `next_choices` MUST take the player "
        "OUT of it rather than further into it. Do not offer three variations on "
        "going deeper.\n"
    )


# ───────── on-screen objects (what SCAN saw) ─────────────────────────────────
# SCAN names every interactable thing in the frame the player is looking at, and
# all but one of those names used to be thrown away: only the single label the
# player tapped ever reached the simulation, as the permanence `subject`. So the
# consequence call was handed the frame itself (as a multimodal part) and its
# pixels (as img2img references) but never a LIST of what is in it — which is
# why a beat could only ever be about the one thing that got poked while the
# other five things on screen might as well not have existed.
#
# Keeping that list for the turn it belongs to costs nothing: the detection has
# already run and been paid for. It is what lets the consequence weave two
# VISIBLE things together instead of resolving on one.

# The detector may name up to DETECT_MAX_ITEMS (12). All twelve in a prompt
# dilutes rather than grounds, and the tail of a detection pass is the least
# salient of it, so the cache keeps the front of the list.
SCENE_OBJECTS_MAX = 8


def record_scene_objects(state: dict, objects: list) -> list:
    """Cache the labels SCAN just named, stamped with the turn they describe."""
    labels: list = []
    for obj in objects or []:
        label = str((obj or {}).get("label") or "").strip()
        if label and label.lower() not in {l.lower() for l in labels}:
            labels.append(label)
        if len(labels) >= SCENE_OBJECTS_MAX:
            break
    state["scene_objects"] = labels
    state["scene_objects_turn"] = int(state.get("turn_count", 0) or 0)
    return labels


def scene_objects_for_turn(state: dict) -> list:
    """The cached on-screen labels, or [] once they describe a frame we've left.

    Stale nouns are worse than none. A list captured two rooms ago would tell
    the consequence call to feature things that are no longer in front of the
    player — the exact teleporting/ungrounded failure the spatial rules exist to
    prevent. `turn_count` only increments once a turn has fully resolved, so a
    SCAN and the action the player commits from it share a stamp, and the cache
    expires by itself the moment the world moves on.
    """
    labels = state.get("scene_objects") or []
    if not isinstance(labels, list) or not labels:
        return []
    try:
        stamped = int(state.get("scene_objects_turn", -1))
        current = int(state.get("turn_count", 0) or 0)
    except (TypeError, ValueError):
        return []
    if stamped != current:
        return []
    return [str(l).strip() for l in labels if str(l).strip()]


def onscreen_directive(labels: list) -> str:
    """Prompt text naming what is in frame, and asking for a collision.

    Two things, not one: a consequence that resolves on the single object the
    player poked reads as a vignette, while the same beat with a second visible
    thing reacting to it reads as a world that is alive. Choosing WHICH pairing
    is interesting is what the model is already good at — it just has to be told
    what is on the table. Below two labels there is nothing to pair, so the
    directive stays out of the prompt rather than asking for the impossible.
    """
    if len(labels) < 2:
        return ""
    return (
        "\n\nON SCREEN RIGHT NOW (named from the frame the player is looking at): "
        f"{', '.join(labels)}\n"
        "Weave AT LEAST TWO of these into this beat, and let one of them CHANGE "
        "STATE — move, open, break, react, close in, give way. Both `dispatch` and "
        "`visual_scene` must show them. Do NOT invent a new prop to carry the beat "
        "while these sit inert in the background.\n"
    )


def grounded_entities(state: dict, limit: int = 12) -> str:
    """The entity list for choice generation: what's on screen, then memory.

    On-screen labels lead because they are what the player can physically act on
    THIS turn; `seen_elements` follows as world memory (most recent first, which
    is also the order truncation should eat from the back of). This ordering is
    what stops a slate proposing a sprint to a shed that was never in frame.
    """
    seen = [str(e) for e in (state.get("seen_elements") or []) if str(e).strip()]
    out: list = []
    for label in scene_objects_for_turn(state) + seen[::-1]:
        if label.lower() not in {o.lower() for o in out}:
            out.append(label)
        if len(out) >= limit:
            break
    return ", ".join(out)


# ───────── hard-transition throttle (NOT called from the live turn pipeline) ─
# A hard transition throws away img2img continuity and composes a fresh frame.
# That's right for genuinely walking into a new space, and ruinous when it
# happens every single turn: a 30-turn SCAN run that entered a pipe, then a
# tunnel, then a bone structure, then another tunnel spent 27 consecutive turns
# in organic interiors that shared no geography with each other, because each
# cut invented a fresh "inside" with nothing holding it to the last one.
#
# So consecutive cuts used to be capped here. Past the cap the turn still
# MOVED, but the frame was composed off the previous one. The cap itself
# became the next inconsistency: the SAME "walk to the silo" wording could cut
# or not depending on how many cuts had happened recently, for no reason
# visible to the player — the exact coin-flip MOVE TO was fixed to not have.
# advance_turn_image_fast no longer calls this for any action (MOVE is
# unconditional; typed/curated text is un-throttled too, see its else
# branch). Kept — tested, self-contained — for a future feature that
# legitimately wants "cap consecutive cuts" back without re-deriving this.
MAX_CONSECUTIVE_HARD_TRANSITIONS = 2

# How many soft turns may compound off each other before the chain is
# re-anchored. A soft turn generates from the previous GENERATED frame, so the
# nth frame in a run has been through n rounds of lossy resampling; a 20-turn
# outdoor stretch (which is what an open world produced before travel was
# detectable) ends up a smeared, colour-drifted copy of a copy.
IMG2IMG_SOFT_CHAIN_MAX = int(os.getenv("IMG2IMG_SOFT_CHAIN_MAX", "3"))


def _soft_chain_anchor(history: Optional[list], limit: int) -> Optional[str]:
    """The clean frame that opened this location, once the chain is too deep.

    Walks back to the last hard cut, counting soft frames. Returns that
    boundary frame's image only if the run since it is longer than ``limit``
    — below the cap, compounding is cheap and continuity is worth more.
    """
    if not history or limit <= 0:
        return None
    soft = 0
    for entry in reversed(history):
        if not isinstance(entry, dict):
            continue
        path = entry.get("image")
        if entry.get("hard_transition"):
            if soft <= limit:
                return None
            return path if path and os.path.exists(str(path)) else None
        if path:
            soft += 1
    return None

# Language that means a new space genuinely opened in the fiction. When the
# consequence says this, the cut is earned no matter how many preceded it —
# otherwise the throttle would flatten a real breakthrough into a camera nudge.
_NEW_SPACE_PROSE = (
    "opens into", "opens onto", "opens out", "gives way to", "widens into",
    "emerges into", "emerge into", "emerges onto", "spills into", "breaks through into",
    "you are now inside", "you are inside", "find yourself in", "step out into",
    "collapses into", "drops you into", "on the other side",
)


def narrative_opened_new_space(dispatch: str) -> bool:
    """Did the consequence prose actually describe arriving somewhere new?"""
    low = (dispatch or "").lower()
    return any(phrase in low for phrase in _NEW_SPACE_PROSE)


def throttle_hard_transition(state: dict, wants_cut: bool, dispatch: str,
                             kind: str = "") -> bool:
    """Decide whether this turn really gets a fresh composition.

    Mutates ``state['consecutive_hard_transitions']``. A soft turn resets the
    run, so ordinary play never trips the cap — only an unbroken chain of
    location changes does.

    A PORTAL is exempt. The throttle exists to stop walking up to a rock from
    composing a whole new world; it was never meant to adjudicate whether the
    player got through a door they were told they could open. Refusing one of
    those is unrenderable — the previous frame shows the near side and the
    prose says they are on the far side — so the image has to contradict one of
    them, and it contradicts the prose. That is what "I entered the dark door
    and appeared back outside" is. Being asked to play MOVE-first made it
    constant rather than occasional: nearly every turn now wants a cut, so the
    cap was reached by turn three and, because a refusal HOLDS the count at the
    cap, stayed reached. Runs of four and five consecutive refusals show up in
    the logs, and each one re-pinned the camera to a place already left.
    """
    run = int(state.get("consecutive_hard_transitions", 0) or 0)
    if not wants_cut:
        state["consecutive_hard_transitions"] = 0
        return False
    if kind == "portal":
        # Doesn't clear the run — an approach after this is still throttleable —
        # but is never itself refused.
        state["consecutive_hard_transitions"] = run + 1
        return True
    if run >= MAX_CONSECUTIVE_HARD_TRANSITIONS and not narrative_opened_new_space(dispatch):
        # Hold the chain at the cap: the next turn is still throttled unless a
        # soft turn breaks it, so a stuck run can't alternate its way around.
        print(f"[HARD TRANSITION] throttled — {run} consecutive cuts already and the "
              f"prose didn't open a new space; composing off the previous frame", flush=True)
        return False
    state["consecutive_hard_transitions"] = run + 1
    return True


def get_last_movement_type() -> Optional[str]:
    """Get the last detected movement type for display purposes."""
    return _last_movement_type

# The MOVE rail writes its own actions, so they are exact strings rather than
# player prose and can be recognised outright. They used to go through the
# keyword lists below like anything else, which went wrong twice over: "Move
# to the X" matches no keyword, so the commonest travel action in the game
# paid for an LLM round-trip and then accepted whatever came back; and the
# object's name is interpolated INTO the sentence, so a MOVE TO the panel hit
# the 'pan' substring and was classified as standing still.
#
# "walk over to the" / "moving inside into the space beyond" are the RETIRED
# client phrasings (moveActionPhrase used to pick one of the two based on the
# object's name); kept here so a replayed older session or saved history entry
# still gets the fast path instead of quietly falling through to the LLM call.
_UI_MOVE_PHRASES = re.compile(
    r"\bmove to the\b|\bwalk over to the\b|\bmoving inside into the space beyond\b",
    re.IGNORECASE,
)


def _mentions(text: str, keywords) -> bool:
    """Whole-word keyword search.

    Substring matching is what let an object's NAME answer a question about the
    player's VERB: panel/company contain "pan", turnstile contains "turn",
    checkpoint contains "check", scanner contains "scan". Every one of those
    turned a walk into a stationary shot.
    """
    return any(re.search(rf"\b{re.escape(k)}\b", text) for k in keywords)


def _detect_movement_type(player_choice: str) -> str:
    """
    Use LLM to intelligently classify action type.
    Returns: 'forward_movement', 'stationary', 'exploration'
    """
    # Keyword-based classification for common patterns (faster, more reliable)
    choice_lower = player_choice.lower()

    # The rail's own MOVE actions, before anything can misread them.
    if _UI_MOVE_PHRASES.search(choice_lower):
        return 'forward_movement'

    # Leaving the region is travel by definition, and it must not be decided by
    # a round-trip that can fail. "travel to antartica" matches no keyword below,
    # so the commonest typed journey in the game paid for an LLM call and then
    # accepted whatever came back — and the failure default is 'exploration',
    # which renders a change of continent as a slight pan from the same spot.
    # A live capture has that call returning 403 and doing exactly that.
    if is_region_change(player_choice):
        return 'forward_movement'

    # Stationary actions (observing, no camera movement)
    stationary_keywords = ['photograph', 'examine', 'inspect', 'check', 'observe', 'watch', 'study', 'crouch in place', 'stand still']
    if _mentions(choice_lower, stationary_keywords):
        return 'stationary'
    
    # Exploration actions (subtle movement, turning, panning)
    exploration_keywords = ['turn', 'look around', 'scan', 'survey', 'glance', 'peer', 'look back', 'turn around', 'rotate', 'pan', 'back away', 'step back', 'retreat']
    if _mentions(choice_lower, exploration_keywords):
        return 'exploration'
    
    # Forward movement actions (significant spatial progression)
    forward_keywords = ['sprint', 'dash', 'run toward', 'charge', 'advance', 'approach', 'move forward', 'walk toward', 'climb', 'enter', 'cross', 'vault', 'scramble', 'rush']
    if _mentions(choice_lower, forward_keywords):
        return 'forward_movement'
    
    # Fallback to LLM if no keywords match
    detection_prompt = (
        f"Classify this player action into ONE category:\n\n"
        f"ACTION: '{player_choice}'\n\n"
        f"CATEGORIES:\n"
        f"- FORWARD_MOVEMENT: Camera moves significantly FORWARD/CLOSER to destination (advance, sprint, climb, enter, cross, approach buildings)\n"
        f"- EXPLORATION: Camera moves slightly (look around, scan, pan, turn, back away, retreat) but no major spatial progression\n"
        f"- STATIONARY: Camera stays in exact same position (examine object, photograph, crouch in place)\n\n"
        f"CRITICAL: 'Turn back', 'retreat', 'back away' are EXPLORATION (slight movement), NOT forward_movement.\n\n"
        f"Return ONLY one word: FORWARD_MOVEMENT, EXPLORATION, or STATIONARY"
    )
    
    try:
        result = _ask(detection_prompt, temp=0.2, tokens=5, use_lore=False).strip().upper()
        if 'FORWARD' in result:
            return 'forward_movement'
        elif 'EXPLORATION' in result:
            return 'exploration'
        else:
            return 'stationary'
    except Exception as e:
        safe_e = str(e).encode('ascii', 'replace').decode('ascii')
        print(f"[MOVEMENT DETECTION] Error: {safe_e}, defaulting to exploration")
        return 'exploration'  # Default to some movement to keep things interesting

def build_image_prompt(
    player_choice: str = "",
    dispatch: str = "",
    narrative_dispatch: str = "",
    prev_vision_analysis: str = "",
    hard_transition: bool = False,
    is_timeout_penalty: bool = False,
    prev_spatial: str = "",
    prev_setting: str = "",
    softened_move: bool = False,
    holds_reference_frame: bool = False,
    region_change: bool = False,
    spec: Optional[dict] = None,
) -> str:
    """
    Build an image generation prompt with spatial-anchor continuity.

    ``dispatch`` — visual scene description of what the camera sees now
    (generated as ``visual_scene`` by the LLM, or falls back to narrative).

    ``narrative_dispatch`` — the narrative consequence text the player reads
    (what they feel/experience). Provided as context alongside the visual scene.

    ``prev_spatial`` — the directional compass extracted from the previous
    turn's vision analysis (ahead/left/right/ground/height).  When present it
    is injected as a hard spatial constraint so the model cannot silently move
    the camera to a different environment.

    ``prev_setting`` — indoor/outdoor environment type from previous vision
    analysis; used to enforce environment type consistency.

    ``region_change`` — this turn did not move to another part of the same
    place, it left the place. See :func:`is_region_change`: the hard-cut block
    below tells the camera to carry the light and the indoor/outdoor state over,
    which is right for the next room and wrong for another continent. When this
    is set, that carry-over is withdrawn and said so explicitly, because a
    withdrawn instruction the model never hears is indistinguishable from the
    instruction still being there.

    ``softened_move`` — this turn asked for a location change and the throttle
    declined to give it a fresh composition. It still has to MOVE. Without
    this the two states were indistinguishable to the prompt, so a declined
    move was built exactly like standing still: the spatial anchor below told
    the camera it could not leave a position the player had already walked out
    of, and the render obediently drew where they used to be. Vision then read
    that frame back into ``spatial_compass``, so the next turn anchored on the
    old place too, and the run walked backwards a frame at a time.

    Every branch below returns through ``game_identity.apply(..., "image")``,
    which stamps the active CAMERA / CAST / LOCATION directive on top and
    reconciles the perspective language underneath it. That's what makes the
    editor's first/third-person switch actually reach the image model rather
    than losing an argument with the hardcoded first-person prose.
    """
    spec = spec or game_identity.get_spec()
    cam = game_identity.mode_config(spec)

    def _finish(text: str) -> str:
        return game_identity.apply(text, "image", spec)

    # ── VIEWFINDER: same place, eyes-on-the-world, no evolution ────────────
    if game_identity.is_viewfinder_spec(spec):
        bits = [
            "VIEWFINDER RESTAGE — same place, no scene evolution, no camera travel.",
            "The camera IS the player's eyes. Restage this exact view as first person.",
            "Do not draw the player, their back, silhouette, clothes, or gear.",
            "Do not draw a camcorder, viewfinder, or film HUD.",
            "Do not walk the follow-cam body around to face the lens.",
            game_identity.viewfinder_hero_ban(spec),
        ]
        if prev_spatial:
            bits.append(f"Looking at: {prev_spatial}")
        if prev_setting:
            bits.append(f"Setting: {prev_setting}")
        if dispatch:
            bits.append(dispatch)
        return _finish("\n".join(bits))

    # ── TIMEOUT PENALTIES: identical camera, only environment reacts ──────────
    if is_timeout_penalty:
        base = (
            f"Result: {dispatch}\n\n"
            f"CRITICAL: TIMEOUT PENALTY — ZERO camera movement.\n"
            f"Show the EXACT SAME ANGLE and LOCATION as before.\n"
            f"ONLY environmental reactions (dust, debris, creature, attack, danger).\n"
            f"If outdoor, STAY outdoors. If indoor, STAY indoors. NO teleportation."
        )
        if prev_spatial:
            base += f"\n\n🗺️ LOCKED POSITION: {prev_spatial}"
        return _finish(base)

    # ── INTRO FRAME: pure establishing shot ───────────────────────────────────
    if player_choice.lower().strip() == "intro":
        prompt = f"Opening scene: {dispatch}"
        print(f"\n{'='*60}")
        print(f"[INTRO MODE] Creating establishing shot")
        print(f"{'='*60}\n", flush=True)
        return _finish(prompt)

    # ── Detect movement type ──────────────────────────────────────────────────
    global _last_movement_type
    movement_type = _detect_movement_type(player_choice)
    _last_movement_type = movement_type

    type_label = {
        'forward_movement': 'FORWARD MOVEMENT',
        'exploration':      'EXPLORATION',
        'stationary':       'STATIONARY',
    }
    print(f"\n{'='*60}")
    safe_choice = player_choice.encode('ascii', 'replace').decode('ascii')
    print(f"[MOVEMENT DETECTION] '{safe_choice}'")
    print(f"  -> {type_label.get(movement_type, movement_type.upper())}")
    print(f"{'='*60}\n", flush=True)

    # ── Base prompt ───────────────────────────────────────────────────────────
    # Three cases:
    #   A. LLM produced a distinct visual_scene → VISUAL-DOMINANT prompt, narrative
    #      compressed to a short context clause so it cannot dominate the image.
    #   B. No visual_scene but we DO have a prior vision_analysis → reuse the prior
    #      camera position as the spatial scaffold, then describe what changed.
    #   C. No visual scene and no prior vision → last-resort original style.
    has_visual_scene = (
        narrative_dispatch and
        narrative_dispatch.strip() and
        narrative_dispatch.strip() != dispatch.strip()
    )
    if has_visual_scene:
        # Compress narrative to a single short clause. The image model is biased
        # toward describing whatever it reads at length, so long narrative text
        # (which is intentionally non-visual / kinesthetic) was the original drift
        # cause. Keep it to ~120 chars of context only.
        narrative_brief = narrative_dispatch.strip().replace("\n", " ")
        if len(narrative_brief) > 120:
            narrative_brief = narrative_brief[:117] + "..."
        prompt = (
            f"{cam['camera_header']} — render exactly this scene:\n"
            f"{dispatch}\n\n"
            f"Action just performed: {player_choice}\n"
            f"(Brief narrative context, do not over-illustrate: {narrative_brief})"
        )
    elif prev_vision_analysis:
        # Visual scaffold from the previous frame's actual visual analysis. This is
        # WAY more visually grounded than narrative text and prevents drift even
        # when the LLM forgets to emit `visual_scene`.
        #
        # It used to end with "render the SAME camera position evolved... keep
        # ground type, environment type and visible landmarks identical" — an
        # unconditional stasis order, emitted on movement turns too, sitting
        # directly beneath the CAMERA line that had just said the opposite. One
        # more voice in the argument that made MOVE TO render as a redecorated
        # copy of the previous frame. What the camera did is decided above; this
        # branch's job is only to describe what the previous frame contained.
        scaffold = prev_vision_analysis.strip().replace("\n", " ")
        if len(scaffold) > 240:
            scaffold = scaffold[:237] + "..."
        prompt = (
            f"{cam['camera_header']}.\n"
            f"The previous frame showed: {scaffold}\n"
            f"Action just performed: {player_choice}\n"
            f"Render the result of that action, keeping the film stock, the light "
            f"and the materials of the previous frame."
        )
    else:
        prompt = f"Action taken: {player_choice}. Result: {dispatch}"

    # ── Camera state: decided once, said once, in prose ───────────────────────
    # This used to be two blocks: an emoji-marked prefix ("🗺️ SPATIAL ANCHOR",
    # "➡️ YOU HAVE CROSSED THE SPACE") and a bulleted suffix ("FORWARD MOVEMENT:
    # camera moved 5-15 ft"), which the img2img template then STRING-MATCHED for
    # those markers to pick one of its own five camera branches. Three layers
    # restating one decision, each with its own capitals and its own claim to
    # precedence — the template's header literally read "NOTHING BELOW MAY
    # OVERRULE IT" while the cast directive above it read "THIS OVERRIDES ANY
    # CONFLICTING CAMERA LANGUAGE BELOW".
    #
    # With precedence undefined, the model stopped arbitrating by authority and
    # went with whatever line was most concrete — always the literal scene
    # sentence. That is the whole reason MOVE TO rendered as the previous frame
    # with the chosen object pasted into it: the capitals lost to a sentence
    # that said where the player was standing.
    #
    # One sentence group, no markers to match, no precedence to assert.
    travelled = softened_move or movement_type == 'forward_movement'

    if hard_transition and region_change:
        # A different place on the map. Everything the ordinary hard cut keeps —
        # the light, the palette, the indoor/outdoor state — is a property of
        # the place just left, so here it is all explicitly released. What is
        # kept is what actually makes this the same GAME: the film stock, the
        # era, the grain, and the person.
        keep = (
            "Keep only the film stock, the era, the grain and the people — the "
            "same camera and the same cast, somewhere else entirely."
        )
        if cam["shows_body"]:
            lock = cam.get("follow_lock") or (
                "the character stays on screen, medium-wide, seen from behind at chest height"
            )
            camera = (
                "The camera is in a DIFFERENT PLACE ON THE MAP — not another "
                "part of the previous location. The reference photograph is "
                "where they used to be and is NOT where they are: do not keep "
                "its ground, its horizon, its landmarks, its weather, its "
                "palette or its light, and do not keep whether it was indoors "
                "or outdoors. The new place brings its own daylight, its own "
                "weather and its own colour.\n"
                f"{keep}\n"
                "Render the destination the scene names, established and "
                "filling the depth of frame — they have arrived, it is not a "
                "shape on the horizon.\n"
                f"{lock}."
            )
        else:
            camera = (
                "The camera is in a DIFFERENT PLACE ON THE MAP — not another "
                "part of the previous location. The reference photograph is "
                "where it used to be and is NOT where it is: do not keep its "
                "ground, its horizon, its landmarks, its weather, its palette "
                "or its light, and do not keep whether it was indoors or "
                "outdoors. The new place brings its own daylight, its own "
                "weather and its own colour.\n"
                f"{keep}\n"
                "Render the destination the scene names, established and "
                "filling the depth of frame — they have arrived, it is not a "
                "shape on the horizon."
            )
    elif hard_transition:
        # "Carry over only the light, the film stock and the look" was too
        # literal a licence: a run that entered a building and then went deeper
        # through two interior doors grew a purple storm sky over an indoor
        # corridor, because "nothing of the previous location" had been read to
        # include the ceiling. Enclosure is not scenery — going through a door
        # inside a building does not take you outdoors.
        if cam["shows_body"]:
            lock = cam.get("follow_lock") or (
                "the character stays on screen, medium-wide, seen from behind at chest height"
            )
            camera = (
                "The camera is in a NEW PLACE — a different space, not the previous "
                "one rearranged. Carry over the light, the look, and whether this is "
                "indoors or outdoors, unless the scene says the player actually went "
                "in or out. Do not spin to face them or cut to their POV.\n"
                f"{lock}."
            )
        else:
            camera = (
                "The camera is in a NEW PLACE — a different space, not the previous "
                "one rearranged. Carry over the light, the film stock, the look, and "
                "whether this is indoors or outdoors, unless the scene says the "
                "player actually went in or out."
            )
        if holds_reference_frame and travelled:
            # A hard cut normally ships a blurred swatch, so there is no framing
            # to copy and nothing had to say so. Straight out of the opening the
            # reference is a LEGIBLE frame on purpose — the establishing shot the
            # player is standing in — and with nothing forbidding it the model
            # reproduced that composition and called it a move. The harness put a
            # number on it: "Sprint toward the rusted factory" came back at 0.96
            # continuity, the same photograph. Keep the reference for the place,
            # the light and the cast; say plainly that the vantage has moved.
            camera += (
                "\nThe reference photograph is where the camera stood a moment ago, "
                "not where it stands now. The player has MOVED: the camera has "
                "travelled with them, deeper into that same place. Same ground, "
                "same light, same landmarks — a NEW vantage and a NEW distance. "
                "Do not reproduce the reference framing."
            )
        if travelled:
            # "A NEW PLACE — a different space" says the camera moved and never
            # says WHERE, so a travelling hard cut was an unspecified step into
            # whatever the model felt like inventing. The branch that DOES state
            # the arrival is `elif travelled` below, and MOVE TO can never reach
            # it: is_move forces hard_transition unconditionally (see
            # advance_turn_image_fast), so the one camera block written for
            # walking to something never renders on the verb that does it. Say
            # it here as well rather than relaxing the cut — the cut is correct,
            # it was just silent about the destination.
            camera += (
                "\nThe new place is the DESTINATION the scene names, not an "
                "unspecified step further on. They have arrived: it commands "
                "the depth in front of them and what surrounded them a moment "
                "ago is behind them. Do not arrive at some other feature "
                "because it was nearer or more photogenic, and do not leave the "
                "destination a distant shape on the horizon. If they were "
                "outdoors they are still outdoors unless the destination is "
                "itself the way in."
            )
    elif softened_move:
        # Asked to change location; the throttle declined a fresh composition.
        # It still travelled — it just travels as a continuation, not a cut.
        if cam["shows_body"]:
            lock = cam.get("follow_lock") or (
                "They remain visible from behind; what they faced is now around them"
            )
            camera = (
                "The follow camera moved forward WITH the character into what was "
                "ahead. Do not reproduce the reference framing, and do "
                "not turn the lens to face them.\n"
                f"{lock}."
            )
        else:
            camera = (
                "The camera has MOVED FORWARD, through and into what was ahead of "
                "it. What it was facing is now around it; what was beside it has "
                "passed behind. Do not reproduce the reference framing, and do not "
                "turn back toward anywhere already left."
            )
    elif travelled:
        # Walking to something inside the space you are already in: the ground,
        # the light and the landmarks are the established ones. What changes is
        # the distance — and that it changes at all is the point of MOVE TO.
        where = f" Still inside: {prev_setting}." if prev_setting else ""
        # Both halves have to STATE the distance closed and FORBID copying the
        # reference. This was the one movement branch that did neither, and it
        # is the ordinary walk — the most common travelling turn in the game.
        #
        # The follow-cam half was worse than it reads. Its only compositional
        # instruction, "do not fill the frame with the destination alone", is a
        # brake with no accelerator opposite it, and the sentence that WOULD
        # have said the camera closed the distance sat in the default
        # `follow_lock` — which an authored camera block overrides, so on any
        # real world it never rendered at all. Nothing in the payload asked the
        # composition to change, while the previous frame went in as the img2img
        # init. The client harness measured the result: "Sprint toward the
        # utility truck" came back at 0.91 continuity, the same photograph.
        if cam["shows_body"]:
            lock = cam.get("follow_lock") or (
                "They are on screen at the new spot — medium-wide, seen from behind"
            )
            camera = (
                "The follow camera walked with the character to the destination "
                "and stands there now. The destination fills far more of the "
                "frame than it did, and what stood beside the camera has slid "
                f"out past the edges; they are on screen at the new spot.{where} "
                "Same place seen from further in — keep the ground, the light "
                "and the surrounding landmarks. Do not reproduce the reference "
                "framing; do not fill the frame with the destination alone or "
                "flip to a face-on reverse.\n"
                f"{lock}."
            )
        else:
            camera = (
                "The camera has WALKED TO IT and stands there now, close enough to "
                "touch. It fills far more of the frame than it did; what stood "
                f"beside the camera has slid out past the edges.{where} Same place "
                "seen from further in — keep the ground, the light and the "
                "surrounding landmarks. Do not reproduce the reference framing."
            )
    elif movement_type == 'exploration':
        camera = (
            "The camera has panned or tilted slightly from the reference "
            "position. Same spot, new angle."
        )
    else:
        camera = (
            "The camera has NOT moved from the reference position. Only the "
            "environment, the light, or the subject reacts."
        )
        if prev_spatial:
            camera += f" It is looking at: {prev_spatial}"

    prompt = f"CAMERA: {camera}\n\n{prompt}"

    # LEAVE CAMP → new level: forbid vehicle-cabin POVs even if narrative drifts.
    choice_l = (player_choice or "").lower()
    if (
        hard_transition
        and ("leave camp" in choice_l or "not inside any vehicle" in choice_l)
    ):
        prompt = f"{prompt}\n\n{_CAMP_LEAVE_ON_FOOT_CONSTRAINT}"

    # The previous frame's vision analysis, when the async reground actually
    # landed in time, as ONE optional context clause. It used to be pasted into
    # each of four movement branches that restated the CAMERA line above; the
    # camera decision is already made, so this is only description.
    #
    # Withheld on a hard cut, where the previous frame's contents are explicitly
    # moot, and when the scaffold branch above already opened with it — saying it
    # twice is how a 2,000-word prompt gets built one reasonable addition at a
    # time.
    if prev_vision_analysis and not hard_transition and has_visual_scene:
        # Clipped at a word and terminated. A live capture had this landing as
        # "...jeans, and a red  Visual tone: gritty 1993 desert suspense" — the
        # hard [:150] cut mid-word and the caller appends its tone gloss with a
        # space, so the model was handed one run-on sentence that stopped dead
        # on an adjective. An unfinished clause is an invitation to finish it,
        # which is the last thing a description of the PREVIOUS frame should be.
        prompt = (
            f"{prompt}\n\nThe previous frame showed: "
            f"{_clip_sentence(prev_vision_analysis, 150)}"
        )

    return _finish(prompt)

# Stable "scene bible" anchor for the realtime world model (Reactor Happy Oyster).
# Happy Oyster turns a PARAGRAPH OF TEXT into a navigable place you then travel
# through in first person, so every prompt describes a coherent WORLD (space,
# lighting, mood) in a consistent style. We keep this constant across turns so
# the built world maintains one look while the scene text evolves. Style-only
# (NO location) so location comes from the per-turn scene description. Because
# the player navigates with held movement/look (not per-frame prompts), the
# anchor commits to a first-person, walk-through vantage.
REALTIME_STYLE_ANCHOR = os.getenv(
    "REALTIME_STYLE_ANCHOR",
    "A navigable third-person world you can walk through, photographed as a 1993 "
    "photoreal still — muted colour, available light, slight grain, low-light dread. "
    "Eye-level walking vantage with a medium-wide field of view. "
    # World models are trained on a great deal of gameplay footage, and
    # "first-person" plus a motion verb is the strongest FPS cue there is —
    # so they hallucinate a weapon in the lower frame, a crosshair, and a
    # health bar. Nothing downstream can remove them: this path has no
    # negative prompt, so the ban has to live in the anchor itself.
    "Empty hands, nothing held in the lower frame. No weapon, no gun, no crosshair, "
    "no reticle, no HUD, no health bar, no minimap, no on-screen text or game UI of "
    "any kind — this is a photograph of a place, not a video game",
)

# Conversation Moment portraits use a DIFFERENT lens language than the handheld
# camcorder world view — a shallow-DoF cinematic medium shot — so the cut into
# dialogue reads as a register change (Mass Effect / Persona style), not a
# different game. Era/palette stay continuous with the 1993 analog-horror world.
CONVERSATION_PORTRAIT_STYLE_ANCHOR = os.getenv(
    "CONVERSATION_PORTRAIT_STYLE_ANCHOR",
    "stylish cinematic medium shot, 35mm film still, shallow depth of field, "
    "dramatic rim lighting, soft bokeh background, analog-horror 1993 muted palette, "
    "subtle film grain, intimate character portrait from mid-torso up",
)

# Soft budget: how many conversation portraits a single session may mint.
# Cached hits do not count. Prevents runaway cost if a player re-opens TALK a lot.
CONVERSATION_PORTRAIT_BUDGET = int(os.getenv("CONVERSATION_PORTRAIT_BUDGET", "12"))
# Companion plates written from a SCAN crop (not Gemini-invented). Camp
# ignores older files so a leftover player-as-Watcher shot cannot sit at
# the fire.
COMPANION_PORTRAIT_GEN = 2

# In-memory portrait cache: (session_id, subject_label, scene_hash) -> web url.
# Cleared implicitly when the process restarts; disk files remain in session images/.
_PORTRAIT_CACHE: dict = {}
_PORTRAIT_CACHE_LOCK = threading.Lock()
_PORTRAIT_SPEND: dict = {}  # session_id -> count of generations this session

# Camp establishing-shot cache: (session_id, sorted_labels, jeep_hash) -> web url.
# Revisiting camp with the same roster reuses the shot (no re-generation).
_CAMP_CACHE: dict = {}
_CAMP_CACHE_LOCK = threading.Lock()

# How many companions come to the fire, and whether the jeep takes one of the
# image model's six reference slots. Editable while a game is running — see
# tunables.py, which writes straight onto these.
CAMP_COMPANION_CAP = 5
CAMP_INCLUDE_JEEP = True

# The shipped camp shot, used only if `camp_scene_prompt` is missing from the
# prompt file or an edit to it broke a placeholder. Camp must still be able to
# draw itself on a bad edit, so this is the floor — not a second copy anyone is
# expected to maintain. Keep it in step with the default in
# prompts/simulation_prompts.json.
_CAMP_PROMPT_FALLBACK = (
    "{vantage}: handheld establishing shot of a night campsite in {terrain}\n"
    "4:3 frame matching the rest of the game. A small campfire burns in the mid-ground,\n"
    "warm orange firelight pooling on the ground, embers drifting, deep blue-black night sky,\n"
    "Photoreal 1993 still. Not a collage.\n"
    "CRITICAL — THE RED JEEP MUST BE IN FRAME: a dusty bright-red 1990s Jeep "
    "Cherokee/Wrangler parked at the RIGHT edge of the firelight, three-quarter "
    "view, clearly readable silhouette and red paint, mud-caked tires. Do NOT "
    "omit the jeep. Do NOT replace it with a truck or car. The jeep is as "
    "important as the fire.\n"
    "{who}\n"
    "No text, no UI, no letterbox bars inside the image. Photoreal cinematic still."
)

# Fixed seat slots around the fire, keyed by attendee count. Approximate
# tap-target positions (x_pct / y_pct of the establishing shot) — no vision.
_CAMP_SEATS = {
    1: [{"x_pct": 50, "y_pct": 62}],
    2: [{"x_pct": 32, "y_pct": 60}, {"x_pct": 68, "y_pct": 60}],
    3: [{"x_pct": 28, "y_pct": 62}, {"x_pct": 50, "y_pct": 58}, {"x_pct": 72, "y_pct": 62}],
    4: [
        {"x_pct": 22, "y_pct": 64}, {"x_pct": 40, "y_pct": 58},
        {"x_pct": 60, "y_pct": 58}, {"x_pct": 78, "y_pct": 64},
    ],
    5: [
        {"x_pct": 18, "y_pct": 66}, {"x_pct": 34, "y_pct": 58},
        {"x_pct": 50, "y_pct": 55}, {"x_pct": 66, "y_pct": 58},
        {"x_pct": 82, "y_pct": 66},
    ],
}

_JEEP_PROP_PROMPT = (
    "Hero plate of a dusty bright-red 1990s Jeep Cherokee / Wrangler, parked alone "
    "in empty high-desert scrub at dusk. Three-quarter view from the front-left, "
    "vehicle fills most of the frame, weathered paint, mud-caked tires, spare tire "
    "on the back, chrome details dulled by dust. No people, no other vehicles, no "
    "text, photoreal cinematic still, muted 1993 palette."
)

# Bump when camp plate grammar changes so stale jeep-/companion-less caches regenerate.
_CAMP_CACHE_VERSION = "v4-all-companions"

# Canonical LEAVE CAMP → new-level choice. Must keep hard-transition detectors
# ("leave ", "new location") firing, but MUST NOT mention driving / the jeep —
# cab/dashboard POVs break the walkable realtime world model after camp.
_CAMP_LEAVE_CHOICE = (
    "Leave camp and walk into a new outdoor location across the desert — "
    "arrive on foot at eye level with open ground ahead, not inside any vehicle."
)
# Retuned by game_identity.apply() at use (build_image_prompt runs every branch
# through it), so the "first-person eye-level" opener follows the camera switch.
# States where the camera IS, and says nothing about perspective — that is
# game_identity's call, and this rule used to make it twice over.
#
# It opened "first-person eye-level walking vantage", which `retune` dutifully
# rewrote to "third-person …" whenever the player had chosen a third-person
# camera. That handed `reconcile` a line pairing a prohibition ("Do NOT show a
# vehicle interior") with a third-person framing term, which is exactly its
# signature for "a rule that forbids what the active mode requires" — so it
# deleted the line. Retune inserted the word that made reconcile destroy it, and
# the entire no-vehicle-cabin constraint silently stopped shipping in the one
# mode where LEAVE CAMP renders a character on screen. Nothing here names a
# perspective now, so there is nothing for either stage to catch on.
_CAMP_LEAVE_ON_FOOT_CONSTRAINT = (
    "ON-FOOT ARRIVAL: outdoors on open ground, arriving on foot, eye level with "
    "the ground ahead. The camera is NOT inside a vehicle — no cabin interior, "
    "no dashboard, no steering wheel, no windshield frame, no seats. If a vehicle "
    "is in shot at all it is distant or parked, never the camera's location."
)


def _normalize_camp_leave_choice(choice: str, source: Optional[str] = None) -> str:
    """Rewrite LEAVE CAMP turns onto the canonical on-foot arrival choice.

    Older clients still send \"drive the red jeep…\"; that text makes Gemini and
    the world model spawn a driving cab. Always normalize when ``source`` is
    ``camp_leave``, regardless of the raw choice string.
    """
    if (source or "").strip() == "camp_leave":
        return _CAMP_LEAVE_CHOICE
    return choice or ""


def realtime_action_beat(choice: str = "") -> str:
    """The single 'one new element per prompt' motion clause for an action.

    Kept in sync with the client (standalone.js) so an action can be injected
    into the live video instantly — against the current scene — before the full
    turn resolves.
    """
    c = (choice or "").strip().rstrip(".")
    if not c or c.lower() in ("intro", "initialize simulation"):
        return ""
    action = c[0].lower() + c[1:]
    return f"Motion: {game_identity.motion_clause()} {action}."


def build_realtime_base(visual_scene: str = "", narrative: str = "") -> str:
    """The stable part of a realtime prompt: style/camera anchor + physical scene
    description (no action beat). The client recombines this with the live action
    for instant, seamless steering.

    The anchor goes through ``game_identity.world_anchor``, which is the only
    thing making the cast sheet reach this path at all. The world model builds
    a navigable place from this paragraph and nothing else — no negative
    prompt, no directive block, no reference plates — so a hardcoded
    "first-person 1993 VHS desert" anchor meant that selecting third person or
    authoring a level changed every still frame and none of the live world.
    """
    scene = (visual_scene or narrative or "").strip().replace("\n", " ")
    scene = _sanitize_for_image_generation(scene)
    # Keep it focused; overly long prompts dilute the signal for the video
    # model, and the anchor's negatives are the first thing a long scene pushes
    # out of the effective context.
    if len(scene) > 480:
        scene = scene[:477].rstrip() + "..."
    parts = [game_identity.world_anchor(REALTIME_STYLE_ANCHOR).rstrip(". ") + "."]
    if scene:
        parts.append(scene)
    # The level's own geography, so the walkable world keeps returning to the
    # landmarks the player authored instead of inventing fresh ones each turn.
    place = game_identity.place_line()
    if place:
        parts.append(f"The place is {place}")
    return " ".join(parts)


def build_realtime_prompt(visual_scene: str = "", narrative: str = "", choice: str = "") -> str:
    """Compose a clean, natural-language prompt for the realtime world model.

    This is deliberately NOT the still-image diffusion prompt (which is packed
    with model-specific control text — spatial anchors, camera-distance math,
    anti-border/anti-person rules, img2img continuity clauses, world-state dumps).
    Feeding that to a video world model produces incoherent output. Instead we
    follow Happy Oyster's prompt-to-world guidance: a consistent style/vantage
    anchor + a physical description of the PLACE (which already covers
    near/mid/far + lighting) + one action beat. Everything is sanitized the same
    way as the image prompt so we don't regress on content filtering, and the
    whole prompt stays well under Happy Oyster's 2000-character world-prompt cap.
    """
    base = build_realtime_base(visual_scene, narrative)
    beat = realtime_action_beat(choice)
    return base + (" " + beat if beat else "")


# ── Ambient world drift: the text-only simulation tick between turns ──────────
# The turn pipeline is the ONLY thing that ever spoke to the world model, so a
# live stream sat on one unchanging prompt for as long as the player deliberated
# — the video kept moving but the WORLD was frozen at the moment of the last
# choice. A drift tick is a cheap, text-only simulation step for an idle
# session: one small LLM call turns the current world state into ONE concrete
# change, that change is folded back into session state (and into the next
# world-evolution rewrite, so it becomes part of the world's history rather than
# set dressing), and the new render prompt is pushed to the live model as a
# prompt-only re-steer — no still to generate, no turn consumed, no choice used.
#
# The prompt driving it (`world_tick_micro_change_instructions`) has been sitting
# in simulation_prompts.json — phase-gated time-of-day rules and all — with no
# loop to call it.
#
# Cost and correctness are bounded four ways: a server-enforced minimum
# interval (a spammy client cannot buy extra ticks), a per-decision-point
# budget, a hard skip while a real turn is in flight (drift must never race the
# turn pipeline for the world prompt), and a process-wide single-flight guard.
#
# OFF BY DEFAULT. Production serves the whole game from ONE gunicorn worker with
# only GUNICORN_THREADS (default 4) threads, shared by every client's 1.5s feed
# poll, status poll, resets and turns. An extra endpoint that every connected
# client hits on a timer is a real risk to that budget, so this stays opt-in
# until it has been exercised against a live deploy: set WORLD_DRIFT=1.
WORLD_DRIFT_ENABLED = os.getenv("WORLD_DRIFT", "0").strip().lower() not in ("0", "false", "no", "off")
try:
    WORLD_DRIFT_MIN_INTERVAL_S = max(5.0, float(os.getenv("WORLD_DRIFT_INTERVAL", "20")))
except ValueError:
    WORLD_DRIFT_MIN_INTERVAL_S = 20.0
try:
    WORLD_DRIFT_MAX_PER_TURN = max(0, int(os.getenv("WORLD_DRIFT_MAX_PER_TURN", "8")))
except ValueError:
    WORLD_DRIFT_MAX_PER_TURN = 8
# How many drift beats we keep on state: enough to stop the LLM repeating itself
# and to hand the next world-evolution pass what changed while nobody acted.
WORLD_DRIFT_BEATS_KEPT = 6
# The instruction block for a drift beat.
#
# Carried here rather than in simulation_prompts.json on purpose. The editable
# prompt surface is deliberately ranked down to the few prompts that are worth a
# designer's attention, and this text was pruned from it once as a "dead knob"
# (correctly — nothing called it yet). A feature must not silently become a
# no-op because its prompt was tidied away, so this is the default and the JSON
# key is an override that's honoured when someone chooses to expose it again.
_WORLD_DRIFT_INSTRUCTIONS = """{location_context} TIME PASSES. Describe substantial change in {environment_type} based on the actions.

Write ONE vivid sentence (max 15 words). Match the environment you're actually in. Include sound when dramatic.

In 'normal' phase, developments should be minor and occasional (e.g., a single unexpected detail like a helicopter rumble or new graffiti). In 'escalating' phase, allow moderate world intrusions. In 'critical' phase, frequent major events may occur.

CRITICAL RULES:
- If you're INSIDE, describe INDOOR changes (lights, sounds, alarms, equipment, footsteps).
- If you're OUTSIDE, describe OUTDOOR changes (wind, metal sounds, distant gunfire, engines).
- DO NOT describe outdoor elements if indoors, and vice versa.
- Describe small physical/sound/atmospheric changes
- Be specific and grounded

TIME OF DAY:
- Do not change the time of day or the lighting. The evening of this run is already set.
- Never invent weather changes (no storms, no sudden night)."""

# Process-wide single-flight: at most ONE drift LLM call in flight, ever.
# Guarded by its own lock because the check and the set are far apart (a state
# load and five gates sit between them): two request threads for DIFFERENT
# sessions would otherwise both read False and both spawn, which is exactly the
# thread-budget exhaustion the guard exists to prevent. Same-session races are
# already handled by the last_drift_ts claim under WORLD_STATE_LOCK.
_DRIFT_LOCK = threading.Lock()
_drift_worker_active = False


def _turn_in_flight() -> bool:
    """Is a turn (or reset, or scene render) currently holding TURN_LOCK?

    Probed rather than read: TURN_LOCK is an RLock, which exposes no locked(),
    and a drift must NOT take the lock — it isn't a turn and has no business
    delaying one. Because RLock is reentrant per-thread this only answers
    correctly for a caller that doesn't already hold it, which is exactly the
    drift path (a plain request thread).
    """
    if TURN_LOCK.acquire(blocking=False):
        TURN_LOCK.release()
        return False
    return True


def _drift_environment_type(st: dict, hist: list) -> str:
    """The environment the drift must stay inside (indoor/outdoor + kind).

    Vision already records this per turn as `setting_type` ("indoor-corridor",
    "outdoor-desert", …) — reuse it rather than re-deriving, so a drift can't
    put wind and dust inside a sealed lab.
    """
    for entry in reversed(hist or []):
        setting = (entry.get("setting_type") or "").strip()
        if setting:
            return setting
    # Vision may never have run (no key, or the frame landed after Phase 2).
    # The render base still says where we are, so read it rather than giving the
    # drift no environment at all.
    return classify_setting((st or {}).get("current_render_base") or "") or "the current environment"


def _drift_location_context(st: dict) -> str:
    """The place a drift beat happens in, as the world model already sees it."""
    base = (st.get("current_render_base") or "").strip()
    if base:
        return "WHERE YOU ARE RIGHT NOW: " + base[:700]
    return ""


def _world_drift_beat(st: dict, hist: list) -> str:
    """One concrete present-tense change in the world right now (text only).

    Deliberately small and cheap: no vision, no image, one short completion.
    Returns "" when there's nothing usable, and the caller skips the tick.
    """
    if not LLM_ENABLED:
        return ""
    tmpl = (PROMPTS.get("world_tick_micro_change_instructions") or "").strip() \
        or _WORLD_DRIFT_INSTRUCTIONS
    try:
        head = tmpl.format(
            location_context=_drift_location_context(st),
            environment_type=_drift_environment_type(st, hist),
        )
    except (KeyError, IndexError, ValueError):
        head = tmpl
    recent = list(st.get("ambient_beats") or [])[-WORLD_DRIFT_BEATS_KEPT:]
    sections = [
        head,
        "PHASE: {} \u00b7 THREAT: {}".format(
            st.get("current_phase", "normal"), int(st.get("threat_level", 0) or 0)
        ),
        "TIME OF DAY: {}".format(st.get("time_of_day") or "unspecified"),
        "THE PLAYER'S LAST ACTION: {}".format(st.get("last_choice") or "none yet"),
    ]
    if recent:
        sections.append(
            "ALREADY DRIFTED SINCE THAT ACTION (do not repeat, build on these):\n"
            + "\n".join("- {}".format(b) for b in recent)
        )
    sections.append(
        "The player has NOT acted since. Nobody moves the camera and nothing the "
        "player does happens here \u2014 only the world itself changes. Describe a "
        "PHYSICAL change, never a camera move.\n"
        "Return ONLY the sentence."
    )
    try:
        beat = (_ask("\n\n".join(s for s in sections if s), temp=0.9, tokens=60,
                     use_lore=False) or "").strip()
    except Exception as e:
        log_error(f"[DRIFT] beat generation failed: {e}")
        return ""
    # One sentence, no labels, no quotes — this text is appended straight onto
    # the world model's scene prompt.
    beat = beat.split("\n")[0].strip().strip('"').strip("'")
    for label in ("CHANGE:", "TICK:", "WORLD:", "DRIFT:"):
        if beat.upper().startswith(label):
            beat = beat[len(label):].strip()
    words = beat.split()
    if len(words) > 24:
        beat = " ".join(words[:24]).rstrip(",;:") + "."
    if beat and not beat.endswith((".", "!", "?")):
        beat += "."
    return beat if len(beat) > 12 else ""


def world_drift_tick(session_id: str = 'default', background: bool = False) -> dict:
    """Run ONE text-only simulation step for an idle session.

    Appends a `world_drift` feed item whose metadata carries the re-steer prompt
    (scene base + the new beat) and NO image, which is exactly the shape the
    client already applies as a prompt-only hot-swap on the running stream.

    Returns {"ok": bool, "skipped": <reason>|None, "beat": str}. Every refusal
    is a named reason rather than an error: the client ticks optimistically and
    the server decides whether the world has earned a drift.

    background=True does all the cheap gating inline (one small JSON read) and
    then hands the LLM call to a worker thread, returning immediately. That is
    what the HTTP endpoint uses: production serves everything from one gunicorn
    worker with a handful of threads, so an endpoint every client polls must
    never sit on one of them waiting on a model.
    """
    if not WORLD_DRIFT_ENABLED:
        return {"ok": False, "skipped": "disabled"}
    # Never let drift ticks stack up process-wide. With several players (or
    # tabs) polling, unguarded ticks would run one LLM call each and exhaust the
    # thread budget the actual game needs.
    if _drift_worker_active:
        return {"ok": False, "skipped": "busy"}
    st = _load_state(session_id)
    if not st.get("player_state", {}).get("alive", True):
        return {"ok": False, "skipped": "dead"}
    if int(st.get("turn_count", 0) or 0) < 1:
        return {"ok": False, "skipped": "no_turns_yet"}
    if not (st.get("current_render_base") or "").strip():
        # Nothing to build a re-steer on yet (no scene has been rendered).
        return {"ok": False, "skipped": "no_scene"}
    # A turn owns the world prompt while it runs; drifting into it would fight
    # the consequence the player is waiting for.
    if _turn_in_flight():
        return {"ok": False, "skipped": "turn_in_flight"}
    if int(st.get("drift_count", 0) or 0) >= WORLD_DRIFT_MAX_PER_TURN:
        return {"ok": False, "skipped": "budget_spent"}

    now = time.time()
    # Claim this tick's slot BEFORE the LLM call, under the lock, so overlapping
    # polls (or two tabs on one session) can't each buy a drift.
    with WORLD_STATE_LOCK:
        st = _load_state(session_id)
        if now - float(st.get("last_drift_ts", 0) or 0) < WORLD_DRIFT_MIN_INTERVAL_S:
            return {"ok": False, "skipped": "too_soon"}
        st["last_drift_ts"] = now
        _save_state(st, session_id)
        _sync_ambient_state(st, session_id)

    if background:
        if not _spawn_world_drift(session_id, st):
            return {"ok": False, "skipped": "busy"}
        return {"ok": True, "skipped": None, "queued": True}
    return _world_drift_publish(session_id, st)


def _spawn_world_drift(session_id: str, st: dict) -> bool:
    """Run the drift's LLM call + publish OFF the request thread.

    Returns False when another drift is already in flight process-wide.
    """
    global _drift_worker_active
    # Claim atomically — a plain check-then-set lets two sessions both through.
    with _DRIFT_LOCK:
        if _drift_worker_active:
            return False
        _drift_worker_active = True

    def _worker():
        global _drift_worker_active
        try:
            _world_drift_publish(session_id, st)
        except Exception as e:
            log_error(f"[DRIFT] worker failed: {e}")
        finally:
            with _DRIFT_LOCK:
                _drift_worker_active = False

    try:
        threading.Thread(target=_worker, daemon=True).start()
        return True
    except Exception as e:
        with _DRIFT_LOCK:
            _drift_worker_active = False
        log_error(f"[DRIFT] could not spawn worker: {e}")
        return False


def _world_drift_publish(session_id: str, st: dict) -> dict:
    """Generate the beat and append it to the feed. Assumes the slot is claimed."""
    base = (st.get("current_render_base") or "").strip()
    beat = _world_drift_beat(st, _load_history(session_id))
    if not beat:
        return {"ok": False, "skipped": "no_beat"}

    render_prompt = base + " " + beat
    item = create_feed_item(
        type="world_drift",
        content=beat,
        metadata={
            "prompt": render_prompt,
            "base": base,
            # Marks this as an ambient re-steer, NOT a new scene: no image, no
            # transition, and the client must not treat it as a turn resolving.
            "drift": True,
            "hard_transition": False,
            "phase": st.get("current_phase", "normal"),
        },
    )
    with WORLD_STATE_LOCK:
        st = _load_state(session_id)
        st["current_render_prompt"] = render_prompt
        beats = list(st.get("ambient_beats") or [])
        beats.append(beat)
        st["ambient_beats"] = beats[-WORLD_DRIFT_BEATS_KEPT:]
        st["drift_count"] = int(st.get("drift_count", 0) or 0) + 1
        _feed_append(st, item)
        _save_state(st, session_id)
        _sync_ambient_state(st, session_id)
    print(f"[DRIFT] {session_id} #{st.get('drift_count')}: {beat}", flush=True)
    return {"ok": True, "skipped": None, "beat": beat, "item": item}


def api_world_tick():
    """One text-only simulation step for an idle session (see world_drift_tick).

    Client-driven on purpose. A server-side timer would keep ticking (and
    billing) sessions nobody is watching, and would have to guess which of them
    still have a live stream; the client knows both, and stops the moment the
    tab is hidden or the renderer isn't live. The server still owns the pacing,
    so the client can only ever ASK.

    Always returns immediately: the gating is a small JSON read and the model
    call runs on a worker thread (see world_drift_tick's background flag), so
    this endpoint can never occupy one of the few gunicorn threads the rest of
    the game is sharing.
    """
    try:
        session_id = _resolve_request_session_id()
        return jsonify(world_drift_tick(session_id, background=True))
    except Exception as e:
        log_error(f"[DRIFT] tick failed: {e}")
        return jsonify({"ok": False, "error": str(e)}), 500


def _build_vhs_prompt(base_prompt: str, use_img2img: bool = False) -> str:
    """Render the shared image template for the OpenAI path.

    Look lives in `image_art_direction`. This wrapper only adds the
    first-person empty-frame rule when the camera is nobody's eyes.
    """
    # Load the appropriate template from simulation_prompts.json
    if use_img2img:
        template_key = "gemini_image_to_image_instructions"
    else:
        template_key = "gemini_text_to_image_instructions"
    
    structured_prompt = prompts_store.render_image_template(template_key, base_prompt)
    
    # Empty-frame rule — but ONLY while the camera is supposed to be nobody's
    # eyes. In any third-person mode the player has explicitly asked to see
    # their character, so this block would argue against the thing they asked for.
    if game_identity.shows_character():
        anti_person = ""
    else:
        anti_person = (
            "\n\nNo person in frame: no head, shoulders, back, hands, or silhouette. "
            "Show only the environment."
        )
    
    full_prompt = structured_prompt + anti_person

    # Retune/reconcile the wrapper's own perspective language. `base_prompt`
    # arrives already stamped with the camera directive by build_image_prompt();
    # this pass catches the first-person wording baked into the JSON template
    # and the constant blocks above it. "raw" so we don't stack a second
    # directive on top of the one already in there.
    full_prompt = game_identity.apply(full_prompt, "raw")

    # Add negative prompt for extra safety (used by some providers), rewritten
    # so it stops banning whichever perspective is currently selected.
    negative_prompt_text = game_identity.negative_prompt()
    if negative_prompt_text:
        full_prompt += f"\n\nNEGATIVE PROMPT (avoid these): {negative_prompt_text}"
    
    return full_prompt


# ───────── flipbook prompt blocks ───────────────────────────────────────────
# A flipbook grid is ONE image, so whatever these blocks say is inherited
# by every panel — and they shipped hard-wired to a chest-mounted first-person
# body cam that explicitly invalidated "camera following a character" shots.
# That is the exact shot the third-person modes ask for, so a flipbook run used
# to ignore the camera switch no matter what the rest of the prompt said. The
# first-person text below is preserved verbatim (it is the shipped default and
# heavily tuned); the hero variants are the new branch.

def _flipbook_camera_block(also_visible: str = "") -> str:
    """The flipbook grid's camera contract, written for the active perspective.

    ``also_visible`` is a second body that must survive the grid — the encounter
    plate's stranger. The forbidden list below is written for a solo shot, so on
    a two-shot it named only the protagonist and the model was free to satisfy
    every rule it could see by drawing the player alone.
    """
    cfg = game_identity.mode_config()
    rule = "═" * 63
    head = f"{rule}\n🎥 CAMERA: {cfg['camera_header']} — WIDE ANGLE\n{rule}\n\n"

    if not cfg["shows_body"]:
        body = (
            "• First-person POV, camera strapped to player's chest/head\n"
            "• 28-35mm equivalent field of view (WIDE — show MORE environment)\n"
        )
        if game_identity.hands_visible():
            body += "• Hands may appear at frame bottom when reaching/interacting\n"
        body += (
            "\nFORBIDDEN (third-person shots will invalidate the entire grid):\n"
            "❌ Showing player from behind, side, or above\n"
            "❌ 'Camera following a character' shots\n"
            "❌ Any frame showing the player's body as a separate entity\n"
        )
    else:
        who = game_identity.display_name()
        body = f"• {cfg['rig'][:1].upper()}{cfg['rig'][1:]}\n"
        body += "• 28-35mm equivalent field of view (WIDE — show MORE environment)\n"
        for image_rule in cfg["image_rules"]:
            body += f"• {image_rule}\n"
        body += (
            f"\nFORBIDDEN (these will invalidate the entire grid):\n"
            f"❌ Any panel where {who} is not visible\n"
            f"❌ Cutting to what {who} sees instead of showing {who}\n"
            f"❌ {who} changing face, build, hair, or outfit between panels\n"
            # The rig used to be stated once and then contradicted by the grid
            # rules' tripod line; a 2x2 came back with panel 1 face-on and the
            # camera swinging round behind the character over the next three.
            f"❌ The camera changing sides, height or distance between panels, "
            f"or swinging round to face {who} — it is behind them in panel 1 "
            f"and behind them at the same distance in every panel after\n"
        )
    if also_visible:
        body += f"❌ Any panel where {also_visible} is not visible\n"
    return head + body + f"\n{rule}\n\n"


def _flipbook_fps_keyframes(end_state: str, frames: int) -> str:
    """The body-cam version of the START / END contract: the view, not a body."""
    frames = flipbook.normalize_frames(frames)
    end_state = (end_state or "").strip()
    text = (
        "START (panel 1): the exact view in the START KEYFRAME reference, the "
        "instant after it — same heading, same height, same place. The horizon "
        "sits at the same height in the frame in every panel: on a body cam "
        "that is the anchor the eye holds, and a horizon that jumps between "
        "panels reads as a cut.\n"
    )
    text += (f"END (panel {frames}): {end_state}\n" if end_state else
             f"END (panel {frames}): the action completed, the view settled.\n")
    if frames > 2:
        text += (f"BETWEEN: {frames - 2} evenly spaced in-betweens of that one "
                 "move — not a storyboard of the story.\n")
    return text + "\n"


def _flipbook_keyframes(who: str, end_state: str, frames: int,
                        travels: bool = False) -> str:
    """START / END / BETWEEN — the one thing the flipbook prompt never said.

    Every line of the flipbook prompt described the motion (time advances,
    the action has visibly happened, even steps) and none of it said what the
    FIRST pose was. The model had to pick one, and with a face-on character
    sheet in reference slot 1 it picked that: panel 1 came back as a portrait
    walking toward the lens, and the next three panels swung the camera round
    behind the character to satisfy the follow-cam rules. Played at 400ms a
    panel that is a camera that jumps sides every frame. The start pose IS
    known — it is the previous sequence's last panel, attached and now
    labelled START KEYFRAME — and the end pose is the scene the turn already
    wrote. Say both, and the in-betweens have something to be between.

    ``end_state`` is the turn's `visual_scene` (the caption), not the
    consequence prose: the prose is several beats long ("you sprint… you reach
    the door… you slam into it") and handed to "ANIMATE THIS" it was
    storyboarded, one beat per panel. It stays in the prompt as context.
    """
    frames = flipbook.normalize_frames(frames)
    who = who or "the player"
    end_state = (end_state or "").strip()
    start = (
        f"START (panel 1) — {who} exactly as the START KEYFRAME reference shows "
        f"them: the same spot, the same stance, the camera in the same place "
        f"behind them, the instant they begin this action. Framed the way that "
        f"reference frames them, too — {who} in the same part of the picture, "
        f"at the same size on screen.\n"
    )
    if end_state:
        end = f"END (panel {frames}) — {end_state}\n"
    else:
        end = (
            f"END (panel {frames}) — the action completed, {who} settled in the "
            f"scene the render instruction describes.\n"
        )
    # The rig is stated once for panel 1 and the grid drifted to a face-on
    # by panel 4 (the character sheet, a portrait, is still attached). Say it
    # about the END too: the camera never crossed to their front.
    end += (
        f"Panel {frames} is shot from the SAME side as panel 1 — the camera "
        f"is still behind {who}, at the same height; it never crossed to "
        f"their front on the way. AND THE SAME FRAMING: {who} is in the same "
        f"part of the picture, at the same size on screen, as in panel 1. The "
        f"place around them has changed; the shot has not. A panel {frames} "
        f"that moves {who} across the frame or changes how big they are is "
        f"the jolt a player sees at the end of every beat.\n"
    )
    # The render instruction at the foot of the prompt is the still path's,
    # and on a move it says "the camera has travelled … do not reproduce the
    # reference framing". True of the END panel; read against panel 1 it is
    # the opposite of the contract above.
    end += (
        f"(The render instruction at the end of this prompt describes panel "
        f"{frames}. Where it says the camera has moved, or not to reproduce "
        f"the reference framing, it means panel {frames} — panel 1 still "
        f"continues the START KEYFRAME.)\n"
    )
    if frames > 2:
        between = (
            f"BETWEEN (panels 2 to {frames - 1}) — {frames - 2} evenly spaced "
            f"in-betweens of that ONE motion, from the start pose to the end "
            f"pose"
            + (", the camera travelling behind them the whole way" if travels
               else "")
            + ". Not a storyboard of the story: one move, sampled — and "
            f"never a step back toward the START pose once it has been left. "
            f"{who} stays in the same part of the frame at the same size the "
            f"whole way through: it is the WORLD that slides past them.\n"
        )
    else:
        between = ""
    return start + end + between


def _flipbook_action_block(choice: str, dispatch_preview: str, is_free_will: bool,
                           frames: int = None, *, end_state: str = "",
                           travels: bool = False) -> str:
    """The 'animate exactly this action' header, in the active perspective.

    `frames` is the active grid's panel count. It used to be the literal 16 in
    three sentences here, which quietly contradicted the grid the rest of the
    prompt asked for the moment the count became a setting.

    `end_state` is the turn's visual_scene — the END keyframe. `travels` is a
    relocating turn: the same contract, with the camera going with them. See
    _flipbook_keyframes for why the contract exists.
    """
    frames = flipbook.normalize_frames(frames if frames is not None else FLIPBOOK_FRAMES)
    seconds = _flipbook_seconds(frames)
    if game_identity.shows_character():
        cfg = game_identity.mode_config()
        who = game_identity.display_name()
        header = (
            f"🎬🎬🎬 {cfg['camera_header']} — THE CHARACTER IS ON SCREEN 🎬🎬🎬\n\n"
            f"This is {cfg['label'].lower()} game footage. The camera is {cfg['rig']}.\n"
            f"{who} is visible in EVERY panel, performing the action with their whole body.\n"
            f"Do NOT cut to what {who} sees — show {who} doing it.\n\n"
        )
        keyframes = _flipbook_keyframes(who, end_state, frames, travels=travels)
        if is_free_will:
            command = (
                "ABSOLUTE COMMAND - FREE WILL ACTION\n\n"
                "The player used FREE WILL to command this EXACT action:\n"
                f">>> \"{choice}\" <<<\n\n"
                "YOU MUST OBEY THIS COMMAND AT ALL COSTS.\n\n"
                + keyframes + "\n"
            )
            tail = f"Context (what happens as result): {dispatch_preview}\n\n"
        else:
            command = (
                "CRITICAL INSTRUCTION - READ THIS FIRST\n\n"
                f"THE ACTION THESE {frames} PANELS ANIMATE, START TO END:\n"
                f">>> {choice} <<<\n\n"
                + keyframes + "\n"
            )
            tail = (
                "What happens during it — why the END looks the way it does. "
                "Context, not extra beats to draw: "
                f"{dispatch_preview}\n\n"
            )
        rules = (
            "ABSOLUTE RULES:\n"
            f"1. {who} is the subject of every panel — never an empty environment shot\n"
            f"2. The camera trails {who} at the same height, on the same side and "
            f"at the same distance in every panel; it never becomes their eyes "
            f"and never swings round to face them\n"
            f"3. Face, build, hair, and outfit are identical across all {frames} panels\n"
            "4. Show stance, reach, weight, and momentum — the body doing the work\n"
            f"5. The {frames} panels are {seconds:g} seconds of {who} performing "
            f"this one action, from the START pose to the END pose\n"
            # START / END / seconds are direction, and one roll in six drew
            # "T=0s … T=1.7s" into the corners from them. The grid rules ban
            # text further down; say it here, next to the words that cause it.
            f"6. None of these words are drawn. No \"START\", no \"END\", no "
            f"\"T=0s\", no timecode, no panel number, no caption anywhere in "
            f"the picture\n\n"
        )
        return header + command + rules + tail + "=" * 70 + "\n\n"

    if is_free_will:
        return (
            "🚫🚫🚫 FIRST-PERSON ONLY - NO 3RD PERSON ALLOWED 🚫🚫🚫\n\n"
            "THIS IS BODY CAM FOOTAGE. The camera IS the player's eyes.\n"
            "DO NOT show 'a man walking' or 'a person' from outside.\n"
            "Show ONLY what the player's eyes see while performing the action.\n\n"
            "ABSOLUTE COMMAND - FREE WILL ACTION\n\n"
            "The player used FREE WILL to command this EXACT action:\n"
            f">>> \"{choice}\" <<<\n\n"
            "YOU MUST OBEY THIS COMMAND AT ALL COSTS.\n\n"
            + _flipbook_fps_keyframes(end_state, frames) +
            "ABSOLUTE RULES:\n"
            "1. Show FIRST-PERSON perspective - you ARE the player, camera = your eyes\n"
            "2. DO NOT show 'a man' or 'a person' - that's 3rd person (FORBIDDEN)\n"
            "3. Show what YOUR EYES see while performing the action\n"
            "4. If 'head towards vehicles' -> show vehicles getting closer in YOUR view\n"
            "5. If 'climb fence' -> show YOUR hands grabbing fence from YOUR POV\n"
            "6. If 'run to tower' -> show ground/tower from running POV\n"
            f"7. The flipbook shows {seconds:g} seconds of this action from YOUR eyes\n"
            "8. NEVER show the player as a separate person/character\n\n"
            f"Context (what happens as result): {dispatch_preview}\n\n"
            + "=" * 70 + "\n\n"
        )
    return (
        "🚫🚫🚫 FIRST-PERSON ONLY - NO 3RD PERSON ALLOWED 🚫🚫🚫\n\n"
        "THIS IS BODY CAM FOOTAGE. The camera IS the player's eyes.\n"
        "DO NOT show 'a man walking' or 'a person' from outside.\n"
        "Show ONLY what the player's eyes see while performing the action.\n\n"
        "CRITICAL INSTRUCTION - READ THIS FIRST\n\n"
        "YOU MUST ANIMATE THIS SPECIFIC ACTION:\n"
        f">>> {choice} <<<\n\n"
        + _flipbook_fps_keyframes(end_state, frames) +
        f"What happens during it (context, not extra beats to draw): "
        f"{dispatch_preview}\n\n"
        "RULES:\n"
        "1. FIRST-PERSON PERSPECTIVE - Show what YOUR eyes see (NOT a person from outside)\n"
        "2. Show EXACTLY what the text describes from first-person POV\n"
        "3. If text says 'approach' -> show target getting closer in YOUR view\n"
        "4. If text says 'examine' -> show object filling YOUR view\n"
        "5. NEVER show 'a man' or 'a person' - that's 3rd person (FORBIDDEN)\n"
        "6. You ARE the player - camera = your eyes - no external views\n\n"
        + "=" * 70 + "\n\n"
    )


def _flipbook_confrontation_block(other: str, look: str, beat: str,
                                  frames: int = None) -> str:
    """A TWO-SHOT beat: both bodies, every panel, for an encounter grid.

    The ordinary action block is written for a solo protagonist — "<who> is the
    subject of every panel", "never an empty environment shot" — and an encounter
    is the one beat where that is the wrong cast. Handed the solo block, the model
    satisfied every rule it could see by animating the player alone and the
    stranger it had been asked for was never drawn.

    `beat` is what the two of them are doing. The encounter callers used to leave
    it empty, so it fell through to the caption and the grid was told to animate
    the literal string "encounter_Horizon facility surveyor".
    """
    frames = flipbook.normalize_frames(frames if frames is not None else FLIPBOOK_FRAMES)
    seconds = _flipbook_seconds(frames)
    who = (game_identity.display_name() if game_identity.shows_character()
           else "the player")
    other = (other or "the other person").strip()
    look = (look or "").strip()
    block = (
        "🎬🎬🎬 TWO-SHOT — A CONFRONTATION, NOT A SOLO SHOT 🎬🎬🎬\n\n"
        f"TWO people are in this frame: {who}, and {other}.\n"
        + (f"{other} is {look}.\n" if look else "")
        + f"BOTH are in ALL {frames} panels. {other} is already standing there "
        f"in panel 1 and is still there in panel {frames} — not off-screen, not "
        f"implied, not arriving later, not left for a following shot.\n"
        f"A panel containing only {who} is a FAILED panel.\n"
        f"{other} is a DIFFERENT person from {who}: different face, different "
        f"build, different clothes in different colours. Not a second copy of "
        f"{who}, and not wearing any part of their outfit.\n\n"
    )
    if beat:
        block += (
            "WHAT THE PANELS ANIMATE:\n"
            f">>> {beat} <<<\n"
            f"The {frames} panels are {seconds:g} seconds of that, played between "
            f"the two of them — {who} reacting, {other} pressing in. Both "
            f"bodies move; neither leaves the frame.\n\n"
        )
    return block + "=" * 70 + "\n\n"


# The first playable frame is img2img'd from the montage's WIDEST panel (see
# _montage_place_refs), and that panel is now required to carry the level's goal
# on its skyline. So the goal reaches this frame for free — as long as nothing
# here quietly drops it. "Same landmarks" was doing that job by implication and
# losing: the block goes on to ask for something unreadable approaching in the
# far distance, and given two things to put on one horizon the model kept the
# one it had just been told about and dropped the one it had to read out of the
# reference. Reported as "I never see that in the opening montage or opening
# image".
_KEEP_THE_HORIZON = (
    "WHAT IS ON THE HORIZON STAYS ON THE HORIZON.\n"
    "If the reference photograph has a structure, tower, rig or landmark "
    "standing on its skyline, it is STILL THERE in this frame: same place in "
    "the composition, same distance, same size, unreached. It is what the "
    "character is looking at and what the level is about walking to. Do not "
    "crop it out, do not move it, do not close the distance to it, and do not "
    "replace it with weather.\n\n"
)


def _flipbook_establishing_block_base(frames: int = None, *,
                                      single: bool = False) -> str:
    """A held ESTABLISHING beat: an IDLE, played with the camera locked off.

    The action block walks the character across the panels — exactly wrong for an
    opening, which walked the player out of the montage's frame and landed the
    run somewhere the reference never showed. This pins the composition, so the
    last panel is still the establishing view the player then acts from.

    What it no longer pins is the character. "Stands still, same pose, same spot"
    got precisely what it asked for and it read as nothing: a figure rocking a
    few pixels back and forth for eight seconds, which is the first thing a
    player ever sees of the person they are playing. The fix is the idle
    animation a game holds on while it waits for input — weight settling, a hand
    going over the gear, then the head coming up at something far off that has
    not arrived. Feet planted and camera locked, but somebody alive, standing in
    a place where something is wrong.

    The reference is now the montage's own widest panel, which is DELIBERATELY
    unpeopled — the opening montage bans figures from all four shots. So this
    also has to ask for the character to be put INTO the photograph, in the
    composition the game goes on to use. That used to be the separately
    rendered plate's job, and having a second render decide where the level was
    is exactly what made the opening incoherent.

    ``single`` drops the grid language for the no-flipbook fallback, which needs
    the same instruction as one photograph rather than four panels.
    """
    frames = flipbook.normalize_frames(frames if frames is not None else FLIPBOOK_FRAMES)
    seconds = _flipbook_seconds(frames)
    who = game_identity.display_name() if game_identity.shows_character() else ""
    if who:
        idle = (
            f"· FIRST, {who} SETTLES: weight coming down onto one leg, shoulders "
            "dropping, the stillness of somebody who has just stopped walking.\n"
            f"· THEN {who} CHECKS THEIR GEAR: one hand going over what they are "
            "already carrying — tightening a strap, feeling for something in a "
            "pocket, turning a tool or a weapon over once and letting it hang. "
            "Hands stay close to the body. Nothing new appears in them.\n"
            f"· THEN {who} LOOKS UP AND OUT: the head lifting and turning toward "
            "the far distance, and going still — caught by something out there.\n"
        )
        closing = (
            f"{who} is standing in the same spot, planted, head up and looking off "
            "at it"
        )
    else:
        idle = (
            "· FIRST THE BREATH SETTLES: the horizon rocking a fraction and coming "
            "to rest, the stillness of somebody who has just stopped walking.\n"
            "· THEN YOU CHECK YOUR GEAR: your own hands entering the bottom of the "
            "frame over what you are already carrying — a strap, a pocket, a tool "
            "or a weapon turned over once and lowered again. Nothing new appears "
            "in them.\n"
            "· THEN YOU LOOK UP AND OUT: the view lifting and settling on the far "
            "distance, holding there.\n"
        )
        closing = "your hands are down and the view is settled on the far distance"

    # The reference photographs are the montage, and the montage is unpeopled by
    # instruction. Every rule below that says "as the reference" is about the
    # PLACE; the person has to be added, and added in the composition the rest
    # of the game shoots in, because this frame is turn one's img2img anchor.
    cast_in = (
        "WHO IS IN IT — THE REFERENCE PHOTOGRAPHS HAVE NOBODY IN THEM.\n"
        f"They are photographs of the PLACE. Put {who or 'the player'} into that "
        "place: same location, same light, same weather, same ground, same "
        "landmarks, standing in it now.\n"
        + (f"{who} is the subject — standing at a natural distance for a "
           "person in this space, seen from BEHIND, reading at roughly a third "
           "to a half of the frame height, with the place opening away beyond "
           "them so it stays legible. Not a portrait, not a silhouette, not a "
           "speck on the horizon.\n"
           if who else
           "The camera is their eyes: no body, no back, no face — only what "
           "they can see, and their own hands when they come up.\n")
        + "Take the wardrobe and the face from the character reference, not "
          "from the place.\n\n"
    )
    if single:
        return (
            "🎬 THE FIRST PLAYABLE FRAME — AN IDLE, CAMERA LOCKED OFF 🎬\n\n"
            "ONE photograph. The moment the player takes control.\n\n"
            + cast_in + _KEEP_THE_HORIZON +
            "THE POSE: settled, having just stopped walking — weight on one leg, "
            "a hand resting on the gear they already carry, head up and looking "
            "off at something in the far distance. Alive and waiting, not posed "
            "for the camera.\n\n"
            "IN THE FAR DISTANCE: something is coming and has NOT arrived — a "
            "smear of dust on the horizon, a stain in the light. Unreadable, "
            "never identified, never closer than the deep distance.\n\n"
            "Settled and readable: no blur, no half-finished gesture. Do NOT "
            "introduce locations, structures, vehicles or creatures that are not "
            "in the reference.\n\n"
            + "=" * 70 + "\n\n"
        )
    return (
        "🎬 ESTABLISHING SHOT — AN IDLE, CAMERA LOCKED OFF 🎬\n\n"
        f"This is the opening: {seconds:g} seconds of a HELD frame with somebody "
        "alive standing in it. NOT a journey, NOT an action, NOT a camera move.\n\n"
        + cast_in + _KEEP_THE_HORIZON +
        "THE IDLE, IN ORDER ACROSS THE PANELS:\n"
        + idle +
        "\n"
        "WHAT IS HAPPENING IN THE FAR DISTANCE:\n"
        "Behind and beyond all of that, something is coming and has NOT arrived. "
        "Across the panels it grows by a touch and stays unreadable: a smear of "
        "dust lifting on the horizon, a stain in the light over there, birds "
        "coming up off something too far away to see. It never gets closer than "
        "the deep distance, it is never identified, and it never enters the "
        "middle or the foreground. Dread, not an event.\n\n"
        "ABSOLUTE RULES:\n"
        f"1. All {frames} panels are the SAME framing, the SAME camera position, "
        "the SAME lens and the SAME composition as each other — pick the shot "
        "once and hold it. Do NOT move the camera, do NOT push in, do NOT change "
        "the vantage, do NOT cut to a new angle between panels.\n"
        "2. The figure does NOT walk, does NOT cross the frame, does NOT change "
        "which way their feet point, and does NOT reach for, open, or approach "
        "anything in the world. The feet do not move. Everything above them does.\n"
        "3. The idle is SMALL and CONTINUOUS — each panel is the next fraction of "
        "a second of the same unbroken moment, not three different poses cut "
        "together. Real weight, real breath, no posing for the camera.\n"
        f"4. The final panel is the same shot as the first, a beat later: "
        f"{closing}. This is the frame the player will act from, so it is "
        "settled and readable — no blur, no half-finished gesture.\n"
        "5. Do NOT introduce new locations, structures, gates, vehicles, people or "
        "creatures that are not already in the reference. Stay in this exact "
        "place. The only thing that changes in the distance is weather, dust and "
        "light.\n\n"
        + "=" * 70 + "\n\n"
    )


def _flipbook_establishing_block(frames: int = None, *, single: bool = False,
                                 goal: str = "") -> str:
    """The establishing idle, pointed at the run's goal when it has one.

    The idle used to end on the character looking off at "something coming",
    unreadable and never identified. With a goal that becomes the thing they
    are looking at: plainly in frame, far off, unreached — so the first frame
    a player controls is a view of where they are going (goal.py).
    """
    text = _flipbook_establishing_block_base(frames, single=single)
    goal = str(goal or "").strip()
    if not goal:
        return text
    far = (
        f"IN THE FAR DISTANCE, WHAT THEY CAME HERE FOR: {goal}.\n"
        "It is PLAINLY VISIBLE and readable, standing on the horizon or at the "
        "far end of the space, in the upper half of the frame, crisp and "
        "unmistakable: a hard silhouette against the sky, or lit against the "
        "dark. Rain, fog and haze sit in front of the rest of the view, never "
        "over it. It is the thing the eye "
        "goes to. The figure stands off to one side of it and looks at it; never "
        "in front of it, never hiding it. It is far away and unreached, and it "
        "does not move, grow or come closer.\n\n"
    )
    before = text
    text = re.sub(r"IN THE FAR DISTANCE: something is coming.*?deep distance\.\n\n",
                  lambda m: far, text, flags=re.S)
    text = re.sub(r"WHAT IS HAPPENING IN THE FAR DISTANCE:\n.*?Dread, not an event\.\n\n",
                  lambda m: far, text, flags=re.S)
    if text == before:
        text = text.replace(_KEEP_THE_HORIZON, _KEEP_THE_HORIZON + far, 1)
    text = text.replace(
        "not already in the reference.",
        "not already in the reference, except what they came here for, which "
        "MUST be in the frame.")
    text = text.replace(
        "that are not in the reference.",
        "that are not in the reference, except what they came here for, which "
        "MUST be in the frame.")
    # VISTA v5
    # The first playtest drew the character a third of the frame high,
    # dead centre, standing in front of the very thing they came for.
    text = text.replace(
        "reading at roughly a third to a half of the frame height, with the "
        "place opening away beyond them so it stays legible.",
        "SMALL in the frame, no more than a quarter of its height, standing "
        "in the lower left or lower right third, so the wide view past them "
        "to what they came for stays open. This is a VISTA, not a portrait.")
    return text


def _flipbook_shot_block(is_free_will: bool) -> str:
    """The text-to-image flipbook's one-continuous-shot clause, per perspective."""
    if not game_identity.shows_character():
        tail = (
            "You ARE the player looking OUT at the world.\n\n"
            if is_free_will
            else "You ARE the player looking OUT at the world. No cuts, no edits, no perspective changes.\n\n"
        )
        return (
            "PERSPECTIVE: ONE CONTINUOUS FIRST-PERSON SHOT - camera strapped to player's head.\n"
            "NEVER show the player from outside. NEVER show their back, profile, or body.\n"
            + tail
        )
    cfg = game_identity.mode_config()
    who = game_identity.display_name()
    return (
        f"PERSPECTIVE: ONE CONTINUOUS {cfg['camera_header']} — the camera is {cfg['rig']}.\n"
        f"{who} is visible in every panel and is the subject of the shot.\n"
        "The camera never becomes their eyes and never cuts to an empty environment.\n\n"
    )


def _flipbook_seconds(frames: int, frame_ms: int = None) -> float:
    """How long the sequence will actually be on screen.

    The prompt asks for an action that fits the playback length, so this is the
    same arithmetic the client uses rather than the old hardcoded "4 seconds".
    """
    ms = int(frame_ms or FLIPBOOK_FRAME_MS)
    return max(0.5, round(flipbook.normalize_frames(frames) * ms / 1000.0, 1))


# The frames from each session's most recent generation. The turn loop hands
# back ONE still because everything downstream of it — history, SCAN, the next
# turn's reference, the Discord client — is written for a single image. The
# frames ride alongside in here and are collected by whoever builds the feed
# item. Popped rather than read: a still-only turn following a flipbook turn
# must not be able to re-attach the previous turn's motion.
_FLIPBOOK_SEQUENCES: Dict[str, dict] = {}
_FLIPBOOK_SEQ_LOCK = threading.Lock()

# How long each panel of the opening ESTABLISHING flipbook holds. At the default
# flip speed the beat flicks past right after the montage's long held shots and
# reads as rushed; ~2.9s a frame lets the establishing scene breathe and land as
# immersive rather than as a quick animation.
OPENING_ESTABLISHING_FRAME_MS = int(os.getenv("OPENING_ESTABLISHING_FRAME_MS", "2900"))


def take_flipbook_sequence(session_id: str = 'default') -> Optional[dict]:
    """The sequence from this session's last generation, once."""
    with _FLIPBOOK_SEQ_LOCK:
        return _FLIPBOOK_SEQUENCES.pop(session_id, None)


def flipbook_web_payload(seq: Optional[dict], session_id: str = 'default') -> Optional[dict]:
    """A sequence as the browser needs it: URLs, count, and how fast to play it.

    Deliberately NOT a GIF. These are the lossless PNG panels, played by the
    client, because a 256-colour GIF throws away the resolution that splitting a
    high-resolution grid was for.
    """
    if not seq:
        return None
    frames = [u for u in (_to_web_image_url(p, session_id)
                          for p in seq.get("frame_paths") or []) if u]
    if len(frames) < 2:
        return None
    return {
        "frames": frames,
        "frame_count": len(frames),
        "frame_ms": int(seq.get("frame_ms") or FLIPBOOK_FRAME_MS),
        "still": frames[-1],
        "grid": seq.get("grid"),
    }


def _flipbook_generate(*, prompt_str: str, caption: str, choice: str,
                       dispatch: str, world_prompt: str, time_of_day: str,
                       img_dir, session_id: str, st: dict,
                       refs: Optional[list] = None,
                       ref_is_anchor: bool = False,
                       identity_paths: Optional[list] = None,
                       identity_seed: bool = False,
                       spec=None,
                       establishing: bool = False,
                       two_shot: str = "",
                       two_shot_look: str = "",
                       hold_cast: bool = False,
                       cast_plates: Optional[list] = None,
                       write_state: bool = True,
                       hard_cut: bool = False,
                       design_refs: Optional[list] = None) -> Optional[dict]:
    """Draw this turn as a grid of in-betweens and split it back into frames.

    hard_cut — the engine has already decided this turn LEAVES the place the
    previous panel shows (MOVE TO, a relocating typed action). The grid rules
    are written for one unbroken take and say so in the strongest terms they
    have ("panel 1 is the very next instant after the reference … same
    landmarks"), and the authored prefix adds "HELD CONSTANT IN EVERY PANEL:
    location". On a cut turn those beat the render prompt's "NEW PLACE" every
    time: "Move to the doorway" came back as the same hatch at 0.97 continuity
    while the still path, given the identical prompt and references, relocated
    four times out of four. See flipbook.grid_prompt(cut=True).

    establishing — an ESTABLISHING beat instead of an action. Ordinary turns
    animate a specific action (the character performs it with their whole body,
    walking/reaching across the panels), which is exactly wrong for the opening:
    it walks the player out of the frame the montage just established and lands
    the run on somewhere the plate never showed. When True the grid HOLDS the
    reference composition and only the ambient world moves (dust, light), so the
    last panel is still the establishing view the player then acts from.

    two_shot / two_shot_look — a SECOND body that has to be in every panel: who
    they are, and what they have on. This is not just prompt wording: it switches
    the image call
    itself onto its confrontation branch (`include_people`). Without it the grid
    goes through the solo/environment branch, which attaches "a previous frame may
    show a different person — ignore that person" and closes on "not a different
    person than the character sheet". The flipbook was asking for an antagonist in
    the middle of the prompt while the image layer appended an instruction against
    one at the end, so the encounter drew four panels of the player alone.

    hold_cast — the two bodies are ALREADY in the reference and must be copied out
    of it rather than introduced (the resolve beat), matching what the resolve
    still passes.

    cast_plates — close-ups of subjects the player has just been shown at length
    (the INTERACT dive's plate). Same treatment as identity_paths, for the same
    reason: flipbook is the default renderer, so a plate that only reached the
    still path would reach almost none of the turns actually played.

    identity_paths — the player's character sheet / level plate from the Cast &
    Camera editor. These ride along as EXTRA labeled references (prepended by
    generate_gemini_img2img) so the protagonist stays the SAME PERSON across the
    animated panels, exactly as the still path already does. Dropping them here
    is why an uploaded character never populated a flipbook turn — and flipbook
    is the default, so that was every turn.

    Runs INLINE, and that is the fix. The old implementation fired the flipbook
    off in a daemon thread beside the still and wrote the result to state for a
    Discord client to poll, while the turn itself set `result_path = None` —
    which in the web app is the "signal lost" beat. Flipbook mode didn't render
    a sequence, it rendered nothing.

    Returns the sequence (see flipbook.sequence_from_grid), or None if the grid
    never came back or wouldn't split — in which case the caller falls through
    to a normal still, so a bad flipbook costs quality, not the turn.
    """
    from gemini_image_utils import generate_gemini_img2img, generate_with_gemini

    cfg = flipbook_settings(st)
    frames, frame_ms = cfg["frames"], cfg["frame_ms"]
    label = flipbook.grid_label(frames)

    # ── references, in the order Gemini weights them ────────────────────────
    # The FIRST reference wins, so it is the previous sequence's last panel:
    # that is where the camera is standing right now, and panel 1 has to be the
    # next instant after it. Everything else is context.
    flipbook_refs: List[str] = []
    prev_last = st.get('flipbook_last_frame')    # where the camera IS
    prev_first = st.get('flipbook_first_frame')  # the wider scene at turn start
    prev_grid = st.get('flipbook_last_grid')     # style/quality only

    # ``ref_is_anchor`` is for a caller whose own frame IS this pass's init
    # rather than context — the encounter plate, where the grid and the still
    # path it replaces were both generated from the captured frame. Without
    # this the confrontation was drawn from the previous sequence's last panel,
    # which is where the camera stood BEFORE the standoff was staged.
    anchor = str(refs[0]) if (ref_is_anchor and refs and refs[0]) else ""
    if anchor and os.path.exists(anchor):
        flipbook_refs.append(anchor)
        # Anything the anchored caller passed BEHIND its anchor is context it
        # chose deliberately, and it used to be dropped on the floor — only
        # refs[0] was ever read. The opening hands the montage's own panels
        # through here so the first playable frame continues the place the
        # player just watched, not only the plate that place was drawn from.
        for extra in refs[1:]:
            extra = str(extra or "")
            if extra and extra != anchor and os.path.exists(extra):
                flipbook_refs.append(extra)
    elif prev_last and os.path.exists(prev_last):
        flipbook_refs.append(prev_last)
    elif refs:
        # First flipbook turn of a run: the still the game is already showing is
        # the spatial anchor, otherwise panel 1 starts somewhere new.
        flipbook_refs.append(refs[0])
    # `prev_first` is the wider scene as the LAST sequence opened — useful context
    # for an ordinary turn, and time travel for an anchored one.
    #
    # An anchored caller has already said "my frame is the truth"; the guard above
    # was written for exactly that and then only applied to prev_last. prev_first
    # kept going in underneath it, so a confrontation staged right after the player
    # set a truck on fire was handed a clean photograph of that truck NOT on fire,
    # taken one panel before the flames. The model believed the photograph: the
    # encounter opened on the pre-fire scene, the burning truck was gone, and the
    # antagonist the brief had written never made it into the frame, because two
    # of its three references showed a place with nobody in it. Reported as "it
    # warped me back in time".
    # A turn where what the player wears just changed (characters.py) trades
    # the wider view for the new thing itself: the fitted turnaround alone
    # lost to the start keyframe's old helmet two turns running (2026-09-24
    # harness), and the item's own plate is the most concrete "this, on them"
    # there is. The reference budget is six, and the layout guide must stay.
    new_gear = _wardrobe_change_plates(st)
    if prev_first and os.path.exists(prev_first) and not anchor and not new_gear:
        flipbook_refs.append(prev_first)
    for plate in new_gear:
        flipbook_refs.append(plate)
    if prev_grid and os.path.exists(prev_grid) and len(flipbook_refs) < 2:
        flipbook_refs.append(prev_grid)

    # The layout guide goes LAST (lowest weight) and is always the blank one.
    # Labels sitting in a reference image come back burned into the panels, and
    # asking the model to ignore text it can see does not work. Before this,
    # engine pointed at two template files that were never in the repo, so
    # every flipbook generation ran with no layout reference at all — run
    # tools/build_flipbook_guides.py to (re)build them.
    guide = flipbook.find_guide(frames, root=ROOT / "prompts")
    if guide:
        flipbook_refs.append(str(guide))
    else:
        print(f"[FLIPBOOK] no layout guide for {label} — run "
              f"tools/build_flipbook_guides.py", flush=True)

    # ── what each reference IS, next to it in the request ───────────────────
    # The image layer labels attachments so a character sheet is not read as
    # "the previous frame". Its label for everything that is NOT a plate is
    # "PREVIOUS FRAME — place, light, and materials only. If a CHARACTER SHEET
    # is also attached, do NOT copy the person in this frame." Written for the
    # still path, where it stops a recast from redrawing the leftover guy —
    # and on a flipbook turn it is the sentence that threw the start pose
    # away: the one reference that shows where the character is standing and
    # how, was captioned "do not copy the person". The blank layout guide got
    # the same caption. So the flipbook names its own references: the frame
    # the grid continues from is the START KEYFRAME (pose and camera
    # included), the wider opening frame is context, the guide is a layout,
    # and the character sheet is told whose pose it is NOT.
    start_ref = flipbook_refs[0] if (flipbook_refs and flipbook_refs[0] != str(guide or "")) else ""
    reference_labels: Dict[str, str] = {}
    if start_ref:
        reference_labels[start_ref] = (
            "START KEYFRAME — the previous sequence's last panel: where the "
            "camera stands RIGHT NOW and how the subject is standing in it. "
            "Panel 1 is the very next instant after this: same camera, same "
            "place, same pose, beginning to move. Copy the POSE and POSITION "
            "from here; copy face and outfit from the CHARACTER SHEET if one "
            "is attached."
        )
    for extra in flipbook_refs[1:]:
        if extra in new_gear:
            reference_labels[extra] = (
                f"NEW GEAR — {new_gear[extra]}, which the player has JUST put on. It is on "
                "them from panel 1, worn exactly as the CHARACTER SHEET shows it. An "
                "object reference only: not a scene, not a keyframe, not a second item.")
            continue
        if extra == str(guide or ""):
            reference_labels[extra] = (
                f"LAYOUT TEMPLATE — a blank {label} grid. Copy ONLY its panel "
                "layout and proportions. Nothing in it is the scene, the "
                "light or the place."
            )
        elif extra == prev_grid:
            reference_labels[extra] = (
                "PREVIOUS GRID — film stock and quality only. Not a keyframe."
            )
        else:
            reference_labels[extra] = (
                "WIDER VIEW — the same place as the START KEYFRAME opened, one "
                "move ago: context for what surrounds the subject. Not a "
                "keyframe; do not return to this framing."
            )
    if start_ref and _wardrobe_change_directive(st):
        reference_labels[start_ref] += (
            " The keyframe shows the OLD outfit: what the player wears changed "
            "just now — take every garment from the CHARACTER SHEET, not from here.")
    if start_ref and game_identity.shows_character():
        who = game_identity.display_name()
        for plate in (identity_paths or []):
            if plate and str(plate) in set(game_identity.character_reference_paths(spec)):
                reference_labels[str(plate)] = (
                    game_identity.reference_part_label(str(plate), spec)
                    + f" {who}'s pose, facing and position in panel 1 come "
                    f"from the START KEYFRAME, not from this sheet — do not "
                    f"turn them toward the lens to match it."
                )

    # ── prompt ──────────────────────────────────────────────────────────────
    is_free_will = bool(st.get('_turn_is_custom_action'))
    dispatch_preview = (dispatch or caption or "")[:250]
    authored = PROMPTS.get("gemini_flipbook_4panel_prefix", "") or ""

    # A turn that has a start keyframe CONTINUES, cut or not. `identity_seed`
    # arrives True on every hard transition (the still path's rule: a
    # relocating frame is composed fresh from the plates), and for the grid it
    # meant the text-to-image template — "FIRST FRAME - NOTHING TO CONTINUE
    # FROM: there is no reference image" — under five attached references,
    # plus "compose a NEW opening shot" in place of the continuity block.
    # With MOVE TO, "further down the corridor" and every relocating verb
    # counted as cuts, that was most turns of a run, each one a fresh
    # composition that began wherever the model liked (face-on, from the
    # character sheet in slot 1). The establishing beat keeps the seed: its
    # reference is the montage's unpeopled plate and the character has to be
    # composed into it.
    continues = bool(start_ref) and not establishing
    if identity_seed and continues:
        identity_seed = False
    if flipbook.prefix_is_stale(authored, frames):
        # A world authored when the grid was always 4x4 carries "THE RENDER MUST
        # BE A 4×4 GRID" in its own prompt set. Handed that alongside a 2x2
        # request the model picks one, and it isn't ours.
        print(f"[FLIPBOOK] authored prefix describes another grid — using the "
              f"built-in {label} rules for this turn", flush=True)
        authored = ""

    if establishing:
        # An establishing beat HOLDS the composition. The action block, the
        # movement camera block and any authored per-turn action prefix all push
        # the character to walk/perform across the panels — the opposite of what
        # an opening needs — so none of them run here. Its reference is the
        # montage's unpeopled plate, so panel 1 inherits its camera and place
        # but not a pose: the establishing block places the character.
        flipbook_prompt = game_identity.apply(
            _flipbook_establishing_block(frames, goal=_goal_mod.look_line(st))
            + flipbook.grid_prompt(frames, seconds=_flipbook_seconds(frames, frame_ms),
                                   keyframe_subject=False)
            + "\n" + prompt_str,
            "raw",
        )
    elif two_shot:
        # The cast staging LEADS. `prompt_str` here is the encounter plate prompt
        # — "TWO DISTINCT PEOPLE IN A STANDOFF", "Add EXACTLY ONE new person" —
        # and it used to sit last, under four thousand characters of solo-shot
        # rules. Whichever of the two contradictions the model resolved first was
        # a coin flip, and the solo rules came first, so they won.
        flipbook_prompt = game_identity.apply(
            _flipbook_confrontation_block(two_shot, two_shot_look,
                                          dispatch_preview, frames)
            + prompt_str + "\n\n"
            + flipbook.grid_prompt(frames, seconds=_flipbook_seconds(frames, frame_ms))
            + "\n" + _flipbook_camera_block(also_visible=two_shot),
            "raw",
        )
    else:
        if hard_cut and authored:
            # The authored prefix is the continuous-shot contract ("the first
            # reference image is the final frame of the previous sequence …
            # same landmarks, same horizon", "HELD CONSTANT IN EVERY PANEL:
            # location"). Correct for every ordinary turn; on a cut it is the
            # instruction that kept the player in the room. The generated grid
            # rules carry the travelling version of the same contract: the
            # start keyframe still leads, and the LAST panel has arrived.
            print("[FLIPBOOK] hard cut — the grid travels from the start keyframe "
                  "to the destination; the continuous-shot prefix is stood down "
                  "for this turn", flush=True)
            authored = ""
        flipbook_prompt = game_identity.apply(
            _flipbook_action_block(choice, dispatch_preview, is_free_will, frames,
                                   end_state=caption, travels=hard_cut)
            + flipbook.grid_prompt(frames, seconds=_flipbook_seconds(frames, frame_ms),
                                   cut=hard_cut)
            + "\n" + _flipbook_camera_block()
            + (authored + "\n" if authored else "")
            + prompt_str,
            "raw",
        )

    _wc_lead = _wardrobe_change_directive(st)
    if _wc_lead and not flipbook_prompt.startswith(_wc_lead):
        flipbook_prompt = _wc_lead + "\n\n" + flipbook_prompt
    if new_gear:
        # The look book's world sheet sits this one turn out. It takes its
        # slots from the tail of the six, which is where the new gear rides,
        # and a harness turn with a roster plate aboard dropped the helmet for
        # the sheet (2026-09-24).
        design_refs = None
    print(f"[FLIPBOOK] generating {label} grid ({frames} frames, "
          f"{_flipbook_seconds(frames, frame_ms):g}s) from "
          f"{len(flipbook_refs)} reference(s)"
          f"{f' — TWO-SHOT with {two_shot}' if two_shot else ''}", flush=True)

    identity_paths = [p for p in (identity_paths or []) if p and os.path.exists(str(p))]
    grid_path = None
    try:
        # img2img whenever there is ANYTHING to seed from — a spatial anchor OR
        # the player's identity plates. The identity plates alone are enough to
        # keep the character consistent on a first flipbook turn with no prior
        # frame; falling through to text-to-image here (as the old `if
        # flipbook_refs` gate did) is exactly what dropped the character sheet.
        if flipbook_refs or identity_paths:
            grid_path = generate_gemini_img2img(
                prompt=flipbook_prompt,
                caption=f"{caption}_flipbook",
                reference_image_path=flipbook_refs,
                world_prompt=world_prompt,
                time_of_day=time_of_day,
                action_context=choice,
                output_dir=img_dir,
                is_flipbook=True,
                flipbook_grid=flipbook.shape_for(frames),
                # The switch that decides how many people the image layer thinks
                # belong in this frame. See the two_shot note in the docstring.
                include_people=bool(two_shot),
                hold_cast=bool(two_shot and hold_cast),
                # Character sheet / level plate as EXTRA labeled references so the
                # animated panels keep the SAME protagonist as the stills.
                identity_paths=identity_paths,
                identity_seed=bool(identity_seed and identity_paths),
                spec=spec,
                # The close-up the player just came out of, so the panels animate
                # the same face they were looking at rather than a new one.
                cast_plates=cast_plates,
                # Which attachment is the start keyframe, which is context,
                # which is the blank layout — see the block that builds it.
                reference_labels=reference_labels,
                # ...and the start keyframe takes slot 1 on a continuing turn.
                # The image layer puts the plates first so the person is
                # copied from the sheet; on a grid that continues a previous
                # panel the person is ALREADY in that panel, from the side and
                # in the pose panel 1 has to continue, and the sheet in slot 1
                # (a face-on portrait) is what kept opening the grid face-on.
                lead_reference=(start_ref if continues else None),
                # The run's look book, behind everything and ahead of the
                # layout guide. 24 test grids with a 3x3 sheet attached all
                # came back as the grid that was asked for, not the sheet's.
                design_refs=design_refs,
            )
        else:
            # Nothing to continue from and no guide built: a plain grid request.
            grid_path = generate_with_gemini(
                prompt=flipbook_prompt,
                caption=f"{caption}_flipbook",
                world_prompt=world_prompt,
                time_of_day=time_of_day,
                action_context=choice,
                output_dir=img_dir,
            )
    except Exception as e:
        print(f"[FLIPBOOK] generation raised: {e}", flush=True)

    if not grid_path:
        print(f"[FLIPBOOK] no grid came back — falling back to a still", flush=True)
        return None

    # Every way out of here that isn't a sequence says so. A silent None is
    # indistinguishable from "flipbook is off" at the call site, which cost a
    # session of guessing at the encounter plate.
    try:
        seq = flipbook.sequence_from_grid(grid_path, frames, out_dir=img_dir,
                                         frame_ms=frame_ms)
    except Exception as e:
        print(f"[FLIPBOOK] splitting the grid raised: {type(e).__name__}: {e} "
              f"— falling back to a still", flush=True)
        return None
    if not seq:
        print(f"[FLIPBOOK] the grid came back but would not split into {label} "
              f"panels ({os.path.basename(str(grid_path))}) — falling back to a "
              f"still", flush=True)
        return None

    # Anchors for the NEXT turn, plus the sequence itself so /api/status can
    # report motion to a client that reconnected mid-turn. Skipped when the
    # caller owns the state write (the opening establishing beat writes its
    # anchors itself, atomically, so a re-run can't leave a stale one behind).
    if write_state:
        with WORLD_STATE_LOCK:
            live = _load_state(session_id)
            live['flipbook_last_grid'] = seq['grid_path']
            live['flipbook_first_frame'] = seq['first_path']
            live['flipbook_last_frame'] = seq['still_path']
            live['current_sequence'] = flipbook_web_payload(seq, session_id)
            _save_state(live, session_id)
        with _FLIPBOOK_SEQ_LOCK:
            _FLIPBOOK_SEQUENCES[session_id] = seq
    return seq


def _gen_image(*args, session_id: str = 'default', **kwargs) -> Optional[tuple[str, str, Optional[str]]]:
    """
    Thin cost-tracking wrapper around `_gen_image_impl` (the real
    900+-line, multi-provider implementation below). Deliberately does NOT
    touch the implementation's internals — it just times the call, reads
    which provider/model was active, and records one usage event based on
    whether an image path came back. This keeps the (fragile, many-return-
    path) implementation untouched while still covering every provider
    branch (gemini/krea/fal/veo/openai) from a single call site.

    Image providers don't return granular token usage the way text APIs do
    (Krea/fal/Veo bill per-image or per-second at a flat published rate, not
    per-request usage metadata), so this records exactly one image (or, for
    Veo, one ~8s video clip) per call — see pricing.json / ADMIN_COST_ANALYTICS_DASHBOARD_PLAN.md §4.
    """
    provider = ai_provider_manager.get_image_provider()
    model_name = ai_provider_manager.get_image_model()
    t0 = time.time()
    result = _gen_image_impl(*args, session_id=session_id, **kwargs)
    latency_ms = int((time.time() - t0) * 1000)

    try:
        image_path, _prompt_used, video_path = result if result else (None, "", None)
        success = bool(image_path)
        if provider == "veo" and video_path:
            cost_tracker.record_usage(
                session_id, "video", provider, model_name, operation="gen_image",
                output_units=8.0, unit_type="seconds", latency_ms=latency_ms, success=success,
                error_message=None if success else "no_image_returned",
            )
        else:
            cost_tracker.record_usage(
                session_id, "image", provider, model_name, operation="gen_image",
                output_units=1.0, unit_type="images", latency_ms=latency_ms, success=success,
                error_message=None if success else "no_image_returned",
            )
    except Exception as _e:
        print(f"[COST TRACKER] _gen_image usage recording failed (non-fatal): {_e}", flush=True)

    return result


def _gen_image_impl(caption: str, mode: str, choice: str, previous_image_url: Optional[str] = None, previous_caption: Optional[str] = None, previous_mode: Optional[str] = None, strength: float = 0.25, image_description: str = "", time_of_day: Optional[str] = None, use_edit_mode: bool = False, frame_idx: int = 0, dispatch: str = "", world_prompt: str = "", hard_transition: bool = False, is_timeout_penalty: bool = False, session_id: str = 'default', history_ref: Optional[list] = None, softened_move: bool = False, identity_spec: Optional[dict] = None, cast_plates: Optional[List[str]] = None) -> Optional[tuple[str, str, Optional[str]]]:
    """Generate image and return (image_path, prompt_used, video_path).
    
    video_path is None for non-Veo providers or when video generation fails/disabled.
    
    time_of_day: If None, will use state['time_of_day'] for consistency
    session_id: Session ID for storing images in correct directory
    cast_plates: Close-ups of subjects the player has just been shown at length
        (the INTERACT dive's plate). They ride as EXTRA labeled references, like
        the identity plates and for the same reason — a wide frame does not
        carry enough of a face to redraw it, so without the plate the character
        the player just met comes back as somebody else.
    history_ref: The caller's session history to collect img2img reference frames
        from. Pass this (rather than relying on the module-global `history`) from
        any multi-user path — a concurrent different-session request can swap the
        global mirror out mid-render, which would otherwise feed one session's
        reference frames into another session's image. Falls back to the global
        for legacy single-session callers (the Discord bot) that don't pass it.
    """
    global _last_image_path
    # Resolve the history this render reads its img2img reference frames from.
    # Local variable so a concurrent set_active_session()/session swap can't
    # change it mid-function (the whole point of the history_ref parameter).
    _hist = history_ref if history_ref is not None else history
    import random
    if not (IMAGE_ENABLED and LLM_ENABLED):
        print("[IMG] Image or LLM disabled, returning None")
        return (None, "", None)
    
    # SANITIZE caption for image generation (narrative text stays grim!)
    # This prevents content filter blocks while keeping the story dark
    original_caption = caption
    caption = _sanitize_for_image_generation(caption)
    if original_caption != caption:
        print(f"[SANITIZE] Image prompt cleaned to avoid content filters")

    # CRITICAL: The narrative `dispatch` text (player-facing) is now ALSO injected
    # into the image prompt as `narrative_dispatch`. It must be sanitized the same
    # way as `caption`, otherwise raw narrative gore/violence words bypass the
    # content filter shield and the image silently fails or degrades.
    sanitized_narrative_dispatch = ""
    if dispatch:
        sanitized_narrative_dispatch = _sanitize_for_image_generation(dispatch)
        if sanitized_narrative_dispatch != dispatch:
            print(f"[SANITIZE] Narrative dispatch cleaned for image prompt")
    
    try:
        prev_time_of_day, prev_color = "", ""
        prev_img_captions = []
        prev_vision_analysis = ""  # Vision AI description of last frame
        prev_spatial         = ""  # Spatial compass: ahead/left/right/ground/height
        prev_setting         = ""  # Environment type: outdoor-desert, indoor-corridor, etc.
        prev_img_path = None
        prev_img_paths_list = []  # List of recent image paths for multi-img2img
        # High-fidelity guide still for the PRIMARY reference. When the primary
        # reference 'image' has been replaced by a live world-model frame (act-time
        # capture / observe), this holds the original Gemini still so img2img can
        # anchor QUALITY on it while spatial state follows the live frame.
        primary_guide_image_path = None
        live_capture_this = False
        # Is the newest reference the frame the opening handed over — the intro
        # cutscene's last shot, or the opening plate? That frame is the
        # establishing shot of the place the player is standing in, so the first
        # generated frame has to continue from its pixels even when the choice
        # reads as a hard cut. See the hard_transition branch below.
        opening_handoff_ref = False
        # The montage panels behind that handoff frame, when the opening left
        # any. They are the only images in a boot drawn from the live level
        # definition (cutscene.mystery_shotlist reads the world bible for their
        # subjects), and with the establishing flipbook off they had no other
        # route into the game — the handoff is the plate, and the plate is where
        # turn one continued from. See _finish_opening_montage.
        opening_montage_refs: List[str] = []
        
        if frame_idx > 0 and _hist:
            last_imgs = []
            # Use 2 reference images for better stability
            num_images_to_collect = 2
            print(f"\n{'='*70}")
            print(f"[IMG2IMG COLLECT] Frame {frame_idx} - Starting reference collection")
            print(f"[IMG2IMG COLLECT] History has {len(_hist)} entries")
            print(f"[IMG2IMG COLLECT] Collecting up to {num_images_to_collect} reference images")
            print(f"[IMG2IMG COLLECT] Will stop at last hard transition (location change)")
            print(f"{'='*70}\n")
            
            for idx, entry in enumerate(reversed(_hist)):
                has_image = bool(entry.get("image"))
                has_vision = bool(entry.get("vision_dispatch"))
                was_hard_transition = entry.get("hard_transition", False)
                
                print(f"[IMG2IMG COLLECT] History[{idx}]: image={has_image}, vision={has_vision}, hard_transition={was_hard_transition}")
                if has_image:
                    print(f"[IMG2IMG COLLECT]   Image path: {entry.get('image')}")
                
                if entry.get("image") and entry.get("vision_dispatch"):
                    img_name = Path(str(entry.get("image") or "")).name
                    is_live = bool(entry.get("live_capture")) or img_name.startswith("observed_")
                    last_imgs.append((
                        entry["image"],
                        entry["vision_dispatch"],
                        entry.get("vision_analysis", ""),  # visual description
                        entry.get("spatial_compass", ""),  # ahead/left/right compass
                        entry.get("setting_type", ""),     # indoor/outdoor type
                        entry.get("guide_image", ""),      # original hi-fi guide still
                        is_live,
                    ))
                    print(f"[IMG2IMG COLLECT]   -> Added to reference list (total: {len(last_imgs)})")
                    if len(last_imgs) == 1 and entry.get("cached_opening"):
                        opening_handoff_ref = True
                        print(f"[IMG2IMG COLLECT]   -> this is the OPENING HANDOFF frame")
                        opening_montage_refs = [
                            str(p) for p in (entry.get("montage_refs") or [])
                            if p and os.path.exists(str(p))
                        ]
                        if opening_montage_refs:
                            print(f"[IMG2IMG COLLECT]   -> {len(opening_montage_refs)} "
                                  f"montage panel(s) ride with it")
                
                # CRITICAL: The reference buffer must RESET at a location change —
                # whether or not that boundary frame produced a usable image.
                #
                # This break used to be nested INSIDE the has-image branch above.
                # That meant a hard-cut frame whose image was missing (async
                # write-back race, content-filter block, or flipbook turn) never
                # stopped the search, so collection kept walking back PAST the cut
                # and grabbed PRE-CUT frames. The next turn then did img2img off the
                # OLD scene instead of the freshly-expanded new area — exactly the
                # "hard cut expands, then the next image snaps back to the old scene"
                # bug. Evaluating the boundary unconditionally fixes that: we include
                # the new-area frame if it has an image, otherwise we fall back to a
                # clean text-to-image for the new area rather than reviving the old one.
                if was_hard_transition:
                    print(f"[IMG2IMG COLLECT] HARD TRANSITION BOUNDARY - stopping collection")
                    print(f"[IMG2IMG COLLECT] Reference buffer reset at location change (collected {len(last_imgs)} pre-boundary refs)")
                    break
                
                if len(last_imgs) == num_images_to_collect:
                    print(f"[IMG2IMG COLLECT] Collected {num_images_to_collect} references, stopping search")
                    break
            
            print(f"\n[IMG2IMG COLLECT] RESULT: Found {len(last_imgs)} reference images in history")
            if len(last_imgs) == 0:
                print(f"[IMG2IMG COLLECT] WARNING: NO REFERENCE IMAGES FOUND!")
                print(f"[IMG2IMG COLLECT] This will generate a text-to-image (no continuity)")
            
            if len(last_imgs) >= 1:
                print(f"[IMG2IMG COLLECT] Processing {len(last_imgs)} references for img2img...")
                # Get most recent entry — unpack all fields
                img, cap, vis_analysis, spatial_compass, setting_type, guide_img, live_capture_this = last_imgs[0]
                prev_vision_analysis = vis_analysis
                prev_spatial         = spatial_compass
                prev_setting         = setting_type
                prev_img_path = str(_resolve_image_path(img))
                if not os.path.exists(prev_img_path):
                    prev_img_path = None

                # If the primary reference's 'image' is a live world-model frame,
                # the original hi-fi guide still lives under 'guide_image'. Keep it
                # as a secondary reference so img2img anchors quality on it while
                # the composition follows the realtime frame. (Skip if it's the
                # same file — i.e. no realtime frame ever replaced it.)
                if guide_img:
                    _guide_resolved = str(_resolve_image_path(guide_img))
                    if os.path.exists(_guide_resolved) and _guide_resolved != prev_img_path:
                        primary_guide_image_path = _guide_resolved
                
                # Collect all recent image paths for multi-reference img2img
                for idx, (img, cap, *_rest) in enumerate(last_imgs):
                    img_path = str(_resolve_image_path(img))
                    if not os.path.exists(img_path):
                        continue  # Skip missing images
                    if os.path.exists(img_path):
                        prev_img_paths_list.append(img_path)
                        prev_img_captions.append(cap)
                    else:
                        print(f"[IMG2IMG ERROR] Ref {idx+1}: {img_path} NOT FOUND!")
                
                # EXPERIMENTAL: Always include frame 0 as visual anchor
                # Toggle: Set USE_FRAME_0_ANCHOR = False to disable
                USE_FRAME_0_ANCHOR = False  # Set to False to disable frame 0 anchoring
                
                if USE_FRAME_0_ANCHOR and len(_hist) > 0 and frame_idx > 1:
                    frame_0_image = _hist[0].get("image")
                    if frame_0_image and frame_0_image not in prev_img_paths_list:
                        frame_0_path = str(_resolve_image_path(frame_0_image))
                        if not os.path.exists(frame_0_path):
                            frame_0_path = None
                        if os.path.exists(frame_0_path):
                            # Prepend frame 0 as the "visual constitution"
                            prev_img_paths_list.insert(0, frame_0_path)
                            print(f"[IMG2IMG] Frame 0 anchor ENABLED - Added: {os.path.basename(frame_0_path)}")
                elif not USE_FRAME_0_ANCHOR and frame_idx > 1:
                    print(f"[IMG2IMG] Frame 0 anchor DISABLED")
                
                print(f"\n[IMG2IMG SUMMARY] Frame {frame_idx}: Final reference list:")
                for i, path in enumerate(prev_img_paths_list):
                    print(f"[IMG2IMG SUMMARY]   Ref {i+1}: {os.path.basename(path)}")
                print(f"[IMG2IMG SUMMARY] Total: {len(prev_img_paths_list)} reference image(s)\n")
                
                # Skip time extraction - we maintain it in state already
                prev_time_of_day = ""
                prev_color = ""
        
        # Did this turn leave the region, or only the room? Decided here, once,
        # and then applied to all four places that would otherwise pin the new
        # place to the old one's light. See is_region_change for the capture
        # this comes from.
        region_change = bool(hard_transition) and is_region_change(choice)

        # Use provided time_of_day, or fall back to state (persistent across frames)
        # Check for None explicitly (not just falsy) to handle empty string vs None
        if time_of_day is None:
            use_time_of_day = state.get('time_of_day', '') if 'state' in globals() else ''
            if use_time_of_day:
                print(f"[TIME] Using time_of_day from state: {use_time_of_day}")
        else:
            use_time_of_day = time_of_day
            if use_time_of_day:
                print(f"[TIME] Using explicitly provided time_of_day: {use_time_of_day}")
        if region_change:
            use_time_of_day = _clock_only(use_time_of_day)
        use_color = prev_color
        
        # --- Summarize world prompt for image flavor ---
        # No summarize_world_state() here on purpose. Its beat lines are written
        # for the story prompts and name things off camera ("a violent storm is
        # gathering overhead", "the red biome is dangerously close"); appended to
        # a render as "Background context" they became instructions, and img2img
        # continuity then carried the invention forward for the rest of the run.
        current_state = get_state(session_id)
        # The session's own world text wins. The `world_prompt` ARGUMENT is the
        # fallback, and until now it was dead here: a caller that renders into a
        # session with no state behind it (world_frames._generate_paid, which
        # draws a World's plate in a throwaway wf-<slug> session) passed the
        # level's bible in and it reached nothing, so the plate came back with no
        # sense of the place at all while the montage drawn from that same bible
        # was full of it.
        world_context = current_state.get("world_prompt", "") or world_prompt
        world_flavor = ""
        if world_context:
            world_flavor = summarize_world_prompt_for_image(
                world_context,
                session_id=session_id,
                hard_transition=hard_transition,
                frame_idx=frame_idx,
                relight=region_change,
            )
        identity_spec = identity_spec or game_identity.get_spec()
        if game_identity.is_viewfinder_spec(identity_spec):
            # A viewfinder restage must not inherit turn flavor that names the
            # follow-cam body, and must not kick a flipbook on the side.
            world_flavor = ""
        prompt_str = build_image_prompt(
            player_choice=choice,
            dispatch=caption,                              # visual scene (sanitized)
            narrative_dispatch=sanitized_narrative_dispatch,  # narrative text (sanitized)
            prev_vision_analysis=prev_vision_analysis,
            hard_transition=hard_transition,
            is_timeout_penalty=is_timeout_penalty,
            prev_spatial=prev_spatial,
            prev_setting=prev_setting,
            softened_move=softened_move,
            # The opening handoff is the one hard cut that keeps a legible
            # reference (see the branch that sets it), so it is the one that
            # needs telling the vantage moved.
            holds_reference_frame=opening_handoff_ref,
            region_change=region_change,
            spec=identity_spec,
        )
        
        # A fitting landed at this turn's boundary (characters.py): the frame
        # being continued shows the OLD outfit, and continuity copies it —
        # the 2026-09-24 harness run put on a riot helmet and the next two
        # turns still drew the old one. Said first, where it is read hardest.
        try:
            _wc = _wardrobe_change_directive(_load_state(session_id))
            if _wc:
                prompt_str = _wc + "\n\n" + prompt_str
        except Exception as _wc_err:
            print(f"[CHARACTERS] wardrobe line skipped: {_wc_err}", flush=True)

        # Inject world flavor and location for image model only.
        # Labelled "Visual tone" rather than "World flavor" on purpose — the
        # latter reads like a second scene description to hand off to, and
        # summarize_world_prompt_for_image() is now explicitly forbidden from
        # putting a character/pose/action in this text, so the label should
        # not imply one either.
        if world_flavor:
            prompt_str += f" Visual tone: {world_flavor}."
        # NOTHING ELSE from the story state goes on the end of a render prompt.
        # A `_tmp_regression_check = summarize_world_state(...)` probe was left
        # here appending " Background context: <beat>." to every single frame,
        # directly under the comment above that forbids exactly that — and it
        # shipped. A live capture caught it putting "Background context: The red
        # biome is dangerously close." on a render, which is almost word for
        # word the example that comment uses to explain why this is banned: the
        # beat lines name things that are NOT on camera, the image model reads
        # them as things to draw, and img2img then carries the invention forward
        # for the rest of the run.
        # ALWAYS maintain lighting/aesthetic continuity, even during location changes.
        # NOTE: guard on prev_img_paths_list (the list we actually populate). The old
        # code checked `prev_img_paths`, which is never appended to, so this whole
        # continuity clause was silently dead — hard cuts lost their "same world
        # aesthetic" instruction and same-location frames lost their lighting match.
        if prev_img_paths_list:
            if region_change:
                # A different place on the map. This clause is the single most
                # CONCRETE statement in the whole payload — it names lighting,
                # time of day and palette in one breath, and it sits at the very
                # end, which is why the desert won the Antarctica frame outright
                # (see is_region_change). On a change of region the reference is
                # a record of the camera and the cast, and of nothing else about
                # where they were.
                prompt_str = (
                    f"{prompt_str}\nThe previous image is a reference for the FILM STOCK, "
                    f"the grain, the era and the people only. Its lighting, its time of day, "
                    f"its weather and its color palette belong to a place that has been left "
                    f"behind — do not carry any of them into this frame. Light this location "
                    f"the way this location is lit."
                )
            elif hard_transition:
                # Location change - use reference for lighting/aesthetic ONLY (not composition)
                prompt_str = (
                    f"{prompt_str}\nMaintain the same lighting, time of day, and color palette as the previous image. "
                    f"New location, but same world aesthetic and atmospheric conditions."
                )
            else:
                # Same location - full img2img continuity
                prompt_str = (
                    f"{prompt_str}\nMatch the lighting, time of day, and color palette to the previous image."
                )

        # --- IDENTITY PLATES (character sheet / level reference) ---
        # User-supplied art from the Cast & Camera editor. These ride along as
        # EXTRA img2img references so the protagonist stays the same person and
        # the level keeps its architecture. They're appended AFTER the previous
        # frame(s) on continuation turns — Gemini weights the first reference
        # hardest and spatial continuity has to keep winning that slot — but on
        # frame 0 (nothing to continue from) they lead, which is what turns a
        # location plate into an actual opening shot of YOUR level.
        # PHOTO restage: the live grab is the place lock. A level plate
        # prepends as Gemini's first reference and restages the opening
        # location instead of where the player is standing.
        if game_identity.is_viewfinder_spec(identity_spec):
            identity_plates = []
        else:
            identity_plates = game_identity.identity_reference_paths(
                # A character sheet is only useful to the renderer when the body or
                # hands can appear; otherwise it just wastes a reference slot and
                # tempts the model into putting a stranger in frame.
                include_character=(
                    game_identity.shows_character(identity_spec)
                    or game_identity.hands_visible(identity_spec)
                ),
                spec=identity_spec,
            )
        if identity_plates:
            prompt_str += game_identity.reference_annotation(
                identity_plates,
                identity_spec,
            )
            print(f"[IDENTITY] {len(identity_plates)} reference plate(s) available for this frame")

        # --- CAST PLATES (the close-up the player just came out of) ---
        # A viewfinder restage is the player's own photograph of the place; a
        # discovered face has no business being composited into it.
        cast_plate_paths = [] if game_identity.is_viewfinder_spec(identity_spec) else [
            str(p) for p in (cast_plates or []) if p and os.path.exists(str(p))
        ]
        if cast_plate_paths:
            prompt_str += (
                "\n\n🫱 THE SUBJECT YOU JUST LOOKED AT CLOSELY:\n"
                "One of the attached references is a CLOSE-UP the player has "
                "just spent a moment studying — the thing they reached out to. "
                "It is in THIS scene, and it is the same one: copy its face, "
                "build, hair, clothing, materials and wear from that close-up "
                "exactly. Do not recast it, do not swap it for something "
                "similar, and do not leave it out of the frame.\n"
                "Do NOT copy the close-up's framing. That was a look at one "
                "thing; this is the wide scene it lives in, so place it in the "
                "space at the distance the scene describes."
            )
            print(f"[CAST PLATE] {len(cast_plate_paths)} close-up plate(s) ride into "
                  f"this frame: {', '.join(os.path.basename(p) for p in cast_plate_paths)}",
                  flush=True)

        # --- LOOK BOOK (the run's contact sheet; see look_book.py) ---
        # The world sheet rides last as DESIGN (how this world's people, places
        # and film look); a roster plate rides when this frame's text names a
        # roster entry, so the guard from the fight is the guard on the catwalk.
        # A viewfinder restage is the player's own photograph and takes neither.
        design_ref_paths: List[str] = []
        roster_plate_paths: List[str] = []
        if not game_identity.is_viewfinder_spec(identity_spec):
            try:
                import look_book
                # A World the run just arrived in may still be having its book
                # shot (look_book.ensure_for_level). Its frames wait for it
                # rather than being drawn without — bounded, see wait_ready.
                if look_book.building(session_id):
                    look_book.wait_ready(session_id, timeout=120)
                sheet = look_book.world_sheet(session_id)
                if sheet:
                    design_ref_paths.append(sheet)
                # A cut that lands in one of the book's designed sets gets that
                # set's panel too (story half only; see look_book.set_panel_for).
                if hard_transition:
                    set_panel = look_book.set_panel_for(session_id, f"{caption}\n{dispatch}")
                    if set_panel:
                        design_ref_paths.insert(0, set_panel)
                if not cast_plate_paths:
                    roster_plate_paths = look_book.plates_named_in(
                        session_id, f"{caption}\n{dispatch}")
            except Exception as _lb_err:
                print(f"[LOOK BOOK] skipped for this frame: {_lb_err}", flush=True)
        if roster_plate_paths:
            print(f"[LOOK BOOK] roster plate rides into this frame: "
                  f"{', '.join(os.path.basename(p) for p in roster_plate_paths)}", flush=True)
            cast_plate_paths = cast_plate_paths + roster_plate_paths

        # --- LOGGING ---
        print("[IMG LOG] --- IMAGE GENERATION PARAMETERS ---")
        print(f"[IMG LOG] frame_idx: {frame_idx}")
        print(f"[IMG LOG] mode: {mode}")
        safe_choice = str(choice).encode('ascii', 'replace').decode('ascii')
        print(f"[IMG LOG] choice: {safe_choice}")
        safe_caption = str(caption).encode('ascii', 'replace').decode('ascii')
        print(f"[IMG LOG] caption (vision_dispatch): {safe_caption}")
        safe_dispatch = str(dispatch).encode('ascii', 'replace').decode('ascii')
        print(f"[IMG LOG] dispatch (narrative): {safe_dispatch}")
        print(f"[IMG LOG] time_of_day: {use_time_of_day}")
        safe_prompt = str(prompt_str).encode('ascii', 'replace').decode('ascii')
        print(f"[IMG LOG] prompt_str (full): {safe_prompt}")
        print(f"[IMG LOG] previous_image_path (actual): {prev_img_path if prev_img_path else 'None'}")
        print(f"[IMG LOG] reference_images_list: {len(prev_img_paths_list)} images")
        print(f"[IMG LOG] cast_plates: {len(cast_plate_paths)} close-up plate(s)")
        print(f"[IMG LOG] use_edit_mode: {use_edit_mode}")
        safe_world = str(world_prompt).encode('ascii', 'replace').decode('ascii')
        print(f"[IMG LOG] world_prompt: {safe_world}")
        print(f"[IMG LOG] session_id: {session_id}")
        print("[IMG LOG] --- END IMAGE GENERATION PARAMETERS ---")
        img_dir = _get_image_dir(session_id)
        filename = f"{hash(caption) & 0xFFFFFFFF}_{_slug(caption)}.png"
        image_path = img_dir / filename
        
        # --- ROUTE TO APPROPRIATE IMAGE PROVIDER ---
        active_image_provider = ai_provider_manager.get_image_provider()
        if active_image_provider == "veo":
            try:
                # Use Veo 3.1 for video-based image generation
                # Generates video from previous frame, extracts last frame as "image"
                print(f"[IMG] Using Veo 3.1 video generation (last frame extraction)", flush=True)
                from veo_video_utils import generate_frame_via_video, _session_costs, MAX_SESSION_COST
                print(f"[IMG] Veo module imported, session_cost=${_session_costs['total_cost']:.2f}/${MAX_SESSION_COST:.2f}", flush=True)
                
                # No frame limit - only budget limit
                print(f"[IMG] Calling generate_frame_via_video with frame_idx={frame_idx}", flush=True)
                
                # Pass reference frames for visual continuity (like img2img)
                # Use the same reference frames we collected for img2img, plus
                # the player's own plates — Veo weights its references the same
                # way, and without them the character sheet reached every
                # provider except the one generating actual motion.
                reference_frames_for_veo = list(prev_img_paths_list) if prev_img_paths_list else []
                for plate in identity_plates:
                    if plate not in reference_frames_for_veo:
                        reference_frames_for_veo.append(plate)
                        print(f"[IDENTITY] Attached plate as Veo reference: {os.path.basename(plate)}")
                if reference_frames_for_veo:
                    print(f"[IMG] Passing {len(reference_frames_for_veo)} reference frames to Veo for continuity", flush=True)

                result_path, veo_prompt, video_path = generate_frame_via_video(
                    prompt=prompt_str,
                    # Deliberately NOT seeded from a plate: this is the literal
                    # first frame of a generated video, and a portrait there
                    # produces eight seconds of that portrait. Plates ride in
                    # `reference_frames`, where they describe rather than start.
                    first_frame_path=prev_img_paths_list[0] if prev_img_paths_list else None,
                    caption=caption,
                    frame_idx=frame_idx,
                    world_prompt=world_prompt,
                    action_context=choice,
                    reference_frames=reference_frames_for_veo,  # Pass ALL frames (including starting frame) for style continuity
                    video_segments_dir=_get_video_segments_dir(session_id),  # Session-specific segments directory
                    video_films_dir=_get_video_films_dir(session_id)  # Session-specific films directory
                )
                print(f"[IMG] generate_frame_via_video returned: {result_path}", flush=True)
                if video_path:
                    print(f"[IMG] Video available for playback: {video_path}", flush=True)
                
                if result_path:
                    _last_image_path = result_path
                    return (result_path, veo_prompt, video_path)
                else:
                    print(f"[IMG] Veo returned None - budget limit reached or error, falling back to Gemini", flush=True)
                    # Fall through to Gemini below
            except Exception as veo_error:
                print(f"[IMG] Veo error: {veo_error}", flush=True)
                import traceback
                traceback.print_exc()
        
        elif active_image_provider == "gemini":
            # Use Google Gemini (Nano Banana) - OFFICIAL API
            print(f"[IMG] Using Google Gemini (Nano Banana) provider")
            from gemini_image_utils import generate_with_gemini, generate_gemini_img2img, make_style_swatch
            
            # Use img2img for ALL frames with history (style continuity + movement instructions)
            use_style_swatch = False
            if prev_img_paths_list and frame_idx > 0:
                # For hard transitions (location changes), use ONLY 1 reference for lighting/aesthetic
                # For normal transitions, use full reference set for composition continuity
                print(f"\n{'='*70}")
                print(f"[IMG GENERATION] USING IMG2IMG MODE (STYLE CONTINUITY)")
                print(f"[IMG GENERATION] frame_idx={frame_idx}")
                print(f"[IMG GENERATION] movement_type={_last_movement_type}")
                print(f"[IMG GENERATION] hard_transition={hard_transition}")
                print(f"[IMG GENERATION] References will provide STYLE/AESTHETIC only")
                print(f"[IMG GENERATION] Movement instructions will override composition")
                print(f"[IMG GENERATION] Available references: {len(prev_img_paths_list)}")
                
                # Frame 1 used to ALWAYS img2img off the intro still, even when
                # this turn asked for a hard cut. That made the first curated
                # choice ("Follow the fence", "Climb the ladder") a modification
                # of the establishing shot instead of a new composition. Soft
                # turns (look-around, INTERACT, timeout) still lock to Frame 0.
                if frame_idx == 1 and not hard_transition:
                    ref_images_to_use = prev_img_paths_list[:1]  # Use ONLY most recent (Frame 0)
                    print(f"[IMG GENERATION] FRAME 1 SPECIAL CASE - Using most recent reference from intro")
                    print(f"[IMG GENERATION] This ensures color/lighting consistency from Frame 0 to Frame 1")
                elif hard_transition:
                    # A hard transition is supposed to be a genuinely NEW
                    # composition, not "the same shot with a color-matched
                    # skin." Handing Gemini's img2img endpoint the previous
                    # frame as even a single "style-only" reference was the
                    # theory (see the print above) — in practice it was NOT
                    # style-only: the model kept reproducing the old frame's
                    # camera angle and character position near-verbatim, and
                    # the prompt's "NEW VANTAGE POINT" wording did nothing to
                    # override an actual photo sitting in the same request
                    # ("Move to the pipes" rendered as the same shot with
                    # steam added). No reference means the model has no photo
                    # to be faithful TO; the world_prompt's own written-out
                    # lighting/time-of-day/character description is what
                    # keeps a hard cut feeling like the same world.
                    #
                    # A blurred-past-recognition swatch of that same frame is
                    # a different bet, not a repeat of the failed one: there
                    # is no legible photo left to be faithful TO, only a
                    # color/light field, so it can carry lighting continuity
                    # without giving the model a composition to copy. Falls
                    # back to no reference at all (the proven-safe behavior)
                    # if the swatch can't be built for any reason.
                    #
                    # EXCEPT straight out of the opening. The intro cutscene's
                    # last shot is not "the previous location" — it is the
                    # establishing shot of the ground the player is standing on,
                    # and the first playable frame is the continuation of it.
                    # Blurring it to a swatch meant the run visibly began
                    # somewhere other than where the cutscene had just put you:
                    # a montage of a chain-link fence under a mesa, then a first
                    # frame that shares only its palette. The first choice out of
                    # an opening is nearly always a "hard" verb (climb, cut
                    # through, approach), so this fired almost every run.
                    if opening_handoff_ref:
                        ref_images_to_use = prev_img_paths_list[:1]
                        print(f"[IMG GENERATION] Hard transition, but the reference IS the "
                              f"opening handoff frame - keeping its pixels so the first "
                              f"playable frame continues the cutscene it came out of")
                        # With the establishing flipbook on, the montage is
                        # already baked into that handoff frame. With it off
                        # there is no establishing beat at all, the handoff is
                        # the bare plate, and the four photographs the player
                        # just watched reached nothing. Ride them in here so the
                        # documented order — level definition, montage, first
                        # playable frame — holds in both modes.
                        for extra in opening_montage_refs:
                            if extra not in ref_images_to_use:
                                ref_images_to_use.append(extra)
                        if opening_montage_refs:
                            print(f"[IMG GENERATION] + {len(opening_montage_refs)} montage "
                                  f"panel(s) so the first frame continues the place the "
                                  f"montage established, not just the plate")
                    else:
                        swatch_path = make_style_swatch(prev_img_paths_list[0], output_dir=img_dir)
                        if swatch_path:
                            ref_images_to_use = [swatch_path]
                            use_style_swatch = True
                            print(f"[IMG GENERATION] Hard transition - using a blurred color/light "
                                  f"swatch (no legible composition to copy) instead of no reference")
                        else:
                            ref_images_to_use = []
                            print(f"[IMG GENERATION] Hard transition - swatch build failed, falling back "
                                  f"to NO reference image (forces text-to-image)")
                else:
                    ref_images_to_use = prev_img_paths_list[:1]  # ONLY most recent for strongest continuity
                    print(f"[IMG GENERATION] Normal transition - using 1 reference image (most recent frame)")
                    # Each soft turn edits the PREVIOUS GENERATED frame, so a
                    # run of them is an edit of an edit of an edit. Nothing
                    # bounded that chain — it only reset at a hard cut — and
                    # colour, contrast and texture drift compound every pass
                    # until the frame is mush. Past the cap, the clean frame
                    # that opened this location leads for quality and the
                    # previous frame follows for spatial state: the same
                    # dual-reference the realtime path already uses.
                    anchor = _soft_chain_anchor(_hist, IMG2IMG_SOFT_CHAIN_MAX)
                    if anchor and anchor not in ref_images_to_use:
                        ref_images_to_use = [anchor] + ref_images_to_use
                        print(f"[IMG GENERATION] Soft chain past {IMG2IMG_SOFT_CHAIN_MAX} frames — "
                              f"re-anchoring quality on {os.path.basename(anchor)} "
                              f"(previous frame kept as secondary/spatial)")

                # Live capture is WHERE THEY ARE NOW. Using it as img2img init
                # on a hard cut (MOVE TO) redrew that same yard every trip —
                # the exploration freeze. Same-place turns still refine from
                # the frame on screen; a relocation keeps the swatch / empty
                # path above so the destination can actually be a new place.
                if (live_capture_this and not hard_transition
                        and prev_img_path and os.path.exists(prev_img_path)):
                    ref_images_to_use = [prev_img_path]
                    if primary_guide_image_path and primary_guide_image_path != prev_img_path:
                        ref_images_to_use.append(primary_guide_image_path)
                    use_style_swatch = False
                    print(f"[IMG GENERATION] Live world-model frame is PRIMARY img2img reference [{os.path.basename(prev_img_path)}]")
                elif primary_guide_image_path and not hard_transition:
                    live_frame = ref_images_to_use[0] if ref_images_to_use else None
                    if frame_idx == 1:
                        ref_images_to_use = [primary_guide_image_path]
                        print(f"[IMG GENERATION] Realtime: guide still as sole reference (quality anchor) [{os.path.basename(primary_guide_image_path)}]")
                    else:
                        ref_images_to_use = [primary_guide_image_path]
                        if live_frame and live_frame != primary_guide_image_path:
                            ref_images_to_use.append(live_frame)
                        print(f"[IMG GENERATION] Realtime dual-ref: guide still PRIMARY (quality/aesthetic) + live frame SECONDARY (spatial) [{os.path.basename(primary_guide_image_path)}]")

                if game_identity.is_viewfinder_spec(identity_spec) and prev_img_path and os.path.exists(prev_img_path):
                    # PHOTO restage must img2img the frame the player is looking
                    # at (live reactor grab or current still). The guide-still
                    # primary path above would redraw the authored 3P plate.
                    ref_images_to_use = [prev_img_path]
                    use_style_swatch = False
                    print(f"[IMG GENERATION] Viewfinder: source frame is the sole img2img reference [{os.path.basename(prev_img_path)}]")
                
                # Character / level plates are passed as identity_paths, not
                # mixed into the continuity list. Appending them here made
                # Gemini treat the previous Jason still as "the person" and
                # the authored sheet as a second previous frame.
                if identity_plates:
                    print(f"[IDENTITY] {len(identity_plates)} plate(s) ride as labeled identity, "
                          f"not as extra continuity frames")

                print(f"[IMG GENERATION] References being passed to API:")
                for i, ref in enumerate(ref_images_to_use):
                    print(f"[IMG GENERATION]   {i+1}. {os.path.basename(ref)}")
                print(f"{'='*70}\n")
                
                # ALWAYS use HQ for first image, then respect quality toggle
                use_hq_for_this_frame = True if frame_idx == 0 else QUALITY_MODE
                if frame_idx == 0:
                    print(f"[QUALITY MODE] Frame 0 (intro) - FORCING HQ (Gemini Pro) for visual consistency")
                
                # --- FLIPBOOK: this turn's frames instead of one still ---
                # Inline, and that is the point. This used to fire into a daemon
                # thread beside the still for a Discord client to poll, leaving
                # the turn itself with result_path = None — the "signal lost"
                # beat. The sequence's last panel IS the still now, so the turn
                # waits for it.
                current_state = _load_state(session_id)
                flipbook_enabled = flipbook_active(current_state, identity_spec)
                flipbook_seq = None
                if flipbook_enabled:
                    flipbook_seq = _flipbook_generate(
                        prompt_str=prompt_str,
                        caption=caption,
                        choice=choice,
                        dispatch=dispatch,
                        world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        img_dir=img_dir,
                        session_id=session_id,
                        st=current_state,
                        refs=ref_images_to_use,
                        # Same character sheet / level plate the still path uses,
                        # so the animated panels keep YOUR protagonist. On frame 0
                        # (nothing to continue from) seed from the plate so the
                        # opening flipbook is your character, not a stranger.
                        identity_paths=identity_plates,
                        identity_seed=bool(frame_idx == 0 or hard_transition),
                        spec=identity_spec,
                        # Flipbook is the default renderer, so a close-up plate
                        # that only reached the still path would reach almost no
                        # real turns.
                        cast_plates=cast_plate_paths,
                        # ...and it is the renderer that was ignoring hard cuts:
                        # the still path relocates, the grid held the room.
                        hard_cut=bool(hard_transition and frame_idx > 0),
                        design_refs=design_ref_paths or None,
                    )
                    # A flipbook that didn't come back costs quality, not the
                    # turn: fall through to the ordinary still below.
                    flipbook_enabled = bool(flipbook_seq)

                # --- STATIC IMAGE GENERATION (Skip if in Flipbook Mode) ---
                if not flipbook_enabled and not ref_images_to_use and not identity_plates:
                    # Hard transition with nothing to attach (no identity plates
                    # configured for this game): go straight to pure text-to-image
                    # rather than calling the img2img endpoint with an empty
                    # reference list and hoping it degrades sensibly. This is the
                    # same function the img2img call below already falls back to
                    # on failure — using it directly here, on purpose, is what
                    # actually produces a fresh composition instead of an edit.
                    print(f"[IMG GENERATION] Hard transition, no references to attach - "
                          f"generating via text-to-image", flush=True)
                    result_path = generate_with_gemini(
                        prompt=prompt_str,
                        caption=caption,
                        world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        is_first_frame=(frame_idx == 0),
                        action_context=choice,
                        hd_mode=use_hq_for_this_frame,
                        output_dir=img_dir,
                    )
                elif not flipbook_enabled:
                    result_path = generate_gemini_img2img(
                        prompt=prompt_str,
                        caption=caption,
                        reference_image_path=ref_images_to_use,  # Adjusted based on transition type
                        world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        action_context=choice,  # Pass action for FPS hands context
                        hd_mode=use_hq_for_this_frame,  # Frame 0 always HQ, others respect quality toggle
                        output_dir=img_dir,  # Session-specific directory
                        style_only_swatch=use_style_swatch,
                        identity_seed=bool(hard_transition and identity_plates),
                        identity_paths=identity_plates,
                        spec=identity_spec,
                        cast_plates=cast_plate_paths,
                        design_refs=design_ref_paths or None,
                    )
                    # SAFETY NET: img2img can come back empty (API timeout on the
                    # slow lite model, a safety block triggered by the accumulated
                    # live-frame references, or a transient API error — all of which
                    # generate_gemini_img2img swallows into a None). When that
                    # happens the turn used to emit NOTHING, so "interacting" left
                    # the scene frozen on the last frame ("gemini fast can't render a
                    # new image on interact"). Fall back to a plain text-to-image
                    # render (no reference images → smaller payload, far less likely
                    # to time out or trip the reference-driven safety filter) so a
                    # FRESH frame still lands. We lose pixel-perfect img2img
                    # continuity for that one turn, but the world keeps moving —
                    # which mirrors the Krea/fal branches' existing Gemini safety net.
                    if not result_path and (identity_plates or cast_plate_paths):
                        # Drop the accumulated continuity frames (the usual
                        # suspects for a timeout or a reference-driven safety
                        # block) but KEEP the player's own plates: falling all
                        # the way back to text-to-image is what silently drops
                        # the character sheet, so the recovery frame is the one
                        # frame in the run their character isn't in.
                        print(f"[IMG GENERATION] img2img returned no image - retrying from the "
                              f"{len(identity_plates)} identity plate(s) and "
                              f"{len(cast_plate_paths)} close-up plate(s) alone", flush=True)
                        result_path = generate_gemini_img2img(
                            prompt=prompt_str,
                            caption=caption,
                            reference_image_path=identity_plates or cast_plate_paths,
                            world_prompt=world_prompt,
                            time_of_day=use_time_of_day,
                            action_context=choice,
                            hd_mode=use_hq_for_this_frame,
                            output_dir=img_dir,
                            identity_seed=True,
                            identity_paths=identity_plates,
                            spec=identity_spec,
                            # The recovery frame is the one frame in the run the
                            # character sheet used to be missing from; a face the
                            # player met ten seconds ago deserves the same care.
                            cast_plates=cast_plate_paths,
                        )
                    if not result_path:
                        print(f"[IMG GENERATION] img2img returned no image - falling back to text-to-image so the scene still advances", flush=True)
                        result_path = generate_with_gemini(
                            prompt=prompt_str,
                            caption=caption,
                            world_prompt=world_prompt,
                            time_of_day=use_time_of_day,
                            is_first_frame=(frame_idx == 0),
                            action_context=choice,
                            hd_mode=use_hq_for_this_frame,
                            output_dir=img_dir,
                        )
                else:
                    print(f"[IMG GENERATION] Flipbook sequence stands in for the still "
                          f"({flipbook_seq['frame_count']} frames)")
                    result_path = flipbook_seq['still_path']
            else:
                print(f"\n{'='*70}")
                print(f"[IMG GENERATION] USING TEXT-TO-IMAGE MODE (NO STYLE ANCHOR)")
                print(f"[IMG GENERATION] Reasons:")
                print(f"[IMG GENERATION]   - prev_img_paths_list has {len(prev_img_paths_list)} items")
                print(f"[IMG GENERATION]   - frame_idx={frame_idx}")
                if len(prev_img_paths_list) == 0:
                    print(f"[IMG GENERATION] NO REFERENCE IMAGES IN HISTORY")
                    print(f"[IMG GENERATION] This may cause style/aesthetic discontinuity")
                print(f"{'='*70}\n")
                
                # --- FLIPBOOK: this turn's frames instead of one still ---
                # Same inline treatment as the img2img branch above. Nothing to
                # continue from here (intro turn, or a run with no history), so
                # the player's own plates are the only spatial anchor available.
                current_state = _load_state(session_id)
                flipbook_enabled = flipbook_active(current_state, identity_spec)
                flipbook_seq = None
                if flipbook_enabled:
                    flipbook_seq = _flipbook_generate(
                        prompt_str=prompt_str,
                        caption=caption,
                        choice=choice,
                        dispatch=dispatch,
                        world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        img_dir=img_dir,
                        session_id=session_id,
                        st=current_state,
                        refs=list(identity_plates or []),
                    )
                    flipbook_enabled = bool(flipbook_seq)

                # ALWAYS use HQ for first image, then respect quality toggle
                use_hq_for_this_frame = True if frame_idx == 0 else QUALITY_MODE
                if frame_idx == 0:
                    print(f"[QUALITY MODE] Frame 0 (intro) - FORCING HQ (Gemini Pro) for visual consistency")
                
                # --- STATIC IMAGE GENERATION (Skip if in Flipbook Mode) ---
                if not flipbook_enabled:
                    if identity_plates:
                        # No previous frame to continue from, but the player HAS
                        # supplied art. Go through img2img so the opening frame is
                        # built out of their level plate and their character sheet
                        # instead of the model's guess at the same words.
                        print(f"[IDENTITY] No history — seeding this frame from "
                              f"{len(identity_plates)} reference plate(s)", flush=True)
                        result_path = generate_gemini_img2img(
                            prompt=prompt_str,
                            caption=caption,
                            reference_image_path=identity_plates,
                            world_prompt=world_prompt,
                            time_of_day=use_time_of_day,
                            action_context=choice,
                            hd_mode=use_hq_for_this_frame,
                            output_dir=img_dir,
                            identity_seed=True,
                            identity_paths=identity_plates,
                            spec=identity_spec,
                        )
                    else:
                        result_path = None
                    if not result_path:
                        result_path = generate_with_gemini(
                            prompt=prompt_str,
                            caption=caption,
                            world_prompt=world_prompt,
                            time_of_day=use_time_of_day,
                            is_first_frame=(frame_idx == 0),  # Keep for fallback logic
                            action_context=choice,  # Pass action for FPS hands context
                            hd_mode=use_hq_for_this_frame,  # Frame 0 always HQ, others respect quality toggle
                            output_dir=img_dir  # Session-specific directory
                        )
                else:
                    print(f"[IMG GENERATION] Flipbook sequence stands in for the still "
                          f"({flipbook_seq['frame_count']} frames)")
                    result_path = flipbook_seq['still_path']
            # A flipbook turn whose grid did not come back stood a still in. That
            # still is the whole render, twice the size of every panel around
            # it, so it arrives as the one sharp frame in a run of soft ones —
            # shrunk to a panel here (flipbook.match_panel_size).
            if result_path and not locals().get("flipbook_seq"):
                try:
                    _fb_st = _load_state(session_id)
                    if flipbook_active(_fb_st, identity_spec) and flipbook.match_panel_size(
                            result_path, flipbook_settings(_fb_st)["frames"],
                            like=_fb_st.get("flipbook_last_frame")):
                        print(f"[IMG GENERATION] still stands in for the flipbook — "
                              f"shrunk to panel size", flush=True)
                except Exception:
                    pass
            # Return canonical frame (always single image now)
            _last_image_path = result_path
            return (result_path, prompt_str, None)  # Return canonical frame for story logic

        elif active_image_provider == "krea":
            # Use Krea 2 (foundation image model). img2img continuity is done via
            # Krea's style-transfer system (previous frame(s) uploaded as style
            # references). Mirrors the Gemini branch's t2i/img2img split and the
            # realtime guide-still quality guard.
            print(f"[IMG] Using Krea 2 provider")
            from krea_image_utils import generate_with_krea, generate_krea_img2img

            use_hq_for_this_frame = True if frame_idx == 0 else QUALITY_MODE
            if frame_idx == 0:
                print(f"[QUALITY MODE] Frame 0 (intro) - FORCING Krea Large for visual consistency")

            if prev_img_paths_list and frame_idx > 0:
                # Most-recent frame is the strongest continuity anchor.
                ref_images_to_use = prev_img_paths_list[:1]

                if hard_transition:
                    # The blurred swatch is a workaround for a GEMINI problem:
                    # handed a legible photo, Gemini's img2img reproduces its
                    # composition, so the geometry has to be destroyed before
                    # the request to get lighting continuity without a layout
                    # to copy. Krea does not have that problem — references go
                    # into `image_style_references`, a genuine style channel
                    # that already takes palette and grain without composition.
                    # Giving THAT channel a blurred colour field means the blur
                    # is the style, and Krea faithfully returns a smear with no
                    # scene in it. The sharp frame is the correct input here:
                    # it yields a new composition in the same world.
                    ref_images_to_use = prev_img_paths_list[:1]
                    print(f"[IMG GENERATION] Krea hard cut — previous frame as STYLE reference "
                          f"(Krea's style channel carries no composition; no swatch needed)")
                elif (live_capture_this
                        and prev_img_path and os.path.exists(prev_img_path)):
                    ref_images_to_use = [prev_img_path]
                    if primary_guide_image_path and primary_guide_image_path != prev_img_path:
                        ref_images_to_use.append(primary_guide_image_path)
                    print(f"[IMG GENERATION] Krea: live world-model frame is PRIMARY style reference")
                elif primary_guide_image_path:
                    live_frame = ref_images_to_use[0] if ref_images_to_use else None
                    if frame_idx == 1:
                        ref_images_to_use = [primary_guide_image_path]
                        print(f"[IMG GENERATION] Krea realtime: guide still as sole style reference")
                    else:
                        ref_images_to_use = [primary_guide_image_path]
                        if live_frame and live_frame != primary_guide_image_path:
                            ref_images_to_use.append(live_frame)
                        print(f"[IMG GENERATION] Krea realtime dual-ref: guide still PRIMARY + live frame SECONDARY")

                # Plates lead. A captured live frame of the leftover guy used
                # to sit in slot 1 and win every MOVE TO.
                if identity_plates:
                    leading = [p for p in identity_plates if p not in ref_images_to_use]
                    ref_images_to_use = (leading + ref_images_to_use)[:4]
                    print(f"[IDENTITY] {len(leading)} plate(s) lead the Krea reference list")

                if ref_images_to_use:
                    print(f"[IMG GENERATION] Krea img2img (style transfer) with {len(ref_images_to_use)} reference(s)")
                    result_path = generate_krea_img2img(
                        prompt=prompt_str,
                        caption=caption,
                        reference_image_path=ref_images_to_use,
                        world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        action_context=choice,
                        hd_mode=use_hq_for_this_frame,
                        output_dir=img_dir,
                    )
                else:
                    print(f"[IMG GENERATION] Krea text-to-image (hard cut, no composition reference)")
                    result_path = generate_with_krea(
                        prompt=prompt_str,
                        caption=caption,
                        world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        is_first_frame=False,
                        action_context=choice,
                        hd_mode=use_hq_for_this_frame,
                        output_dir=img_dir,
                    )
            elif identity_plates:
                # No history, but the player supplied art. Same call the Gemini
                # branch makes on frame 0: build the opening frame out of their
                # plates instead of the model's guess at the same words.
                print(f"[IDENTITY] No history — seeding this Krea frame from "
                      f"{len(identity_plates)} reference plate(s)", flush=True)
                result_path = generate_krea_img2img(
                    prompt=prompt_str,
                    caption=caption,
                    reference_image_path=identity_plates,
                    world_prompt=world_prompt,
                    time_of_day=use_time_of_day,
                    action_context=choice,
                    hd_mode=use_hq_for_this_frame,
                    output_dir=img_dir,
                )
            else:
                print(f"[IMG GENERATION] Krea text-to-image (no reference anchor)")
                result_path = generate_with_krea(
                    prompt=prompt_str,
                    caption=caption,
                    world_prompt=world_prompt,
                    time_of_day=use_time_of_day,
                    is_first_frame=(frame_idx == 0),
                    action_context=choice,
                    hd_mode=use_hq_for_this_frame,
                    output_dir=img_dir,
                )

            # SAFETY NET: if Krea failed (job error/timeout or missing key) but
            # Gemini is available, render the frame with Gemini so the world
            # never goes blank on a single bad turn.
            if not result_path and provider_bridge.can_call_gemini_api():
                print(f"[IMG] Krea returned no image - falling back to Gemini for this frame", flush=True)
                from gemini_image_utils import generate_with_gemini, generate_gemini_img2img
                if prev_img_paths_list and frame_idx > 0:
                    fb_refs = [primary_guide_image_path] if primary_guide_image_path else prev_img_paths_list[:1]
                    result_path = generate_gemini_img2img(
                        prompt=prompt_str, caption=caption, reference_image_path=fb_refs,
                        world_prompt=world_prompt, time_of_day=use_time_of_day,
                        action_context=choice, hd_mode=use_hq_for_this_frame, output_dir=img_dir,
                    )
                else:
                    result_path = generate_with_gemini(
                        prompt=prompt_str, caption=caption, world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        is_first_frame=(frame_idx == 0), action_context=choice,
                        hd_mode=use_hq_for_this_frame, output_dir=img_dir,
                    )

            _last_image_path = result_path
            return (result_path, prompt_str, None)

        elif active_image_provider == "fal":
            # fal.ai SDXL Lightning — optional speed preset. Synchronous REST
            # call typically completes in ~1-2s (vs ~12s Krea Medium / ~15-30s
            # Gemini Pro), at the cost of lower fidelity than either. Only a
            # single reference image is supported for continuity.
            print(f"[IMG] Using fal.ai (SDXL Lightning) provider")
            from fal_image_utils import generate_with_fal, generate_fal_img2img

            if prev_img_paths_list and frame_idx > 0:
                if hard_transition and identity_plates:
                    ref_image_to_use = identity_plates[0]
                    print(f"[IDENTITY] Hard cut — fal's one slot is the character plate")
                else:
                    ref_image_to_use = primary_guide_image_path or prev_img_paths_list[0]
                print(f"[IMG GENERATION] fal img2img with reference: {Path(ref_image_to_use).name}")
                result_path = generate_fal_img2img(
                    prompt=prompt_str,
                    caption=caption,
                    reference_image_path=ref_image_to_use,
                    world_prompt=world_prompt,
                    time_of_day=use_time_of_day,
                    action_context=choice,
                    output_dir=img_dir,
                )
            elif identity_plates:
                # SDXL takes exactly ONE reference, so continuity always wins
                # the slot once there is a frame to continue from. With no
                # history there is nothing to lose by spending it on the
                # player's own art, which is the whole point of frame 0.
                print(f"[IDENTITY] No history — seeding this fal frame from "
                      f"{os.path.basename(identity_plates[0])}", flush=True)
                result_path = generate_fal_img2img(
                    prompt=prompt_str,
                    caption=caption,
                    reference_image_path=identity_plates[0],
                    world_prompt=world_prompt,
                    time_of_day=use_time_of_day,
                    action_context=choice,
                    output_dir=img_dir,
                )
            else:
                print(f"[IMG GENERATION] fal text-to-image (no reference anchor)")
                result_path = generate_with_fal(
                    prompt=prompt_str,
                    caption=caption,
                    world_prompt=world_prompt,
                    time_of_day=use_time_of_day,
                    is_first_frame=(frame_idx == 0),
                    action_context=choice,
                    output_dir=img_dir,
                )

            # SAFETY NET: if fal failed (bad key, rate limit, etc.) but Gemini
            # is available, render the frame with Gemini so the world never
            # goes blank on a single bad turn.
            if not result_path and provider_bridge.can_call_gemini_api():
                print(f"[IMG] fal returned no image - falling back to Gemini for this frame", flush=True)
                from gemini_image_utils import generate_with_gemini, generate_gemini_img2img
                if prev_img_paths_list and frame_idx > 0:
                    fb_refs = [primary_guide_image_path] if primary_guide_image_path else prev_img_paths_list[:1]
                    result_path = generate_gemini_img2img(
                        prompt=prompt_str, caption=caption, reference_image_path=fb_refs,
                        world_prompt=world_prompt, time_of_day=use_time_of_day,
                        action_context=choice, hd_mode=False, output_dir=img_dir,
                    )
                else:
                    result_path = generate_with_gemini(
                        prompt=prompt_str, caption=caption, world_prompt=world_prompt,
                        time_of_day=use_time_of_day,
                        is_first_frame=(frame_idx == 0), action_context=choice,
                        hd_mode=False, output_dir=img_dir,
                    )

            _last_image_path = result_path
            return (result_path, prompt_str, None)

        elif active_image_provider == "openai":
            # Use OpenAI gpt-image-1
            # Supports img2img via /images/edits endpoint (up to 16 reference images!)
            
            # Validate API key
            if not OPENAI_API_KEY:
                print("[OPENAI IMG] ERROR: OPENAI_API_KEY not set! Cannot generate image.")
                print("[OPENAI IMG] Set environment variable OPENAI_API_KEY or add to config.json")
                return (None, "", None)
            
            # Try IMG2IMG if we have reference images AND it's enabled. The
            # player's own plates count as references, so an authored character
            # routes the opening frame through /images/edits too.
            openai_refs = list(prev_img_paths_list[:OPENAI_IMG2IMG_REFERENCE_COUNT]) \
                if (prev_img_paths_list and frame_idx > 0) else []
            for plate in identity_plates:
                if plate not in openai_refs:
                    openai_refs.append(plate)
            use_img2img = bool(OPENAI_IMG2IMG_ENABLED and openai_refs)
            img2img_success = False
            
            if use_img2img:
                # IMG2IMG MODE - Use /images/edits with previous frames as reference
                # Using raw requests because Python SDK doesn't support multiple images properly
                print(f"[OPENAI IMG2IMG] Attempting img2img with {len(openai_refs)} reference image(s)")
                print(f"[OPENAI IMG2IMG] Rendering shared image template...")
                
                # Render through the shared image template (same as Gemini)
                vhs_prompt = _build_vhs_prompt(prompt_str, use_img2img=True)
                
                # Build multipart form-data with multiple images
                files = []
                for idx, img_path in enumerate(openai_refs):
                    if os.path.exists(img_path):
                        try:
                            files.append(('image[]', (os.path.basename(img_path), open(img_path, 'rb'), 'image/png')))
                            print(f"[OPENAI IMG2IMG] Added reference {idx+1}: {os.path.basename(img_path)}")
                        except Exception as e:
                            print(f"[OPENAI IMG2IMG] Failed to open {img_path}: {e}")
                
                # If no files could be opened, fall back to text-to-image
                if len(files) == 0:
                    print(f"[OPENAI IMG2IMG] No reference images available, falling back to TEXT-TO-IMAGE")
                else:
                    print(f"[OPENAI IMG2IMG] Total references: {len(files)}")
                    
                if len(files) > 0:
                    try:
                        # Use raw requests library for multipart form-data
                        headers = {
                            "Authorization": f"Bearer {OPENAI_API_KEY}"
                        }
                        data = {
                            'model': 'gpt-image-1',
                            'prompt': vhs_prompt,
                            'n': '1',
                            'size': '1536x1024',
                            'quality': OPENAI_IMG2IMG_QUALITY,  # Configurable: 'low', 'medium', 'high'
                            'input_fidelity': 'high',  # CRITICAL: Stick closer to reference images
                            'moderation': 'low'
                        }
                        
                        response = requests.post(
                            "https://api.openai.com/v1/images/edits",
                            headers=headers,
                            data=data,
                            files=files,
                            timeout=60  # 60 second timeout
                        )
                        
                        if response.status_code != 200:
                            print(f"[OPENAI IMG2IMG] HTTP ERROR {response.status_code}: {response.text}")
                            raise Exception(f"OpenAI API error: {response.status_code}")
                        
                        # Parse JSON response with error handling
                        try:
                            result = response.json()
                        except json.JSONDecodeError as e:
                            print(f"[OPENAI IMG2IMG] Failed to parse JSON response: {e}")
                            raise Exception(f"Invalid JSON response from OpenAI: {e}")
                        
                        # Extract image data with error handling
                        if 'data' not in result or len(result['data']) == 0:
                            print(f"[OPENAI IMG2IMG] No image data in response")
                            raise Exception("OpenAI response missing 'data' field")
                        
                        if 'b64_json' not in result['data'][0]:
                            print(f"[OPENAI IMG2IMG] No b64_json in response data")
                            raise Exception("OpenAI response missing 'b64_json' field")
                        
                        b64_data = result['data'][0]['b64_json']
                        
                        # Decode and save the image with error handling
                        try:
                            img_data = base64.b64decode(b64_data)
                        except Exception as e:
                            print(f"[OPENAI IMG2IMG] Failed to decode base64: {e}")
                            raise Exception(f"Base64 decode error: {e}")
                        
                        try:
                            with open(image_path, "wb") as f:
                                f.write(img_data)
                        except Exception as e:
                            print(f"[OPENAI IMG2IMG] Failed to write image file: {e}")
                            raise Exception(f"File write error: {e}")
                        
                        print(f"[OPENAI IMG2IMG] Edit complete with {len(files)} reference(s)")
                        print(f"[OPENAI IMG2IMG] Image saved to: {image_path}")
                        
                        img2img_success = True
                        _last_image_path = f"/images/{filename}"
                        return (_last_image_path, vhs_prompt, None)  # OpenAI doesn't generate videos
                        
                    except Exception as e:
                        print(f"[OPENAI IMG2IMG] Error during img2img: {e}")
                        print(f"[OPENAI IMG2IMG] Will fall back to TEXT-TO-IMAGE")
                        # Don't re-raise - let it fall through to text-to-image fallback
                        
                    finally:
                        # Close all file handles
                        for field_name, file_tuple in files:
                            try:
                                # file_tuple is (filename, file_obj, mime_type)
                                file_tuple[1].close()
                            except Exception as e:
                                print(f"[OPENAI IMG2IMG] Warning: Failed to close file handle: {e}")
            
            # TEXT-TO-IMAGE MODE - Either img2img failed or no reference images
            if not img2img_success:
                print(f"[OPENAI TEXT2IMG] Generating fresh image")
                print(f"[OPENAI TEXT2IMG] Rendering shared image template...")
                
                # Render through the shared image template (same as Gemini)
                vhs_prompt = _build_vhs_prompt(prompt_str, use_img2img=False)
                
                response = client.images.generate(
                    model="gpt-image-1",
                    prompt=vhs_prompt,  # ← Now using VHS-wrapped prompt!
                    n=1,
                    size="1536x1024",  # Landscape (closer to 4:3)
                    quality=OPENAI_IMG2IMG_QUALITY,  # Use same quality as img2img for consistency
                    moderation="low"  # Less restrictive for horror content
                )
                
                # gpt-image-1 always returns b64_json (no URL option)
                b64_data = response.data[0].b64_json
                img_data = base64.b64decode(b64_data)
                
                with open(image_path, "wb") as f:
                    f.write(img_data)
                print(f"[OPENAI TEXT2IMG] Image saved to: {image_path}")
                
            _last_image_path = f"/images/{filename}"
            return (_last_image_path, vhs_prompt, None)  # OpenAI doesn't generate videos
        
        else:
            raise ValueError(f"Unknown IMAGE_PROVIDER: {active_image_provider}. Supported: 'openai', 'gemini', 'veo', 'krea', 'fal'")
        # Skip time extraction - we already set time_of_day in state before generation
        # No need to extract it back from the image we just generated!
        return (f"/images/{filename}", prompt_str, None)
    except Exception as e:
        try:
            safe_error = str(e).encode('ascii', 'replace').decode('ascii')
            print(f"[IMG PROVIDER {ai_provider_manager.get_image_provider()}] Error: {safe_error}")
            import traceback
            traceback.print_exc()
        except UnicodeEncodeError:
            # Windows console can't handle Unicode in traceback - print minimal info
            print(f"[IMG PROVIDER] Error during image generation (traceback contains special characters)")
            print(f"[IMG PROVIDER] Error type: {type(e).__name__}")
        return (None, "", None)

# ───────── image prompt sanitization ─────────────────────────────────────────
def _sanitize_for_image_generation(text: str) -> str:
    """
    Sanitize visual descriptions to avoid content filters while keeping dramatic tension.
    Only affects IMAGE prompts - narrative text stays intact!
    """
    import re
    
    # Explicit gore/violence keywords to soften
    replacements = {
        # Blood and injuries
        r'\b(blood|bleeding|bloody)\b': 'dark stains',
        r'\bgushes?\b': 'flows',
        r'\bsoaked?\b': 'dampened',
        r'\bsoaking\b': 'wetting',
        r'\bbleeding\b': 'injured',
        r'\bhemorrhag(e|ing)\b': 'severe injury',
        
        # Wounds and gore
        r'\bwound(s)?\b': 'injury',
        r'\bgash(es)?\b': 'tear',
        r'\bgaping\b': 'deep',
        r'\bopen wound\b': 'injury',
        r'\brip(s|ped|ping)?\b': 'tear',
        r'\bsever(ed|ing)?\b': 'separated',
        r'\bgore\b': 'injury',
        r'\bgory\b': 'disturbing',
        r'\bviscera\b': 'internal damage',
        r'\bentrails\b': 'remains',
        r'\bguts\b': 'interior',
        
        # Body parts and trauma
        r'\bflesh\b': 'tissue',
        r'\bimpale(d|s|ment)?\b': 'pierce',
        r'\bpiercing through\b': 'penetrating',
        r'\bpuncture(d|s)?\b': 'penetrate',
        r'\bmaul(ed|ing)?\b': 'attacked severely',
        r'\bmutilate(d|s)?\b': 'damaged severely',
        r'\bdismember(ed|ing|ment)?\b': 'torn apart',
        r'\bshredded\b': 'torn',
        r'\bslashed\b': 'cut',
        
        # Explicit damage descriptions
        r'\btearing (through|into)\b': 'damaging',
        r'\bripping through\b': 'tearing into',
        r'\bembedded in\b': 'stuck in',
        r'\blodged in\b': 'caught in',
        r'\bpulled free\b': 'removed',
        r'\byanked out\b': 'extracted',
        
        # Violence and pain
        r'\bagony\b': 'severe pain',
        r'\bscreaming\b': 'crying out',
        r'\bshriek(ing|s)?\b': 'calling out',
        r'\btorture(d)?\b': 'extreme discomfort',
        r'\bthrobbing\b': 'pulsing',
        r'\bburning pain\b': 'intense sensation',
        
        # Body horror
        r'\bbone fragments?\b': 'debris',
        r'\bexposed bone\b': 'structural damage',
        r'\bfractured?\b': 'broken',
        r'\bshattered\b': 'broken badly',
        r'\bcrushed\b': 'compressed',
        r'\bpulp\b': 'mush',
        r'\bmangled\b': 'damaged',
        r'\brotting\b': 'decaying',
        r'\bdecompos(ing|ed)\b': 'deteriorating',
        
        # Death and corpses
        r'\bcorpse(s)?\b': 'remains',
        r'\bdead bod(y|ies)\b': 'remains',
        r'\bcadaver(s)?\b': 'remains',
        r'\bskull(s)?\b': 'cranium',
    }
    
    # Apply replacements (case-insensitive)
    sanitized = text
    for pattern, replacement in replacements.items():
        sanitized = re.sub(pattern, replacement, sanitized, flags=re.IGNORECASE)
    
    # Remove intensifiers that make it more graphic
    sanitized = re.sub(r'\b(violently|brutally|viciously|savagely|horrifically)\s+', '', sanitized, flags=re.IGNORECASE)
    
    # Soften extreme descriptors
    sanitized = re.sub(r'\b(profusely|heavily)\s+(bleeding|damaged)', r'significantly injured', sanitized, flags=re.IGNORECASE)
    
    # Remove redundant graphic details
    sanitized = re.sub(r'\s+stained (with blood|red)', ' stained darkly', sanitized, flags=re.IGNORECASE)
    
    print(f"[SANITIZE] Original length: {len(text)}, Sanitized length: {len(sanitized)}")
    if text != sanitized:
        print(f"[SANITIZE] Changes applied to image prompt (narrative text unchanged)")
    
    return sanitized

# ───────── vision dispatch generator ─────────────────────────────────────────
def _generate_vision_dispatch(narrative_dispatch: str, world_prompt: str = "") -> str:
    # `visual_scene` written here becomes the image prompt, so the rules about
    # who may appear in frame have to follow the camera. In third person the
    # "do not show the protagonist" rules are exactly backwards.
    if game_identity.shows_character():
        cfg = game_identity.mode_config()
        who = game_identity.display_name()
        framing = (
            f"Rewrite the following narrative as a present-tense description of what the camera sees "
            f"in {cfg['phrase']} view. {who} is IN the shot — describe where they are in the frame, "
            f"their posture, and what they are doing, then the space around them. "
            f"No internal thoughts, no sound, no feelings — only what is visible."
        )
        prompt = (
            "You are a visual scene writer for a video game camera.\n\n"
            + framing
            + f"\n\nNARRATIVE DISPATCH: {narrative_dispatch}\n\nWORLD CONTEXT: {world_prompt}"
        )
    else:
        prompt = (
            "You are a visual scene writer. Output only the literal, visible scene as you would see it, in first-person present tense.\n\n"
            "Rewrite the following narrative as a first-person, present-tense description of what you see, suitable for a visual scene. "
            "Only describe what is visible. Do not include yourself or any internal thoughts. "
            "Do not show yourself. Do not show the protagonist. Do not show any character from behind. Only show what you see from your own eyes. "
            f"\n\nNARRATIVE DISPATCH: {narrative_dispatch}\n\nWORLD CONTEXT: {world_prompt}"
        )
    # Don't use lore - this is just reformatting narrative to visual description
    result = _ask(prompt, model="gemini", temp=1.0, tokens=100, use_lore=False)
    return result

# ───────── public API (two‑stage) ───────────────────────────────────────────
def _generate_situation_report(current_image: str = None, current_dispatch: str = None, vision_analysis: str = None) -> str:
    """Generate situation report with optional visual context from current frame."""
    if history or current_dispatch:
        # Use provided dispatch or last one from history
        last_dispatch = current_dispatch if current_dispatch else (history[-1]["dispatch"] if history else "")
        
        # Use the updated world state after the simulation tick
        state_data = _load_state()
        world_state = state_data.get("world_prompt", "")
        turn_count = len(history)
        
        major_event_nudge = ""
        if turn_count % 5 == 0 and turn_count > 0:
            major_event_nudge = (
                "\n\nIMPORTANT: This is a turning point. Introduce a major new development, threat, opportunity, or mystery. Shake up the situation in a dramatic way."
            )
        
        prompt = game_identity.apply(
            PROMPTS.get("situation_summary_instructions", "Describe what is happening NOW."),
            "narrative",
        ) + f"\n\nWorld State (before current moment):\n{world_state}\n\nNarrative Result of Last Action:\n{last_dispatch}"
        
        if vision_analysis:
            prompt += f"\n\nVisual Reality (what is actually seen):\n{vision_analysis}"
            
        prompt += major_event_nudge + "\n\nDescribe what is happening NOW as a concise 1-2 sentence situation report. This should reconcile the narrative text with the visual reality."
        
        # Don't use lore - this is just a summary with visual grounding
        return _ask(prompt, model="gemini", temp=1.0, tokens=60, image_path=current_image, use_lore=False)
    
    authored = game_identity.opening_shot()
    if authored:
        return authored["prologue"]
    return "You stand on a rocky outcrop overlooking the Horizon facility, situated in the distance, surrounded by the vast red american southwest."

def begin_tick() -> dict:
    from choices import generate_choices  # Local import to avoid circular dependency
    
    state = _load_state()
    # If at intro/prologue, return generate_intro_turn result (with choices)
    if not history or (state.get('last_choice', '') == '' and state.get('world_prompt', '').startswith('You crouch behind a rusted Horizon vehicle')):
        return generate_intro_turn()
    # Generate a world summary (narrative)
    world_summary = state["world_prompt"]
    # Use the last dispatch as the situation report
    situation_report = history[-1]["dispatch"]
    # Use evolution summary if available, otherwise fallback
    interim_messages = state.get("evolution_summary", "World state evolving...")
    loader = interim_messages
    # Generate the narrative update using the narrative prompt
    narrative_update = _world_report()
    # Condense world state for choices
    situation_summary = summarize_world_state(state)
    options = generate_choices(
        client, PROMPTS["player_choice_generation_instructions"],
        situation_report,
        n=3,
        seen_elements=', '.join(state.get('seen_elements', [])[-10:]),  # Last 10 discovered entities
        recent_choices=recent_actions_taken(state),
        caption=situation_report,
        image_description='',
        world_prompt=state.get('world_prompt', ''),
        temperature=0.2,
        situation_summary=situation_summary,
        beat_nudge=beat_nudge_text(state),
    )
    # Remove placeholder/empty choices
    options = [c for c in options if c and c.strip() and c.strip() != '—']
    if not options:
        options = ["Look around", "Move forward", "Wait"]
    while len(options) < 3:
        options.append("")
    return {
        "situation_report": situation_report,  # Return this as a separate field
        "choices": options,
        "interim_loader": loader,
    }

def _extract_time_and_color(image_path: str) -> tuple[str, str]:
    """Extract time of day and color palette (uses cached unified analysis)."""
    result = _vision_analyze_all(image_path)
    return result["time_of_day"], result["color_palette"]

# Weather words that stand or fall together. A world that rules out storms has
# ruled out the lightning inside them, but "no storms or thunderclouds" is the
# only sentence it is ever going to write about it — so a ban on one member bans
# the family. Without this, a legal roll of "hazy twilight with purple lightning"
# passed the shape check and became the `Lighting:` line on every render of the
# session, because time_of_day is written once at reset and never re-examined.
_WEATHER_FAMILIES = (
    ("storm", "storms", "stormy", "thunderstorm", "thunderstorms", "thundercloud",
     "thunderclouds", "thunderhead", "thunder", "lightning", "squall", "tempest"),
    ("rain", "rainy", "raining", "rainfall", "downpour", "drizzle", "sleet", "hail", "monsoon"),
    ("snow", "snowy", "snowing", "snowfall", "blizzard", "flurries"),
    ("fog", "foggy", "mist", "misty"),
)


def _world_constraint_text() -> str:
    """The authored prose a world states its rules in, as it exists at reset.

    Read at reset rather than from state['world_prompt'], because the run's world
    document is built after this and the evolving copy will eventually describe
    whatever is actually happening.
    """
    parts = [PROMPTS.get("world_initial_state", "") or ""]
    try:
        setting = game_identity.authored_setting() or {}
        parts += [str(setting.get("opening_shot") or ""), str(setting.get("summary") or "")]
    except Exception:
        pass
    return "\n".join(p for p in parts if p)


def _forbidden_weather(text: str) -> set:
    """Weather words the world names only to rule out, expanded by family."""
    banned = set()
    for family in _WEATHER_FAMILIES:
        for term in family:
            if (re.search(rf"\b{re.escape(term)}\b", text or "", flags=re.I)
                    and not _world_asserts(text, term)):
                banned.update(family)
                break
    return banned


def _named_terms(text: str, terms) -> list:
    return sorted(t for t in terms
                  if re.search(rf"\b{re.escape(t)}\b", text or "", flags=re.I))


def _generate_random_starting_time() -> str:
    """
    Use LLM to generate a randomized starting time/weather/mood for each game session.
    Format: "6:30pm | weather: clear, warm light | mood: tense anticipation"
    """
    # The weather of the run has to be the weather of the LEVEL. Asking for
    # "desert weather" in an authored flooded shipyard produced a dust-storm
    # mood line that then coloured every image prompt for the whole session.
    place = game_identity.place_summary() or "the American Southwest desert at a mysterious facility"
    weather_rule = (
        "Weather that fits that location + lighting description"
        if game_identity.setting_enabled()
        else "Desert weather + lighting description (clear/cloudy/dusty/overcast + lighting type)"
    )
    # The level's OWN light, if the sheet names one. Without this the roll only
    # ever saw the place's name — place_summary() excludes palette on purpose —
    # so on a level whose plate reads "PALETTE & LIGHT: golden hour, rust, red
    # dust" it happily returned "7:43pm | weather: thick crimson fog backlit by
    # flickering floodlights". Both strings then go into every single render for
    # the whole session, one as the LEVEL PLATE and one as "Lighting:", and the
    # frame is drawn by whichever the model believes. Worse, "backlit by
    # flickering floodlights" invents a light SOURCE that is nowhere in an
    # outdoor desert at golden hour, and img2img carries it for the rest of the
    # run. The roll is meant to vary the clock and the mood, not overrule the
    # authored look.
    palette = ""
    try:
        if game_identity.setting_authored():
            palette = str(
                (game_identity.authored_setting() or {}).get("palette") or ""
            ).strip()
    except Exception:
        palette = ""
    if palette:
        weather_rule = (
            f"EXACTLY this, copied verbatim, because the level has already "
            f"decided its light: {palette}"
        )
    banned = _forbidden_weather(_world_constraint_text())
    if banned:
        weather_rule += (
            f". This world rules the following out — never name or imply any of "
            f"them, in the weather OR the mood: {', '.join(sorted(banned))}"
        )
    prompt = f"""Generate a starting time/weather/mood for a horror game set in {place}

Use EXACTLY this format: "TIME | weather: DESCRIPTION | mood: DESCRIPTION"

Example: "{INITIAL_TIME_OF_DAY}"

Requirements:
- TIME: Evening hours only (6:00pm - 8:00pm range, use exact time like 6:45pm or 7:22pm)
- WEATHER: {weather_rule}
- MOOD: Horror/suspense mood (2-3 words describing emotional tone)

Generate ONE random variation. Return ONLY the formatted string, no explanation."""

    # Two attempts, then the seed line. Telling the model the ban is not enough
    # on its own at temp 1.2 — the whole string is checked, mood clause included,
    # because all of it is injected as the render's lighting instruction.
    for attempt in (1, 2):
        try:
            result = _ask(prompt, model="gemini", temp=1.2, tokens=40, use_lore=False).strip()
        except Exception as e:
            print(f"[INIT] Error generating time: {e}, using default")
            return INITIAL_TIME_OF_DAY
        if not ('|' in result and 'pm' in result.lower()
                and 'weather:' in result and 'mood:' in result):
            print(f"[INIT] LLM returned invalid format (attempt {attempt})")
            continue
        violations = _named_terms(result, banned)
        if violations:
            print(f"[INIT] Rolled weather this world rules out "
                  f"({', '.join(violations)}) on attempt {attempt}")
            continue
        # Asking was not enough. At temp 1.2 this returned "thick crimson fog
        # backlit by flickering floodlights" and then "thick rolling coastal
        # fog" on a level whose plate reads "golden hour, rust, red dust" — the
        # second one on the very next run after the instruction was added, and
        # coastal fog in the Four Corners desert at that. So when the level has
        # authored its light, the weather clause is not the model's to choose:
        # take its time and its mood, which are what the roll is FOR, and seat
        # the authored palette in the middle. Nothing downstream can catch this
        # later — the string goes into every render of the session as
        # "Lighting:", directly against the LEVEL PLATE's own palette line.
        if palette:
            result = _reseat_palette(result, palette)
        print(f"[INIT] Generated starting time: {result}")
        return result
    print("[INIT] Falling back to default starting time")
    return INITIAL_TIME_OF_DAY


def _reseat_palette(rolled: str, palette: str) -> str:
    """Put the level's authored light back in a rolled time/weather/mood line.

    Keeps the rolled TIME and MOOD (the variety the roll exists to provide) and
    replaces the weather clause with the palette. Returns ``rolled`` untouched
    if it cannot be parsed, since a mangled lighting string is worse than a
    contradictory one.
    """
    parts = [p.strip() for p in str(rolled or "").split("|")]
    if len(parts) < 3:
        return rolled
    time_part, mood_part = parts[0], parts[-1]
    if not time_part or not mood_part.lower().startswith("mood:"):
        return rolled
    was = next((p for p in parts if p.lower().startswith("weather:")), "")
    seated = f"{time_part} | weather: {palette} | {mood_part}"
    if was and _permanence_subject(was[len("weather:"):]) != _permanence_subject(palette):
        print(f"[INIT] Reseated the level's own light over a rolled "
              f"'{was[len('weather:'):].strip()}'", flush=True)
    return seated

def extract_scene_elements(*args):
    """Extract key nouns/entities from dispatch, vision, and world state."""
    text = ' '.join([a for a in args if a])
    # Simple noun extraction: words after 'the', 'a', or capitalized words
    words = re.findall(r'\b(?:the|a|an) ([A-Za-z0-9\-]+)|\b([A-Z][a-z0-9\-]+)', text)
    nouns = set()
    for w1, w2 in words:
        if w1: nouns.add(w1.lower())
        if w2: nouns.add(w2.lower())
    # Also add all unique words longer than 3 chars
    for w in re.findall(r'\b\w{4,}\b', text):
        nouns.add(w.lower())
    return nouns

# Safety cap on how long a turn will wait to join its deferred world-evolution
# thread. On the normal path evolve overlaps the ~6s render and is already done,
# so the join is instant; this only bounds a genuinely hung evolve (whose own
# HTTP calls time out well inside this) so it can never wedge the turn forever.
EVOLVE_JOIN_TIMEOUT = float(os.getenv("EVOLVE_JOIN_TIMEOUT", "25"))

# Safety cap on how long Phase 2 waits to join its parallel frame-read thread
# before writing the history entry. The read's own HTTP call times out at 30s,
# so this only bounds a genuinely hung request; normally it is already done.
VISION_JOIN_TIMEOUT = float(os.getenv("VISION_JOIN_TIMEOUT", "35"))

# How long the choice slate waits for the frame it is supposed to be looking at
# to exist and be non-empty on disk. Short on purpose: Phase 2 runs after the
# render has been written, so this only covers a file that has not finished
# flushing. It exists because a path that fails to attach did not fail loudly —
# choices.py logged "[CHOICES ERROR] Image file not found" and generated the
# slate from text anyway.
CHOICE_FRAME_WAIT = float(os.getenv("CHOICE_FRAME_WAIT", "5"))

# How long it then waits for the vision READ of that frame before writing the
# slate. This is the one wait a player actually feels — buttons appear after it —
# so it is tighter than VISION_JOIN_TIMEOUT, and expiring is survivable: the
# frame is still attached to the call, the slate just has no scene text.
CHOICE_VISION_WAIT = float(os.getenv("CHOICE_VISION_WAIT", "20"))


def _await_frame_on_disk(image_url: str, budget: float) -> str:
    """Block until the frame the slate will read is readable, or time out.

    Returns the resolved path, or "" if nothing became readable. A file that
    exists but is still being written attaches as a truncated image, which is
    worse than waiting for it, so size has to be non-zero too.
    """
    if not image_url:
        return ""
    deadline = time.time() + max(0.0, budget)
    while True:
        try:
            resolved = _resolve_image_path(str(image_url))
            if resolved and os.path.isfile(resolved) and os.path.getsize(resolved) > 0:
                return str(resolved)
        except OSError:
            pass
        if time.time() >= deadline:
            return ""
        time.sleep(0.1)


# RENAMED from advance_turn
def _latest_history_image_path(session_id: str = "default") -> str:
    """Filesystem path of the newest history still, if it still exists."""
    try:
        hist = _load_history(session_id) or []
    except Exception:
        hist = []
    for entry in reversed(hist or []):
        if not isinstance(entry, dict):
            continue
        for key in ("image", "image_url"):
            p = entry.get(key)
            if not p:
                continue
            s = str(p)
            if s.startswith("/images/"):
                continue
            if Path(s).exists():
                return s
    return ""


def _process_turn_background(choice: str, initial_player_action_item_id: int, signal_file_path: Optional[str] = None, source: Optional[str] = None, session_id: str = 'default', subject: Optional[str] = None, skip_image: bool = False, pacing: bool = True):
    """Standalone feed turn — a thin adapter over the canonical two-phase
    session pipeline.

    This runs in the background thread spawned by api_choose, scoped to
    whichever session issued the choice (see the `session_id` argument —
    api_choose passes the requester's session so multiple users' turns never
    cross-write each other's saves). It delegates the actual turn work to
    advance_turn_image_fast + advance_turn_choices_deferred (the same
    pipeline the Discord/session path uses), then translates their return
    dicts into the feed items the standalone UI polls for. It replaces the
    previous ~600-line duplicate orchestration so there is now ONE turn
    implementation.

    Design decisions (previously divergent between the two paths):
      • Death: honor the consequence LLM's player_alive verdict (Phase 1),
        not a second check_player_death call.
      • Image + flipbook: produced inside _gen_image (Phase 1); no separate
        standalone flipbook copy.
      • Risk: every turn now drives the story-escalation backend (threat_level →
        phase → fate roll) via advance_story_dynamics, so the web/SCAN path stops
        running flat at NORMAL. `source` marks how the action was issued; SCAN
        object interactions ("scan_interact"/"scan_move") push risk harder so
        poking the world moves the story forward and raises the stakes.

    NOTE ON CONCURRENCY: this function reads/writes a LOCAL `turn_state` dict
    (always reloaded via _load_state(SID)) rather than the ambient module-
    global `state`, specifically so that a DIFFERENT session's concurrent
    background thread swapping the global mirror can't corrupt this turn's
    own in-flight computation. `_sync_ambient_state` only mirrors our result
    into the global when this session is still the active one (see its
    docstring) — the on-disk save is always the source of truth regardless.
    """
    if signal_file_path:
        try:
            Path(signal_file_path).write_text("THREAD SPAWNED AND WROTE TO FILE")
        except Exception:
            pass

    if pacing:
        # Brief pacing delay so the client paints the action line before the
        # turn's work lands. 0.25s is enough for that repaint; the old 0.75s
        # was pure dead time on the critical path.
        time.sleep(0.25)

    SID = session_id
    # Serialize this session's ENTIRE turn pipeline (world update, scene
    # image, choice generation) against every OTHER session's turn/reset.
    # The slate is derived from the new frame, so the render stays on this
    # path instead of racing ahead of the choices.
    with TURN_LOCK:
        # Handle to this turn's deferred world-evolution thread. Joined before
        # Phase 2 (so the choice phase reads the EVOLVED world_prompt /
        # seen_elements, never the pre-turn values) and again in `finally` so
        # evolution never outlives the turn that spawned it.
        evolve_thread = None
        # Per-stage wall-clock (ms) for the turn-timing play_log event. usage.db
        # never records latency for operation=ask, so this is the only measured
        # split of consequence / image / evolve / vision / choices per turn.
        _turn_t0 = time.time()
        _turn_timings: dict = {}
        try:
            # ── STORY ESCALATION + FATE ──
            # Drive the risk backend BEFORE the consequence generates, so the rising
            # phase feeds the prompt (advance_turn_image_fast reads current_phase for
            # its grounding block) and the rolled fate colors THIS turn's outcome.
            # SCAN interactions ("scan_interact"/"scan_move") are deliberate meddling
            # with the world, so they push threat harder and bias fate toward risk —
            # exactly the "interacting moves the story forward + raises stakes" goal.
            is_interaction = source in ("scan_interact", "scan_move", "encounter")
            is_move = source == "scan_move"
            # The client tags a genuinely player-typed action with source="typed"
            # (see submitCustomAction in standalone.js) — that's the ONLY reliable
            # signal, because a tapped choice pill sends no source at all, same as
            # a typed one used to. Downstream code used to guess this from the
            # choice TEXT (does it start with "Approach"/"Examine"/...?), which
            # matched nothing once choices moved to "Enter the..."/"Walk over
            # to..." phrasing — so it fired "FREE WILL" on every curated pick,
            # every turn, injecting a first-person-framed instruction block that
            # fought whatever camera perspective the player had actually chosen.
            is_custom_action = source == "typed"
            # A conversation is a deliberate act on the world too, but it is
            # not meddling: talking to someone should be able to move the
            # story and draw attention without carrying the same threat as
            # prying open a sealed drum. It is deliberately NOT in
            # `is_interaction` — that flag also selects the "handling/entering
            # a specific thing" directive, which is the wrong sentence for a
            # person the player just spoke to (see _conversation_directive,
            # which carries this turn's requirement and its permanence).
            is_talk = source == "talk"
            risk_boost = 2 if is_interaction else (1 if is_talk else 0)
            encounter_released = True
            if source == "encounter":
                try:
                    import encounter as _encounter
                    _enc_st = _load_state(SID) or {}
                    _rec = _enc_st.get("encounter_outcome") if isinstance(
                        _enc_st.get("encounter_outcome"), dict) else {}
                    encounter_released = _encounter.encounter_releases(
                        _rec.get("outcome"), _rec)
                    if encounter_released:
                        _encounter.clear_encounter(SID)
                except Exception:
                    encounter_released = True
            dyn = advance_story_dynamics(session_id=SID, risk_boost=risk_boost)
            turn_fate = dyn.get("fate", "NORMAL")
            print(f"[TURN DYNAMICS] source={source} phase={dyn.get('phase')} "
                  f"threat={dyn.get('threat_level')} fate={turn_fate} escalated={dyn.get('escalated')}", flush=True)
            try:
                import play_log as _play_log
                _play_log.record("turn_start", SID, {
                    "source": source,
                    "choice": str(choice or "")[:220],
                    "phase": dyn.get("phase"),
                    "fate": turn_fate,
                })
            except Exception:
                pass

            # ── PHASE 1: camera beat + NO image, evolution deferred to a thread ──
            # The consequence LLM writes visual_scene; the still is composed from
            # THAT, not from the evolved world document — so world evolution no
            # longer blocks the frame. defer_evolve=True runs it on a thread that
            # OVERLAPS the render below; it is joined before Phase 2 reads
            # world_prompt / seen_elements, so those stay fresh (see the join
            # before advance_turn_choices_deferred). skip_evolve stays False: this
            # is a deferred-but-joined evolve, not a fire-and-forget one.
            _t_conseq = time.time()
            p1 = advance_turn_image_fast(choice, fate=turn_fate, is_timeout_penalty=False, session_id=SID, skip_image=True, skip_evolve=False, interaction=is_interaction, local_only=True, subject=(subject or ""), is_move=is_move, escalated=bool(dyn.get("escalated")), is_custom_action=is_custom_action, defer_evolve=True)
            _turn_timings["consequence_ms"] = int((time.time() - _t_conseq) * 1000)
            # World evolution is now in flight on this thread, running in parallel
            # with the scene render. Joined before the choice phase.
            evolve_thread = p1.get("_evolve_thread")
            turn_state = _load_state(SID)
            _sync_ambient_state(turn_state, SID)

            vision_dispatch_text = (p1.get("vision_dispatch") or "").strip()
            # The feed gets the narrative; only the renderer gets the caption.
            dispatch_text = (
                (p1.get("dispatch") or "").strip()
                or vision_dispatch_text
                or "The situation evolves..."
            )
            consequence_img_url = None  # streamed after the slate
            player_alive = turn_state.get("player_state", {}).get("alive", True)
            # Encounter resolve already decided live/die. The consequence LLM
            # writes that beat; it does not get to flip player_alive.
            if source == "encounter":
                forced = turn_state.get("encounter_outcome")
                if isinstance(forced, dict) and "alive" in forced:
                    player_alive = bool(forced.get("alive"))
                    with WORLD_STATE_LOCK:
                        st_force = _load_state(SID)
                        ps = st_force.setdefault("player_state", {})
                        if not isinstance(ps, dict):
                            ps = {}
                            st_force["player_state"] = ps
                        ps["alive"] = player_alive
                        cond = str(forced.get("condition") or ps.get("condition") or "ok")
                        if cond in ("ok", "wounded"):
                            ps["condition"] = cond
                        _save_state(st_force, SID)
                        turn_state = st_force
                        _sync_ambient_state(st_force, SID)

            turn_items: List[Dict[str, Any]] = [
                create_feed_item(
                    type="narrative_event",
                    content=dispatch_text,
                    metadata={
                        "source": "dispatch",
                        "degraded": bool(p1.get("degraded")),
                        # The visual scene this turn is about to draw. The
                        # consequence bed is armed here, five steps before the
                        # picture, so it cannot use vision's read of the frame
                        # — the frame does not exist yet. This is the same KIND
                        # of text (a description of the shot, no camera or film
                        # language) and it is the only one available this early.
                        "visual": vision_dispatch_text,
                    },
                )
            ]

            # Phase escalation sting: when this turn tipped the story into a higher
            # phase, surface an in-world beat (the client renders `threat_escalation`
            # with its own style + escalation sound) so the player FEELS the stakes
            # climb. Skip on the death turn — the game-over beat carries that weight.
            if player_alive and dyn.get("escalated"):
                beat = _phase_escalation_beat(dyn.get("phase", ""))
                if beat:
                    turn_items.append(create_feed_item(
                        type="threat_escalation", content=beat,
                        metadata={"phase": dyn.get("phase"), "threat_level": dyn.get("threat_level")},
                    ))

            # The run's goal, reached. `objective_done` is the type the client
            # already styles as COMPLETE for its own case-file beats, so the
            # moment the world says "you are there" reads like the rest of the
            # objectives without a client change.
            if player_alive and p1.get("goal_reached"):
                goal_text = run_goal(turn_state)
                if goal_text:
                    turn_items.append(create_feed_item(
                        type="objective_done",
                        content=f"What you came here for: {goal_text}",
                        metadata={"goal": goal_text,
                                  "turn": turn_state.get("goal_reached_turn")},
                    ))

            # Item pickup detection (feed notification; inventory itself is in state).
            _inventory_update = None
            try:
                from items import detect_item_pickups, add_items_to_inventory, ITEMS
                current_inventory = turn_state.get("inventory", [])
                picked_up = detect_item_pickups(vision_dispatch_text or dispatch_text, current_inventory)
                if picked_up:
                    updated_inventory, didnt_fit = add_items_to_inventory(current_inventory, picked_up)
                    _inventory_update = updated_inventory
                    names = [ITEMS[i]["display"] for i in picked_up if i in ITEMS]
                    if names:
                        turn_items.append(create_feed_item(type="inventory_pickup", content=f"\U0001F392 **Picked up:** {', '.join(names)}"))
                    overflow = [ITEMS[i]["display"] for i in (didnt_fit or []) if i in ITEMS]
                    if overflow:
                        turn_items.append(create_feed_item(type="inventory_full", content=f"\u26A0\uFE0F Inventory full! Couldn't pick up: {', '.join(overflow)}"))
            except Exception as e_pick:
                log_error(f"Error detecting item pickups: {e_pick}")

            # Atomic append (reload inside the lock) so concurrent realtime writers
            # (/api/observe, scene-image, reground) can't clobber these feed items —
            # the bug that made SCAN/realtime turns "freeze" (narrative + choices
            # vanished from feed_log and the client polled an empty feed forever).
            with WORLD_STATE_LOCK:
                st = _load_state(SID)
                if _inventory_update is not None:
                    st["inventory"] = _inventory_update
                # Written on EVERY turn, not only the ones that tapped something:
                # a turn with no subject must clear any prior claim, or a
                # permanence check whose reground never ran would be settled
                # later against a frame nobody ever asked it about.
                st["permanence"] = _permanence_record(
                    subject or "", is_move, vision_dispatch_text
                )
                _feed_extend(st, turn_items)
                _save_state(st, SID)
                turn_state = st
                _sync_ambient_state(st, SID)

            # ── DEATH: single mechanism — the Phase 1 player_alive verdict ──
            if not player_alive:
                # Encounter resolve already pinned the death still. A normal
                # death turn still renders a scene image behind YOU DIED.
                if not skip_image:
                    _spawn_scene_image_async(
                        caption=vision_dispatch_text or dispatch_text,
                        dispatch=dispatch_text,
                        choice=choice,
                        frame_idx=int(p1.get("frame_idx", 1)),
                        world_prompt=turn_state.get("world_prompt", ""),
                        hard_transition=bool(p1.get("hard_transition", False)),
                        session_id=SID,
                        softened_move=bool(p1.get("softened_move", False)),
                    )
                game_over_item = create_feed_item(type="game_over", content="You have succumbed to the horrors. The transmission ends.")
                game_over_choices = _structure_choices_for_feed(
                    ["Restart Simulation"], "GAME OVER",
                    image_url=turn_state.get("current_image_url"),
                )
                with WORLD_STATE_LOCK:
                    st = _load_state(SID)
                    st["turn_count"] = int(st.get("turn_count", 0)) + 1
                    switched = _tick_world_and_maybe_transition(
                        st, SID, player_alive=False)
                    if switched:
                        st.setdefault("player_state", {})["alive"] = True
                        if switched.get("kind") == "cutscene":
                            _feed_append(st, _cutscene_feed_item(switched))
                        else:
                            _feed_append(st, _world_transition_feed_item(switched))
                            dest_name = (switched.get("to") or {}).get("name") or "a new world"
                            _feed_append(st, _structure_choices_for_feed(
                                ["Look around"], dest_name,
                                image_url=st.get("current_image_url"),
                            ))
                    else:
                        _feed_append(st, game_over_item)
                        _feed_append(st, game_over_choices)
                        try:
                            import run_tape
                            run_tape.end(SID, "died", cause=_tape_death_cause(st))
                        except Exception as _tape_err:
                            log_error(f"[TAPE] death not marked: {_tape_err}")
                    _save_state(st, SID)
                    turn_state = st
                    _sync_ambient_state(st, SID)
                try:
                    import play_log as _play_log
                    _play_log.record("turn", SID, {
                        "source": source,
                        "choice": str(choice or "")[:220],
                        "dispatch": str(dispatch_text or "")[:280],
                        "alive": False,
                    })
                except Exception:
                    pass
                return

            # Loop: world already updated. Render the new frame, then derive
            # the slate from that frame — only act on what is actually in it.
            # Encounter resolve already pinned the play-out still for
            # survive / wounded / die. Escape generates a new world frame
            # so the punch does not become the walkable yard.
            hard_cut = bool(p1.get("hard_transition", False))
            if source == "encounter" and encounter_released:
                hard_cut = True
            # The render is where world evolution overlaps: evolve_thread is in
            # flight while this ~6s call runs, so joining it afterward is ~free.
            _t_img = time.time()
            if skip_image:
                scene = None
                img_path = _latest_history_image_path(SID)
                img_prompt = ""
                turn_state = _load_state(SID)
                _sync_ambient_state(turn_state, SID)
            else:
                # INTERACT: hold here until the dive's close-up exists, then
                # carry it into the scene so the thing the player just looked
                # at closely is the same thing when the world comes back. Every
                # other turn gets an empty list without waiting.
                cast_plates = _await_interact_plate(SID, source, subject)
                # `caption` is the camera line, `dispatch` is the prose. Passing
                # the caption to BOTH made them equal, and build_image_prompt
                # decides whether to send the scene at all by comparing them:
                # has_visual_scene is `narrative != caption`, so it was False on
                # every turn of the only path the game plays on, and the
                # "render exactly this scene" branch was unreachable. Every
                # frame fell back to the scaffold — a paraphrase of the PREVIOUS
                # frame plus "render the result of that action" — with
                # visual_scene generated, logged, and discarded. MOVE TO was
                # where it showed worst: nothing in the payload named the
                # destination, so a click on the mesa rendered as a step forward
                # into an invented shed. Harmless until the two channels were
                # split apart (dispatch used to BE visual_scene, so passing it
                # twice was a no-op); the split never reached this call site.
                scene = _generate_and_append_scene_image(
                    caption=vision_dispatch_text or dispatch_text,
                    dispatch=dispatch_text,
                    choice=choice,
                    frame_idx=int(p1.get("frame_idx", 1)),
                    world_prompt=turn_state.get("world_prompt", ""),
                    hard_transition=hard_cut,
                    session_id=SID,
                    write_history=False,
                    softened_move=bool(p1.get("softened_move", False)),
                    cast_plates=cast_plates,
                )
                turn_state = _load_state(SID)
                _sync_ambient_state(turn_state, SID)
                img_path = (scene or {}).get("img_path") or ""
                img_prompt = (scene or {}).get("image_prompt") or ""
            _turn_timings["image_ms"] = int((time.time() - _t_img) * 1000)

            # Survive / wounded stay locked. The world just evolved through
            # the same pipeline as MOVE TO / a typed action. The Moment
            # owns the next slate — do not generate explore verbs.
            if source == "encounter" and not encounter_released:
                switched = None
                with WORLD_STATE_LOCK:
                    st = _load_state(SID)
                    st["turn_count"] = int(st.get("turn_count", 0)) + 1
                    switched = _tick_world_and_maybe_transition(
                        st, SID, player_alive=True)
                    if switched:
                        try:
                            import encounter as _encounter
                            _encounter.clear_encounter(SID)
                        except Exception:
                            pass
                        if switched.get("kind") == "cutscene":
                            _feed_append(st, _cutscene_feed_item(switched))
                        else:
                            _feed_append(st, _world_transition_feed_item(switched))
                    MAX_FEED_LOG_ITEMS = 100
                    if len(st.get("feed_log", [])) > MAX_FEED_LOG_ITEMS:
                        st["feed_log"] = st["feed_log"][-MAX_FEED_LOG_ITEMS:]
                    _save_state(st, SID)
                    turn_state = st
                    _sync_ambient_state(st, SID)
                if switched:
                    return {
                        "dispatch": dispatch_text,
                        "choices": [],
                        "danger": "",
                        "stakes": "",
                        "released": True,
                        "alive": True,
                    }
                try:
                    import encounter as _encounter
                    held = _encounter.hold_after_engine_turn(SID, dispatch_text)
                except Exception as e_hold:
                    log_error(f"[ENCOUNTER] hold after engine turn failed: {e_hold}")
                    try:
                        import encounter as _encounter
                        _encounter._clear_encounter_resolving(SID)
                    except Exception:
                        pass
                    held = {
                        "dispatch": dispatch_text,
                        "choices": [],
                        "danger": "",
                        "stakes": "",
                        "released": False,
                        "alive": True,
                    }
                return held

            # Join world evolution BEFORE Phase 2 so the choice generator and the
            # history entry it writes both read the evolved world_prompt /
            # seen_elements — not the pre-turn values. It has been overlapping the
            # render, so on the normal path this returns immediately.
            _t_evolve = time.time()
            if evolve_thread is not None:
                try:
                    evolve_thread.join(timeout=EVOLVE_JOIN_TIMEOUT)
                except Exception:
                    pass
                evolve_thread = None
            _turn_timings["evolve_join_ms"] = int((time.time() - _t_evolve) * 1000)

            _t_p2 = time.time()
            # `dispatch` is the beat the player read; `vision_dispatch` is the
            # camera line the renderer was given. This call passed the camera
            # line as BOTH, so everything downstream that reads the turn's
            # dispatch — the history entry, the narrator's "recent beats", the
            # encounter brief, and the choice generator's "what just
            # happened" — was handed "Isaac Clarke is hunched in the center
            # of a pitch-black chamber" instead of "You lunge through the
            # dark threshold, but your foot catches...". Same fault as the
            # render call above (dispatch used to BE visual_scene, so passing
            # it twice was a no-op until the two were split); this was the
            # other call site the split never reached. Seen in a live run's
            # history.json: dispatch == vision_dispatch on every pill turn.
            p2 = advance_turn_choices_deferred(
                img_path, dispatch_text, vision_dispatch_text, choice,
                img_prompt, p1.get("hard_transition", False), SID, local_only=True,
                pregenerated_choices=[],
            )
            _turn_timings["phase2_ms"] = int((time.time() - _t_p2) * 1000)
            # Fold in the finer Phase-2 split (vision / choices / critic) so the
            # timing event has every stage, not just the phase2 total.
            try:
                _p2_timing = p2.get("_timing") if isinstance(p2, dict) else None
                if isinstance(_p2_timing, dict):
                    _turn_timings.update(_p2_timing)
            except Exception:
                pass
            _turn_timings["turn_total_ms"] = int((time.time() - _turn_t0) * 1000)
            try:
                import play_log as _play_log
                _play_log.record("turn_timing", SID, {"source": source, **_turn_timings})
            except Exception:
                pass
            turn_state = _load_state(SID)
            _sync_ambient_state(turn_state, SID)

            next_choices = [c for c in (p2.get("choices") or []) if c and c.strip() and c.strip() != "\u2014"]
            prompt_item = _structure_choices_for_feed(
                next_choices, "What do you do next?",
                turn_state.get("current_image_url"),
            )

            with WORLD_STATE_LOCK:
                st = _load_state(SID)
                st["turn_count"] = int(st.get("turn_count", 0)) + 1
                switched = _tick_world_and_maybe_transition(
                    st, SID, player_alive=True)
                if switched and switched.get("kind") == "cutscene":
                    # The montage owns this beat — do not leave the source
                    # World's verbs live under the overlay (they would start
                    # another turn while the run is parked on the Cutscene).
                    _feed_append(st, _cutscene_feed_item(switched))
                elif switched:
                    # A direct edge into another World. The slate just written
                    # was derived from the frame of the World being left, so
                    # offering it under the new place's picture is the old
                    # place leaking through ("Heave open the truck door" in a
                    # facility with no truck). The new place gets the same
                    # first move a cutscene arrival gets.
                    _feed_append(st, _world_transition_feed_item(switched))
                    dest_name = (switched.get("to") or {}).get("name") or "a new world"
                    prompt_item = _structure_choices_for_feed(
                        ["Look around"], dest_name,
                        image_url=st.get("current_image_url"),
                    )
                    next_choices = ["Look around"]
                    _feed_append(st, prompt_item)
                else:
                    _feed_append(st, prompt_item)
                MAX_FEED_LOG_ITEMS = 100  # keep feed_log manageable
                if len(st.get("feed_log", [])) > MAX_FEED_LOG_ITEMS:
                    st["feed_log"] = st["feed_log"][-MAX_FEED_LOG_ITEMS:]
                _save_state(st, SID)
                turn_state = st
                _sync_ambient_state(st, SID)
            try:
                import play_log as _play_log
                _play_log.record("turn", SID, {
                    "source": source,
                    "choice": str(choice or "")[:220],
                    "dispatch": str(dispatch_text or "")[:280],
                    "alive": True,
                    "choices": [c[:80] for c in (next_choices or [])[:3]],
                })
            except Exception:
                pass
            return {
                "dispatch": dispatch_text,
                "choices": next_choices,
                "released": True,
                "alive": True,
            }

        except Exception as e_critical:
            log_error(f"Critical unhandled error in _process_turn_background thread: {e_critical}")
            logging.exception("CRITICAL EXCEPTION in _process_turn_background thread top level:")
            try:
                critical_error_item = create_feed_item(type="error_event", content=f"System critical error during turn processing: {e_critical}")
                with WORLD_STATE_LOCK:
                    current_state_for_err = _load_state(SID)
                    _feed_append(current_state_for_err, critical_error_item)
                    _save_state(current_state_for_err, SID)
                    _sync_ambient_state(current_state_for_err, SID)
            except Exception as e_final_log:
                log_error(f"Could not even log critical error to feed_log: {e_final_log}")
        finally:
            # Never let a deferred world-evolution thread outlive the turn that
            # spawned it (early returns on the death / encounter-held paths reach
            # here too). On the normal path it was already joined before Phase 2,
            # so this is a no-op there.
            if evolve_thread is not None:
                try:
                    evolve_thread.join(timeout=EVOLVE_JOIN_TIMEOUT)
                except Exception:
                    pass
    # Thread callers ignore the return. Sync encounter-hold reads it for the
    # next Moment slate. State is always persisted to disk regardless.


# How long after a turn starts a second /api/choose is treated as an accidental
# duplicate rather than the player's next move. A double-click or a client retry
# lands in milliseconds; a real next action requires reading the new prose and
# deciding, and the client will not even offer it until the choices are live.
DOUBLE_SUBMIT_WINDOW_S = 4.0


def _clear_turn_processing(session_id: str) -> None:
    """Release the api_choose re-entrancy guard (see its `turn_processing`
    check). Best-effort — a failure here should never crash the background
    thread it's cleaning up after."""
    try:
        with WORLD_STATE_LOCK:
            st = _load_state(session_id) or {}
            if st.get("turn_processing"):
                st["turn_processing"] = False
                _save_state(st, session_id)
                _sync_ambient_state(st, session_id)
    except Exception:
        pass


def _process_turn_background_guarded(*args, **kwargs):
    """Thread target wrapper for _process_turn_background.

    Found by playtest.py's double-submit race probe (see
    docs/plans/PLAYTEST_CONSOLIDATION_PLAN.md): api_choose had NO
    re-entrancy guard at all, unlike encounter.api_resolve's
    encounter_resolving flag. Two concurrent /api/choose calls for the same
    session — a double-click, a client-side retry — both got HTTP 200 and
    both ran a full turn: doubled narrative_event, doubled
    player_choice_prompt, doubled LLM/image spend, for one player click.

    api_choose sets `turn_processing=True` (atomically, under
    WORLD_STATE_LOCK, right next to the existing cutscene_playing check) and
    refuses a second /api/choose with 409 while it's set. The turn itself
    runs on a daemon thread that api_choose doesn't wait on, so the flag has
    to be cleared from the far end of that thread, not from api_choose's own
    return — hence this wrapper, kept OUTSIDE _process_turn_background's own
    (large, many-return-path) body so the guard's lifecycle doesn't have to
    be threaded through every existing exit point by hand.
    """
    session_id = kwargs.get("session_id", "default")
    try:
        _process_turn_background(*args, **kwargs)
    finally:
        _clear_turn_processing(session_id)


def _structure_choices_for_feed(choice_texts: List[str], prompt_text: str = "What do you do next?", image_url: Optional[str] = None) -> Dict[str, Any]:
    global state 
    structured_choices_list = []
    if not choice_texts: 
        choice_texts = ["Observe your surroundings.", "Think about your next move.", "Stay alert."]
        prompt_text = "The path ahead is unclear. Consider your options carefully."

    for i, text in enumerate(choice_texts):
        if text and text.strip() and text.strip() != "—":
            action_id = _slug(text) if _slug(text) else f"auto_choice_{get_next_feed_item_id()}_{i}"
            structured_choices_list.append({"text": text, "action_id": action_id})
    
    if not structured_choices_list: 
        structured_choices_list = [
            {"text": "Look around.", "action_id": "fallback_look_around"},
            {"text": "Wait and see.", "action_id": "fallback_wait_see"}
        ]
    
    return create_feed_item(
        type="player_choice_prompt",
        content=prompt_text,
        choices=structured_choices_list,
        image_url=image_url
    )

def _generate_and_append_scene_image(caption: str, dispatch: str, choice: str, frame_idx: int,
                                     world_prompt: str, hard_transition: bool = False,
                                     session_id: str = 'default', write_history: bool = True,
                                     softened_move: bool = False,
                                     cast_plates: Optional[List[str]] = None):
    """Generate the scene image, append the scene_image feed item, and update
    session state. Returns {'img_path','web_url','image_prompt','render_prompt'}
    or None on failure / when image generation is disabled.

    cast_plates — close-ups of characters/objects the player has just been shown
    at length, carried in as extra labeled references so they come back as the
    same face. Today that is the INTERACT dive's plate (see
    _await_interact_plate); anything that puts a generated subject on screen and
    then hands the scene back has the same problem and the same answer.

    write_history controls the history img2img-continuity write:
      • True  — write the image into THIS turn's history entry ourselves. Used by
                the async/death/intro paths, where choices were produced in
                PARALLEL, so we must wait for their entry to land and target it.
      • False — the caller sequences the choice phase AFTER us and hands our
                img_path to advance_turn_choices_deferred, which writes the image
                into the entry it appends — so there's no race and nothing to do.
    """
    global state, history
    if not WORLD_IMAGE_ENABLED:
        return None
    # Serialize scene-image generation PER SESSION, not globally.
    #
    # This used to take the global TURN_LOCK for the entire 10-30s render, and
    # TURN_LOCK is also what /api/reset and /api/choose hold. So one player's
    # intro still blocked every OTHER player's reset and turns: their HTTP
    # request sat waiting on a lock held by a stranger's render. The client
    # awaits /api/reset before it can render anything, so a second player
    # opening the game watched the loader sit on its first step over a black
    # screen until someone else's image finished — and with only a handful of
    # gunicorn threads, a few concurrent opens wedged the whole service.
    #
    # A render only ever needed to exclude another render of the SAME session
    # (they both write that session's history entry). Cross-session safety is
    # already handled explicitly: we read this session's history from disk into
    # a LOCAL and hand it to _gen_image via history_ref, so a concurrent
    # different-session request swapping the module-global `history` can't feed
    # the wrong session's frames into this render.
    with _session_image_lock(session_id), _IMAGE_SLOTS:
        try:
            # Before the (large) still write, make sure the persistent disk has
            # room. If it's low, this sweeps stale/regenerable data across all
            # sessions so the render — and the state save that follows — don't
            # fail on a full disk. No-op when there's healthy headroom.
            _ensure_disk_headroom()
            local_history = _load_history(session_id)
            result = _gen_image(
                caption=caption or dispatch,
                mode="normal",
                choice=choice,
                dispatch=dispatch,
                world_prompt=world_prompt,
                hard_transition=hard_transition,
                frame_idx=frame_idx,
                session_id=session_id,
                history_ref=local_history,
                softened_move=softened_move,
                cast_plates=cast_plates,
            )
            img_path = result[0] if result else None
            # Two different prompts for two different renderers:
            #   • image_prompt (result[1]) — the diffusion prompt used for the
            #     Gemini still. Also sent as metadata.image_prompt so enabling
            #     Reactor / LingBot / Oyster can animate from the same text.
            #   • render_prompt — a clean, video-model-appropriate scene bible
            #     used to STEER Reactor/Helios (see build_realtime_prompt). This
            #     is what we hand the standalone client via metadata.prompt.
            # Built up front (independent of the still) so realtime can keep
            # steering the world off the prompt even when the still was blocked.
            image_prompt = result[1] if (result and len(result) > 1) else ""
            render_base = build_realtime_base(visual_scene=caption, narrative=dispatch)
            render_prompt = build_realtime_prompt(
                visual_scene=caption, narrative=dispatch, choice=choice
            )

            if not img_path:
                # Image was blocked (content filter) or generation failed. Do NOT go
                # silent: emitting nothing leaves the turn's ceremony parked on the
                # guide-image step (a spinner that never resolves) and the scene
                # visually frozen — which reads as "the game broke" (exactly the
                # report: switching back to stills, "selecting an action didn't
                # change scenes"). Emit a scene beat WITHOUT an image so the client
                # still resolves the turn, realtime keeps steering off the prompt,
                # and stills mode can surface a "signal lost" glitch instead of a
                # dead UI. We deliberately keep the LAST good still as
                # current_image_url so a fallback to stills still shows a real frame.
                blocked_item = create_feed_item(
                    type="scene_image",
                    content="",
                    image_url=None,
                    metadata={
                        "prompt": render_prompt,
                        "base": render_base,
                        "image_prompt": image_prompt or caption or "",
                        "hard_transition": bool(hard_transition),
                        "blocked": True,
                    },
                )
                with WORLD_STATE_LOCK:
                    st = _load_state(session_id)
                    st['current_render_prompt'] = render_prompt
                    st['current_render_base'] = render_base
                    # The last good still is deliberately kept (see above), but
                    # its motion is not: replaying the previous turn's frames
                    # under a new dispatch would animate the wrong action.
                    st['current_sequence'] = None
                    take_flipbook_sequence(session_id)
                    _feed_append(st, blocked_item)
                    _save_state(st, session_id)
                    _sync_ambient_state(st, session_id)
                print(f"[SCENE IMG] image blocked/failed for {session_id}; emitted signal-lost beat "
                      f"(turn resolves, realtime keeps steering)", flush=True)
                return None

            web = _to_web_image_url(img_path, session_id)
            # In flipbook mode this turn produced a sequence, and `img_path` is
            # its LAST panel. The still stays the contract for everything that
            # only understands one image; the frames travel on the beat so the
            # client can play the motion and land on that same still.
            sequence = flipbook_web_payload(take_flipbook_sequence(session_id),
                                            session_id)
            item = create_feed_item(
                type="scene_image",
                content="",
                image_url=web,
                metadata={
                    "sequence": sequence,
                    "prompt": render_prompt,
                    # 'base' (style + scene, no action) lets the client re-steer
                    # instantly with the next action before the turn resolves.
                    "base": render_base,
                    # The text that generated the still — injected when a world
                    # model (Reactor / LingBot / Oyster) is enabled so it has
                    # something to animate besides the seed image.
                    "image_prompt": image_prompt or caption or "",
                    "hard_transition": bool(hard_transition),
                },
            )
            with WORLD_STATE_LOCK:
                st = _load_state(session_id)
                st['current_image_url'] = web
                # Cleared, not left behind: a client that reconnects after a
                # still-only turn must not be handed the previous turn's frames.
                st['current_sequence'] = sequence
                if not sequence:
                    # A STILL turn has to OWN the flipbook anchors, not inherit
                    # them. `_flipbook_generate` writes these on success and
                    # leaves them untouched when the grid is refused — so after
                    # a blocked flipbook they still pointed at the PREVIOUS
                    # turn's last panel, and everything that reads them
                    # quietly rewound a turn.
                    #
                    # Reported as: type a custom action, get a still, and the
                    # next ordinary choice carries on from the frame BEFORE the
                    # custom action, as if it never happened. Two readers were
                    # doing it — the vision pass that sets the next turn's
                    # spatial anchor, and `_flipbook_generate` itself, which
                    # takes `flipbook_last_frame` as "where the camera IS" for
                    # its first reference.
                    #
                    # `img_path` is the frame this turn actually rendered, so it
                    # is where the camera is now. The other two describe motion
                    # that did not happen this turn and would be time travel:
                    # `flipbook_first_frame` is the wider scene at the START of
                    # a sequence, and re-using an old one is the same bug the
                    # anchored-caller guard upstream exists to prevent.
                    st['flipbook_last_frame'] = img_path
                    st['flipbook_first_frame'] = None
                    st['flipbook_last_grid'] = None
                st['current_image_prompt'] = image_prompt
                st['current_render_prompt'] = render_prompt
                st['current_render_base'] = render_base
                # Record the frame on THIS run's tape. /api/tape used to rebuild
                # the reel by globbing the image directory by mtime, which meant
                # a session that had been played before showed a tape splicing
                # every run together in timestamp order. An explicit per-run list
                # is the only thing that knows where one playthrough ends.
                tape = [f for f in (st.get('tape_frames') or []) if isinstance(f, str)]
                if not tape or tape[-1] != web:
                    tape.append(web)
                st['tape_frames'] = tape[-400:]
                _feed_append(st, item)
                _save_state(st, session_id)
                _sync_ambient_state(st, session_id)
                _tape_turn = st.get('turn_count')
                _tape_state = dict(st)
            # ...and the whole beat on THE TAPE (run_tape.py): every panel,
            # what the player did, the narration, and the prompt it came from
            # — outside the state lock, it writes its own files.
            try:
                import run_tape
                run_tape.record(
                    session_id, "turn" if _tape_turn else "opening",
                    (sequence or {}).get("frames") or [img_path],
                    frame_ms=(sequence or {}).get("frame_ms"),
                    action=_tape_action(choice), prose=dispatch or "",
                    prompt=image_prompt or caption or "",
                    turn=_tape_turn, state=_tape_state)
            except Exception as _tape_err:
                log_error(f"[TAPE] turn not recorded: {_tape_err}")

            if write_history:
                # Write the absolute image path back into history so the NEXT turn's
                # img2img can use this frame for continuity.
                if int(frame_idx) == 0:
                    # INTRO (frame 0): the opening image never goes through
                    # advance_turn_choices_deferred, so no history entry exists for it
                    # yet. Seed history[0] ourselves — otherwise the FIRST player turn
                    # finds no reference frame and falls back to text-to-image, so the
                    # very first image never passes itself to the second via img2img
                    # (breaking visual continuity right at the start of the game).
                    hist = _load_history(session_id)
                    if not hist:
                        intro_entry = {
                            "choice":            choice,
                            "dispatch":          dispatch,
                            # vision_dispatch is REQUIRED by the img2img reference gate
                            # in _gen_image (it skips entries missing it).
                            "vision_dispatch":   caption or dispatch,
                            "world_prompt":      world_prompt,
                            "image":             img_path,
                            "image_url":         img_path,
                            "analysis_image":    img_path,
                            # Original hi-fi guide still, preserved so a later realtime
                            # frame overwriting 'image' still leaves it as a secondary
                            # img2img quality reference (see _ingest_realtime_frame).
                            "guide_image":       img_path,
                            "image_prompt":      image_prompt,
                            "hard_transition":   bool(hard_transition),
                        }
                        hist.append(intro_entry)
                        _save_history(hist, session_id)
                        _sync_ambient_history(hist, session_id)
                        print(f"[SCENE IMG] intro frame seeded into history[0] for img2img continuity: {img_path}")
                    else:
                        # A player turn already appended before the (async) intro image
                        # landed. Seeding now would reorder history, so skip — the intro
                        # still shows in the feed, we just don't chain off it this game.
                        print(f"[SCENE IMG] intro image arrived after a turn was appended (len={len(hist)}); skipping history seed to avoid reordering")
                else:
                    # Regular turn: frame_idx == len(history)+1 at turn start, so after
                    # the parallel choice append this turn's entry is at index
                    # frame_idx-1; wait briefly for it.
                    hist = _load_history(session_id)
                    target_idx = int(frame_idx) - 1
                    for _ in range(40):  # up to ~10s: append is quick, image is slow
                        if 0 <= target_idx < len(hist):
                            break
                        time.sleep(0.25)
                        hist = _load_history(session_id)
                    if 0 <= target_idx < len(hist):
                        hist[target_idx]["image"] = img_path
                        hist[target_idx]["image_url"] = img_path
                        # Record the original high-fidelity guide still separately so it
                        # survives even after a realtime frame later overwrites 'image'
                        # (see _ingest_realtime_frame) — it stays available as a
                        # secondary img2img quality reference.
                        hist[target_idx]["guide_image"] = img_path
                        _save_history(hist, session_id)
                        _sync_ambient_history(hist, session_id)
                    elif hist:
                        print(f"[SCENE IMG] WARN: turn entry idx {target_idx} absent (len={len(hist)}); writing hist[-1]")
                        hist[-1]["image"] = img_path
                        hist[-1]["image_url"] = img_path
                        hist[-1]["guide_image"] = img_path
                        _save_history(hist, session_id)
                        _sync_ambient_history(hist, session_id)
            print(f"[SCENE IMG] scene appended for {session_id}: {web}", flush=True)
            if int(frame_idx) == 0 and img_path:
                try:
                    import world_frames
                    world_frames.remember_from_play(img_path, session_id=session_id)
                except Exception as e_wf:
                    logging.warning(f"[WORLD FRAMES] remember skipped: {e_wf}")
            return {"img_path": img_path, "web_url": web,
                    "image_prompt": image_prompt, "render_prompt": render_prompt}
        except Exception as e:
            log_error(f"[SCENE IMG] failed: {e}")
            # Do NOT swallow the turn's scene entirely. On the realtime (reactor)
            # path the client only re-steers the live world when a scene_image
            # feed item arrives with metadata.prompt; if an exception here emits
            # nothing, the video never receives the new scene and appears to
            # "just stop" (exactly the report: entered the dark hatch and the
            # video never started). Emit a best-effort blocked beat so realtime
            # keeps steering off the prompt and the turn's ceremony still
            # resolves. Built from the always-available turn inputs since
            # render_prompt/render_base may not have been reached before the
            # throw. Guarded so a secondary failure can't mask the original.
            try:
                fb_base = build_realtime_base(visual_scene=caption, narrative=dispatch)
                fb_prompt = build_realtime_prompt(
                    visual_scene=caption, narrative=dispatch, choice=choice
                )
                fallback_item = create_feed_item(
                    type="scene_image",
                    content="",
                    image_url=None,
                    metadata={
                        "prompt": fb_prompt,
                        "base": fb_base,
                        "image_prompt": caption or "",
                        "hard_transition": bool(hard_transition),
                        "blocked": True,
                    },
                )
                with WORLD_STATE_LOCK:
                    st = _load_state(session_id)
                    st['current_render_prompt'] = fb_prompt
                    st['current_render_base'] = fb_base
                    _feed_append(st, fallback_item)
                    _save_state(st, session_id)
                    _sync_ambient_state(st, session_id)
                print(f"[SCENE IMG] exception recovery for {session_id}: emitted signal-lost beat "
                      f"so realtime keeps steering", flush=True)
            except Exception as e2:
                log_error(f"[SCENE IMG] failed to emit recovery beat: {e2}")
            return None


def _spawn_scene_image_async(caption: str, dispatch: str, choice: str, frame_idx: int,
                             world_prompt: str, hard_transition: bool = False,
                             session_id: str = 'default', softened_move: bool = False):
    """Generate a scene image OFF the turn's critical path (death + intro paths,
    where choices are produced in parallel). The browser polls /api/feed and
    streams the scene in. For the main turn loop we instead generate the image
    synchronously and derive the choices from it — see _process_turn_background.
    """
    if not WORLD_IMAGE_ENABLED:
        return
    threading.Thread(
        target=_generate_and_append_scene_image,
        kwargs=dict(caption=caption, dispatch=dispatch, choice=choice, frame_idx=frame_idx,
                    world_prompt=world_prompt, hard_transition=hard_transition,
                    session_id=session_id, write_history=True,
                    softened_move=softened_move),
        daemon=True,
    ).start()


def _spawn_evolve_thread(session_id: str, consequence_summary: str,
                         vision_dispatch: str, player_action: str = "") -> "threading.Thread":
    """Run world evolution on a daemon thread and RETURN the thread handle.

    evolve_world_state is read-only against live state; the worker merges only
    the world fields under WORLD_STATE_LOCK with a fresh reload-inside-lock, so
    a concurrent scene-image write (which touches disjoint keys the same way)
    is never clobbered. Affects only the NEXT turn's world_prompt / seen_elements,
    so the caller can let it OVERLAP the scene render and then join it before the
    choice phase reads those fields — see _process_turn_background.

    player_action is THIS turn's choice, threaded through explicitly because the
    history evolve reads does not yet contain the current turn."""
    def _worker():
        global state
        try:
            from evolve_prompt_file import evolve_world_state
            hist = _load_history(session_id)
            evolution_result = evolve_world_state(
                hist, consequence_summary,
                state_file=str(_get_state_path(session_id)),
                vision_description=vision_dispatch,
                player_action=player_action,
            )
            if not evolution_result:
                return
            with WORLD_STATE_LOCK:
                st = _load_state(session_id)
                # 'ambient_beats' comes back EMPTIED: the evolution just wrote
                # those drifts into the world state, so they're history now and
                # must not be replayed into the next rewrite.
                for k in ("world_prompt", "evolution_summary", "recent_events",
                          "seen_elements", "ambient_beats"):
                    if k in evolution_result:
                        st[k] = evolution_result[k]
                _save_state(st, session_id)
                _sync_ambient_state(st, session_id)
            print(f"[ASYNC EVOLVE] world updated for {session_id}", flush=True)
        except Exception as e:
            log_error(f"[ASYNC EVOLVE] failed: {e}")

    t = threading.Thread(target=_worker, daemon=True)
    t.start()
    return t


def _evolve_world_async(session_id: str, consequence_summary: str, vision_dispatch: str,
                        player_action: str = ""):
    """Fire-and-forget world evolution off the turn's critical path (the bot /
    skip_evolve path, which does not join). Affects the next turn's world_prompt."""
    _spawn_evolve_thread(session_id, consequence_summary, vision_dispatch,
                         player_action=player_action)


# Ensure generate_intro_turn_feed_items is defined AFTER _structure_choices_for_feed
def generate_intro_turn_feed_items(session_id: str = 'default', new_state: Optional[dict] = None,
                                   spawn_image: bool = True, frame_path: Optional[str] = None):
    """Build the intro feed items for a fresh session.

    `frame_path` — the still this run will OPEN on, when we already have one
    (a warm World frame). The opening slate is generated from that picture
    rather than from the shot description, so turn 1 is grounded the same way
    every later turn is.

    `new_state` — the LOCAL (not module-global) fresh-state dict the caller
    just built for `session_id`. Reading/writing it directly (instead of the
    ambient `state` global) matters here because this function makes a slow
    synchronous LLM call (generate_choices); if it touched the ambient
    global, a concurrent request resetting a DIFFERENT session could swap
    that global out from under us mid-call, corrupting either session's
    dict. Falls back to the ambient global only for legacy direct callers
    that don't pass one.
    """
    from choices import generate_choices # Local import
    global state
    if new_state is None:
        new_state = state
    intro_items = [] # This list will be returned
    
    initial_narrative_content = game_identity.opening_narration() or (
        "1993. Golden hour bleeds across the Four Corners desert. You are Jason Fleece, "
        "photojournalist, crouched at the perimeter of Horizon Industries' quarantined "
        "facility \u2014 the last place the missing were ever seen. The camera strap bites into "
        "your neck. Fifty yards off along the fence line, a black-clad patrol sweeps a "
        "flashlight through the dusk, red night-vision goggles catching the last of the "
        "light. Whatever they buried out here, you came to photograph it \u2014 and you are "
        "already not alone."
    )
    narrative_item = create_feed_item(type="narrative_event", content=initial_narrative_content)
    intro_items.append(narrative_item)

    # The opening slate is grounded on a description of the first frame. Those
    # two strings were the shipped Horizon fence line, hardcoded — so the very
    # first thing an authored run asked you to do was vault a fence that isn't
    # in your level. Derive them from the level plate when there is one.
    authored_open = game_identity.opening_shot()
    if authored_open:
        intro_image_description = authored_open["vision"]
        intro_situation = authored_open["prologue"]
        choice_prompt_text = "You've arrived. What's your first move?"
        fallback_choices = ["Move deeper into the space", "Search the nearest structure", "Circle the perimeter on foot"]
    else:
        intro_image_description = "Golden-hour desert at the perimeter fence of the Horizon facility; a black-clad guard patrol sweeps the fence line fifty yards off, red mesas and abandoned vehicles beyond."
        intro_situation = "You are crouched at the fence line of the quarantined Horizon facility as a guard patrol sweeps past, fifty yards off. This is your way in \u2014 if they don't see you first."
        choice_prompt_text = "The patrol hasn't spotted you yet. What's your first move?"
        fallback_choices = ["Duck behind cover from the patrol", "Cut the fence while their backs are turned", "Circle wide around the guard"]

    # Ground the opening slate on the picture the player is about to be looking
    # at, when we have it. intro_image_description is the shot we ASKED for; a
    # slate written from it offers to vault a fence the render may never have
    # drawn. With no cached frame there is nothing to look at yet, so we fall
    # back to the description and reground once the render lands (see
    # _spawn_scene_choices_reground at the reset call site).
    intro_frame_vision = ""
    if frame_path and VISION_ENABLED:
        try:
            _vres = _vision_analyze_all(frame_path)
            if isinstance(_vres, dict):
                intro_frame_vision = (_vres.get("description") or "").strip()
        except Exception as e_vis:
            log_error(f"[INTRO] opening-frame vision failed: {e_vis}")
        print(f"[INTRO] opening frame vision len={len(intro_frame_vision)}", flush=True)

    initial_choice_texts = []
    try:
        initial_choice_texts = generate_choices(
            client=client,
            prompt_tmpl=PROMPTS["player_choice_generation_instructions"],
            last_dispatch=initial_narrative_content,
            world_prompt=new_state.get("world_prompt", "System Online."),
            image_url=frame_path or None,
            image_description=intro_frame_vision or intro_image_description,
            situation_summary=intro_frame_vision or intro_situation,
            n=3,
            beat_nudge=beat_nudge_text(new_state),
        )
    except Exception as e_choices:
        log_error(f"Error generating initial choices: {e_choices}")
        initial_choice_texts = fallback_choices

    choices_item = _structure_choices_for_feed(initial_choice_texts, choice_prompt_text, None)
    intro_items.append(choices_item)
    new_state["choices"] = choices_item['choices']

    # The intro scene image renders in the background and streams into the feed,
    # so reset returns immediately instead of blocking on image generation.
    # An authored opening shot is a description of a FRAME; the narration is
    # prose about a character. Render the frame when we have one.
    intro_image_kwargs = dict(
        caption=initial_narrative_content,
        dispatch=intro_image_description if authored_open else initial_narrative_content,
        choice="Initialize Simulation",
        frame_idx=0,
        world_prompt=new_state.get("world_prompt", "Initialization sequence."),
        session_id=session_id,
    )
    if spawn_image:
        _spawn_scene_image_async(**intro_image_kwargs)
        return intro_items
    # Deferred: the caller spawns it AFTER persisting the new state. The render
    # appends its scene_image by reloading state under the lock, so spawning it
    # before the caller's own _save_state lets that save clobber the appended
    # item — and losing the intro frame is a black screen the run never recovers
    # from. Previously this was masked by the global TURN_LOCK (the render
    # couldn't start until reset released it); now that renders are per-session,
    # the ordering has to be explicit.
    return intro_items, intro_image_kwargs


def _spawn_cached_opening_vision(session_id: str, img_path: str,
                                 slate_id=None) -> None:
    """Look at the frame the run opens on, off the reset's critical path.

    The opening frame is the picture the player starts on, but nothing ever
    read it: the entry went into history with an empty ``vision_analysis``, so
    everything downstream fell through to ``vision_dispatch`` — the intro
    dispatch, which describes the protagonist rather than the scene on screen.
    The first turn was therefore grounded on a picture nobody had looked at.

    ``slate_id`` additionally regrounds the opening CHOICE SLATE on what this
    vision pass saw, pushing a ``choices_revised`` item. On the montage path the
    slate is written during reset, when the run has not rendered a single frame
    — so it is drafted from the level's prose and can describe somewhere the
    player is not. It did: on 2026-09-17 the opening slate offered "Smash the
    CRT screen glass" while the player stood on a ridge above an open-pit mine.

    Done here rather than through _spawn_observe_reground, which does the same
    job for an ordinary turn, because that one writes ``hist[-1]`` unguarded —
    fine mid-turn, wrong here, where the player may already have taken turn one
    by the time this lands. This walks the same path with the opening's own
    guard on it, and spends ONE vision call for both jobs.
    """
    if not VISION_ENABLED or not img_path:
        print(f"[WORLD FRAMES] opening vision skipped "
              f"(vision={VISION_ENABLED}, path={bool(img_path)})", flush=True)
        return

    def _worker():
        global history
        try:
            vres = _vision_analyze_all(img_path)
        except Exception as e:
            log_error(f"[WORLD FRAMES] opening vision failed: {e}")
            return
        vision = ((vres or {}).get("description") or "").strip() \
            if isinstance(vres, dict) else ""
        if not vision:
            print("[WORLD FRAMES] opening vision returned nothing", flush=True)
            return
        with WORLD_STATE_LOCK:
            hist = _load_history(session_id)
            # Only the opening, and only while the run is still sitting on it.
            if not hist or not (hist[0] or {}).get("cached_opening"):
                print("[WORLD FRAMES] opening vision arrived after the run "
                      "moved on; dropping", flush=True)
                return
            if hist[0].get("vision_analysis"):
                return
            hist[0]["vision_analysis"] = vision
            for key, src in (("setting_type", "setting"),
                             ("spatial_compass", "spatial")):
                val = (vres.get(src) or "").strip()
                if val:
                    hist[0][key] = val
            _save_history(hist, session_id)
            if get_active_session_id() == session_id:
                history = hist
        print(f"[WORLD FRAMES] opening vision len={len(vision)}", flush=True)
        if slate_id is not None:
            _reground_opening_slate(session_id, img_path, vision, slate_id)

    threading.Thread(target=_worker, name="opening-vision", daemon=True).start()


def _reground_opening_slate(session_id: str, img_path: str, vision: str,
                            slate_id) -> None:
    """Rewrite the opening choices from the frame the player actually arrived on.

    Called with the vision text the opening pass already produced, so this costs
    one choice call and no extra look. Never fatal: on any failure the slate the
    level was authored with stays exactly as it is.
    """
    from choices import generate_choices

    try:
        with WORLD_STATE_LOCK:
            st = _load_state(session_id) or {}
            hist = _load_history(session_id) or []
        # The player has already moved on; their live slate is turn one's.
        if len(hist) > 1:
            print("[OPENING SLATE] the run moved on before the reground "
                  "landed; leaving the choices alone", flush=True)
            return
        texts = generate_choices(
            client=client,
            prompt_tmpl=PROMPTS["player_choice_generation_instructions"],
            last_dispatch=vision,
            image_description=vision,
            image_url=img_path,
            world_prompt=st.get("world_prompt", ""),
            situation_summary=summarize_world_state(st),
            inventory=st.get("inventory"),
            n=3,
            beat_nudge=beat_nudge_text(st),
        ) or []
    except Exception as e:
        log_error(f"[OPENING SLATE] reground failed: {e}")
        return
    if not texts:
        return
    item = create_feed_item(
        type="choices_revised",
        content="",
        choices=[{"text": t} for t in texts],
        metadata={"prompt_id": slate_id},
    )
    with WORLD_STATE_LOCK:
        st = _load_state(session_id) or {}
        st["choices"] = [{"text": t} for t in texts]
        _feed_append(st, item)
        _save_state(st, session_id)
        _sync_ambient_state(st, session_id)
    print(f"[OPENING SLATE] regrounded on the frame the player arrived on: "
          f"{texts}", flush=True)


# The Level sheet fields that have to say something before a run can claim to
# be set anywhere. `name` alone is not enough — that is exactly the state the
# boot warning calls hollow (see api._warn_if_the_world_is_hollow).
_LEVEL_ANCHOR_FIELDS = ("summary", "era", "palette", "landmarks", "opening_shot")


def level_sheet_is_hollow(spec: Optional[dict] = None) -> bool:
    """The Level sheet has a name and nothing else, or not even that."""
    try:
        spec = spec or game_identity.get_spec()
        setting = spec.get(game_identity.SETTING_KEY) or {}
    except Exception:
        return False
    return not any(str(setting.get(f) or "").strip() for f in _LEVEL_ANCHOR_FIELDS)


def _goal_for_this_run(new_state: dict, authored: str = "", session_id: str = "") -> str:
    """The thing on the horizon this run is walking toward. Always something.

    A run with no goal has no shape: the montage establishes "toward
    '(no goal authored)'", every frame is a place rather than a direction, and
    the player is left wandering a world that never tells them what it is FOR.
    Reported as "the goal system is completely non functional ... making sure we
    always have a goal generated can really help the experience stay focused".

    WHAT THIS DOES NOT DO IS WRITE TO THE LEVEL SHEET. That distinction is the
    whole design, and it is not stylistic — see _ensure_level_sheet_is_filled,
    which was on the boot path for one afternoon, invented "The Kettle Yard" out
    of the Four Corners bible, and persisted it over the author's own words with
    no prompt and no undo. Model-invented content must never silently replace
    something a person typed.

    So the draft lands in the RUN, not in the authoring data:

      · an authored goal is used verbatim and nothing is generated,
      · otherwise this run gets one of its own, cached in state so it costs a
        single call per playthrough and stays the same landmark all the way
        through it,
      · and `prompts/simulation_prompts.json` is never touched either way.

    Never fatal, and never blocking: the montage's own fallback (the first
    landmark) still stands if the draft fails, which is worse but not broken.
    """
    authored = str(authored or "").strip()
    # Whose look book the first goal draws its gear from. This read a bare
    # `session_id` that was never in scope, so the NameError took the draw
    # AND the draft down with it and the first goal fell back to the level's
    # sentence cut to 34 characters: "The reinforced blast door at the"
    # (22:00 playtest).
    sid = str(session_id or "").strip()
    if not sid:
        try:
            sid = _resolve_request_session_id()
        except Exception:
            sid = ""
        if not sid or sid == "default":
            sid = get_active_session_id() or "default"
    # GOAL-BODY v2
    # Chosen already for this run: a second call on the same reset, or a state
    # that already carries a line (kept verbatim, labelled without a model).
    if str((new_state or {}).get("goal_name") or "").strip():
        return str(new_state.get("level_goal") or "")
    cached = str((new_state or {}).get("level_goal") or "").strip()
    if cached:
        return _goal_mod.install(new_state, {}, line=cached)

    # An authored goal wins, always, in its own words. The model only gives it
    # a label-length name and a far-off look for the pictures; nothing is
    # written back to the Level sheet either way (see the docstring above).
    written = str(game_identity.level_goal(fallback=False) or "").strip()
    rec = {}
    gear = {}
    if LLM_ENABLED:
        lore = ""
        try:
            import experience_store as _xs
            lore = _xs.lore_brief() or ""
        except Exception:
            pass  # no lore is a thinner draft, not a failed one
        # THE FIRST GOAL DRAWS ITS GEAR TOO. Goals 2 and 3 go through
        # goal.advance, which draws from the look book's table before it
        # drafts the place; this one is built here instead, and without the
        # same draw the opening lap was the only one that handed out an
        # invented prize — a run whose first find was not one of the six
        # pieces its own world had designed.
        gear = {}
        try:
            gear = _goal_mod.draw_gear(new_state, sid) or {}
        except Exception as err:
            log_error(f"[GOAL] no gear for the first goal ({err})")
        try:
            rec = _goal_mod.invent(
                lore=lore,
                world_prompt=str((new_state or {}).get("world_prompt") or ""),
                authored=written,
                holds=_goal_mod.as_prize(gear) if gear else None,
                session_id=sid,
            ) or {}
        except TypeError:
            # An older goal module without the gear arguments.
            rec = _goal_mod.invent(
                lore=lore,
                world_prompt=str((new_state or {}).get("world_prompt") or ""),
                authored=written,
            ) or {}
        except Exception as err:
            log_error(f"[GOAL] invent failed ({err})")
            rec = {}
    # The drawn gear IS what is inside, whatever the draft came back with.
    if gear and isinstance(rec, dict):
        try:
            rec["prize"] = _goal_mod.as_prize(gear)
        except Exception:
            pass
    if written:
        # The author's words stay the goal; everything else the draft came
        # back with rides along — the thing inside it, the one who holds it,
        # and the spine. Hand-picking three keys here is why an authored
        # World never had a prize to take and its tag pointed at the building
        # the player was already standing in.
        line = _goal_mod.install(
            new_state, {**rec, "name": rec.get("name") or "",
                        "why": rec.get("why") or "",
                        "look": rec.get("look") or written}, line=written)
    elif rec:
        line = _goal_mod.install(new_state, rec)
    else:
        # No model, or it failed: the landmark the montage fell back to.
        fallback = authored or str(game_identity.level_goal() or "").strip()
        if not fallback:
            print("[GOAL] no goal this run", flush=True)
            return ""
        line = _goal_mod.install(new_state, {"look": fallback}, line=fallback)
    # ASCII only on the console (cp1252).
    print(f"[GOAL] this run is walking toward: "
          f"{str(new_state.get('goal_name') or '')!r}", flush=True)
    return line

def run_goal(state: Optional[dict] = None) -> str:
    """The goal THIS run is walking toward, as the rest of the loop should read it.

    `_goal_for_this_run` above wrote `state["level_goal"]` at every reset and
    then nothing read it: the goal reached the montage's title card and,
    one narration in six, the narrator — and never the consequence model, the
    choice slate, the objectives HUD or an encounter. A run had a destination
    for exactly as long as the opening cinematic was on screen. Matt's report
    was "the goal system is completely non functional", and a traced
    twelve-turn run bore it out: the door the montage was staged toward
    turned up in the prose only as recurring scenery (the level's LANDMARKS
    line), the HUD lead never named it in eleven turns, and the player dove
    through it on turn 12 without the run noticing — the next slate still
    offered "Kick the blast door open".

    Read off the RUN only. Both reset paths write `level_goal` now (the
    montage path always did; the cached-frame path calls `_goal_for_this_run`
    too), so this never has to go back to the level sheet — and a state that
    carries no goal gets no goal line, which keeps every prompt surface
    deterministic for a test that builds a bare state.
    """
    st = state if isinstance(state, dict) else {}
    return str(st.get("level_goal") or "").strip()[:220]


def goal_directive(state: Optional[dict] = None) -> str:
    """The one line every prompt surface gets about where the run is going.

    Deliberately NOT "make the player reach it": a goal that the world hands
    over on request is a title card, not a destination. The beat may put it
    closer, put something in the way, or make it cost — it may not forget it,
    and it may not quietly resolve it. Ends with a newline so it drops into
    the grounding block like the other directives.
    """
    goal = run_goal(state)
    if not goal:
        return ""
    st = state if isinstance(state, dict) else {}
    # IN THE ROOM WITH IT. The walk is over but the goal is not: what they came
    # for is in here and they have not put their hands on it yet, so the beat
    # is written around the thing rather than around "what comes after".
    if _goal_mod.phase(st) == "prize":
        return (f"WHAT THE PLAYER CAME HERE FOR: {goal}\n"
                + _goal_mod.sight_directive(st))
    reached = int(st.get("goal_reached_turn") or 0)
    if reached:
        return (
            f"WHAT THE PLAYER CAME HERE FOR: {goal} — REACHED on turn {reached}.\n"
            "The run is now about what it cost and what comes after: what they "
            "found there, and the way out with it. Do not offer the goal again "
            "as if it were still ahead of them.\n"
        )
    return (
        f"WHAT THE PLAYER CAME HERE FOR: {goal}\n"
        "This is the run's destination. It stays true until an action plainly "
        "reaches it: the beat may bring it closer, block it, or make it cost "
        "something, but it must not forget it exists, and must not hand it over "
        "for free.\n"
    ) + _goal_mod.sight_directive(st)


def _ensure_level_sheet_is_filled() -> bool:
    """Draft every EMPTY identity-sheet field from the world bible. EXPLICIT ONLY.

    NOT ON THE BOOT PATH, and it must not go back on it. It was, for one
    afternoon, and that was a worse bug than the one it set out to fix: a blank
    Level sheet made this run a live LLM call at reset and PERSIST the answer
    into prompts/simulation_prompts.json. Handed a nine-thousand-word bible
    about a quarantined Horizon site in the Four Corners, the model invented "The
    Kettle Yard — a flooded shipbreaking yard on a tidal flat", wrote it over the
    authoring data, and the opening montage was then drawn of it. No prompt, no
    undo, every boot. Model-invented content must never silently replace
    something a person typed.

    What the empty field genuinely costs is still real, and is still the reason
    this function exists to be CALLED: nothing else in a boot knows where the
    level is. ``opening_shot``, ``place_summary``, ``establishing_shot`` and the
    montage's own shotlist each read this sheet, and when it is blank they each
    fall through to free-associating over that same bible — three reads of one
    empty field, three different answers, a run that does not stay in a place.
    One blank field does it too: with ``goal`` empty, ``level_goal`` walks back
    to the first landmark, so a level whose landmarks began "chain-link fence"
    established a montage toward a fence the player already stood at.

    So the capability stays, behind an explicit call — the editor's fill button,
    or ``python tools/draft_identity_sheets.py`` — where a person sees the draft
    and decides. The boot's job is to SAY the sheet is blank
    (api._warn_if_the_world_is_hollow), not to answer for the author.

    Never fatal. A failed draft leaves the sheets exactly as they were.
    """
    try:
        blocks = [b for b in game_identity.text_fillable_blocks()
                  if game_identity.empty_fill_fields(b)]
    except Exception:
        logging.exception("[SHEETS] could not read the identity sheets")
        return False
    if not blocks:
        return False
    # The Level sheet leads: it is the one that anchors the place, and it is
    # what everything below this line is about to read.
    setting_key = getattr(game_identity, "SETTING_KEY", "")
    if setting_key in blocks:
        blocks = [setting_key] + [b for b in blocks if b != setting_key]

    gaps = {b: game_identity.empty_fill_fields(b) for b in blocks}
    if not LLM_ENABLED:
        print(f"[SHEETS] blank fields {gaps} and no text model to draft them "
              f"from — the run may not know where it is", flush=True)
        return False

    t0 = time.time()
    print(f"[SHEETS] drafting blank fields from the world bible before "
          f"anything renders: {gaps}", flush=True)
    any_filled = False
    for block in blocks:
        try:
            res = game_identity.apply_text_fill(block)
        except Exception as e:
            log_error(f"[SHEETS] {block} draft failed: {e}")
            continue
        filled = (res or {}).get("filled") or {}
        if not filled:
            print(f"[SHEETS] {block}: nothing drafted "
                  f"({(res or {}).get('reason') or 'unknown'})", flush=True)
            continue
        any_filled = True
        for key, val in filled.items():
            print(f"[SHEETS]   {block}.{key}: {str(val)[:110]}", flush=True)
    if any_filled:
        print(f"[SHEETS] done in {time.time() - t0:.1f}s — every render below "
              f"this now agrees where it is", flush=True)
    return any_filled


def _cached_opening_frame(new_state: dict) -> tuple:
    """The plate this run opens on — DRAWN FRESH, every run. No cache read.

    Returns (slug, rec). `rec` is {} only when there is genuinely nothing to
    open on, in which case the intro renders its own frame and the run gets no
    montage. Split out of _apply_cached_opening_frame so the opening CHOICE
    SLATE can be grounded on this still before the feed items are built — the
    slate used to be written from the shot description while the picture the
    player actually starts on sat on disk, unread.

    It used to read ``world_frames.record()`` and open on whatever was cached.
    That cache is stamped with the World SNAPSHOT's hash while a run is played
    on the LIVE prompt file, and the two drift the moment anybody edits
    anything — so the frame on disk could be a photograph of the previous hero.
    ``drawn_from_live`` caught that, and the only thing it could then do was
    give up: ``ensure()`` renders from the snapshot, so re-rendering would have
    produced the wrong hero again. The run therefore opened with NO CUTSCENE,
    explained in one line of server stdout that no player will ever read, and
    healed itself on the following run. Editing a world cost you your opening,
    silently, and that is exactly what happened on 2026-09-17.

    So the opening does not consult the cache any more. ``render_live_plate``
    draws it now, from the prompts this run is about to be played on, which
    makes the frame correct by construction and removes every reason the
    montage had to be skipped. The gain is that the opening happens EVERY time.

    Two costs, both accepted deliberately:

    · One image render on the boot path. In the case that was broken this is
      free — the run was already paying for ``_spawn_scene_image_async``
      because the cache had been refused. On a warm, valid cache it is new.
    · It runs inside ``TURN_LOCK``, because the plate has to be drawn from the
      prompts ``apply_experience_start`` binds a few lines earlier, and that
      binding is what the lock protects. Scene renders were deliberately moved
      OFF this lock once (see _spawn_scene_image_async) because one player's
      render stalled every other player's reset, so this is a knowing step
      back toward that for a once-per-run event on a local single-player boot.
      If this app ever serves concurrent players again, hoist the plate render
      out by binding the Experience before the lock.

    The cache is still written — the editor's carousel and the Experience graph
    read it — it just no longer decides whether the player gets a cutscene.
    """
    try:
        import world_frames
    except Exception as e:
        logging.warning(f"[WORLD FRAMES] inject skipped: {e}")
        return "", {}
    slug = ""
    try:
        wid = str((new_state or {}).get("experience_world_id") or "")
        import experience_store
        exp = experience_store.get_experience()
        world = experience_store.world_by_id(exp, wid) if wid else None
        slug = str((world or {}).get("slug") or "") or world_frames.start_world_slug(exp)
    except Exception:
        slug = world_frames.start_world_slug()
    if not slug:
        return "", {}

    def _usable(r: dict) -> bool:
        # A placeholder is a 64px mint square that world_frames installs the
        # moment a frame goes missing, and it stays there if the paid render
        # then fails. Opening a run on it is the flat green screen on Start.
        return bool(r and r.get("url") and r.get("path")
                    and world_frames.is_real_still(r))

    rec = {}
    try:
        # The plate is lit by THIS run's lighting line. Without it the render
        # read the lighting off the module-global run state, which during a
        # reset is still the run being thrown away — often another World's.
        rec = world_frames.render_live_plate(
            slug, time_of_day=str((new_state or {}).get("time_of_day") or "")) or {}
    except Exception:
        logging.exception(f"[WORLD FRAMES] live plate for {slug} raised")
    if not rec:
        rec = world_frames.record(slug) or {}

    # Below here is the ORIGINAL refusal logic, unchanged, and it should now be
    # unreachable whenever images are on: the render above draws from the live
    # prompts and stamps them, so the frame cannot be of the wrong hero. What is
    # left are the genuinely degraded cases — images off, no key, a render that
    # came back empty — where there is no montage to be had either way, because
    # the montage is itself a paid render. Falling back to a stale plate there
    # would buy nothing and would re-introduce the bug these checks exist for:
    # opening a run on a photograph of the previous protagonist.
    if not _usable(rec):
        # Warm this World in the background so the *next* reset has something.
        try:
            world_frames.ensure(slug, wait=False)
        except Exception:
            pass
        return slug, {}
    if not world_frames.drawn_from_live(rec):
        print(f"[WORLD FRAMES] {slug} has no plate of this run's own and the "
              f"cached one was drawn from different prompts, so the run renders "
              f"its own opening still and gets NO MONTAGE. This is now only "
              f"reachable when the plate render could not run at all (images "
              f"off, no key, empty result) — see world_frames.render_live_plate.",
              flush=True)
        # Deliberately no ensure() here: it would re-render from the snapshot,
        # i.e. the wrong hero again. The intro about to run installs the right
        # frame itself (see world_frames.remember_from_play).
        return slug, {}
    return slug, rec


def _apply_cached_opening_frame(
    session_id: str,
    new_state: dict,
    intro_items: list,
    intro_image_kwargs: dict,
    resolved: Optional[tuple] = None,
) -> bool:
    """Put the World's cached first frame into a fresh run's feed.

    Returns True if intro gen should still spawn (cache missing, or dirty so
    we want a background refresh). Returns False when the cache is warm and
    clean — Play can start on that still with no render wait.

    `resolved` is the (slug, rec) the caller already looked up to ground the
    opening slate; passing it through avoids resolving (and re-warming) twice.
    """
    slug, rec = resolved if resolved is not None else _cached_opening_frame(new_state)
    if not rec:
        return True
    try:
        import world_frames
    except Exception as e:
        logging.warning(f"[WORLD FRAMES] inject skipped: {e}")
        return True
    web = rec["url"]
    img_path = rec["path"]
    caption = (intro_image_kwargs or {}).get("caption") or ""
    dispatch = (intro_image_kwargs or {}).get("dispatch") or caption
    choice = (intro_image_kwargs or {}).get("choice") or "Initialize Simulation"
    world_prompt = (intro_image_kwargs or {}).get("world_prompt") or ""
    frame_prompt = str(rec.get("prompt") or "").strip()
    if not frame_prompt:
        try:
            import worlds_store
            data = worlds_store.get_world(slug)
            frame_prompt = world_frames.scene_prompt_for(
                data.get("prompts") or {}, dispatch
            )
        except Exception:
            frame_prompt = (dispatch or caption or "").strip()
    visual = frame_prompt or dispatch or caption
    render_base = build_realtime_base(visual_scene=visual, narrative=caption)
    render_prompt = build_realtime_prompt(
        visual_scene=visual, narrative=caption, choice=choice
    )
    item = create_feed_item(
        type="scene_image",
        content="",
        image_url=web,
        metadata={
            "prompt": render_prompt,
            "base": render_base,
            "image_prompt": visual,
            "hard_transition": True,
            "cached_opening": True,
        },
    )
    intro_items.append(item)
    new_state["current_image_url"] = web
    new_state["current_image_prompt"] = visual
    new_state["current_render_prompt"] = render_prompt
    new_state["current_render_base"] = render_base
    tape = [f for f in (new_state.get("tape_frames") or []) if isinstance(f, str)]
    if not tape or tape[-1] != web:
        tape.append(web)
    new_state["tape_frames"] = tape[-400:]
    try:
        import run_tape
        run_tape.record(session_id, "opening", [web], prose=dispatch or "",
                        prompt=visual or "", turn=0, state=new_state)
    except Exception as _tape_err:
        log_error(f"[TAPE] opening not recorded: {_tape_err}")
    hist = _load_history(session_id)
    if not hist:
        hist.append({
            "choice": choice,
            "dispatch": dispatch,
            "vision_dispatch": dispatch or caption,
            "world_prompt": world_prompt,
            "image": img_path,
            "image_url": img_path,
            "analysis_image": img_path,
            "guide_image": img_path,
            "image_prompt": visual,
            "hard_transition": True,
            "cached_opening": True,
        })
        _save_history(hist, session_id)
        _sync_ambient_history(hist, session_id)
        _spawn_cached_opening_vision(session_id, img_path)
    else:
        print(f"[WORLD FRAMES] opening not seeded: history already has "
              f"{len(hist)} entries", flush=True)
    logging.info(f"[WORLD FRAMES] opening from cache for {slug}: {web}")
    # No regen behind it. The frame was drawn from the prompts this run is
    # using, so it is already right, and a background regen would redraw it
    # from the snapshot — which is how the wrong hero got cached in the
    # first place.
    return False


def _open_on_montage(new_state: dict) -> bool:
    """Whether this run should open on an establishing montage.

    It used to require a cached World frame, because the montage was drawn FROM
    one. That requirement is what made the opening disappear whenever the cache
    was unusable, and the plate it depended on has been deleted: the montage is
    the run's FIRST render now and establishes the place itself (see
    cutscene.generate_shots with no source_path). So the only questions left are
    whether montages are switched on and whether somebody authored their own.
    """
    if not INTRO_CUTSCENE or not IMAGE_ENABLED:
        return False
    # An authored Cutscene node on the start of the graph is somebody's
    # deliberate opening. Don't stack a second montage in front of it.
    return not str((new_state or {}).get("experience_cutscene_id") or "").strip()


def _stage_opening_montage(
    session_id: str,
    new_state: dict,
    intro_items: list,
) -> list:
    """Open the run on the level's approach montage. It renders FIRST.

    There is no plate any more. The montage used to be drawn from a cached (and
    later, a freshly rendered) World frame, and that frame was a whole separate
    image render whose only jobs were to seed this one and to flash for four
    seconds as a fifth beat. It also decided, from a from-scratch text-to-image
    guess, where the level was — which is how a run opened with a montage of an
    open-pit mine and a first playable frame in an indoor storeroom.

    So the order is inverted. The montage establishes the place, from the lore
    and the Level sheet (which _ensure_level_sheet_is_filled has guaranteed says
    something), and the IDLE beat that follows it is drawn from these panels.
    Two renders, and the second one is locked to the first.

    The opening choice slate is pulled OUT of the feed and parked in
    ``pending_opening_choices``. Verbs sitting under a montage are a prompt to
    act during a beat the player is supposed to watch; the montage hands them
    back when it finishes (see _finish_opening_montage).
    """
    import uuid

    import cutscene as _cutscene

    shot = game_identity.establishing_shot()
    shot["goal"] = _goal_for_this_run(new_state, shot.get("goal"), session_id)
    slate = next((it for it in intro_items
                  if (it or {}).get("type") == "player_choice_prompt"), None)
    if slate:
        intro_items = [it for it in intro_items if it is not slate]
        new_state["pending_opening_choices"] = slate

    new_state["pending_cutscene"] = {
        "cutscene_id": "open-" + uuid.uuid4().hex[:8],
        "name": shot["title"],
        "mood": "approach",
        "status": "pending",
        "opening": True,
        "goal": shot["goal"],
        "prologue": shot["prologue"],
        # Deliberately absent: there is no source plate. cutscene.play_for_session
        # reads `opening` to know it may render without one.
        "source_path": "",
        "duration_ms": int(_cutscene.HOLD_MS),
        "graph": False,
    }
    intro_items.append(_cutscene_feed_item({
        "cutscene": new_state["pending_cutscene"],
        "from": {},
    }))
    print(f"[OPENING] establishing montage for {shot['title']!r} "
          f"toward {shot['goal'] or '(no goal authored)'!r}", flush=True)
    return intro_items


# How many montage panels seed the idle beat. The FIRST is the img2img anchor —
# the place the character is about to be standing in — and the rest are context.
# generate_gemini_img2img caps the whole payload at six references and prepends
# the identity plates, and the flipbook LAYOUT GUIDE goes on the tail — lose
# that and the grid comes back unsplittable. Two panels is what fits with room
# to spare.
#
# It was one while the plate held the anchor slot. With the plate gone the
# panels ARE the place, so the wide and the architectural wide both go in; the
# macro detail and the ground-level litter shot would be poor anchors and fall
# off the end of the limit naturally, in shot order.
OPENING_MONTAGE_REFS = 2


def _montage_place_refs(pending: dict, plate_path: str = "") -> List[str]:
    """The montage panels the first playable frame is drawn from.

    The opening montage is the part of a boot that is drawn from the live level
    definition — cutscene.mystery_shotlist reads the world bible for its four
    subjects — and it is now also the run's first render. So these panels are
    not context any more, they are the anchor: refs[0] is the photograph the
    idle beat puts the character into.

    Panel one leads because the approach mood's first brief is "the widest,
    emptiest view this place affords", which is the strongest single statement
    of where we are.

    ``plate_path`` is vestigial and defaults to "". The opening has no plate, so
    there is nothing to exclude; the argument survives for the graph-cutscene
    callers that still restage from one.
    """
    def _key(p: str) -> str:
        try:
            return os.path.normcase(os.path.realpath(p))
        except Exception:
            return os.path.normcase(p)

    skip = {_key(plate_path)} if plate_path else set()
    out: List[str] = []
    for shot in (pending or {}).get("shots") or []:
        path = str((shot or {}).get("path") or "")
        if not path or _key(path) in skip or not os.path.exists(path):
            continue
        skip.add(_key(path))
        out.append(path)
    if not out:
        print("[OPENING FLIPBOOK] no montage panels to draw the first playable "
              "frame from", flush=True)
    return out[:OPENING_MONTAGE_REFS]


def _generate_opening_establishing(session_id: str, pending: dict) -> Optional[dict]:
    """Render the IDLE — the first playable frame — SYNCHRONOUSLY, for THIS run.

    The montage is four unpeopled photographs of the place. This is the beat the
    player arrives on: the character standing in that same place, checking their
    gear, looking at something far off (establishing=True — see
    _flipbook_establishing_block). It is the second and LAST render of a boot.

    Drawn from the montage's own panels (``_montage_place_refs``), with the
    character sheet riding along as the identity lock. It used to be drawn from
    a separately rendered plate, with one montage panel behind it for context —
    and that plate was a from-scratch text-to-image guess that had every right
    to disagree with the montage about where the level was. It duly did: an
    indoor storeroom after four photographs of an open-pit mine, on 2026-09-17.
    Anchoring on panel one instead removes the disagreement by removing the
    second opinion.

    Normally started by _spawn_opening_establishing the instant the montage
    begins playing, and collected at /api/cutscene/complete. The first playable
    turn continues (img2img) from this beat's last panel, so it must be FINISHED
    and be the anchor before that turn can run — but "finished before the
    hand-off" does not mean "started at the hand-off", which is what it used to
    mean and what made the opening feel dead: the montage is ~20s of held shots
    with the server doing nothing, and then the player waited again. Generated
    fresh for the run named by ``pending``, which is what stops a slow render
    from a previous run leaking a frame into this one. It does NOT write shared
    flipbook state itself (write_state=False); the caller installs the anchors
    atomically under lock once it knows this is still the current run.

    Returns {"payload", "still", "still_url", "seq"} — ``payload`` is None when
    flipbook is off and this came back as a single still, which is a first
    playable frame either way. Returns None only when nothing rendered.
    """
    montage = _montage_place_refs(pending)
    if not montage:
        return None
    st = _load_state(session_id) or {}
    try:
        identity_spec = game_identity.get_spec()
        if game_identity.is_viewfinder_spec(identity_spec):
            plates = []
        else:
            plates = game_identity.identity_reference_paths(
                include_character=(
                    game_identity.shows_character(identity_spec)
                    or game_identity.hands_visible(identity_spec)
                ),
                spec=identity_spec,
            )
        prompt_str = game_identity.apply(
            str(st.get("world_prompt") or ""), "image", identity_spec)
        # The montage is unpeopled by instruction, so this beat is where the
        # player first SEES themselves — and it is drawn from montage panels
        # that contain nobody. If the character plate does not reach this call
        # the model invents a person out of the bible's "you are a
        # photojournalist", which is how a stranger kept opening the game.
        # Silent before; the reference list in the log showed two panels and a
        # layout guide and nothing said the plate was missing.
        if plates:
            print(f"[OPENING IDLE] {len(plates)} identity plate(s): "
                  f"{[os.path.basename(str(p)) for p in plates]}", flush=True)
        else:
            log_error("[OPENING IDLE] NO identity plate — the person in the "
                      "first playable frame will be invented from the bible, "
                      "not drawn from the character sheet")

        if not flipbook_active(st):
            # Flipbook off: the idle cannot animate, but the run still needs a
            # frame with the character in it. Without this the boot would hand
            # turn one an unpeopled montage panel — there is no plate behind it
            # any more to fall back on.
            return _opening_idle_still(
                session_id, pending, st, montage, plates, identity_spec,
                prompt_str)

        seq = _flipbook_generate(
            prompt_str=prompt_str,
            caption="opening",
            choice="",
            dispatch=str((pending or {}).get("prologue") or ""),
            world_prompt=str(st.get("world_prompt") or ""),
            time_of_day=str(st.get("time_of_day") or ""),
            img_dir=_get_image_dir(session_id),
            session_id=session_id,
            st=st,
            # refs[0] is the montage's widest panel and it is the ANCHOR: the
            # place the player is about to be standing in, already photographed,
            # already seen by them. The character comes from identity_paths.
            refs=montage,
            ref_is_anchor=True,
            identity_paths=plates or None,
            identity_seed=True,
            spec=identity_spec,
            establishing=True,
            write_state=False,  # caller installs the anchors atomically
        )
        if not seq:
            print("[OPENING IDLE] no grid — falling back to a single still",
                  flush=True)
            return _opening_idle_still(
                session_id, pending, st, montage, plates, identity_spec,
                prompt_str)
        payload = flipbook_web_payload(seq, session_id)
        still = str(seq.get("still_path") or "")
        if not payload or not still:
            return None
        # Hold each frame ~2.9s so the beat breathes (see
        # OPENING_ESTABLISHING_FRAME_MS) instead of flicking past.
        payload = dict(payload)
        payload["frame_ms"] = OPENING_ESTABLISHING_FRAME_MS
        print(f"[OPENING IDLE] {payload.get('frame_count')} frames ready — the "
              f"player arrives standing in the place they just watched",
              flush=True)
        return {"payload": payload, "still": still,
                "still_url": _to_web_image_url(still, session_id), "seq": seq}
    except Exception as e:
        log_error(f"[OPENING IDLE] failed: {e}")
        return None


def _opening_idle_still(session_id: str, pending: dict, st: dict,
                        montage: List[str], plates: list,
                        identity_spec: dict, prompt_str: str) -> Optional[dict]:
    """One frame of the player standing in the montage's place. No animation.

    The floor under the idle beat. With the plate deleted, a boot that cannot
    draw a flipbook — flipbook switched off, or a grid that would not split —
    has nothing else in it containing the protagonist, and handing turn one an
    unpeopled establishing photograph would start the game on a landscape.
    """
    from gemini_image_utils import generate_gemini_img2img

    prompt = game_identity.apply(
        _flipbook_establishing_block(single=True, goal=_goal_mod.look_line(st))
        + "\n" + prompt_str, "raw")
    try:
        path = generate_gemini_img2img(
            prompt=prompt,
            caption="opening_idle",
            reference_image_path=list(montage),
            strength=0.5,
            world_prompt=str(st.get("world_prompt") or ""),
            time_of_day=str(st.get("time_of_day") or ""),
            output_dir=_get_image_dir(session_id),
            is_flipbook=False,
            include_people=True,
            identity_paths=plates or None,
            spec=identity_spec,
        )
    except Exception as e:
        log_error(f"[OPENING IDLE] still fallback failed: {e}")
        return None
    if not path or not os.path.exists(str(path)):
        return None
    print("[OPENING IDLE] one still (no flipbook this run)", flush=True)
    return {"payload": None, "still": str(path),
            "still_url": _to_web_image_url(str(path), session_id),
            "seq": {"still_path": str(path)}}


# The opening establishing beat, rendered WHILE the montage is on screen. One
# entry per session: the run it belongs to, an Event that fires when the render
# settles either way, and the result the hand-off wants.
_OPENING_PREFETCH: Dict[str, dict] = {}
_OPENING_PREFETCH_LOCK = threading.Lock()

# How long the hand-off will hold on a prefetch that has not landed. The montage
# runs ~20s of held shots and the render takes ~15s, so by the time the player
# reaches the end it has almost always finished; a wait anywhere near this long
# means the image call is stuck, and the run opens on the static plate rather
# than leaving the browser parked on the last shot forever.
OPENING_PREFETCH_TIMEOUT_S = float(os.getenv("OPENING_PREFETCH_TIMEOUT_S", "180"))


def _spawn_opening_establishing(session_id: str, pending: dict) -> bool:
    """Start the establishing beat the moment the montage starts playing.

    This is the whole responsiveness fix. The montage's panels are the render's
    references (see _montage_place_refs), so this is the earliest moment the
    beat CAN be drawn — and it is also the moment the player stops waiting and
    starts watching, which makes the next ~20s free. /api/cutscene/complete then
    collects whatever this produced instead of starting from scratch.

    ``pending`` is snapshotted because the caller's copy is state that a reset
    landing mid-render will replace underneath us. Whether the result still
    belongs to the live run is decided at collection, by cutscene_id.
    """
    import copy

    cut_id = str((pending or {}).get("cutscene_id") or "")
    if not cut_id or not (pending or {}).get("opening"):
        # Loud on purpose. A silent return here is the whole run losing its
        # first playable frame, and it took a live playtest and four passes
        # through the logs to notice because nothing said anything.
        print(f"[OPENING] NOT rendering the first playable frame: "
              f"cutscene_id={cut_id!r} opening={(pending or {}).get('opening')!r} "
              f"— the idle beat will have to be rendered inline at the hand-off",
              flush=True)
        return False
    with _OPENING_PREFETCH_LOCK:
        live = _OPENING_PREFETCH.get(session_id)
        if live and live.get("cutscene_id") == cut_id:
            return False
        entry = {"cutscene_id": cut_id, "done": threading.Event(), "result": None}
        _OPENING_PREFETCH[session_id] = entry
    snapshot = copy.deepcopy(pending)

    def _worker():
        t0 = time.time()
        try:
            entry["result"] = _generate_opening_establishing(session_id, snapshot)
        except Exception as e:
            log_error(f"[OPENING] establishing beat raised behind the montage: {e}")
        finally:
            entry["done"].set()
        print(f"[OPENING] establishing beat settled in {time.time() - t0:.1f}s "
              f"behind the montage "
              f"({'ready' if entry['result'] else 'nothing — the plate stands'})",
              flush=True)

    threading.Thread(target=_worker, daemon=True,
                     name=f"opening-establishing-{session_id}").start()
    print(f"[OPENING] rendering the first playable frame while {cut_id} plays",
          flush=True)
    return True


def _take_opening_establishing(session_id: str,
                               cutscene_id: str) -> tuple[Optional[dict], bool]:
    """Collect the prefetched beat for this run, waiting if it is still going.

    Returns ``(sequence, handled)``. ``handled`` is False only when there is no
    prefetch for this run at all — the caller then renders inline, exactly as it
    did before this existed (an Esc'd montage, a client that never called
    /api/cutscene/play, a session whose prefetch belonged to a replaced run).
    """
    with _OPENING_PREFETCH_LOCK:
        entry = _OPENING_PREFETCH.get(session_id)
        if not entry or entry.get("cutscene_id") != str(cutscene_id or ""):
            return None, False
        _OPENING_PREFETCH.pop(session_id, None)
    if entry["done"].is_set():
        print("[OPENING] the establishing beat was ready before the montage "
              "ended — handing over immediately", flush=True)
        return entry.get("result"), True
    t0 = time.time()
    print("[OPENING] the montage ended first — holding on the establishing beat",
          flush=True)
    if not entry["done"].wait(OPENING_PREFETCH_TIMEOUT_S):
        log_error(f"[OPENING] the establishing beat did not land within "
                  f"{OPENING_PREFETCH_TIMEOUT_S:g}s — opening on the plate")
        return None, True
    print(f"[OPENING] held {time.time() - t0:.1f}s for the establishing beat",
          flush=True)
    return entry.get("result"), True


def _finish_opening_montage(st: dict, session_id: str,
                            opening_seq: Optional[dict] = None) -> dict:
    """Hand the run over from the opening montage to turn one.

    The IDLE beat is the frame the run plays from — the character standing in
    the place the montage just photographed (see _generate_opening_establishing).
    That matters beyond presentation: history[0] is the img2img reference for
    turn 1 and what SCAN and the vision pass read.

    If the idle did not render, the montage's last panel stands in. It is an
    unpeopled photograph, which is a poor place to start a game, so it is a
    genuine fallback and not a design — see the degraded branch below, which
    asks the intro renderer for a frame instead.

    Returns the fields api_cutscene_complete puts on the wire.
    """
    pending = st.get("pending_cutscene") or {}
    shots = [s for s in (pending.get("shots") or []) if (s or {}).get("url")]
    last = shots[-1] if shots else {}
    st["pending_cutscene"] = None
    st["experience_cutscene_id"] = ""

    web = last.get("url") or st.get("current_image_url") or ""
    img_path = last.get("path") or ""

    # The idle beat was rendered FRESH for this run (see
    # _generate_opening_establishing) and handed in — the run hands off on its
    # LAST panel and ships the sequence so the client plays it in. Turn one's
    # img2img continues from that same panel, so we install the flipbook anchors
    # here, atomically, now that we know this is the current run. Nothing is
    # carried across runs, so a re-run can never land on a stale frame.
    #
    # ``payload`` is None when flipbook is off and the idle came back as a
    # single still. That is still a first playable frame with the character in
    # it, so it installs exactly the same way; there is just nothing to play.
    # LAST LINE OF DEFENCE. The idle beat is normally rendered behind the
    # montage and handed in as ``opening_seq``; when it is not, the run has NO
    # frame with the protagonist in it and turn one draws one from nothing —
    # text-to-image, no reference, a different place. That is precisely what
    # shipped for an afternoon and it is the worst failure the opening has.
    #
    # So if the beat is absent and the panels are on disk, render it HERE,
    # synchronously, from those panels. Slower than the prefetch, and the point
    # is that it cannot be skipped: the montage the player just watched is the
    # input to the frame they arrive on, always.
    if not (isinstance(opening_seq, dict) and opening_seq.get("still")) \
            and _montage_place_refs(pending):
        log_error("[OPENING] no idle beat arrived from the prefetch — rendering "
                  "it inline from the montage panels so the run does not open "
                  "on a frame drawn from nothing")
        try:
            opening_seq = _generate_opening_establishing(session_id, pending)
        except Exception as e:
            log_error(f"[OPENING] inline idle render failed: {e}")

    seq_payload = None
    idle_landed = False
    if isinstance(opening_seq, dict) and opening_seq.get("still") \
            and os.path.exists(str(opening_seq.get("still"))):
        idle_landed = True
        seq_payload = opening_seq.get("payload")
        web = str(opening_seq.get("still_url") or "") or web
        img_path = str(opening_seq.get("still") or "") or img_path
        _seq = opening_seq.get("seq") or {}
        if _seq.get("still_path"):
            # Anchor turn one on the idle frame (the img2img reference).
            st["flipbook_last_grid"] = _seq.get("grid_path")
            st["flipbook_first_frame"] = _seq.get("first_path")
            st["flipbook_last_frame"] = _seq.get("still_path")
            st["current_sequence"] = seq_payload
        print(f"[OPENING] the player arrives in the place they just watched "
              f"({(seq_payload or {}).get('frame_count') or 1} frame(s))",
              flush=True)
    elif shots:
        log_error("[OPENING] the idle beat did not render — the run is opening "
                  "on the montage's last panel, which has nobody in it")

    if web:
        st["current_image_url"] = web
        tape = [f for f in (st.get("tape_frames") or []) if isinstance(f, str)]
        if not tape or tape[-1] != web:
            tape.append(web)
        st["tape_frames"] = tape[-400:]
    # THE TAPE opens the way the run did: the montage's establishing shots,
    # then the arrival (the idle beat's panels, or the frame it landed on).
    try:
        import run_tape
        # The prologue is read over the montage a sentence a shot, the way a
        # title sequence is; whatever is left is the arrival's line.
        _lines = [x for x in re.split(r"(?<=[.!?])\s+", str(pending.get("prologue") or "").strip()) if x]
        for _i, _shot in enumerate(shots):
            run_tape.record(session_id, "montage", [_shot.get("path") or _shot.get("url")],
                            prose=_lines[_i] if _i < len(_lines) else "",
                            prompt=str(_shot.get("camera") or ""), turn=0, state=st)
        _arrive = list((seq_payload or {}).get("frames") or []) or ([img_path or web] if (img_path or web) else [])
        if _arrive:
            run_tape.record(session_id, "opening", _arrive,
                            frame_ms=(seq_payload or {}).get("frame_ms"),
                            prose=" ".join(_lines[len(shots):]) or str(pending.get("goal") or ""),
                            prompt=st.get("current_image_prompt") or pending.get("goal") or "",
                            turn=0, state=st)
    except Exception as _tape_err:
        log_error(f"[TAPE] opening not recorded: {_tape_err}")

    seed_vision_for = ""
    if img_path and os.path.exists(img_path):
        hist = _load_history(session_id)
        if not hist:
            visual = st.get("current_image_prompt") or pending.get("goal") or ""
            # The montage panels, for turn one's img2img — but only when the
            # idle beat did not land at all. When it did, `img_path` IS a frame
            # generated from these panels, so handing the raw panels to turn one
            # as well would put a second composition beside the one that already
            # won.
            montage_refs = [] if idle_landed else _montage_place_refs(pending)
            if montage_refs:
                print(f"[OPENING] no idle beat this run — carrying "
                      f"{len(montage_refs)} montage panel(s) into turn one's "
                      f"references instead", flush=True)
            hist.append({
                "choice": "Initialize Simulation",
                "dispatch": pending.get("prologue") or "",
                "vision_dispatch": pending.get("prologue") or "",
                "world_prompt": st.get("world_prompt") or "",
                "image": img_path,
                "image_url": img_path,
                "analysis_image": img_path,
                "guide_image": img_path,
                "image_prompt": visual,
                "hard_transition": True,
                "cached_opening": True,
                "montage_refs": montage_refs,
            })
            _save_history(hist, session_id)
            _sync_ambient_history(hist, session_id)
            seed_vision_for = img_path

    # The real opening slate, generated at reset and parked while the montage
    # played. Falling back to "Look around" here would throw away three choices
    # that were already written for this level.
    choices_item = st.pop("pending_opening_choices", None)
    if not choices_item:
        choices_item = _structure_choices_for_feed(
            ["Look around"], "You've arrived. What's your first move?",
            image_url=web,
        )
    _feed_append(st, choices_item)
    st["choices"] = choices_item.get("choices")
    # That slate was written during reset, before this run had rendered a
    # single frame — on the montage path there is nothing to ground it on at
    # that point. Look at the frame the player actually arrived on and rewrite
    # it from that, in the background, off the same vision call that grounds
    # history[0]. Appended first so the reground has an id to revise.
    if seed_vision_for:
        _spawn_cached_opening_vision(session_id, seed_vision_for,
                                     slate_id=choices_item.get("id"))
    return {"image_url": web, "choices": choices_item,
            "to_world": st.get("experience_world_id") or "",
            # The idle beat's frames + timing when it animated in, else None —
            # the client plays it before settling on the last frame.
            "sequence": seq_payload}

# --- Internal Reset Logic --- (Moved from api_reset for reusability)
# ═══════════════════════════════════════════════════════════════════════════
# ONE PURGE, CALLED FROM EVERY PLACE A RUN BEGINS
#
# Reported from the sofa: "when I run the game the current run is always
# polluted by previous runs. when I switch worlds I get artifacts from the last
# one... sometimes I see images of a character appear in my new world."
#
# The run's own DATA was never the problem. `_perform_game_reset` rebuilds
# state.json and history.json correctly and always has. What survived was
# everything held in PROCESS memory beside them: module-level dicts keyed by
# session_id, where `session_id` for a single-player boot is always the literal
# string "default". A new run therefore asked each of them a question the old
# run had already answered, and got the old run's answer:
#
#   _VISUAL_TONE_CACHE   the previous world's palette — and it is not merely
#                        returned, it is fed to the new world's first tone call
#                        as "PREVIOUS TONE (keep matching this)". The new world
#                        was told to look like the old one before it had
#                        rendered a single frame.
#   _PORTRAIT_CACHE      a face minted in the previous world, returned for any
#                        subject carrying the same label in the new one
#   _CAMP_CACHE          the previous world's campfire, because its key is the
#                        companion roster and the jeep, and names no world
#   _INTERACT_PLATES     a close-up published in the previous run, still inside
#                        its 90-second TTL, composited into the new run's first
#                        scene under the heading "THE SUBJECT YOU JUST LOOKED
#                        AT CLOSELY"
#   _OPENING_PREFETCH    an opening image prefetched for the world we left
#   _FLIPBOOK_SEQUENCES  a half-consumed animation from the previous run
#   _vision_cache        a read of a frame belonging to the previous world
#
# The last four are how a character from the previous world physically walks
# into the new one, and neither reset path cleared any of them.
#
# So: one function, no judgement calls at the call sites. Both reset paths call
# it, and so does the mid-run world stitch — switching worlds is where the
# complaint is loudest, and `apply_experience_world` only ever cleared the open
# encounter.
#
# It takes a session id and clears that session's slice, because two people on
# one server must not purge each other's run. The genuinely process-wide ones
# are cleared wholesale; they cache a picture or a reading of one, so another
# session losing an entry costs it a re-read rather than correctness.
#
# ADDING A CACHE: put its name in one of the tuples below, or in
# `_RUN_CACHES_EXEMPT` with the reason it must survive. test_run_isolation.py
# walks this module for caches and fails if a new one appears in neither —
# because the entire class of bug above is "somebody added a cache and nothing
# told them it had to be forgotten".

#: Dicts keyed DIRECTLY by session_id.
_RUN_CACHES_BY_SESSION = (
    "_VISUAL_TONE_CACHE",
    "_PORTRAIT_SPEND",
    "_FLIPBOOK_SEQUENCES",
    "_OPENING_PREFETCH",
    "_INTERACT_PLATES",
)

#: Dicts whose key is a TUPLE whose FIRST element is the session id. Purging
#: these means walking the keys, so they are listed apart rather than guessed
#: at: popping by session id would silently no-op and read as working.
_RUN_CACHES_BY_SESSION_TUPLE = (
    "_PORTRAIT_CACHE",
    "_CAMP_CACHE",
)

#: Caches with no session in the key at all, cleared wholesale.
_RUN_CACHES_PROCESS_WIDE = (
    "_vision_cache",
)

#: Module-level dicts that must SURVIVE a reset, and why. A reader arriving
#: here from the guard test needs the reason, not just the exemption.
_RUN_CACHES_EXEMPT = {
    "_SESSION_IMAGE_LOCKS":
        "locks, not data — replacing one mid-render loses mutual exclusion "
        "between the render that holds it and the next one",
    "_RATE_BUCKETS":
        "abuse limits are keyed per client IP and deliberately outlive a run. "
        "Clearing them would make /api/reset the way to bypass every limit.",
}


def purge_run_caches(session_id: str = "default", *, reason: str = "reset") -> None:
    """Forget everything this process remembers about ``session_id``'s run.

    Safe to call more than once and safe to call on a session that has never
    played — every branch is a pop or a clear. It deliberately touches only
    caches: nothing here is authoritative, so the cost of purging too much is
    latency and the cost of purging too little is the previous world's
    character standing in this one.
    """
    global _last_image_path, _last_movement_type, _is_inside

    sid = str(session_id or "default")
    cleared: List[str] = []

    for name in _RUN_CACHES_BY_SESSION:
        cache = globals().get(name)
        if isinstance(cache, dict) and cache.pop(sid, None) is not None:
            cleared.append(name)

    for name in _RUN_CACHES_BY_SESSION_TUPLE:
        cache = globals().get(name)
        if not isinstance(cache, dict):
            continue
        doomed = [k for k in list(cache.keys())
                  if isinstance(k, tuple) and k and k[0] == sid]
        for key in doomed:
            cache.pop(key, None)
        if doomed:
            cleared.append(name)

    for name in _RUN_CACHES_PROCESS_WIDE:
        cache = globals().get(name)
        if cache is not None and hasattr(cache, "clear"):
            try:
                cache.clear()
                cleared.append(name)
            except Exception as e:
                logging.warning(f"[PURGE] {name} would not clear: {e}")

    # Single-slot process globals that describe "the frame we are continuing
    # from". A new run continues from nothing, and `_last_image_path` in
    # particular is what a render reaches for when history is empty — which is
    # exactly the state a reset leaves history in.
    _last_image_path = None
    _last_movement_type = None
    _is_inside = False

    # Sibling modules keep their own run-scoped state. They are imported here
    # rather than at module scope because `encounter` imports `engine` back.
    try:
        import gemini_image_utils
        # The img2img continuity handle. It is a module global holding a PIL
        # image of the last frame this process corrected, with no session in
        # it at all, so the first render of a new world could continue from the
        # last render of the old one.
        gemini_image_utils._last_corrected_image = None
        cleared.append("gemini_image_utils._last_corrected_image")
    except Exception as e:
        logging.warning(f"[PURGE] image continuity handle survived: {e}")

    try:
        import encounter
        encounter._LOOK_READ_CACHE.pop(sid, None)
        # Keyed by description text, not by session: the previous world's
        # wardrobe tokens would answer a clone check in the new one.
        encounter._LOOK_TOKEN_CACHE.clear()
        cleared.append("encounter look caches")
    except Exception as e:
        logging.warning(f"[PURGE] encounter look caches survived: {e}")

    try:
        import choices as _choices
        _choices.LAST_CHOICE_TIMING.update({"choices_ms": 0, "critic_ms": 0})
    except Exception:
        pass

    print(f"[PURGE] session={sid} reason={reason} "
          f"cleared={', '.join(cleared) if cleared else 'nothing was stale'}",
          flush=True)


#: Media a run generates and can generate again. Wiped when a run is thrown
#: away so the disk does not fill with orphans — every one of these is
#: referenced only by the history and state files the reset has just emptied.
#:
#: `films/` and `tapes/` are NOT here. They are finished artifacts a player
#: asked for and may still want; a new run cannot splice onto them because the
#: reel is rebuilt from `tape_frames`, which the reset empties in state.
#: Extensions, not one glob: `reset_state` only ever deleted `*.png` and the
#: pipeline writes jpg on some provider paths, so half a run survived the wipe
#: that was supposed to clear it.
_REGENERABLE_FRAME_SUFFIXES = (".png", ".jpg", ".jpeg", ".webp")


def purge_run_media(session_id: str = "default") -> int:
    """Delete the frames of a run that is being thrown away. Returns the count.

    Orphan frames are not a correctness bug on their own — nothing points at
    them once history is empty. They became one through `_ensure_disk_headroom`,
    which sweeps regenerable files across sessions when space runs short and so
    turned "last night's frames are still on disk" into "this run's frames were
    deleted to make room for last night's".
    """
    removed = 0
    try:
        frames = list(_get_image_dir(session_id).iterdir())
    except Exception as e:
        logging.warning(f"[PURGE] could not list frames for {session_id}: {e}")
        return 0
    for stale in frames:
        if stale.suffix.lower() not in _REGENERABLE_FRAME_SUFFIXES:
            continue
        try:
            stale.unlink()
            removed += 1
        except Exception as e:
            logging.warning(f"[PURGE] could not delete {stale.name}: {e}")
    if removed:
        print(f"[PURGE] session={session_id} deleted {removed} orphaned frame(s)",
              flush=True)
    return removed


def _perform_game_reset(start_world_id: str = "", character_id: str = "") -> List[Dict[str, Any]]:
    global state, history, _last_image_path, _next_feed_item_id
    # Resolve THIS request's session id straight from Flask's request object
    # (see _resolve_request_session_id's docstring) rather than the shared
    # get_active_session_id() global, which a concurrent different-session
    # request can swap out from under us between _session_scoped's swap-in
    # and this line running. Previously this (and the _load_state()/
    # _save_state(state) calls below) defaulted to 'default' unconditionally,
    # so /api/reset for ANY session silently read + overwrote the 'default'
    # session's save file instead of the caller's own session — the
    # multi-user "New Game" flow never actually created an isolated instance.
    # Serialize the ENTIRE reset (state build, intro-turn LLM call, save)
    # against every OTHER session's turn/reset processing — see TURN_LOCK's
    # definition and _process_turn_background's matching wrapper. Without
    # this, a concurrent /api/choose or /api/reset for a DIFFERENT session
    # could interleave with generate_intro_turn_feed_items()'s calls into
    # the deep turn pipeline (which still touch the module-global `state`/
    # `history` mirrors internally) and corrupt either session's data.
    need_intro_spawn = True
    intro_image_kwargs = {}
    initial_items: List[Dict[str, Any]] = []
    with TURN_LOCK:
        SID = _resolve_request_session_id()
        logging.info(f"_perform_game_reset: ENTER session='{SID}'. Initial global state object id: {id(state)}")

        # Forget the last run BEFORE building the new one, not after. Everything
        # below this line renders, reads a frame and mints a tone gloss for the
        # new world, and each of those consults a cache — so a purge at the end
        # of the reset would arrive after the very frames it exists to protect.
        # See purge_run_caches for what was surviving and what it looked like.
        purge_run_caches(SID, reason="new run")
        purge_run_media(SID)

        # WHO THIS RUN IS (characters.py). Bound before anything below reads
        # the cast sheet — the intro beat, the montage, the look book all ask
        # game_identity who is on screen, and until the new state is saved the
        # file on disk still says who the LAST run was. A reset that names no
        # character (an older client, a harness) is the cast sheet, as before.
        _char = _bind_character_for_reset(SID, character_id)

        # Reset state variables by loading a fresh copy and then clearing/setting specifics
        current_state_at_reset_start = _load_state(SID) 
        logging.info(f"_perform_game_reset: After _load_state. Loaded state id: {id(current_state_at_reset_start)}. Its feed_log (len {len(current_state_at_reset_start.get('feed_log',[]))}) id: {id(current_state_at_reset_start.get('feed_log')) if current_state_at_reset_start.get('feed_log') is not None else 'None'}")
    
        # Bind the Experience graph first so a stitched start World is live
        # before world_brief() reads the prompt file.
        import experience_store
        _experience_seed = apply_experience_start({}, SID, world_id=start_world_id)

        # Generate random starting time/weather/mood for this session — AFTER
        # the bind, because the roll reads the level's palette off the live
        # prompt file, and before the bind that file still holds whichever
        # World was played last. The first run of a newly picked World rolled
        # its lighting against the previous World's palette: a traced run of
        # the cyberpunk sub-level opened with "weather: golden hour, rust, red
        # dust, chain-link steel", the Horizon desert's line, and that string
        # went into every render of the session as "Lighting:". It is the
        # "first run inherits the previous run" class of bug, one bind early.
        starting_time = _generate_random_starting_time()

        # Deliberately NOT drafting the identity sheets here. See
        # _ensure_level_sheet_is_filled: it used to run on this line, and an LLM
        # write over authoring data on the boot path is not a fix, it is a
        # second bug. A blank Level sheet is reported by
        # api._warn_if_the_world_is_hollow and filled by a human in the editor,
        # or explicitly by tools/draft_identity_sheets.py.
    
        # Explicitly create a new dictionary for the state to ensure no shared references for critical parts.
        # This is a LOCAL variable — NOT assigned to the ambient `state` global
        # yet — because generate_intro_turn_feed_items() below makes a slow
        # synchronous LLM call. If we reassigned the global here, a concurrent
        # /api/reset for a DIFFERENT session could swap it out (or itself get
        # clobbered) mid-call; see generate_intro_turn_feed_items's docstring.
        new_state = {
            # world_brief() folds the cast sheet into the run's world document.
            # This is the reset /api/reset (and therefore the editor's "Save &
            # Restart") actually goes through, and it used to seed the raw
            # world_initial_state — so restarting after authoring a character
            # and a level produced a run whose world state had never heard of
            # either. reset_state() has always done this; the two agreeing is
            # the difference between "the editor works" and "the editor works
            # from the admin page".
            "world_prompt": experience_store.with_lore(
                game_identity.world_brief(
                    PROMPTS.get("world_initial_state", "Default world starting point.")
                )
            ),
            "current_phase": "normal",
            "chaos_level": 0,
            "last_choice": "",
            "last_saved": datetime.now(timezone.utc).isoformat(),
            "seen_elements": [],
            "player_state": {"alive": True},
            # Turn 0 of a new run has not been scanned yet, and the stamp must not
            # be left matching turn_count or the last run's frame would ground the
            # new one's opening beat.
            "scene_objects": [],
            "scene_objects_turn": -1,
            # A new run starts a new tape. Without this the reel would splice
            # this playthrough onto the end of the last one.
            "tape_frames": [],
            "feed_log": [],  # Explicitly a new empty list
            "current_image_url": _experience_seed.get("current_image_url"),
            "choices": [],
            "choices_metadata": {},
            "turn_count": 0,
            "interim_index": 0,
            "in_combat": False,
            "threat_level": 0,
            # A new run is unseen. This was missing here, so detection had
            # nowhere to start.
            "detection": {"heat": 0, "level": DETECT_HIDDEN, "since_turn": 0},
            "time_of_day": starting_time,
            "experience_id": _experience_seed.get("experience_id") or "default",
            "experience_world_id": _experience_seed.get("experience_world_id") or "",
            "world_turn_count": 0,
            "pending_world_transition": False,
            "experience_cutscene_id": _experience_seed.get("experience_cutscene_id") or "",
            "pending_cutscene": _experience_seed.get("pending_cutscene"),
            # Add any other essential keys that should be present from a fresh state
        }
        logging.info(f"_perform_game_reset: New state object created. New state id: {id(new_state)}. Its feed_log (len {len(new_state['feed_log'])}) id: {id(new_state['feed_log'])}")

        _last_image_path = None

        # NOTE: Do NOT reset _next_feed_item_id here. Feed item ids must stay
        # monotonically increasing across resets — a connected client tracks the
        # last id it has seen (and dedups by id), so restarting the counter made
        # a fresh intro reuse low ids that the client had already rendered, which
        # got deduped away → "Reset does nothing". Keeping the counter monotonic
        # guarantees the new intro's items are always newer than anything seen.

        new_history: List[dict] = []
        hist_path_for_sid = _get_history_path(SID)
        if hist_path_for_sid.exists():
            try:
                hist_path_for_sid.write_text("[]", encoding='utf-8') # Clear history file
                logging.info("_perform_game_reset: history.json cleared.")
            except Exception as e_hist_clear:
                logging.error(f"_perform_game_reset: Error clearing history.json: {e_hist_clear}")
        else:
            logging.info("_perform_game_reset: history.json does not exist, no need to clear.")

        # THE TAPE (run_tape.py): the run that just ended is closed and a new
        # one starts recording. Its frames were hard-linked into its own
        # folder as they were shown, so the purge above did not take them.
        try:
            import run_tape
            run_tape.begin(SID, new_state)
        except Exception as _tape_err:
            log_error(f"[TAPE] could not start the tape: {_tape_err}")

        # How the level starts.
        #
        # On the montage path NOTHING is resolved or rendered here. The montage
        # is the run's first render and it happens on /api/cutscene/play, a
        # moment later, with the client already watching — so the reset returns
        # fast and the boot is two renders (montage, then the idle beat) instead
        # of the three it briefly became. Resolving a plate here is what used to
        # cost a whole extra image and let a from-scratch guess disagree with
        # the montage about where the level was.
        #
        # Off the montage path the old behaviour stands: resolve the World's
        # cached frame first, so the opening slate can be written from the
        # picture the run opens on rather than from the shot description, and
        # so Play / Watch paint immediately instead of sitting on black.
        if _open_on_montage(new_state):
            need_intro_spawn = False
            initial_items, intro_image_kwargs = generate_intro_turn_feed_items(
                SID, new_state, spawn_image=False)
            initial_items = _stage_opening_montage(SID, new_state, initial_items)
        else:
            # No montage to stage the goal through, but the run still needs
            # one: the consequence, slate, lead and encounter prompts all
            # read `level_goal` off the run now (see run_goal), and a run
            # that opened without a cinematic used to have none at all.
            try:
                _goal_for_this_run(new_state, "", SID)
            except Exception as _goal_err:
                log_error(f"[GOAL] no goal for this run: {_goal_err}")
            opening_slug, opening_rec = _cached_opening_frame(new_state)
            initial_items, intro_image_kwargs = generate_intro_turn_feed_items(
                SID, new_state, spawn_image=False,
                frame_path=opening_rec.get("path") or None)
            need_intro_spawn = _apply_cached_opening_frame(
                SID, new_state, initial_items, intro_image_kwargs,
                resolved=(opening_slug, opening_rec))
        logging.info(f"_perform_game_reset: initial_items from generate_intro_turn_feed_items (IDs): {[item['id'] for item in initial_items if item]}")

        if new_state.get("experience_cutscene_id"):
            # Opening is the montage — don't leave intro verbs under it.
            initial_items = [
                it for it in initial_items
                if (it or {}).get("type") != "player_choice_prompt"
            ]
            try:
                import experience_store
                exp = experience_store.get_experience()
                dest = experience_store.cutscene_by_id(
                    exp, new_state.get("experience_cutscene_id"))
            except Exception:
                dest = None
            initial_items.append(_cutscene_feed_item({
                "to": dest or {},
                "cutscene": new_state.get("pending_cutscene") or {},
                "from": {},
            }))
            if new_state.get("current_image_url") is None:
                seed_url = _experience_seed.get("current_image_url")
                if seed_url:
                    new_state["current_image_url"] = seed_url

        if _char:
            try:
                import characters as _characters
                _characters.bind_run(new_state, _char["id"])
                _characters.note_world(new_state, str(new_state.get("experience_world_id") or ""))
            except Exception as _char_err:
                log_error(f"[CHARACTERS] could not bind the run: {_char_err}")
        new_state['feed_log'].extend(initial_items) # Add to the new state's new feed_log
        logging.info(f"_perform_game_reset: state['feed_log'] before _save_state (IDs): {[item['id'] for item in new_state['feed_log'] if item]}")
    
        _save_state(new_state, SID) # Save the completely new state to THIS session's file
        # Mirror into the ambient globals only if SID is still the active
        # session (see _sync_ambient_state) — same reasoning applies to `history`.
        if get_active_session_id() == SID:
            state = new_state
            history = new_history
        logging.info(f"_perform_game_reset: Game reset complete. {len(initial_items)} initial items generated and saved.")
    # The run's look book (look_book.py): a new run gets a new roster and a
    # new cast. api_reset has already shot it (prepare_level_look_book) and
    # this claims that one; a caller that skipped the prepare starts one here.
    try:
        import look_book
        look_book.reset_for_new_run(SID)
    except Exception as _lb_err:
        log_error(f"[LOOK BOOK] could not start: {_lb_err}")
    # Spawn the intro render OUTSIDE the TURN_LOCK block and AFTER the save
    # above, so it can never be clobbered by that save and never holds the
    # global lock. Skip it when the cache is warm and clean — that render is
    # how this used to feel slow.
    if need_intro_spawn:
        _spawn_scene_image_async(**intro_image_kwargs)
        # There was no still to ground the opening slate on, so it came from the
        # shot description. Replace it with one read off the frame as soon as the
        # render lands — otherwise the very first thing the game asks the player
        # to do is the only decision in the run that never saw a picture.
        _intro_prompt = next(
            (it for it in initial_items
             if (it or {}).get("type") == "player_choice_prompt"), None)
        if _intro_prompt:
            _spawn_scene_choices_reground(
                _intro_prompt.get("id"),
                new_state.get("current_image_url"),
                SID,
            )
    return initial_items

def prepare_level_look_book(session_id: str, start_world_id: str = "",
                            wait: bool = False) -> dict:
    """Bind the World this run will start in and start its look book.

    The bind is the reset's own (apply_experience_start, on a throwaway
    state) so the book is shot for exactly the World the reset will load, and
    it is done under TURN_LOCK like the reset's. The wait, when asked for,
    happens OUTSIDE the lock: a minute of image calls must not stall every
    other session's turns.
    """
    try:
        import look_book
    except Exception as e:
        logging.warning(f"[LOOK BOOK] prepare skipped: {e}")
        return {}
    if not look_book.enabled():
        return {"enabled": False}
    with TURN_LOCK:
        apply_experience_start({}, session_id, world_id=start_world_id)
        try:
            import worlds_store
            bound = worlds_store.bound_slug()
        except Exception:
            bound = ""
    # A World with no bible or a placeholder name gets them drafted once, into
    # its own file, before its book is shot (world_gaps). Outside the lock:
    # it is a model call. The reset rebinds from the World file, so it plays
    # the same text the book was shot from.
    if bound:
        try:
            import world_gaps
            world_gaps.fill(bound, reason="new run")
        except Exception as e:
            logging.warning(f"[WORLD GAPS] skipped: {e}")
    with TURN_LOCK:
        look_book.prepare_for_level(session_id)
    if wait:
        look_book.wait_ready(session_id)
    return look_book.summary(session_id)


def _bind_character_for_reset(sid: str, character_id: str = "") -> Optional[dict]:
    """Point this session at a character for the run about to be built (in
    memory, at once — see characters.set_binding), or at nobody."""
    try:
        import characters
    except Exception:
        return None
    rec = None
    cid = str(character_id or "").strip()
    if cid:
        rec = characters.load(cid) if characters.valid_id(cid) else None
        if not rec or rec.get("status") != characters.STATUS_READY or not rec.get("current_look"):
            logging.warning(f"[CHARACTERS] reset asked for {cid!r}, which is not ready — "
                            "playing the cast sheet")
            rec = None
    characters.set_binding(sid, rec["id"] if rec else "", rec.get("current_look", "") if rec else "")
    return rec


def api_reset():
    # Resolve THIS request's session id straight from Flask's request object
    # (see _resolve_request_session_id's docstring) rather than reading the
    # ambient `state` global below — _perform_game_reset() already does the
    # same resolution internally and is now serialized system-wide via
    # TURN_LOCK, but the fallback/error paths here used to read/write the
    # shared `state` mirror directly (and `_save_state(state)` with no
    # session_id at all, which defaults to 'default'!), so a concurrent
    # different-session reset could make this handler report or persist the
    # WRONG session's data.
    SID = _resolve_request_session_id()
    logging.info(f"api_reset: POST request received for session='{SID}'.")
    try:
        # The editor's GENERATE restarts the run in the World it drew.
        start_world_id = ""
        character_id = ""
        try:
            body = request.get_json(silent=True) or {}
            start_world_id = str(body.get("world_id") or "").strip()
            character_id = str(body.get("character_id") or "").strip()
        except Exception:
            start_world_id = ""
        # Bound before the look book is prepared: its roster is designed to
        # look unlike the protagonist, and that is this run's character.
        if character_id:
            _bind_character_for_reset(SID, character_id)
        # The level starts with its look book finished. The client prepares and
        # waits for it before calling here (/api/look_book/prepare), so this is
        # normally instant; it is the guarantee for any other caller.
        prepare_level_look_book(SID, start_world_id, wait=True)
        initial_items = _perform_game_reset(start_world_id, character_id=character_id)
        if not initial_items:
            logging.warning("api_reset: _perform_game_reset returned no items, but this might be okay if feed_log is now populated by it.")
            # Fallback to checking THIS session's on-disk feed_log if initial_items is empty from return
            initial_items = _load_state(SID).get('feed_log', [])

        # Fallback: If still no player_choice_prompt, add a default
        has_choice_prompt = any(item.get('type') == 'player_choice_prompt' for item in initial_items)
        has_opening_cutscene = any(item.get('type') == 'cutscene' for item in initial_items)
        if not has_choice_prompt and not has_opening_cutscene:
            logging.error("api_reset: No player_choice_prompt found in initial_items. Adding fallback.")
            # The id MUST come from the shared counter, and the item MUST be
            # appended to the session's feed_log like every other beat.
            #
            # This used to be a literal id of 999999 that was never persisted.
            # The client tracks the highest id it has seen and then polls
            # `/api/feed?since_id=<that>`, so one appearance of this fallback
            # pinned the client at since_id=999999 for the life of the page:
            # every real item (ids in the tens) was filtered out server-side,
            # the feed went permanently silent, and every turn afterwards died
            # on the watchdog. A recovery path must not be able to brick the
            # session it is recovering.
            fallback_item = create_feed_item(
                type="player_choice_prompt",
                content="The system is online. Your journey begins now. What is your first action?",
                choices=[
                    {"text": "Look around", "action_id": "look_around"},
                    {"text": "Move forward", "action_id": "move_forward"},
                    {"text": "Wait", "action_id": "wait"},
                ],
            )
            with WORLD_STATE_LOCK:
                st = _load_state(SID)
                _feed_append(st, fallback_item)
                _save_state(st, SID)
                _sync_ambient_state(st, SID)
            initial_items.append(fallback_item)
        logging.info(f"api_reset: Returning {len(initial_items)} items. First item ID (if any): {initial_items[0]['id'] if initial_items else 'N/A'}")
        return jsonify(initial_items)
    except Exception as e:
        log_error(f"Critical error in api_reset: {e}")
        logging.exception("Exception in api_reset:")
        # In case of an error, ensure a valid JSON response is sent.
        # _perform_game_reset might have partially modified state, or failed before creating items.
        error_feed_item = create_feed_item(type="error_event", content=f"Failed to reset game: {str(e)}")
        # Attempt to log this error to THIS session's on-disk feed_log.
        try:
            with WORLD_STATE_LOCK:
                err_state = _load_state(SID)
                err_state.setdefault('feed_log', []).append(error_feed_item)
                _save_state(err_state, SID)
                _sync_ambient_state(err_state, SID)
        except Exception as e_log:
            log_error(f"Could not save error item to feed_log during api_reset error handling: {e_log}")
        return jsonify([error_feed_item]), 500


def api_revive():
    """Bring a dead player back to life on the CURRENT run.

    Intended to be called by the coin-op layer AFTER a payment has been
    verified server-side (see coinop.verify_and_redeem). This endpoint is
    itself agnostic to payment — it simply flips the death state, eases the
    heat, and appends a short narrative beat + a fresh choice prompt so the
    player can keep going.

    Idempotent: calling api_revive on an already-alive player is a no-op
    that returns the (empty) list of newly appended items, so a duplicate
    return-URL redemption cannot double-revive or corrupt state.
    """
    SID = _resolve_request_session_id()
    appended: List[Dict[str, Any]] = []
    try:
        with WORLD_STATE_LOCK:
            st = _load_state(SID)
            ps = st.get("player_state") or {}
            # NOTE: no "already alive → no-op" guard here. In realtime
            # sessions the client's peripheral-vignette DangerSystem can
            # kill the player CLIENT-side (see standalone.js DangerSystem.
            # die() and its enterGameOver call) before the server's Phase-1
            # verdict has flipped alive→False. If we no-op'd on
            # alive==True, a legitimately-paid coin-op continue in that
            # window would silently do nothing and the death overlay would
            # never dismiss. Idempotency for double-charges lives one
            # layer up in coinop.verify_and_redeem's redeemed-set — this
            # function trusts its caller.
            ps["alive"] = True
            # A continue buys a moment of not being hunted. Coming back still
            # cornered spends the coin before the player touches anything, and
            # since detection is now the thing that gets you killed, this is
            # what a continue actually purchases.
            det = get_detection(st)
            if det["level"] > DETECT_SUSPICIOUS:
                det["heat"] = DETECT_THRESHOLDS[DETECT_SUSPICIOUS]
                det["level"] = DETECT_SUSPICIOUS
                st["detection"] = det
                st["in_combat"] = False
            ps["revived"] = True
            ps["revive_count"] = int(ps.get("revive_count", 0)) + 1
            st["player_state"] = ps

            # Bookkeeping so downstream logic (e.g. tape / analytics) can
            # tell a run apart from one that was never dead.
            revives = int(st.get("continues_used", 0)) + 1
            st["continues_used"] = revives

            # Narrative beat: a short, arcade-native line. Kept intentionally
            # separate from the standard 'narrative_event' so the client can
            # style it (CRT flicker, coin-drop cue) if it wants to. Falls
            # back to 'narrative_event' rendering in older clients.
            revive_item = create_feed_item(
                type="continue_used",
                content=(
                    "\U0001FA99 A coin drops. The transmission stutters back to life. "
                    "You are on your feet, breathing hard. Keep moving."
                ),
            )
            _feed_append(st, revive_item)
            appended.append(revive_item)

            # Give the player something to do next. We use a set of
            # deliberately safe, universally applicable choices so the
            # revive never lands the player in a broken decision point; the
            # next real turn will regenerate choices from vision as normal.
            prompt_item = _structure_choices_for_feed(
                [
                    "Look around carefully.",
                    "Move forward, cautiously.",
                    "Get your bearings.",
                    "Wait a moment and listen.",
                ],
                "What do you do next?",
                image_url=st.get("current_image_url"),
            )
            _feed_append(st, prompt_item)
            appended.append(prompt_item)

            _save_state(st, SID)
            _sync_ambient_state(st, SID)

        logging.info(f"api_revive: revived session='{SID}' (revive_count={ps.get('revive_count')})")
        return jsonify(appended)
    except Exception as e:  # noqa: BLE001
        log_error(f"api_revive: error reviving session='{SID}': {e}")
        logging.exception("Exception in api_revive:")
        err = create_feed_item(
            type="error_event",
            content=f"Continue failed: {e}. The run remains ended.",
        )
        try:
            with WORLD_STATE_LOCK:
                st = _load_state(SID)
                _feed_append(st, err)
                _save_state(st, SID)
        except Exception:
            pass
        return jsonify([err]), 500


def api_feed():
    # Resolve straight from Flask's (thread-local) request object rather than
    # reading the ambient `state` global directly. `/api/feed` is polled
    # continuously by every connected browser, so with multiple sessions live
    # at once this handler runs concurrently across many threads — reading
    # the shared `state` mirror here raced with OTHER sessions' concurrent
    # session_context() swaps (a poll for session A could land squarely on
    # top of session B's swap-in and read B's feed_log instead of A's).
    # Loading directly from THIS session's disk file every poll costs one
    # small JSON read and closes that race entirely.
    session_id = _resolve_request_session_id()
    since_id_str = request.args.get('since_id')
    items_to_return = []
    with WORLD_STATE_LOCK: # Ensure thread-safe access to the on-disk feed_log
        st = _load_state(session_id)
        feed_log = st.get('feed_log', [])
        if since_id_str:
            try:
                since_id = int(since_id_str)
                items_to_return = [item for item in feed_log if item.get('id', 0) > since_id]
            except ValueError:
                log_error(f"/api/feed: Invalid since_id '{since_id_str}'. Returning full feed.")
                items_to_return = list(feed_log) # Return a copy
        else:
            items_to_return = list(feed_log) # Return a copy of the full feed log
    return jsonify(items_to_return)

_THREAD_SIGNAL_TTL_S = 300

# One scene-image lock per session (see _generate_and_append_scene_image). Keyed
# by session so two players never wait on each other's render; re-entrant
# because the render path can recurse through fallback helpers.
_SESSION_IMAGE_LOCKS: Dict[str, threading.RLock] = {}
_SESSION_IMAGE_LOCKS_GUARD = threading.Lock()

# …but not UNBOUNDED across sessions. Production is a 0.5-CPU / 512MB box, and a
# render decodes and writes a multi-megabyte still; letting every session render
# at once trades one stall (everyone queued behind a global lock) for a worse
# one (the box thrashing). Two at a time keeps players off each other's critical
# path without swamping the instance. Raise via WORLD_IMAGE_CONCURRENCY on
# bigger hardware.
try:
    _IMAGE_CONCURRENCY = max(1, int(os.getenv("WORLD_IMAGE_CONCURRENCY", "2")))
except ValueError:
    _IMAGE_CONCURRENCY = 2
_IMAGE_SLOTS = threading.BoundedSemaphore(_IMAGE_CONCURRENCY)


def _session_image_lock(session_id: str) -> threading.RLock:
    with _SESSION_IMAGE_LOCKS_GUARD:
        lock = _SESSION_IMAGE_LOCKS.get(session_id)
        if lock is None:
            lock = threading.RLock()
            _SESSION_IMAGE_LOCKS[session_id] = lock
        return lock


def _sweep_thread_signals() -> None:
    """Delete stale thread_signal_*.tmp scratch files from ROOT.

    Nothing waits on these anymore (see api_choose), so a worker's marker is
    just litter once its turn is over. Cheap: one small glob per turn, and only
    files older than the TTL are removed, so a marker for a turn still running
    is never touched. Best-effort — this must never fail a turn.
    """
    try:
        cutoff = time.time() - _THREAD_SIGNAL_TTL_S
        for p in DATA.glob("thread_signal_*.tmp"):
            try:
                if p.stat().st_mtime < cutoff:
                    p.unlink()
            except OSError:
                pass
    except Exception:
        pass


def api_choose():
    global state
    try:
        data = request.get_json()
        if not data or 'choice' not in data:
            return jsonify({"error": "Missing 'choice' in request body"}), 400
        
        player_choice_text = data['choice']
        context_item_id = data.get('context_item_id') # Optional, for context
        # Session id for THIS request, resolved straight from Flask's request
        # object (see _resolve_request_session_id's docstring for why this
        # must NOT be get_active_session_id() — that shared global can be
        # swapped by a concurrent, different-session request between when
        # _session_scoped entered session_context() and this line running).
        # Previously this defaulted to 'default' and was never actually used
        # below — every /api/choose call silently operated on the 'default'
        # session's saved state regardless of which session the caller
        # asked for. Using it here (and threading it into the background
        # thread below) is what makes each session's turns land in ITS OWN
        # save file instead of everyone's turns landing in 'default'.
        session_id = _resolve_request_session_id()
        with WORLD_STATE_LOCK:
            _cut_st = _load_state(session_id) or {}
            if str(_cut_st.get("experience_cutscene_id") or "").strip():
                return jsonify({"ok": False, "error": "cutscene_playing"}), 409
            # Re-entrancy guard — see _process_turn_background_guarded's
            # docstring for the double-submit bug this closes. Check-and-set
            # in the same lock hold as the cutscene check above so two
            # concurrent /api/choose calls can't both read "not processing"
            # before either writes "processing".
            #
            # The flag is only cleared at the far end of the background thread,
            # which does not finish until the scene image is rendered (up to
            # 75s). But the client hands input back the moment the CHOICES are
            # live (~27s), by design. So a flat "is it set?" refused the
            # player's next real action for the whole image tail and surfaced as
            # "The world hesitated. Choose again." Only a genuine double-submit
            # — a double-click, a client retry — is near-simultaneous, so scope
            # the refusal to a short window instead of the entire turn.
            _now = time.time()
            _started = float(_cut_st.get("turn_processing_at") or 0)
            if _cut_st.get("turn_processing") and (_now - _started) < DOUBLE_SUBMIT_WINDOW_S:
                return jsonify({"error": "turn_in_progress"}), 409
            _cut_st["turn_processing"] = True
            _cut_st["turn_processing_at"] = _now
            _save_state(_cut_st, session_id)
            _sync_ambient_state(_cut_st, session_id)
        # How the action was issued. SCAN object interactions ("scan_interact"/
        # "scan_move") drive the story-escalation backend harder (see
        # _process_turn_background) so poking the world moves the plot + raises risk.
        action_source = data.get('source')
        # The detection label the player actually tapped. It rides along so the
        # consequence can be REQUIRED to keep that object in frame — see the
        # OBJECT PERMANENCE block. Only SCAN taps carry one; a typed or generated
        # choice has no identified subject and pins nothing.
        action_subject = _permanence_subject(data.get('subject'))
        # INTERACT opened a dive, so a close-up of this subject is being
        # generated right now on another request thread. Arm the handoff before
        # the turn thread starts, so the scene render holds for that close-up
        # and carries it as a reference instead of re-imagining the character
        # from a wide frame (see _arm_interact_plate).
        #
        # The client has to say so rather than the server assuming it from the
        # verb: a dive only opens when the Moments chrome is there, and the
        # playtest harnesses post `scan_interact` with no client at all.
        if action_source == "scan_interact" and data.get('awaiting_closeup'):
            try:
                _arm_interact_plate(session_id, action_subject)
            except Exception as e_plate:
                log_error(f"api_choose: could not arm the interact plate: {e_plate}")
        # Encounter Moment: the feed shows the short verb; the turn LLM gets
        # the character + danger briefing so the aftermath is about THIS interrupt.
        turn_choice_text = player_choice_text
        if action_source == "encounter":
            try:
                import encounter as _encounter
                _enc_st = _load_state(session_id) or {}
                enc = _enc_st.get("encounter")
                rec = _enc_st.get("encounter_outcome") if isinstance(_enc_st.get("encounter_outcome"), dict) else {}
                if isinstance(enc, dict):
                    turn_choice_text = _encounter.encounter_action_for_turn(
                        player_choice_text, enc,
                        lane=rec.get("lane"),
                        outcome=rec.get("outcome"),
                    )
                    if not action_subject:
                        action_subject = _permanence_subject(
                            (enc.get("character") or {}).get("label"))
            except Exception as e_enc:
                log_error(f"api_choose: encounter enrich failed: {e_enc}")
        # TALK: the conversation that just ended IS this turn's action.
        #
        # Everything the two of them actually said rides along on the choose,
        # rather than being posted separately to /api/talk/end — that call is a
        # sendBeacon and would race the turn it is supposed to inform. Stored
        # on state stamped with the turn it belongs to, so the consequence
        # prompt can pick it up (see _conversation_for_turn) without another
        # argument threaded through four layers of the pipeline.
        if action_source == "talk":
            try:
                _record_turn_conversation(session_id, action_subject,
                                          data.get("conversation"))
            except Exception as e_conv:
                log_error(f"api_choose: could not record the conversation: {e_conv}")

        # LEAVE CAMP must arrive on foot — never in a cab/dashboard POV.
        player_choice_text = _normalize_camp_leave_choice(player_choice_text, action_source)

        if DEBUG_MODE: print(f"[DEBUG] api_choose received choice: '{player_choice_text}', context_id: {context_item_id}. Current state ID: {id(state)}", flush=True)

        # ACT-TIME FRAME CAPTURE: if the client sent the frame the player was
        # actually looking at in the live world model, ingest it BEFORE the turn
        # spawns. It becomes the latest history entry's img2img reference (the
        # realtime state we're interacting with), while the original high-fidelity
        # guide still is preserved as a secondary quality anchor. Must run before
        # the background thread appends this turn's new history entry, so it lands
        # on the CURRENT scene (history[-1]). Best-effort: a bad frame is ignored.
        act_frame_b64 = data.get('act_frame')
        if act_frame_b64:
            try:
                if _ingest_realtime_frame(act_frame_b64, session_id):
                    if DEBUG_MODE: print(f"[DEBUG] api_choose ingested act-time world-model frame for img2img.", flush=True)
            except Exception as e_frame:
                log_error(f"api_choose: failed to ingest act frame: {e_frame}")

        # A specimen armed from the investigations tray. The client used to send
        # only `investigation_id`, which was meaningless here — the capture lives
        # in the browser and was never uploaded — so selecting a photo and acting
        # on it grounded nothing. The crop itself arrives now and becomes this
        # turn's img2img reference, so "describe your action" is answered by a
        # frame that actually contains the thing being described. Ingested AFTER
        # act_frame so an explicitly chosen specimen outranks the ambient frame.
        investigation_frame = data.get('investigation_frame')
        if investigation_frame:
            try:
                if _ingest_realtime_frame(investigation_frame, session_id):
                    print(f"[INVESTIGATION] grounded the turn on specimen "
                          f"{data.get('investigation_id') or '(unnamed)'}", flush=True)
            except Exception as e_inv:
                log_error(f"api_choose: failed to ingest investigation frame: {e_inv}")

        # 1. Immediately create and log the Player Action
        player_action_item = create_feed_item(
            type="player_action", 
            content=f"{player_choice_text}", # Display the choice text directly
            metadata={"raw_choice": player_choice_text, "context_id": context_item_id}
        )
        # Atomic read-modify-write: reload the freshest state INSIDE the lock
        # before appending, so a concurrent writer (the realtime /api/observe
        # fast-path, scene-image thread, or a reground worker) can't have its
        # save clobbered — and ours can't be clobbered by a stale snapshot.
        with WORLD_STATE_LOCK:
            st = _load_state(session_id)
            _feed_append(st, player_action_item)
            st['last_choice'] = player_choice_text
            # Fresh drift budget for the decision point this turn opens (see
            # world_drift_tick). The beats themselves are NOT cleared here —
            # they're what the world-evolution pass folds into the world state.
            st['drift_count'] = 0
            _save_state(st, session_id)
            # Guarded mirror update (see _sync_ambient_state's docstring): a
            # blind `state = st` here raced with OTHER sessions' concurrent
            # /api/choose calls — this request thread's `st` could overwrite
            # the ambient mirror right before a DIFFERENT session's request
            # exits session_context() and (seeing its own session still
            # "active") persists that stale mirror over ITS OWN save file.
            # That was a real, reproducible cross-session leak under
            # concurrent load; _sync_ambient_state's active-session check
            # closes it.
            _sync_ambient_state(st, session_id)
        if DEBUG_MODE: print(f"[DEBUG] api_choose - Player action item ID {player_action_item['id']} logged. Starting background thread for _process_turn_background.", flush=True)

        # 2. Start background processing for the rest of the turn
        # Pass the ID of the player_action_item so the background thread can link its logs if needed.
        
        # The turn runs on a DAEMON thread and we do not wait on it.
        #
        # This used to spawn a non-daemon thread, then sleep 200ms on the
        # request thread polling for a scratch file the worker writes, purely to
        # print a debug line. Three costs, all real in production (one gunicorn
        # worker, a handful of threads): 200ms added to every single turn while
        # holding a serving thread; a non-daemon thread per turn, so a graceful
        # restart blocked on every in-flight LLM+image pipeline; and, whenever
        # scheduling pushed the worker's write past the 200ms window, an
        # orphaned thread_signal_*.tmp left in ROOT forever.
        #
        # The signal file is still passed (the worker writes it and it is useful
        # under DEBUG_MODE), but nothing blocks on it and it's swept, not leaked.
        temp_signal_file = DATA / f"thread_signal_{player_action_item['id']}.tmp"

        try:
            thread = threading.Thread(
                target=_process_turn_background_guarded,
                args=(turn_choice_text, player_action_item['id'], str(temp_signal_file)),
                kwargs={"source": action_source, "session_id": session_id,
                        "subject": action_subject},
                daemon=True,
            )
            thread.start()
            _sweep_thread_signals()

        except Exception as e_thread_start:
            print(f"CRITICAL DEBUG PRINT: api_choose - ERROR STARTING THREAD: {e_thread_start}", flush=True)
            # The thread never started, so _process_turn_background_guarded's
            # finally never runs — release the guard here or the session
            # would be stuck refusing every /api/choose with turn_in_progress.
            _clear_turn_processing(session_id)
            # Optionally re-raise or handle specifically if needed, for now just printing
            raise # Re-raise to see if it gets caught by the broader handler or stops the test

        # 3. Return only the player_action_item immediately to the client
        if DEBUG_MODE: print(f"[DEBUG] api_choose - Returning player_action_item (ID: {player_action_item['id']}) to client immediately.", flush=True)
        return jsonify([player_action_item])

    except Exception as e:
        log_error(f"Error in api_choose: {e}")
        logging.exception("Exception in api_choose:")
        # Create a generic error item to return
        error_item = create_feed_item(type="error_event", content=f"Server error processing choice: {str(e)}")
        # Attempt to log this error to the feed_log if state is available
        try:
            with WORLD_STATE_LOCK:
                err_session_id = _resolve_request_session_id()
                err_state = _load_state(err_session_id)
                err_state.setdefault('feed_log', []).append(error_item)
                # If this exception happened after the turn_processing guard
                # was set but before the background thread started (which is
                # the only thing that clears it), clear it here too — else
                # every /api/choose for this session refuses with
                # turn_in_progress forever after one failure this early.
                err_state["turn_processing"] = False
                _save_state(err_state, err_session_id)
                _sync_ambient_state(err_state, err_session_id)
        except Exception as e_log:
            log_error(f"Could not save error item to feed_log during api_choose error handling: {e_log}")
        return jsonify([error_item]), 500


def _prune_observed_frames(img_dir, keep: int = 12):
    """Cap the number of transient realtime-capture frames on disk.

    Every realtime turn writes one or more `observed_*.png` scratch frames
    (act-time capture in /api/choose + the post-choice perception frame in
    /api/observe). These are ONLY ever used as an img2img reference for the
    immediately-following turn (reference collection in _gen_image reaches back
    at most ~2 history entries), yet nothing pruned them mid-session — they only
    got wiped on /api/reset. On the now-persistent 1GB disk (see
    RENDER_STORAGE_LIMITATION.md) they pile up across a play session until the
    disk fills, at which point new image writes start failing and the scene can
    no longer render a fresh frame — i.e. "I can only play for a short time".

    Keep the most-recent `keep` frames (generous margin over the ~2-turn
    reference window) and delete the rest. Best-effort: any failure is ignored
    so this can never break a turn.
    """
    try:
        from pathlib import Path as _P
        d = _P(img_dir)
        if not d.exists():
            return
        frames = sorted(
            list(d.glob("observed_*.png")) + list(d.glob("observed_*.jpg")),
            key=lambda p: p.stat().st_mtime,
        )
        excess = len(frames) - max(0, int(keep))
        for old in frames[:excess]:
            try:
                old.unlink()
            except Exception:
                pass
    except Exception as _e:
        log_error(f"_prune_observed_frames failed: {_e}")


# ── Persistent-disk headroom management ────────────────────────────────────
# The sessions/ tree lives on a bounded persistent disk on Render (1GB by
# default — see RENDER_STORAGE_LIMITATION.md / render.yaml). Per-session pruning
# (_prune_observed_frames) bounds ONE session's scratch frames, but across many
# sessions + generated stills + tapes/films the disk can still fill up, and once
# it's full EVERY image/state write fails (the scene can't render, saves are
# lost). When we detect the disk is low, sweep stale/regenerable data across ALL
# sessions — oldest first — until a healthy margin is restored.
_DISK_MIN_FREE_FRACTION = 0.12          # keep ≥12% of the disk free
_DISK_MIN_FREE_BYTES = 150 * 1024 * 1024  # …and never below a 150MB floor
_DISK_SWEEP_MIN_INTERVAL_S = 20         # throttle the (FS-walking) sweep
_DISK_KEEP_IMAGES_PER_SESSION = 12      # protect the newest N images/session
_last_disk_sweep_ts = 0.0
_disk_sweep_lock = threading.Lock()


def _disk_free_status(path):
    """Return (ok, usage, need_bytes). ok=True when free space is healthy.
    On any error, reports ok=True so disk checks can never break a turn."""
    import shutil as _sh
    try:
        usage = _sh.disk_usage(str(path))
        need = max(_DISK_MIN_FREE_BYTES, int(usage.total * _DISK_MIN_FREE_FRACTION))
        return (usage.free >= need, usage, need)
    except Exception:
        return (True, None, 0)


def _ensure_disk_headroom(force: bool = False):
    """Free space on the persistent sessions disk when it's running low.

    Deletes stale, REGENERABLE data across every session, oldest-first, until a
    healthy free-space margin is recovered. Deliberately conservative about what
    it will remove:

      • NEVER deletes session state — state.json / history.json / meta.json — or
        the analytics ledger (anything under sessions/_analytics, or any *.db).
      • PROTECTS the newest _DISK_KEEP_IMAGES_PER_SESSION images in each
        session so img2img continuity and the on-screen scene survive.
      • Everything else under sessions/ (old stills, observed_*/photo/
        investigation scratch frames, _small downsamples, tapes, films/videos)
        is fair game, removed oldest-first.

    Throttled (won't walk the tree more than once per _DISK_SWEEP_MIN_INTERVAL_S)
    and fully best-effort: any failure is swallowed so it can never break a turn.
    """
    global _last_disk_sweep_ts
    sessions_root = DATA / "sessions"
    ok, usage, need = _disk_free_status(sessions_root)
    if ok and not force:
        return
    if not _disk_sweep_lock.acquire(blocking=False):
        return  # another thread is already sweeping
    try:
        # Re-check under the lock — the other waiter may have already freed space.
        ok, usage, need = _disk_free_status(sessions_root)
        if usage is None:
            return
        now = time.time()
        if ok and not force:
            return
        if not force and (now - _last_disk_sweep_ts) < _DISK_SWEEP_MIN_INTERVAL_S:
            return
        _last_disk_sweep_ts = now
        if not sessions_root.exists():
            return

        # Protect the newest N images per session (continuity + current scene).
        protected = set()
        try:
            for sess_dir in sessions_root.iterdir():
                if not sess_dir.is_dir() or sess_dir.name == "_analytics":
                    continue
                img_dir = sess_dir / "images"
                if not img_dir.exists():
                    continue
                imgs = sorted(
                    (p for p in img_dir.glob("*") if p.is_file()),
                    key=lambda p: p.stat().st_mtime, reverse=True,
                )
                for p in imgs[:_DISK_KEEP_IMAGES_PER_SESSION]:
                    try:
                        protected.add(p.resolve())
                    except Exception:
                        pass
        except Exception:
            pass

        def _is_protected(p):
            try:
                if p.resolve() in protected:
                    return True
            except Exception:
                pass
            if p.name in ("state.json", "history.json", "meta.json"):
                return True
            if p.suffix == ".db" or "_analytics" in p.parts:
                return True
            # Companion portraits are a persistent roster (see _record_companion)
            # meant to be reused across scenes for a continuing story — never
            # sweep them. Prop images (e.g. prop_jeep.png) are the same idea
            # for durable objects (see _record_prop).
            if p.name.startswith("companion_") or p.name.startswith("prop_"):
                return True
            # The run's look book (look_book.py) is written once at the start
            # of a run, which makes every file in it the OLDEST thing in the
            # session — first in line for an oldest-first sweep. On a tight
            # disk the sweep deleted book.json mid-run and the book rebuilt
            # itself twice in five turns; the plates vanished under the fight
            # that was drawing from them.
            if "look_book" in p.parts:
                return True
            return False

        # How much to free (with a little extra so we don't immediately re-trip).
        to_free = int(max(0, need - usage.free) * 1.25)

        candidates = []
        for p in sessions_root.rglob("*"):
            try:
                if not p.is_file() or _is_protected(p):
                    continue
                candidates.append((p.stat().st_mtime, p.stat().st_size, p))
            except Exception:
                continue
        candidates.sort(key=lambda t: t[0])  # oldest first

        freed = 0
        deleted = 0
        for _mtime, size, p in candidates:
            if freed >= to_free:
                break
            try:
                p.unlink()
                freed += size
                deleted += 1
            except Exception:
                continue
        if deleted:
            print(f"[DISK] headroom sweep freed ~{freed // (1024 * 1024)}MB "
                  f"({deleted} stale files) to keep the sessions disk under "
                  f"{int((1 - _DISK_MIN_FREE_FRACTION) * 100)}% full", flush=True)
    except Exception as _e:
        log_error(f"_ensure_disk_headroom failed: {_e}")
    finally:
        try:
            _disk_sweep_lock.release()
        except Exception:
            pass


def _ingest_realtime_frame(frame_b64: str, session_id: str = 'default'):
    """Ingest a frame captured from the live world-model video.

    Decodes the base64 frame, saves it, and makes it the current scene image +
    the latest history entry's img2img reference — so the NEXT turn's img2img
    evolves from what the world model actually rendered (the realtime state the
    player is interacting with) instead of a stale guide still.

    Crucially, the ORIGINAL high-fidelity guide still is preserved on the history
    entry under 'guide_image' (set once, never clobbered). That lets _gen_image
    pass BOTH references to img2img: the live frame for spatial/state continuity,
    and the guide still for image quality.

    Shared by /api/choose (act-time capture) and /api/observe (post-choice
    perception loop). Returns (fpath, web_url) or None on a bad/too-small frame.
    """
    import base64 as _b64, re as _re, time as _time
    from pathlib import Path as _Path
    global state, history
    if not frame_b64:
        return None
    m = _re.match(r'^data:image/[^;]+;base64,(.*)$', frame_b64, _re.DOTALL)
    raw = m.group(1) if m else frame_b64
    try:
        img_bytes = _b64.b64decode(raw)
    except Exception:
        return None
    if len(img_bytes) < 512:
        return None

    img_dir = _Path(_get_image_dir(session_id))
    img_dir.mkdir(parents=True, exist_ok=True)
    fname = f"observed_{int(_time.time() * 1000)}.jpg"
    fpath = img_dir / fname
    fpath.write_bytes(img_bytes)
    web = _to_web_image_url(fname, session_id)

    # Bound the transient-frame footprint so a long session can't fill the disk
    # (which would make every subsequent image write fail — see the helper's
    # docstring). Runs AFTER writing this frame so the newest one is retained.
    _prune_observed_frames(img_dir)
    # And, if the shared persistent disk is genuinely low (many sessions / stale
    # tapes+films), sweep old regenerable data across ALL sessions. Throttled and
    # a no-op while there's healthy headroom, so this is cheap on the hot path.
    _ensure_disk_headroom()

    with WORLD_STATE_LOCK:
        st = _load_state(session_id)
        st['current_image_url'] = web
        hist = _load_history(session_id)
        if hist:
            # Preserve the original high-fidelity guide still ONCE, before we
            # point 'image' at the live frame, so it survives as a secondary
            # img2img quality reference (see _gen_image dual-reference logic).
            if not hist[-1].get('guide_image') and hist[-1].get('image'):
                hist[-1]['guide_image'] = hist[-1]['image']
            hist[-1]['image'] = str(fpath)
            hist[-1]['image_url'] = str(fpath)
            hist[-1]['live_capture'] = True
            _save_history(hist, session_id)
            if get_active_session_id() == session_id:
                history = hist
        _save_state(st, session_id)
        _sync_ambient_state(st, session_id)

    return (str(fpath), web)


def api_observe():
    """Vision for the realtime renderer — close the perception loop.

    The player watches the Helios video, which drifts from the Gemini still the
    simulation is grounded on, so narrative/choices stop matching the screen.
    This accepts the ACTUAL frame currently on screen (captured client-side from
    the video) and feeds it back into the simulation:

      • saves it as the current scene image and overwrites the latest history
        frame + its vision, so the NEXT turn's consequence, img2img reference,
        and narrative track what the player actually saw (anti-drift);
      • regenerates the current choices from what's literally visible in the
        video and returns them for the client to swap in place.

    Loop: video -> vision -> simulation -> prompt (+seed) -> video.
    """
    global state, history
    try:
        data = request.get_json(silent=True) or {}
        frame_b64 = data.get('frame')
        session_id = data.get('session_id', 'default')
        prompt_id = data.get('prompt_id')
        if not frame_b64:
            return jsonify({"error": "missing frame"}), 400
        # FAST PATH (no LLM on the request): make the actual video frame the
        # current scene image + the latest history reference (preserving the
        # original guide still as a secondary quality ref), so the NEXT turn's
        # img2img composition follows the video. Returns immediately.
        ingested = _ingest_realtime_frame(frame_b64, session_id)
        if not ingested:
            return jsonify({"error": "bad frame"}), 400
        fpath, web = ingested

        # SLOW PATH (off the request thread): analyze what's actually on screen
        # and regenerate the live choices to match. Bounded so it can never hang
        # the app; delivers revised choices via a 'choices_revised' feed item.
        _spawn_observe_reground(str(fpath), web, session_id, prompt_id)

        return jsonify({"ok": True, "image_url": web})
    except Exception as e:
        import traceback as _tb
        log_error(f"[OBSERVE] failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e)}), 500


def api_detect():
    """Realtime object recognition for the SCAN tool.

    Accepts the frame currently on screen (a JPEG data URL captured client-side
    from the live world-model video) and returns the prominent, interactable
    things visible in it plus WHERE they are, so the standalone UI can float
    "starfield" tags over the live scene where each object actually sits — and
    let the player poke any of them.

    Request JSON:  {"frame": "data:image/jpeg;base64,...", "purpose": "scan"?}
    Response JSON: {"objects": [{"label", "cx", "cy", "w", "h", "kind", "speaks"}, ...],
                    "anti_loop_suppressed": bool,
                    "encounter_with"?: {"label", "kind", "cx", "cy", "w", "h",
                                        "distance", "figures", "source": "sighting"}}
    Coordinates are normalized 0..1 (cx/cy = box center, w/h = box size).
    `encounter_with` is present when a `purpose: "scan"` pass found a person
    (or creature) and nothing stopped a sighting from opening on them — see
    _stage_encounter_sighting; the client hands it to Encounter.start().

    Read-only w.r.t. history and choices: unlike /api/observe this never touches
    the turn record. The ONE thing it writes is `purpose: "scan"`-gated — the
    labels are cached on state so the next consequence call knows what is in
    frame (see record_scene_objects). That gate matters: photo targeting polls
    this same endpoint every ~2.5 s while the camera is armed, and a locked
    state read+write at that cadence would contend with the turn loop for no
    benefit. A deliberate SCAN tap is one pass, and it is the act already wired
    to scan_interact / scan_move, so it is the only caller that opts in.
    """
    import base64 as _b64, re as _re
    try:
        data = request.get_json(silent=True) or {}
        frame_b64 = data.get('frame')
        session_id = data.get('session_id', 'default')
        if not frame_b64:
            return jsonify({"error": "missing frame"}), 400
        # Pull the MIME type off the data URL so we can pass it straight to
        # Gemini without any guesswork or filename-based inference.
        mime_match = _re.match(r'^data:(image/[^;]+);base64,(.*)$', frame_b64, _re.DOTALL)
        if mime_match:
            mime_type = mime_match.group(1)
            raw = mime_match.group(2)
        else:
            mime_type = "image/jpeg"
            raw = frame_b64
        try:
            img_bytes = _b64.b64decode(raw)
        except Exception:
            return jsonify({"error": "bad frame encoding"}), 400
        if len(img_bytes) < 512:
            return jsonify({"error": "frame too small"}), 400

        # Ground the detector with a description of the on-screen frame when
        # we have one (current_observed_vision). Never the last still's render
        # recipe — that names objects from the previous location after the
        # live video has drifted. No prior is fine: the JPEG is the truth.
        scene_prompt = ""
        anti_loop_gate = False
        streak = 0
        det_level = DETECT_HIDDEN
        try:
            _st = get_state(session_id) or {}
            scene_prompt = _detect_scene_prior(_st)
            streak = int(_st.get("environment_streak", 0) or 0)
            det_level = get_detection(_st).get("level", DETECT_HIDDEN)
            anti_loop_gate = streak >= ENVIRONMENT_STREAK_LIMIT or det_level >= DETECT_HUNTED
        except Exception:
            scene_prompt = ""

        # Detection runs on the bytes we already have in RAM — no disk write,
        # no re-read, no second base64 encode. The old scratch-file path was
        # both slower and a source of contention when SCAN + PHOTO detects
        # fired against the same session at once.
        viewfinder = bool(data.get("viewfinder"))
        objects = _detect_objects(
            image_bytes=img_bytes,
            mime_type=mime_type,
            scene_prompt=scene_prompt,
            viewfinder=viewfinder,
        )

        # Read the detection ladder's witness off this pass BEFORE the
        # anti-loop gate below empties the list. That gate withholds objects
        # from the player; it is not a statement that the frame is empty, and
        # recording a clean witness from a suppressed list would tell the
        # engine nobody is there at the exact moment a run is being hunted.
        witness = witness_from_detections(objects)
        # The figures that could be an encounter, read off the same
        # pre-gate list for the same reason: the gate withholds tags from the
        # player, it does not empty the room.
        try:
            import encounter as _enc_mod
            sight_candidates = _enc_mod.sighting_candidates(objects)
        except Exception:
            sight_candidates = []

        # SCAN used to be a second front door into the world with no relation
        # to the anti-loop gate `enforce_egress_option` already enforces on the
        # text-choice pills — a run stuck retracing the same room (or being
        # hunted) could just keep tapping whatever SCAN rotated through
        # forever, because the pills' forced "way out" option sat unused right
        # next to a tap target nobody had a reason to ignore. That is exactly
        # how a 40-turn run spent 25+ turns cycling "man / soldier / rifle /
        # truck" in one wrecked vehicle: every tap was a genuine hard cut, but
        # none of them were the fallback pool's forced egress, because SCAN
        # never consulted it. Rather than build a second, parallel
        # stuck-detector for the object list, this reuses the SAME signal:
        # when the pills would already be forcing an egress choice, SCAN goes
        # quiet too (unless it already found the way out itself), so the only
        # affordance left on screen is the one the model or the fallback pool
        # is trying to hand the player.
        suppressed = False
        if anti_loop_gate and objects and not any(
            is_egress_choice(o.get("label") or "") for o in objects
        ):
            print(f"[ANTI-LOOP] SCAN suppressed (streak={streak}, detection={det_level}) "
                  f"— forcing the choice pills' egress option", flush=True)
            objects = []
            suppressed = True

        # Remember what this pass named, so the turn the player commits from it
        # is grounded in the things they can actually see. Best-effort: losing
        # the cache costs grounding, never the scan itself.
        #
        # The same gate carries the detection witness, for the same reasons:
        # it is one deliberate tap rather than the ~2.5 s viewfinder poll, and
        # it reuses this block's existing lock + save, so the frame reading
        # costs no extra API call, no extra round trip and no extra contention.
        # ...and, on the same pass, whether a person in the picture opens an
        # encounter. A sighting is the one rational trigger the confrontation
        # system has: the figure the frame shows, rolled if there are several,
        # with their close-up cut from this very frame. Same gate, same lock,
        # same save — the auto-scan runs one of these on every painted
        # picture, so this is "if a person appears on screen".
        sighting = None
        if str(data.get('purpose') or "").strip().lower() == "scan":
            try:
                with WORLD_STATE_LOCK:
                    st = _load_state(session_id)
                    labels = record_scene_objects(st, objects or [])
                    record_witness(st, witness)
                    try:
                        sighting = _stage_encounter_sighting(
                            st, session_id, sight_candidates, img_bytes)
                    except Exception as e_sight:
                        log_error(f"[ENCOUNTER] sighting failed (non-fatal): {e_sight}")
                        sighting = None
                    _save_state(st, session_id)
                if labels:
                    print(f"[SCENE OBJECTS] turn {st.get('turn_count', 0)} on screen: "
                          f"{', '.join(labels)}", flush=True)
            except Exception as e_cache:
                log_error(f"[SCENE OBJECTS] cache failed (non-fatal): {e_cache}")

        # `anti_loop_suppressed` lets callers (the playtest harness's SCAN
        # hit-rate checks, in particular) tell "the detector found nothing"
        # apart from "the detector found things but the anti-loop gate
        # deliberately withheld them" — an empty `objects` list looks
        # identical on the wire otherwise, and a harness that can't tell
        # those apart flags this gate's own correct behavior as a detector
        # regression every time a run gets hunted long enough to trip it.
        out = {"objects": objects or [], "anti_loop_suppressed": suppressed}
        if sighting:
            # The figure the client opens the confrontation with — label,
            # kind, box, distance. Absent when nothing fired.
            out["encounter_with"] = sighting
        return jsonify(out)
    except Exception as e:
        import traceback as _tb
        log_error(f"[DETECT] failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e), "objects": [], "anti_loop_suppressed": False}), 500


def api_danger():
    """Realtime danger grading for the peripheral-vignette / health system.

    Accepts the frame currently on screen (a JPEG data URL captured client-side
    from the live world-model video) and returns a single ordinal threat level
    for that frame. The client fires this at ~1 Hz while the realtime renderer
    is live; the returned level drives the client's danger state machine (SAFE
    → WARNING → HURTING) which pulses the red peripheral vignette and drains
    health when danger persists.

    Request JSON:  {"frame": "data:image/jpeg;base64,..."}
    Response JSON: {"level": 0|1|2,
                    "reason": "<8 words",
                    "direction": "left"|"right"|"top"|"bottom"|"center"|null,
                    "threat_cx": float|null,
                    "threat_cy": float|null}

    Stateless and read-only, like /api/detect: never mutates world state,
    history, or choices. Degrades to `level: 0` (safe) on ANY failure — the
    danger loop must not be able to hurt the player because vision hiccuped.
    """
    import base64 as _b64, re as _re
    safe = {"level": 0, "reason": "", "direction": None,
            "threat_cx": None, "threat_cy": None}
    try:
        data = request.get_json(silent=True) or {}
        frame_b64 = data.get('frame')
        session_id = data.get('session_id', 'default')
        if not frame_b64:
            return jsonify({"error": "missing frame", **safe}), 400
        mime_match = _re.match(r'^data:(image/[^;]+);base64,(.*)$', frame_b64, _re.DOTALL)
        if mime_match:
            mime_type = mime_match.group(1)
            raw = mime_match.group(2)
        else:
            mime_type = "image/jpeg"
            raw = frame_b64
        try:
            img_bytes = _b64.b64decode(raw)
        except Exception:
            return jsonify({"error": "bad frame encoding", **safe}), 400
        if len(img_bytes) < 512:
            # A tiny/black frame is almost certainly the freeze buffer or a
            # blackout gap — grade it as safe so the vignette doesn't flash
            # on transitions.
            return jsonify(safe)

        # Ground danger with a description of THIS frame when we have one —
        # not the last still's render recipe (same rule as /api/detect).
        scene_prompt = ""
        try:
            _st = get_state(session_id) or {}
            scene_prompt = _detect_scene_prior(_st)
        except Exception:
            scene_prompt = ""

        result = _perceive_danger(
            image_bytes=img_bytes,
            mime_type=mime_type,
            scene_prompt=scene_prompt,
        )
        return jsonify(result if isinstance(result, dict) else safe)
    except Exception as e:
        import traceback as _tb
        log_error(f"[DANGER] failed: {e}")
        _tb.print_exc()
        # Return 200 with a safe reading — the client's loop should not treat
        # a server error as danger. It'll ease back toward SAFE on its own.
        return jsonify({"error": str(e), **safe})


# ───────── dictation: speech to text for the free-will box ───────────────────
# The client tries the browser's own SpeechRecognition first, because it is
# free, instant, and streams words as you speak. It is also unreliable in a way
# that cannot be detected up front: plain Chromium builds expose the API but
# ship without Google's speech key, so every attempt dies with `network` the
# moment it starts, and corporate DNS does the same thing to real Chrome. The
# API being present tells you nothing about whether it works.
#
# So this is the path that always works: the client records the audio and posts
# it here. Slower than the native engine (you wait for the upload instead of
# watching words appear), but it answers, and an answer beats a microphone that
# silently never does anything.
TRANSCRIBE_MAX_BYTES = int(os.getenv("TRANSCRIBE_MAX_BYTES") or 8 * 1024 * 1024)

# What a browser MediaRecorder actually produces, plus the obvious uploads.
_TRANSCRIBE_MIMES = (
    "audio/webm", "audio/ogg", "audio/wav", "audio/x-wav", "audio/mpeg",
    "audio/mp3", "audio/mp4", "audio/aac", "audio/flac", "audio/x-m4a",
)


def _transcribe_audio(audio_bytes: bytes, mime_type: str = "audio/webm",
                      note: Optional[dict] = None) -> str:
    """Spoken words as text, or "" on any failure.

    `note`, when given, is filled in with a machine-readable `reason` for an
    empty result. Every way of returning no words used to look identical from
    the client — a missing API key, a rate limit, a dead upstream and a player
    who simply did not speak all arrived as "" and were reported to them as
    "Didn't catch that". That is a message you cannot act on, and it is the
    reason a working microphone looked broken.

    Deliberately narrow: one short utterance, transcribed literally. The
    temptation is to let the model tidy the sentence up into a nice game
    action, and that is exactly wrong — the player said what they said, and a
    dictation box that rewrites you is worse than one that mishears you,
    because you cannot tell which happened.

    Never raises. A dictation that fails has to leave the player's typed text
    alone and say so, not take the request down.
    """
    import base64 as _b64
    import json as _json

    def _why(reason: str) -> str:
        if note is not None:
            note["reason"] = reason
        return ""

    if not LLM_ENABLED or not provider_bridge.can_call_gemini_api():
        return _why("disabled")
    if not audio_bytes or len(audio_bytes) < 512:
        return _why("too_short")
    if len(audio_bytes) > TRANSCRIBE_MAX_BYTES:
        log_error(f"[TRANSCRIBE] audio too large: {len(audio_bytes)} bytes")
        return _why("bad_audio")
    mime = (mime_type or "audio/webm").split(";")[0].strip().lower()
    if mime not in _TRANSCRIBE_MIMES:
        mime = "audio/webm"

    # Deliberately says NOTHING about games, players or characters.
    #
    # The first version of this prompt explained that the clip was "a player
    # saying what they want their character to do next in a game", on the
    # theory that context helps recognition. Handed one second of pure
    # silence, the model answered "I'm going to go to the tavern." — it had
    # been told what kind of sentence to expect and, with no audio to go on,
    # it produced one. A dictation box that invents an action the player never
    # spoke is far worse than one that mishears them, because the player has
    # no way to tell that is what happened.
    #
    # So the prompt describes the job and not the subject matter, and asks for
    # a sentinel rather than an empty reply: models are reliably bad at
    # returning nothing, and much better at returning a specific token.
    prompt = (
        "Transcribe any speech in this audio clip, word for word.\n\n"
        "Return ONLY the words actually spoken, as plain text.\n"
        "- Do not translate, summarise, rephrase or correct the grammar. "
        "Write what was said, even if it is ungrammatical or unfinished.\n"
        "- No quotation marks, no speaker labels, no timestamps, no commentary.\n"
        "- If there is no intelligible speech in the clip - silence, room "
        "tone, breathing, noise, music - reply with exactly: NO_SPEECH\n"
        "- Never guess at words you cannot hear, and never invent a plausible "
        "sentence to fill a silence. A clip with nothing in it is NO_SPEECH."
    )
    try:
        resp = requests.post(
            "https://generativelanguage.googleapis.com/v1beta/models/"
            "gemini-3.1-flash-lite:generateContent",
            headers={"x-goog-api-key": GEMINI_API_KEY,
                     "Content-Type": "application/json"},
            json={
                "contents": [{
                    "parts": [
                        {"inlineData": {
                            "mimeType": mime,
                            "data": _b64.b64encode(audio_bytes).decode("utf-8"),
                        }},
                        {"text": prompt},
                    ],
                }],
                "generationConfig": {
                    "thinkingConfig": {"thinkingBudget": 0},
                    # Transcription is not a creative act.
                    "temperature": 0.0,
                    "maxOutputTokens": 120,
                },
                "safetySettings": [
                    {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                    {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                    {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                    {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
                ],
            },
            timeout=25,
        )
        resp.raise_for_status()
        result = resp.json()
        candidates = result.get("candidates") or []
        if not candidates:
            return _why("upstream_error")
        parts = (candidates[0].get("content") or {}).get("parts") or []
        text = "".join(p.get("text", "") for p in parts).strip()
    except Exception as e:
        safe_e = str(e).encode("ascii", "replace").decode("ascii")
        log_error(f"[TRANSCRIBE] failed: {safe_e}")
        return _why("upstream_error")

    # The model still occasionally wraps the line in quotes or prefixes it
    # despite being told not to. Strip the wrapper rather than shipping it into
    # the player's action text.
    text = text.strip().strip('"').strip("'").strip()
    if text.lower().startswith("transcription:"):
        text = text.split(":", 1)[1].strip()
    # The sentinel, and the ways a model says it when it decides to be helpful
    # instead of literal. All of them mean the player did not speak, and none
    # of them may reach the action box as words.
    flat = text.lower().strip(" .!-")
    if ("no_speech" in flat
            or flat in ("no speech", "no speech detected", "silence",
                        "(silence)", "[silence]", "inaudible", "unintelligible")):
        return _why("no_speech")
    # A result with no letters in it is not speech.
    #
    # Asked for words and having none, the model reaches for a subtitle
    # artifact instead of the sentinel: a live run put "00:00" into the
    # player's action box. The prompt already forbids timestamps, and this is
    # what came back anyway — so the shape is rejected here rather than
    # trusted to instructions. Digits alone are never an action in this game;
    # a real one always has a verb in it.
    if not re.search(r"[^\W\d_]", text, re.UNICODE):
        print(f"[TRANSCRIBE] discarded non-speech result: {text[:40]!r}", flush=True)
        return _why("no_speech")
    return text[:240].strip()


def api_transcribe():
    """POST /api/transcribe — spoken audio in, plain text out.

    Request JSON:  {"audio": "data:audio/webm;base64,...", "mime": "audio/webm"?}
    Response JSON: {"text": "...", "reason"?: str}

    `reason` accompanies an empty `text` and says which kind of nothing it is
    — no_speech / too_short / disabled / upstream_error / slow_down /
    bad_audio — so the client can tell the player something they can act on.

    Stateless and read-only, like /api/detect: never touches world state,
    history or choices. Degrades to empty text on ANY failure — a dictation
    that fails must leave what the player typed alone.
    """
    import base64 as _b64, re as _re
    try:
        if _rate_limited("transcribe", 0.75):
            return jsonify({"text": "", "reason": "slow_down", "error": "slow_down"})
        data = request.get_json(silent=True) or {}
        audio_b64 = data.get("audio") or ""
        if not audio_b64:
            return jsonify({"text": "", "reason": "bad_audio",
                            "error": "missing audio"}), 400
        m = _re.match(r"^data:(audio/[^;]+)[^,]*,(.*)$", audio_b64, _re.DOTALL)
        if m:
            mime, raw = m.group(1), m.group(2)
        else:
            mime, raw = str(data.get("mime") or "audio/webm"), audio_b64
        try:
            audio_bytes = _b64.b64decode(raw)
        except Exception:
            return jsonify({"text": "", "reason": "bad_audio",
                            "error": "bad audio encoding"}), 400
        note: dict = {}
        text = _transcribe_audio(audio_bytes, mime, note=note)
        reason = "" if text else (note.get("reason") or "no_speech")
        print(f"[TRANSCRIBE] {len(audio_bytes)} bytes {mime} -> "
              f"{len(text)} chars{(' (' + reason + ')') if reason else ''}",
              flush=True)
        return jsonify({"text": text, "reason": reason})
    except Exception as e:
        log_error(f"[TRANSCRIBE] endpoint failed: {e}")
        return jsonify({"text": "", "reason": "upstream_error", "error": str(e)})


def _write_data_url_image(
    frame_b64: str,
    session_id: str,
    prefix: str = "viewfinder_live",
) -> Optional[str]:
    """Decode a browser data-URL onto disk. Does not touch history or state."""
    import base64 as _b64, re as _re, time as _time
    if not frame_b64:
        return None
    m = _re.match(r"^data:image/[^;]+;base64,(.*)$", frame_b64, _re.DOTALL)
    raw = m.group(1) if m else frame_b64
    try:
        img_bytes = _b64.b64decode(raw)
    except Exception:
        return None
    if len(img_bytes) < 512:
        return None
    img_dir = Path(_get_image_dir(session_id))
    img_dir.mkdir(parents=True, exist_ok=True)
    fpath = img_dir / f"{prefix}_{int(_time.time() * 1000)}.jpg"
    fpath.write_bytes(img_bytes)
    return str(fpath) if fpath.is_file() else None


def _viewfinder_source_still(session_id: str) -> Optional[str]:
    """Filesystem path of the current 3P gameplay still, if one exists."""
    st = get_state(session_id) or {}
    url = st.get("current_image_url")
    if url:
        resolved = _resolve_image_path(url, session_id)
        if resolved and os.path.exists(resolved):
            return str(resolved)
    hist = _load_history(session_id)
    for entry in reversed(hist or []):
        img = entry.get("image") or entry.get("image_url")
        if not img:
            continue
        resolved = _resolve_image_path(img, session_id)
        if resolved and os.path.exists(resolved):
            return str(resolved)
    return None


def _viewfinder_cache_key(source_path: str, spatial: str = "") -> str:
    p = Path(source_path)
    try:
        digest = hashlib.sha256(p.read_bytes()).hexdigest()[:20]
    except OSError:
        digest = p.name
    raw = f"eyes-v4:{digest}:{spatial or ''}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


def _viewfinder_cache_path(session_id: str, key: str) -> Path:
    return Path(_get_image_dir(session_id)) / f"viewfinder_{key}.png"


def _viewfinder_last_look(session_id: str) -> dict:
    hist = _load_history(session_id)
    last = hist[-1] if hist else {}
    st = get_state(session_id) or {}
    return {
        "spatial": last.get("spatial_compass") or "",
        "setting": last.get("setting_type") or "",
        "description": last.get("vision_analysis") or last.get("vision_dispatch") or "",
        "time_of_day": st.get("time_of_day") or "",
    }


def _viewfinder_leaked_character(image_path: str, *, allow_other_people: bool = False) -> bool:
    """True when a viewfinder plate still has the operator.

    SCAN's normal detect path strips the protagonist so you cannot tag
    yourself. This check asks to keep those labels. Local detect often
    names the leaked body ``person`` rather than the authored name — a
    large centered human on the FIRST (3P-attached) plate is that leak.

    ``allow_other_people`` is for the retry and for cache hits: an NPC
    in front of the lens is a real subject, not the operator. Refusing
    those plates made PHOTO fail in encounters.
    """
    try:
        objects = _detect_objects(image_path=image_path, include_self=True)
    except Exception:
        return False
    for obj in objects or []:
        label = (obj or {}).get("label") or ""
        if _is_player_self_label(label):
            return True
        if allow_other_people:
            continue
        kind = str((obj or {}).get("kind") or "").lower()
        try:
            w = float((obj or {}).get("w") or 0)
            h = float((obj or {}).get("h") or 0)
            cx = float((obj or {}).get("cx") or 0.5)
        except (TypeError, ValueError):
            continue
        if kind in ("person", "character") and (w * h) >= 0.10 and 0.22 <= cx <= 0.78:
            return True
    return False


def _install_viewfinder_cache(generated_path: str, dest: Path) -> Optional[str]:
    """Copy a generated still onto the viewfinder cache name. Returns dest path."""
    src = generated_path
    if not src or not os.path.exists(str(src)):
        resolved = _resolve_image_path(src) if src else None
        if not resolved or not os.path.exists(resolved):
            return None
        src = str(resolved)
    dest.parent.mkdir(parents=True, exist_ok=True)
    if os.path.abspath(src) != os.path.abspath(dest):
        import shutil
        shutil.copy2(src, dest)
    return str(dest) if dest.is_file() else None


def render_viewfinder_image(
    session_id: str = "default",
    *,
    attach_source: bool = True,
    source_path: Optional[str] = None,
) -> Optional[str]:
    """Restage the frame the player is looking at as first person.

    The attached still is the current view (live grab or last gameplay still).
    It is labeled a place lock: copy architecture and light, erase the person.
    """
    source = source_path or _viewfinder_source_still(session_id)
    if not source:
        return None
    look = _viewfinder_last_look(session_id)
    fp_spec = game_identity.viewfinder_spec()
    stripped = game_identity.strip_follow_cam_prose(look["description"], fp_spec)
    caption = stripped or look["spatial"] or "The same place, seen through the player's eyes."
    history_ref = []
    frame_idx = 0
    if attach_source:
        live = Path(str(source)).name.startswith("viewfinder_live_")
        history_ref = [{
            "image": source,
            "vision_dispatch": caption,
            "vision_analysis": caption,
            "spatial_compass": look["spatial"],
            "setting_type": look["setting"],
            "hard_transition": False,
            "live_capture": live,
        }]
        frame_idx = 1
    result = _gen_image(
        caption,
        "camcorder",
        "Raise camera",
        image_description=caption,
        time_of_day=look["time_of_day"] or None,
        use_edit_mode=False,
        frame_idx=frame_idx,
        dispatch=caption,
        world_prompt="",
        hard_transition=False,
        is_timeout_penalty=False,
        session_id=session_id,
        history_ref=history_ref,
        identity_spec=fp_spec,
    )
    path = result[0] if result else None
    if path and not os.path.exists(str(path)):
        resolved = _resolve_image_path(path)
        path = str(resolved) if resolved and os.path.exists(resolved) else None
    return path


def _viewfinder_live_prompt(session_id: str, caption: str = "") -> str:
    """Realtime prompt that restages the world model as planted first person."""
    spec = game_identity.viewfinder_spec()
    contract = game_identity.live_camera_contract(spec)
    look = _viewfinder_last_look(session_id)
    stripped = game_identity.strip_follow_cam_prose(
        caption or look.get("description") or "", spec,
    )
    scene = stripped or look.get("spatial") or contract.get("scene_floor") or ""
    prefix = (contract.get("prefix") or contract.get("vantage") or "").strip()
    planted = (
        "The player is planted and looking through their own eyes. "
        "Looking left or right yaws the camera in place; looking up or down pitches. "
        "Do not walk, truck, strafe, or slide the viewpoint. "
        "Do not draw the player, their hands, or a camcorder. "
        "Do not spawn, walk, or stand a person in front of the lens. "
        "This world has no protagonist on screen. Uninhabited first-person view. "
        "Empty air between the lens and the scene. "
        + game_identity.viewfinder_hero_ban(spec)
    )
    prefix = game_identity.strip_follow_cam_prose(prefix, spec)
    scene = game_identity.strip_follow_cam_prose(scene, spec)
    return " ".join(p for p in (prefix, scene, planted) if p)


def _viewfinder_response(
    session_id: str,
    image_url: str,
    *,
    cached: bool,
    from_live: bool,
    source: Optional[str],
    seed_image: bool = True,
):
    spec = game_identity.viewfinder_spec()
    look = _viewfinder_last_look(session_id)
    caption = game_identity.strip_follow_cam_prose(look.get("description") or "", spec)
    source_url = _to_web_image_url(source, session_id) if source else ""
    return jsonify({
        "image_url": image_url,
        "cached": cached,
        "from_live": from_live,
        "seed_image": seed_image,
        "source_still": source_url,
        "prompt": _viewfinder_live_prompt(session_id, caption),
        "camera": game_identity.live_camera_contract(spec),
    })


def api_viewfinder():
    """Raise PHOTO: restage the current view as first-person, no turn.

    Request JSON:  {"session_id": "...", "frame": "data:image/jpeg;base64,..."?}
    Response JSON: {"image_url", "cached", "source_still", "from_live",
                    "seed_image", "prompt", "camera"}

    ``frame`` is the live view grab. It is the img2img source so the plate is
    THIS place, not the opening still. The person in that grab is erased by
    the place-lock label. Without a frame, falls back to the current still.

    ``seed_image`` is false when detect still names a person.

    ``prompt`` / ``camera`` retarget the running world model onto first person
    without saving a camera-mode change.

    Does not mutate ``camera_perspective``, history, or world state.
    """
    try:
        data = request.get_json(silent=True) or {}
        session_id = data.get("session_id", "default")
        if not (IMAGE_ENABLED and LLM_ENABLED):
            return jsonify({"error": "images_disabled"}), 503

        authored_mode = game_identity.camera_mode()
        hist_before = list(_load_history(session_id) or [])
        state_before = (get_state(session_id) or {}).get("current_image_url")
        live_path = _write_data_url_image(data.get("frame") or "", session_id)
        source = live_path or _viewfinder_source_still(session_id)
        if not source:
            return jsonify({"error": "no_still"}), 400

        look = _viewfinder_last_look(session_id)
        key = _viewfinder_cache_key(source, look.get("spatial") or "")
        cached = _viewfinder_cache_path(session_id, key)
        if cached.is_file():
            if _viewfinder_leaked_character(str(cached), allow_other_people=True):
                print("[VIEWFINDER] cached plate leaked protagonist — regenerating")
                try:
                    cached.unlink()
                except OSError:
                    pass
            else:
                return _viewfinder_response(
                    session_id,
                    _to_web_image_url(str(cached), session_id),
                    cached=True,
                    from_live=bool(live_path),
                    source=source,
                    seed_image=True,
                )

        first = render_viewfinder_image(
            session_id, attach_source=True, source_path=source,
        )
        chosen = first
        if first and _viewfinder_leaked_character(first):
            print("[VIEWFINDER] protagonist leaked into plate — retrying without 3P pixels")
            retry = render_viewfinder_image(
                session_id, attach_source=False, source_path=source,
            )
            if retry:
                chosen = retry
        leaked = bool(chosen) and _viewfinder_leaked_character(
            chosen, allow_other_people=True,
        )
        installed = None
        if chosen and not leaked:
            installed = _install_viewfinder_cache(chosen, cached)
        elif chosen and leaked:
            print("[VIEWFINDER] plate still names a person — refusing leaked viewfinder")
            installed = None
        if game_identity.camera_mode() != authored_mode:
            log_error("[VIEWFINDER] authored camera mode changed — this path must not save")
        hist_after = list(_load_history(session_id) or [])
        if len(hist_after) != len(hist_before):
            log_error("[VIEWFINDER] history grew — this path must not append a turn")
        state_after = (get_state(session_id) or {}).get("current_image_url")
        if state_after != state_before:
            log_error("[VIEWFINDER] current_image_url changed — this path must not clobber the 3P still")

        if not installed:
            return jsonify({"error": "render_failed"}), 502
        return _viewfinder_response(
            session_id,
            _to_web_image_url(installed, session_id),
            cached=False,
            from_live=bool(live_path),
            source=source,
            seed_image=not leaked,
        )
    except Exception as e:
        import traceback as _tb
        log_error(f"[VIEWFINDER] failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e)}), 500


def api_photo():
    """Appraise a photograph the player just captured (the reward loop).

    Accepts the captured crop (a JPEG data URL made client-side from the live
    frame or the current still) and returns an evidence-style appraisal: the
    notable things in frame, each with an interest rating and a terse reason,
    plus a caption and mood. The standalone UI prints this as a "receipt" that
    reveals item-by-item and scores each line toward the run's EVIDENCE total.

    Request JSON:  {"frame": "data:image/jpeg;base64,..."}
    Response JSON: {"items": [{"label", "interest", "note"}], "caption", "mood"}

    Stateless and read-only, like /api/detect: it never mutates world state,
    history, or choices — it only reads what the photo shows. Degrades to an
    empty appraisal (never an error) when vision is unavailable, so the client
    can always render a graceful receipt.
    """
    import base64 as _b64, re as _re
    from pathlib import Path as _Path
    try:
        data = request.get_json(silent=True) or {}
        frame_b64 = data.get('frame')
        session_id = data.get('session_id', 'default')
        if not frame_b64:
            return jsonify({"error": "missing frame"}), 400
        m = _re.match(r'^data:image/[^;]+;base64,(.*)$', frame_b64, _re.DOTALL)
        raw = m.group(1) if m else frame_b64
        try:
            img_bytes = _b64.b64decode(raw)
        except Exception:
            return jsonify({"error": "bad frame encoding"}), 400
        if len(img_bytes) < 512:
            return jsonify({"error": "frame too small"}), 400

        img_dir = _Path(_get_image_dir(session_id))
        img_dir.mkdir(parents=True, exist_ok=True)
        # Reuse a single scratch file per session, like the SCAN grab: these are
        # disposable perception frames, not canonical stills.
        fpath = img_dir / "photo_frame.jpg"
        fpath.write_bytes(img_bytes)

        appraisal = _appraise_photo(str(fpath))
        if not isinstance(appraisal, dict):
            appraisal = {"items": [], "caption": "", "mood": ""}
        return jsonify(appraisal)
    except Exception as e:
        import traceback as _tb
        log_error(f"[PHOTO] failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e), "items": [], "caption": "", "mood": ""}), 500


# ═══════════════════════════════════════════════════════════════════
# TALK — converse with a person / character / thing that speaks
#
# The SCAN tool now classifies whether each detected thing can hold a
# conversation (``speaks``). When the player picks TALK on such a subject we
# open a dialogue that is AWARE of the story: who the player is, the premise,
# the current phase/chaos/location, and the last few beats. This awareness is
# assembled once here and reused two ways:
#   • text mode (always available) — an LLM roleplays the subject in-world.
#   • voice mode (when the key can speak) — the same text dialogue, with each
#     answer spoken in the character's voice (speech.py) and the player able
#     to hold to speak instead of typing.
# Both are stateless/read-only: talking never mutates world state or history.
# ═══════════════════════════════════════════════════════════════════

def _story_premise() -> str:
    """The high-level premise the whole simulation runs on (first paragraph of
    the world-setup prompt), used to ground a conversation partner."""
    try:
        raw = (PROMPTS.get("world_initial_state") or "").strip()
        # First paragraph is the evocative premise; the rest is model direction.
        premise = raw.split("\n\n")[0].strip()
        return premise[:600]
    except Exception:
        return "An analog-horror investigation. You are a photojournalist documenting something that should not exist."


# Best-effort in-memory rate limiting for the (LLM/TTS-backed, cost-bearing)
# conversation + narrator endpoints. Per-client + per-bucket minimum interval;
# generous enough not to bother real players, tight enough to blunt abuse. This
# is a single-process guard (fine for the current gunicorn setup); a shared
# store would be needed if scaled horizontally.
_RATE_BUCKETS = {}


def _rate_limited(bucket: str, min_interval: float) -> bool:
    """Return True if this client is calling ``bucket`` faster than
    ``min_interval`` seconds apart (and should be turned away)."""
    try:
        ip = (request.headers.get("X-Forwarded-For", "") or request.remote_addr or "?").split(",")[0].strip()
    except Exception:
        ip = "?"
    key = f"{bucket}:{ip}"
    now = time.time()
    last = _RATE_BUCKETS.get(key, 0)
    # Opportunistic prune so the dict can't grow without bound.
    if len(_RATE_BUCKETS) > 5000:
        cutoff = now - 300
        for k in [k for k, t in _RATE_BUCKETS.items() if t < cutoff]:
            _RATE_BUCKETS.pop(k, None)
    if now - last < min_interval:
        return True
    _RATE_BUCKETS[key] = now
    return False


def _clean_subject_text(value: str, fallback: str, limit: int) -> str:
    """Sanitize client-supplied subject fields before they enter an LLM prompt:
    collapse whitespace/newlines and hard-cap the length (prompt-injection and
    token-burn guard)."""
    s = re.sub(r"\s+", " ", str(value or "")).strip().lower()
    return (s[:limit] or fallback)


def _talk_vision_snapshot(session_id: str = "default") -> dict:
    """Snapshot of what the character being talked to can actually SEE.

    Reads the frame the player is looking at right now
    (``state['current_image_url']``) and returns a compact summary the persona
    prompt can quote — what visible objects share the scene with the subject,
    plus the cached scene description / time of day / palette. This is what
    lets the character reference the lantern in the player's hand, the door
    behind them, the fresh boot prints on the floor — instead of talking
    blind against just a text scene description.

    Always returns a JSON-safe dict; degrades to empty fields when vision is
    disabled, when the current scene isn't on disk yet, or on any failure
    (never raises — TALK stays available even if perception is down).

    Returns:
        {
          "visible":   [{"label","kind","cx","cy","w","h","speaks"}, ...],
          "description": str,        # single sentence, from _vision_analyze_all
          "time_of_day": str,        # e.g. "night", "dusk"
          "image_url":  str | None,  # web path of the frame we analyzed
        }
    """
    empty = {"visible": [], "description": "", "time_of_day": "", "image_url": None}
    if not LLM_ENABLED or not VISION_ENABLED:
        return empty
    try:
        st = _load_state(session_id) or {}
    except Exception:
        st = {}
    image_url = st.get("current_image_url") or None
    if not image_url:
        return empty
    resolved = _resolve_image_path(image_url)
    if not resolved or not resolved.exists():
        return empty

    # Two vision calls but both are cache-friendly: _vision_analyze_all is
    # already cached per image path, so on the common case (TALK opened during
    # a scene we've already analyzed for the turn dispatch) this is free. The
    # detection call is fresh but reuses the PR #89 keep-alive session and
    # deterministic prompt path, so tag output stays stable frame-to-frame.
    description = ""
    time_of_day = ""
    try:
        analysis = _vision_analyze_all(str(resolved)) or {}
        description = (analysis.get("description") or "").strip()
        time_of_day = (analysis.get("time_of_day") or "").strip()
    except Exception:
        pass

    scene_prompt = _detect_scene_prior(st)
    visible = []
    try:
        visible = _detect_objects(str(resolved), max_items=DETECT_MAX_ITEMS,
                                  scene_prompt=scene_prompt) or []
    except Exception:
        visible = []

    return {
        "visible": visible,
        "description": description[:600],
        "time_of_day": time_of_day[:32],
        "image_url": image_url,
    }


def _format_vision_for_persona(subject_label: str, snapshot: dict) -> str:
    """Turn a ``_talk_vision_snapshot`` into a short block for persona_prompt.

    We deliberately avoid dumping raw coordinates; the character narrates the
    world, they don't read a bounding-box table. Instead we tell them what's
    around them, roughly WHERE (left/center/right), and quote the scene
    description verbatim so the model can pick vocabulary from it. Objects
    whose label matches the subject (they'd be talking about themselves) are
    dropped so the persona doesn't say "I can see a figure over there" when
    THEY are the figure.
    """
    if not snapshot:
        return ""
    parts = []
    desc = (snapshot.get("description") or "").strip()
    if desc:
        parts.append(f"WHAT YOU CAN SEE RIGHT NOW: {desc}")
    tod = (snapshot.get("time_of_day") or "").strip()
    if tod:
        parts.append(f"LIGHT: {tod}.")

    subj = (subject_label or "").strip().lower()
    around = []
    for obj in snapshot.get("visible") or []:
        label = str(obj.get("label") or "").strip().lower()
        if not label or label == subj:
            continue
        cx = float(obj.get("cx", 0.5))
        if cx < 0.35:
            where = "off to your left"
        elif cx > 0.65:
            where = "off to your right"
        else:
            where = "in front of you"
        around.append(f"{label} {where}")
        if len(around) >= 6:
            break
    if around:
        parts.append("Also visible in the scene: " + "; ".join(around) + ".")

    if not parts:
        return ""
    return (
        "\n\nDIRECT PERCEPTION (use these to react to what is actually in "
        "the scene right now; never invent objects that aren't listed):\n"
        + "\n".join(parts)
    )


def build_talk_context(subject: dict, session_id: str = "default", opening_override: str = "",
                       include_vision: bool = True) -> dict:
    """Assemble a story-aware briefing for a conversation with ``subject``.

    ``subject`` is the SCAN object the player chose to talk to
    (``{"label", "kind", "speaks"}``). Returns a JSON-safe dict describing the
    subject, the current situation, and a ready-to-use persona prompt + opening
    line. This is the single source of "awareness" shared by the text fallback
    and the spoken one. ``opening_override`` reuses an existing
    opening line instead of spending an LLM call to regenerate one (used when
    only the VOICE is changing mid-conversation).

    The persona is grounded in the CURRENT visible frame (see
    ``_talk_vision_snapshot``) so the character isn't talking blind — they
    can reference what's actually on screen alongside the story situation.

    ``include_vision=False`` skips the (two Gemini vision calls) perception
    snapshot — used by the portrait endpoint, which only needs subject +
    situation and runs CONCURRENTLY with the session's own build_talk_context,
    so doing the vision work twice would just double the latency for nothing.
    """
    subject = subject or {}
    label = _clean_subject_text(subject.get("label"), "figure", 40)
    kind = _clean_subject_text(subject.get("kind"), "", 20)
    if not kind:
        kind = "person" if _talk_subject_is_figure(subject) else "machine"

    try:
        st = _load_state(session_id) or {}
    except Exception:
        st = {}
    try:
        hist = _load_history(session_id) or []
    except Exception:
        hist = []

    phase = st.get("current_phase", "normal")
    chaos = st.get("chaos_level", 0)
    turn = st.get("turn_count", 0)
    location = st.get("location", "") or ""
    time_of_day = st.get("time_of_day", "") or ""
    world_prompt = (st.get("world_prompt") or "").strip()

    inventory = []
    try:
        from items import ITEMS
        for item_id in (st.get("inventory") or []):
            meta = ITEMS.get(item_id) or {}
            inventory.append(meta.get("display", item_id))
    except Exception:
        inventory = list(st.get("inventory") or [])

    # The last few narrative beats — what just happened, so the character can
    # react to the moment rather than talking in a vacuum.
    recent = []
    for entry in hist[-4:]:
        d = (entry.get("dispatch") or "").strip()
        if d:
            recent.append(d[:280])

    situation = {
        "phase": phase,
        "chaos": chaos,
        "turn": turn,
        "location": location,
        "time_of_day": time_of_day,
        "inventory": inventory,
        "scene": world_prompt[:400],
    }

    premise = _story_premise()

    # Compose the persona / system prompt the roleplay LLM uses to BE this
    # subject, grounded in the story.
    kind_hint = {
        "person": "a person the player has encountered",
        "character": "a named character in this world",
        "creature": "a strange, possibly sentient creature",
        "animal": "an animal that, in this uncanny place, can speak",
        "machine": "a machine or device carrying a voice (radio / intercom / terminal)",
    }.get(kind, "someone the player has encountered")

    recent_block = ""
    if recent:
        recent_block = "\n\nRECENT EVENTS (most recent last):\n- " + "\n- ".join(recent)

    scene_block = f"\n\nRIGHT NOW: {world_prompt}" if world_prompt else ""
    loc_bits = ", ".join([b for b in [location.replace("_", " ") if location else "", time_of_day] if b])
    loc_block = f"\n\nSETTING: {loc_bits}." if loc_bits else ""

    # Direct-perception block: what the subject can actually SEE in the frame
    # the player is looking at, so the character can react to real objects on
    # screen instead of a text-only briefing. Empty string when vision is
    # unavailable or skipped — the persona still works, just without the eyes.
    vision_snapshot = _talk_vision_snapshot(session_id) if include_vision else \
        {"visible": [], "description": "", "time_of_day": "", "image_url": None}
    vision_block = _format_vision_for_persona(label, vision_snapshot)

    # "A 1993 analog-horror world" and "the investigator/photojournalist" are
    # the shipped premise, not the player's. A character talking to you should
    # know who you actually are and where you actually are.
    world_label = game_identity.place_summary() or "a 1993 analog-horror world"
    interlocutor = (
        game_identity.protagonist_line()
        or "the investigator/photojournalist exploring this place"
    )

    persona_prompt = (
        f"You ARE the '{label}' — {kind_hint} — inside {world_label} "
        f"You are NOT an AI assistant and you must never break character or mention being an AI. "
        f"Speak in-world, in first person, reacting to what is happening around you.\n\n"
        f"WORLD PREMISE: {premise}"
        f"{scene_block}{loc_block}{vision_block}"
        f"\n\nSTATE: story phase '{phase}', chaos level {chaos}/10, turn {turn}."
        f"{recent_block}\n\n"
        f"The person you are speaking to is {interlocutor}"
        + (f" (currently carrying: {', '.join(inventory)})" if inventory else "")
        + ". Stay consistent with the premise and the recent events.\n\n"
        "HOW TO TALK: Sound like a real person actually speaking out loud, not writing. Use plain, "
        "everyday words and contractions (I'm, don't, can't, you're). Keep it SHORT — 1 to 2 quick "
        "sentences, a breath or two, never a speech or a monologue. It's fine to be fragmentary, to "
        "trail off, to interrupt yourself, or to answer with just a few words. Skip flowery description "
        "and big vocabulary; talk the way a scared, tired, or wary human really would in the moment. "
        "Never open with a generic sentry line — no 'you shouldn't be here', 'what do you want', "
        "'who are you', 'is someone there'. Name something in front of you, or say the thing only "
        "THIS person would say in THIS second. "
        "You may be afraid, hostile, cryptic, desperate, or helpful depending on who you are and what is "
        "happening. Reveal information sparingly and in character. If asked something you couldn't know, "
        "deflect in a way that fits the scene. Never narrate stage directions or use asterisks — just say the words."
    )

    # A cold-open first line so the conversation starts with presence. Reuse a
    # provided line (e.g. when only the voice is changing) to skip an LLM call.
    opening_line = (opening_override or "").strip()[:320] \
        or _talk_opening_line(label, kind, situation, persona_prompt)

    return {
        "subject": {"label": label, "kind": kind, "speaks": bool(subject.get("speaks", True))},
        "premise": premise,
        "situation": situation,
        "recent": recent,
        "persona_prompt": persona_prompt,
        "opening_line": opening_line,
        # Vision snapshot rides along so any Live-audio path (via
        # system_instruction) can quote the same "what you can see" list the persona was built on.
        "vision": vision_snapshot,
    }


def _talk_llm_failed(text: str) -> bool:
    """True when an ``_ask`` result is an error/placeholder sentinel rather than
    a genuine in-character line, so TALK can fall back gracefully."""
    t = (text or "").strip().lower()
    if not t:
        return True
    sentinels = (
        "signal interrupted", "the transmission wavers",
        "system communications remain static", "narrative paused",
        "the world holds its breath",
    )
    if any(t.startswith(s) or s in t for s in sentinels):
        return True
    return t.startswith(("i cannot", "i can't", "as an", "i'm sorry", "i am sorry"))


def _talk_opening_fallback(label: str, kind: str) -> str:
    """Instant first line — no LLM. TALK must speak even when Gemini is slow.

    These are presence beats, not interrogation. The old stock lines
    ("You. You shouldn't be here. What do you want?") made every conversation
    open as the same video-game NPC.
    """
    who = (label or "it").strip() or "it"
    return {
        "machine": f"The {who} pops. Don't hang up.",
        "creature": "You can hear me.",
        "animal": "Easy. Stay.",
    }.get(kind, "Don't. Not yet.")


def _is_canned_talk_fallback(text: str) -> bool:
    """True when ``text`` is a stock TALK opener the client used to post as
    the first message — ignore those so the persona can write a real line."""
    t = (text or "").strip().lower()
    if not t:
        return False
    if t.startswith("you. you shouldn't be here"):
        return True
    if "is someone there" in t and "say something" in t:
        return True
    if t.startswith("…you can see me") or t.startswith("...you can see me"):
        return True
    return False


def _talk_opening_line(label: str, kind: str, situation: dict, persona_prompt: str) -> str:
    """The subject's first line — spoken before the player says anything.

    Uses the LLM when available (grounded in the persona prompt); falls back to
    a tense, generic-but-fitting line so the mechanic always opens with voice.
    """
    fallback = _talk_opening_fallback(label, kind)

    if not LLM_ENABLED:
        return fallback
    try:
        prompt = (
            persona_prompt
            + "\n\nThe person has just turned to face you. Say your FIRST line to them — "
            "one short sentence, spoken out loud, in character, reacting to this exact moment. "
            "Name something specific you can see, or something only you would say. "
            "Do NOT say 'you shouldn't be here', 'who are you', 'what do you want', "
            "'is someone there', or any other generic sentry/NPC greeting. "
            "Keep it terse and human. Output ONLY the spoken words."
        )
        line = _ask(prompt, temp=0.9, tokens=50, use_lore=False)
        line = (line or "").strip().strip('"').strip()
        # Guard against the model narrating, refusing, or erroring out.
        if _talk_llm_failed(line) or len(line) > 320 or _is_canned_talk_fallback(line):
            return fallback
        return line
    except Exception:
        return fallback


def build_portrait_prompt(context: dict, img2img: bool = False,
                          with_wide: bool = False) -> str:
    """Compose a cinematic medium-shot portrait prompt for a Conversation Moment.

    Reuses the same talk context (subject, scene, time of day) the persona was
    built from, but applies ``CONVERSATION_PORTRAIT_STYLE_ANCHOR`` — a distinct
    lens language from the handheld-camcorder world view — so the cut into
    dialogue reads as a register change.

    ``img2img=True`` phrases it as a likeness hold of a SCAN bounding-box crop
    of the subject (the reference IS those pixels). Beings keep face/clothes
    and reframe to a cinematic medium shot. Machines and objects keep the
    cropped object and reframe to a cinematic close-up — never invent a person.
    """
    context = context or {}
    subject = context.get("subject") or {}
    situation = context.get("situation") or {}
    label = _clean_subject_text(subject.get("label"), "figure", 40)
    kind = _clean_subject_text(subject.get("kind"), "", 20)
    if not kind:
        kind = "person" if _talk_subject_is_figure(subject) else "machine"
    scene = (situation.get("scene") or "").strip()
    if len(scene) > 220:
        scene = scene[:217].rstrip() + "..."
    tod = (situation.get("time_of_day") or "").strip()
    loc = (situation.get("location") or "").replace("_", " ").strip()
    is_figure = _talk_subject_is_figure({"label": label, "kind": kind})

    kind_look = {
        "person": "a wary human figure",
        "character": "a named character from this world",
        "creature": "a strange, possibly inhuman presence with a readable face or visage",
        "animal": "an uncanny animal that meets the camera's gaze",
        "machine": "a machine, radio, intercom, monitor, or terminal that somehow feels present / watched",
        "object": "the exact object in the crop, filling the frame",
    }.get(kind, "a figure the investigator has encountered")

    if img2img:
        # Two references are supplied when `with_wide`: [0] the subject's own
        # crop, [1] the whole frame it was standing in. Naming them separately
        # matters — told only about "the crop", the model treated the second
        # picture as another subject and sometimes drew the wide scene instead of
        # the close-up.
        first = ("The FIRST reference is a close crop of" if with_wide
                 else "The reference is a close crop of")
        if not is_figure:
            bits = [
                f"{first} the '{label}' — {kind_look} — taken from the live video frame.",
                "Keep this exact object: same shape, materials, wear, markings, and the light falling on it.",
                "Cinematic close-up, the object filling the frame, sharp and clearly lit,",
            ]
            if with_wide:
                bits += [
                    "The SECOND reference is the WIDE SHOT of the place this object "
                    "is in. It is not the subject and must not be reproduced as the "
                    "composition — use it only for what lies around and behind the "
                    "object: the same location, the same structures, the same "
                    "ground and sky, the same light and palette. Build the "
                    "background out of THAT place, softly out of focus, so this "
                    "reads as a close look at something here rather than a cut "
                    "somewhere else.",
                ]
            else:
                bits.append("the surrounding environment from the crop softly out of focus behind it.")
            bits.append("Do not invent a person. Do not add a face, figure, or human. Do not replace the object.")
        else:
            # A crop of the SCAN bounding box is supplied — that IS the person, not
            # a wide plate we have to invent a face into.
            bits = [
                f"{first} the '{label}' — {kind_look} — taken from the current frame.",
                "Keep this exact person: same face, hair, clothes, build, and the light falling on them.",
                "Cinematic medium shot, mid-torso up, this same figure sharp and clearly lit,",
            ]
            if with_wide:
                bits += [
                    "The SECOND reference is the WIDE SHOT of the place this person "
                    "is standing in. It is not the subject and its framing must not "
                    "be copied — use it only for what lies around and behind them: "
                    "the same location, the same structures, the same ground and "
                    "sky, the same light and palette. Build the background out of "
                    "THAT place, softly out of focus, so this reads as a close look "
                    "at somebody here rather than a cut somewhere else.",
                ]
            else:
                bits.append("the surrounding environment from the crop softly out of focus behind them.")
            bits.append("Do not invent a different person. Do not replace their face.")
        setting = ", ".join([b for b in [loc, tod] if b])
        if setting:
            bits.append(f"Setting: {setting}.")
        return _sanitize_for_image_generation(" ".join(bits))

    if not is_figure:
        bits = [
            "stylish cinematic close-up, 35mm film still, shallow depth of field, "
            "analog-horror 1993 muted palette, subtle film grain.",
            f"Subject: the '{label}' — {kind_look}. The object fills the frame.",
            "No person, no face, no figure, no human in frame.",
        ]
    else:
        bits = [
            # A portrait is a deliberate break from the world camera — a locked-off
            # medium shot of somebody who is NOT the player — so it takes the
            # level's era and palette but keeps its own framing.
            game_identity.world_anchor(
                CONVERSATION_PORTRAIT_STYLE_ANCHOR,
                include_character=False,
                include_vantage=False,
            ).rstrip(". ") + ".",
            f"Subject: the '{label}' — {kind_look}.",
            "Hold a charged, intimate medium shot; the subject fills the frame.",
        ]
    if scene:
        bits.append(f"Background suggests this place (softly, out of focus): {scene}")
    setting = ", ".join([b for b in [loc, tod] if b])
    if setting:
        bits.append(f"Setting cues: {setting}.")
    bits.append(
        "No text, no UI, no letterbox bars inside the image. Photoreal cinematic still."
    )
    prompt = " ".join(bits)
    return _sanitize_for_image_generation(prompt)


def _companion_slug(label: str) -> str:
    """Filesystem-safe, stable slug for a companion label."""
    s = re.sub(r"[^a-z0-9]+", "_", (label or "").strip().lower()).strip("_")
    return (s or "figure")[:40]


def _persist_companion_image(image_path: str, session_id: str, label: str) -> Optional[str]:
    """Copy a freshly-generated portrait to a STABLE, sweep-protected companion
    file (``companion_<slug>.png``) so it survives as part of the roster and can
    be re-referenced when placing the character into future scenes.

    Returns the web URL of the durable copy, or None on failure.
    """
    try:
        src = _resolve_image_path(image_path)
        if not src or not src.exists():
            return None
        img_dir = Path(_get_image_dir(session_id))
        img_dir.mkdir(parents=True, exist_ok=True)
        slug = _companion_slug(label)
        dst = img_dir / f"companion_{slug}.png"
        import shutil as _shutil
        # Client crops are JPEGs. Write a real PNG so camp img2img / the
        # roster never open JPEG bytes under a .png name.
        try:
            from PIL import Image
            im = Image.open(src)
            if im.mode not in ("RGB", "L"):
                im = im.convert("RGB")
            im.save(dst, "PNG")
        except Exception:
            _shutil.copyfile(str(src), str(dst))
        try:
            small_src = src.with_name(src.name.replace(".png", "_small.png"))
            if small_src.exists():
                _shutil.copyfile(str(small_src), str(img_dir / f"companion_{slug}_small.png"))
        except Exception:
            pass
        return _to_web_image_url(f"companion_{slug}.png", session_id)
    except Exception as e:
        log_error(f"[COMPANION] persist image failed: {e}")
        return None


def _record_companion(session_id: str, subject: dict, portrait_url: str,
                      prompt: str = "", scene: str = "",
                      portrait_source: str = "", portrait_gen: int = 0) -> dict:
    """Upsert a COMPANION into the session roster.

    A companion is a character the player has spoken with, stored WITH their
    cinematic portrait so they can be dropped back into later scenes to build a
    continuing story. Additive metadata on session state (``state.companions``),
    keyed by lowercased label; also links the portrait onto the lightweight
    character-memory record. Returns the companion record (JSON-safe).
    """
    subject = subject or {}
    display_label = re.sub(r"\s+", " ", str(subject.get("label") or "")).strip()[:40]
    label = _clean_subject_text(subject.get("label"), "", 40)
    if not label or not portrait_url:
        return {}
    try:
        st = _load_state(session_id) or {}
    except Exception:
        return {}
    companions = st.get("companions")
    if not isinstance(companions, dict):
        companions = {}
    key = label.lower()
    prev = companions.get(key) if isinstance(companions.get(key), dict) else {}
    turn = st.get("turn_count", 0)
    entry = {
        "label": display_label or label,
        "kind": _clean_subject_text(subject.get("kind"), prev.get("kind") or "person", 20),
        "portrait_url": portrait_url,
        "prompt": (prompt or prev.get("prompt") or "")[:400],
        "scene": (scene or prev.get("scene") or "")[:300],
        "first_seen_turn": prev.get("first_seen_turn", turn),
        "last_seen_turn": turn,
        "seen_count": int(prev.get("seen_count") or 0) + 1,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "portrait_source": portrait_source or prev.get("portrait_source") or "",
        "portrait_gen": int(portrait_gen or prev.get("portrait_gen") or 0),
    }
    # Preserve the voice block if it was recorded first (voice +
    # portrait are resolved in parallel from Talk.start).
    if isinstance(prev.get("voice"), dict):
        entry["voice"] = prev["voice"]
    companions[key] = entry
    st["companions"] = companions
    # Link the portrait onto the character-memory record too, so the two views
    # (relationship notes + roster art) stay in sync.
    chars = st.get("characters")
    if isinstance(chars, dict) and isinstance(chars.get(key), dict):
        chars[key]["portrait_url"] = portrait_url
        st["characters"] = chars
    try:
        _save_state(st, session_id)
    except Exception as e:
        log_error(f"[COMPANION] save failed: {e}")
    return entry


def _record_companion_voice(session_id: str, subject: dict, voice: dict) -> None:
    """Store the voice data for a companion so their voice can be
    reused (by id) OR regenerated from scratch (by description) later.

    ``voice`` is the resolver output plus a couple of fields the caller knows::

        {
          "voice_id":     <str>,   # a Gemini voice name or a designed voice_...
          "description":  <str>,   # the design brief — REGENERATION seed
          "source":       <str>,   # designed / cache / fallback / override / ...
          "status":       <str>,
          "cache_key":    <str|None>,
          "model":        <str>,   # ttv model to regenerate with
          "settings":     <dict|None>,  # tts settings (stability/similarity/...)
        }

    Additive: creates a minimal companion stub if the portrait hasn't landed yet
    (voice + portrait are resolved in parallel), WITHOUT bumping seen_count or
    touching the portrait. Never raises.
    """
    subject = subject or {}
    display_label = re.sub(r"\s+", " ", str(subject.get("label") or "")).strip()[:40]
    label = _clean_subject_text(subject.get("label"), "", 40)
    if not label or not isinstance(voice, dict) or not voice.get("voice_id"):
        return
    try:
        st = _load_state(session_id) or {}
    except Exception:
        return
    companions = st.get("companions")
    if not isinstance(companions, dict):
        companions = {}
    key = label.lower()
    entry = companions.get(key) if isinstance(companions.get(key), dict) else {}
    # Don't downgrade a real designed-voice description to an empty one (e.g. a
    # later preset override): only overwrite the description when we have one.
    new_desc = (voice.get("description") or "").strip()
    voice_block = {
        "voice_id": voice.get("voice_id"),
        "description": new_desc or (entry.get("voice") or {}).get("description", ""),
        "source": voice.get("source") or "",
        "status": voice.get("status") or "",
        "cache_key": voice.get("cache_key"),
        "model": voice.get("model") or "",
        "settings": voice.get("settings") or (entry.get("voice") or {}).get("settings"),
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    entry = dict(entry)
    entry.setdefault("label", display_label or label)
    entry.setdefault("kind", _clean_subject_text(subject.get("kind"), "person", 20))
    entry["voice"] = voice_block
    companions[key] = entry
    st["companions"] = companions
    try:
        _save_state(st, session_id)
    except Exception as e:
        log_error(f"[COMPANION] voice save failed: {e}")


def _norm_box_from_subject(subject: Any, pad: float = 0.12) -> Optional[Dict[str, float]]:
    """SCAN bbox as a padded {x,y,w,h} in 0..1 source space.

    Detector boxes are a 0-1000 grid normalized to center+size on the wire
    (``cx``, ``cy``, ``w``, ``h``). The portrait crop has to come from that
    exact region or img2img invents a generic face from the whole plate.
    """
    if not isinstance(subject, dict):
        return None
    try:
        w = float(subject.get("w") or 0)
        h = float(subject.get("h") or 0)
        cx = float(subject["cx"]) if subject.get("cx") is not None else 0.5
        cy = float(subject["cy"]) if subject.get("cy") is not None else 0.5
    except (TypeError, ValueError):
        return None
    if w < 0.02 or h < 0.02 or (w >= 0.98 and h >= 0.98):
        return None
    pad = max(0.0, min(0.4, float(pad or 0)))
    pw = min(1.0, w * (1.0 + pad * 2.0))
    ph = min(1.0, h * (1.0 + pad * 2.0))
    x = max(0.0, min(1.0 - pw, cx - pw / 2.0))
    y = max(0.0, min(1.0 - ph, cy - ph / 2.0))
    return {"x": round(x, 5), "y": round(y, 5), "w": round(pw, 5), "h": round(ph, 5)}


def _crop_image_to_norm_box(path: str, box: Dict[str, float]) -> Optional[str]:
    """Crop ``path`` to a normalized box, keeping sub-pixel source coords."""
    if not path or not isinstance(box, dict):
        return path
    try:
        from PIL import Image
        x, y, w, h = float(box["x"]), float(box["y"]), float(box["w"]), float(box["h"])
    except Exception:
        return path
    if w <= 0.001 or h <= 0.001:
        return path
    try:
        im = Image.open(path)
        W, H = im.size
        if W < 8 or H < 8:
            return path
        left = max(0.0, min(float(W - 1), x * W))
        top = max(0.0, min(float(H - 1), y * H))
        right = max(left + 1.0, min(float(W), left + w * W))
        bottom = max(top + 1.0, min(float(H), top + h * H))
        cropped = im.crop((left, top, right, bottom))
        cropped.save(path)
        return path
    except Exception as e:
        log_error(f"[TALK PORTRAIT] bbox crop failed: {e}")
        return path


def _sighting_box(subject: Any) -> Optional[Dict[str, float]]:
    """The crop for an encounter's close-up of a sighted figure.

    The portrait crop (`_norm_box_from_subject`) pads a SCAN box a little;
    this one pads more and pulls the top up, the way the client's TALK crop
    does — detection boxes sit on the torso, and a standoff plate needs the
    face, the build and whatever they are holding.
    """
    box = _norm_box_from_subject(subject, pad=0.18)
    if not box:
        return None
    lift = min(box["y"], box["h"] * 0.35)
    box = dict(box)
    box["y"] = round(box["y"] - lift, 5)
    box["h"] = round(min(1.0 - box["y"], box["h"] + lift), 5)
    return box


# Below this the crop is a smear, and a smear captioned "copy this exact face"
# is worse than no close-up at all.
_SIGHTING_CROP_MIN_PX = 48
# ...and below this it is upscaled before it is attached (see _write_sighting_crop).
_SIGHTING_CROP_LEGIBLE_PX = 256


def _write_sighting_crop(im, box: Dict[str, float], label: str,
                         session_id: str = "default") -> Optional[str]:
    """Crop a PIL image to ``box`` and save it as this sighting's close-up."""
    try:
        from PIL import Image
        W, H = im.size
        left = max(0.0, min(float(W - 1), box["x"] * W))
        top = max(0.0, min(float(H - 1), box["y"] * H))
        right = max(left + 1.0, min(float(W), left + box["w"] * W))
        bottom = max(top + 1.0, min(float(H), top + box["h"] * H))
        if (right - left) < _SIGHTING_CROP_MIN_PX or (bottom - top) < _SIGHTING_CROP_MIN_PX:
            print(f"[ENCOUNTER] sighting close-up of {label!r} would be "
                  f"{int(right - left)}x{int(bottom - top)}px — too small, skipped",
                  flush=True)
            return None
        crop = im.convert("RGB").crop((left, top, right, bottom))
        # A far figure is a 50-pixel sliver, and the model attends to a
        # sliver about as well as a person would: the first live sighting
        # (52x127) came back dressed from the world's roster instead of from
        # its own pixels. Upscaling adds no information, but it makes the
        # attachment legible as a figure rather than a smudge.
        short = min(crop.size)
        if short < _SIGHTING_CROP_LEGIBLE_PX:
            scale = _SIGHTING_CROP_LEGIBLE_PX / float(short)
            crop = crop.resize((max(1, round(crop.size[0] * scale)),
                                max(1, round(crop.size[1] * scale))),
                               Image.LANCZOS)
        img_dir = Path(_get_image_dir(session_id))
        img_dir.mkdir(parents=True, exist_ok=True)
        path = img_dir / f"sighting_{_companion_slug(label)}_{int(time.time() * 1000)}.png"
        crop.save(path, "PNG", optimize=False)
        return str(path)
    except Exception as e:
        log_error(f"[ENCOUNTER] sighting crop failed: {e}")
        return None


def _crop_sighting_from_bytes(img_bytes: bytes, subject: dict,
                              session_id: str = "default") -> Optional[str]:
    """The sighted figure's close-up, cut from the frame the detector read."""
    box = _sighting_box(subject)
    if not box or not img_bytes:
        return None
    try:
        from PIL import Image
        import io as _io
        with Image.open(_io.BytesIO(img_bytes)) as im:
            return _write_sighting_crop(im, box, str(subject.get("label") or ""), session_id)
    except Exception as e:
        log_error(f"[ENCOUNTER] sighting crop (bytes) failed: {e}")
        return None


def _crop_sighting_from_path(frame_path: str, subject: dict,
                             session_id: str = "default") -> Optional[str]:
    """Same, from a frame on disk (the one the client posted to begin)."""
    box = _sighting_box(subject)
    if not box or not frame_path or not os.path.exists(str(frame_path)):
        return None
    try:
        from PIL import Image
        with Image.open(str(frame_path)) as im:
            return _write_sighting_crop(im, box, str(subject.get("label") or ""), session_id)
    except Exception as e:
        log_error(f"[ENCOUNTER] sighting crop (path) failed: {e}")
        return None


def _stage_encounter_sighting(st: dict, session_id: str, candidates: list,
                              img_bytes: Optional[bytes]) -> Optional[dict]:
    """A person in the picture IS the encounter. Called from api_detect,
    under the state lock, with the figures the detector found.

    Rolls ONE of them, cuts their close-up from the frame, and stages the
    sighting on state for this turn; returns what the client is told (or
    None when nothing fired — no figure, a fight already open, the cooldown
    after the last one, or the figure who just backed off still standing
    there). See encounter.sighting_can_fire.
    """
    import encounter as _encounter
    pool = list(candidates or [])
    if not pool:
        return None
    ok, why = _encounter.sighting_can_fire(st)
    # The first frame of a run with a goal is the view of where they are
    # going (goal.py). A person standing in that view used to open a
    # confrontation two seconds after it painted, and the player never saw
    # the goal at all. The view first; the street's people from turn one.
    if ok and str(st.get("goal_name") or "").strip() and int(st.get("turn_count") or 0) < 1:
        ok, why = False, "the opening view of the goal"
    if not ok:
        print(f"[ENCOUNTER] sighting: {len(pool)} figure(s) in frame, not firing ({why})",
              flush=True)
        return None
    pool = [c for c in pool if not _encounter.sighting_is_recent_antagonist(st, c.get("label"))]
    if not pool:
        print("[ENCOUNTER] sighting: only the figure the last encounter was with — "
              "not firing", flush=True)
        return None
    pick = _encounter.roll_sighting(pool)
    if not pick:
        return None
    crop = _crop_sighting_from_bytes(img_bytes, pick, session_id) if img_bytes else None
    public = _encounter.stage_sighting(st, pick, crop_path=crop or "", figures=len(pool))
    print(f"[ENCOUNTER] sighting: {len(pool)} figure(s) in frame — rolled "
          f"{pick.get('label')!r} ({public.get('kind')}, {public.get('distance')})"
          f"{' — close-up ' + os.path.basename(crop) if crop else ' — no close-up'}",
          flush=True)
    return public


def _current_frame_path(session_id: str = "default") -> Optional[str]:
    """The whole frame the player is looking at, as a file on disk.

    Used as the SECOND reference for a close-up: the crop says what the subject
    is, this says where it is. A close-up generated from the crop alone had no
    idea what surrounded it and invented a background, so diving on a truck door
    could return that door somewhere else entirely.

    Prefers the last painted flipbook panel over history, because on a flipbook
    turn the panel is what is actually on screen. Never returns a `_small`
    downsample or a crop; those are derived files, not the view.
    """
    try:
        st = _load_state(session_id) or {}
    except Exception:
        st = {}

    candidates = [st.get("flipbook_last_frame")]
    try:
        for entry in reversed(_load_history(session_id) or []):
            if not isinstance(entry, dict):
                continue
            if entry.get("choice") == "__encounter_resolve__":
                continue
            candidates.append(entry.get("guide_image") or entry.get("image"))
            if len(candidates) > 4:
                break
    except Exception:
        pass
    candidates.append(st.get("current_image_url"))

    for raw in candidates:
        if not raw:
            continue
        name = os.path.basename(str(raw))
        if name.endswith("_small.png") or name.startswith("portrait_ref_"):
            continue
        try:
            resolved = _resolve_image_path(str(raw), session_id)
        except Exception:
            continue
        if resolved and Path(resolved).is_file():
            return str(resolved)
    return None


def _save_portrait_reference(frame_b64: str, session_id: str = "default") -> Optional[str]:
    """Decode a client-captured scene frame (data URL) to a file for img2img.

    Read-only w.r.t. sim state (unlike ``_ingest_realtime_frame``): it just
    persists the frame so ``generate_gemini_img2img`` can hold likeness from
    the SCAN subject's bounding-box crop (or crop it server-side). Returns the
    file path, or None on a missing / malformed / too-small frame.
    """
    if not frame_b64:
        return None
    import base64 as _b64, re as _re
    m = _re.match(r'^data:image/[^;]+;base64,(.*)$', frame_b64, _re.DOTALL)
    raw = m.group(1) if m else frame_b64
    try:
        img_bytes = _b64.b64decode(raw)
    except Exception:
        return None
    if len(img_bytes) < 512:
        return None
    try:
        img_dir = Path(_get_image_dir(session_id))
        img_dir.mkdir(parents=True, exist_ok=True)
        fname = f"portrait_ref_{int(time.time() * 1000)}.png"
        fpath = img_dir / fname
        fpath.write_bytes(img_bytes)
        return str(fpath)
    except Exception as e:
        log_error(f"[TALK PORTRAIT] reference save failed: {e}")
        return None


def _portrait_cache_key(session_id: str, label: str, world_prompt: str, box: Any = None) -> tuple:
    scene_hash = hashlib.sha1((world_prompt or "").encode("utf-8")).hexdigest()[:16]
    crop = ""
    if isinstance(box, dict) and box.get("w"):
        crop = "{x:.3f}:{y:.3f}:{w:.3f}:{h:.3f}".format(
            x=float(box.get("x") or 0), y=float(box.get("y") or 0),
            w=float(box.get("w") or 0), h=float(box.get("h") or 0),
        )
    return (session_id or "default", (label or "").strip().lower(), scene_hash, crop)


# ───────── THE INTERACT CLOSE-UP, HANDED TO THE SCENE IT CAME OUT OF ─────────
# INTERACT is a Moment, not a turn: the dive opens a close-up of the thing the
# player tapped and the turn that regenerates the scene runs UNDERNEATH it. The
# client issues both on consecutive lines (openInteractMoment, then makeChoice),
# so they are two renders of the same subject started at the same instant, with
# neither aware of the other. The close-up is generated from that subject's own
# pixels; the scene is generated from a wide frame where the same subject is
# forty pixels tall. They do not agree, and the disagreement lands at the worst
# possible moment — the character the player has just been introduced to is a
# different person by the time the world is handed back.
#
# The close-up wins, because it is the picture the player was actually looking
# at. So the scene render waits for it and then carries it as an extra labeled
# reference, which is what makes the return a discovery rather than a recast.
#
# Both halves are threads in one server (api_choose's turn thread and
# api_talk_portrait's request thread), so the rendezvous is an in-process Event.
# It has to tolerate either side finishing first, because nothing orders them.
#: How long the scene render will hold for a close-up that is still developing.
#: Costs nothing in felt latency: the dive is on screen for the whole wait and
#: its own exits are already gated on this turn finishing.
INTERACT_PLATE_WAIT_S = float(os.getenv("INTERACT_PLATE_WAIT_S", "35"))
#: How long a published plate stays collectable. Long enough for a slow turn,
#: short enough that a TALK portrait from earlier in the run can never be
#: mistaken for this turn's discovery.
_INTERACT_PLATE_TTL_S = 90.0
#: session_id -> {"label", "event", "path", "expires", "taken"}
#:
#: `taken` means a waiter has CLAIMED this record, not that the record is
#: finished — the two are different and conflating them broke the ordinary
#: case. A waiter claims the record and then blocks on its Event, so a publish
#: landing during that block has to fill THAT record. Treating claimed as
#: finished sent the publish down the "nobody is waiting" path, where it set a
#: brand-new Event that nobody held, and the turn waited out the full timeout
#: while the plate it wanted sat in the map beside it.
_INTERACT_PLATES: dict = {}
_INTERACT_PLATE_LOCK = threading.Lock()


def _plate_labels_match(a: str, b: str) -> bool:
    """Whether two subject labels name the same thing.

    The turn is armed from the DETECTED label and the plate is published from
    whatever label `build_talk_context` settled on, which trims and re-cases
    it. Exact equality would spend the full timeout every time those two
    disagree by a definite article.
    """
    x, y = _permanence_subject(a), _permanence_subject(b)
    if not x or not y:
        return False
    return x == y or x in y or y in x


def _arm_interact_plate(session_id: str, label: str) -> None:
    """Declare that a close-up is coming, so the turn knows to wait for it.

    Called from api_choose on the INTERACT tap, and ONLY when the client says
    it actually opened a dive. That condition is the whole reason this is an
    explicit arm rather than something the render infers from `source`: the
    playtest harnesses drive `scan_interact` straight at the server with no
    client and no close-up, and a render that waited on the verb alone would
    add the full timeout to every one of those turns.
    """
    lab = _permanence_subject(label)
    if not lab:
        return
    with _INTERACT_PLATE_LOCK:
        rec = _INTERACT_PLATES.get(session_id)
        # The close-up can already be here: /api/talk/portrait answers a cache
        # hit instantly, and nothing orders it against this request. Arming
        # blind would throw that plate away and then wait for a second one that
        # is never generated.
        already = (
            rec is not None and not rec.get("taken")
            and rec["event"].is_set()
            and time.time() <= float(rec.get("expires") or 0)
            and _plate_labels_match(rec.get("label", ""), lab)
        )
        if already:
            print(f"[INTERACT PLATE] the close-up for '{lab}' is already here — "
                  f"nothing to wait for", flush=True)
            return
        _INTERACT_PLATES[session_id] = {
            "label": lab,
            "event": threading.Event(),
            "path": None,
            "expires": time.time() + _INTERACT_PLATE_TTL_S,
            "taken": False,
        }
    print(f"[INTERACT PLATE] armed for '{lab}' — this turn's scene will wait "
          f"for the close-up (up to {INTERACT_PLATE_WAIT_S:.0f}s)", flush=True)


def _publish_interact_plate(session_id: str, label: str, path: Optional[str]) -> None:
    """Hand a finished close-up to whatever turn is waiting for it.

    `path` is None when the portrait gave up — no crop arrived, generation is
    off, the budget is spent, a safety filter blocked it. Publishing the failure
    is deliberate and is half the point: without it a waiter sits out the entire
    timeout for a plate that was never coming, and INTERACT gets slower the more
    often the close-up fails.
    """
    lab = _permanence_subject(label)
    with _INTERACT_PLATE_LOCK:
        rec = _INTERACT_PLATES.get(session_id)
        live = rec is not None and time.time() <= float(rec.get("expires") or 0)
        if live and not rec["event"].is_set():
            if not _plate_labels_match(rec.get("label", ""), lab):
                # A TALK portrait finishing beside an unrelated INTERACT dive.
                # Overwriting would strand the waiter on an Event nobody sets.
                print(f"[INTERACT PLATE] ignoring a plate for '{lab}' — this "
                      f"session is waiting on '{rec.get('label')}'", flush=True)
                return
            # Fill the record the waiter is blocked on, whether or not it has
            # already claimed it.
            rec["path"] = path
            rec["expires"] = time.time() + _INTERACT_PLATE_TTL_S
            rec["event"].set()
        elif live and _plate_labels_match(rec.get("label", ""), lab):
            # Already settled for this subject — first answer wins, so a second
            # portrait for the same thing cannot swap the plate out from under
            # a render that is mid-flight.
            print(f"[INTERACT PLATE] '{lab}' is already settled; keeping the "
                  f"first close-up", flush=True)
            return
        else:
            # The close-up beat the turn to the rendezvous. Leave it where a
            # matching await can still collect it.
            ev = threading.Event()
            ev.set()
            _INTERACT_PLATES[session_id] = {
                "label": lab, "event": ev, "path": path,
                "expires": time.time() + _INTERACT_PLATE_TTL_S,
                "taken": False,
            }
    print(f"[INTERACT PLATE] published for '{lab}': "
          f"{os.path.basename(path) if path else 'nothing (the close-up failed)'}",
          flush=True)


def _await_interact_plate(session_id: str, source: Optional[str],
                          subject: Optional[str]) -> List[str]:
    """Block until this turn's INTERACT close-up exists, then return it.

    Returns a list because that is what the render takes, and because empty is
    the ordinary answer — every turn that is not an armed INTERACT tap returns
    immediately, having waited on nothing.
    """
    if source != "scan_interact":
        return []
    lab = _permanence_subject(subject or "")
    if not lab:
        return []
    with _INTERACT_PLATE_LOCK:
        rec = _INTERACT_PLATES.get(session_id)
        if (rec is None or rec.get("taken")
                or time.time() > float(rec.get("expires") or 0)
                or not _plate_labels_match(rec.get("label", ""), lab)):
            return []
        rec["taken"] = True
    t0 = time.time()
    if not rec["event"].wait(INTERACT_PLATE_WAIT_S):
        print(f"[INTERACT PLATE] gave up waiting for '{lab}' after "
              f"{INTERACT_PLATE_WAIT_S:.0f}s — the scene renders without it, so "
              f"the character may drift on the way back", flush=True)
        return []
    waited_ms = int((time.time() - t0) * 1000)
    path = rec.get("path")
    if not path:
        print(f"[INTERACT PLATE] no close-up for '{lab}' ({waited_ms}ms) — "
              f"nothing to carry into the scene", flush=True)
        return []
    resolved = _resolve_image_path(path, session_id)
    if not resolved or not resolved.exists():
        print(f"[INTERACT PLATE] close-up for '{lab}' does not resolve on disk: "
              f"{path}", flush=True)
        return []
    print(f"[INTERACT PLATE] held the scene {waited_ms}ms for '{lab}' — "
          f"{resolved.name} rides into the return frame", flush=True)
    return [str(resolved)]


def api_talk_portrait():
    """Generate (or reuse) a cinematic medium-shot portrait for a TALK subject.

    Request JSON: ``{"subject": {"label","kind","speaks","cx","cy","w","h"},
                     "session_id"?, "reference_image"?: <data-url>,
                     "reference_cropped"?: bool}``
    Response JSON: ``{"image_url": "/images/...", "cached": bool, "prompt": str,
                      "mode": "img2img"|"crop"}``
      or ``{"image_url": null, "reason": "..."}`` when no crop arrived.

    The SCAN bounding-box crop is the likeness reference. We img2img it into
    a cinematic medium-shot portrait (``portrait_mode`` + ``subject_crop``).
    A crop-only return is the fallback when generate is disabled or fails.
    Cache is per ``(session, subject, scene, box)``.
    """
    try:
        if _rate_limited("talk_portrait", 1.2):
            return jsonify({"image_url": None, "reason": "slow_down"}), 429
        data = request.get_json(silent=True) or {}
        subject = data.get("subject") or {}
        session_id = data.get("session_id", "default")
        reference_b64 = data.get("reference_image") or ""
        reference_cropped = bool(data.get("reference_cropped"))
        if not isinstance(subject, dict) or not (subject.get("label") or "").strip():
            return jsonify({"error": "missing subject", "image_url": None}), 400

        # Reuse the same briefing Talk built for the persona, but skip BOTH
        # the opening-line LLM call (opening_override=".") AND the vision
        # snapshot (include_vision=False): the portrait only needs the subject
        # + scene, and it runs concurrently with the session's own
        # build_talk_context, so repeating the two Gemini vision calls here
        # would just double the time-to-portrait for no benefit.
        context = build_talk_context(
            subject, session_id, opening_override=".", include_vision=False,
        )
        if context.get("opening_line") == ".":
            context["opening_line"] = ""

        label = context["subject"]["label"]
        try:
            world_prompt = str((_load_state(session_id) or {}).get("world_prompt") or "")
        except Exception:
            world_prompt = ""

        crop_box = _norm_box_from_subject(subject)
        if crop_box is None and isinstance(data.get("box"), dict):
            try:
                raw = data["box"]
                crop_box = {
                    "x": float(raw["x"]), "y": float(raw["y"]),
                    "w": float(raw["w"]), "h": float(raw["h"]),
                }
                if crop_box["w"] <= 0.001 or crop_box["h"] <= 0.001:
                    crop_box = None
            except (KeyError, TypeError, ValueError):
                crop_box = None
        cache_key = _portrait_cache_key(session_id, label, world_prompt, crop_box)

        with _PORTRAIT_CACHE_LOCK:
            cached = _PORTRAIT_CACHE.get(cache_key)
        if cached:
            # A cache hit is still this turn's close-up, and a waiting scene
            # render is entitled to it — arriving instantly is not a reason to
            # let the character drift.
            _publish_interact_plate(session_id, label, cached)
            return jsonify({"image_url": cached, "cached": True, "subject": context["subject"]})

        ref_path = _save_portrait_reference(reference_b64, session_id) if reference_b64 else None
        if ref_path and crop_box and not reference_cropped:
            cropped = _crop_image_to_norm_box(ref_path, crop_box)
            if cropped and cropped != ref_path:
                try:
                    Path(ref_path).unlink(missing_ok=True)
                except Exception:
                    pass
                ref_path = cropped
        if not ref_path:
            # Tell a waiting INTERACT turn it is waiting for nothing, or the
            # scene sits out the whole timeout before rendering anyway.
            _publish_interact_plate(session_id, label, None)
            return jsonify({
                "image_url": None,
                "reason": "no_crop",
                "subject": context["subject"],
            })

        # Resolved before the prompt is built, because the prompt has to describe
        # the references it is actually being handed.
        wide_ref = _current_frame_path(session_id)
        if wide_ref and str(wide_ref) == str(ref_path):
            wide_ref = None
        prompt = build_portrait_prompt(context, img2img=True,
                                       with_wide=bool(wide_ref))
        is_figure = _talk_subject_is_figure(context["subject"])
        tod = ""
        try:
            tod = str((_load_state(session_id) or {}).get("time_of_day") or "")
        except Exception:
            tod = ""
        image_path = None
        gen_mode = "crop"
        spent = False
        if IMAGE_ENABLED:
            with _PORTRAIT_CACHE_LOCK:
                spend = int(_PORTRAIT_SPEND.get(session_id, 0))
            if spend < CONVERSATION_PORTRAIT_BUDGET:
                t0 = time.time()
                # Two references, in this order: the subject's own pixels first,
                # then the whole frame it was standing in.
                #
                # The crop alone gave a close-up that looked like the right thing
                # and lived nowhere — the model had no idea what surrounded it, so
                # it invented a background, and the dive read as a cut to another
                # location instead of a look at something in THIS place. The wide
                # frame carries the light, the palette, the weather and the
                # architecture behind the subject. Crop leads because Gemini
                # weights the first reference most and identity has to win: the
                # wide is context, not the subject, and the prompt says so.
                refs_for_portrait = [str(ref_path)]
                if wide_ref:
                    refs_for_portrait.append(str(wide_ref))
                    print(f"[TALK PORTRAIT] crop + wide "
                          f"({os.path.basename(str(wide_ref))}) so the close-up "
                          f"stays in this place", flush=True)
                try:
                    from gemini_image_utils import generate_gemini_img2img
                    image_path = generate_gemini_img2img(
                        prompt=prompt,
                        caption=f"talk_portrait_{_companion_slug(label)}",
                        reference_image_path=refs_for_portrait,
                        strength=0.58,
                        world_prompt=None,
                        time_of_day=tod,
                        hd_mode=False,
                        output_dir=Path(_get_image_dir(session_id)),
                        portrait_mode=True,
                        subject_crop=True,
                        object_subject=not is_figure,
                    )
                    if image_path:
                        gen_mode = "img2img"
                        spent = True
                except Exception as gen_err:
                    log_error(f"[TALK PORTRAIT] generate failed: {gen_err}")
                    image_path = None
                try:
                    cost_tracker.record_usage(
                        session_id, "image", "gemini", "talk_portrait",
                        operation=f"talk_portrait_{gen_mode}",
                        output_units=1.0 if image_path else 0,
                        unit_type="images",
                        latency_ms=int((time.time() - t0) * 1000),
                        success=bool(image_path),
                        error_message=None if image_path else "no_image_returned",
                    )
                except Exception:
                    pass
        if spent:
            with _PORTRAIT_CACHE_LOCK:
                _PORTRAIT_SPEND[session_id] = int(_PORTRAIT_SPEND.get(session_id, 0)) + 1

        plate = image_path or ref_path
        companion = None
        web = None
        durable_url = None
        try:
            durable_url = _persist_companion_image(plate, session_id, label)
            web = durable_url or _to_web_image_url(plate, session_id)
            if web:
                companion = _record_companion(
                    session_id, context["subject"], web,
                    prompt=prompt if gen_mode == "img2img" else "",
                    scene=world_prompt,
                    portrait_source=gen_mode,
                    portrait_gen=COMPANION_PORTRAIT_GEN,
                )
        except Exception as comp_err:
            log_error(f"[COMPANION] record from portrait failed: {comp_err}")
            web = web or _to_web_image_url(plate, session_id)
        finally:
            if ref_path:
                try:
                    rp = Path(ref_path)
                    if rp.name.startswith("portrait_ref_"):
                        rp.unlink(missing_ok=True)
                except Exception:
                    pass

        # The DURABLE copy, not `plate`: the raw generation is sweepable and a
        # client crop is JPEG bytes, while companion_<slug>.png is a real PNG
        # kept for exactly this — re-referencing the character into later
        # scenes (see _persist_companion_image).
        _publish_interact_plate(session_id, label, durable_url or (web if web else None))

        if not web:
            return jsonify({"image_url": None, "reason": "no_image",
                            "subject": context["subject"]})

        with _PORTRAIT_CACHE_LOCK:
            _PORTRAIT_CACHE[cache_key] = web

        return jsonify({
            "image_url": web,
            "cached": False,
            "mode": gen_mode,
            "prompt": prompt if gen_mode == "img2img" else "",
            "subject": context["subject"],
            "companion": ({
                "label": companion.get("label"),
                "portrait_url": companion.get("portrait_url"),
                "seen_count": companion.get("seen_count"),
                "first_seen": companion.get("seen_count") == 1,
            } if companion else None),
        })
    except Exception as e:
        log_error(f"[TALK PORTRAIT] failed: {e}")
        # Same reason the no_crop path publishes: a turn holding for a close-up
        # that has just crashed should render now, not in thirty-five seconds.
        try:
            _publish_interact_plate(
                data.get("session_id", "default") if isinstance(data, dict) else "default",
                ((data.get("subject") or {}).get("label") if isinstance(data, dict) else "") or "",
                None,
            )
        except Exception:
            pass
        return jsonify({"image_url": None, "reason": "error", "error": str(e)}), 500


# How many lines of a conversation the consequence prompt is shown. Enough to
# carry what was actually agreed, refused or let slip; short enough that the
# exchange informs the beat instead of becoming the beat.
CONVERSATION_TURN_LINES = 12


def _record_turn_conversation(session_id: str, label: str, lines) -> None:
    """Stamp the conversation that just ended onto state, for THIS turn.

    Talking to someone used to change nothing: the transcript lived in the
    browser, `/api/talk/end` counted the conversation and threw the words
    away, and the next turn was generated as though the player had stood
    there in silence. This is the record the consequence reads.

    Stamped with the turn it belongs to so it can only ever inform the turn
    the conversation caused — a stale exchange must not colour a beat three
    moves later (see `_conversation_for_turn`).
    """
    cleaned = []
    for item in (lines or [])[-CONVERSATION_TURN_LINES:]:
        if not isinstance(item, dict):
            continue
        text = re.sub(r"\s+", " ", str(item.get("text") or "")).strip()[:300]
        if not text:
            continue
        who = "them" if str(item.get("role") or "") != "user" else "you"
        cleaned.append({"role": who, "text": text})
    if not cleaned:
        return
    with WORLD_STATE_LOCK:
        st = _load_state(session_id) or {}
        st["last_conversation"] = {
            "with": (label or "").strip()[:60],
            "turn": st.get("turn_count", 0),
            "lines": cleaned,
        }
        _save_state(st, session_id)
        _sync_ambient_state(st, session_id)
    print(f"[TALK TURN] conversation with '{label}' ({len(cleaned)} lines) "
          f"is driving turn {st.get('turn_count', 0)}", flush=True)


def _conversation_for_turn(state: dict) -> Optional[dict]:
    """The conversation this turn is the consequence of, or None.

    The turn counter has not advanced yet when the consequence is written, so
    a record stamped with the current count is the one the player just had.
    Anything older belongs to a turn that has already been answered.
    """
    rec = (state or {}).get("last_conversation")
    if not isinstance(rec, dict) or not rec.get("lines"):
        return None
    if rec.get("turn") != (state or {}).get("turn_count", 0):
        return None
    return rec


def _conversation_directive(state: dict) -> str:
    """What the consequence must make of the conversation just had."""
    rec = _conversation_for_turn(state)
    if not rec:
        return ""
    who = rec.get("with") or "the person they were talking to"
    said = "\n".join(
        f"  {'PLAYER' if ln.get('role') == 'you' else who.upper()}: {ln.get('text')}"
        for ln in rec.get("lines") or []
    )
    return (
        f"\n\nTHE CONVERSATION THE PLAYER JUST HAD with the {who} — this "
        f"exchange IS the action of this turn:\n{said}\n"
        f"Write what the conversation CHANGED. Something has to be different "
        f"because it happened: they were told where to go, warned off, lied "
        f"to, given a thing, followed, believed, refused, or noticed by "
        f"someone else while they stood there talking. Take the most "
        f"consequential specific thing that was said and make it land in the "
        f"world — a door that is now open, a name that now means something, a "
        f"direction the player now has, a debt they now owe.\n"
        f"Never answer with the conversation simply ending. The {who} is still "
        f"here and `visual_scene` must show them: this is the moment after "
        f"they stopped talking, not a cut to somewhere else.\n"
    )


def _record_character_memory(session_id: str, subject: dict, note: str = "") -> dict:
    """Upsert a lightweight per-character memory record on session state.

    Additive metadata only — does not mutate ``history`` / ``feed_log`` / the
    sim turn. Powers future trust/relationship Moments without requiring a
    full NPC database today.
    """
    subject = subject or {}
    display_label = re.sub(r"\s+", " ", str(subject.get("label") or "")).strip()[:40]
    label = _clean_subject_text(subject.get("label"), "", 40)
    if not label:
        return {}
    try:
        st = _load_state(session_id) or {}
    except Exception:
        return {}
    chars = st.get("characters")
    if not isinstance(chars, dict):
        chars = {}
    key = label.lower()
    entry = chars.get(key) if isinstance(chars.get(key), dict) else {}
    first_met = entry.get("first_met_turn")
    if first_met is None:
        first_met = st.get("turn_count", 0)
    notes = list(entry.get("notes") or [])
    clean_note = (note or "").strip()[:240]
    if clean_note and (not notes or notes[-1] != clean_note):
        notes.append(clean_note)
        notes = notes[-8:]  # keep a short rolling window
    entry = {
        # Prefer the player's original casing for display; key stays lowercased.
        "label": display_label or label,
        "kind": _clean_subject_text(subject.get("kind"), entry.get("kind") or "person", 20),
        "first_met_turn": first_met,
        "last_talk_turn": st.get("turn_count", 0),
        "talk_count": int(entry.get("talk_count") or 0) + 1,
        "notes": notes,
        "trust": int(entry.get("trust") or 0),
    }
    chars[key] = entry
    st["characters"] = chars
    try:
        _save_state(st, session_id)
    except Exception as e:
        log_error(f"[TALK] character memory save failed: {e}")
    return entry


def api_companions():
    """List the player's companion roster — characters they've spoken with,
    stored with their cinematic portrait so they can be placed into later
    scenes for a continuing story.

    GET /api/companions?session_id=<id>
    Response: ``{"companions": [{label, kind, portrait_url, seen_count,
      first_seen_turn, last_seen_turn, trust, notes}, ...]}`` — most recently
    seen first.
    """
    try:
        session_id = request.args.get("session_id", "default")
        try:
            st = _load_state(session_id) or {}
        except Exception:
            st = {}
        companions = st.get("companions") or {}
        chars = st.get("characters") or {}
        out = []
        for key, c in companions.items():
            if not isinstance(c, dict):
                continue
            mem = chars.get(key) if isinstance(chars.get(key), dict) else {}
            out.append({
                "label": c.get("label"),
                "kind": c.get("kind"),
                "portrait_url": c.get("portrait_url"),
                "seen_count": c.get("seen_count"),
                "first_seen_turn": c.get("first_seen_turn"),
                "last_seen_turn": c.get("last_seen_turn"),
                "trust": mem.get("trust", 0),
                "notes": (mem.get("notes") or [])[-3:],
                # Voice data: reuse by voice_id, or regenerate from the design
                # description + model.
                "voice": c.get("voice") or None,
            })
        out.sort(key=lambda r: (r.get("last_seen_turn") or 0), reverse=True)
        return jsonify({"companions": out})
    except Exception as e:
        log_error(f"[COMPANION] list failed: {e}")
        return jsonify({"companions": [], "error": str(e)}), 500


def api_companion_place():
    """Place a stored companion INTO a scene — the primitive for continuing-
    story beats where a known character reappears in the world.

    Request JSON: ``{"label": <str>, "session_id"?, "reference_image"?:
      <data-url of the current frame>, "prompt"?: <what they're doing>}``
    Response: ``{"image_url": "/images/...", "label": <str>}`` — a scene
      featuring the companion, img2img'd from [current frame + companion
      portrait] so they read as the same character standing in this place. On
      any failure returns ``{"image_url": null, "reason": "..."}``.
    """
    try:
        if _rate_limited("companion_place", 1.2):
            return jsonify({"image_url": None, "reason": "slow_down"}), 429
        data = request.get_json(silent=True) or {}
        session_id = data.get("session_id", "default")
        label = _clean_subject_text(data.get("label"), "", 40)
        if not label:
            return jsonify({"error": "missing label", "image_url": None}), 400
        if not IMAGE_ENABLED:
            return jsonify({"image_url": None, "reason": "image_disabled"})

        st = _load_state(session_id) or {}
        companions = st.get("companions") or {}
        comp = companions.get(label.lower())
        if not isinstance(comp, dict) or not comp.get("portrait_url"):
            return jsonify({"image_url": None, "reason": "unknown_companion"})
        portrait_path = _resolve_image_path(comp["portrait_url"], session_id)
        if not portrait_path or not portrait_path.exists():
            return jsonify({"image_url": None, "reason": "portrait_missing"})

        who = comp.get("label") or label
        action = _clean_subject_text(data.get("prompt"), "", 200) or \
            (who + " is here in this place with you")
        world_prompt = str(st.get("world_prompt") or "")
        tod = str(st.get("time_of_day") or "")

        # References: the current frame FIRST (environment ground truth), the
        # companion portrait SECOND (who they are) — so the companion appears in
        # this place, consistent with how they looked in conversation.
        refs = []
        ref_frame = _save_portrait_reference(data.get("reference_image") or "", session_id)
        if ref_frame:
            refs.append(ref_frame)
        refs.append(str(portrait_path))

        place_prompt = _sanitize_for_image_generation(
            "In this environment, " + who + " is present: " + action + ". "
            "Keep this location, lighting, palette, and film grain; show them "
            "naturally within the scene."
        )
        t0 = time.time()
        image_path = None
        try:
            from gemini_image_utils import generate_gemini_img2img
            image_path = generate_gemini_img2img(
                prompt=place_prompt,
                caption=f"place_{_companion_slug(who)}",
                reference_image_path=refs,
                strength=0.5,
                world_prompt=world_prompt[:400] if world_prompt else None,
                time_of_day=tod,
                hd_mode=False,
                output_dir=Path(_get_image_dir(session_id)),
                portrait_mode=True,  # person-allowed (skip the anti-person removal)
            )
        except Exception as gen_err:
            log_error(f"[COMPANION] place generate failed: {gen_err}")
            return jsonify({"image_url": None, "reason": "generate_failed"})
        finally:
            if ref_frame:
                try:
                    Path(ref_frame).unlink(missing_ok=True)
                    _small = Path(ref_frame).with_name(
                        Path(ref_frame).name.replace(".png", "_small.png"))
                    if _small.exists():
                        _small.unlink(missing_ok=True)
                except Exception:
                    pass

        web = _to_web_image_url(image_path, session_id)
        try:
            cost_tracker.record_usage(
                session_id, "image", "gemini", "companion_place",
                operation="companion_place", output_units=1.0 if web else 0,
                unit_type="images", latency_ms=int((time.time() - t0) * 1000),
                success=bool(web), error_message=None if web else "no_image_returned",
            )
        except Exception:
            pass
        if not web:
            return jsonify({"image_url": None, "reason": "no_image"})
        # Bump the roster's last-seen so recency reflects the reappearance.
        try:
            _record_companion(session_id, {"label": who, "kind": comp.get("kind")},
                              comp["portrait_url"])
        except Exception:
            pass
        return jsonify({"image_url": web, "label": who})
    except Exception as e:
        log_error(f"[COMPANION] place failed: {e}")
        return jsonify({"image_url": None, "reason": "error", "error": str(e)}), 500


def _watch_companion_voice_regen(session_id: str, subject: dict, cache_key: str,
                                 description: str, model: str) -> None:
    """Daemon: when a regen design lands, write the new voice_id onto the
    companion roster so later TALK reuses it. Best-effort; never raises."""
    def _run():
        try:
            import voice_design as _vd
        except Exception:
            return
        for _ in range(90):
            try:
                time.sleep(1.0)
                st = _vd.get_status(cache_key) or {}
                status = st.get("status")
                if status == "ready" and st.get("voice_id"):
                    _record_companion_voice(session_id, subject, {
                        "voice_id": st["voice_id"],
                        "description": description,
                        "source": "designed",
                        "status": "ready",
                        "cache_key": cache_key,
                        "model": model,
                    })
                    return
                if status in ("failed", "unknown"):
                    return
            except Exception:
                return
    try:
        threading.Thread(
            target=_run, name=f"companion-voice-regen-{cache_key}", daemon=True
        ).start()
    except Exception:
        pass


def api_companion_regenerate_voice():
    """Regenerate a companion's voice from their stored design description — the seed persisted by ``api_talk_session``.

    Request JSON: ``{"label": <str>, "session_id"?, "wait"?: <seconds>}``
    Response: ``{"label", "voice": {voice_id, description, source, status,
      cache_key, model}, "reason"?}``. Poll ``/api/talk/voice/status`` with
    the returned ``cache_key`` when ``status == "generating"``.
    """
    try:
        if _rate_limited("companion_regen_voice", 2.0):
            return jsonify({"voice": None, "reason": "slow_down"}), 429
        data = request.get_json(silent=True) or {}
        session_id = data.get("session_id", "default")
        label = _clean_subject_text(data.get("label"), "", 40)
        if not label:
            return jsonify({"error": "missing label", "voice": None}), 400
        try:
            wait = float(data.get("wait") or 0.0)
        except (TypeError, ValueError):
            wait = 0.0
        wait = max(0.0, min(wait, 45.0))

        st = _load_state(session_id) or {}
        companions = st.get("companions") or {}
        comp = companions.get(label.lower())
        if not isinstance(comp, dict):
            return jsonify({"voice": None, "reason": "unknown_companion",
                            "label": label})
        voice = comp.get("voice") if isinstance(comp.get("voice"), dict) else {}
        description = (voice.get("description") or "").strip()
        if len(description) < 20:
            return jsonify({"voice": None, "reason": "no_description",
                            "label": label})

        try:
            import voice_design as _vd
        except Exception:
            return jsonify({"voice": None, "reason": "voice_design_unavailable",
                            "label": label})
        if not _vd.is_available():
            return jsonify({"voice": None, "reason": "voice_design_disabled",
                            "label": label})

        subject = {
            "label": comp.get("label") or label,
            "kind": comp.get("kind") or "person",
        }
        world_prompt = str(st.get("world_prompt") or "")
        model = (voice.get("model") or getattr(_vd, "MODEL", "") or "").strip()
        old_voice_id = (voice.get("voice_id") or "").strip() or None

        result = _vd.regenerate_voice(
            subject, session_id, description,
            world_prompt=world_prompt,
            old_voice_id=old_voice_id,
            wait=wait,
        )
        if not result:
            return jsonify({"voice": None, "reason": "regenerate_failed",
                            "label": label})

        out_voice = {
            "voice_id": result.get("voice_id"),
            "description": description,
            "source": result.get("source") or "",
            "status": result.get("status") or "",
            "cache_key": result.get("cache_key"),
            "model": model,
        }
        if result.get("status") == "ready" and result.get("voice_id"):
            _record_companion_voice(session_id, subject, {
                "voice_id": result["voice_id"],
                "description": description,
                "source": "designed",
                "status": "ready",
                "cache_key": result.get("cache_key"),
                "model": model,
            })
            out_voice["source"] = "designed"
            out_voice["status"] = "ready"
        elif result.get("status") == "generating" and result.get("cache_key"):
            _watch_companion_voice_regen(
                session_id, subject, result["cache_key"], description, model
            )

        return jsonify({"label": subject["label"], "voice": out_voice})
    except Exception as e:
        log_error(f"[COMPANION] regenerate_voice failed: {e}")
        return jsonify({"voice": None, "reason": "error", "error": str(e)}), 500


# ---------------------------------------------------------------------------
# Persistent props (jeep, etc.) — companion-shaped durable references
# ---------------------------------------------------------------------------

def _persist_prop_image(image_path: str, session_id: str, slug: str) -> Optional[str]:
    """Copy a freshly-generated prop image to a STABLE, sweep-protected file
    (``prop_<slug>.png``) so it survives and can be re-referenced forever.

    Mirrors ``_persist_companion_image``. Returns the web URL of the durable
    copy, or None on failure.
    """
    try:
        src = _resolve_image_path(image_path)
        if not src or not src.exists():
            return None
        img_dir = Path(_get_image_dir(session_id))
        img_dir.mkdir(parents=True, exist_ok=True)
        safe = re.sub(r"[^a-z0-9]+", "_", (slug or "").strip().lower()).strip("_") or "prop"
        safe = safe[:40]
        dst = img_dir / f"prop_{safe}.png"
        import shutil as _shutil
        _shutil.copyfile(str(src), str(dst))
        try:
            small_src = src.with_name(src.name.replace(".png", "_small.png"))
            if small_src.exists():
                _shutil.copyfile(str(small_src), str(img_dir / f"prop_{safe}_small.png"))
        except Exception:
            pass
        return _to_web_image_url(f"prop_{safe}.png", session_id)
    except Exception as e:
        log_error(f"[PROP] persist image failed: {e}")
        return None


def _record_prop(session_id: str, slug: str, portrait_url: str,
                 label: str = "", prompt: str = "") -> dict:
    """Upsert a PROP into ``state.props`` — a companion-shaped sibling dict for
    durable recognizable objects (the red jeep, etc.). Additive metadata; does
    not touch turn_count/history. Returns the prop record (JSON-safe).
    """
    safe = re.sub(r"[^a-z0-9]+", "_", (slug or "").strip().lower()).strip("_")
    if not safe or not portrait_url:
        return {}
    try:
        st = _load_state(session_id) or {}
    except Exception:
        return {}
    props = st.get("props")
    if not isinstance(props, dict):
        props = {}
    prev = props.get(safe) if isinstance(props.get(safe), dict) else {}
    turn = st.get("turn_count", 0)
    entry = {
        "label": (label or prev.get("label") or safe).strip()[:60],
        "slug": safe,
        "portrait_url": portrait_url,
        "prompt": (prompt or prev.get("prompt") or "")[:400],
        "first_seen_turn": prev.get("first_seen_turn", turn),
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    props[safe] = entry
    st["props"] = props
    try:
        _save_state(st, session_id)
    except Exception as e:
        log_error(f"[PROP] save failed: {e}")
    return entry


def _ensure_jeep_prop(session_id: str) -> dict:
    """Return the durable jeep prop record, generating it once if missing.

    Always prefers the persisted ``prop_jeep.png`` on disk so the vehicle stays
    visually identical across every CAMP (and future mission-transition) visit.
    """
    try:
        st = _load_state(session_id) or {}
    except Exception:
        st = {}
    props = st.get("props") if isinstance(st.get("props"), dict) else {}
    jeep = props.get("jeep") if isinstance(props.get("jeep"), dict) else {}
    url = jeep.get("portrait_url") or ""
    if url:
        path = _resolve_image_path(url)
        if path and path.exists():
            return jeep

    # Also accept a leftover durable file from a prior run whose state lost the
    # props block (e.g. state reset but images kept).
    durable = Path(_get_image_dir(session_id)) / "prop_jeep.png"
    if durable.exists():
        web = _to_web_image_url("prop_jeep.png", session_id)
        return _record_prop(session_id, "jeep", web,
                            label="your red jeep", prompt=_JEEP_PROP_PROMPT)

    if not IMAGE_ENABLED:
        return {}

    t0 = time.time()
    image_path = None
    try:
        from gemini_image_utils import generate_with_gemini
        image_path = generate_with_gemini(
            prompt=_sanitize_for_image_generation(_JEEP_PROP_PROMPT),
            caption="prop_jeep",
            world_prompt=None,
            aspect_ratio="4:3",  # match game stills / camp plates
            time_of_day="dusk, desert evening light",
            hd_mode=False,
            output_dir=Path(_get_image_dir(session_id)),
            portrait_mode=False,  # vehicle plate — anti-person is correct
        )
    except Exception as gen_err:
        log_error(f"[PROP] jeep generate failed: {gen_err}")
        try:
            cost_tracker.record_usage(
                session_id, "image", "gemini", "prop_jeep",
                operation="prop_jeep", output_units=0, unit_type="images",
                latency_ms=int((time.time() - t0) * 1000), success=False,
                error_message=str(gen_err)[:200],
            )
        except Exception:
            pass
        return {}

    web = _to_web_image_url(image_path, session_id) if image_path else None
    try:
        cost_tracker.record_usage(
            session_id, "image", "gemini", "prop_jeep",
            operation="prop_jeep", output_units=1.0 if web else 0,
            unit_type="images", latency_ms=int((time.time() - t0) * 1000),
            success=bool(web), error_message=None if web else "no_image_returned",
        )
    except Exception:
        pass
    if not web:
        return {}
    durable_url = _persist_prop_image(image_path, session_id, "jeep") or web
    return _record_prop(session_id, "jeep", durable_url,
                        label="your red jeep", prompt=_JEEP_PROP_PROMPT)


def _active_world_sig(session_id: str = "default") -> str:
    """Which world this session is standing in, for cache keys.

    Belt to the purge's braces. `purge_run_caches` is what actually stops the
    previous world's pictures reappearing, but a purge is a thing somebody has
    to remember to call, and the failure is silent and looks like the image
    model misbehaving. A world in the key means that even a missed purge cannot
    return another world's picture — it can only cost a regeneration.
    """
    try:
        st = get_state(session_id) or {}
    except Exception:
        return ""
    return f"{st.get('experience_id') or ''}/{st.get('experience_world_id') or ''}"


def _camp_cache_key(session_id: str, labels: list, jeep_url: str) -> tuple:
    labels_sig = ",".join(sorted((l or "").strip().lower() for l in labels))
    jeep_hash = hashlib.sha1((jeep_url or "").encode("utf-8")).hexdigest()[:12]
    # The world belongs in here. This key was the session, the roster and the
    # jeep — nothing that changes when the player walks into a different world,
    # so the same five companions sat around the previous world's fire in the
    # new one.
    return (session_id or "default", _CAMP_CACHE_VERSION,
            _active_world_sig(session_id), labels_sig, jeep_hash)


def _camp_seat_layout(count: int) -> list:
    n = max(0, min(int(count or 0), 5))
    if n <= 0:
        return []
    return list(_CAMP_SEATS.get(n) or _CAMP_SEATS[5][:n])


def _collect_camp_companions(session_id: str, st: dict) -> list:
    """Every companion with a resolvable portrait file for CAMP img2img.

    Reads ``state.companions`` and resolves each ``portrait_url`` against the
    session images dir (the bug that dropped the whole cast was resolving
    ``/images/companion_*.png`` against the legacy root images/ folder). Also
    scans the session dir for any durable ``companion_*.png`` files missing
    from state so on-disk roster art still makes it into the fire circle.
    """
    companions = st.get("companions") if isinstance(st.get("companions"), dict) else {}
    roster = []
    seen_paths = set()

    def _add(label, kind, portrait_url, last_seen_turn=0):
        path = _resolve_image_path(portrait_url, session_id) if portrait_url else None
        if not path or not path.exists():
            return
        # Prefer full-res companion plate over the _small downsample for likeness.
        key = str(path.resolve()) if path.exists() else str(path)
        if key in seen_paths:
            return
        seen_paths.add(key)
        roster.append({
            "label": label or "figure",
            "kind": kind or "person",
            "portrait_url": portrait_url or _to_web_image_url(path.name, session_id),
            "portrait_path": str(path),
            "last_seen_turn": int(last_seen_turn or 0),
        })

    for key, c in companions.items():
        if not isinstance(c, dict):
            continue
        gen = int(c.get("portrait_gen") or 0)
        src = str(c.get("portrait_source") or "")
        if gen < COMPANION_PORTRAIT_GEN and src != "crop":
            continue
        _add(
            c.get("label") or key,
            c.get("kind") or "person",
            c.get("portrait_url"),
            c.get("last_seen_turn") or 0,
        )

    # No disk-orphan import. Old invented plates (player-as-Watcher) lived
    # only as companion_*.png and used to walk into CAMP.

    roster.sort(key=lambda r: (r.get("last_seen_turn") or 0), reverse=True)
    return roster


def _build_camp_prompt(attendees: list, jeep_included: bool,
                       ref_map: list = None) -> str:
    """Prompt for the camp establishing shot — night fire + jeep + cast.

    ``ref_map`` is an ordered list of ``{"index", "role", "label"}`` describing
    each img2img reference image (1-based), so Gemini knows reference #1 is the
    jeep and #2..N are specific companion portraits — not anonymous faces.
    """
    attendee_labels = [a.get("label") for a in (attendees or []) if a.get("label")]
    # Camp is a fixed Moment, but its art direction is NOT the engine's business
    # — it was a wall of hardcoded strings in here, which meant the one scene the
    # game composes for you was the one scene you could not direct. It now comes
    # from the `camp_scene_prompt` key like any other look, with the runtime
    # facts substituted in. Terrain follows the level when one is authored.
    terrain = game_identity.place_summary() or "remote Four Corners high-desert scrub"
    # Who is at the fire. The names have to be enumerated here because the image
    # model is being handed exactly these portraits as references.
    if attendee_labels:
        who = (
            f"ALL of these companions are present around the flames (no extras, "
            f"none missing): {', '.join(attendee_labels)}. Arrange them in a "
            f"natural arc around the fire, faces firelit and readable, leaving "
            f"the jeep clearly visible on the right. This is a cast reunion — "
            f"every named companion must be visibly in frame."
        )
    else:
        who = "No people — a quiet empty camp. Only the fire and the red jeep."

    authored = (PROMPTS.get("camp_scene_prompt") or "").strip()
    if authored:
        try:
            bits = authored.format(
                vantage=game_identity.vantage().capitalize(),
                terrain=terrain,
                who=who,
            ).split("\n")
        except (KeyError, IndexError, ValueError) as fmt_err:
            # A broken placeholder must not take camp down with it.
            print(f"[CAMP] camp_scene_prompt has a bad placeholder ({fmt_err}); "
                  f"using the shipped shot", flush=True)
            authored = ""
    if not authored:
        bits = _CAMP_PROMPT_FALLBACK.format(
            vantage=game_identity.vantage().capitalize(),
            terrain=terrain,
            who=who,
        ).split("\n")

    if jeep_included:
        bits.append(
            "Match the jeep reference image's exact color, body shape, and wear."
        )
    if ref_map:
        bits.append("REFERENCE IMAGE MAP (use EVERY listed reference — do not drop any):")
        for item in ref_map:
            idx = item.get("index")
            role = item.get("role")
            label = item.get("label") or ""
            if role == "jeep":
                bits.append(
                    f"Reference image {idx}: the RED JEEP prop plate — put this exact vehicle in the scene."
                )
            else:
                bits.append(
                    f"Reference image {idx}: companion portrait of '{label}' — "
                    f"this person MUST be seated at the fire, matching face, hair, "
                    f"build, and clothing from that portrait."
                )
    if game_identity.shows_character() and game_identity.character_enabled():
        bits.append(
            f"The player's own character is at the fire too: {game_identity.protagonist_line()}"
        )
    # One bit per line, because the reconcile stage works line by line: joined
    # into a single line, the empty-camp bit ("No people…") would take the whole
    # prompt down with it the moment the camera is behind a visible character.
    return _sanitize_for_image_generation(game_identity.apply("\n".join(bits), "raw"))


def _build_camp_realtime_prompt(attendee_labels: list, jeep_included: bool = True) -> str:
    """Realtime world-model prompt for a living campsite (fire flicker, night air)."""
    who = ""
    if attendee_labels:
        who = " Companions seated around the fire: " + ", ".join(attendee_labels) + "."
    # Jeep is always part of camp identity — mention even if the prop file failed.
    jeep = " A dusty bright-red 1990s jeep is parked at the edge of the firelight."
    terrain = game_identity.place_summary() or "remote high-desert scrub"
    visual = (
        f"Night campsite in {terrain} A campfire burns in the mid-ground, "
        "embers drifting, warm firelight on the ground, deep night dark."
        + jeep
        + who
        + f" {game_identity.vantage().capitalize()}, handheld. "
        "Firelight flickers. Quiet night wind."
    )
    return build_realtime_prompt(visual_scene=visual, narrative=visual, choice="")


def api_camp_enter():
    """Build (or reuse) the CAMP Moment establishing shot.

    Request JSON: ``{"session_id"?: str}``
    Response JSON::

        {
          "image_url": "/images/...",
          "attendees": [
            {"label", "kind", "portrait_url", "seat": {"x_pct", "y_pct"}},
            ...
          ],
          "jeep_included": true,
          "cached": bool
        }

    Side pocket: does NOT mutate turn_count/history. Appends one additive
    display-only ``feed_log`` camp item per visit (flavor for the Story Log).
    """
    try:
        if _rate_limited("camp_enter", 1.2):
            return jsonify({"error": "slow_down", "image_url": None}), 429
        data = request.get_json(silent=True) or {}
        session_id = data.get("session_id", "default")

        try:
            st = _load_state(session_id) or {}
        except Exception:
            st = {}

        # ALL companions with resolvable portrait files (session-scoped paths).
        # Gemini img2img accepts up to 6 refs: the jeep plus up to five plates,
        # so the seat count is capped there. Both the cap and whether the jeep
        # takes one of the slots are editable at runtime (see tunables.py).
        roster = _collect_camp_companions(session_id, st)
        cap = max(1, min(5, int(CAMP_COMPANION_CAP)))
        attendees_src = roster[:cap]
        if len(roster) > cap:
            print(f"[CAMP] {len(roster)} companions on roster; "
                  f"img2img using the {cap} most recently seen", flush=True)

        jeep = _ensure_jeep_prop(session_id) if CAMP_INCLUDE_JEEP else None
        jeep_url = (jeep or {}).get("portrait_url") or ""
        jeep_path = None
        if jeep_url:
            jp = _resolve_image_path(jeep_url, session_id)
            if jp and jp.exists():
                jeep_path = str(jp)
        # Also accept a durable prop_jeep.png even if state lost the URL.
        if not jeep_path:
            durable_jeep = Path(_get_image_dir(session_id)) / "prop_jeep.png"
            if durable_jeep.exists():
                jeep_path = str(durable_jeep)
                jeep_url = _to_web_image_url("prop_jeep.png", session_id) or jeep_url
        jeep_included = bool(jeep_path)

        labels = [a["label"] for a in attendees_src]
        cache_key = _camp_cache_key(session_id, labels, jeep_url)
        with _CAMP_CACHE_LOCK:
            cached = _CAMP_CACHE.get(cache_key)
        seats = _camp_seat_layout(len(attendees_src))
        attendees_out = []
        for i, a in enumerate(attendees_src):
            seat = seats[i] if i < len(seats) else {"x_pct": 50, "y_pct": 60}
            attendees_out.append({
                "label": a["label"],
                "kind": a["kind"],
                "portrait_url": a["portrait_url"],
                "seat": seat,
            })

        realtime_prompt = _build_camp_realtime_prompt(labels, jeep_included=True)

        if cached:
            # Validate the cached plate still exists on disk — establishing
            # shots are ordinary session images and can be swept; never serve
            # a 404 URL into the Moment chrome.
            cached_path = _resolve_image_path(cached, session_id)
            if cached_path and cached_path.exists():
                _camp_append_feed(session_id, cached)
                return jsonify({
                    "image_url": cached,
                    "attendees": attendees_out,
                    "jeep_included": jeep_included,
                    "realtime_prompt": realtime_prompt,
                    "cached": True,
                })
            with _CAMP_CACHE_LOCK:
                _CAMP_CACHE.pop(cache_key, None)

        if not IMAGE_ENABLED:
            return jsonify({
                "image_url": None,
                "attendees": attendees_out,
                "jeep_included": jeep_included,
                "reason": "image_disabled",
            })

        # Refs: jeep FIRST (visual anchor), then EVERY companion portrait we can
        # fit (up to 5). Numbered ref_map tells the model which image is who.
        refs = []
        ref_map = []
        if jeep_path:
            refs.append(jeep_path)
            ref_map.append({"index": 1, "role": "jeep", "label": "red jeep"})
        for a in attendees_src:
            refs.append(a["portrait_path"])
            ref_map.append({
                "index": len(refs),
                "role": "companion",
                "label": a["label"],
            })

        print(f"[CAMP] img2img refs={len(refs)} "
              f"(jeep={jeep_included}, companions={len(attendees_src)}): "
              f"{[m.get('label') for m in ref_map]}", flush=True)

        prompt = _build_camp_prompt(attendees_src, jeep_included, ref_map=ref_map)
        world_prompt = str(st.get("world_prompt") or "")[:400] or None
        img_dir = Path(_get_image_dir(session_id))
        t0 = time.time()
        image_path = None
        gen_mode = "ensemble" if refs else "text2img"
        try:
            if refs:
                from gemini_image_utils import generate_gemini_img2img
                image_path = generate_gemini_img2img(
                    prompt=prompt,
                    caption="camp_establish",
                    reference_image_path=refs,
                    # Higher than companion_place (0.5): this is a brand-new
                    # location anchored by people/prop likeness, not the live scene.
                    strength=0.78,
                    world_prompt=world_prompt,
                    time_of_day="night, campfire glow, deep desert dark",
                    hd_mode=False,
                    output_dir=img_dir,
                    ensemble_mode=True,
                    portrait_mode=True,  # allow people (skip anti-person)
                )
            else:
                # No jeep file and no companions — still describe the jeep in
                # text so the plate isn't fire-only scrub.
                from gemini_image_utils import generate_with_gemini
                image_path = generate_with_gemini(
                    prompt=prompt,
                    caption="camp_establish",
                    world_prompt=world_prompt,
                    aspect_ratio="4:3",
                    time_of_day="night, campfire glow, deep desert dark",
                    hd_mode=False,
                    output_dir=img_dir,
                    portrait_mode=False,
                )
        except Exception as gen_err:
            log_error(f"[CAMP] generate failed: {gen_err}")
            try:
                cost_tracker.record_usage(
                    session_id, "image", "gemini", "camp_enter",
                    operation="camp_enter", output_units=0, unit_type="images",
                    latency_ms=int((time.time() - t0) * 1000), success=False,
                    error_message=str(gen_err)[:200],
                )
            except Exception:
                pass
            return jsonify({
                "image_url": None,
                "attendees": attendees_out,
                "jeep_included": jeep_included,
                "reason": "generate_failed",
            })

        web = _to_web_image_url(image_path, session_id) if image_path else None
        try:
            cost_tracker.record_usage(
                session_id, "image", "gemini", "camp_enter",
                operation=f"camp_enter_{gen_mode}",
                output_units=1.0 if web else 0, unit_type="images",
                latency_ms=int((time.time() - t0) * 1000),
                success=bool(web),
                error_message=None if web else "no_image_returned",
            )
        except Exception:
            pass
        if not web:
            return jsonify({
                "image_url": None,
                "attendees": attendees_out,
                "jeep_included": jeep_included,
                "reason": "no_image",
            })

        # Persist a durable, sweep-protected camp plate (prop_camp_<sig>.png)
        # so cache hits survive disk headroom sweeps the same way the jeep does.
        durable_web = web
        try:
            sig = hashlib.sha1(str(cache_key).encode("utf-8")).hexdigest()[:12]
            durable_web = _persist_prop_image(image_path, session_id, f"camp_{sig}") or web
        except Exception as persist_err:
            log_error(f"[CAMP] persist plate failed: {persist_err}")
            durable_web = web

        with _CAMP_CACHE_LOCK:
            _CAMP_CACHE[cache_key] = durable_web
        print(f"[CAMP] establishing shot ready ({gen_mode}, "
              f"{len(attendees_out)} attendees, jeep={jeep_included})", flush=True)

        _camp_append_feed(session_id, durable_web)
        return jsonify({
            "image_url": durable_web,
            "attendees": attendees_out,
            "jeep_included": jeep_included,
            "realtime_prompt": realtime_prompt,
            "cached": False,
        })
    except Exception as e:
        log_error(f"[CAMP] enter failed: {e}")
        return jsonify({"image_url": None, "attendees": [], "error": str(e)}), 500


def _camp_append_feed(session_id: str, image_url: str) -> None:
    """One additive, display-only Story Log beat per camp visit.

    Does not touch turn_count / history / choice generation — camp is a side
    pocket, same as conversation.
    """
    try:
        item = create_feed_item(
            type="camp",
            content="You made camp for the night.",
            image_url=image_url,
            metadata={"source": "camp"},
        )
        with WORLD_STATE_LOCK:
            st = _load_state(session_id) or {}
            _feed_append(st, item)
            _save_state(st, session_id)
    except Exception as e:
        log_error(f"[CAMP] feed append failed: {e}")


def api_talk_session():
    """Open a story-aware conversation with a SCAN subject.

    Request JSON:  {"subject": {"label", "kind", "speaks"}, "session_id"?}
    Response JSON:
        {
          "mode": "voice" | "text",  # voice = replies are spoken (speech.py)
          "subject": {...},
          "context": {premise, situation, recent, opening_line, ...},
          "voice_id": <str>,         # a Gemini voice name or a designed voice_...
          "voice_style": <str>,      # the delivery, in words, for each line
          "voice_status": ..., "voice_cache_key": ..., "voice_description": ...
        }

    A conversation is /api/talk/message turns: the player types or holds to
    speak (dictation, /api/transcribe), the character answers in text, and
    each answer is spoken in the character's voice via /api/narrator/say.
    Until 2026-09-25 this handed the browser an ElevenLabs Convai agent: a
    second account, and a public default agent id that every keyless install
    would have talked on. "voice" now just means this key can speak.
    Read-only: never mutates the sim.
    """
    try:
        if _rate_limited("talk_session", 0.8):
            return jsonify({"error": "slow down", "mode": "text"}), 429
        data = request.get_json(silent=True) or {}
        subject = data.get("subject") or {}
        session_id = data.get("session_id", "default")
        if not isinstance(subject, dict) or not (subject.get("label") or "").strip():
            return jsonify({"error": "missing subject"}), 400

        # Don't block TALK on vision. The greeting used to skip the opening
        # LLM entirely and post a canned "you shouldn't be here" as the first
        # message — every conversation opened on the same stock NPC line.
        # Honor a reused line (voice switch). Ignore canned fallbacks so
        # build_talk_context can write one for THIS subject.
        _label = _clean_subject_text(subject.get("label"), "figure", 40)
        _kind = _clean_subject_text(subject.get("kind"), "", 20)
        if not _kind:
            _kind = "person" if _talk_subject_is_figure(subject) else "machine"
        _opening = (data.get("opening_line") or "").strip()
        if _is_canned_talk_fallback(_opening):
            _opening = ""
        context = build_talk_context(
            subject, session_id, opening_override=_opening, include_vision=False,
        )
        if not (context.get("opening_line") or "").strip():
            context["opening_line"] = _talk_opening_fallback(_label, _kind)

        # Resolve the voice. Precedence:
        #   1) Explicit (validated) client choice — that's what powers the
        #      live voice-switcher pill in the TALK panel.
        #   2) A per-character voice designed on the fly from the persona
        #      brief (Gemini voice design), cached per session and deleted
        #      at session end. See voice_design.py.
        #   3) The static roster in voices.json (always available).
        # The resolver also surfaces cache_key + status so the client can
        # poll /api/talk/voice/status and speak the next line in the designed
        # voice once it lands (typically after the fallback opening).
        chosen_voice = _valid_voice_id(data.get("voice_id"))
        try:
            _world_prompt = str((_load_state(session_id) or {}).get("world_prompt") or "")
        except Exception:
            _world_prompt = ""
        voice_resolution = resolve_voice_for_subject(
            context["subject"], session_id, context=context,
            world_prompt=_world_prompt,
            # Short blocking wait catches the fast path when a preview lands
            # quickly, so the very first line is often already in-character.
            wait=0.6,
        )
        if chosen_voice:
            resolved_voice = chosen_voice
            # Client override wins, but we still keep the designed voice
            # cooking in the background — the picker can revert to "auto".
            voice_status = "override"
            voice_cache_key = None
            voice_description = ""
        else:
            resolved_voice = voice_resolution["voice_id"]
            voice_status = voice_resolution["status"]
            voice_cache_key = voice_resolution.get("cache_key")
            voice_description = voice_resolution.get("description", "")
        # Bump the refcount for the voice this conversation speaks in so
        # session cleanup can't delete it mid-talk. /api/talk/end releases it.
        try:
            import voice_design as _vd
            _vd.acquire(resolved_voice)
        except Exception:
            pass

        # Persist the voice onto this character's companion record so it can
        # be reused (by id) or REGENERATED (by the description, the one field
        # that survives a new key or a new provider) later. Best-effort.
        try:
            _ttv_model = ""
            try:
                import voice_design as _vd2
                _ttv_model = getattr(_vd2, "MODEL", "") or ""
            except Exception:
                _ttv_model = ""
            _record_companion_voice(session_id, context["subject"], {
                "voice_id": resolved_voice,
                "description": voice_description,
                "source": ("override" if chosen_voice else voice_resolution.get("source", "")),
                "status": voice_status,
                "cache_key": voice_cache_key,
                # Only designed voices carry a regeneration description; tag the
                # model so a future regen knows which TTV model produced it.
                "model": _ttv_model if voice_description else "",
            })
        except Exception as _ve:
            log_error(f"[COMPANION] voice record failed: {_ve}")

        return jsonify({
            "mode": "voice" if _speech_available() else "text",
            "subject": context["subject"],
            "context": {
                "premise": context["premise"],
                "situation": context["situation"],
                "recent": context["recent"],
                "opening_line": context["opening_line"],
            },
            "voice_id": resolved_voice or None,
            "voice_style": _talk_voice_style(context, voice_status == "ready"
                                             and bool(voice_description)),
            # The client speaks the next line in the designed voice once the
            # background design lands (poll /api/talk/voice/status).
            "voice_status": voice_status,
            "voice_cache_key": voice_cache_key,
            "voice_description": voice_description,
            "voices": get_voice_registry(),
        })
    except Exception as e:
        import traceback as _tb
        log_error(f"[TALK] session failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e), "mode": "text"}), 500


def _talk_voice_style(context: dict, designed: bool) -> str:
    """How this character's lines are delivered, in words.

    A designed voice already IS the person (age, timbre, accent), and Google's
    advice is to put only the moment's feeling in the per-line direction, so
    it gets the emotion alone. A roster voice is only a timbre; it gets the
    whole brief, which is also all an OpenAI voice can be given."""
    try:
        import voice_design as _vd
        brief = _vd.brief_for_subject(context.get("subject") or {}, context)
    except Exception:
        return ""
    emotion = str(brief.get("emotion") or "").strip()
    if designed:
        return f"Say this {emotion}".strip() if emotion else ""
    desc = str(brief.get("description") or "").strip()
    return (f"Say this in character. {desc}" + (f" Right now: {emotion}." if emotion else ""))[:400]


def api_talk_voices():
    """The voice catalog for the TALK mechanic (and narrator). Lets the client
    render a live voice picker without hardcoding ids. Read-only, no secrets."""
    try:
        return jsonify(get_voice_registry())
    except Exception as e:
        log_error(f"[TALK] voices failed: {e}")
        return jsonify({"voices": [], "default": None, "by_kind": {}, "cast": {}}), 500


def api_talk_end():
    """Client fires this when the TALK widget closes (or switches/hot-swaps
    voice) so we can drop the refcount on the voice it was using AND log the
    conversational-agent minutes to the cost ledger. Voices with refcount == 0
    become eligible for session-end cleanup + LRU eviction.

    Request JSON: ``{"voice_id": <str>, "session_id"?: <str>,
    "duration_seconds"?: <float>, "subject"?: {...}, "memory_note"?: <str>}``.
    `duration_seconds` is how long the conversation was open (informational;
    the lines are metered where they are spoken). When ``subject`` is present we also upsert a lightweight
    per-character memory record (see ``_record_character_memory``) so future
    Moments / trust systems have somewhere to plug in.
    Response JSON: ``{"ok": true, "refcount": <int>, "character"?: {...}}``.
    Always 200 — this is fire-and-forget from the client; we never let an
    end-of-call cleanup error surface as a user-visible failure.
    """
    try:
        data = request.get_json(silent=True) or {}
        voice_id = str(data.get("voice_id") or "").strip()
        session_id = str(data.get("session_id") or "default")
        try:
            seconds = float(data.get("duration_seconds") or 0)
        except (TypeError, ValueError):
            seconds = 0.0
        # Spoken lines are metered where they are made (speech.py's calls are
        # logged at the wire), so the conversation's length is not billed.
        character = None
        subject = data.get("subject")
        if isinstance(subject, dict) and (subject.get("label") or "").strip():
            try:
                character = _record_character_memory(
                    session_id, subject, note=str(data.get("memory_note") or ""),
                )
            except Exception as mem_err:
                log_error(f"[TALK] character memory failed: {mem_err}")
        remaining = 0
        if voice_id:
            try:
                import voice_design as _vd
                remaining = _vd.release(voice_id)
            except Exception:
                remaining = 0
        out = {"ok": True, "refcount": remaining}
        if character:
            out["character"] = {
                "label": character.get("label"),
                "talk_count": character.get("talk_count"),
                "trust": character.get("trust"),
                "first_meeting": character.get("talk_count") == 1,
            }
        return jsonify(out)
    except Exception as e:
        log_error(f"[TALK] end failed: {e}")
        return jsonify({"ok": True, "refcount": 0})


def api_cutscene_play():
    """POST /api/cutscene/play — generate four cinematic shots from the plate."""
    from flask import jsonify, request
    import cutscene as _cutscene

    if _rate_limited("cutscene_play", 0.35):
        return jsonify({"error": "slow_down"}), 429
    sid = _resolve_request_session_id()
    body = request.get_json(silent=True) or {}
    payload = _cutscene.play_for_session(sid, body)
    if not payload.get("ok"):
        return jsonify(payload), 409
    # The montage starts playing the instant this response lands, and its held
    # shots are ~20 seconds in which the server used to do nothing at all. The
    # first playable frame is drawn from the panels the call above just stamped,
    # so it can start NOW and be waiting by the time the player watches the last
    # shot out. /api/cutscene/complete collects it (see _take_opening_
    # establishing) rather than starting the render itself.
    try:
        _pending = (_load_state(sid) or {}).get("pending_cutscene") or {}
        print(f"[OPENING] /api/cutscene/play staged "
              f"id={_pending.get('cutscene_id')!r} opening={_pending.get('opening')!r} "
              f"shots={len(_pending.get('shots') or [])}", flush=True)
        if _pending.get("opening"):
            _spawn_opening_establishing(sid, _pending)
    except Exception as e:
        log_error(f"[OPENING] could not start the establishing beat early: {e}")
    return jsonify(payload)


def api_cutscene_complete():
    """POST /api/cutscene/complete — leave the montage and follow its edge."""
    from flask import jsonify, request

    sid = _resolve_request_session_id()
    # A cutscene arriving in another World bound it (and started its look book)
    # when the montage began. The first frame there waits for that book, here,
    # before any lock is taken. The run's opening already waited in api_reset,
    # so for it this returns at once.
    try:
        import look_book
        if look_book.building(sid):
            look_book.wait_ready(sid)
    except Exception as _lb_err:
        logging.warning(f"[LOOK BOOK] arrival wait skipped: {_lb_err}")
    # Collect the opening establishing flipbook, which has been rendering behind
    # the montage since /api/cutscene/play (see _spawn_opening_establishing) and
    # is usually already finished by now. If it is not, we hold here — it must be
    # complete to serve as the first turn's img2img anchor — and if there is no
    # prefetch for this run we render it inline exactly as before. Either way it
    # happens BEFORE the state lock: a ~15s image render holding that lock would
    # stall every other session.
    _opening_seq = None
    _pre = _load_state(sid) or {}
    _pre_pending = _pre.get("pending_cutscene") or {}
    _pre_id = str(_pre_pending.get("cutscene_id") or "")
    print(f"[OPENING] /api/cutscene/complete sees id={_pre_id!r} "
          f"opening={_pre_pending.get('opening')!r} "
          f"shots={len(_pre_pending.get('shots') or [])}", flush=True)
    if _pre_pending.get("opening"):
        _opening_seq, _prefetched = _take_opening_establishing(sid, _pre_id)
        if not _prefetched:
            _opening_seq = _generate_opening_establishing(sid, _pre_pending)
    with WORLD_STATE_LOCK:
        st = _load_state(sid) or {}
        # That render happens outside the lock, and now spans the whole montage.
        # A reset landing inside it stages a fresh montage with its own plate,
        # and installing this sequence over that one would open the new run on
        # the old run's establishing beat — the stale-first-frame failure this
        # whole path exists to prevent.
        if _opening_seq is not None and str(
                (st.get("pending_cutscene") or {}).get("cutscene_id") or "") != _pre_id:
            print(f"[OPENING] discarding establishing beat for {_pre_id!r} — the "
                  f"run was replaced while it rendered", flush=True)
            _opening_seq = None
        # The opening montage is not a graph node — it has no incoming World and
        # no outgoing edge, so complete_cutscene has nothing to follow and would
        # fall through to a bare "Look around". Check it before that runs, while
        # pending_cutscene still holds the shots.
        if (st.get("pending_cutscene") or {}).get("opening"):
            out = {"ok": True, "kind": "opening"}
            out.update(_finish_opening_montage(st, sid, opening_seq=_opening_seq))
            _save_state(st, sid)
            _sync_ambient_state(st, sid)
            return jsonify(out)
        # THE REWARD (goal.py): the run reached what it came for, the montage
        # showed it, and its last panel is where the player now stands — on the
        # other side of it. Nothing to follow in the graph; the deposit is the
        # whole point, so it is done here before complete_cutscene falls
        # through to a bare "Look around" over the frame they were outside.
        _pending_reward = st.get("pending_cutscene") or {}
        if str(_pending_reward.get("mood") or "") == "reward":
            st["pending_cutscene"] = None
            st["experience_cutscene_id"] = ""
            info = _goal_mod.finish_reward(st, sid, _pending_reward)
            slate = _structure_choices_for_feed(
                ([f"{str((info.get('prize') or {}).get('verb') or 'Take')} the "
                  f"{(info.get('prize') or {}).get('name')}"]
                 if (info.get("prize") or {}).get("name") else [])
                + ["Look around", "Check the way out"],
                info.get("inside") or "What do you do next?",
                image_url=info.get("image_url") or st.get("current_image_url"),
            )
            _feed_append(st, slate)
            st["choices"] = slate.get("choices")
            _save_state(st, sid)
            _sync_ambient_state(st, sid)
            return jsonify({"ok": True, "kind": "goal_reward",
                            "image_url": info.get("image_url"),
                            "name": info.get("name"), "choices": slate,
                            "board": info.get("board"),
                            "phase": info.get("phase") or "",
                            "prize": info.get("prize"),
                            "next_goal": info.get("next") or "",
                            "victory": bool(info.get("victory"))})
        info = complete_cutscene(st, sid)
        out = {"ok": True, "kind": (info or {}).get("kind") or "resume"}
        if info and info.get("kind") == "cutscene":
            _feed_append(st, _cutscene_feed_item(info))
            pending = info.get("cutscene") or {}
            dest = info.get("to") or {}
            out["cutscene"] = pending
            out["cutscene_id"] = dest.get("id") or pending.get("cutscene_id")
            out["name"] = dest.get("name") or pending.get("name")
            out["mood"] = dest.get("mood") or pending.get("mood")
        elif info and info.get("kind") == "world":
            _feed_append(st, _world_transition_feed_item(info))
            dest_name = (info.get("to") or {}).get("name") or "a new world"
            dest_url = st.get("current_image_url")
            choices_item = _structure_choices_for_feed(
                ["Look around"], dest_name, image_url=dest_url,
            )
            _feed_append(st, choices_item)
            out["to_world"] = (info.get("to") or {}).get("id")
            out["to_name"] = dest_name
            out["image_url"] = dest_url
            out["choices"] = choices_item
        else:
            # No outgoing edge, or the dest World is missing. The hop that
            # opened this Cutscene skipped the source World's slate — leave
            # a playable prompt or the choice bar stays empty.
            dest_url = st.get("current_image_url")
            choices_item = _structure_choices_for_feed(
                ["Look around"], "What do you do next?", image_url=dest_url,
            )
            _feed_append(st, choices_item)
            out["to_world"] = st.get("experience_world_id") or ""
            out["image_url"] = dest_url
            out["choices"] = choices_item
        _save_state(st, sid)
        _sync_ambient_state(st, sid)
    return jsonify(out)


