def api_talk_voice_status():
    """Poll for a still-designing per-character voice.

    Request: ``GET /api/talk/voice/status?cache_key=<16-hex>``.
    Response JSON: ``{"cache_key", "voice_id", "status", "description"}`` —
    ``status`` cycles through ``"generating"`` -> ``"ready"`` (or ``"failed"``
    / ``"unknown"``). When ``status == "ready"``, the client speaks the next
    line in the new ``voice_id``, so the character's voice changes
    mid-conversation.
    """
    try:
        cache_key_str = str(request.args.get("cache_key") or "").strip()
        if not cache_key_str:
            return jsonify({"error": "missing cache_key"}), 400
        try:
            import voice_design as _vd
            status = _vd.get_status(cache_key_str) or {
                "cache_key": cache_key_str, "voice_id": None,
                "status": "unknown", "description": "",
            }
        except Exception as _e:
            status = {"cache_key": cache_key_str, "voice_id": None,
                      "status": "unknown", "description": "", "error": str(_e)}
        return jsonify(status)
    except Exception as e:
        log_error(f"[TALK] voice status failed: {e}")
        return jsonify({"error": str(e), "status": "unknown"}), 500


# ═══════════════════════════════════════════════════════════════════
# NARRATOR STREAM — a voice that frames the world (and can BE many voices)
#
# Where TALK is a two-way conversation with a subject IN the scene, the narrator
# is a one-way voice OVER the scene: world-building, lore, cold opens, stingers.
# It can speak as a single "archive voice" or as a small CAST (narrator / man /
# woman / elder / creature / machine / warden…), so a single narration can hand
# off between characters like a radio play. Built on text-to-speech on the
# player's key (speech.py) so it's a clean, expandable primitive:
#   • /api/narrator/say       — speak one line (returns audio)
#   • /api/narrator/narrate   — speak a multi-character script (audio per line)
#   • /api/narrator/worldbuild— GENERATE a story-aware narration, then (opt) speak
#   • /api/narrator/cast      — the voices + named cast the client can pick from
# All read-only; none mutate the sim. Without a voice on this key (mock mode,
# no key) these degrade to returning text only (never an error).
# ═══════════════════════════════════════════════════════════════════

def _tts_synthesize(text: str, voice_id: str, settings: dict = None):
    """One line of narration or dialogue, spoken (speech.py). WAV bytes, or
    None (never raises). `settings["style"]` is the delivery, in words."""
    style = ""
    if isinstance(settings, dict):
        style = str(settings.get("style") or "")
    try:
        import speech
        return speech.synthesize((text or "")[:2500], voice_id, style)
    except Exception as e:  # noqa: BLE001
        log_error(f"[NARRATOR] tts failed: {e}")
        return None


def _narrate_segments(segments: list) -> list:
    """Voice a list of {character, text[, voice_id]} into per-segment results
    with base64 audio (when a key is configured). Each output segment:
    {character, text, voice_id, audio?(data-url)}."""
    import base64 as _b64
    out = []
    # Hard cap the number of voiced lines: bounds TTS cost, latency, and the
    # base64 payload size per request.
    for seg in (segments or [])[:6]:
        if not isinstance(seg, dict):
            continue
        text = (seg.get("text") or "").strip()
        if not text:
            continue
        character = (seg.get("character") or "narrator").strip().lower()
        cast = resolve_cast(character)
        voice_id = _valid_voice_id(seg.get("voice_id")) or cast.get("voice_id") \
            or _narrator_voice_id()
        settings = {k: cast[k] for k in ("style",) if k in cast}
        entry = {"character": character, "text": text[:2500], "voice_id": voice_id}
        audio = _tts_synthesize(text, voice_id, settings)
        if audio:
            entry["audio"] = "data:audio/wav;base64," + _b64.b64encode(audio).decode("ascii")
        out.append(entry)
    return out


def _segment_voice(character: str, voice_id=None) -> str:
    """Resolve the voice a narrator segment should speak in."""
    cast = resolve_cast(character)
    return _valid_voice_id(voice_id) or cast.get("voice_id") \
        or _narrator_voice_id()


def _speech_available() -> bool:
    try:
        import speech
        return speech.can_speak()
    except Exception:
        return False


def api_narrator_cast():
    """The voices + named cast the narrator can speak as (client picker), and
    whether a line will actually be voiced on this key (else subtitles)."""
    try:
        reg = get_voice_registry()
        return jsonify({
            "voices": reg["voices"],
            "narrator": reg["narrator"],
            "cast": reg["cast"],
            "voice_available": _speech_available(),
        })
    except Exception as e:
        log_error(f"[NARRATOR] cast failed: {e}")
        return jsonify({"voices": [], "cast": {}, "voice_available": False}), 500


def api_narrator_say():
    """Speak one line. Request: {text, character?, voice_id?, style?}.
    Returns audio/wav, or 503 JSON with the text when this key has no voice
    (mock mode, no key) — the client shows the subtitle either way."""
    try:
        if _rate_limited("narrator_say", 0.2):
            return jsonify({"error": "slow down"}), 429
        data = request.get_json(silent=True) or {}
        text = (data.get("text") or "").strip()
        if not text:
            return jsonify({"error": "missing text"}), 400
        if not _speech_available():
            return jsonify({"error": "no voice on this key", "text": text}), 503
        cast = resolve_cast(data.get("character"))
        voice_id = (_valid_voice_id(data.get("voice_id")) or cast.get("voice_id")
                    or _narrator_voice_id())
        style = str(data.get("style") or cast.get("style") or "")[:400]
        audio = _tts_synthesize(text, voice_id, {"style": style})
        if not audio:
            return jsonify({"error": "synthesis failed", "text": text}), 502
        from flask import Response as _Resp
        return _Resp(audio, mimetype="audio/wav")
    except Exception as e:
        import traceback as _tb
        log_error(f"[NARRATOR] say failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e)}), 500


def api_narrator_narrate():
    """Speak a multi-character script. Request: {segments:[{character,text}]}.
    Response: {segments:[{character,text,voice_id,audio?}], voice: bool}."""
    try:
        if _rate_limited("narrator_narrate", 2.0):
            return jsonify({"error": "slow down", "segments": []}), 429
        data = request.get_json(silent=True) or {}
        segments = data.get("segments") or []
        if not isinstance(segments, list) or not segments:
            return jsonify({"error": "missing segments"}), 400
        voiced = _narrate_segments(segments)
        return jsonify({"segments": voiced, "voice": _speech_available()})
    except Exception as e:
        import traceback as _tb
        log_error(f"[NARRATOR] narrate failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e), "segments": []}), 500


# The narrator's register is short declaratives stacked into a beat — "Saigon.
# Shit. I'm still only in Saigon." A hard one-sentence clip cut that cadence off
# at the first full stop, so the voice could only ever produce the first third of
# a line. Three is the ceiling; the char cap is what actually keeps a bridging
# beat shorter than the loading it covers.
_NARRATION_MAX_SENTENCES = 3
# Two beats need room that one line did not. At 240 the clip was dropping the
# SECOND beat whenever the first ran long — a live run came back "This ledger
# documented the daily caloric distribution quotas until the blackout of 2154."
# and nothing else, because the pair together cleared the cap and the clip
# keeps only what fits. The directive asks for two sentences of at most fifteen
# words, which lands well inside this; the headroom is only so that a model
# overshooting that ask costs a few words rather than a whole beat.
_NARRATION_MAX_CHARS = 320


def _strip_narration_staging(text: str, acted: str = "") -> str:
    """Drop everything in a narration that is not the spoken line.

    Asked for one sentence of dialogue, a model will still hand back a
    screenplay: a sound cue on its own line ("*Click.*"), or the action echoed
    as a heading before the real line ("Spoke with the miner.\\n\\nHis teeth
    were..."). Both were reaching the voice — the clip keeps the FIRST
    sentence, so the narrator's whole contribution to a turn was the word
    "Click". The brief asks for neither; this is the guarantee.
    """
    t = (text or "").strip()
    t = re.sub(r"^```[a-z]*\s*", "", t)
    t = re.sub(r"\s*```$", "", t).strip()
    flat_acted = re.sub(r"[^a-z0-9 ]", "", (acted or "").lower()).strip()
    kept = []
    for raw in t.splitlines():
        line = raw.strip()
        if not line:
            continue
        # A cue, not a line: wholly wrapped in emphasis or brackets.
        if re.fullmatch(r"[\*_\[\(].{0,80}?[\*_\]\)][.!?]*", line):
            continue
        # The action restated as a heading before the real line. Only ever
        # dropped when something else follows it — if the model gave us
        # nothing but the echo, a weak line still beats no line.
        flat = re.sub(r"[^a-z0-9 ]", "", line.lower()).strip()
        if flat_acted and flat == flat_acted and not kept:
            continue
        kept.append(line)
    out = " ".join(kept) if kept else t
    # Emphasis markers survive into TTS as literal asterisks.
    out = re.sub(r"[*_`]+", "", out)
    return re.sub(r"\s+", " ", out).strip()


def _clip_narration(text: str, max_sentences: int = 1) -> str:
    """Trim a narration line to at most ``max_sentences`` sentences.

    LLMs ignore a sentence count often enough that this is the hard guarantee.
    Ellipses ("...") are preserved as intra-sentence pauses; only a standalone
    terminator (. ! ?) that isn't part of an ellipsis ends a sentence. One
    sentence is the floor — an over-long first sentence is kept whole rather
    than truncated mid-thought.
    """
    t = (text or "").strip()
    if not t:
        return t
    ends = [m.end() for m in re.finditer(r"(?<!\.)[.!?](?!\.)", t)]
    if not ends:
        return t.rstrip(",;:") + "."
    kept = t[: ends[0]].strip()
    for end in ends[1:max(1, max_sentences)]:
        candidate = t[:end].strip()
        if len(candidate) > _NARRATION_MAX_CHARS:
            break
        kept = candidate
    return kept


# HOW the player issued this action, phrased for the narrator.
#
# It used to be handed one anonymous sentence — "THE PLAYER JUST DID: <text>"
# — for every route into the game, so walking toward something, opening it,
# speaking to it, picking an offered option and typing your own sentence all
# arrived looking identical. A voice that cannot tell those apart answers all
# of them the same way, which is what made the narrator feel like it was
# talking over the game instead of about it. Naming the verb is what lets it
# narrate the player's story rather than the room's.
#
# Phrased in the SECOND PERSON, because the brief addresses the narrator as
# the one living this ("You are {self}, speaking into a tape"). Written in the
# third person — "They walked toward the pond" — the model took the hint and
# started addressing the player as "you", which is a different narrator in a
# different game from the one the VOICE line describes.
_DEED_PHRASING = {
    "move": "walked toward {t}",
    "interact": "put your hands on {t}",
    "talk": "spoke to {t}",
    "photo": "photographed {t}",
    "leave": "walked away from {t}",
    "choice": "took one of the options in front of you",
    "custom": "did something nobody offered you",
    "encounter": "answered a threat, face to face",
    "arrive": "arrived somewhere you have not been",
    "death": "died here",
}


def _deed_block(kind: str, target: str, acted: str) -> str:
    """The labelled "what the player just did" block, or "" if we know nothing.

    Deliberately the FIRST thing in the scene slot: the narrator's whole job
    is now to speak to this, and a brief buries whatever it puts last.
    """
    kind = re.sub(r"[^a-z_]", "", str(kind or "").strip().lower())[:24]
    target = re.sub(r"\s+", " ", str(target or "")).strip()[:120]
    acted = re.sub(r"\s+", " ", str(acted or "")).strip()[:240]
    if not acted and not target:
        return ""
    phrase = _DEED_PHRASING.get(kind, "")
    if "{t}" in phrase:
        phrase = phrase.format(t=target) if target else ""
    headline = f"You {phrase}." if phrase else ""
    verbatim = f' In your own words: "{acted}"' if acted else ""
    # Points AT the fact rather than replacing it. An earlier version of this
    # block told the narrator to speak to the action's cost and explicitly
    # not to reach for the history — which answered the wrong complaint and
    # cost the voice its whole register, turning every line into a caption of
    # the thing just touched. The history IS the line; this only says which
    # piece of it to go and get.
    return (
        "WHAT YOU JUST DID — reach for the fact that belongs to THIS:\n"
        f"{headline}{verbatim}\n"
        "Whatever the background knows about that specific thing — what it "
        "was for, who ran it, what was done with it, when it stopped — that "
        "is the fact you set down. Do not narrate the action back, do not "
        "caption the picture, and do not tell them what it cost.\n"
        "Do not echo the action back and do not write a sound effect or a "
        "stage direction before it. Your reply is the spoken line and nothing "
        "else."
    ).strip()


# ───────── THE NARRATOR'S TWO BEATS ──────────────────────────────────────────
# FACT / QUESTION was only ever two shapes over one finite pool of facts, and
# the brief says that pool outright: "ONE LINE OF HISTORY, AND NOTHING ELSE",
# reached out of a background document a few thousand characters long. Once the
# obvious facts are spent there is nowhere left to go, so the voice rewords what
# it already said — which is the reported "repeating lines changing just a few
# words". Alternating harder cannot fix a shortage of shapes.
#
# So a narration is TWO BEATS and the PAIR of shapes rotates. Beat one sets
# something down; beat two turns on it. History is still the register — FACT is
# in every other pair — but it now sits beside what he can reason out for
# himself, what he cannot account for, and (once a cycle) what he came here to
# reach. Those are his own thinking, which is the other half of the ask: the
# voice should sound like someone working it out, not like a file being read.
_BEAT_KINDS = {
    "FACT": (
        "set down ONE buried piece of what was done here — what it was for, "
        "who ran it, what year, what they called it. Flat, as something you "
        "happen to know. Never a fact you have already given"
    ),
    "QUESTION": (
        "ask the part that does not add up. Plainly, of yourself, and leave it "
        "hanging. Not a riddle, not a warning, not a question to anyone else"
    ),
    "MYSTERY": (
        "name the thing in front of you that should not be the way it is — "
        "present tense, no history. What is wrong with this, now. Say it and "
        "do not explain it"
    ),
    "READ": (
        "say what you make of it. Your own read, out loud: what this means, "
        "what it tells you, what you have decided about it. You may be wrong"
    ),
    "GOAL": (
        "measure it against what you came here for. Not the mission recited — "
        "how far off it still is, whether this gets you closer, what it costs "
        "you to keep going"
    ),
    "TALLY": (
        "count what you actually have. What you know now that you did not, or "
        "what you still have nothing on"
    ),
}

#: Ordered pairs. No shape opens two narrations running, and GOAL comes round
#: once per cycle — "occasionally", which is what it is worth. Six narrations
#: is long enough that a player never hears the cycle as a pattern.
_BEAT_CYCLE = (
    ("FACT", "QUESTION"),
    ("MYSTERY", "READ"),
    ("FACT", "MYSTERY"),
    ("READ", "GOAL"),
    ("QUESTION", "FACT"),
    ("TALLY", "MYSTERY"),
)

#: A character's narration is ONE thought, not two beats (Matt, 2026-09-25:
#: "make sure to not have many lines. really they should keep it short, a
#: thought, what they'd think as them, the character"). The shapes still
#: rotate so it does not settle into one; their own READ comes round most,
#: because it is the shape that is most them.
_THOUGHT_CYCLE = ("NOTICE", "READ", "KNOW", "QUESTION", "NOTICE", "HISTORY", "READ", "TALLY", "GOAL")

#: The shapes a character's thought takes. The two-beat shapes were written for
#: a narrator whose register is the World's history, and FACT ("what was done
#: here, who ran it, what year") is a line anybody could say — in an A/B of one
#: moment it swallowed two characters of four ("Horizon signed the permits for
#: this station back in seventy-two"). These ask for what only THIS person
#: would catch, know or make of it; the World's history keeps one slot.
_THOUGHT_KINDS = {
    "NOTICE": ("the thing in front of you that YOU would catch first, the way you would "
               "catch it — present tense, no history"),
    # READ and KNOW say what they are NOT: in a fair A/B (every character from
    # the same point in the cycle) both slid back to "Horizon signed the
    # permits in 1989" for three characters of four. The World's brief spends
    # most of its words on history, and a shape that does not rule it out
    # inherits it.
    "READ": ("what YOU make of it — your own call, in your own words, the way someone like you "
             "would size it up. Not a fact about its past: no year, no company, no permit"),
    "KNOW": ("what your own trade or life tells you about the thing in front of you — the kind "
             "of thing only someone who does what you do would know. Not the World's history: "
             "no year, no company, no permit"),
    "QUESTION": _BEAT_KINDS["QUESTION"],
    "HISTORY": _BEAT_KINDS["FACT"],
    "TALLY": _BEAT_KINDS["TALLY"],
    "GOAL": _BEAT_KINDS["GOAL"],
}

#: Words too common to mean anything as a rut signal.
_NARRATION_STOPWORDS = frozenset("""
about after again against already also always another anything around away
back because been before being below between both came come could down each
even ever every from gone have here into just keep kept know later left like
long look made make many more most much never next nobody none nothing
only other over own place same seen since some something still such take
than that their them then there these they thing think this those through
time under until upon very want went were what when where which while will
with without would your yours
""".split())


def _narration_rut_words(spoken: list, min_hits: int = 2, cap: int = 6) -> list:
    """Content words this narrator has now leaned on in more than ONE line.

    The complaint is not that a noun recurs — the fence and the mesa are
    supposed to recur, they are the place. It is that the SUBJECT stops
    changing: a real run gave three lines running about Horizon signing
    permits, each a reword of the last. A noun used once is the scene; a noun
    used twice is a rut, and only the second kind is worth forbidding.
    """
    hits: dict = {}
    for line in spoken:
        words = {w for w in re.findall(r"[a-z]{4,}", str(line).lower())
                 if w not in _NARRATION_STOPWORDS}
        for w in words:
            hits[w] = hits.get(w, 0) + 1
    ranked = sorted((w for w, n in hits.items() if n >= min_hits),
                    key=lambda w: (-hits[w], w))
    return ranked[:cap]


def _beat_directive(spoken: list, goal: str = "", spoken_count: int = -1,
                    thought: bool = False, lens: str = "") -> str:
    """Name the two shapes this narration owes, and what it may not lean on.

    TOLD, never inferred. The brief used to ask the narrator to "read ALREADY
    SAID THIS RUN and see which one you did last", which makes every line
    depend on the model classifying its own previous output — and it does not:
    left to infer it gave four questions in a row, three of them the same
    Horizon paraphrase. The server knows how many lines have gone by, so it
    picks the shapes and says them.

    Appended LAST on purpose, and explicit that it outranks the shape rules
    above it. The authored brief ends on "ONE LINE OF HISTORY" and "ONE short
    sentence", both emphatic and both last — so anything that means to change
    the shape has to say it does, the same way the radio-play format block does.

    `spoken_count` is how many narrations this run has produced, and it has to
    be a real counter rather than `len(spoken)`. `narrator_recent` is capped at
    NARRATOR_MEMORY entries, so its length stops growing — and with a memory of
    six and a cycle of six, the index pinned itself at `6 % 6 == 0` from the
    seventh narration on. Every later line in the run got FACT then QUESTION,
    which is the exact rut this rotation exists to break, and it looked from
    the outside like the rotation being ignored. -1 means "no counter was
    passed"; fall back to the length, which is right for a short run.
    """
    spoken = [str(s).strip() for s in (spoken or []) if str(s).strip()]
    idx = len(spoken) if spoken_count < 0 else spoken_count
    if thought:
        return _thought_directive(spoken, goal, idx, lens)
    first, second = _BEAT_CYCLE[idx % len(_BEAT_CYCLE)]
    # No goal authored, so the slot would ask him to measure against nothing.
    # Spend it on his own read instead of wasting the turn in the rotation.
    if "GOAL" in (first, second) and not (goal or "").strip():
        first, second = ("READ" if first == "GOAL" else first,
                         "TALLY" if second == "GOAL" else second)

    out = [
        "\nTHIS NARRATION IS TWO BEATS — this is the shape, and it replaces any "
        "one-sentence or one-line rule above.",
        "TWO SHORT SENTENCES, at most fifteen words each. Spoken aloud, the "
        "whole thing is over in about eight seconds. Cut an adjective before "
        "you cut a noun.",
        "The second turns on the first — it does not restate it, and it does "
        "not answer it tidily.",
        "This is you thinking, not a report being read: say it the way it "
        "occurs to you.",
    ]
    if "GOAL" in (first, second) and (goal or "").strip():
        out.append(f"WHAT YOU CAME HERE FOR: {str(goal).strip()[:200]}")
    if spoken:
        opening = " ".join(spoken[-1].split()[:3])
        out.append(f'Your last line began "{opening}". Do not begin this one '
                   f"that way.")
        rut = _narration_rut_words(spoken)
        if rut:
            out.append(
                "You have already built more than one line on: "
                + ", ".join(rut)
                + ". Do not make either beat about those again — find a "
                  "different thing in this world to be talking about."
            )
    # The two beats go LAST, after every constraint, because the thing the
    # model reads last is the thing it does. They were above these lines and a
    # measured run drifted back to fact-then-question by the sixth narration
    # even while being told otherwise — the same "last wins" that made the
    # shapes a tail in the first place, one level down.
    out += [
        "THE TWO BEATS, IN THIS ORDER:",
        f"BEAT ONE — {first}: {_BEAT_KINDS[first]}.",
        f"BEAT TWO — {second}: {_BEAT_KINDS[second]}.",
    ]
    return "\n".join(out) + "\n"


def _thought_directive(spoken: list, goal: str, idx: int, lens: str = "") -> str:
    """The shape for a character's narration: ONE thought, in their head.

    Same placement as the beats and for the same reason — last, and saying
    that it replaces the brief's own shape rules ("TWO BEATS", "Two short
    sentences"), which are emphatic and would otherwise win."""
    kind = _THOUGHT_CYCLE[idx % len(_THOUGHT_CYCLE)]
    if kind == "GOAL" and not (goal or "").strip():
        kind = "READ"
    out = [
        "\nTHIS NARRATION IS ONE THOUGHT — this is the shape, and it replaces the "
        "two beats, the two sentences and any other length rule above.",
        "ONE short sentence, twelve words or fewer. What goes through YOUR head right "
        "now, as you — the way you would put it, the thing you would notice. Not a "
        "report, not an announcement, not a line for anyone else.",
    ]
    if kind == "GOAL":
        out.append(f"WHAT YOU CAME HERE FOR: {str(goal).strip()[:200]}")
    if spoken:
        opening = " ".join(spoken[-1].split()[:3])
        out.append(f'Your last thought began "{opening}". Do not begin this one that way.')
        rut = _narration_rut_words(spoken)
        if rut:
            out.append("You have already thought more than once about: " + ", ".join(rut)
                       + ". Think about something else this time.")
    # WHO is thinking goes last too. Placed only under the brief's VOICE line,
    # the lens lost to everything after it: an A/B of one moment across four
    # characters gave four lines any of them could have said, and a rancher
    # and a paramedic both counting "three rolls of film" — the premise's
    # photojournalist, speaking through whoever was playing.
    if lens:
        out.append("WHO IS THINKING — the thought has to be one only THEY would have:\n" + lens.strip()
                   + "\nIf the PREMISE describes the protagonist as someone else (another trade, "
                     "other gear), that is not you: you have only what you are and what you carry.")
    out.append(f"THE THOUGHT — {kind}: {_THOUGHT_KINDS[kind]}.")
    return "\n".join(out) + "\n"


def _narrator_goal(state: Optional[dict] = None) -> str:
    """What the player came here to reach — the RUN's goal first.

    `place_summary()` deliberately leaves this out, so the one voice that could
    use it — the one speaking the player's own thoughts — never saw it.

    Reads the run before the sheet. A run whose level sheet had no goal still
    gets one drafted at reset (`_goal_for_this_run`), and this used to look
    only at the sheet — so on exactly those runs the narrator's GOAL beat was
    swapped out for READ/TALLY while the title card had just named a
    destination. Two answers to "what did I come here for", one of them empty.
    """
    goal = run_goal(state)
    if goal:
        if (state or {}).get("goal_reached_turn"):
            return f"{goal} — and you are there now"
        return goal
    try:
        if game_identity.setting_authored():
            return str((game_identity.authored_setting() or {}).get("goal") or "").strip()
    except Exception:
        pass
    return ""


def _narrator_sees(st: dict) -> str:
    """What the frame on screen actually shows, for the narrator.

    It read `current_observed_vision`, then `current_image_prompt`. The first
    is only ever written by /api/observe — the live-video path — so on the
    stills path every player plays it was empty, and the fallback is the
    RENDER RECIPE, which opens with the camera rules: clipped to 400
    characters, the narrator's "WHAT IS ON SCREEN" for a frame of a rancher
    at a rusted truck facing a razor-wired bunker was "🎥 CAMERA: THIRD-PERSON
    FOLLOW-CAM VIEW … a camera three to five metres behind the character"
    (2026-09-25, asked "do the thoughts pertain to what's happening in the
    scene we're looking at?" — they could not have).

    Now: the live read if there is one; else the vision pass over the still
    (_vision_analyze_all, cached per image path — the same read TALK's persona
    and the turn already paid for); and the detector's labels for this frame
    either way. The render recipe is never used: it is instructions, not a
    picture. The World document is the last resort."""
    seen = re.sub(r"\s+", " ", str(st.get("current_observed_vision") or "")).strip()
    if not seen and st.get("current_image_url"):
        try:
            path = _resolve_image_path(st["current_image_url"])
            if path and path.exists():
                seen = re.sub(r"\s+", " ", str((_vision_analyze_all(str(path)) or {})
                                                .get("description") or "")).strip()
        except Exception:
            seen = ""
    things = [str(x).strip() for x in (st.get("scene_objects") or []) if str(x).strip()][:8]
    if things:
        seen = (seen + " " if seen else "") + "In the frame: " + ", ".join(things) + "."
    if not seen:
        seen = re.sub(r"\s+", " ", str(st.get("world_prompt") or "")).strip()
    return seen[:600]


def _narrator_script(focus: str, multi: bool, session_id: str, acted: str = "",
                     deed_kind: str = "", deed_target: str = "") -> list:
    """Generate a short, story-aware world-building narration as a list of
    {character, text} segments. `multi` lets it hand off between cast voices.

    Every returned segment is CLIPPED to a single sentence — the narrator always
    speaks exactly one line, so a bridging beat (e.g. MOVE TO's black loading
    screen) is over before the loading is."""
    try:
        st = _load_state(session_id) or {}
    except Exception:
        st = {}
    try:
        hist = _load_history(session_id) or []
    except Exception:
        hist = []
    premise = _story_premise()
    # WHAT IS ACTUALLY ON SCREEN — not the world document.
    #
    # This used to be the whole `world_prompt`: a 1200-1500 word summary of the
    # world at large, rewritten each turn but slow-moving at the top, pasted in
    # under the label "CURRENT SCENE" with no clip at all. So the one voice that
    # speaks directly to the player was handed a wall of background that barely
    # changes between turns and almost nothing about the frame in front of them,
    # and its bulk drowned the recent beats underneath it. A narrator generated
    # from near-identical inputs every time says near-identical things.
    #
    # Freshest first: the vision pass over the frame that actually rendered
    # (written every turn by the reground), then the prompt that frame was drawn
    # from, then the world document as a last resort — clipped either way.
    still = _narrator_sees(st)
    # MOVE TO's spoken line fires on the click, before /api/choose writes
    # last_choice. The client therefore sends `acted` on the worldbuild
    # request so this line names the trip they just committed to, not the
    # previous pick (or a recaption of the still they are leaving).
    acted = (acted or "").strip() or (st.get("last_choice") or "").strip()
    scene_bits = []
    deed = _deed_block(deed_kind, deed_target, acted)
    if deed:
        scene_bits.append(deed)
    if still:
        # Labelled as something NOT to describe back. The narrator is the one
        # voice that can say the part of a moment the picture cannot, and it
        # spent every line captioning the frame because the frame was the only
        # thing in its brief that looked like a subject.
        if (focus or "").strip():
            scene_bits.append(f"WHERE THEY WERE LEAVING: {still}")
        else:
            scene_bits.append(
                "WHAT IS ON SCREEN (they can already see this — do not "
                f"describe it back to them): {still}"
            )
    scene = "\n\n".join(scene_bits)
    # The cheap signals that genuinely differ turn to turn. Without them the
    # only thing separating two narrations is model temperature.
    now = []
    if (st.get("time_of_day") or "").strip():
        now.append(str(st["time_of_day"]).strip()[:60])
    phase = str(st.get("current_phase") or "").strip().lower()
    if phase and phase != "normal":
        now.append(f"the situation is {phase}")
    # This used to carry the tracked injury list. That went away with the wound
    # parser; the narrator gets the wound prose from RECENT EVENTS below anyway,
    # and being hunted is the live stake now, so hand it that instead.
    det_level = get_detection(st)["level"]
    if det_level > DETECT_HIDDEN:
        now.append(f"you are {DETECT_NAMES[det_level]}")
    if now:
        line = "RIGHT NOW: " + "; ".join(now)
        scene = (scene + "\n\n" + line) if scene else line
    recent = []
    for entry in hist[-3:]:
        ch = (entry.get("choice") or "").strip()
        d = (entry.get("dispatch") or entry.get("vision_dispatch") or "").strip()
        line = (f"{ch} -> {d}" if ch and d else (d or ch))
        if line:
            recent.append(line[:220])
    recent_block = ("\n\nRECENT EVENTS:\n- " + "\n- ".join(recent)) if recent else ""
    focus_block = f"\n\nFOCUS THIS NARRATION ON: {focus.strip()}" if (focus or "").strip() else ""
    # What this narrator has already said. Asking a model not to be repetitive
    # while showing it nothing it previously said is asking it to guess; the
    # lines it must not land on again are the only reliable way to move it off
    # them. Kept short — this is a nudge, not a transcript.
    spoken = [str(s).strip() for s in (st.get("narrator_recent") or []) if str(s).strip()]
    # OPENINGS ONLY, never the whole sentences. This block is why the rut was
    # so hard to break: four complete, well-formed lines under a "do not
    # repeat" heading are still four EXAMPLES, and few-shot pull beats a
    # negative instruction every time. Measured, on the same prompt and the
    # same model: a fresh session gave six different shapes across six
    # narrations, while a session whose remembered lines were all
    # fact-then-question gave eight fact-then-questions in a row — obeying the
    # instruction not to reuse the words while copying the shape it was being
    # shown. Telling it harder did not work; removing the demonstration did.
    #
    # A stem is enough for the job that is actually left here. It identifies a
    # line well enough to catch a literal restart, and the two guards that do
    # the real work are elsewhere: the rut words ban the SUBJECT (see
    # _narration_rut_words) and the beat rotation names the SHAPE.
    stems = []
    for line in spoken[-3:]:
        words = line.split()
        stems.append(" ".join(words[:6]) + ("…" if len(words) > 6 else ""))
    avoid_block = (
        "\nALREADY SAID THIS RUN — these are how your last lines OPENED. Do "
        "not open this way again, and do not say those lines again in other "
        "words:\n- " + "\n- ".join(stems)
        + "\nThey are not examples. Nothing about their shape is a template.\n"
    ) if stems else ""
    # NOT folded into avoid_block. `{avoid}` sits near the top of the authored
    # brief, above the long WHAT YOU SAY / HOW YOU SAY IT sections — and those
    # end with "ONE LINE OF HISTORY", which is emphatic and, being last, wins.
    # Putting the beat shapes there produced three facts in a row; they have to
    # be the final instruction in the prompt, so they go on as a tail below.
    # A run played as a character narrates as ONE thought through their eyes
    # (_narrator_lens); a run without one (an older save, a harness session)
    # keeps the two beats it was tuned on.
    lens = _narrator_lens()
    alternation = _beat_directive(spoken, _narrator_goal(st),
                                  spoken_count=int(st.get("narrator_beat") or 0),
                                  thought=bool(lens), lens=_narrator_lens_short())

    fallback = [{"character": "narrator",
                 "text": "The light was going. Nobody had been through here in a long time."}]
    if not LLM_ENABLED:
        return fallback

    # The narrator speaks as the player. "A 1993 analog-horror world" and the
    # implicit unnamed lone person are both overridable; an authored run should
    # hear its own protagonist's voice in its own level.
    world_label = game_identity.place_summary() or "a 1993 analog-horror world"
    narrator_self = game_identity.protagonist_line() or "one lone person"

    # Built before the branch because BOTH paths need it now. The authored brief
    # used to be read only on the single-voice path, and the narrator button
    # asks for multi — so the one prompt in the editor with a whole panel to
    # itself ("The Narrator → What it says") had no effect on the one button a
    # player presses to hear it. Editing it looked exactly like editing nothing.
    # The blocks label themselves now (the deed first, the frame after it), so
    # there is no outer "CURRENT SCENE:" heading to wrap them in — that
    # heading is what told the narrator the frame was the subject.
    scene_block = (chr(10) + chr(10) + scene) if scene else ""
    focus_block_line = ""
    if (focus or "").strip():
        # Named separately from the mood note so an authored template can put it
        # first: with the baseline mood ahead of it, every focused line collapsed
        # back into the same generic beat.
        focus_block_line = (
            f"INSTRUCTIONS FOR THIS LINE: {focus.strip()}\n"
            f"Follow these exactly, ahead of any mood note below.\n\n"
        )
    authored = _authored_narrator_brief(
        world=world_label, self=narrator_self, premise=premise,
        scene=scene_block, recent=recent_block, focus=focus_block_line,
        avoid=avoid_block, lens=lens,
    )

    if multi:
        cast_names = ", ".join((VOICES_CONFIG.get("cast") or {}).keys()) or "narrator"
        # The radio play is an OUTPUT SHAPE, not a voice. So when the narrator is
        # authored, the authored brief is the prompt and the handoff contract is
        # appended to it — last word on format, no opinion about what is said.
        # (An authored brief ends with its own "exactly one sentence" rule, which
        # is why the override has to be explicit rather than merely later.)
        shape = (
            f"OUTPUT FORMAT — this replaces any format instruction above. Write a SHORT "
            f"radio-play style narration: 2 to 5 lines that hand off between these voices "
            f"where it fits: {cast_names}. EACH LINE IS EXACTLY ONE SHORT SENTENCE. Respond "
            f'with ONLY a JSON array, each item {{"character": "<one of the voice names>", '
            f'"text": "<exactly one short sentence>"}}.'
        )
        prompt = (authored + "\n\n" + shape) if authored else (
            f"You script {world_label} PREMISE: {premise}"
            f"{scene_block}{recent_block}{focus_block}\n{avoid_block}\n"
            f"Write a SHORT radio-play style world-building narration: 2 to 5 lines that hand off between "
            f"these voices where it fits: {cast_names}. Keep it atmospheric, ominous, concrete — no meta, "
            f"no stage directions. EACH LINE IS EXACTLY ONE SHORT SENTENCE. Respond with ONLY a JSON array, "
            f'each item {{"character": "<one of the voice names>", "text": "<exactly one short sentence>"}}.'
        )
        raw = _ask(prompt, temp=0.9, tokens=320, use_lore=True)
        if _talk_llm_failed(raw):
            return [{"character": s["character"], "text": _clip_narration(s["text"])} for s in fallback]
        import json as _json, re as _re
        cleaned = _re.sub(r"^```(?:json)?|```$", "", (raw or "").strip(), flags=_re.MULTILINE).strip()
        try:
            arr = _json.loads(cleaned)
        except Exception:
            m = _re.search(r"\[.*\]", cleaned, _re.DOTALL)
            arr = _json.loads(m.group(0)) if m else None
        segs = []
        if isinstance(arr, list):
            for it in arr[:4]:  # cap lines — bounds TTS cost + payload size
                if isinstance(it, dict) and (it.get("text") or "").strip():
                    # One sentence PER LINE here — the radio play gets its
                    # length from the handoff between voices, not from stacking
                    # sentences inside a single voice's line.
                    one = _clip_narration(
                        _strip_narration_staging((it.get("text") or "")[:400], acted))
                    if one:
                        segs.append({"character": (it.get("character") or "narrator").strip().lower(),
                                     "text": one})
        return segs or [{"character": s["character"], "text": _clip_narration(s["text"])} for s in fallback]

    # Single-voice narration — one lone voice thinking out loud, in exactly ONE
    # short sentence (a bridging beat, not a monologue).
    #
    # When a SPECIFIC focus is provided (e.g. MOVE TO's "reveal a dark truth"
    # follow-up), the focus text takes primacy over the generic "afraid /
    # uneasy / must find out what happened here" template — otherwise the
    # baseline mood-instructions overwhelm the focus and every follow-up line
    # collapses back into the same generic "I have to find out what happened
    # here" beat. With no focus, keep the original evocative baseline.
    # WHO the narrator is and HOW they speak is authored (`narrator_direction`),
    # not baked in here: it was three hardcoded f-strings, so the one voice that
    # talks directly to the player was the one voice you couldn't write.
    if authored:
        return _narrator_one_line(authored + "\n" + alternation, fallback, acted, thought=bool(lens))

    if (focus or "").strip():
        prompt = (
            f"You are the NARRATOR of {world_label} You are {narrator_self} "
            f"speaking quietly to yourself.{chr(10) + lens + chr(10) if lens else ' '}PREMISE: {premise}"
            f"{scene_block}{recent_block}\n\n"
            f"INSTRUCTIONS FOR THIS LINE: {focus.strip()}\n{avoid_block}\n"
            f"Speak in FIRST PERSON, as your own thinking. Plain words. "
            f"No meta, no stage directions, no purple prose. Follow the INSTRUCTIONS above exactly, "
            f"and take the shape of the line from the beats named at the end."
        )
    else:
        # Direct the VOICE, never the content. The shipped line used to command
        # the feeling and the intent — "say how you FEEL: afraid, uneasy, but
        # determined; make it clear you have to find out what happened here" —
        # so every unfocused narration was ordered to land on the same beat, and
        # then did. Repetition was not the model drifting; it was the brief.
        prompt = (
            f"You are the NARRATOR of {world_label} You are {narrator_self} "
            f"speaking quietly to yourself.{chr(10) + lens + chr(10) if lens else ' '}PREMISE: {premise}"
            f"{scene_block}{recent_block}\n{avoid_block}\n"
            f"Speak in FIRST PERSON, as your own thinking — the way it occurs to you, "
            f"not the way a report reads. Plain words. "
            f"Name something specific from what is in front of you or from what just happened. "
            f"Do NOT recite the mission, do NOT summarise the premise, and do NOT describe your "
            f"general mood — it must only make sense in THIS moment and nowhere else. "
            f"No meta, no stage directions, no purple prose. "
            f"Take the shape of the line from the beats named at the end."
        )
    return _narrator_one_line(prompt + "\n" + alternation, fallback, acted, thought=bool(lens))


def _authored_narrator_brief(**fields) -> str:
    """The editor's narrator brief, filled in — or "" to use the shipped voice.

    One place, because both narration paths need it and only one of them used
    to have it. Everything the engine knows about this moment goes in as a
    placeholder; a template that names one we don't supply is an authoring
    mistake, not a crash, so it falls back and says why in the log.
    """
    template = (PROMPTS.get("narrator_direction") or "").strip()
    if not template:
        return ""
    # The character's lens goes right under the VOICE line, where the brief
    # says how the narrator talks — in every World's copy of the brief, none
    # of which name {lens}. An author who wants it elsewhere writes {lens}.
    lens = str(fields.get("lens") or "")
    if lens and "{lens}" not in template:
        lines = template.split("\n")
        at = next((i for i, ln in enumerate(lines) if ln.strip().upper().startswith("VOICE:")), 0)
        lines.insert(at + 1, lens.replace("{", "{{").replace("}", "}}"))
        template = "\n".join(lines)
    fields.setdefault("lens", "")
    try:
        return template.format(**fields)
    except (KeyError, IndexError, ValueError) as fmt_err:
        print(f"[NARRATOR] narrator_direction has a bad placeholder "
              f"({fmt_err}); using the shipped voice", flush=True)
        return ""


def _narrator_one_line(prompt: str, fallback: list, acted: str = "", thought: bool = False) -> list:
    """Ask for the narrator's line and clip it to a beat. Shared by the authored
    path and the shipped fallback so both behave identically.

    `tokens` has to clear three short sentences with room to land the last full
    stop — at 80 the model was being cut off mid-word and the clip then threw
    away the unfinished sentence, which read as the narrator trailing off.
    """
    line = _ask(prompt, temp=0.85, tokens=140, use_lore=True)
    if _talk_llm_failed(line):
        return [{"character": s["character"],
                 "text": _clip_narration(s["text"], _NARRATION_MAX_SENTENCES)}
                for s in fallback]
    spoken = _strip_narration_staging((line or "")[:600], acted)
    return [{"character": "narrator",
             "text": _clip_narration(spoken, _THOUGHT_MAX_SENTENCES if thought
                                     else _NARRATION_MAX_SENTENCES)}]


#: A thought is one sentence; two lets a fragment land ("Fresh tracks. Not his.").
_THOUGHT_MAX_SENTENCES = 2

NARRATOR_MEMORY = 6


def _remember_narration(script: list, session_id: str) -> None:
    """Keep the last few narrated lines so the next one can be told not to
    repeat them.

    Best-effort and never raises: a narration that fails to be remembered is a
    slightly more repetitive next line, which must never be allowed to fail the
    narration the player is waiting on.
    """
    try:
        lines = [str((s or {}).get("text") or "").strip() for s in (script or [])]
        lines = [ln for ln in lines if ln]
        if not lines:
            return
        with WORLD_STATE_LOCK:
            st = _load_state(session_id)
            kept = [str(x) for x in (st.get("narrator_recent") or []) if str(x).strip()]
            st["narrator_recent"] = (kept + lines)[-NARRATOR_MEMORY:]
            # Counted separately from the list it is remembered in, because the
            # list is CAPPED and the beat rotation is driven off this. Reusing
            # the list's length froze the rotation at one pairing the moment the
            # cap was reached — see _beat_directive.
            st["narrator_beat"] = int(st.get("narrator_beat") or 0) + 1
            _save_state(st, session_id)
            _sync_ambient_state(st, session_id)
    except Exception as e:
        log_error(f"[NARRATOR] could not remember narration: {e}")


def api_narrator_worldbuild():
    """Generate a story-aware world-building narration and (optionally) speak it.

    Request JSON: {"focus"?: str, "follow_focus"?: str, "acted"?: str,
                   "deed_kind"?: str, "deed_target"?: str,
                   "multi"?: bool, "speak"?: bool, "session_id"?}

    `deed_kind` / `deed_target` say HOW the player acted and on WHAT — see
    _DEED_PHRASING. Without them every route into the game reads to the
    narrator as the same anonymous event.
    Response: {"segments": [{character, text, voice_id?, audio?}], "voice": bool}
    With speak=false (or no key) it returns text-only segments the client can
    display and/or send to /api/narrator/narrate later. Read-only."""
    try:
        if _rate_limited("narrator_worldbuild", 3.0):
            return jsonify({"error": "slow down", "segments": []}), 429
        data = request.get_json(silent=True) or {}
        focus = re.sub(r"\s+", " ", str(data.get("focus") or "")).strip()[:240]
        acted = re.sub(r"\s+", " ", str(data.get("acted") or "")).strip()[:240]
        # Optional SECOND focus — appended to the primary script's segments in
        # one round trip so a caller who needs a bridging + follow-up beat (e.g.
        # MOVE TO's black loading transition) never has to fire two requests
        # (which would hit the per-IP rate limit). Always single-voice; the
        # multi-voice path is inherently multi-line and doesn't need this.
        follow_raw = str(data.get("follow_focus") or "")
        follow_focus = re.sub(r"\s+", " ", follow_raw).strip()[:240]
        multi = bool(data.get("multi"))
        speak = data.get("speak", True)  # legacy: server-side TTS audio inline
        session_id = data.get("session_id", "default")
        deed_kind = re.sub(r"\s+", " ", str(data.get("deed_kind") or "")).strip()[:24]
        deed_target = re.sub(r"\s+", " ", str(data.get("deed_target") or "")).strip()[:120]
        script = _narrator_script(focus, multi, session_id, acted=acted,
                                  deed_kind=deed_kind, deed_target=deed_target)
        # A character thinks ONE thought per narration — the MOVE TO bridge's
        # second line ("go one step further in") is two lines where one was
        # asked for, so a run with a lens drops it.
        if follow_focus and _narrator_lens():
            follow_focus = ""
        if follow_focus:
            # Remembered BEFORE the follow-up is asked for, not after both.
            # Every per-line guard reads `narrator_recent` — the beat rotation,
            # the "do not begin this one that way" opening, the rut words — so
            # generating both from one snapshot meant the second line was
            # written blind to the first: same rotation index, same forbidden
            # opening, nothing saying they had to differ. Two lines in one
            # breath, and the likeliest pair in the game to sound like one
            # sentence said twice. This is also what lets the client stop
            # hardcoding "fact, then question" to force them apart.
            _remember_narration(script, session_id)
            follow_script = _narrator_script(follow_focus, False, session_id, acted=acted,
                                             deed_kind=deed_kind, deed_target=deed_target)
            _remember_narration(follow_script, session_id)
            script = list(script or []) + list(follow_script or [])
        else:
            _remember_narration(script, session_id)
        # Attach the resolved voice and delivery per line; the client asks
        # /api/narrator/say for each one while the line before it plays, so
        # the first line is not held back by the synthesis of the last.
        for seg in script:
            seg["voice_id"] = _segment_voice(seg.get("character"), seg.get("voice_id"))
            seg["style"] = resolve_cast(seg.get("character")).get("style", "")
        can = _speech_available()
        if speak and can:
            voiced = _narrate_segments(script)
            return jsonify({"segments": voiced, "voice": True, "voice_available": True})
        return jsonify({"segments": script, "voice": False, "voice_available": can})
    except Exception as e:
        import traceback as _tb
        log_error(f"[NARRATOR] worldbuild failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e), "segments": []}), 500


def api_talk_message():
    """One turn of a text conversation with a SCAN subject (the always-on path).

    Request JSON:
        {
          "subject": {"label", "kind", "speaks"},
          "messages": [{"role": "user"|"assistant", "content": str}, ...],
          "session_id"?: str
        }
    Response JSON: {"reply": str}

    The server rebuilds the story-aware persona each call from CURRENT state, so
    the character stays aware of how the world has evolved between lines. The
    client owns the running transcript and sends it back each turn. Read-only.
    """
    try:
        if _rate_limited("talk_message", 0.8):
            return jsonify({"error": "slow down", "reply": "\u2026"}), 429
        data = request.get_json(silent=True) or {}
        subject = data.get("subject") or {}
        messages = data.get("messages") or []
        session_id = data.get("session_id", "default")
        if not isinstance(subject, dict) or not (subject.get("label") or "").strip():
            return jsonify({"error": "missing subject"}), 400
        if not isinstance(messages, list):
            messages = []
        # Text mode reuses the same opening line the client already showed (skip
        # a redundant LLM call); the transcript itself carries the conversation.
        opening = ""
        for _m in messages:
            if isinstance(_m, dict) and _m.get("role") == "assistant":
                opening = _m.get("content") or ""
                break
        context = build_talk_context(
            subject, session_id, opening_override=opening, include_vision=False,
        )
        persona = context["persona_prompt"]

        # Render the running transcript into the prompt. Keep only the last ~12
        # turns so the prompt stays bounded on long conversations.
        lines = []
        for m in messages[-12:]:
            if not isinstance(m, dict):
                continue
            role = m.get("role")
            content = (m.get("content") or "").strip()
            if not content:
                continue
            who = "INVESTIGATOR" if role == "user" else context["subject"]["label"].upper()
            lines.append(f"{who}: {content[:400]}")
        transcript = "\n".join(lines)

        if not LLM_ENABLED:
            return jsonify({"reply": "[static swallows the reply — the channel is dead]"})

        prompt = (
            persona
            + "\n\nCONVERSATION SO FAR:\n"
            + (transcript or "(the investigator has just approached you)")
            + f"\n\nRespond as {context['subject']['label']}, in character, the way a real person would "
            "actually say it out loud — 1 to 2 short sentences, plain and human, never a monologue. "
            "Output ONLY your spoken reply — no name prefix, no stage directions."
        )
        reply = _ask(prompt, temp=0.9, tokens=80, use_lore=False)
        reply = (reply or "").strip().strip('"').strip()
        if _talk_llm_failed(reply):
            reply = "[the channel breaks up — say that again]"
        # Strip an accidental leading "LABEL:" prefix if the model added one.
        label_up = context["subject"]["label"].upper()
        if reply.upper().startswith(label_up + ":"):
            reply = reply[len(label_up) + 1:].strip()
        return jsonify({"reply": reply[:600]})
    except Exception as e:
        import traceback as _tb
        log_error(f"[TALK] message failed: {e}")
        _tb.print_exc()
        return jsonify({"error": str(e), "reply": "…"}), 500


def api_investigate():
    """Store an 'investigation' texture the player captured from the scene.

    The TOUCH tool (and, later, a 'photograph' mechanic) crops a small thumbnail
    from the region around/under the reticle — a close-up specimen of what the
    player is looking at. This persists that crop to disk and records its
    metadata in state['investigations'] so it can seed future scene-driven
    prompt mechanics (interacting with the world by referencing what you've
    examined closely).

    Request JSON: {texture: dataURL, region?:{x,y,w,h} (0..1), kind?, note?, label?}
    Response JSON: the stored entry {id, kind, label, note, region, image_url, ts}.
    The crop is saved as investigation_<ts>.jpg — a .jpg, so (like scan/observe
    grabs) it never leaks into the .png-only VHS tape.
    """
    import base64 as _b64, re as _re, time as _time
    from pathlib import Path as _Path
    global state
    try:
        data = request.get_json(silent=True) or {}
        tex = data.get('texture')
        session_id = data.get('session_id', 'default')
        kind = (str(data.get('kind') or 'touch'))[:24]
        note = (str(data.get('note') or ''))[:400]
        label = (str(data.get('label') or ''))[:120]
        region = data.get('region') if isinstance(data.get('region'), dict) else None
        if not tex:
            return jsonify({"error": "missing texture"}), 400
        m = _re.match(r'^data:image/[^;]+;base64,(.*)$', tex, _re.DOTALL)
        raw = m.group(1) if m else tex
        try:
            img_bytes = _b64.b64decode(raw)
        except Exception:
            return jsonify({"error": "bad texture encoding"}), 400
        if len(img_bytes) < 64:
            return jsonify({"error": "texture too small"}), 400

        img_dir = _Path(_get_image_dir(session_id))
        img_dir.mkdir(parents=True, exist_ok=True)
        ts = int(_time.time() * 1000)
        fname = f"investigation_{ts}.jpg"
        (img_dir / fname).write_bytes(img_bytes)
        entry = {
            "id": ts,
            "kind": kind,
            "label": label,
            "note": note,
            "region": region,
            "image_url": f"/images/{fname}",
            "ts": ts,
        }
        MAX_INVESTIGATIONS = 60  # keep the case file bounded
        with WORLD_STATE_LOCK:
            st = _load_state(session_id)
            invs = st.setdefault('investigations', [])
            invs.append(entry)
            if len(invs) > MAX_INVESTIGATIONS:
                del invs[:-MAX_INVESTIGATIONS]
            _save_state(st, session_id)
            _sync_ambient_state(st, session_id)
        print(f"[INVESTIGATE] stored {kind} specimen {fname}", flush=True)
        return jsonify({"ok": True, **entry})
    except Exception as e:
        log_error(f"[INVESTIGATE] failed: {e}")
        return jsonify({"error": str(e)}), 500


def api_investigations():
    """List stored investigation textures for the session (most recent first)."""
    try:
        session_id = request.args.get('session_id', 'default')
        st = _load_state(session_id)
        invs = list(st.get('investigations', []))
        invs.reverse()
        return jsonify({"investigations": invs})
    except Exception as e:
        log_error(f"[INVESTIGATE] list failed: {e}")
        return jsonify({"investigations": []}), 500


def _spawn_scene_choices_reground(prompt_id, prev_image_url: str, session_id: str = 'default'):
    """Wait (bounded) for THIS turn's guide image to render, then reground the
    live choices on it via vision and push a choices_revised item. Runs entirely
    off the turn's critical path so it can NEVER stall/hang the turn (the prompt
    is already live); if the image never lands it just gives up. Reuses the
    observe reground pipeline so there's one grounding path."""
    if not WORLD_IMAGE_ENABLED or not VISION_ENABLED:
        return

    def _worker():
        try:
            img_dir = _get_image_dir(session_id)
            for _ in range(80):  # ~20s: wait for the async render to land
                st = _load_state(session_id)
                cur = st.get('current_image_url')
                if cur and cur != prev_image_url:
                    # current_image_url carries a ?session=… query string, and
                    # basename() keeps it — the path built from it can never
                    # exist, so this waited out its whole timeout every turn and
                    # the reground never ran once.
                    fpath = os.path.join(str(img_dir),
                                         os.path.basename(cur.split('?', 1)[0]))
                    if os.path.exists(fpath):
                        # Hand off to the shared reground pipeline (vision +
                        # regenerate choices + push choices_revised).
                        _spawn_observe_reground(fpath, cur, session_id, prompt_id)
                        return
                time.sleep(0.25)
            print(f"[REGROUND] guide image never landed for {session_id}; skipping", flush=True)
        except Exception as e:
            log_error(f"[REGROUND] worker failed: {e}")

    threading.Thread(target=_worker, daemon=True).start()


def _spawn_observe_reground(fpath: str, web: str, session_id: str, prompt_id):
    """Background: run vision on the observed video frame and regenerate choices
    grounded on what's actually visible, then push a 'choices_revised' feed item.
    Kept off the request path (vision + choice LLM calls are slow) so /api/observe
    never blocks or hangs the UI."""
    # Vision + choice LLM calls can be slow/rate-limited; never stack them.
    global _observe_reground_active
    if _observe_reground_active:
        return
    _observe_reground_active = True

    def _worker():
        global state, history, _observe_reground_active
        try:
            print(f"[OBSERVE] reground worker start: {fpath}", flush=True)
            vision = ""
            v_setting = v_spatial = ""
            v_witness = None
            try:
                vres = _vision_analyze_all(fpath)  # has an internal 30s timeout
                if isinstance(vres, dict):
                    vision    = (vres.get("description") or "").strip()
                    v_setting = (vres.get("setting") or "").strip()
                    v_spatial = (vres.get("spatial") or "").strip()
                    # Could anything in that frame see the player. Same call,
                    # one more parsed line — see WATCHERS in _vision_analyze_all
                    # and "the witness" beside the detection ladder. None when
                    # the field is missing, which is what a pre-WATCHERS cache
                    # entry and a failed vision call both look like; neither is
                    # allowed to assert an empty room.
                    v_witness = witness_from_vision(vres)
            except Exception as e:
                log_error(f"[OBSERVE] vision failed: {e}")
            print(f"[OBSERVE] vision len={len(vision)}", flush=True)
            if not vision:
                print("[OBSERVE] empty vision — skipping reground", flush=True)
                return

            with WORLD_STATE_LOCK:
                st = _load_state(session_id)
                st['current_observed_vision'] = vision
                # Realtime has no scene_image beat to score off, so this read
                # of the live frame is also what the ambience is built from.
                st['current_vision'] = vision
                record_witness(st, v_witness)
                # This vision text describes the frame that was ACTUALLY
                # rendered, which is the only honest answer to "did the object
                # the player touched survive the turn?" — the consequence text
                # is what we asked for, this is what we got.
                _resolve_permanence(st, vision)
                hist = _load_history(session_id)
                if hist:
                    hist[-1]['vision_dispatch'] = vision
                    hist[-1]['vision_analysis'] = vision
                    # Phase 2 runs before this frame exists, so it had no image to
                    # read these off. This is the only pass that sees the frame
                    # that actually rendered — drop them here and the stagnation
                    # guard and the drift beats never get a real label at all.
                    if v_setting:
                        hist[-1]['setting_type'] = v_setting
                    if v_spatial:
                        hist[-1]['spatial_compass'] = v_spatial
                    _save_history(hist, session_id)
                    if get_active_session_id() == session_id:
                        history = hist
                _save_state(st, session_id)
                _sync_ambient_state(st, session_id)

            # Local import, like every other generate_choices call site. Without
            # it this raised NameError on every run — swallowed by the worker's
            # except, so nothing 500'd and the only trace was one line in the
            # error log, but it meant the realtime anti-drift loop (regenerating
            # choices from the frame the player is actually looking at) had never
            # worked: the vision call was paid for, then thrown away.
            from choices import generate_choices
            # The live frame + its vision are the source of truth. The last
            # narrative dispatch describes the previous still and will pull
            # MOVE-TO-style choices back to objects that are no longer on
            # screen. Pass the filesystem path so generate_choices can attach
            # the JPEG (the /images/observed_… web URL used to resolve to
            # images/observed_….png, which does not exist).
            texts = generate_choices(
                client=client,
                prompt_tmpl=PROMPTS["player_choice_generation_instructions"],
                last_dispatch=vision,
                image_description=vision,
                image_url=fpath,
                world_prompt=st.get('world_prompt', ''),
                situation_summary=summarize_world_state(st),
                inventory=st.get('inventory'),
                n=3,
                beat_nudge=beat_nudge_text(st),
            ) or []
            print(f"[OBSERVE] regenerated {len(texts)} choices", flush=True)
            if not texts:
                return

            item = create_feed_item(
                type="choices_revised",
                content="",
                choices=[{"text": t} for t in texts],
                metadata={"prompt_id": prompt_id},
            )
            with WORLD_STATE_LOCK:
                st = _load_state(session_id)
                st['choices'] = [{"text": t} for t in texts]
                _feed_append(st, item)
                _save_state(st, session_id)
                _sync_ambient_state(st, session_id)
            print(f"[OBSERVE] re-grounded on video frame; {len(texts)} choices", flush=True)
        except Exception as e:
            log_error(f"[OBSERVE] reground failed: {e}")
        finally:
            _observe_reground_active = False

    # Clear the guard if the thread can't even start (thread exhaustion is a
    # live risk on a small gunicorn worker). Setting the flag before the spawn
    # and only clearing it inside the worker meant a failed start disabled
    # regrounding permanently for the rest of the process.
    try:
        threading.Thread(target=_worker, daemon=True).start()
    except Exception as e:
        _observe_reground_active = False
        log_error(f"[OBSERVE] could not spawn reground worker: {e}")


def api_regenerate_choices():
    global state
    logging.info("api_regenerate_choices: POST request received.")
    try:
        # Resolve THIS request's session id directly from Flask's request
        # object (see _resolve_request_session_id) rather than the shared
        # get_active_session_id() global — this handler calls a slow LLM
        # (generate_choices) synchronously, so a concurrent different-
        # session request has plenty of time to swap the ambient mirror
        # before we get to the save at the end.
        SID = _resolve_request_session_id()
        with WORLD_STATE_LOCK:
            fresh_state = _load_state(SID)
            current_feed_log = list(fresh_state.get('feed_log', [])) # Operate on a copy for reading context
            state_snapshot_for_context = fresh_state.copy() # For world prompt, etc.

        last_choice_prompt = None
        last_dispatch_text = "No recent dispatch found."

        for item in reversed(current_feed_log):
            if item.get('type') == 'player_choice_prompt':
                last_choice_prompt = item
                # Try to find the narrative dispatch that led to this old choice prompt
                prompt_index = current_feed_log.index(item)
                for prev_item_idx in range(prompt_index -1, -1, -1):
                    prev_item = current_feed_log[prev_item_idx]
                    if prev_item.get('type') == 'narrative_event':
                        last_dispatch_text = prev_item.get('content', last_dispatch_text)
                        break
                break
        
        if not last_choice_prompt:
            logging.warning("api_regenerate_choices: No prior player_choice_prompt found in feed_log.")
            # Use generic context if no prior prompt
            world_prompt_context = state_snapshot_for_context.get("world_prompt", "The situation is unclear.")
            image_desc_context = "The scene is ambiguous."
        else:
            # If we found a previous choice prompt, use its context (or what led to it)
            world_prompt_context = state_snapshot_for_context.get("world_prompt") # Current world prompt is best
            image_desc_context = state_snapshot_for_context.get("current_image_url") # Use current image if any for context
            # If last_choice_prompt had an image_url, that could also be relevant context,
            # but vision_dispatch for current state.current_image_url is better.
            if state_snapshot_for_context.get("current_image_url"):
                 vision_for_regen = _generate_vision_dispatch(last_dispatch_text, world_prompt_context)
                 if vision_for_regen : image_desc_context = vision_for_regen


        from choices import generate_choices
        situation_summary = summarize_world_state(state_snapshot_for_context)
        # generate_choices() returns a plain List[str], not a (choices, meta)
        # tuple — do not unpack it as one (see note in _process_turn_background).
        regenerated_choice_texts = generate_choices(
            client=client,
            prompt_tmpl=PROMPTS["player_choice_generation_instructions"],
            last_dispatch=last_dispatch_text,
            world_prompt=world_prompt_context,
            image_description=image_desc_context,
            situation_summary=situation_summary, # Use general summary
            n=3,
            temperature=0.7, # Slightly higher temp for variety
            beat_nudge=beat_nudge_text(state_snapshot_for_context),
        )

        prompt_text = last_choice_prompt.get("content", "What do you do now?") if last_choice_prompt else "The path is unclear. Choose wisely."
        # Use current image if available, or the one from the last prompt if that's more relevant
        image_for_new_choices = state_snapshot_for_context.get("current_image_url") # Prefer current image
        if WORLD_IMAGE_ENABLED == False: image_for_new_choices = None


        new_choice_prompt_item = _structure_choices_for_feed(
            regenerated_choice_texts,
            f"[REVISED OPTIONS] {prompt_text}", # Indicate these are regenerated
            image_url=image_for_new_choices
        )

        with WORLD_STATE_LOCK:
            st = _load_state(SID)
            st.setdefault('feed_log', []).append(new_choice_prompt_item)
            st['choices'] = new_choice_prompt_item['choices'] # Update current choices in state
            _save_state(st, SID)
            _sync_ambient_state(st, SID)
        
        logging.info(f"api_regenerate_choices: Regenerated choices. New prompt ID: {new_choice_prompt_item['id']}")
        return jsonify([new_choice_prompt_item])

    except Exception as e:
        log_error(f"Error in api_regenerate_choices: {e}")
        logging.exception("Exception in api_regenerate_choices:")
        error_item = create_feed_item(type="error_event", content=f"Failed to regenerate choices: {str(e)}")
        try:
            err_sid = _resolve_request_session_id()
            with WORLD_STATE_LOCK:
                err_state = _load_state(err_sid)
                err_state.setdefault('feed_log', []).append(error_item)
                _save_state(err_state, err_sid)
                _sync_ambient_state(err_state, err_sid)
        except Exception as e_log:
            log_error(f"Could not save error item to feed_log during api_regenerate_choices error handling: {e_log}")
        return jsonify([error_item]), 500


# ───────── OBJECT PERMANENCE ──────────────────────────────────────────────────
# The world model has none. Every frame is regenerated from `visual_scene`, so a
# noun that text does not name simply stops existing — which is what made SCAN
# interactions feel inert. The player taps the steel door, commits to forcing it,
# and the next frame is a corridor with no door in it. The action resolved in the
# prose and vanished from the picture.
#
# So a turn issued by tapping a DETECTED object carries that object's label into
# the consequence prompt as a requirement: `visual_scene` must still show it.
# For exactly ONE turn. Pinning a noun for longer would freeze the scene and stop
# the world evolving, which is the opposite of what this simulation is for — the
# object has to survive the transition it was acted on, then it is free to go.
#
# Two things are then measured, because they fail independently:
#   • in_text   — did the consequence LLM keep the noun in `visual_scene`?
#                 (whether the model honoured the requirement)
#   • in_pixels — does the rendered frame's vision pass still describe it?
#                 (whether the image/world model drew what it was asked for)
# Both are free. The first is a string check on text the turn already produced;
# the second rides the reground pass that already analyses every new guide image.

def _permanence_subject(raw) -> str:
    """Normalize a tapped detection label into a comparable subject phrase."""
    s = str(raw or "").strip().lower()
    s = re.sub(r"[^a-z0-9\s\-]", "", s)
    return re.sub(r"\s+", " ", s).strip()[:40]


def _subject_in_text(subject: str, text: str) -> bool:
    """Whether `subject` is still being talked about in `text`.

    Tries the whole phrase, then its head noun: a model handed "rusted steel
    door" routinely writes "the door", and scoring that as a miss would make the
    measurement worthless. Plural head nouns count for the same reason.
    """
    subj = _permanence_subject(subject)
    hay = str(text or "").lower()
    if not subj or not hay:
        return False
    if re.search(rf"\b{re.escape(subj)}\b", hay):
        return True
    head = subj.split()[-1] if subj.split() else ""
    return bool(len(head) >= 3 and re.search(rf"\b{re.escape(head)}s?\b", hay))


def _permanence_directive(subject: str, is_move: bool) -> str:
    """The requirement block naming the object this turn may not delete.

    The `is_move` wording used to ask for the subject "central to this new
    vantage" — meant as "don't cut away from it," but a model handed that
    instruction satisfies it the cheapest way possible: a tight, centered
    hero shot of the object, isolated, nothing around it. That reads as the
    OBJECT moving to the middle of the screen, not the PLAYER walking up to
    it — exactly backwards from what a relocation is supposed to sell. The
    fix asks for the same guarantee (the object is provably in the new
    frame) without ever using the word that made "centered and dominant"
    the easy answer.

    The replacement then overcorrected into a different failure: it described
    the object as sitting "in the room the player just crossed into ... on its
    wall, floor, or surface". That is a true sentence about a steel door or a
    control panel and a nonsense one about a mesa, a water tower or a parked
    truck — and those are exactly what SCAN detects outdoors. Handed
    subject='mesa', the model did the only thing that sentence permits: it
    invented an enclosure, put the player inside it, and hung the mesa behind
    it as a backdrop. The guarantee here is that the object is provably in the
    new frame and is the thing the player REACHED, so the wording has to hold
    for a landform in open desert as readily as for a hatch in a corridor.
    """
    subj = _permanence_subject(subject)
    if not subj:
        return ""
    survives = (
        f"the {subj} as the thing the player has ARRIVED AT — near enough that "
        f"it commands the depth in front of them, with the place it actually "
        f"stands in around it (its ground, its surroundings, whatever else is "
        f"there), the way it would look from a few steps away. What \"a few "
        f"steps away\" means depends on the {subj}: something you could reach "
        f"out and touch is at arm's length, something the size of a building "
        f"or a landform is seen from its foot. Do NOT move the {subj} into a "
        f"room, an interior or an enclosure it was not already part of, and do "
        f"NOT leave it as a distant shape while some nearer structure takes "
        f"the foreground — that is the one failure this requirement exists to "
        f"prevent. Not a close-up of the {subj} alone with nothing else in "
        f"frame either; that is a product photo, not a person arriving "
        f"somewhere"
        if is_move else
        f"the {subj} still visible and CHANGED BY the action — opened, moved, "
        f"damaged, reacting — not absent"
    )
    return (
        f"\n\nOBJECT PERMANENCE: the player is acting on the \"{subj}\", which the "
        f"scene detector confirmed is in the frame right now. Your `visual_scene` "
        f"MUST name it and show {survives}. That text is the only thing the "
        f"renderer sees, so a `visual_scene` that omits the {subj} deletes the "
        f"very thing the player just reached out and touched.\n"
    )


def _action_directive(is_interaction: bool, is_move: bool, subject: str,
                        also_relocating: bool = False) -> str:
    """The requirement block for an action that relocates the camera or hands
    the player a specific SCAN object — MOVE TO, INTERACT, or (via
    `also_relocating`) a curated/typed choice that is about to earn its own
    hard cut for the same reason MOVE always does.

    This used to be gated on `is_interaction` alone — a SCAN tap only —
    which meant a plain choice like "Sprint toward the side corridor" (forced
    into a hard cut by the egress backstop, or by the ordinary text
    classifier) got NONE of this. The model writing that turn's `visual_scene`
    had no steering away from a dramatic reaction pose — spinning to face
    the threat, hands raised toward camera — and nothing telling it this is
    the same kind of beat MOVE is. That is exactly the seam a real run fell
    through: MOVE turns held a consistent over-the-shoulder framing for six
    turns straight, then the first curated escape choice flipped the camera
    to face the character on the very next one. `also_relocating` closes
    that seam by asking the caller "is this choice about to get a hard cut
    for a reason OTHER than a SCAN tap?" — egress-forced or text-classified —
    and routing it through the exact same TRAVERSAL text.

    MOVE and INTERACT are different verbs and need different beats, but they
    used to share one block that told the model the player was "handling" the
    thing. On a MOVE turn that is a lie: the player only walked toward it. The
    consequence came back as an ordinary action from an unchanged camera, so the
    footage read as standing still while something happened nearby, which is
    precisely what MOVE is supposed not to look like. The traversal text below
    asks for the one thing that makes travel legible in a still: a new vantage.
    """
    relocating = is_move or also_relocating
    if not is_interaction and not relocating:
        return ""
    if relocating:
        directive = (
            "\n\nTRAVERSAL: this is a full relocation, every time — the engine "
            "has already committed to a fresh composition for this turn (see "
            "CAMERA above), so `visual_scene` must land somewhere the previous "
            "frame did not show, not the old view with the destination nudged "
            "closer. This is locomotion, not handling — the player does not "
            "touch, open, or operate anything yet, and nothing here is a "
            "confrontation. Write the crossing itself: what they move past, "
            "what the footing is, what falls away behind them. The scene MUST "
            "end from a NEW VANTAGE POINT the camera did not have a moment "
            "ago — whatever surrounded the player before is now behind them, "
            "replaced by what's here. A description that could be mistaken "
            "for the previous frame with the object pasted into it is WRONG. "
            "This is a person arriving somewhere, not a product photo of the "
            "destination: hold a normal human vantage — the room's walls, "
            "floor, and depth around the player — and let the destination sit "
            "wherever it actually would from a few steps away, not centered "
            "and filling the frame. A tight, centered hero shot of the thing "
            "the player moved to, with no space around it, reads as an "
            "object floating in a void, not a person who just walked there. "
            "When the camera shows the player character, it stays BEHIND them "
            "as they arrive — they face into the new space, we see their back. "
            "Do not spin around to a walking-toward-camera hero shot just "
            "because this is a new scene. Fleeing, sprinting, or scrambling "
            "away is still travel, not a turn-and-confront beat, even under "
            "threat. "
            "When the destination is ITSELF an opening — a door, hatch, vent, "
            "threshold, entrance, stair — visual_scene is the space on the FAR "
            "SIDE of it, not another exterior shot of its face: arriving means "
            "they crossed through. When it is anything else — a landform, a "
            "vehicle, a tank, a mast, a body, a stretch of open ground, the "
            "outside of a structure — they arrive AT it and stop there, and "
            "they stay outdoors if they were outdoors. Do not manufacture an "
            "interior, an enclosure or a doorway for them to have passed "
            "through, and do not swap the destination for a nearer or more "
            "photogenic thing beside it: the place they end up is the place "
            "they said they were going. "
            "When the camera shows the player character, `visual_scene` must "
            "name them in the place (what they are doing there), not only the "
            "empty room ahead of their eyes. "
            "Covering ground is exposure: the trip itself should cost something "
            "or reveal something.\n"
        )
    else:
        directive = (
            "\n\nOBJECT INTERACTION: The player is deliberately handling/entering a "
            "specific thing in the scene. This action MUST produce a consequential "
            "development — reveal something new, trigger a mechanism or reaction, "
            "disturb the environment, draw attention, or expose a threat/clue. Never "
            "answer with 'nothing happens' or a purely cosmetic result. Meddling with "
            "the unknown here should carry real risk and push the mystery forward.\n"
        )
    # …and the thing must still be THERE afterwards. Both directives ask for
    # consequence, which a model can satisfy by cutting to somewhere new
    # entirely — see the OBJECT PERMANENCE block for why that reads as the
    # action never landing. `subject` is empty for a non-SCAN relocation (no
    # detected object was tapped), so this contributes nothing in that case —
    # there is nothing to name, which is correct, not a gap.
    return directive + _permanence_directive(subject, relocating)


def _permanence_record(subject: str, is_move: bool, visual_scene: str) -> Optional[dict]:
    """The pending permanence claim for a turn, or None when nothing was tapped."""
    subj = _permanence_subject(subject)
    if not subj:
        return None
    kept = _subject_in_text(subj, visual_scene)
    print(f"[PERMANENCE] subject='{subj}' kind={'move' if is_move else 'interact'} "
          f"in_text={kept}", flush=True)
    return {
        "subject": subj,
        "kind": "move" if is_move else "interact",
        "in_text": kept,
        "in_pixels": None,   # filled in by the reground pass; None = never checked
        "pending": True,
    }


def _resolve_permanence(st: dict, vision_text: str) -> None:
    """Settle this turn's permanence claim against the rendered frame.

    Mutates `st` in place; the caller owns the lock and the save. Resolving is
    one-shot: a claim the reground never reached stays pending until the next
    turn overwrites it, so a stale subject can never be scored against a frame
    it was never asked about.
    """
    rec = st.get("permanence")
    if not isinstance(rec, dict) or not rec.get("pending"):
        return
    held = _subject_in_text(rec.get("subject", ""), vision_text)
    rec["in_pixels"] = held
    rec["pending"] = False
    st["permanence"] = rec
    print(f"[PERMANENCE] subject='{rec.get('subject')}' survived into the rendered "
          f"frame: {held}", flush=True)


# ───────── COMBINED dispatch generator (saves 1 API call) ─────────────────────
def _look_book_story(state: dict) -> str:
    """The look book's story half (look_book.story_directive); "" when off."""
    try:
        import look_book
        return look_book.story_directive(get_active_session_id(), state)
    except Exception:
        return ""


def _wardrobe_change_plates(state: Optional[dict]) -> Dict[str, str]:
    """{plate path: item name} for what was put on at this turn's boundary,
    while the change is being drawn (see _wardrobe_change_directive)."""
    if not _wardrobe_change_directive(state):
        return {}
    ch = (state or {}).get("look_changed") or {}
    out: Dict[str, str] = {}
    for p, name in zip(ch.get("plates") or [], ch.get("put_on") or []):
        if p and os.path.exists(str(p)):
            out[str(p)] = str(name)
    return dict(list(out.items())[:1])


def _wardrobe_change_directive(state: Optional[dict]) -> str:
    """For the image model, the turn a new look is taken and the one after:
    what changed on the player, said so the previous frame's outfit loses."""
    ch = (state or {}).get("look_changed") or {}
    if not ch:
        return ""
    try:
        age = int((state or {}).get("turn_count") or 0) - int(ch.get("at") or 0)
    except Exception:
        age = 99
    if age < 0 or age > 1:
        return ""
    bits = []
    if ch.get("put_on"):
        bits.append("NOW WEARING " + ", ".join(ch["put_on"]))
    if ch.get("took_off"):
        bits.append("NO LONGER WEARING " + ", ".join(ch["took_off"]))
    if not bits:
        return ""
    who = str(ch.get("who") or "the player")
    return (f"WARDROBE CHANGE — {who} is {'; '.join(bits)}. Draw them in it in "
            "every panel, exactly as the CHARACTER SHEET shows it, even though the "
            "previous frame shows the old outfit. Nothing else about them changes.")


def _look_note_directive(state: dict) -> str:
    """One line when the player's character changed what they wear since the
    last beat (characters.sync_run_look set it at this turn's boundary): the
    fitting has already changed the turnaround every frame is drawn from, and
    the prose should know it too — "You are now wearing …"."""
    line = str((state or {}).get("look_note") or "").strip()
    if not line:
        return ""
    # The visual scene is what the picture is drawn from, and it beats every
    # reference: told only to "mention it in passing", the prose did and the
    # frames kept the old helmet (2026-09-24 harness). The beat shows it.
    return (f"WHAT THE PLAYER IS WEARING CHANGED: {line} It is on them now and "
            "never contradict it. This beat's visual_scene MUST show it plainly — "
            "the camera catches it (a glance, a hand settling it, a turn of the head) "
            "and names it with its look, so the picture draws the new gear rather "
            "than what the last frame showed.\n")


def _generate_combined_dispatches(choice: str, state: dict, prev_state: dict = None, prev_vision: str = "", current_image: str = None, fate: str = "NORMAL", is_interaction: bool = False, subject: str = "", is_move: bool = False, environment_streak: int = 0, is_custom_action: bool = False) -> tuple[str, str, bool, list, Optional[bool]]:
    """
    Generate BOTH narrative dispatch AND vision dispatch in ONE API call.
    Now supports multimodal input - can see the current frame!
    
    Args:
        fate: Luck modifier - "LUCKY", "NORMAL", or "UNLUCKY"

    Returns: (dispatch, vision_dispatch, player_alive, provisional_choices,
              relocated)

    `relocated` is the model's own answer to "did the beat I just wrote move
    them somewhere else", or None when it did not say. The renderer uses it
    instead of guessing a location change out of the choice wording — see the
    hard_transition read in advance_turn_image_fast.

    provisional_choices is a best-effort list of next-action options produced in
    THIS same call (see the OUTPUT CONTRACT addendum below). The turn loop can
    use them to skip the separate choice-generation LLM round-trip; it falls
    back to the dedicated generator whenever the list is empty/unusable.
    """
    try:
        # Get previous vision analysis for spatial consistency.
        # Source priority:
        #   1. `prev_vision` arg (passed by caller — preferred, may be richer)
        #   2. `history[-1].vision_analysis` (fallback when caller didn't pass)
        # NOTE: Previously both sources were injected separately ("CURRENT VISUAL
        # SCENE" + "PREVIOUS SCENE"), duplicating identical text and confusing the
        # LLM about which is authoritative. We now use ONE consolidated block.
        prev_vision_analysis = (prev_vision or "").strip()
        if not prev_vision_analysis and history and len(history) > 0:
            last_entry = history[-1]
            if last_entry.get("vision_analysis"):
                prev_vision_analysis = last_entry["vision_analysis"][:300]

        # This block lands second-to-last in the assembled prompt, immediately
        # before the output instructions, which makes it the most recent and
        # most concrete thing the model reads. It used to say "Do NOT change
        # locations unless the choice explicitly moves through a door,
        # entrance, or exit. Stay in the same environment." — and it won,
        # against a template that spends 15,000 characters insisting actions
        # always succeed and "Change location → You are now THERE".
        #
        # So the player got stuck in rooms. Told to keep them where they were
        # but still to write an interesting beat, the model changed something
        # ABOUT the room instead: a live run answered "explore deeper into
        # this space" by slamming shut the door the player had opened the turn
        # before. It never decided they failed; it was obeying a standing
        # order not to leave, and inventing a reason. The "unless it's a door"
        # exemption never helped, because corridors, yards, gaps and stairs
        # are not doors.
        #
        # What the block is actually for is continuity — no teleporting, no
        # drifting to an unrelated place — and that is not the same
        # instruction as "do not move". It now constrains where they can
        # arrive rather than whether they may.
        spatial_context = ""
        if prev_vision_analysis:
            spatial_context = (
                f"\n\nCURRENT VISUAL SCENE (the camera is HERE — visible state of the "
                f"world right before your action): {prev_vision_analysis[:300]}\n"
                f"Anywhere they arrive has to be somewhere this place could plausibly "
                f"lead, reachable on foot from here, with the place they left still "
                f"behind them. Do not cut to an unrelated location. When the action "
                f"does NOT move them, keep the ground, landmarks and layout exactly "
                f"as described above."
            )

        prev_context = _previous_beat_block(state)
        world_prompt = state.get('world_prompt', '')
        
        # (An `image_context` string used to be built here — "ATTACHED IMAGE =
        # CURRENT LOCATION. You are HERE. Do NOT teleport yourself." — and
        # never used. Removed rather than wired up: it says the same thing
        # that used to pin the player in place, so the next person to notice
        # the dead variable would have been fixing a bug by reintroducing one.
        # Where the player is is already established by the attached frame and
        # by CURRENT VISUAL SCENE above.)

        # Detect timeout penalties
        is_timeout_penalty = any(phrase in choice.lower() for phrase in [
            "crushes you", "hits you", "attacks you", "shoots you", "tears into you",
            "engulfs you", "mauls you", "slams into you", "impacts you", "sustained",
            "to torso", "to limb", "trauma", "burns to", "pressure on", "collapses on"
        ])
        
        # Whether the player typed this rather than picking a curated choice or
        # SCAN object. Used to used to guess this from the choice TEXT — did it
        # start with "Approach"/"Examine"/"Use"/"Take"/"Look"/"Search"/"Listen"/
        # "Wait"? — which matched the choice phrasing from months ago and
        # nothing since choices moved to "Enter the...", "Walk over to...",
        # "Move to..." framing. That made it fire on essentially every curated
        # pick (confirmed: 6/6 in a live smoke test), injecting a "describe
        # them DOING the action" header on every single turn regardless of
        # what the player actually did. The caller now threads the real signal
        # through instead — see is_custom_action in advance_turn_image_fast's
        # docstring.
        is_free_will = bool(is_custom_action)
        
        # Build FREE WILL emphasis if detected
        free_will_header = ""
        if is_free_will:
            try:
                safe_choice = choice[:80].encode('ascii', 'replace').decode('ascii')
                print(f"[FREE WILL ACTION DETECTED] {safe_choice}", flush=True)
            except:
                print(f"[FREE WILL ACTION DETECTED] (choice contains special characters)", flush=True)
            free_will_header = (
                "\n\n🔥🔥🔥 THIS IS A FREE WILL ACTION 🔥🔥🔥\n\n"
                f"The player used FREE WILL to command: \"{choice}\"\n\n"
                "CRITICAL INSTRUCTIONS FOR FREE WILL:\n"
                "1. The player IS PERFORMING this exact action RIGHT NOW\n"
                "2. Describe them DOING the action in the active camera mode "
                "(third-person follow shows their body doing it; first-person shows it from their eyes)\n"
                # This used to read "Show the ATTEMPT - the physical movements,
                # the effort", and that one word undid the whole block. An
                # ATTEMPT is a thing that can fail, so an action the model
                # judged impossible came back as the attempt failing: "fly to
                # antarctica" produced "You attempt to take flight, but your
                # body remains pinned to the unforgiving red earth" — which is
                # verbatim the pattern action_consequence_instructions already
                # forbids ('NO "you try but fail"', 'FORBIDDEN: "You try to
                # [action] but..."'). Two prompts disagreed and the one sitting
                # next to the action won.
                "3. The action HAPPENS. Write it LANDING, not being attempted. "
                "Never 'you try to', 'you attempt to', 'you start to', or a "
                "body that 'remains' where it was\n"
                "4. THEN show what the world does about it - that is where cost, "
                "damage, noise and attention belong\n"
                "5. BEYOND A HUMAN BODY? THE WORLD SUPPLIES THE MEANS. Flying, "
                "crossing a continent, calling in help - something in the "
                "fiction makes it possible: a vehicle, a rope, a stranger, a "
                "machine, a door that was unlocked, luck that will be paid for. "
                "Invent the means, let the action succeed, and charge for it in "
                "the consequence. Refusing outright is the one answer that is "
                "always wrong - it tells the player their idea did not count\n"
                "6. Example: If they say 'Kick door' → 'You draw back your leg and slam your boot into the door. [result]'\n"
                "7. Example: If they say 'Climb fence' → 'You grab the chain-link and haul yourself up. [result]'\n"
                "8. Make their command REAL and VISIBLE in the text\n\n"
                "Your dispatch MUST start by showing them performing this specific action.\n"
            )
        
        # Build fate modifier text.
        #
        # This is the single most influential block in the turn and it is not in
        # the editable prompt file, so it escaped the prompt trim entirely. It
        # used to run 280 words: five headed categories, fifteen bullets, three
        # forbidden patterns. Two things were wrong with it beyond the length.
        #
        # It pointed at a rule by a heading the payload no longer contains: it
        # cited the old death-fairness heading as still applying "above", while
        # the consequence template's heading now reads "INJURY IS THE DEFAULT,
        # NOT DEATH". A dangling cross-reference is worse than no reference — it
        # tells the model there is a governing rule somewhere it cannot find.
        # Nothing here cites a heading by name any more; the rule is restated in
        # one line instead, so a prompt rename cannot silently orphan it.
        #
        # And every one of its complications could REPLACE the player's action
        # instead of costing them for it. "Equipment fails", "sprained ankle" —
        # applied to a MOVE, the cheapest way to realise those is to snag the
        # player mid-stride, which is precisely what a live run produced: "you
        # grunt, shifting your weight to lunge forward, BUT the film strip
        # tightens, snagging your boot and dragging you to your knees." The
        # template's "A MOVE ALWAYS COMPLETES" rule was already in the payload
        # and lost, because this block is later and far more concrete. So the
        # additive-not-substitutive rule has to live HERE, where the model is
        # actually deciding what goes wrong.
        fate_modifier = ""
        if fate == "LUCKY":
            fate_modifier = (
                "\n\n🎰 LUCKY: something breaks your way. Add ONE tangible "
                "advantage on top of what the player did — a door already open, "
                "a patrol turning away, cover where none was expected, a threat "
                "hesitating, something useful within reach. Concrete and usable, "
                "not just a lighter mood.\n"
            )
        elif fate == "UNLUCKY":
            fate_modifier = (
                "\n\n🎰 UNLUCKY: fate turns against you. Add ONE concrete "
                "complication — and it is the COST of the action, never a "
                "cancellation of it. What the player did still happened: they "
                "got the door open, crossed the gap, reached the room. The "
                "complication is what it took, or what is waiting there.\n"
                "  WRONG: \"You lunge for it, but the cable snags your boot and "
                "drags you down.\"\n"
                "  RIGHT: \"You make it through, the cable tearing a strip out of "
                "your calf on the way.\"\n"
                "Prefer a character or an event: someone closing in, a creature "
                "emerging, an alarm tripping, a structure giving way under you. "
                "Otherwise a bad wound — broken, burned, lacerated, concussed — "
                "described in visceral specifics.\n"
                "Only characters and dramatic events may kill. Inert scenery — "
                "rebar, glass, debris, spores, a fall — wounds badly and never "
                "kills; `player_alive` stays true and the wound persists.\n"
            )
        # NORMAL = no modifier, outcome is purely based on choice

        # ── Entity grounding (fairness) ──────────────────────────────────────
        # The death-fairness doctrine in the prompt requires that any lethal
        # threat already be visible to the player, so surface the seen entities
        # for the LLM to honor that contract. There used to be an INJURY STATE
        # line here too, fed from a tracked wound list; that went with the wound
        # parser. Continuity of harm now comes from PREVIOUS BEAT below, which
        # carries the actual prose of what just happened to the player.
        seen_list = state.get('seen_elements', []) or []
        if isinstance(seen_list, list):
            seen_str = ', '.join(str(e) for e in seen_list[-10:])
        else:
            seen_str = str(seen_list)
        phase_str = state.get('current_phase', 'normal')
        # Phase directives make the STORY PHASE actually STEER the beat — pressure
        # rises turn over turn instead of the world staying flat at "normal".
        phase_directive = {
            "normal": "COLD OPEN. Get a character or a direct threat on screen — or "
                      "close enough to hear/see — within THIS beat or the next one. "
                      "Atmosphere alone is not enough: give the player someone or "
                      "something to be afraid of, then end on a cue that tightens the noose.",
            "escalating": "STAKES ARE RISING. Press the player: a threat moves closer, a "
                          "complication compounds, or the facility reacts to what they've "
                          "stirred up. Do NOT let this beat idle — something must develop.",
            "critical": "THIS IS THE CLIMAX. Danger is immediate and lethal-capable. Force a "
                        "hard, consequential beat — a threat commits, an event triggers, the "
                        "situation lurches. No stalling, no safe nothing-happens beats.",
        }.get(phase_str, "")

        # SCAN object actions must MOVE THE STORY, not dead-end on a shrug.
        #
        # A curated or typed choice earns the exact same hard cut a SCAN MOVE
        # does whenever it reads as an egress pick (the anti-loop backstop's
        # own escape hatch) or the ordinary hard-transition text classifier
        # would cut to it — is_hard_transition only ever inspects `choice`
        # itself (never the not-yet-written dispatch), so this is knowable
        # before the LLM call below, not a guess. Without also_relocating here,
        # that turn got NO traversal guidance at all: nothing telling the
        # model this is locomotion, not confrontation, and nothing telling it
        # to hold the camera's existing relationship to the player. A run can
        # hold a steady over-the-shoulder framing across six straight SCAN
        # MOVE turns and then flip to face the character on the very next
        # egress choice — same hard cut, same camera rig, missing directive.
        non_scan_relocation = not is_interaction and (
            is_egress_choice(choice) or is_hard_transition(choice, "")
        )
        interaction_directive = _action_directive(
            is_interaction, is_move, subject, also_relocating=non_scan_relocation,
        )

        # What SCAN named in the frame the player is looking at. This is the only
        # pixel-accurate entity list in the prompt: `seen_elements` is written by
        # the world-evolution rewrite, which runs async and therefore lags a turn.
        onscreen = scene_objects_for_turn(state)

        # goal_directive: where the run is going. The montage promised the
        # player a destination; without it the consequence model never heard
        # of one and wrote every beat as a place, not a direction.
        grounding_block = (
            f"\n\nDISCOVERED ENTITIES (these are the only things on the board — "
            f"any LETHAL threat must come from here or the current scene): "
            f"{seen_str or 'none yet'}\n"
            f"{condition_directive(state)}"
            f"STORY PHASE: {phase_str} — {phase_directive}\n"
            f"{goal_directive(state)}"
            f"{_look_note_directive(state)}"
            f"{onscreen_directive(onscreen)}"
            f"{interaction_directive}"
            f"{_conversation_directive(state)}"
            f"{stagnation_directive(environment_streak)}"
            f"{_look_book_story(state)}"
        )

        # Use JUST the action_consequence_instructions (which has JSON format).
        # The director's sheet goes on top so the model knows who it's writing
        # and what the camera can actually see before it reads a single rule —
        # `visual_scene` in particular is the text that becomes the image, so it
        # has to be composed for the active perspective.
        json_prompt = game_identity.apply(
            PROMPTS['action_consequence_instructions'], "narrative"
        ) + (
            f"\n\n{game_identity.visual_scene_guidance()}\n"
            # The free-will header is written outside the template, so it needs
            # its own pass — it says "describe them DOING the action from
            # first-person perspective", which is an instruction to write the
            # wrong shot when the camera is behind the character.
            f"\n\n{game_identity.apply(free_will_header, 'raw')}"
            # Finished history goes ABOVE the choice, never below it. Read last,
            # it was what the model continued instead of acting on the choice.
            f"{prev_context}"
            f"\nPLAYER CHOICE: '{choice}'\n"
            f"THE ACTION COMPLETED. The attached image is WHERE THEY WERE when "
            f"they chose. visual_scene is the camera AFTER this action — do not "
            f"recaption the attached still.\n"
            f"Write THIS action's outcome. If your first sentence could have "
            f"been written before the player picked it, you have written the "
            f"wrong beat.\n"
            # Several rusted things are usually in frame at once, and the model
            # would act on a neighbour: "Sprint toward rusted truck" came back
            # as scrambling behind the rusted TANK, and "Move to the chain link
            # fence" as wrenching open the pickup's door. Naming the object is
            # the whole content of a MOVE TO / SCAN action, so it has to bind.
            f"If the PLAYER CHOICE names a specific object, THAT object is the "
            f"one the beat acts on — not a similar one elsewhere in frame. Do "
            f"not substitute a neighbouring prop because it is nearer or more "
            f"interesting.\n"
            # Interpolated raw, this is the one surface the director's sheet
            # never reached: the world document still carried the shipped
            # protagonist's name, so the model was told who the player is by
            # the sheet and contradicted six times by the context below it.
            f"WORLD CONTEXT: {game_identity.recast(world_prompt)}\n"
            f"{grounding_block}"
            f"{fate_modifier}"
            f"{spatial_context}\n\n"
            "Return JSON with all five fields from the OUTPUT CONTRACT:\n"
            "  dispatch — the prose the player reads. 2-3 sentences. What the "
            "action cost, what it changed, what the place does back. Write the "
            "beat, not the camera position: never open with the protagonist's "
            "name followed by a posture verb.\n"
            "  visual_scene — the camera after the action completed. One or two "
            "sentences, only what is physically visible, no feelings, no sound. "
            "Do not recaption the attached still.\n"
            "  player_alive — true or false.\n"
            "  relocated — true if the beat you just wrote leaves them "
            "somewhere the camera could not see from where they started: "
            "another room, the far side of a door, further down a passage. "
            "False if they are still standing in the same place, however much "
            "changed around them. Answer for the beat you wrote, not for what "
            "the action asked for.\n"
            "  goal_reached — true ONLY if this beat plainly reaches WHAT THE "
            "PLAYER CAME HERE FOR. Seeing it, or opening a way toward it, is "
            "not reaching it; standing at it, through it, or holding it, is. "
            "False on every other turn.\n"
            "dispatch and visual_scene must not be the same sentence. "
            "No next_choices."
        )
        
        # Build parts list (text + optional image)
        parts = [{"text": json_prompt}]
        
        # Add previous timestep image if provided
        if current_image:
            # Use our centralized path resolution
            actual_path = _resolve_image_path(current_image)
            
            if not actual_path or not actual_path.exists():
                print(f"[GEMINI TEXT+IMG] WARNING: Could not resolve image path: {current_image}")
            else:
                # Use pre-downsampled version if available
                small_path = actual_path.parent / actual_path.name.replace(".png", "_small.png")
                use_path = small_path if small_path.exists() else actual_path
                with open(use_path, "rb") as f:
                    import base64
                    image_data = base64.b64encode(f.read()).decode('utf-8')
                
                parts.insert(0, {
                    "inlineData": {
                        "mimeType": "image/png",
                        "data": image_data
                    }
                })
                size_note = "(480x360, 4:3)" if small_path.exists() else "(full-res)"
                print(f"[GEMINI TEXT+IMG] Including PREVIOUS timestep image: {current_image} {size_note}")
        
        # Don't use lore - dispatch is immediate action/consequence (use _ask instead of direct API call)
        import json as json_lib
        result = _ask(
            json_prompt,
            model="gemini",
            temp=1.0,
            # Two prose fields now, not one caption. At 200 the second field
            # came back truncated mid-sentence.
            tokens=420,
            image_path=current_image,
            use_lore=False,
            response_schema=_CONSEQUENCE_RESPONSE_SCHEMA,
        )
        
        print("[COMBINED DISPATCH] Complete")
        
        # Strip markdown code fences if present
        if result.startswith("```"):
            lines_raw = result.split("\n")
            if lines_raw[0].startswith("```"):
                lines_raw = lines_raw[1:]
            if lines_raw and lines_raw[-1].strip() == "```":
                lines_raw = lines_raw[:-1]
            result = "\n".join(lines_raw)
        
        # Parse JSON response
        dispatch = ""
        visual_scene = ""
        player_alive = True
        # None means "the model did not say", which is different from False —
        # the caller falls back to the old wording guess rather than assuming
        # the player stayed put. See the hard_transition read in
        # advance_turn_image_fast.
        relocated = None
        provisional_choices: list = []
        
        try:
            import json as json_lib
            data = json_lib.loads(result)
            visual_scene = (data.get("visual_scene") or "").strip()
            player_alive = data.get("player_alive", True)
            if isinstance(data.get("relocated"), bool):
                relocated = data["relocated"]
            # Did this beat reach the run's goal? Left on the caller's state
            # object rather than widening the return tuple, which three tests
            # unpack by position. advance_turn_image_fast reads it back right
            # after it records `player_alive`, and only ever counts it once.
            if isinstance(state, dict):
                state["_turn_goal_reached"] = data.get("goal_reached") is True
            # The feed reads `dispatch`; the image model reads `visual_scene`.
            # Only fall back to the caption when the model actually withheld
            # the prose — assigning one to the other unconditionally is what
            # turned the story log into a shot list.
            dispatch = (data.get("dispatch") or "").strip() or visual_scene
            # Safe print with Unicode handling
            try:
                print(f"[DISPATCH] Parsed JSON: dispatch={dispatch[:50]}..., alive={player_alive}")
                if visual_scene:
                    print(f"[DISPATCH] visual_scene={visual_scene[:80]}...")
                else:
                    print(f"[DISPATCH] visual_scene: NOT generated (will fall back to dispatch)")
            except UnicodeEncodeError:
                print(f"[DISPATCH] Parsed JSON: alive={player_alive} (dispatch contains special characters)")
        except Exception as parse_error:
            try:
                print(f"[DISPATCH] JSON parse failed: {parse_error}")
                print(f"[DISPATCH] Raw result: {result[:200]}...")
            except UnicodeEncodeError:
                print(f"[DISPATCH] JSON parse failed (output contains special characters)")
            # Fallback: try to extract dispatch text
            dispatch = result.replace('"dispatch":', '').replace('"player_alive":', '').replace('"visual_scene":', '').replace('{', '').replace('}', '').strip()
            if ',' in dispatch:
                dispatch = dispatch.split(',')[0].strip(' "')
        
        # vision_dispatch = visual scene description for image generation
        # If the LLM generated a proper visual_scene, use it; otherwise fall back to dispatch
        if visual_scene:
            vision_dispatch = visual_scene
        elif game_identity.shows_character():
            who = game_identity.display_name()
            vision_dispatch = (
                f"{who} is in frame, full body, after the action, "
                "at the current location."
            )
        else:
            vision_dispatch = dispatch
        
        # 400 was sized for a one-line caption. The narrative is 2-3 sentences
        # of prose and was landing in the feed as "...(truncated)" mid-word;
        # the caption keeps the tighter bound because it steers the renderer.
        dispatch = _clip_sentence(dispatch, 700)
        vision_dispatch = _clip_sentence(vision_dispatch, 400)
        
        return dispatch, vision_dispatch, player_alive, provisional_choices, relocated
        
    except Exception as e:
        try:
            print(f"[COMBINED DISPATCH ERROR] {e}")
        except UnicodeEncodeError:
            print(f"[COMBINED DISPATCH ERROR] (error contains special characters)")
        import traceback
        traceback.print_exc()
        # Fallback to safe defaults. `relocated` is None, not False: a call
        # that failed has no opinion about where the player ended up.
        return ("You make a tense move in the chaos.",
                "The desert stretches ahead.", True, [], None)

# ───────── degraded turns, told in-world ─────────────────────────────────────
# When dispatch generation fails, `_ask` returns a sentinel string — "Signal
# interrupted due to timeout...", "Signal interrupted — Anthropic API key not
# configured." — and the turn loop's only guard was for an EMPTY dispatch, so
# those went straight into the feed as the story. The player got an error
# message in the voice of the narrator, which is the least recoverable way for
# an outage to present: it reads as the game being broken rather than the
# signal being bad.
_DISPATCH_FAILURE_MARKERS = (
    "signal interrupted",
    "api error",
    "transmission wavers",
    "system communications remain static",
    "the world holds its breath",
    "could not read image",
    "error:",
    "gemini_api_key",
    "openai_api_key",
    "not configured",
)

# Deliberately world-neutral: these run in whatever level the player authored,
# so they describe the CAMERA failing, never the setting. Anything about a
# desert or a facility would be a different bug in a hand-built world.
_DIEGETIC_DISPATCHES = (
    "The viewfinder floods with static, then snaps back. For a heartbeat you saw "
    "nothing at all — and whatever moved while the picture was gone has already stopped.",
    "The tape stutters. Audio drops to a low hum, the frame smears, then steadies. "
    "Something took that moment from you.",
    "A wave of interference rolls across the lens. When it clears the light has "
    "shifted, and the silence feels deliberate — like it waited for the picture to break.",
    "The battery indicator flickers red. The image ghosts, doubles, resolves. You are "
    "still moving, and you have lost track of how far.",
    "Static swallows the shot. You keep rolling on instinct; when the picture returns "
    "the shadows have rearranged themselves.",
)


def _clip_sentence(text: Optional[str], limit: int) -> str:
    """Bound a beat without leaving a half-word in the feed."""
    t = (text or "").strip()
    if len(t) <= limit:
        return t
    cut = t[:limit]
    end = max(cut.rfind(". "), cut.rfind("! "), cut.rfind("? "))
    if end > limit * 0.5:
        return cut[:end + 1]
    if " " in cut:
        cut = cut[:cut.rfind(" ")]
    return cut.rstrip(" ,;:-") + "..."


def _is_failure_dispatch(text: Optional[str]) -> bool:
    """True when a dispatch is an error sentinel rather than story."""
    t = (text or "").strip().lower()
    if not t:
        return True
    return any(marker in t for marker in _DISPATCH_FAILURE_MARKERS)


def _diegetic_dispatch(choice: str = "") -> str:
    """An in-world line to show instead of an error sentinel.

    Varied by the action and a coarse clock so two failures in a row don't
    print the same sentence, but stable within a turn.
    """
    seed = f"{choice}|{int(time.time() // 7)}"
    return _DIEGETIC_DISPATCHES[abs(hash(seed)) % len(_DIEGETIC_DISPATCHES)]


# ───────── how a run ends ────────────────────────────────────────────────────
# There used to be a wound parser and a hit-point pool here: prose was scraped
# for injury words, each wound priced from a severity table, and a run ended
# when the total reached zero.
#
# It was cut because the mechanic was being extracted from free text, and every
# playtest found a new way for that to be wrong. "Punctures the silence" was
# filed as a puncture wound the player then carried for the rest of the run.
# Excerpts clipped the injury off the end, so five of eleven wounds in one run
# were stored as pure scene-setting and the prompts described the player as
# hurt by a noise. And in the last run before removal, ONE thigh wound was
# billed three times — -35, -14, -35 — because each turn's prose opened the
# sentence differently, which is 84 of 100 points and most of what killed that
# run. The prompts are deliberately fed the injury list so the writing keeps
# referring back to it, which means restatement is the normal case; a text
# scraper cannot reliably tell "you are hurt again" from "you are still hurt".
#
# So death is the model's call now, from `player_alive` in the consequence JSON
# — the same structured field it already returned. What keeps that from being
# arbitrary is the fairness doctrine in the consequence prompt (inert scenery
# wounds, characters and events kill) plus the detection ladder below, which is
# event-driven rather than scraped: being hunted is what kills you, not bleeding.


# ───────── detection: something out there knowing where you are ──────────────
# The prose would say a guard spots you and gives chase, and nothing in the
# engine knew it on the next turn. `in_combat` was initialised False and written
# by nothing at all; there was no alert level, no pursuer, no memory of having
# been seen. Every turn began from hidden regardless of how the last one ended,
# so being hunted was a sentence rather than a situation.
#
# This is the smallest version of that which is genuinely simulated. Heat rises
# when a turn describes attention and bleeds away when it doesn't, the level is
# a reading of the heat, and the level is fed back into the prompt, the odds and
# the HUD — so the next turn is obliged to honour what the last one said.
#
# The level constants sit with the other game constants near the top; they are
# needed during import.
DETECT_THRESHOLDS = (0, 2, 4, 7)   # heat at which each level begins
DETECT_HEAT_MAX = 10
DETECT_COOL = 1                    # bled off by a turn that draws no attention
DETECT_COOL_MOVING = 2             # ... and more when you put ground behind you

# What breaking away is worth. This one is load-bearing: the condition directive
# tells the narrator that a hunted player must not get a calm beat, so once the
# level is up the prose describes a chase every single turn, that prose re-fires
# the signal, and heat sits at the ceiling for the rest of the run. A 20-turn
# render climbed 0 -> 10 by turn six and never came back down.
#
# So fleeing has to beat the prose rather than argue with it. Taking an egress
# option ignores this turn's signal and sheds heat outright — three or four
# turns of committed running gets you clear, and they cost you every other
# thing you might have done. Being seen should be recoverable; being seen once
# should not decide the rest of the run.
DETECT_COOL_FLEEING = 4

# What the prose has to say for the world to notice. Weighted worst-first: being
# chased is worse than being seen, and being seen is worse than being watched.
#
# Every phrase either names the player or is unambiguous alarm hardware. That is
# not fussiness — the first draft of this table had bare "stirs", "notices" and
# "pauses" in it, and "Nothing stirs." raised the alert level. Ambient scene
# prose is most of what a narrator writes, so anything that can fire on it will
# fire constantly, and the dial becomes noise wearing a number.
_DETECT_SIGNALS: tuple[tuple[int, tuple[str, ...]], ...] = (
    (4, ("gives chase", "gives pursuit", "charges at you", "charges toward you",
         "lunges at you", "lunges for you", "runs at you", "sprints toward you",
         "closing on you", "closing in on you", "chasing you", "hunting you",
         "pursuing you", "comes after you", "bearing down on you",
         "grabs you", "seizes you", "drags you")),
    (3, ("spots you", "sees you", "sights you", "notices you", "spotted you",
         "locks onto you", "fixes on you", "points at you", "aims at you",
         "fires at you", "shoots at you", "opens fire", "screams an alarm",
         "alarm blares", "alarm sounds", "alarm shrieks", "siren", "klaxon",
         "raises its weapon", "raises his weapon", "raises her weapon",
         "shouts at you", "calls out to you")),
    (2, ("turns toward you", "turns to face you", "looks straight at you",
         "looks right at you", "catches sight of you", "sweeps over you",
         "light finds you", "beam settles on you", "head snaps toward you",
         "footsteps quicken behind you", "following you", "watching you",
         "staring at you", "tracks you")),
)


def detection_signal(text: str) -> int:
    """How much attention this turn's prose drew. 0 when it drew none."""
    low = (text or "").lower()
    for weight, phrases in _DETECT_SIGNALS:
        if any(p in low for p in phrases):
            return weight
    return 0


def detection_level(heat: int) -> int:
    """The level a given heat reads as."""
    level = DETECT_HIDDEN
    for idx, floor in enumerate(DETECT_THRESHOLDS):
        if heat >= floor:
            level = idx
    return level


def _as_int(value, fallback: int = 0) -> int:
    """Whatever was on disk, as an int. Saves get hand-edited and half-written."""
    try:
        return int(value)
    except (TypeError, ValueError):
        return fallback


def get_detection(state: dict) -> dict:
    """The detection record, defaulted for a state that predates the system.

    This rebuilds the record from a fixed set of fields rather than copying it,
    so anything parked on `state["detection"]` that is not listed here is
    dropped on the next apply_detection write. The frame reading is kept at
    `state["detection_witness"]` for exactly that reason — see record_witness.
    """
    det = state.get("detection")
    if not isinstance(det, dict):
        det = {}
    heat = max(0, min(DETECT_HEAT_MAX, _as_int(det.get("heat"))))
    source = str(det.get("source") or "").strip().lower()
    return {"heat": heat,
            "level": max(0, min(DETECT_HUNTED,
                                _as_int(det.get("level"), detection_level(heat)))),
            "since_turn": _as_int(det.get("since_turn")),
            # Which sensor last moved the dial: "frame" when the picture showed
            # somebody, "prose" when the narration said so, "noise" when it was
            # only the player's own meddling, "" when nothing did. The HUD
            # shows it so being seen is legible as a fact about the picture
            # rather than a number that drifts.
            "source": source if source in ("frame", "prose", "noise") else ""}


# ───────── the witness: what the PICTURE says, not what the prose says ───────
# _DETECT_SIGNALS above reads the narrator's word choice. That is the only
# sensor a text turn has, but it is also a closed loop — the model decides
# whether the model got seen — and it is why the dial read as invented. Phrase
# it as "the guard's attention settles on your position" instead of "spots you"
# and nothing moves; write a calm sentence while a figure stands in frame and
# the heat quietly bleeds off.
#
# Two vision passes already look at the frame the player is actually looking
# at, and both were throwing this answer away:
#
#   • /api/detect (the SCAN tap) returns `kind` and a normalized box per
#     object. Counting the animate ones and measuring the nearest box is pure
#     arithmetic on a payload we already paid for.
#   • _vision_analyze_all (the observe reground) needed one extra line in a
#     prompt it was already sending — see WATCHERS in that function.
#
# Neither adds an API call or a millisecond to the turn's critical path. A
# reading is stamped onto state as a "witness" and consumed by the next
# apply_detection, on the SAME 0..4 scale _DETECT_SIGNALS uses, so it lands in
# the existing arithmetic rather than beside it.

# Which detector kinds can look back at you. `machine` is excluded on purpose:
# a camera on a pole is a watcher, but the detector labels far more things
# `machine` than are pointed anywhere, and a sensor that fires on every pump
# and generator in frame is the ambient-prose failure again in a new coat.
WITNESS_ANIMATE_KINDS = frozenset({"person", "character", "creature", "animal"})

# Normalized box height for the nearest animate thing. Above NEAR it is
# standing over you; below MID it is a silhouette across the yard.
WITNESS_NEAR_H = 0.55
WITNESS_MID_H = 0.22

# How much a frame RAISES heat, keyed (facing, distance). `unknown` is the
# SCAN detector, which reports geometry but not orientation — deliberately
# graded between `facing` and `away` rather than guessing either way.
#
# Everything with its back turned scores zero, at every distance. The dial
# measures what the WORLD KNOWS, and a thing that has not looked at you knows
# nothing however close it is standing. Being close to it is still a fact about
# your position, and that is what `witness_holds` is for: exposure without
# perception stops you getting less noticed, rather than making you more so.
# Splitting it this way is what lets a player walk a yard full of oblivious
# bodies and stay hidden until one of them turns round — which is the entire
# reason to have a hidden state at all.
_WITNESS_GAIN = {
    ("facing", "near"): 3,   # as bad as "spots you": it is close and looking
    ("facing", "mid"): 2,    # as bad as "turns toward you"
    ("facing", "far"): 1,
    ("unknown", "near"): 2,
    ("unknown", "mid"): 1,
    ("unknown", "far"): 0,
    ("away", "near"): 0,
    ("away", "mid"): 0,
    ("away", "far"): 0,
}

# A frame nothing is facing cannot push past this on its own, which is one
# short of `alerted`. Alerted means the world HAS SEEN the player; a picture in
# which nothing has looked at them is not evidence of that, however crowded or
# close it is. Getting past suspicious needs either something that actually
# looked, or prose reporting what a single frame cannot show — footsteps
# closing from behind, a radio call, a door opening off-camera.
#
# Without this, a scene that simply contains people ratchets: a live run walked
# a yard of backs-turned creatures from hidden to hunted in four turns, each
# turn adding a little and nothing ever having looked up.
WITNESS_UNSEEN_CEILING = DETECT_THRESHOLDS[DETECT_ALERTED] - 1

_WITNESS_FACING = ("facing", "away", "unknown", "none")
_WITNESS_DISTANCE = ("near", "mid", "far")


def _witness(watchers: int, facing: str, distance: str, source: str,
             turn: int = 0, label: str = "") -> dict:
    """One normalized reading of the frame. Never raises on junk input.

    `label` names the nearest animate thing when the reading came from the SCAN
    detector, which is the only pass that returns nouns. It is what lets an
    encounter at high heat be the thing the player actually saw rather than a
    fresh roster draw — see onscreen_threat_target in encounter.py.
    """
    watchers = max(0, _as_int(watchers))
    facing = str(facing or "").strip().lower()
    distance = str(distance or "").strip().lower()
    if facing not in _WITNESS_FACING:
        facing = "unknown"
    if distance not in _WITNESS_DISTANCE:
        distance = "far"
    if watchers <= 0:
        facing, distance, label = "none", "far", ""
    return {"watchers": watchers, "facing": facing, "distance": distance,
            "source": str(source or "frame"), "at_turn": _as_int(turn),
            "label": str(label or "").strip()[:60]}


def witness_signal(witness: Optional[dict]) -> int:
    """How much attention the FRAME drew, on the _DETECT_SIGNALS scale."""
    if not isinstance(witness, dict):
        return 0
    watchers = max(0, _as_int(witness.get("watchers")))
    if watchers <= 0:
        return 0
    facing = str(witness.get("facing") or "unknown").strip().lower()
    distance = str(witness.get("distance") or "far").strip().lower()
    gain = _WITNESS_GAIN.get((facing, distance), 0)
    # A crowd looking at you is worse than one person looking at you, but a
    # crowd with its back turned is still just scenery.
    if gain and watchers >= 3:
        gain += 1
    return max(0, min(4, gain))


def witness_holds(witness: Optional[dict]) -> bool:
    """Does this frame forbid cooling even though it raises nothing?

    The other half of the fix. Heat bleeding off under a calm sentence is
    correct in an empty room and a lie when there is somebody standing in the
    doorway, and the prose sensor could not tell those apart.

    `near` only, deliberately. This started as near-or-mid, which in a live run
    meant a yard with anything at all in the middle distance could never cool —
    and since these scenes almost always have something in the middle distance,
    that is a dial with no way down rather than a dial that answers the room.
    Within reach is the claim worth making; a shape across the yard is scenery
    and is allowed to bleed off.

    This is the whole answer for a body that is close and facing away, which
    scores no gain at all (see _WITNESS_GAIN): standing next to something that
    has not noticed you does not make the world know more about you, but it is
    very obviously not how you become less noticed either.
    """
    if not isinstance(witness, dict):
        return False
    if max(0, _as_int(witness.get("watchers"))) <= 0:
        return False
    return str(witness.get("distance") or "far").strip().lower() == "near"


def witness_from_detections(objects: Optional[list], turn: int = 0) -> Optional[dict]:
    """A reading off a SCAN pass. Geometry only — the detector has no opinion
    about which way anything is facing, so this is always `unknown`.

    Returns None when the payload is unusable, which is NOT the same as a clean
    frame: a detector that failed must leave the dial alone, not assert that
    nobody is there. See record_witness.
    """
    if not isinstance(objects, (list, tuple)):
        return None
    animate = []
    for obj in objects:
        if not isinstance(obj, dict):
            continue
        if str(obj.get("kind") or "").strip().lower() in WITNESS_ANIMATE_KINDS:
            animate.append(obj)
    if not animate:
        return _witness(0, "none", "far", "scan", turn)

    def _height(obj: dict) -> float:
        try:
            return max(0.0, min(1.0, float(obj.get("h") or 0)))
        except (TypeError, ValueError):
            return 0.0

    nearest = max(animate, key=_height)
    tallest = _height(nearest)
    if tallest >= WITNESS_NEAR_H:
        distance = "near"
    elif tallest >= WITNESS_MID_H:
        distance = "mid"
    else:
        distance = "far"
    return _witness(len(animate), "unknown", distance, "scan", turn,
                    label=str(nearest.get("label") or ""))


# "2 | facing | near" — see the WATCHERS block in _vision_analyze_all's prompt.
_WATCHERS_COUNT_RE = re.compile(r"-?\d+")
# The format asks for a digit and usually gets one, but "none" for an empty
# frame is the obvious thing to write instead and it is a real answer, not a
# failed read. Without this it parsed as "no reading" and an empty room could
# never cool the dial.
_WATCHERS_ZERO_RE = re.compile(r"\b(none|nobody|no one|no-one|nothing|zero)\b")


def witness_from_vision(vision: Any, turn: int = 0) -> Optional[dict]:
    """A reading off the observe reground's scene analysis.

    Accepts the whole result dict or just its `watchers` string. Returns None
    when the field is absent — which is the normal case for a cached analysis
    written before the field existed, and for any vision call that failed.
    """
    if isinstance(vision, dict):
        raw = vision.get("watchers")
    else:
        raw = vision
    raw = str(raw or "").strip()
    if not raw:
        return None
    parts = [p.strip().lower() for p in raw.split("|")]
    head = parts[0] if parts else ""
    count_match = _WATCHERS_COUNT_RE.search(head)
    if count_match:
        watchers = max(0, int(count_match.group(0)))
    elif _WATCHERS_ZERO_RE.search(head):
        watchers = 0
    else:
        return None
    facing = parts[1] if len(parts) > 1 else "unknown"
    distance = parts[2] if len(parts) > 2 else "far"
    return _witness(watchers, facing, distance, "vision", turn)


def merge_witness(prior: dict, incoming: dict) -> dict:
    """Combine two readings of the SAME frame, field by field.

    The two passes are not rivals to be ranked — they are differently blind,
    and picking the higher score let the blinder one win. Measured in a live
    run: the scene analysis reported "3 | away | mid" (three things, backs
    turned) and the SCAN detector reported three animate boxes at `unknown`
    orientation, because boxes have no orientation. `unknown + near` scores 2,
    `away + mid` scores 0, so the higher score won and the engine concluded the
    player was being watched at close range by something it had just been told
    was facing the other way. Four turns from hidden to hunted, in a yard where
    nothing had looked up.

    So each field is taken from whichever pass can actually answer it:

    • watchers — the larger count. Both looked at the same picture, so the more
      thorough read is the better one.
    • facing   — a KNOWN orientation always beats `unknown`, and between two
      known ones `facing` beats `away`. Only the scene analysis reports this at
      all, which makes it the whole ballgame: it is the difference between
      somebody looking at you and somebody with their back to you, and it is
      most of the gain table. Two passes disagreeing usually means they locked
      onto different bodies, and one of them having looked up is the fact that
      matters.
    • distance — the nearer of the two. The detector's box height is literal
      where the analysis is judging, and being wrong toward caution here costs
      a point of heat rather than a missed threat.
    • label    — whoever has one. Only the detector returns nouns.

    Fields are only taken from a reading that actually saw somebody: a pass
    that found an empty frame reports `none | far`, which must not be mistaken
    for an observation about the figures the other pass did find.
    """
    watchers = max(_as_int(prior.get("watchers")), _as_int(incoming.get("watchers")))
    if watchers <= 0:
        return _witness(0, "none", "far",
                        incoming.get("source") or prior.get("source") or "frame")

    seeing = [w for w in (prior, incoming) if _as_int(w.get("watchers")) > 0]
    known = {str(w.get("facing") or "").strip().lower() for w in seeing}
    facing = "facing" if "facing" in known else (
        "away" if "away" in known else "unknown")
    distance = "far"
    for rung in ("near", "mid", "far"):
        if any(str(w.get("distance") or "far").strip().lower() == rung
               for w in seeing):
            distance = rung
            break
    label = ""
    for w in seeing:
        if str(w.get("label") or "").strip():
            label = str(w["label"]).strip()
            break
    sources = [str(w.get("source") or "") for w in (prior, incoming)]
    source = "+".join(sorted({s for s in sources if s})) or "frame"
    return _witness(watchers, facing, distance, source, label=label)


def record_witness(state: dict, witness: Optional[dict],
                   for_turn: Optional[int] = None) -> Optional[dict]:
    """Stamp a frame reading onto state for the next apply_detection.

    Kept OUT of the `detection` record on purpose: get_detection rebuilds that
    dict from a fixed set of fields every turn, so anything else parked in
    there is silently dropped on the next write.

    `for_turn` defaults to the current turn, which is right for every pass that
    reads a frame the player is looking at NOW (the SCAN tap, the observe
    reground). The still path is the exception: it reads the frame it has just
    finished rendering, which the player will not act on until the turn after,
    so it stamps one ahead. See the call site in advance_turn_choices_deferred.

    Several passes can land inside one turn — the observe reground at the
    decision point, then a SCAN tap before the player commits — and they are
    MERGED rather than ranked, because each can answer something the other
    cannot. See merge_witness. Overwriting with the latest instead would let a
    player who scanned an empty patch of floor erase the figure the reground
    saw ten seconds earlier, which is precisely the kind of "the game forgot"
    this system exists to stop.
    """
    if not isinstance(state, dict) or not isinstance(witness, dict):
        return None
    turn = (int(state.get("turn_count", 0) or 0) if for_turn is None
            else _as_int(for_turn))
    witness = dict(witness)
    prior = state.get("detection_witness")
    if isinstance(prior, dict) and _as_int(prior.get("at_turn"), -1) == turn:
        witness = merge_witness(prior, witness)
    witness["at_turn"] = turn
    state["detection_witness"] = witness
    print(f"[DETECT] witness ({witness['source']}): {witness['watchers']} "
          f"{witness['facing']} {witness['distance']} "
          f"-> signal {witness_signal(witness)}", flush=True)
    return witness


def current_witness(state: dict) -> Optional[dict]:
    """This turn's frame reading, or None if there isn't a fresh one.

    A witness describes ONE frame. Once the turn it was taken on has resolved,
    that frame is gone and the reading is an opinion about somewhere the player
    no longer is — the same staleness rule scene_objects_for_turn enforces on
    the SCAN label cache, and for the same reason.
    """
    if not isinstance(state, dict):
        return None
    witness = state.get("detection_witness")
    if not isinstance(witness, dict):
        return None
    try:
        if _as_int(witness.get("at_turn"), -1) != int(state.get("turn_count", 0) or 0):
            return None
    except (TypeError, ValueError):
        return None
    return witness


def apply_detection(state: dict, dispatch: str, *, interaction: bool = False,
                    is_move: bool = False, fate: str = "NORMAL",
                    fleeing: bool = False) -> tuple[dict, bool]:
    """Re-read how much the world knows about the player from this turn.

    Returns (detection, rose) where `rose` says the level went up, which is a
    tension event the same way a new injury is.

    Two sensors, and the louder one wins: the narrator's prose (_DETECT_SIGNALS)
    and the frame the player is looking at (see "the witness" above). Prose is
    kept rather than replaced because it is all a still or text-only turn has,
    and because it can report things a single frame cannot — footsteps closing
    behind you are not in the picture. The frame is what stops the dial being
    decided by word choice.
    """
    det = get_detection(state)
    was_heat, was_level = det["heat"], det["level"]

    witness = current_witness(state)
    heard = detection_signal(dispatch)
    seen = witness_signal(witness)
    gain = max(heard, seen)

    # Meddling is loud — but only if something is there to hear it.
    #
    # This was an unconditional +1, and because any gain at all skips the
    # cooling branch below, a turn that interacted could never cool. SCAN's
    # MOVE TO and INTERACT both count as interaction, so a player exploring
    # with the SCAN verbs gained heat every single turn and shed it never.
    # Measured in a live run: ten turns alone in an empty utility corridor,
    # prose signal 0 and frame signal 0 on every one of them, nobody in any
    # frame — and the game reported HUNTED. That is the invented-stakes bug
    # this whole system exists to remove, wearing the one costume nobody had
    # thought to check.
    #
    # `unheard` requires a POSITIVE reading of an empty frame. A missing
    # witness (offline, or a vision call that failed) is not evidence the room
    # is empty, so it keeps the old behaviour.
    unheard = bool(interaction) and heard <= 0 and (
        witness is not None and _as_int(witness.get("watchers")) <= 0)
    if interaction and not unheard:
        gain += 1
    if fate == "UNLUCKY" and gain:
        gain += 1                      # bad luck arrives as attention

    if fleeing:
        # Running wins over whatever the prose says, because while hunted the
        # prose is under instruction to describe a chase and would otherwise
        # hold the dial at maximum forever. See DETECT_COOL_FLEEING.
        heat = max(0, was_heat - DETECT_COOL_FLEEING)
    elif gain:
        heat = min(DETECT_HEAT_MAX, was_heat + gain)
        if (heard <= 0 and witness is not None
                and str(witness.get("facing") or "") != "facing"):
            # The prose said nothing, and the picture says nothing has looked
            # at the player. Cap one rung below `alerted`, whatever produced
            # the gain — the frame, the meddling bonus, or bad luck on top of
            # them. Keying this on the frame term alone left the hole the
            # meddling bonus walked straight through: one creature with its
            # back turned, a valve to open every turn, and the run climbed to
            # hunted anyway.
            #
            # Never below where the dial already was, so this clamps a climb
            # without undoing an earlier turn that genuinely got them seen.
            heat = min(heat, max(was_heat, WITNESS_UNSEEN_CEILING))
    elif witness_holds(witness) or unheard:
        # Nothing raised it, but the player is not getting quieter either:
        # either there is a body within reach, or they just made noise in a
        # room that happens to be empty. Neither is how you become un-seen.
        heat = was_heat
    else:
        heat = max(0, was_heat - (DETECT_COOL_MOVING if is_move else DETECT_COOL))

    # Which sensor actually moved the dial, for the HUD and for tuning. A
    # player who can see that the number answers the picture will believe it;
    # one watching it move for reasons they cannot observe will not — which is
    # why "prose" is never claimed for a turn the prose said nothing about.
    if gain and seen > 0 and seen >= heard:
        det["source"] = "frame"
    elif gain and heard > 0:
        det["source"] = "prose"
    elif gain:
        det["source"] = "noise"        # the meddling bonus, with both sensors quiet
    elif heat == was_heat and witness_holds(witness):
        det["source"] = "frame"
    elif heat == was_heat and unheard:
        det["source"] = "noise"
    else:
        det["source"] = ""

    level = detection_level(heat)
    det["heat"], det["level"] = heat, level
    why = f" [{det['source']}]" if det.get("source") else ""
    if level != was_level:
        det["since_turn"] = int(state.get("turn_count", 0) or 0)
        print(f"[DETECT] {DETECT_NAMES[was_level]} -> {DETECT_NAMES[level]} "
              f"(heat {was_heat}->{heat}){why}", flush=True)
    elif heat != was_heat:
        print(f"[DETECT] {DETECT_NAMES[level]}, heat {was_heat}->{heat}{why}",
              flush=True)

    state["detection"] = det
    # in_combat was dead state that /api/status reported every turn. Alerted or
    # worse is what it was always supposed to mean.
    state["in_combat"] = level >= DETECT_ALERTED
    return det, level > was_level


def condition_directive(state: dict) -> str:
    """How much the world knows about the player, as prompt text.

    Detection is simulated, so the narrator has to be handed what it currently
    says. Without this the prose invents its own answer every turn and the HUD
    ends up contradicting the story in front of the player — which is the whole
    reason this stuff read as hallucinated.

    This used to lead with a PLAYER CONDITION line priced off a hit-point pool.
    That pool is gone (see "how a run ends"), and with it the risk that the two
    halves disagreed: the number could say "dying" while the prose had the
    player sprinting, because only one of them was load-bearing.
    """
    level = get_detection(state)["level"]

    seen = (
        "Nothing out there knows where the player is. Stealth is intact; "
        "keep the danger latent.",
        "Something SUSPECTS. A search is beginning — not a hunt yet. Write "
        "the world starting to look for them.",
        "The player HAS BEEN SEEN and whatever saw them is acting on it. Do "
        "not quietly forget this; it cannot be walked back to calm in one beat.",
        "The player is BEING HUNTED right now, this turn. The pursuer is close "
        "and closing. A calm or idle beat here is wrong. One of next_choices "
        "MUST be a way to break away and run — fleeing is the only thing that "
        "shakes a pursuer, so a slate without it is a dead end. This pursuer "
        "is ALLOWED TO KILL: if the player stands and takes it while hunted, "
        "`player_alive` may be false, and that death is earned because they "
        "were told it was coming and given a way out.",
    )[level]

    return f"DETECTION: {DETECT_NAMES[level].upper()} — {seen}\n"


def _record_recent_event(state: dict, choice: str, visual_scene: str) -> None:
    """Append this turn's camera beat to the session tape (cap 10)."""
    beat = (visual_scene or "").strip() or (choice or "").strip()
    line = f"{(choice or '').strip()} -> {beat}"[:200]
    events = list(state.get("recent_events") or [])
    events.append(line)
    state["recent_events"] = events[-10:]


def recent_actions_taken(state: Optional[dict], limit: int = 5) -> list:
    """The last few actions the player actually committed, newest last.

    `recent_events` stores "<choice> -> <visual_scene>" lines; the slate only
    needs the left half. This is the memory the choice generator never had —
    `recent_choices` was hardcoded to '' at every call site, so nothing in the
    choice path could tell that the option it was about to offer had just been
    played. See drop_recently_done in choices.py.
    """
    out = []
    for line in list((state or {}).get("recent_events") or [])[-limit:]:
        action = str(line).split(" -> ", 1)[0].strip()
        if action:
            out.append(action)
    return out


def _previous_beat_block(state: Optional[dict], history: Optional[list] = None) -> str:
    """Already-played beats, as background for the next call.

    This used to be headed "PREVIOUS BEAT" with no statement of what it was
    for, and it was interpolated LAST — immediately before the output
    contract. The model read three finished beats and then wrote the next
    dispatch, so it frequently just continued them: a live run answered "Kick
    through the fence mesh" with "Your kick buckles the hood", which was the
    PREVIOUS turn's action, and answered "Scramble over the rusted truck" by
    narrating the landing from the fence vault before it. The block is
    context, not a cue to continue, and it now says so.
    """
    events = list((state or {}).get("recent_events") or [])[-3:]
    if history:
        last = history[-1] if history else {}
        extra = (last.get("vision_dispatch") or last.get("dispatch") or "").strip()
        if extra and extra not in " ".join(events):
            events.append(extra)
    if not events:
        return ""
    lines = "\n".join(f"- {e}" for e in events if e)
    return (
        "\n\nALREADY PLAYED (oldest first) — this is finished history, for "
        "continuity only. These beats are OVER. Do not re-narrate them, do not "
        "continue them, and never open your dispatch by describing one of "
        "them. The player has moved past all of this and is now doing the "
        f"PLAYER CHOICE below:\n{lines}\n"
    )


def summarize_world_state_diff(prev_state: dict, state: dict) -> str:
    """
    Return a concise summary of the most important differences between two world states.
    """
    diffs = []
    # Major world prompt change
    if prev_state.get('world_prompt', '') != state.get('world_prompt', ''):
        motifs = ["red biome", "creature", "alliance", "alert", "injury", "resource", "threat", "opportunity", "military", "activist", "danger", "quarantine", "mutation", "disaster", "conflict", "chaos", "discovery", "revelation", "attack", "wound", "escape", "surveillance", "protest", "panic", "contamination", "artifact", "ancient", "storm", "explosion", "hostile", "warning", "rumor", "evidence", "mutation", "leader", "broadcast", "rescue", "raid", "sabotage", "betrayal", "alliance broken", "alliance formed"]
        new_prompt = state.get('world_prompt', '').lower()
        if any(m in new_prompt for m in motifs):
            diffs.append(f"World event: {state.get('world_prompt', '')}")
    # Chaos level
    if prev_state.get('chaos_level', 0) != state.get('chaos_level', 0):
        diffs.append(f"Chaos level: {prev_state.get('chaos_level', 0)} -> {state.get('chaos_level', 0)}")
    # Phase
    if prev_state.get('current_phase', 'normal') != state.get('current_phase', 'normal'):
        diffs.append(f"Phase: {prev_state.get('current_phase', 'normal')} -> {state.get('current_phase', 'normal')}")
    # Player state
    if prev_state.get('player_state', {}) != state.get('player_state', {}):
        prev_alive = prev_state.get('player_state', {}).get('alive', True)
        curr_alive = state.get('player_state', {}).get('alive', True)
        if not curr_alive:
            diffs.append("Player is dead or gravely wounded.")
        elif not prev_alive and curr_alive:
            diffs.append("Player revived or recovered.")
        else:
            diffs.append(f"Player state changed")
    # New seen elements
    prev_seen = set(prev_state.get('seen_elements', []))
    curr_seen = set(state.get('seen_elements', []))
    new_seen = curr_seen - prev_seen
    if new_seen:
        motifs = ["red biome", "creature", "alliance", "alert", "injury", "resource", "threat"]
        motif_seen = [e for e in new_seen if any(m in e.lower() for m in motifs)]
        if motif_seen:
            diffs.append(f"New key elements: {', '.join(list(motif_seen)[:3])}")
    if not diffs:
        return "No major world state changes."
    return "; ".join(diffs)

# ───────── story escalation + fate (the "risk" backend) ────────────────────────
# The web/standalone turn loop (which SCAN interactions flow through) used to run
# EVERY turn at a flat NORMAL fate with current_phase pinned to "normal". chaos
# climbed but nothing consumed it, so tension never actually rose and poking an
# object felt inert. The front-end HUD, the escalation sting, the `threat_escalation`
# feed type, the phase-linked prompt directives, and the fate-intervention system
# were all already built — they were simply never driven on the web path. These
# helpers wake that machinery up so every action moves the story forward and
# ratchets risk, and so interacting with a scanned object pushes hardest.
# Threat POINTS (a choice is 1, a MOVE TO / INTERACT / TALK is 2), so 3 / 6
# tips into "escalating" by turn 2-3 and "critical" by turn 3-6. Was 4 / 9.
STORY_ESCALATE_AT = 3   # threat pressure at which the story tips into "escalating"
STORY_CRITICAL_AT = 6   # ... and into "critical"
# Platform default when an Experience does not name its own curve — the
# same sprint (was 8 / 20, which did not peak before turn ten).
_HARNESS_ESCALATE_AT = 3
_HARNESS_CRITICAL_AT = 6
_DEFAULT_BEAT_NORMAL = ("BEAT: put a character or a direct threat in view early — "
                        "a patrol, a figure, a voice — don't let the opening stay empty.")
_DEFAULT_BEAT_ESCALATING = "BEAT: pressure is rising. Push the situation forward."
_DEFAULT_BEAT_CRITICAL = "BEAT: the situation is critical. Offer a way through or a last stand."


def _threat_block() -> dict:
    """Authorable pacing on the active Experience. Empty dict if none."""
    try:
        import experience_store
        raw = (experience_store.get_experience() or {}).get("threat") or {}
        return raw if isinstance(raw, dict) else {}
    except Exception:
        return {}


def _threat_marks() -> tuple[int, int]:
    """SOMEWHERE keeps 3/6. An Experience may author a slower curve."""
    esc, crit = STORY_ESCALATE_AT, STORY_CRITICAL_AT
    raw = _threat_block()
    if raw.get("escalate_at") is not None:
        try:
            esc = int(raw["escalate_at"])
        except (TypeError, ValueError):
            pass
    if raw.get("critical_at") is not None:
        try:
            crit = int(raw["critical_at"])
        except (TypeError, ValueError):
            pass
    esc = max(1, esc)
    return esc, max(esc + 1, crit)


def beat_nudge_text(state: Optional[dict] = None) -> str:
    """Fills {beat_nudge} on the choice template.

    The three lines are Experience pacing — authored in Create — not a
    hardcoded engine slogan. Missing copy falls back to the shipped beats.

    "Calm" used to mean silence here: threat 0 sent the choice slate nothing
    at all, so turn one — the run's only chance at a cold open — read exactly
    like a quiet turn fifteen minutes in. A run that wants its danger to show
    up FAST needs the opening beat pulling in that direction too, not just the
    two escalation marks further down the clock.
    """
    st = state if isinstance(state, dict) else {}
    threat = int(st.get("threat_level") or 0)
    phase = str(st.get("current_phase") or _phase_for_threat(threat) or "")
    raw = _threat_block()
    if phase == "critical":
        text = str(raw.get("beat_critical") or "").strip()
        beat = text or _DEFAULT_BEAT_CRITICAL
    elif phase == "escalating":
        text = str(raw.get("beat_escalating") or "").strip()
        beat = text or _DEFAULT_BEAT_ESCALATING
    else:
        text = str(raw.get("beat_normal") or "").strip()
        beat = text or _DEFAULT_BEAT_NORMAL
    # The run's destination rides on the same slot, because this is the one
    # line every slate generator already reads (eight call sites, one
    # template placeholder). A slate that never offers a step toward the
    # goal is how a run with a destination still felt like wandering.
    goal = run_goal(st)
    if goal and st.get("goal_reached_turn"):
        beat += (f"\nGOAL REACHED: the player came here for {goal} and is there. "
                 f"Options are about what comes after — what they found, the "
                 f"way out — never about reaching it again.")
    elif goal:
        beat += (f"\nGOAL: the player came here for {goal} — one option should "
                 f"move toward it, or reveal something about it. Not all three.")
    return beat

# How much a single deliberate act of meddling can add to the story clock on top
# of the turn's own +1. Measured, not guessed: at the original +2, a SCAN-driven
# playtest where every turn was a MOVE TO hit "critical" on turn 3 and finished
# at threat 90, so 27 of its 30 turns had nowhere left to escalate and the whole
# time-of-day ladder was spent before turn 4. Meddling should still push the
# story harder than a button press — it just can't triple the clock.
MAX_RISK_THREAT_BOOST = 1

def _phase_for_threat(threat: int) -> str:
    """Map accumulated threat pressure onto the three story phases the rest of
    the engine (prompt directives, world-tick, time-of-day, HUD) already keys off."""
    esc, crit = _threat_marks()
    if threat >= crit:
        return "critical"
    if threat >= esc:
        return "escalating"
    return "normal"

# ───────── the clock ─────────────────────────────────────────────────────────
# `time_of_day` is written once at reset and read by every image generation.
# A later pass stepped it one lighting tier darker on each phase tip so the
# "act break" would show in the sky. That string is injected into every
# render as a lighting constraint, and hard cuts have no previous frame to
# hold the old light — so the movie relit (golden hour → purple twilight →
# night) instead of staying the evening it started as. The helper below
# still knows how to step a line if something asks; the turn loop does not.
#
# Ordered dark-ward. The first entry of each tier is the canonical name written
# back into the string; the rest are the ways a generated line might have said
# it. Tiers only ever advance, never wrap — a run must not brighten back to dawn.
_TIME_TIERS: tuple[tuple[str, ...], ...] = (
    ("dawn", "sunrise", "first light"),
    ("morning", "mid-morning"),
    ("midday", "noon", "high sun"),
    ("afternoon", "mid-afternoon"),
    ("golden hour", "late afternoon", "low sun"),
    ("dusk", "twilight", "sunset", "evening", "gloaming"),
    ("night", "nightfall", "after dark"),
    ("deep night", "dead of night", "midnight", "small hours"),
)

_TIME_STEP_MINUTES = 45
_CLOCK_RE = re.compile(r"\b(\d{1,2}):(\d{2})\s*([ap])\.?m\.?", re.I)


def _current_time_tier(time_of_day: str) -> tuple[int, str]:
    """The darkest tier named in ``time_of_day``, and the word that named it.

    Darkest-wins because the aliases nest: "deep night", "midnight" and
    "nightfall" all contain a word from an earlier tier, and taking the first
    match would read them as one tier brighter than they are. Returns (-1, "")
    when no tier is named at all.
    """
    low = (time_of_day or "").lower()
    best_idx, best_alias = -1, ""
    for idx, aliases in enumerate(_TIME_TIERS):
        for alias in aliases:
            if re.search(rf"\b{re.escape(alias)}\b", low):
                best_idx, best_alias = idx, alias
                break
    return best_idx, best_alias


# Where each tier starts on a 24h clock, darkest-first so a lookup takes the
# first hour it is at or past.
_TIER_START_HOUR = (
    (21, 6),  # night proper; "deep night" is reserved for after midnight
    (19, 5),  # dusk
    (17, 4),  # golden hour
    (14, 3),  # afternoon
    (11, 2),  # midday
    (7, 1),   # morning
    (5, 0),   # dawn
)


def _tier_from_clock(time_of_day: str) -> int:
    """Infer the lighting tier from the clock when the text doesn't name one.

    The default seed string is "6:30pm | weather: clear, warm light | …", which
    names no tier at all — so without this, the one run that starts from the
    default could only ever move its clock and would never darken.
    """
    m = _CLOCK_RE.search(time_of_day or "")
    if not m:
        return -1
    hour = (int(m.group(1)) % 12) + (12 if m.group(3).lower() == "p" else 0)
    if hour < 5:
        return 7  # deep night
    for start, idx in _TIER_START_HOUR:
        if hour >= start:
            return idx
    return -1


def _bump_clock(time_of_day: str, minutes: int) -> str:
    """Move the "7:42pm" part of the string forward, wrapping past midnight."""
    def _shift(m: "re.Match[str]") -> str:
        hour, minute, half = int(m.group(1)), int(m.group(2)), m.group(3).lower()
        total = (((hour % 12) + (12 if half == "p" else 0)) * 60 + minute + minutes) % (24 * 60)
        h24, mm = divmod(total, 60)
        return f"{h24 % 12 or 12}:{mm:02d}{'am' if h24 < 12 else 'pm'}"
    return _CLOCK_RE.sub(_shift, time_of_day, count=1)


def advance_time_of_day(time_of_day: str) -> str:
    """One lighting tier darker, with the clock moved to match.

    Only the lighting word is rewritten; the weather and mood clauses the run
    was seeded with are left alone, because they're the identity of this
    playthrough's evening and shouldn't be reinvented at an act break.
    """
    time_of_day = (time_of_day or "").strip()
    if not time_of_day:
        return time_of_day
    idx, alias = _current_time_tier(time_of_day)
    if idx < 0:
        # No lighting word to rewrite, so read the tier off the clock and NAME
        # the new one in the weather clause. The next step then finds it and
        # rewrites in place, so a run self-heals into the ladder after one tick.
        idx, alias = _tier_from_clock(time_of_day), ""
    if idx < 0 or idx >= len(_TIME_TIERS) - 1:
        # Unreadable, or already as dark as the ladder goes: the clock still
        # moves so time visibly passes, but the run never brightens.
        return _bump_clock(time_of_day, _TIME_STEP_MINUTES)
    darker = _TIME_TIERS[idx + 1][0]
    if alias:
        # Swallow a trailing "light"/"lighting" along with the tier word, so
        # "golden hour light" becomes "dusk" rather than "dusk light" and then
        # the frankly unusable "night light".
        shifted = re.sub(rf"\b{re.escape(alias)}(\s+light(?:ing)?)?\b", darker,
                         time_of_day, count=1, flags=re.I)
    else:
        shifted = _name_lighting(time_of_day, darker)
    return _bump_clock(shifted, _TIME_STEP_MINUTES)


# A seed describes its light in its own words ("dusty haze with fading violet
# light"), which name no tier this ladder knows. Appending the new tier next to
# that phrase is what produced render prompts reading "fading violet light, deep
# night" — two different times of day in one breath, handed straight to the
# image model. Take the seed's lighting phrase out before naming the new one.
_LIGHTING_PHRASE_RE = re.compile(
    r"[,;]?\s*\b(?:with|in|under)?\s*(?:[\w-]+\s+){0,3}light(?:ing)?\b", re.I)


def _name_lighting(time_of_day: str, tier: str) -> str:
    """Write ``tier`` into the weather clause of a "TIME | weather: … | mood: …" string."""
    parts = time_of_day.split("|")
    for i, part in enumerate(parts):
        stripped = part.strip()
        if stripped.lower().startswith("weather:"):
            body = _LIGHTING_PHRASE_RE.sub(
                "", stripped[len("weather:"):].strip(), count=1).strip(" ,;")
            parts[i] = f" weather: {body + ', ' if body else ''}{tier} "
            return "|".join(parts)
    return f"{time_of_day} | weather: {tier}"


# ───────── chaos as a tension dial ───────────────────────────────────────────
# chaos_level used to be `+= 1` every turn in generate_and_apply_choice, which
# made it a second turn counter rather than a reading of how bad things are: it
# rose on every turn regardless of content, never fell, and ran unbounded to 30
# over a long run. It is read by summarize_world_state (which branches on
# chaos > 7 and > 5), by the TALK persona's STATE line ("chaos level N/10" —
# already written against a 10-point scale) and by the HUD.
#
# It is NOT an accumulator. The first attempt at this was — spikes on events,
# −1 on a quiet turn — and a 30-turn live run pinned it at the ceiling from turn
# 6 to turn 30, falling on 2 turns out of 27. That isn't a tuning problem: once
# the story reaches its 'critical' phase, UNLUCKY fires on roughly half of all
# turns and the phase directive explicitly demands a hard consequential beat, so
# nearly every turn IS eventful and ANY accumulator saturates.
#
# So chaos is a decaying average of recent intensity instead. Each turn keeps
# half of the previous reading and adds this turn's spike, which means it tracks
# how bad the last few turns have been rather than how many turns there have
# been. A relentless stretch sits high, one quiet turn visibly cools it, and it
# only reaches the ceiling when everything fires at once.
CHAOS_MAX = 10
CHAOS_MEMORY = 0.5          # how much of last turn's heat carries into this one
CHAOS_MEMORY_LUCKY = 0.25   # a break bleeds it off faster


def chaos_events(fate: str, escalated: bool, interaction: bool,
                 spotted: bool = False) -> list[tuple[str, int]]:
    """What this turn ADDED to the tension, as (reason, weight) pairs.

    Weights only ever push up; the fall comes from the decay in apply_chaos, so
    a turn with nothing in it needs no entry here.

    There was a "new injury" weight here, fed by the wound parser. It went with
    that parser, and it was largely double-counting anyway: an injury nearly
    always arrived on an UNLUCKY turn, which is already worth 2 below.
    """
    events: list[tuple[str, int]] = []
    if escalated:
        events.append(("story escalated", 3))
    if fate == "UNLUCKY":
        events.append(("fate turned", 2))
    if spotted:
        events.append(("the world noticed you", 3))
    if interaction:
        events.append(("meddled with the world", 1))
    return events


def apply_chaos(state: dict, *, fate: str, escalated: bool,
                interaction: bool, spotted: bool = False) -> int:
    """Re-read ``state['chaos_level']`` from what the turn contained.

    Returns the new value.
    """
    events = chaos_events(fate, escalated, interaction, spotted)
    memory = CHAOS_MEMORY_LUCKY if fate == "LUCKY" else CHAOS_MEMORY
    before = int(state.get("chaos_level", 0) or 0)
    after = max(0, min(CHAOS_MAX, round(before * memory + sum(w for _, w in events))))
    state["chaos_level"] = after
    reasons = ", ".join(f"{r} +{w}" for r, w in events) or "quiet turn"
    print(f"[CHAOS] {before} -> {after} (kept {memory:.0%}; {reasons})", flush=True)
    return after


#: Luck never becomes impossible, and misfortune never becomes the house rule.
#:
#: Both floors are here because the bias arithmetic below could erase a whole
#: outcome. `lucky_cut = 0.25 - bias` reaches zero at bias 0.25, and in scan_move
#: — where every turn is a SCAN interaction and therefore carries the +0.15 risk
#: boost unconditionally — 0.25 is passed as soon as the story reaches
#: "escalating". A measured 13-turn run rolled LUCKY exactly ZERO times and
#: UNLUCKY seven times: from turn three onward a break was arithmetically
#: unavailable, so the world could only ever be neutral or cruel. That reads to a
#: player as a game that has stopped responding to them.
FATE_LUCKY_FLOOR = 0.10
FATE_UNLUCKY_CEILING = 0.55


def compute_fate(risk_bias: float = 0.0) -> str:
    """Roll narrative luck for a turn.

    Base odds mirror the Discord bot: 25% LUCKY / 50% NORMAL / 25% UNLUCKY.
    `risk_bias` (0..0.5) shifts probability out of LUCKY and into UNLUCKY without
    touching the NORMAL band much — so riskier moments (deep escalation, poking
    an unknown object) are genuinely more likely to bite. At bias 0 the split is
    unchanged; higher bias makes fate lean mean, but only as far as
    FATE_LUCKY_FLOOR / FATE_UNLUCKY_CEILING allow.
    """
    bias = max(0.0, min(0.5, risk_bias))
    lucky_cut = max(FATE_LUCKY_FLOOR, 0.25 - bias)
    unlucky_cut = max(lucky_cut, 1.0 - FATE_UNLUCKY_CEILING, 0.75 - bias)
    roll = random.random()
    if roll < lucky_cut:
        return "LUCKY"
    if roll < unlucky_cut:
        return "NORMAL"
    return "UNLUCKY"

def advance_story_dynamics(session_id: str = 'default', risk_boost: int = 0) -> dict:
    """Escalate the persistent story dials for THIS turn and roll its fate.

    • threat_level climbs every turn (base +1, plus `risk_boost` for high-stakes
      moves like SCAN object interactions) so pressure accumulates across a run
      instead of resetting to nothing each turn.
    • current_phase is derived from threat_level (normal → escalating → critical).
      The consequence LLM, world-tick, time-of-day, and HUD systems already react
      to this phase — they were just never handed a rising one on the web path.
    • fate is rolled with a bias that grows as the phase escalates AND when the
      action itself is risky, so late-game turns and object-poking swing harder.

    • time_of_day is the evening this run started in. It is not stepped here.
      Phase is the tension dial; rewriting the light on an act break made
      every hard-cut frame a new time of day (see the image-path injection
      in gemini_image_utils). The clock helper still exists if something
      deliberately waits until night — the turn loop is not that something.

    Mutates + persists session state under the world lock. Returns
    {"fate", "phase", "prev_phase", "threat_level", "escalated", "time_of_day"}.
    """
    global state
    with WORLD_STATE_LOCK:
        st = _load_state(session_id)
        prev_phase = st.get("current_phase", "normal")
        threat = int(st.get("threat_level", 0) or 0) + 1 + min(
            MAX_RISK_THREAT_BOOST, max(0, int(risk_boost)))
        phase = _phase_for_threat(threat)
        escalated = _PHASE_RANK.get(phase, 0) > _PHASE_RANK.get(prev_phase, 0)
        st["threat_level"] = threat
        st["current_phase"] = phase
        detect_level = get_detection(st)["level"]
        # Lighting is the identity of this run's evening, not a tension dial.
        # Stepping the tier on an act break (golden hour → dusk → night) was
        # handed to every image as a CRITICAL rewrite, so a hard cut relit
        # the whole movie instead of holding the light the first frame set.
        # Phase still climbs; the sky does not.
        time_of_day = st.get("time_of_day", "") or ""
        phase_bias = {"normal": 0.0, "escalating": 0.12, "critical": 0.22}.get(phase, 0.0)
        # A risk_boost (SCAN interaction / entering the unknown) both accelerated
        # the phase above and tilts THIS turn's luck toward complication.
        #
        # Being known about is its own risk, and separate from how far the story
        # has got: hiding successfully should make a turn safer, and being hunted
        # should make it meaner, or detection is a readout rather than a stake.
        detect_bias = (0.0, 0.05, 0.14, 0.24)[max(0, min(3, detect_level))]
        risk_bias = phase_bias + detect_bias + (0.15 if risk_boost else 0.0)
        fate = compute_fate(risk_bias)
        # Persisted, not just returned. A fight rolls every round with
        # `state["fate"]` as luck (encounter.fight_context: LUCKY +2, UNLUCKY
        # -2 on every roll) — and nothing ever wrote that key, so every fight
        # ever played was rolled NORMAL whatever the turn's luck was. The fate
        # of the turn a
        # fight lands in is the fate it fights under.
        st["fate"] = fate
        _save_state(st, session_id)
        _sync_ambient_state(st, session_id)
    return {"fate": fate, "phase": phase, "prev_phase": prev_phase,
            "threat_level": threat, "escalated": escalated,
            "detection": detect_level, "time_of_day": time_of_day}

_PHASE_RANK = {"normal": 0, "escalating": 1, "critical": 2}

# Short, in-world stings shown when the story tips into a new phase — so the
# player FEELS the stakes climb (paired with the client's escalation sound + HUD).
_PHASE_ESCALATION_BEATS = {
    "escalating": [
        "The facility notices you now. Whatever you stirred is moving.",
        "Something shifts in the dark ahead — the quiet just got heavier.",
        "The air tightens. You are no longer the only thing hunting out here.",
    ],
    "critical": [
        "No more creeping. It's coming for you — fast.",
        "The whole place turns hostile at once. This is where people vanish.",
        "Alarms of instinct scream. Whatever comes next could be the last thing you film.",
    ],
}

def _phase_escalation_beat(phase: str) -> str:
    beats = _PHASE_ESCALATION_BEATS.get(phase)
    return random.choice(beats) if beats else ""

# ───────── game loop ──────────────────────────────────────────────────────────
def advance_turn_image_fast(choice: str, fate: str = "NORMAL", is_timeout_penalty: bool = False, session_id: str = 'default', skip_image: bool = False, skip_evolve: bool = False, interaction: bool = False, local_only: bool = False, subject: str = "", is_move: bool = False, escalated: bool = False, is_custom_action: bool = False, defer_evolve: bool = False) -> dict:
    """
    PHASE 1 (FAST): Generate dispatch and image, return immediately.

    skip_image=True   -> don't block on the scene image (feed streams it async).
    skip_evolve=True  -> run the world-evolution rewrite in the background
                         (it only affects the next turn), so the turn's
                         narrative + choices return fast.
    defer_evolve=True -> run the world-evolution rewrite on a thread and return
                         its handle in the result dict under "_evolve_thread",
                         WITHOUT blocking on it here. The web caller starts the
                         scene render, lets evolve overlap it, then joins the
                         thread before the choice phase reads world_prompt /
                         seen_elements (see _process_turn_background). Ignored
                         when skip_evolve is set.
    subject           -> the detection label the player tapped to issue this
                         action, if any. Required to survive into this turn's
                         `visual_scene` — see the OBJECT PERMANENCE block.
    is_move           -> the tap was MOVE TO rather than INTERACT, so the
                         subject must end up closer rather than merely changed.
    escalated         -> this turn tipped the story into a higher phase (the
                         caller rolled it in advance_story_dynamics). Feeds the
                         chaos dial, which is the biggest single jolt it takes.
    is_custom_action  -> the player typed this action rather than picking a
                         curated choice or tapping a SCAN object. Gates the
                         FREE WILL prompt block in _generate_combined_dispatches
                         (and the matching flipbook branch in _gen_image_impl,
                         which reads it back off state — see below).
    local_only=True   -> operate entirely on LOCAL `state`/`history` variables
                         (loaded + saved per session_id) and never touch the
                         module-global mirrors. The web multi-user path passes
                         this so a concurrent different-session request that
                         swaps the shared mirror can't corrupt this turn's
                         in-flight computation or make its _save_state write the
                         wrong session's data. The Discord bot keeps the default
                         (False), which publishes the result to the globals its
                         interaction handlers read after a turn.
    
    Args:
        session_id: Session ID for state management
    Returns image ASAP so bot can display it while choices are generating.
    
    Args:
        choice: Player's chosen action
        fate: Luck modifier - "LUCKY", "NORMAL", or "UNLUCKY"
        is_timeout_penalty: If True, maintains EXACT camera position (no movement/teleportation)
    """
    # NOTE: `state` / `history` below are LOCAL variables (no `global`
    # declaration on purpose — see local_only in the docstring). The bot path
    # mirrors them into the module globals at the end via _publish_ambient.
    state = None
    history = None

    # CRITICAL: Log everything for Render debugging
    safe_choice = choice[:100].encode('ascii', 'replace').decode('ascii')
    print(f"[ADVANCE_TURN] Choice: '{safe_choice}'")
    print(f"[ADVANCE_TURN] Fate: {fate}")
    print(f"[ADVANCE_TURN] Is Timeout Penalty: {is_timeout_penalty}")
    try:
        # Load session-specific state and history
        state = _load_state(session_id)
        history = _load_history(session_id)
        prev_state = state.copy() if isinstance(state, dict) else dict(state)
        from choices import generate_and_apply_choice, generate_choices
        # Ensure session-specific state path is passed!
        state_file_path = _get_state_path(session_id)
        generate_and_apply_choice(choice, state_path=str(state_file_path))
        state = _load_state(session_id)

        # THE TURN BOUNDARY for the player's character: a fitting that landed
        # since the last beat becomes this turn's look now — never mid-render —
        # and the pack mirror follows the character (characters.py).
        try:
            import characters as _characters
            _prev_look = state.get("look_id")
            _look_line = _characters.sync_run_look(state, session_id)
            if state.get("character_id") and state.get("look_id") != _prev_look:
                import run_tape as _tape
                _tape.note_look(session_id, state["character_id"], state["look_id"], _look_line, state)
        except Exception as _char_err:
            print(f"[CHARACTERS] look sync skipped: {_char_err}", flush=True)
        
        # Get previous vision and image
        # Use vision_analysis (actual image analysis) over vision_dispatch (narrative text)
        # for better spatial continuity in the next dispatch generation
        prev_vision = ""
        prev_image = None
        if history and len(history) > 0:
            prev_vision = (history[-1].get("vision_analysis", "") or
                           history[-1].get("vision_dispatch", ""))
            prev_image = history[-1].get("image_url", None)

        # How long the run has been in the same KIND of place. Read from history
        # because that's where the previous turn's vision label was persisted;
        # Phase 2 doesn't save state, so it can't put it anywhere else. The
        # previous turn's hard cut is what actually moved the player, so that is
        # what clears the count.
        env_streak = update_environment_streak(
            state,
            resolve_environment_label(state, history),
            hard_transition=bool(history[-1].get("hard_transition")) if history else False,
            scene_text=state.get("current_render_base") or "",
        )
        # Persisted (not just passed down the call stack) so the flipbook branch
        # in _gen_image_impl — which reloads state from disk rather than
        # receiving this call's arguments — can see it too. See is_custom_action
        # in this function's docstring.
        state['_turn_is_custom_action'] = is_custom_action
        _save_state(state, session_id)
        
        # TIMEOUT PENALTIES: Use penalty text AS dispatch (don't generate new one)
        provisional_choices: list = []
        # The model's own answer to "did that beat move them", or None when it
        # did not say. Read below, where the hard cut is decided.
        relocated = None
        if is_timeout_penalty:
            dispatch = choice  # The penalty text IS the consequence
            vision_dispatch = choice
            player_alive = True  # timeout penalties never kill directly; the next turn's consequence LLM judges lethality
            print(f"[TIMEOUT PENALTY] Using penalty text as dispatch: {dispatch[:100]}")
        else:
            # Camera beat only. Choices are a later call after evolve lands.
            dispatch, vision_dispatch, player_alive, provisional_choices, relocated = _generate_combined_dispatches(choice, state, prev_state, prev_vision, prev_image, fate, is_interaction=interaction, subject=subject, is_move=is_move, environment_streak=env_streak, is_custom_action=is_custom_action)
        # Told once (see _look_note_directive).
        state.pop("look_note", None)
        
        # SIMPLE DEATH SYSTEM: Just trust the LLM
        state['player_state']['alive'] = player_alive

        if not player_alive:
            print(f"[DEATH] Player killed by: {dispatch[:100]}...")
            try:
                import characters as _characters
                _characters.note_death(state)
            except Exception:
                pass

        # The goal, same verdict system as death: the model's word, counted
        # once. A run used to have no record of reaching what it came for — a
        # traced run dove through the blast door it was staged toward and was
        # still being offered "Kick the blast door open" two turns later.
        goal_reached = bool(state.pop("_turn_goal_reached", False))
        # ...but the WALK has to have happened. The model will call the first
        # beat of a brand new goal an arrival — a playtest lap was handed
        # "Atmospheric Filtration Hub" and was inside it without one step,
        # because the beat it read was the player walking out of the last
        # place with its prize in hand. The player's own steps toward it
        # (goal.approach, one per turn) are the thing that says how close they
        # are; the model's word only confirms the last of them.
        _near = True
        try:
            import goal as _goal_steps
            _p = _goal_steps.progress(state)
            _near = int(_p.get("steps") or 0) >= _goal_steps.APPROACH_STEPS - 1
        except Exception:
            _near = True
        if goal_reached and not _near:
            print("[GOAL] the model called it reached, but they have not walked "
                  "there yet — ignored", flush=True)
        if goal_reached and _near and player_alive and run_goal(state) \
                and not state.get("goal_reached_turn"):
            state["goal_reached_turn"] = int(state.get("turn_count") or 0) + 1
            print(f"[GOAL] reached on turn {state['goal_reached_turn']}: "
                  f"{run_goal(state)[:80]}", flush=True)
        else:
            goal_reached = False

        # Save state immediately after death detection
        _save_state(state, session_id)
        print(f"[STATE] Saved - alive={player_alive}")
        
        # An error sentinel is not an empty string, so it slipped past the guard
        # below and was narrated to the player verbatim. Mask it as a camcorder
        # glitch instead: the turn is degraded either way, but the fiction holds.
        degraded = _is_failure_dispatch(dispatch)
        if degraded:
            print(f"[DEGRADED TURN] masking failed dispatch: {str(dispatch)[:80]}", flush=True)
            dispatch = _diegetic_dispatch(choice)
            if _is_failure_dispatch(vision_dispatch):
                vision_dispatch = dispatch

        if not dispatch or dispatch.strip().lower() in {"none", "", "[", "[]"}:
            dispatch = "You make a tense move in the chaos."
        if not vision_dispatch or vision_dispatch.strip().lower() in {"none", "", "[", "[]"}:
            vision_dispatch = dispatch

        # Whether anything out there now knows where the player is. Read from
        # the prose, so a turn that says "it gives chase" is a turn the next one
        # has to answer for. This is the only stake the engine adjudicates now;
        # death itself is the model's verdict, above.
        # Both channels: the caption carries the geometry, the narrative carries
        # "it gives chase". Reading only the caption meant a turn could announce
        # pursuit in the prose and the engine would never register it.
        _det, spotted = apply_detection(state, f"{dispatch}\n{vision_dispatch}",
                                        interaction=interaction,
                                        is_move=is_move, fate=fate,
                                        fleeing=is_egress_choice(choice))
        # Chaos reads the turn that just happened, so it has to land after the
        # detection check and after the caller has told us whether the story
        # tipped.
        apply_chaos(state, fate=fate, escalated=escalated,
                    interaction=interaction, spotted=spotted)
        _record_recent_event(state, choice, dispatch)
        _save_state(state, session_id)

        # Evolve from what HAPPENED, with the camera beat in its own slot. The
        # evolve prompt has always had separate CONSEQUENCE OF ACTION and VISION
        # ANALYSIS sections; handing the caption to both left the world state
        # growing out of a shot list, which is why it drifted instead of
        # developing. The dummy summarize_world_state_diff string is not the
        # evolve input.
        consequence_summary = dispatch or vision_dispatch
        _deferred_evolve_thread = None
        if defer_evolve and not skip_evolve:
            # Web path: run world evolution on a thread so it OVERLAPS the scene
            # render the caller is about to do. evolve only changes the NEXT
            # turn's world_prompt / seen_elements — never this turn's still,
            # which is composed from visual_scene — so the caller joins the
            # returned handle before Phase 2 reads those fields. Same read-
            # inside-lock merge as the async path; no feed_log clobber.
            _deferred_evolve_thread = _spawn_evolve_thread(
                session_id, consequence_summary, vision_dispatch, player_action=choice)
        elif skip_evolve:
            # Feed path: run the (slow, ~1k-token) world evolution in the
            # background so the turn's narrative + choices return fast. It only
            # affects the NEXT turn's world_prompt. evolve_world_state is
            # read-only; the worker merges its result under lock, preserving
            # feed_log.
            _evolve_world_async(session_id, consequence_summary, vision_dispatch,
                                player_action=choice)
        else:
            from evolve_prompt_file import evolve_world_state
            state_file_path = _get_state_path(session_id)
            evolution_result = evolve_world_state(history, consequence_summary, state_file=str(state_file_path), vision_description=vision_dispatch, player_action=choice)
            state = _load_state(session_id)
            if evolution_result:
                for _k in ("world_prompt", "evolution_summary", "recent_events",
                           "seen_elements", "ambient_beats"):
                    if _k in evolution_result:
                        state[_k] = evolution_result[_k]
                _save_state(state, session_id)
                print(f"[WORLD EVOLUTION] Applied and saved evolution results for {session_id}")
        
        # Generate image
        mode = state.get("mode", "camcorder")
        frame_idx = len(history) + 1
        # `softened_move` used to mean "asked for a hard cut, the throttle
        # declined it, still has to visibly travel" (see build_image_prompt).
        # Nothing asks for a cut and gets refused anymore — MOVE is
        # unconditional and the text classifier below is no longer throttled
        # either — so this is permanently False. Left wired through
        # build_image_prompt / the flipbook regeneration path rather than
        # ripped out, since a future feature that legitimately wants a
        # "travelled but stayed in-frame" render (as opposed to a fresh
        # composition) has a tested branch to reuse instead of reinventing it.
        softened_move = False
        # CRITICAL: Timeout penalties NEVER change location
        if is_timeout_penalty:
            hard_transition = False
            print(f"[TIMEOUT PENALTY] Forcing NO location change - maintaining exact camera position")
        elif is_move:
            # MOVE is a single, unconditional verb, not a spectrum the engine
            # infers from wording. It used to be run through the same
            # portal-vs-approach text classifier as everything else, which
            # decided from the OBJECT NAME whether "move to X" got a fresh
            # composition ("enter the door") or was quietly kept on the old
            # frame ("walk over to the television" / "the broken glass") — so
            # clicking MOVE TO felt like a coin flip depending on what the
            # player happened to tap. The engine had no reliable signal for
            # "this was a structural relocation" and had to guess one from
            # prose. It has one now: `is_move` comes straight from the client
            # tapping the dedicated MOVE TO verb (source == "scan_move"), not
            # from parsing what the player typed. MOVE always gets a fresh
            # composition — a run that wants continuous, same-place
            # development belongs on a different verb (INTERACT), not on a
            # MOVE that sometimes doesn't move.
            hard_transition = True
            _save_state(state, session_id)
        elif interaction or is_custom_action:
            # INTERACT and typed free-will still have no dedicated "this is a
            # new beat" verb, so intent is inferred from the wording. This is
            # also the refine-from-current path: look-around / in-place pokes
            # stay on the previous frame unless the text itself is a
            # relocation. Realtime WSAD look-around never comes through here
            # (/api/observe), so this branch is the only place a soft
            # continuation is still allowed.
            #
            # Egress/flight wording ("Bolt for the nearest way out", ...) is
            # forced to a cut: is_hard_transition was tuned for "enter the
            # door" and never recognizes "bolt"/"sprint"/"climb out".
            hard_transition = resolve_hard_transition(choice, dispatch, relocated)
            _save_state(state, session_id)
        else:
            # Curated choice pill. Refine from the frame the player was
            # looking at (the live capture, once ingested) unless the beat
            # actually relocated them. Forcing every pill to a hard cut threw
            # that capture away and the next still left the Reactor scene.
            hard_transition = resolve_hard_transition(choice, dispatch, relocated)
            _save_state(state, session_id)
        if state.pop("pending_world_transition", False):
            hard_transition = True
            _save_state(state, session_id)

        # Leaving the REGION also empties the world's memory of props.
        #
        # The render is only half of what the player sees. `seen_elements` is the
        # discovered-entity list `grounded_entities` hands to the choice
        # generator, and nothing pruned it on a relocation — so the capture that
        # produced is_region_change offered "Climb over the chain link fence" and
        # "Heave open the truck door" on an Antarctic ice shelf. Those props are
        # two thousand miles away. Forgetting them is not a loss: a choice the
        # player cannot physically take is worse than a shorter list, and the
        # next frame's SCAN refills the list from the place they are actually in.
        if hard_transition and not is_timeout_penalty and is_region_change(choice):
            forgotten = len(state.get("seen_elements") or [])
            state["seen_elements"] = []
            state["scene_objects"] = []
            state["scene_objects_turn"] = -1
            _save_state(state, session_id)
            print(f"[REGION CHANGE] forgot {forgotten} prop(s) belonging to the "
                  f"place just left, so the next slate cannot offer them",
                  flush=True)

        consequence_img_url = None
        consequence_img_prompt = ""  # Initialize to prevent undefined variable error
        consequence_video_url = None  # Initialize to prevent UnboundLocalError if _gen_image raises before its internal assignment
        try:
            if skip_image:
                # Feed path streams the image asynchronously; skip the slow
                # inline generation so the turn resolves fast.
                raise _SkipImage()
            last_image_path = None
            if history and len(history) > 0:
                for entry in reversed(history):
                    if entry.get("image"):
                        # DON'T strip leading slash - session images are absolute paths!
                        last_image_path = entry["image"]
                        
                        # Handle both absolute and relative paths
                        if not Path(last_image_path).is_absolute():
                            # Relative path like "/images/..." - make it absolute
                            if last_image_path.startswith("/images/"):
                                last_image_path = str(ROOT / "images" / Path(last_image_path).name)
                        break
            
            print(f"[IMG GEN] About to generate image:")
            safe_choice = choice[:80].encode('ascii', 'replace').decode('ascii')
            print(f"  - Choice: '{safe_choice}'")
            print(f"  - Is timeout penalty: {is_timeout_penalty}")
            print(f"  - Hard transition: {hard_transition}")
            print(f"  - Last image path: {last_image_path}")
            print(f"  - Last image EXISTS: {last_image_path and os.path.exists(last_image_path)}", flush=True)
            print(f"  - Will use img2img: {last_image_path and os.path.exists(last_image_path) and frame_idx > 0}", flush=True)
            
            result = _gen_image(
                vision_dispatch,
                mode,
                choice,
                image_description="",
                use_edit_mode=(last_image_path and os.path.exists(last_image_path)),
                frame_idx=frame_idx,
                dispatch=dispatch,
                world_prompt=state.get("world_prompt", ""),
                hard_transition=hard_transition,
                is_timeout_penalty=is_timeout_penalty,  # Pass flag to image generation
                session_id=session_id,  # Session-specific image directory
                history_ref=history,  # LOCAL history — never the shared global mirror
                softened_move=softened_move,
            )
            consequence_video_url = None
            if result:
                consequence_img_url, consequence_img_prompt, consequence_video_url = result
                print(f"[IMG FAST] Image ready: {consequence_img_url}", flush=True)
            else:
                # Image generation failed (safety block, API error, etc.) - provide graceful fallback
                print(f"[IMG FAST] WARNING: Image generation returned None (likely safety block or API error)")
                print(f"[IMG FAST] Providing fallback 'static' image message")
                consequence_img_url = None  # Explicitly None - bot will show text-only
                consequence_img_prompt = "[Image blocked - content filtered]"
            
            if consequence_video_url:
                print(f"[IMG FAST] Video ready: {consequence_video_url}")
        except _SkipImage:
            pass  # feed path renders the image asynchronously
        except Exception as e:
            print(f"[IMG FAST] Error: {e}")
            import traceback
            traceback.print_exc()
        
        # Bot path only: mirror this turn's result into the module globals its
        # interaction handlers read after the turn. Web (local_only=True) keeps
        # everything local + on-disk so concurrent sessions never collide.
        if not local_only:
            _publish_ambient(st=state, hist=history)

        return {
            "dispatch": dispatch,
            "vision_dispatch": vision_dispatch,
            "consequence_image": consequence_img_url,
            "consequence_image_prompt": consequence_img_prompt,
            "consequence_video": consequence_video_url,  # Video path for HD mode playback
            "hard_transition": hard_transition,  # Track location changes for reference buffer
            # Wanted a location change and was throttled to a soft one. The feed
            # path renders its image asynchronously and so re-derives the whole
            # prompt later, from these fields alone — omit this and the camera
            # gets pinned to the previous frame on exactly the turns the player
            # asked to leave it.
            "softened_move": softened_move,
            # True when the dispatch was a masked failure. The player sees only
            # the in-world glitch line, but autoplay and QA need to know this
            # beat carried no real story so they don't treat it as progress.
            "degraded": degraded,
            # This beat reached the run's goal (first time only). The turn
            # loop turns it into an `objective_done` feed beat.
            "goal_reached": goal_reached,
            "frame_idx": frame_idx,  # for async image generation on the feed path
            "provisional_choices": provisional_choices,  # next-action options from the same LLM call (may be empty)
            # Handle to the deferred world-evolution thread (defer_evolve=True),
            # or None. The caller joins this before the choice phase reads
            # world_prompt / seen_elements — see _process_turn_background.
            "_evolve_thread": _deferred_evolve_thread,
            "evolution_summary": state.get("evolution_summary", ""),  # Include world changes
            "phase": state["current_phase"],
            "chaos": state["chaos_level"],
            "world_prompt": state.get("world_prompt", ""),
            "mode": state.get("mode", "camcorder")
        }
    except Exception as e:
        print(f"[IMG FAST] Fatal error: {e}")
        import traceback
        traceback.print_exc()
        return {
            "dispatch": f"Error: {e}",
            "vision_dispatch": "",
            "consequence_image": None,
            "phase": "error",
            "chaos": 0,
            "world_prompt": "",
            "mode": "camcorder"
        }

def advance_turn_choices_deferred(consequence_img_url: str, dispatch: str, vision_dispatch: str, choice: str, consequence_img_prompt: str = "", hard_transition: bool = False, session_id: str = 'default', local_only: bool = False, pregenerated_choices: Optional[List[str]] = None) -> dict:
    """
    PHASE 2 (DEFERRED): Generate choices after image is displayed.
    
    Args:
        session_id: Session ID for state management
        local_only: When True (web multi-user path), operate on LOCAL state/
            history only and never touch the module-global mirrors — see
            advance_turn_image_fast's docstring.
    """
    try:
        return _advance_turn_choices_deferred_impl(consequence_img_url, dispatch, vision_dispatch, choice, consequence_img_prompt, hard_transition, session_id, local_only, pregenerated_choices)
    except Exception as e:
        import traceback
        print(f"[PHASE 2] Fatal error in advance_turn_choices_deferred: {e}", flush=True)
        traceback.print_exc()
        return {
            "choices": ["Look around carefully", "Move forward cautiously", "Hold position and observe"],
            "situation_report": "The situation is tense.",
            "consequences": "",
            "player_state": {},
            "evolution_summary": "",
            "streak_reward": None,
            "rare_event": None,
            "danger": False,
            "combat": False
        }


def _advance_turn_choices_deferred_impl(consequence_img_url: str, dispatch: str, vision_dispatch: str, choice: str, consequence_img_prompt: str = "", hard_transition: bool = False, session_id: str = 'default', local_only: bool = False, pregenerated_choices: Optional[List[str]] = None) -> dict:
    """Internal implementation of Phase 2 choice generation.

    `state` / `history` below are LOCAL variables (no `global` on purpose): the
    web path (local_only=True) must not touch the shared module mirrors, and
    the bot path mirrors the result at the end via _publish_ambient."""
    from choices import generate_choices

    state = None
    history = None
    state = _load_state(session_id)
    
    # --- FRAME TO READ ---
    # The rendered frame is the source of truth for the NEXT turn's spatial
    # anchor. For a flipbook turn the LAST panel is where the action ended, so
    # that is the only frame worth reading — the first panel is just where the
    # player already was, and analyzing it too was a second sequential vision
    # call for context the slate no longer consumes.
    #
    # `current_sequence` is the proof that THIS turn drew a flipbook, and it has
    # to be checked — the history selector below already learned that and this
    # one did not. Asking only whether flipbook MODE is on meant a turn whose
    # grid was refused (a content filter on a typed action is the common way)
    # read the previous turn's last panel instead of the still it had just
    # rendered, and wrote that frame's spatial anchor into history as if it were
    # this turn's. The next turn then continued from before the refused one.
    analysis_img_url = consequence_img_url
    if flipbook_settings(state)["enabled"] and state.get("current_sequence"):
        _fb_last = state.get('flipbook_last_frame')
        if _fb_last and os.path.exists(_fb_last):
            print(f"[VISION] Flipbook mode - reading the LAST panel only")
            analysis_img_url = _fb_last

    # vision_dispatch is the fallback caption (what the image model was ASKED to
    # draw); the real read overwrites it once it lands.
    vision_analysis_text  = (vision_dispatch or "").strip()
    _spatial_compass_turn = ""   # directional compass: ahead/left/right/ground/height
    _setting_type_turn    = ""   # environment type: outdoor-desert, indoor-corridor, etc.

    # Read the frame on a BACKGROUND thread so it can overlap the bookkeeping
    # below. It used to also overlap CHOICE GENERATION, on the reasoning that the
    # slate has the picture attached and so does not need the vision TEXT. On a
    # real turn that does not hold. From bugs/20260917_153517:
    #
    #   15:35:09  [SCENE IMG] scene appended ... _f04.png
    #   15:35:09  [VISION] Analyzing _f04.png ...
    #   15:35:11  [CHOICES RAW LLM OUTPUT] 'Sprint toward the rusted truck / ...'
    #   15:35:11  [VISION] Analysis complete: Ahead: Rusted industrial tanks and
    #             pipes ~10m. Left: Chain-link fence ~2m.
    #
    # The slate was written with `image_description=""`, so the only scene TEXT
    # it had was `grounded_entities(state)` — a cumulative list that still
    # carried "rusted truck", "Black pickup" and "Guard" two turns after the
    # player vaulted the fence and left all three on the far side of it. The
    # picture showed tanks and pipes. The game offered the truck.
    #
    # A picture is stronger grounding than a caption, but it is not stronger than
    # a caption PLUS an entity list pulling the other way. So the slate now waits
    # for the frame to be readable AND for the read of that frame to land, and
    # spends both on `{image_description}`. That puts the vision call back on the
    # turn's critical path, which is the cost of the buttons describing the
    # picture the player is looking at.
    _vision_holder = {"description": "", "spatial": "", "setting": "",
                      "witness": None}
    _vision_ms = {"ms": 0}

    def _run_vision():
        if not (analysis_img_url and VISION_ENABLED):
            return
        _vt0 = time.time()
        try:
            r = _vision_analyze_all(analysis_img_url)
            _vision_holder["description"] = (r.get("description") or "").strip()
            _vision_holder["spatial"]     = r.get("spatial", "") or ""
            _vision_holder["setting"]     = r.get("setting", "") or ""
            # Could anything in the frame we just drew see the player. This is
            # the still path's detection sensor, and it rides the read that was
            # already happening here — see WATCHERS in _vision_analyze_all.
            _vision_holder["witness"]     = witness_from_vision(r)
        except Exception as e:
            print(f"[VISION] Analysis failed: {e} — keeping the render caption")
        finally:
            _vision_ms["ms"] = int((time.time() - _vt0) * 1000)

    _vision_thread = threading.Thread(target=_run_vision, daemon=True)
    _vision_thread.start()

    _vision_absorbed = {"done": False}

    def _absorb_vision(budget: float, why: str) -> bool:
        """Join the frame read and take what it found. Idempotent, so the slate
        can wait for it and the history entry can ask again for free."""
        nonlocal vision_analysis_text, _spatial_compass_turn, _setting_type_turn
        if _vision_absorbed["done"]:
            return bool(_vision_holder["description"])
        try:
            _vision_thread.join(timeout=budget)
        except Exception:
            pass
        if _vision_thread.is_alive():
            print(f"[VISION] read has not landed after {budget:g}s ({why})",
                  flush=True)
            return False
        _vision_absorbed["done"] = True
        if _vision_holder["description"]:
            vision_analysis_text = _vision_holder["description"]
            print(f"[VISION] Analysis complete: {vision_analysis_text[:100]}...")
        if _vision_holder["spatial"]:
            _spatial_compass_turn = _vision_holder["spatial"]
            print(f"[VISION] Spatial compass: {_spatial_compass_turn[:80]}...")
        if _vision_holder["setting"]:
            _setting_type_turn = _vision_holder["setting"]
        return bool(_vision_holder["description"])

    # FAST PATH: if the consequence call already produced usable next-action
    # options, reuse them and SKIP both the situation-report and choice-generation
    # LLM calls (they exist only to feed choice generation, which we now already
    # have). This collapses the turn's text critical path from ~3 sequential LLM
    # round-trips (dispatch → situation report → choices) down to 1. All state /
    # history bookkeeping below still runs, and the client's vision reground still
    # refines these against the actual rendered frame. Falls back to the full
    # generator whenever the pregenerated list doesn't yield a FULL slate of
    # clean, meaningful options: accepting a short one used to hand the player
    # two buttons where the UI lays out three, which reads as the game running
    # out of ideas. The shortcut is worth taking only when it's complete —
    # otherwise the extra round-trip buys back the missing option.
    _pregen = None
    if pregenerated_choices:
        try:
            from choices import drop_meaningless_choices, enforce_diversity, SLATE_SIZE
            _cleaned = enforce_diversity(drop_meaningless_choices(
                [c for c in pregenerated_choices if c and c.strip()]
            ))
            if len(_cleaned) >= SLATE_SIZE:
                _pregen = _cleaned[:SLATE_SIZE]
            elif _cleaned:
                print(f"[PHASE 2] provisional choices came back short "
                      f"({len(_cleaned)}/{SLATE_SIZE}) — generating a full slate instead.", flush=True)
        except Exception as _e_pre:
            print(f"[PHASE 2] pregenerated-choices cleaning failed, will generate: {_e_pre}", flush=True)
            _pregen = None

    situation_summary = ""
    _choice_timing: dict = {}
    if _pregen is not None:
        next_choices = list(_pregen)
        print(f"[PHASE 2] Using {len(next_choices)} provisional choice(s) from the consequence call "
              f"(skipped situation-report + choice LLM calls).", flush=True)
    else:
        # ── THE SLATE DOES NOT RUN UNTIL IT HAS A FRAME TO RUN OFF ───────────
        # Two waits, both bounded. First the frame has to be readable: a path
        # that failed to attach used to degrade the slate to text-only and say so
        # only in a log line nobody reads ("[CHOICES ERROR] Image file not
        # found"). Then the READ of that frame has to land, so the slate gets
        # scene text describing what actually rendered instead of nothing.
        frame_for_slate = _await_frame_on_disk(analysis_img_url, CHOICE_FRAME_WAIT)
        if analysis_img_url and not frame_for_slate:
            print(f"[CHOICES] the frame never became readable in "
                  f"{CHOICE_FRAME_WAIT:g}s ({analysis_img_url}) — this slate is "
                  f"written from text and may not match the picture", flush=True)
        if frame_for_slate and not _absorb_vision(
                CHOICE_VISION_WAIT, "the slate is waiting on it"):
            print(f"[CHOICES] no scene text within {CHOICE_VISION_WAIT:g}s — the "
                  f"frame is still attached, but the slate has only the entity "
                  f"list for context this turn", flush=True)

        # What the frame actually SHOWS, as text, for the {image_description}
        # slot the template already has. The spatial compass goes in with it:
        # "Ahead: rusted tanks ~10m. Left: chain-link fence ~2m." is the line
        # that makes "sprint toward the rusted truck" obviously wrong when the
        # truck is behind a fence the player already crossed.
        scene_text_for_slate = vision_analysis_text if frame_for_slate else ""
        if frame_for_slate and _spatial_compass_turn:
            scene_text_for_slate = (
                (scene_text_for_slate + "\n") if scene_text_for_slate else ""
            ) + _spatial_compass_turn

        # With a frame read in hand the reading IS the situation report. Only a
        # frameless turn has to pay for a separate text one.
        if frame_for_slate and vision_analysis_text:
            situation_summary = vision_analysis_text
        elif not analysis_img_url:
            situation_summary = _generate_situation_report(
                current_image=None,
                current_dispatch=dispatch,
                vision_analysis=vision_analysis_text,
            )

        next_choices = generate_choices(
            client, PROMPTS["player_choice_generation_instructions"],
            dispatch,
            n=3,
            image_url=frame_for_slate or analysis_img_url,
            # What SCAN saw in frame, then discovered entities as world memory —
            # so the slate offers verbs on things the player can actually see.
            seen_elements=grounded_entities(state),
            # What the player has ALREADY done, so the slate stops re-offering
            # it. The frame stays visually continuous under img2img, so without
            # this the same landmark yields the same option every turn.
            recent_choices=recent_actions_taken(state),
            caption=vision_dispatch,
            image_description=scene_text_for_slate,
            world_prompt=state.get('world_prompt', ''),
            temperature=0.7,
            situation_summary=situation_summary,
            beat_nudge=beat_nudge_text(state),
        )
        try:
            import choices as _choices_mod
            _choice_timing = dict(_choices_mod.LAST_CHOICE_TIMING)
        except Exception:
            _choice_timing = {}

    # The slate has usually already waited for this, in which case the call is
    # free. It still has to happen for the two paths that did not: the
    # pregenerated-choices fast path, and a slate whose tighter
    # CHOICE_VISION_WAIT expired. The history entry is the NEXT turn's spatial
    # anchor, so it must not be written from a caption if a real read exists.
    _absorb_vision(VISION_JOIN_TIMEOUT, "the history entry needs it")
    # The frame this turn just rendered is the one the player sits looking at
    # while they decide what to do next, so its witness belongs to the NEXT
    # turn rather than this one. turn_count is still this turn's number here —
    # the bump lives in _process_turn_background, after this function returns.
    # Without this the still path has no frame sensor at all and detection
    # falls back to reading the narrator's word choice, which is the whole
    # thing the witness exists to stop.
    if _vision_holder["witness"]:
        record_witness(state, _vision_holder["witness"],
                       for_turn=int(state.get("turn_count", 0) or 0) + 1)
        _save_state(state, session_id)
    # The client's situation_report is the vision reading once we have it.
    if analysis_img_url and vision_analysis_text:
        situation_summary = vision_analysis_text
        # …and so is the scene's SOUND. This is the only description of the
        # frame that actually rendered (on a flipbook turn, of the last panel —
        # where the motion settles), which makes it the only honest source for
        # ambience. The audio lanes used to score off the realtime render base:
        # 1,480 characters opening with the style/camera anchor, from which
        # _clean_scene_text keeps the last 240 — i.e. the place line. Measured,
        # a desert well pad came out as "…s grit across the pad. The place is
        # the Four Corners fence…" and the keyword matcher, seeing no outdoor
        # cue in that, fell through to its default: indoor room tone under an
        # outdoor scene. Surfaced on state because the turn result's
        # situation_report is never sent to the browser.
        state["current_vision"] = vision_analysis_text
        _save_state(state, session_id)

    next_choices = [c for c in next_choices if c and c.strip() and c.strip() != '—']
    if not next_choices:
        next_choices = ["Look around", "Move forward", "Wait"]
    # Backstop for the stagnation directive in the dispatch prompt: a run that
    # has been in one kind of place too long must be OFFERED a way out, whatever
    # the model felt like generating.
    next_choices = enforce_egress_option(
        next_choices, int(state.get("environment_streak", 0) or 0),
        get_detection(state)["level"], int(state.get("turn_count", 0) or 0))
    while len(next_choices) < 3:
        next_choices.append("—")
    
    # Save to history (with custom action flag for permanence tracking). Reads
    # the same real signal Phase 1 stashed on state (see is_custom_action in
    # advance_turn_image_fast's docstring) rather than guessing from keywords
    # in the choice text, which this used to do independently of — and
    # inconsistently with — the guess _generate_combined_dispatches made.
    history = _load_history(session_id)
    is_custom_action = bool(state.get('_turn_is_custom_action'))
    
    # CRITICAL TEMPORAL CONTINUITY FIX:
    # On a flipbook turn the LAST PANEL is where the action ended, so it is the
    # only honest img2img reference for the next turn.
    #
    # This used to prefer consequence_img_url and fall back to the panel only
    # when that was empty. But on a flipbook turn consequence_img_url can still
    # be carrying an EARLIER image, so the next generation was seeded from a
    # frame taken before the motion happened and the story jumped backwards —
    # make a helicopter appear, and the turn after it is standing where you
    # started. `current_sequence` is the proof that THIS turn drew a flipbook,
    # so a turn whose flipbook failed still uses its own still rather than a
    # stale panel from an older one.
    history_image = consequence_img_url
    if flipbook_settings(state)["enabled"] and state.get("current_sequence"):
        _fb_last = state.get("flipbook_last_frame")
        if _fb_last:
            history_image = _fb_last
            print(f"[HISTORY] Flipbook: next turn's img2img reference is the LAST panel: {os.path.basename(_fb_last)}")
    
    history_entry = {
        "choice":            choice,
        "is_custom_action":  is_custom_action,
        "dispatch":          dispatch,
        "vision_dispatch":   vision_dispatch,
        "vision_analysis":   vision_analysis_text,
        "spatial_compass":   _spatial_compass_turn,  # directional compass for next-turn anchor
        "setting_type":      _setting_type_turn,     # environment type for next-turn anchor
        "world_prompt":      state.get("world_prompt", ""),
        "image":             history_image,
        "image_url":         history_image,
        "analysis_image":    analysis_img_url,
        "image_prompt":      consequence_img_prompt,
        "hard_transition":   hard_transition,
    }
    history.append(history_entry)
    _save_history(history, session_id)

    # Bot path only: mirror into the module globals its handlers read after a
    # turn. Web (local_only=True) stays fully local + on-disk per session.
    if not local_only:
        _publish_ambient(st=state, hist=history)

    return {
        "choices": next_choices,
        "situation_report": situation_summary,
        "consequences": "",
        "player_state": state.get('player_state', {}),
        "evolution_summary": state.get('evolution_summary', ""), # Include this here too just in case
        "streak_reward": state.get('streak_reward', None),
        "rare_event": state.get('rare_event', None),
        "danger": False,
        "combat": False,
        # Per-stage split for the turn-timing log (see _process_turn_background).
        # These are close to SEQUENTIAL again: the slate waits for the frame read
        # so its options can describe the picture, so vision_ms is in front of
        # choices_ms rather than hidden underneath it. phase2_ms upstream is
        # still the true elapsed for the pair, and is now roughly their sum.
        "_timing": {
            "vision_ms": int(_vision_ms.get("ms", 0) or 0),
            "choices_ms": int(_choice_timing.get("choices_ms", 0) or 0),
            "critic_ms": int(_choice_timing.get("critic_ms", 0) or 0),
        },
    }

def advance_turn(choice: str) -> dict:
    """Atomically advance the simulation by one turn."""
    global state, history, _last_image_path
    try:
        # Phase 1: Image fast
        phase1_result = advance_turn_image_fast(choice)
        
        # Phase 2: Choices deferred
        phase2_result = advance_turn_choices_deferred(
            phase1_result["consequence_image"],
            phase1_result["dispatch"],
            phase1_result["vision_dispatch"],
            choice,
            phase1_result.get("consequence_image_prompt", ""),
            phase1_result.get("hard_transition", False)
        )
        
        # Combine results
        return {
            **phase1_result,
            **phase2_result
        }
    except Exception as e:
        log_error(f"[ADVANCE TURN] {e}")
        import traceback
        traceback.print_exc()
        return {
            "phase": "error",
            "chaos": 0,
            "dispatch": f"Error: {str(e)}",
            "vision_dispatch": "",
            "dispatch_image": None,
            "consequence_image": None,
            "caption": "Error",
            "mode": "camcorder",
            "situation_report": f"An error occurred: {str(e)}",
            "choices": ["Restart", "Continue", "—"],
            "player_state": {},
            "consequences": f"Error: {str(e)}",
            'error': str(e)
        }

# Alias for compatibility
complete_tick = advance_turn

# ───────── state management ──────────────────────────────────────────────────
def adopt_current_look(session_id='default') -> str:
    """Every beat that DRAWS the player starts on the character's current look.

    The run used to take a fitting only at a choice turn (advance_turn_image_
    fast). A goal cutscene, a fight, a photo or a conversation played before
    the next choice still drew the look from before the fitting — the old
    turnaround and the old wardrobe words — and the reward then chained that
    into every turn after it. Called before the render starts, never during
    one. Returns the look line ('' when nothing changed)."""
    try:
        import characters as _characters
        st = _load_state(session_id)
        if not isinstance(st, dict) or not st.get("character_id"):
            return ""
        rec = _characters.load(st["character_id"]) or {}
        cur = rec.get("current_look") or ""
        if not cur or cur == st.get("look_id"):
            return ""
        prev = st.get("look_id")
        line = _characters.sync_run_look(st, session_id)
        if st.get("look_id") != prev:
            _save_state(st, session_id)
            try:
                import run_tape as _tape
                _tape.note_look(session_id, st["character_id"], st["look_id"], line, st)
            except Exception:
                pass
        return line
    except Exception as e:
        print(f"[CHARACTERS] adopt look skipped: {e}", flush=True)
        return ""


def get_state(session_id='default'):
    """Get current state for a session"""
    return _load_state(session_id)

def get_history(session_id='default'):
    """Get game history for a session"""
    return _load_history(session_id)

def archive_session(session_id='default', reason='reset'):
    """
    Archive a session before deletion for later review.
    Creates a timestamped archive with all session data.
    
    Args:
        session_id: The session to archive
        reason: Why it's being archived ('reset', 'death', 'manual')
    
    Returns:
        Path to the archive directory, or None if failed
    """
    import shutil
    from datetime import datetime
    
    session_root = DATA / "sessions" / session_id
    if not session_root.exists():
        print(f"[ARCHIVE] Session {session_id} doesn't exist, nothing to archive")
        return None
    
    # Create archives directory
    archives_root = DATA / "archives"
    archives_root.mkdir(exist_ok=True)
    
    # Create timestamped archive folder
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    archive_name = f"{session_id}_{timestamp}"
    archive_path = archives_root / archive_name
    
    try:
        print(f"[ARCHIVE] Creating archive: {archive_name}")
        
        # Copy entire session directory
        shutil.copytree(session_root, archive_path)
        
        # Load state and history for metadata
        state = _load_state(session_id)
        history = _load_history(session_id)
        
        # Create archive metadata
        metadata = {
            "session_id": session_id,
            "archive_timestamp": timestamp,
            "archive_reason": reason,
            "turns_completed": state.get('turn_count', 0),
            "player_status": state.get('player_alive', True),
            "final_location": state.get('location', 'unknown'),
            "total_history_entries": len(history),
            "game_duration": "unknown",  # Could calculate from history timestamps
            "world_prompt": state.get('world_prompt', ''),
            "seen_elements": state.get('seen_elements', []),
        }
        
        # Add death info if player died
        if not state.get('player_alive', True) and history:
            last_entry = history[-1]
            metadata["death_turn"] = last_entry.get('turn_count', 0)
            metadata["death_dispatch"] = last_entry.get('dispatch', '')
        
        # Save metadata
        metadata_path = archive_path / "archive_metadata.json"
        metadata_path.write_text(json.dumps(metadata, indent=2))
        
        print(f"[ARCHIVE] SUCCESS - Archived to: {archive_path}")
        print(f"[ARCHIVE]   Turns: {metadata['turns_completed']}")
        print(f"[ARCHIVE]   History entries: {metadata['total_history_entries']}")
        print(f"[ARCHIVE]   Reason: {reason}")
        
        return archive_path
        
    except Exception as e:
        print(f"[ARCHIVE] Failed to create archive: {e}")
        import traceback
        traceback.print_exc()
        return None


def reset_state(session_id='default'):
    """Reset state for a session"""
    global state, history, _last_image_path, _vision_cache
    
    print(f"[RESET] Resetting session: {session_id}")

    # Archive before deletion
    archive_session(session_id, reason='reset')

    # Reset is a session boundary — release any designed voices so we don't
    # keep casts around for a story that no longer exists.
    try:
        import voice_design as _vd
        released = _vd.release_session_voices(session_id)
        if released.get("deleted") or released.get("skipped"):
            print(f"[RESET] voice_design: {released}")
    except Exception as _e:
        print(f"[RESET] voice_design release failed: {_e}")
    
    # Delete session-specific files
    state_path = _get_state_path(session_id)
    history_path = _get_history_path(session_id)
    
    try:
        if state_path.exists():
            os.remove(str(state_path))
            print(f"[RESET] Deleted state file: {state_path}")
    except Exception as e:
        print(f"[RESET] Failed to delete state: {e}")
    
    try:
        if history_path.exists():
            os.remove(str(history_path))
            print(f"[RESET] Deleted history file: {history_path}")
    except Exception as e:
        print(f"[RESET] Failed to delete history: {e}")
    
    # Every process cache this run wrote, including the vision LRU this used to
    # clear on its own. The disk vision layer (authored worlds/ frames only) is
    # deliberately left alone: those pictures are identical next run, and
    # re-reading them is what made a fresh start hang on a vision call.
    #
    # This path and /api/reset had drifted into two different ideas of what a
    # reset means — this one archived and released voices, that one cleared the
    # feed. Neither cleared the caches. They now agree on the caches at least,
    # which is the half that was producing the previous world's character.
    purge_run_caches(session_id, reason="hard reset")
    purge_run_media(session_id)
    
    # Recreate history as empty list
    _save_history([], session_id)
    
    # Update global history if this is the legacy session
    if session_id == 'legacy':
        history = []
    
    # Generate random starting time/weather/mood for this session
    initial_time = _generate_random_starting_time()
    
    # Recreate state for this session
    place_state = game_identity.intro_place_state()
    intro_state = {
        # Seed the run's evolving world document with the cast sheet, not just
        # the setting brief — otherwise the protagonist and level exist only as
        # a per-prompt garnish that the world-evolution pass overwrites.
        "world_prompt": game_identity.world_brief(PROMPTS["world_initial_state"]),
        "current_phase": "normal",
        "chaos_level": 0,
        "turn": 0,
        "time_of_day": initial_time,
        "last_action": "Initial simulation state",
        "situation": place_state["situation"],
        "beat": 0,
        "tape_frames": [],
        "inventory": ["Nikon F3 camera", "notebook", "flashlight"],
        "location": place_state["location"],
        "environment_type": place_state["environment_type"],
        "turn_count": 0,
        "player_state": {"alive": True}
    }
    _save_state(intro_state, session_id)
    
    # Create/reset session metadata (Minecraft-style world info)
    _create_session_metadata(
        session_id,
        name=f"New Game {session_id[:8]}" if session_id != 'default' else "Default Session",
        description="A new game session in the quarantine zone"
    )
    
    # Update global state if this is the legacy session
    if session_id == 'legacy':
        state = intro_state
    
    _last_image_path = None
    print(f"[RESET] Session {session_id} cleared. Starting fresh.")

def _intro_world_seed(prologue: str) -> str:
    """The world document a fresh run starts from, given its opening shot.

    The intro used to store the one-sentence prologue AS the whole world state,
    which threw away `world_initial_state` and the cast sheet on turn zero. The
    per-turn evolution pass then treated that sentence as the entire history of
    the world and rebuilt everything else from the shipped defaults, so an
    authored world survived exactly until the first action.
    """
    import experience_store
    base = experience_store.with_lore(
        game_identity.world_brief(
            PROMPTS.get("world_initial_state", "Default world starting point.")
        )
    )
    if not prologue:
        return base
    return f"{base}\n\nOPENING SHOT: {prologue}" if base else prologue


